// arabic: 88 lessons, 16 units
LESSONS.push(
  {"id":"g9-arabic-1-2","grade":"g9","subject":"arabic","term":1,"unit":6,"no":2,"title":"المفعول المطلق","summary":"شرح متحرك لتعريف المفعول المطلق وأنواعه الثلاثة وما ينوب عنه وإعرابه، ثم أنشطة بثلاثة مستويات.","page":"lesson-absolute-object.html","video":"","pdf":"","notes":["المفعول المطلق: مصدر منصوب يأتي بعد فعل من لفظه، مثل: فَرِحَ الطالبُ فَرَحًا.","أنواعه: مؤكِّد للفعل، ومبيِّن للنوع، ومبيِّن للعدد.","المؤكِّد لا يُثنّى ولا يُجمع، أما المبيِّن للعدد فيُثنّى ويُجمع.","ينوب عنه: كلّ وبعض المضافتان إلى المصدر، والعدد، والصفة.","يُعرب: مفعولًا مطلقًا منصوبًا، وعلامة نصبه الفتحة أو الياء أو الكسرة.","لا تخلط بينه وبين المفعول به: المفعول المطلق هو مصدر الفعل نفسه."],"exercises":["استخرج المفعول المطلق وبيّن نوعه: نِمتُ نومًا عميقًا ، قفزَ اللاعبُ قفزتينِ.","أكمل بمفعول مطلق مناسب: جلسَ الضيفُ ........ ، انتظرتُ صديقي ........","أعرب ما تحته خط: سِرتُ سَيرًا بطيئًا."],"levels":{"easy":[{"type":"mcq","q":"ما المفعول المطلق في جملة: فَرِحَ الطالبُ فَرَحًا؟","options":["الطالبُ","فَرِحَ","فَرَحًا","لا يوجد مفعول مطلق"],"answer":2,"why":"فَرَحًا مصدر الفعل فَرِحَ، جاء منصوبًا بعده، فهو مفعول مطلق."},{"type":"mcq","q":"أيّ الجمل الآتية فيها مفعول مطلق؟","options":["قرأ الطالبُ كتابًا","قرأ الطالبُ قراءةً","قرأ الطالبُ في البيتِ","قرأ الطالبُ صباحًا"],"answer":1,"why":"قراءةً مصدر الفعل قرأ. أما كتابًا فمفعول به، وفي البيتِ جار ومجرور، وصباحًا ظرف زمان."},{"type":"mcq","q":"ما نوع المفعول المطلق في جملة: نِمتُ نومًا عميقًا؟","options":["مبيِّن للعدد","مؤكِّد للفعل","مفعول به","مبيِّن للنوع"],"answer":3,"why":"المصدر نومًا وُصف بكلمة عميقًا، فبيّن نوع النوم، فهو مبيِّن للنوع."},{"type":"mcq","q":"ما علامة نصب كلمة «قفزتينِ» في جملة: قفزَ اللاعبُ قفزتينِ؟","options":["الياء","الفتحة","الكسرة","الألف"],"answer":0,"why":"قفزتينِ مثنّى، والمثنّى يُنصب بالياء."}],"medium":[{"type":"mcq","q":"في جملة: انتصرَ الفريقُ انتصارًا، المفعول المطلق من نوع:","options":["مبيِّن للنوع","مبيِّن للعدد","مؤكِّد للفعل","نائب عن المفعول المطلق"],"answer":2,"why":"انتصارًا مصدر لم يُوصف ولم يدل على عدد، وإنما أكّد وقوع الفعل."},{"type":"tfr","q":"كلمة «كتابًا» في جملة: قرأ الطالبُ كتابًا، مفعول مطلق.","answer":false,"reasons":["لأن كتابًا ليس مصدر الفعل قرأ، بل هو ما وقعت عليه القراءة، فهو مفعول به","لأن كتابًا مرفوعة","لأن المفعول المطلق لا يأتي بعد الفعل"],"reason":0,"why":"المفعول المطلق هو مصدر الفعل نفسه، مثل: قراءةً."},{"type":"essay","q":"استخرج المفعول المطلق من الجملة: سِرتُ سَيرَ الواثقينَ، وبيّن نوعه.","model":"المفعول المطلق: سَيرَ. وهو مبيِّن للنوع لأنه أُضيف إلى «الواثقين» فبيّن كيف كان السير."},{"type":"tfr","q":"المفعول المطلق المؤكِّد للفعل يجوز تثنيته وجمعه.","answer":false,"reasons":["لأنه دائمًا مرفوع","لأن المؤكِّد لا يدل على عدد ولا نوع، فلا يُثنّى ولا يُجمع","لأن المثنّى لا يأتي بعد الفعل"],"reason":1,"why":"الذي يُثنّى ويُجمع هو المبيِّن للعدد، مثل: قفزتينِ وقفزاتٍ."},{"type":"mcq","q":"ما إعراب كلمة «فَرَحًا» في جملة: فَرِحَ الطالبُ فَرَحًا؟","options":["فاعل مرفوع","مفعول به منصوب","حال منصوبة","مفعول مطلق منصوب وعلامة نصبه الفتحة"],"answer":3,"why":"فَرَحًا مصدر الفعل فَرِحَ، فهو مفعول مطلق منصوب بالفتحة."},{"type":"essay","q":"أكمل الجملة بمفعول مطلق مبيِّن للعدد: قفزَ اللاعبُ ........","model":"قفزَ اللاعبُ قفزتينِ (أو قفزةً أو قفزاتٍ). كلها مصادر تدل على عدد مرات القفز."},{"type":"tfr","q":"في جملة: أحببتُ وطني كلَّ الحُبِّ، تنوب كلمة «كلَّ» عن المفعول المطلق.","answer":true,"reasons":["لأن كلَّ فاعل","لأن كلَّ حرف نصب","لأن كلَّ مضافة إلى المصدر الحُبِّ، فنابت عن المفعول المطلق وأخذت حكمه"],"reason":2}],"hard":[{"type":"mcq","q":"أيّ الجمل الآتية فيها نائب عن المفعول المطلق؟","options":["قرأتُ كتابًا","انتظرتُ صديقي طويلًا","جلستُ في الحديقةِ","وصلتُ مساءً"],"answer":1,"why":"طويلًا صفة لمصدر محذوف، والتقدير: انتظرتُه انتظارًا طويلًا، فنابت عنه."},{"type":"essay","q":"اشرح الفرق بين المفعول المطلق والمفعول به بمثال لكل منهما.","model":"المفعول المطلق هو مصدر الفعل نفسه ويؤكد الفعل أو يبيّن نوعه أو عدده، مثل: كتبَ الطالبُ كتابةً. أما المفعول به فهو ما وقع عليه الفعل، مثل: كتبَ الطالبُ الدرسَ."},{"type":"tfr","q":"في جملة: قفزَ اللاعبُ ثلاثَ قفزاتٍ، كلمة «ثلاثَ» نائب عن المفعول المطلق.","answer":true,"reasons":["لأنها فاعل مرفوع","لأنها عدد مضاف إلى المصدر قفزاتٍ، يدل على عدد مرات الفعل، فنابت عن المفعول المطلق","لأنها مفعول به وقع عليه الفعل"],"reason":1},{"type":"mcq","q":"ما علامة نصب المفعول المطلق في جملة: قفزَ اللاعبُ قفزاتٍ؟","options":["الفتحة","الياء","الألف","الكسرة"],"answer":3,"why":"قفزاتٍ جمع مؤنث سالم، وهو يُنصب بالكسرة نيابةً عن الفتحة."},{"type":"essay","q":"كوّن جملة فيها مفعول مطلق مبيِّن للنوع بوصفه بصفة، ثم أعربه.","model":"مثال: ركضَ الولدُ ركضًا سريعًا. ركضًا: مفعول مطلق منصوب وعلامة نصبه الفتحة الظاهرة، وسريعًا: صفة منصوبة وعلامة نصبها الفتحة. وتُقبل أي جملة صحيحة تؤدي المعنى."},{"type":"tfr","q":"في جملة: ضحكَ الطفلُ ضحكًا، المفعول المطلق مؤكِّد للفعل.","answer":true,"reasons":["لأنه مصدر لم يُوصف ولم يدل على عدد، وإنما أكّد وقوع الفعل","لأنه يبيّن نوع الضحك","لأنه يدل على أن الضحك وقع مرتين"],"reason":0},{"type":"mcq","q":"أيّ الجمل الآتية فيها مفعول مطلق مبيِّن للعدد؟","options":["طرقتُ البابَ طرقتينِ","طرقتُ البابَ بقوةٍ","طرقتُ البابَ أمامَ البيتِ","طرقتُ البابَ طرقًا"],"answer":0,"why":"طرقتينِ تدل على عدد المرات. أما طرقًا فمؤكِّد للفعل، وبقوةٍ جار ومجرور، وأمامَ ظرف مكان."},{"type":"essay","q":"حوّل الجملة: انتصرَ الفريقُ، إلى جملة فيها مفعول مطلق مبيِّن للنوع، ثم اذكر علامة نصبه.","model":"انتصرَ الفريقُ انتصارًا كبيرًا. انتصارًا: مفعول مطلق منصوب وعلامة نصبه الفتحة، وكبيرًا صفته تبيّن نوع الانتصار."},{"type":"tfr","q":"إذا قلنا: اجتهدتُ بعضَ الاجتهادِ، فإن «بعضَ» مفعول به.","answer":false,"reasons":["لأن بعضَ فعل ماضٍ","لأن بعضَ مرفوعة فلا تكون منصوبة","لأن بعضَ مضافة إلى المصدر الاجتهادِ، فهي نائب عن المفعول المطلق وليست مفعولًا به"],"reason":2},{"type":"essay","q":"اكتب ثلاث جمل عن يوم دراسي، في كل جملة نوع من أنواع المفعول المطلق: المؤكِّد للفعل، والمبيِّن للنوع، والمبيِّن للعدد.","model":"أمثلة: فرحَ الطلابُ فرحًا (مؤكِّد للفعل). استمعتُ إلى المعلمِ استماعًا هادئًا (مبيِّن للنوع). قفزَ اللاعبُ قفزتينِ في الساحة (مبيِّن للعدد). وتُقبل أي جمل صحيحة."}]}},
  {"id":"g9-arabic-1-1","grade":"g9","subject":"arabic","term":1,"unit":6,"no":4,"title":"التعبير: ترجمة علم","summary":"شرح متحرك لعناصر كتابة ترجمة العَلَم وأسلوبها بمثال الخليل بن أحمد الفراهيدي، ثم أنشطة بثلاثة مستويات.","page":"lesson-biography-writing.html","video":"","pdf":"","notes":["ترجمة العَلَم: نص قصير يعرّف بحياة شخص مشهور وأعماله وأثره.","عناصرها بالترتيب: الاسم والنسب والمولد، ثم النشأة وطلب العلم، ثم الأعمال والإنجازات، ثم المؤلفات والتلاميذ، ثم الوفاة والأثر.","نختار من الإنجازات أهمها فقط، ونكتب كل إنجاز بجملة واضحة محددة.","نكتب الترجمة بضمير الغائب وبالفعل الماضي، مثل: وُلد ونشأ وألّف.","نرتب الأحداث ترتيبًا زمنيًا من الولادة إلى الوفاة.","نلتزم الموضوعية: معلومات صحيحة بلا مبالغة."],"exercises":["اذكر عناصر ترجمة العَلَم بالترتيب.","أعد كتابة الجملة بأسلوب الترجمة: أنا أحب الخليل، وأنا أقرأ كتابه.","اكتب ترجمة قصيرة من أربع جمل لعالم أو أديب تعرفه."],"levels":{"easy":[{"type":"mcq","q":"ما ترجمة العَلَم؟","options":["قصة خيالية عن بطل","نص يعرّف بحياة شخص مشهور وأعماله","نقل نص من لغة إلى أخرى","قصيدة في مدح شخص"],"answer":1,"why":"ترجمة العَلَم نص يعرّف بشخص مشهور: حياته وأعماله وأثره، وليست نقل نص من لغة إلى أخرى."},{"type":"mcq","q":"بماذا نبدأ ترجمة العَلَم؟","options":["بالوفاة والأثر","بالمؤلفات فقط","بالاسم والنسب والمولد","بذكر رأينا فيه"],"answer":2,"why":"نبدأ بالاسم والنسب والمولد لنعرف من هو العَلَم ومن أي قوم ومتى عاش."},{"type":"mcq","q":"بأي ضمير تُكتب ترجمة العَلَم؟","options":["ضمير المتكلم (أنا)","ضمير المخاطب (أنت)","ضمير الجمع (نحن)","ضمير الغائب (هو)"],"answer":3,"why":"نكتب عن العَلَم وهو غائب، فنقول: وُلد ونشأ وألّف."},{"type":"mcq","q":"بماذا نختم ترجمة العَلَم؟","options":["بالوفاة والأثر","بالاسم والنسب","بالنشأة وطلب العلم","بسؤال للقارئ"],"answer":0,"why":"نختم بالوفاة ثم بالأثر الذي تركه العَلَم."}],"medium":[{"type":"mcq","q":"أيّ الجمل الآتية تناسب أسلوب كتابة الترجمة؟","options":["أنا أحب الخليل كثيرًا","وُلد الخليل في البصرة ونشأ محبًّا للعلم","اذهب واقرأ كتاب العين","سيولد الخليل في البصرة"],"answer":1,"why":"الترجمة تُكتب بضمير الغائب وبالفعل الماضي، وهذا ما في الجملة الثانية."},{"type":"tfr","q":"من عناصر الترجمة أن نذكر مؤلفات العَلَم وتلاميذه.","answer":true,"reasons":["لأن المؤلفات والتلاميذ تُظهر قيمة العَلَم وتأثيره","لأن الترجمة لا تذكر غير الوفاة","لأن المؤلفات تُذكر في أول الترجمة فقط"],"reason":0},{"type":"essay","q":"اذكر عناصر ترجمة العَلَم الخمسة بالترتيب.","model":"الاسم والنسب والمولد، ثم النشأة وطلب العلم، ثم الأعمال والإنجازات، ثم المؤلفات والتلاميذ، ثم الوفاة والأثر."},{"type":"tfr","q":"يجوز أن نبالغ في مدح العَلَم في الترجمة لنُظهر فضله.","answer":false,"reasons":["لأن الترجمة لا تذكر فضل العَلَم أبدًا","لأن الترجمة تلتزم الموضوعية، فتذكر معلومات صحيحة بلا مبالغة","لأن المبالغة تُكتب في المقدمة فقط"],"reason":1},{"type":"mcq","q":"في أي عنصر نذكر أن الخليل «وضع علم العروض»؟","options":["الاسم والنسب والمولد","النشأة وطلب العلم","الوفاة والأثر","الأعمال والإنجازات"],"answer":3,"why":"وضع علم العروض عمل من أعمال الخليل، فيدخل في الأعمال والإنجازات."},{"type":"essay","q":"أكمل بفعل مناسب لأسلوب الترجمة: الخليل بن أحمد ........ في البصرة نحو سنة مئة للهجرة.","model":"وُلد. فعل ماضٍ يناسب ضمير الغائب وأسلوب الترجمة."},{"type":"tfr","q":"نرتب أحداث الترجمة ترتيبًا زمنيًا من الولادة إلى الوفاة.","answer":true,"reasons":["لأن الترجمة تبدأ بالوفاة دائمًا","لأن الترتيب لا يهم في الترجمة","لأن الترتيب الزمني يجعل حياة العَلَم واضحة متسلسلة"],"reason":2}],"hard":[{"type":"mcq","q":"أيّ الجمل الآتية فيها خلل في أسلوب كتابة الترجمة؟","options":["أنا أعجب بالخليل أشد الإعجاب","نشأ الخليل محبًّا للعلم","ألّف الخليل معجم العين","توفي الخليل في البصرة"],"answer":0,"why":"الترجمة تُكتب بضمير الغائب وبموضوعية، لا بضمير المتكلم ولا بإبداء الإعجاب الشخصي."},{"type":"essay","q":"لماذا نبدأ ترجمة العَلَم بالاسم والنسب والمولد؟","model":"لأنها تعرّف القارئ بمن هو العَلَم ومن أي قوم، ومتى ولد وأين، وبها تتهيأ بقية الترجمة. وتُقبل أي إجابة تؤدي هذا المعنى."},{"type":"tfr","q":"يمكن أن تبدأ الترجمة بذكر الوفاة ثم الولادة.","answer":false,"reasons":["لأن الترجمة تُكتب بصيغة المضارع","لأن الوفاة لا تُذكر في الترجمة","لأن الترجمة تُرتَّب زمنيًا من الولادة إلى الوفاة"],"reason":2},{"type":"mcq","q":"لماذا نختار من إنجازات العَلَم أهمها فقط؟","options":["لأن بقية الإنجازات غير صحيحة","لأن الترجمة لا تذكر الإنجازات","لأن الترجمة تعرّف بالعَلَم، فنختار ما يخدم هذا التعريف ولا نذكر غيره","لكي يطول النص"],"answer":2,"why":"الترجمة نص قصير غايته التعريف بالعَلَم، فنقتصر على ما يخدم ذلك."},{"type":"essay","q":"اذكر ثلاث صفات لأسلوب كتابة الترجمة، وأعطِ مثالًا على إحداها.","model":"ضمير الغائب والفعل الماضي، والترتيب الزمني، والموضوعية. مثال: وُلد الخليل في البصرة ونشأ محبًّا للعلم."},{"type":"tfr","q":"نكتب في الترجمة معلومات صحيحة حتى لو لم نكن متأكدين منها.","answer":false,"reasons":["لأن الموضوعية تقتضي ذكر معلومات صحيحة موثوقة فقط","لأن الترجمة تعتمد على الخيال","لأن المعلومات لا تؤثر في قيمة الترجمة"],"reason":0},{"type":"mcq","q":"في أي عنصر نذكر أن سيبويه من تلاميذ الخليل؟","options":["الأعمال والإنجازات","الاسم والنسب والمولد","الوفاة والأثر","المؤلفات والتلاميذ"],"answer":3,"why":"ذكر التلاميذ يدخل في عنصر المؤلفات والتلاميذ، وهو يُظهر أثر العَلَم."},{"type":"essay","q":"اكتب جملتين عن إنجازات عالم أو أديب تعرفه بأسلوب الترجمة.","model":"مثال: ألّف الخليل معجم العين وهو أول معجم عربي. ووضع علم العروض فضبط أوزان الشعر. وتُقبل أي جملتين بضمير الغائب وفعل ماضٍ ومعلومات صحيحة."},{"type":"tfr","q":"ذكر الأثر في آخر الترجمة يبيّن قيمة العَلَم بعد وفاته.","answer":true,"reasons":["لأن الأثر يُذكر لملء الصفحة فقط","لأن الأثر يبيّن ما بقي من فضل العَلَم بعد وفاته","لأن الأثر لا علاقة له بالعَلَم"],"reason":1},{"type":"essay","q":"اكتب ترجمة قصيرة من أربع جمل لعالم أو أديب تعرفه، مراعيًا العناصر وأسلوب الترجمة.","model":"مثال: وُلد الخليل بن أحمد الفراهيدي في البصرة نحو سنة مئة للهجرة. نشأ محبًّا للعلم وأخذ عن علماء البصرة. وضع علم العروض وألّف معجم العين. توفي في البصرة، وما زال علمه يُدرَّس. وتُقبل أي ترجمة مرتبة زمنيًا وبضمير الغائب."}]}},
  {"id":"g9-arabic-1-u1-1","grade":"g9","subject":"arabic","term":1,"unit":1,"no":1,"title":"البلاغة عند العرب","summary":"شرح متحرك لنص الجاحظ من كتاب البيان والتبيين ومفهوم البلاغة ومقوّمات البليغ، ثم أنشطة بثلاثة مستويات.","page":"lesson-balagha-arabs.html","video":"","pdf":"","notes":["كاتب النص هو الجاحظ (عمرو بن بحر)، ومصدره كتاب «البيان والتبيين».","البلاغة لغةً: الوصول إلى الغاية. واصطلاحًا: مطابقة الكلام لمقتضى الحال مع فصاحته.","طرح الجاحظ فكرة أصالة البلاغة عند العرب وردّ على من شكّك في فصاحتهم.","من تعريفات العرب للبلاغة: الإيجاز، وإصابة المعنى، وملاءمة الكلام للمقام والسامعين.","من مقوّمات الخطيب البليغ: وضوح الصوت، وحسن الإشارة، والثبات، ومعرفة موضع الإيجاز والتفصيل.","يقوم منهج الجاحظ على طرح الفكرة ثم تدعيمها بشواهد من خطباء العرب مثل صُحار العبدي."],"exercises":["عرّف البلاغة لغةً واصطلاحًا.","كيف استدلّ الجاحظ على أصالة البلاغة عند العرب؟","اذكر اثنتين من سمات أسلوب الجاحظ في النص."],"levels":{"easy":[{"type":"mcq","q":"من كاتب نص «البلاغة عند العرب»؟","options":["المتنبي","الجاحظ","البوصيري","ابن المقفع"],"answer":1,"why":"كاتب النص هو أبو عثمان عمرو بن بحر المعروف بالجاحظ."},{"type":"mcq","q":"من أي كتاب أُخذ نص «البلاغة عند العرب»؟","options":["البخلاء","الحيوان","البيان والتبيين","كتاب العين"],"answer":2,"why":"أُخذ النص من كتاب «البيان والتبيين» للجاحظ."},{"type":"mcq","q":"ما معنى «البلاغة» في اللغة؟","options":["الوصول والانتهاء إلى الغاية","كثرة الكلام وتكراره","السكوت الطويل","رفع الصوت"],"answer":0,"why":"البلاغة في اللغة من الفعل «بلغ» أي وصل إلى الغاية والمنتهى."},{"type":"mcq","q":"بماذا عرّف الخطيب صُحار العبدي البلاغة؟","options":["الإطالة","الإيجاز","السجع","الغموض"],"answer":1,"why":"أجاب صُحار العبدي بإجابة موجزة جامعة: البلاغة هي الإيجاز."}],"medium":[{"type":"mcq","q":"ما المقصود بالبلاغة في الاصطلاح؟","options":["استخدام ألفاظ غريبة يصعب فهمها","إطالة الخطبة مهما كان الموقف","مطابقة الكلام لمقتضى الحال مع فصاحته","الاكتفاء بالشعر دون النثر"],"answer":2,"why":"البلاغة اصطلاحًا هي مطابقة الكلام لمقتضى الحال مع فصاحته، أي لكل مقام مقال."},{"type":"tfr","q":"اكتفى الجاحظ بطرح رأيه في بلاغة العرب دون أن يستشهد بأقوال الخطباء.","answer":false,"reasons":["لأن منهج الجاحظ يقوم على طرح الفكرة ثم الاستشهاد عليها بأقوال بلغاء العرب","لأن الجاحظ لم يكتب في البلاغة أصلًا","لأن الشواهد لا تُستخدم في النثر"],"reason":0},{"type":"essay","q":"ما الفكرة العامة التي يدافع عنها الجاحظ في نص «البلاغة عند العرب»؟","model":"إثبات أصالة البلاغة والفصاحة والبيان عند العرب، والردّ على من شكّك في ذلك."},{"type":"tfr","q":"الإيجاز يعني أداء المعنى الكثير بلفظ قليل غير مُخلّ بالمعنى.","answer":true,"reasons":["لأن الإيجاز البليغ يجمع بين قلة الألفاظ ووضوح المعنى وكماله","لأن الإيجاز يعني حذف المعنى المهم","لأن الإيجاز يعني إطالة الجملة"],"reason":0},{"type":"mcq","q":"أيٌّ مما يأتي يُعدّ من مقوّمات الأداء لدى الخطيب البليغ؟","options":["الارتباك والتردد","وضوح الصوت وحسن الإشارة","خفض الصوت حتى لا يُسمع","استخدام كلمات غامضة"],"answer":1,"why":"البلاغة تشمل جمال العبارة وحسن الأداء كوضوح الصوت وحسن الإشارة والثبات."},{"type":"essay","q":"اذكر اثنتين من سمات أسلوب الجاحظ في هذا النص.","model":"وضوح الألفاظ ودقّتها، والتنويع بين الخبر والحوار (السؤال والجواب)، والإكثار من الشواهد والأمثلة."},{"type":"tfr","q":"التطويل في الكلام يُعدّ بلاغة في جميع المواقف دون استثناء.","answer":false,"reasons":["لأن التطويل في موضع الإيجاز يُملّ، فلكل مقام ما يناسبه من إيجاز أو تفصيل","لأن التطويل ممنوع في اللغة العربية دائمًا","لأن البلاغة لا علاقة لها بالموقف"],"reason":0}],"hard":[{"type":"mcq","q":"لماذا نوّع الجاحظ بين أسلوب الخبر وأسلوب السؤال والجواب في النص؟","options":["لإطالة النص بلا فائدة","لتشويق القارئ وتثبيت الفكرة وإقناعه","لإخفاء المعنى المقصود","لأنه نسي بقية الفكرة"],"answer":1,"why":"الحوار والسؤال والجواب يجذب انتباه القارئ ويجعل عرض الفكرة أكثر إقناعًا وتشويقًا."},{"type":"essay","q":"اشرح العبارة: «لكلّ مقامٍ مقالٌ» وبيّن علاقتها بمفهوم البلاغة.","model":"تعني أن الكلام يجب أن يناسب الموقف وحال السامعين؛ فيوجز المتكلم حين يقتضي المقام الإيجاز، ويفصّل حين يحتاج السامع إلى التوضيح، وهذا جوهر البلاغة (مطابقة الكلام لمقتضى الحال)."},{"type":"tfr","q":"يجمع كتاب «البيان والتبيين» للجاحظ بين دراسة الخطابة والفصاحة وشواهد العرب.","answer":true,"reasons":["لأنه من أوائل الموسوعات الأدبية التي جمعت قضايا البيان والخطابة وأقوال البلغاء","لأنه كتاب في علم الحساب فقط","لأنه يقتصر على ترجمة الكتب الأجنبية"],"reason":0},{"type":"mcq","q":"ماذا ينتج إذا اختصر المتكلّم كلامه اختصارًا شديدًا أضاع الفكرة؟","options":["يُعدّ قمة البلاغة","يُعدّ إيجازًا مُخلًّا يُفسد المعنى","يُعدّ إطنابًا محمودًا","لا يؤثر في الفهم"],"answer":1,"why":"الإيجاز المحمود هو ما يؤدّي المعنى كاملًا بوضوح، أما الاختصار الذي يضيع المعنى فمُخلّ."},{"type":"essay","q":"دلّل من النص على أن الجاحظ يتبع منهجًا علميًا في عرض أفكاره.","model":"يطرح الفكرة (أصالة البلاغة عند العرب) ثم يورد أدلة وشواهد من أقوال خطباء وبلغاء معروفين مثل صُحار العبدي لتأكيدها وإقناع القارئ."},{"type":"tfr","q":"اقتصرت البلاغة عند العرب على جمال الألفاظ المكتوبة دون الاهتمام بالخطابة الشفهية.","answer":false,"reasons":["لأن الخطابة والارتجال وحسن الأداء أمام الناس كانت من أبرز ميادين البلاغة عند العرب","لأن العرب لم يعرفوا الخطابة أبدًا","لأن البلاغة خاصة بالرسائل فقط"],"reason":0},{"type":"mcq","q":"أيّ الصفات الآتية تبتعد عن مفهوم البلاغة كما عرضه الجاحظ؟","options":["إصابة المعنى","ملاءمة حال السامع","الحشو والتعقيد اللفظي","الإيجاز الواضح"],"answer":2,"why":"الحشو والتعقيد يُضعفان الكلام ويبعدانه عن الوضوح والتأثير البلاغي."},{"type":"essay","q":"قارن بين «الإيجاز» و«التفصيل (الإطناب)» من حيث متى يكون كلٌّ منهما بليغًا.","model":"يكون الإيجاز بليغًا عندما تكفي العبارة القصيرة لإيصال المعنى بقوة، ويكون التفصيل بليغًا عندما يحتاج المقام إلى الشرح والإيضاح لإزالة اللبس."},{"type":"tfr","q":"مراعاة مستوى عقول المستمعين جزءٌ أساسٌ من بلاغة المتكلّم.","answer":true,"reasons":["لأن البلاغة هي إيصال المعنى إلى قلب السامع وعقله بما يلائم فهمه وحاله","لأن المتكلّم يخاطب الجميع بألفاظ صعبة دائمًا","لأن السامع لا دور له في البلاغة"],"reason":0},{"type":"essay","q":"اكتب فقرة قصيرة من ثلاث جمل توضّح فيها كيف تستفيد من قواعد البلاغة عند إلقاء كلمة في الإذاعة المدرسية.","model":"أختار ألفاظًا واضحة ومناسبة لزملائي، وأوجز في عباراتي دون حشو ممل، وأحرص على وضوح الصوت والثبات وحسن الإشارة لإيصال الفكرة بتأثير."}]}},
  {"id":"g9-arabic-1-u1-2","grade":"g9","subject":"arabic","term":1,"unit":1,"no":6,"title":"قصيدة: يا سماء","summary":"شرح متحرك لقصيدة «يا سماء» للبوصيري وأفكارها وصورها الجمالية وأساليبها البلاغية، ثم أنشطة بثلاثة مستويات.","page":"lesson-ya-samaa.html","video":"","pdf":"","notes":["الشاعر: الإمام شرف الدين محمد بن سعيد البوصيري، ومن أشهر قصائده «البردة» و«الهمزية».","غرض القصيدة: المدائح النبوية (تعظيم مكانة النبي ﷺ وبيان أخلاقه وخلود رسالته).","الاستفهام في «كيف ترقى رقيّك الأنبياءُ» غرضه النفي والتعظيم.","شبّه الشاعر النبيّ ﷺ بالسماء في العلوّ، وبالدرّة اليتيمة في عقد الشرف، وشبّه وجهه بالشمس المضيئة.","جمع الشاعر أخلاق النبيّ ﷺ في بيتٍ واحد: الرحمة، الحزم، العزم، الوقار، العصمة، الحياء.","أكّد الشاعر أن العلماء يرثون نور هداية النبيّ ﷺ، وأن العجز عن حصر فضائله معجزةٌ بحدّ ذاتها."],"exercises":["ما الغرض من الاستفهام في قول البوصيري: «كيف ترقى رقيّك الأنبياءُ»؟","اشرح الصورة الجمالية في: «أنت فيه اليتيمةُ العصماءُ».","اذكر أربع صفات خُلقية للنبيّ ﷺ وردت في القصيدة."],"levels":{"easy":[{"type":"mcq","q":"من قائل قصيدة «يا سماء»؟","options":["المتنبي","شرف الدين البوصيري","أبو تمام","الجاحظ"],"answer":1,"why":"قائل القصيدة هو الإمام شرف الدين محمد بن سعيد البوصيري."},{"type":"mcq","q":"ما الغرض الشعري لقصيدة «يا سماء»؟","options":["الرثاء","الهجاء","المدائح النبوية","الوصف الطبيعي"],"answer":2,"why":"القصيدة من روائع المدائح النبوية في تعظيم النبيّ محمد ﷺ."},{"type":"mcq","q":"ما معنى كلمة «المحيّا» في قول الشاعر «ومحيًّا كالشمس منك مضيءٌ»؟","options":["الوجه","السيف","الطريق","الصوت"],"answer":0,"why":"المحيّا هو الوجه، وقد شبّهه الشاعر بالشمس المضيئة."},{"type":"mcq","q":"ما أسلوب «حبّذا» في قول الشاعر: «حبّذا عقدُ سؤددٍ وفخارِ»؟","options":["أسلوب نهي","أسلوب استفهام","أسلوب ذم","أسلوب مدح"],"answer":3,"why":"«حبّذا» أسلوب مدحٍ يعبّر عن الإعجاب والتعظيم."}],"medium":[{"type":"mcq","q":"ما الغرض البلاغي من الاستفهام في: «كيف ترقى رقيّك الأنبياءُ»؟","options":["التمني","النفي والتعظيم","التعجب من القلة","طلب المعلومة"],"answer":1,"why":"المعنى أنه لا يبلغ أحدٌ منزلة النبيّ ﷺ الرفيعة، فغرضه النفي والتعظيم."},{"type":"tfr","q":"سُمّيت قصيدة البوصيري التي أُخذ منها النص بـ «الهمزية» لأن قافيتها تنتهي بالهمزة.","answer":true,"reasons":["لأن حرف الرويّ في أبياتها هو الهمزة المضمومة (سماءُ، أنبياءُ، عصماءُ)","لأنها تبدأ بحرف الهمزة فقط","لأن عدد أبياتها همزة"],"reason":0},{"type":"essay","q":"اشرح الصورة الجمالية في قول الشاعر: «ومحيًّا كالشمس منك مضيءٌ».","model":"شبّه الشاعر وجه النبيّ ﷺ بالشمس المضيئة في إشراقه ونوره، مما يوحي بالبهاء والهداية."},{"type":"tfr","q":"كلمة «السؤدد» في البيت: «حبّذا عقدُ سؤددٍ وفخارِ» تعني الضعف والانكسار.","answer":false,"reasons":["لأن «السؤدد» يعني السيادة والشرف والمكانة العالية","لأن «السؤدد» يعني الليل المظلم","لأن «السؤدد» اسم مدينة"],"reason":0},{"type":"mcq","q":"من الذين وصفهم الشاعر بأنهم يرثون نور هدي النبيّ ﷺ بعده؟","options":["التجار","العلماء","الشعراء فقط","المسافرون"],"answer":1,"why":"قال الشاعر: «لم نخف بعدك الضلال وفينا / وارثو نور هديك العلماءُ»."},{"type":"essay","q":"ما المقصود بـ «اليتيمة العصماء» في وصف النبيّ ﷺ؟","model":"اليتيمة هي الدرّة الثمينة الفريدة التي لا مثيل لها، والعصماء أي الرفيعة المصونة؛ فشُبّه النبيّ ﷺ بالجوهرة الفريدة وسط عقد الشرف."},{"type":"tfr","q":"بين كلمتي «مضيءٌ» و«ليلةٌ» في البيت طباقٌ يبرز أثر نور النبيّ ﷺ.","answer":true,"reasons":["لأن الجمع بين النور والليل يوضّح المعنى ويُبرز كيف أضاء نور الهداية الظلام","لأن الكلمتين مترادفتان بنفس المعنى","لأنهما من نفس الجذر اللغوي"],"reason":0}],"hard":[{"type":"mcq","q":"على ماذا يدلّ قول الشاعر: «رحمةٌ كلّه» في وصف النبيّ ﷺ؟","options":["أنه رحيم أحيانًا فقط","عموم رحمته ﷺ وكأن ذاته كلّها رحمة للعالمين","أنه يفتقر إلى الحزم","أنه وصف للطبيعة"],"answer":1,"why":"جَعْلُه «رحمةً كلّه» تعبير بليغ يدلّ على شمول رحمته ﷺ للناس جميعًا."},{"type":"essay","q":"كيف جمع البوصيري بين صفات القوة وصفات اللين في شخصية النبيّ ﷺ؟","model":"جمع بين «الرحمة والحياء والوقار» (صفات اللين والرفق) وبين «الحزم والعزم» (صفات القوة والقيادة) في بيتٍ واحدٍ ليبيّن تكامل شخصيته ﷺ."},{"type":"tfr","q":"يرى الشاعر أن معجزات النبيّ ﷺ انقضت بوفاته مثل معجزات الأنبياء السابقين.","answer":false,"reasons":["لأنه أكّد أن آيات الأنبياء السابقين انقضت، أما آيات النبيّ ﷺ والقرآن فباقية لا تنقضي","لأنه لم يذكر المعجزات في القصيدة","لأنه قارن بين الشعر والنثر فقط"],"reason":0},{"type":"mcq","q":"لماذا أطال البوصيري في مدح النبيّ ﷺ كما ذكر في نهاية الأبيات؟","options":["ليحصر جميع فضائله بالكامل","لأنه مشتاقٌ كالظمآن لا يرتوي من ذكره ﷺ رغم عجزه عن الإحصاء","ليثبت أنه أفضل من غيره من الشعراء","لأنه طلب مالًا من أحد الملوك"],"answer":1,"why":"صرّح بأنه لا يستطيع استقصاء فضائله، وإنما يطيل المدح شوقًا ومحبةً كالظمآن الذي لا يرتوي بقليل الماء."},{"type":"essay","q":"ما دلالة نداء النبيّ ﷺ بقوله «يا سماءً ما طاولتها سماءُ»؟","model":"يدلّ على سموّ مكانة النبيّ ﷺ وارتفاع قدره فوق كلّ رفعة، فلا تبلغ منزلته أيّ منزلة أخرى."},{"type":"tfr","q":"العاطفة المسيطرة على قصيدة «يا سماء» هي عاطفة الحب الصادق والتعظيم والشوق.","answer":true,"reasons":["لأن ألفاظ القصيدة وصورها وتواضع الشاعر في ختامها كلها تفيض بالمحبة والإجلال للنبيّ ﷺ","لأن العاطفة هي الحزن واليأس","لأن الشاعر يفتخر بنفسه فقط"],"reason":0},{"type":"mcq","q":"أيّ بيتٍ مما يأتي يعكس اطمئنان الأمة على هدايتها بعد النبيّ ﷺ؟","options":["كيف ترقى رقيّك الأنبياءُ","لم نخف بعدك الضلال وفينا وارثو نور هديك العلماءُ","حبّذا عقدُ سؤددٍ وفخارِ","رحمةٌ كلّه وحزمٌ وعزمٌ"],"answer":1,"why":"البيت يطمئن الأمة بأن العلماء يرثون نور الهدي النبوي ويحفظون الناس من الضلال."},{"type":"essay","q":"اذكر أسلوبين بلاغيين من القصيدة ومثّل لكلٍّ منهما من الأبيات.","model":"١) أسلوب الاستفهام للتعظيم: «كيف ترقى رقيّك الأنبياءُ». ٢) أسلوب المدح: «حبّذا عقدُ سؤددٍ وفخارِ». (ويُقبل أيضًا النداء «يا سماءً» أو التشبيه «محيًّا كالشمس»)."},{"type":"tfr","q":"وصف الشاعر العجز عن وصف النبيّ ﷺ بأنه من معجزاته لأنه لا يمكن إحصاء فضائله.","answer":true,"reasons":["لأنه قال: «إنّ من معجزاتك العجزُ عن وصفك إذ لا يحدّه الإحصاءُ»","لأن الشاعر لم يعرف شيئًا عن سيرة النبيّ ﷺ","لأن الإحصاء يسهل حصر فضائله"],"reason":0},{"type":"essay","q":"تأمّل البيت: «رحمةٌ كلّه وحزمٌ وعزمٌ / ووقارٌ وعصمةٌ وحياءُ». ما أثر تعدّد الصفات المعطوفة بالواو في المعنى؟","model":"يدلّ تعدّد الصفات والعطف بالواو على اجتماع الفضائل كلّها في شخصيته ﷺ وتكامل أخلاقه الإنسانية والقيادية دون نقص."}]}},
  {"id":"g9-arabic-1-u1-3","grade":"g9","subject":"arabic","term":1,"unit":5,"no":2,"title":"المفعول لأجله","summary":"شرح متحرك لمفهوم المفعول لأجله وشروطه وصوره وإعرابه، ثم أنشطة بثلاثة مستويات.","page":"lesson-mafool-liajlih.html","video":"","pdf":"","notes":["المفعول لأجله: مصدر قلبي منصوب يُذكر لبيان سبب وقوع الفعل، ويجيب عن السؤال «لماذا؟».","شروط نصبه: أن يكون مصدرًا قلبيًّا، وأن يبيّن سبب الفعل، وأن يتحد مع الفعل في الزمن والفاعل.","إذا فقد أحد الشروط وجب جره بحرف جر يفيد التعليل مثل اللام أو مِنْ.","صور المفعول لأجله ثلاث: مجرد من (أل) والإضافة (يغلب نصبه)، ومضاف (يستوي نصبه وجره)، ومقترن بـ (أل) (يكثر جره ويقل نصبه).","يُعرب: مفعولًا لأجله منصوبًا وعلامة نصبه الفتحة الظاهرة على آخره.","يختلف عن المفعول المطلق (المأخوذ من لفظ الفعل) وعن الحال (الذي يجيب عن «كيف؟»)."],"exercises":["استخرج المفعول لأجله وبيّن صورته: «يُذاكِرُ الطالبُ رَغْبَةً في التفوّقِ».","أعرب ما تحته خط: «يلجأ الناسُ إلى المصايفِ خَشْيَةَ الحرِّ».","حوّل المفعول لأجله المجرّد إلى مضاف في جملة: «تصدّقتُ طَلَبًا للأجرِ»."],"levels":{"easy":[{"type":"mcq","q":"أين المفعول لأجله في جملة: «وَقَفَ التلميذُ احترامًا للمعلّمِ»؟","options":["وَقَفَ","التلميذُ","احترامًا","للمعلّمِ"],"answer":2,"why":"«احترامًا» مصدر قلبي منصوب يجيب عن السؤال: لماذا وقف التلميذ؟"},{"type":"mcq","q":"ما السؤال الذي نستخدمه لمعرفة المفعول لأجله في الجملة؟","options":["أين؟","متى؟","كيف؟","لماذا؟"],"answer":3,"why":"المفعول لأجله يبيّن سبب وقوع الفعل، لذلك يصلح جوابًا عن «لماذا؟»."},{"type":"mcq","q":"ما علامة إعراب المفعول لأجله في جملة: «أجتهدُ رَغْبَةً في النجاحِ»؟","options":["الضمة","الفتحة","الكسرة","السكون"],"answer":1,"why":"المفعول لأجله منصوب دائمًا، وعلامة نصبه هنا الفتحة الظاهرة."},{"type":"mcq","q":"ما صورة المفعول لأجله في جملة: «تصدّقتُ طَلَبًا للأجرِ»؟","options":["مجرّد من أل والإضافة","مضاف","مقترن بأل","جار ومجرور"],"answer":0,"why":"«طَلَبًا» نكرة منوّنة غير مقترنة بأل ولم يأتِ بعدها مضاف إليه."}],"medium":[{"type":"mcq","q":"ما صورة المفعول لأجله في قوله تعالى: ﴿وَلَا تَقْتُلُوا أَوْلَادَكُمْ خَشْيَةَ إِمْلَاقٍ﴾؟","options":["مجرّد من أل والإضافة","مضاف","مقترن بأل","حال منصوبة"],"answer":1,"why":"«خَشْيَةَ» أضيفت إلى «إِمْلَاقٍ» فحُذف منها التنوين وجاءت بفتحة واحدة."},{"type":"tfr","q":"يُنوَّن المفعول لأجله بتنوين الفتح عندما يكون مضافًا.","answer":false,"reasons":["لأن الإضافة تحذف التنوين، فيُضبط بفتحة واحدة مثل: خشيةَ الحرِّ","لأن المفعول لأجله المضاف يكون مجرورًا دائمًا","لأن التنوين يوضع فقط على المقترن بأل"],"reason":0},{"type":"essay","q":"أعرب كلمة «حِفاظًا» في جملة: «يمارسُ الشابُّ الرياضةَ حِفاظًا على صحّتِهِ».","model":"حِفاظًا: مفعول لأجله منصوب وعلامة نصبه الفتحة الظاهرة على آخره."},{"type":"tfr","q":"في جملة «أقبلَ الطالبُ مبتسمًا» تُعرب كلمة «مبتسمًا» مفعولًا لأجله.","answer":false,"reasons":["لأنها تجيب عن «كيف؟» وتبيّن هيئة الطالب فهي حال وليست سببًا للفعل","لأنها مفعول مطلق مأخوذ من لفظ الفعل","لأنها فاعل مرفوع"],"reason":0,"why":"المفعول لأجله مصدر قلبي يجيب عن «لماذا؟»، أما «مبتسمًا» فحال."},{"type":"mcq","q":"أيُّ جملة مما يأتي تشتمل على مفعول لأجله؟","options":["اجتهدَ الطالبُ اجتهادًا عظيمًا","عادَ المسافرُ سعيدًا إلى وطنه","يتسابقُ الطلابُ رَغْبَةَ الفوزِ","قرأَ أحمدُ القصةَ مساءً"],"answer":2,"why":"«رَغْبَةَ» مصدر قلبي منصوب يبيّن سبب التسابق، وهو مضاف إلى «الفوزِ»."},{"type":"essay","q":"استخرج المفعول لأجله واذكر صورته في جملة: «يلجأ الناسُ إلى المصايفِ خَشْيَةَ الحرِّ».","model":"المفعول لأجله: «خَشْيَةَ»، وصورته: مضاف (أضيف إلى «الحرِّ»)."},{"type":"tfr","q":"عندما يكون المصدر مقترنًا بـ «أل» يكثر جرّه بحرف الجر ويقلّ نصبه.","answer":true,"reasons":["لأن الجرّ باللام أو مِنْ أفصح وأكثر استعمالًا مع «أل»، مثل: للرغبةِ في التفوّقِ","لأن النصب ممنوع تمامًا مع «أل»","لأن «أل» تحوّل المصدر إلى فعل"],"reason":0}],"hard":[{"type":"mcq","q":"لماذا جُرَّت كلمة «السفرِ» باللام في جملة: «أعددتُ الحقيبةَ للسفرِ غدًا»؟","options":["لأنها ليست مصدرًا","لاختلاف زمن الإعداد عن زمن السفر","لأنها مقترنة بأل فقط","لأن الفعل لازم"],"answer":1,"why":"الإعداد وقع الآن والسفر غدًا، فاختل شرط اتحاد الزمن ووجب الجر بحرف الجر."},{"type":"essay","q":"أعرب «خَشْيَةَ إملاقٍ» في قوله تعالى: ﴿وَلَا تَقْتُلُوا أَوْلَادَكُمْ خَشْيَةَ إِمْلَاقٍ﴾ إعرابًا تامًّا.","model":"خَشْيَةَ: مفعول لأجله منصوب وعلامة نصبه الفتحة الظاهرة على آخره وهو مضاف. إملاقٍ: مضاف إليه مجرور وعلامة جره الكسرة الظاهرة على آخره."},{"type":"tfr","q":"يجوز نصب كلمة «القراءة» مفعولًا لأجله في جملة: «ذهبتُ إلى المكتبةِ قراءةً».","answer":false,"reasons":["لأن «القراءة» ليست مصدرًا قلبيًّا بل عملٌ بالجوارح، فيجب جرّها باللام: للقراءةِ","لأن الفاعل مختلف بين الذهاب والقراءة","لأنها مضافة إلى المكتبة"],"reason":0},{"type":"mcq","q":"في أيِّ جملة مما يأتي جاء المفعول لأجله مضافًا؟","options":["أصومُ طاعةً لله","أسعى ابتغاءَ مرضاةِ الله","أجتهدُ للرغبةِ في التفوّقِ","أحترمُ الكبيرَ احترامًا"],"answer":1,"why":"«ابتغاءَ» مصدر قلبي منصوب بفتحة واحدة وأضيف إلى «مرضاةِ»."},{"type":"essay","q":"فرّق بين إعراب الكلمة المنصوبة في الجملتين: (١) اجتهدتُ اجتهادًا. (٢) اجتهدتُ طلبًا للنجاحِ.","model":"في (١) «اجتهادًا» مفعول مطلق منصوب لأنه مصدر من لفظ الفعل. وفي (٢) «طلبًا» مفعول لأجله منصوب لأنه مصدر قلبي من غير لفظ الفعل يبيّن سبب الاجتهاد."},{"type":"tfr","q":"في جملة «جئتُ لإكرامِكَ لي» يجب جرّ «إكرامِكَ» باللام لاختلاف الفاعل.","answer":true,"reasons":["لأن فاعل المجيء هو المتكلم وفاعل الإكرام هو المخاطب، فاختل شرط اتحاد الفاعل","لأن «إكرام» ليس مصدرًا","لأن الزمن مختلف بين المجيء والإكرام"],"reason":0},{"type":"mcq","q":"ما الحكم الإعرابي الغالب في المفعول لأجله المجرّد من «أل» والإضافة؟","options":["وجوب الجر بحرف الجر","استواء النصب والجر","غلبة النصب وجواز الجر","وجوب الرفع"],"answer":2,"why":"المجرّد من «أل» والإضافة يغلب فيه النصب مثل «رَغبةً»، ويجوز جره مثل «لرغبةٍ»."},{"type":"essay","q":"حوّل المفعول لأجله المجرّد إلى مضاف ثم إلى مقترن بأل في جملة: «أقرأُ الكتبَ رَغبةً في المعرفةِ».","model":"مضاف: «أقرأُ الكتبَ رَغبةَ المعرفةِ». مقترن بأل: «أقرأُ الكتبَ للرغبةِ في المعرفةِ» (أو «الرغبةَ في المعرفةِ»)."},{"type":"tfr","q":"تُعرب كلمة «حذرَ» في قوله تعالى: ﴿يَجْعَلُونَ أَصَابِعَهُمْ فِي آذَانِهِم مِّنَ الصَّوَاعِقِ حَذَرَ الْمَوْتِ﴾ مفعولًا لأجله منصوبًا.","answer":true,"reasons":["لأنها مصدر قلبي مضاف يبيّن سبب جعل أصابعهم في آذانهم، واتحدت مع الفعل في الزمن والفاعل","لأنها حال منصوبة تجيب عن كيف","لأنها مفعول به للفعل يجعلون"],"reason":0},{"type":"essay","q":"اذكر شروط نصب الاسم على أنه مفعول لأجله، ومثّل بجملة تامة من إنشائك.","model":"الشروط: أن يكون مصدرًا قلبيًّا، وأن يبيّن سبب وقوع الفعل (التعليل)، وأن يتحد مع الفعل في الزمن والفاعل. مثال: «أساعدُ المحتاجَ رَغبةً في الأجرِ»."}]}},
  {"id":"g9-arabic-1-u1-4","grade":"g9","subject":"arabic","term":1,"unit":1,"no":5,"title":"المعجم المختص","summary":"شرح متحرك لمفهوم المعجم المختص والفرق بينه وبين المعجم العام وأنواعه وطريقة البحث فيه، ثم أنشطة بثلاثة مستويات.","page":"lesson-specialized-dictionary.html","video":"","pdf":"","notes":["المعجم المختص (معجم المصطلحات): معجم يجمع مصطلحات علمٍ أو فنٍّ واحدٍ ويشرحها شرحًا علميًّا دقيقًا.","المعجم العام يجمع ألفاظ اللغة العامة كلها ويؤلّفه اللغويون لعموم الناس، مثل «المعجم الوسيط».","المعجم المختص يجمع مصطلحات مجال محدّد ويؤلّفه المختصون في ذلك العلم للدارسين والباحثين.","من أسباب نشأة المعاجم المختصة: اتّساع العلوم، وتوحيد المصطلح العلمي، والترجمة ومواكبة التطور.","من أمثلته: المعجم الطبي، ومعجم مصطلحات البلاغة، ومعجم ألفاظ القرآن، ومعجم الحاسوب.","تُرتَّب مادته غالبًا ترتيبًا ألفبائيًّا (حسب الحرف الأول للمصطلح) أو ترتيبًا موضوعيًّا."],"exercises":["قارن بين المعجم العام والمعجم المختص من حيث المادة والمؤلّف.","اذكر ثلاثة أمثلة لمعاجم مختصة في مجالات مختلفة.","ما الفرق بين شرح كلمة «الجزم» في المعجم العام وفي معجم النحو المختص؟"],"levels":{"easy":[{"type":"mcq","q":"ما الذي يجمعه المعجم المختص؟","options":["ألفاظ اللغة العامة كلها","مصطلحات علمٍ أو فنٍّ واحدٍ فقط","القصائد الشعرية فقط","أسماء المدن فقط"],"answer":1,"why":"المعجم المختص يقتصر على مصطلحات مجال علمي أو فني محدد ويشرحها بدقة."},{"type":"mcq","q":"أيٌّ مما يأتي يُعدّ مثالًا على المعجم العام؟","options":["المعجم الطبي","معجم الحاسوب","المعجم الوسيط","معجم مصطلحات الفقه"],"answer":2,"why":"المعجم الوسيط معجم لغوي عام يجمع ألفاظ اللغة العامة."},{"type":"mcq","q":"من الذي يؤلّف المعجم المختص غالبًا؟","options":["المختصّون في ذلك العلم أو الفن","طلاب الصف الأول","الشعراء فقط","أي قارئ عادي"],"answer":0,"why":"يؤلّف المعجم المختص علماء ومختصّون في التخصص نفسه لضمان الدقة العلمية."},{"type":"mcq","q":"ما الاسم الآخر الذي يُطلق على المعجم المختص؟","options":["معجم القوافي","معجم الألغاز","معجم القصص","معجم المصطلحات"],"answer":3,"why":"يُسمّى معجم المصطلحات لأنه يعتني بشرح المصطلحات العلمية والفنية."}],"medium":[{"type":"mcq","q":"إذا أردتَ معرفة التعريف العلمي الدقيق لمصطلح «التأكسد»، فأيّ معجمٍ تختار؟","options":["المعجم الوسيط","معجم مصطلحات الكيمياء","معجم البلاغة","لسان العرب"],"answer":1,"why":"«التأكسد» مصطلح كيميائي، لذا نجد تعريفه العلمي الدقيق في معجم مصطلحات الكيمياء."},{"type":"tfr","q":"تتجدّد مادة المعجم المختص باستمرار لمواكبة تطور العلوم والاكتشافات.","answer":true,"reasons":["لأن العلوم الحديثة تنتج مصطلحات ومفاهيم جديدة باستمرار","لأن المعجم المختص لا يتغير أبدًا","لأنه يحذف المصطلحات العلمية كل عام"],"reason":0},{"type":"essay","q":"اذكر فرقَين بين المعجم العام والمعجم المختص.","model":"١) المادة: العام يجمع ألفاظ اللغة كلها، والمختص يجمع مصطلحات علم واحد. ٢) المؤلّف: العام يؤلّفه اللغويون، والمختص يؤلّفه المختصون في ذلك العلم."},{"type":"tfr","q":"المعجم العام يُوجَّه إلى المتخصصين والباحثين في علمٍ واحدٍ فقط.","answer":false,"reasons":["لأن المعجم العام يُوجَّه إلى عموم القراء والطلاب في حياتهم اليومية","لأن المعجم العام لا يستخدمه أحد","لأن المعجم العام خاص بالأطباء فقط"],"reason":0},{"type":"mcq","q":"ما طريقتا الترتيب الأكثر شيوعًا في المعاجم المختصة؟","options":["الترتيب حسب طول الكلمة","الترتيب الألفبائي أو الموضوعي","الترتيب العشوائي","الترتيب حسب عدد النقاط"],"answer":1,"why":"تُرتَّب المعاجم المختصة ألفبائيًّا حسب الحرف الأول للمصطلح، أو موضوعيًّا حسب الأبواب."},{"type":"essay","q":"اذكر سببين من أسباب نشأة المعاجم المختصة وتطورها.","model":"اتّساع العلوم وتشعّبها، والحاجة إلى توحيد المصطلح العلمي، وحركة الترجمة ومواكبة الاكتشافات الحديثة."},{"type":"tfr","q":"تكتفي المعاجم المختصة الحديثة بذكر المصطلح باللغة العربية دون مقابله الأجنبي.","answer":false,"reasons":["لأن كثيرًا من المعاجم المختصة الحديثة تذكر المصطلح العربي ومعه مقابله باللغة الأجنبية لتسهيل البحث والترجمة","لأن اللغات الأجنبية لا تحتوي على مصطلحات","لأن المقابل الأجنبي يوضع في المعجم العام فقط"],"reason":0}],"hard":[{"type":"mcq","q":"ما معنى كلمة «الجزم» في معجم النحو المختص مقارنةً بالمعجم العام؟","options":["في كليهما تعني القطع فقط","في العام تعني القطع والبتّ، وفي النحو تعني حالة إعرابية للفعل المضارع","في النحو تعني رفع الفاعل","لا توجد كلمة الجزم في المعجم العام"],"answer":1,"why":"المعجم العام يعطي المعنى اللغوي (القطع)، بينما المختص يعطي المعنى الاصطلاحي الدقيق في علم النحو."},{"type":"essay","q":"لماذا لا يُغني المعجم اللغوي العام عن المعجم المختص للباحث في العلوم؟","model":"لأن المعجم العام يركّز على المعنى اللغوي العام للكلمات، أما الباحث فيحتاج إلى التعريف الاصطلاحي الدقيق والمتجدّد للمصطلحات في تخصصه، وهو ما يقدّمه المعجم المختص."},{"type":"tfr","q":"في الترتيب الألفبائي لبعض المعاجم المختصة نبحث عن المصطلح بحرفه الأول مباشرة دون الحاجة دائمًا للرد إلى الجذر الثلاثي.","answer":true,"reasons":["لأن ذلك يُسهّل على الدارسين والباحثين الوصول السريع إلى المصطلح كما يُنطق","لأن المصطلحات ليس لها حروف أولى","لأن الترتيب الألفبائي يبدأ من الحرف الأخير"],"reason":0},{"type":"mcq","q":"أيُّ معجمٍ مما يأتي ينتمي إلى المعاجم المختصة في العلوم الشرعية؟","options":["معجم ألفاظ القرآن الكريم","معجم الحاسوب","المعجم الوسيط","معجم الجغرافيا"],"answer":0,"why":"معجم ألفاظ القرآن الكريم يختص بألفاظ القرآن ودلالاتها، فهو معجم مختص في مجال شرعي."},{"type":"essay","q":"ما دور المعاجم المختصة في توحيد المصطلح العلمي العربي؟","model":"تضع تعريفًا دقيقًا وموحدًا لكل مصطلح علمي ومقابله الأجنبي، مما يمنع تضارب الترجمات ويساعد الباحثين العرب على التواصل العلمي الواضح."},{"type":"tfr","q":"الترتيب الموضوعي في المعجم المختص يعني جمع مصطلحات كل موضوعٍ معًا في بابٍ واحد.","answer":true,"reasons":["لأن المعجم يُقسَّم إلى موضوعات أو محاور، فتُجمع المصطلحات المتقاربة في باب واحد","لأن الموضوعي يعني الترتيب من الياء إلى الألف","لأن الموضوعي يحذف الشرح العلمي"],"reason":0},{"type":"mcq","q":"إذا أردتَ معرفة معنى «الاستعارة» بوصفها صورةً بيانيةً، فأيّ معجمٍ تراجع؟","options":["معجم الطب","معجم مصطلحات البلاغة والأدب","معجم الفيزياء","معجم الجيولوجيا"],"answer":1,"why":"الاستعارة مصطلح بلاغي، لذا يُرجع فيها إلى معجم مصطلحات البلاغة والأدب."},{"type":"essay","q":"صنّف المعاجم الآتية إلى (عام) و(مختص): لسان العرب، المعجم الطبي الموحّد، المعجم الوسيط، معجم مصطلحات الحاسوب.","model":"معاجم عامة: لسان العرب، المعجم الوسيط. معاجم مختصة: المعجم الطبي الموحّد، معجم مصطلحات الحاسوب."},{"type":"tfr","q":"مادة المعجم اللغوي العام أكثر ثباتًا واستقرارًا من مادة المعجم المختص.","answer":true,"reasons":["لأن الألفاظ اللغوية العامة مستقرة، أما المصطلحات العلمية فتتجدّد بسرعة مع تطور العلوم","لأن اللغة العامة تتغير كل أسبوع","لأن المعجم المختص لا يُضاف إليه شيء"],"reason":0},{"type":"essay","q":"اختر مجالًا علميًا تحبه، واقترح ثلاثة مصطلحات يمكن أن يضمّها معجمٌ مختصٌّ في هذا المجال.","model":"مثال في مجال الحاسوب: الخوارزمية، البرمجة، قاعدة البيانات. (وتُقبل أي ثلاثة مصطلحات صحيحة في أي مجال علمي أو أدبي)."}]}},
  {"id":"g9-arabic-1-u2-1","grade":"g9","subject":"arabic","term":1,"unit":2,"no":1,"title":"الأدب في عصر اليعاربة","summary":"شرح متحرك للنهضة العلمية والأدبية في عهد اليعاربة وأغراض الشعر والنثر وخصائصهما، ثم أنشطة بثلاثة مستويات.","page":"lesson-yaariba-literature.html","video":"","pdf":"","notes":["قامت دولة اليعاربة عام ١٦٢٤م بمبايعة الإمام ناصر بن مرشد، فوحّد عُمان وحرّر موانئها من البرتغاليين.","أدّى الأمن والاستقرار إلى نهضة علمية وأدبية في نزوى والرستاق وصحار وغيرها.","كانت العلاقة بين الأئمة والعلماء والأدباء وثيقةً وتكامليةً، وكان بعض الأئمة علماء وأدباء.","من أبرز أغراض الشعر: الحماسة والبطولة وتسجيل الانتصارات، والمديح، والزهد والوعظ، والوصف، والرثاء.","تميّز شعر اليعاربة بجزالة الألفاظ وجمال الصور والتشبيهات والمحسنات كالطباق.","ازدهر النثر في الرسائل الديوانية، وخطب الجهاد، وفن النصائح للأئمة، ومؤلفات الفقه والتاريخ واللغة."],"exercises":["ما أثر قيام دولة اليعاربة واستقرار عُمان في الحركة العلمية والأدبية؟","اذكر ثلاثة أغراض شعرية ازدهرت في عصر اليعاربة.","بيّن جمال التصوير في: «وليلةِ سعدٍ مزّقَ السيفُ ثوبَها / كأنّ دُجاها بالسيوفِ نهارُ»."],"levels":{"easy":[{"type":"mcq","q":"من مؤسّس دولة اليعاربة في عُمان عام ١٦٢٤م؟","options":["الإمام ناصر بن مرشد","الجاحظ","البوصيري","الخليل بن أحمد"],"answer":0,"why":"بويع الإمام ناصر بن مرشد فوحّد عُمان وطهّر سواحلها من البرتغاليين."},{"type":"mcq","q":"ضدّ مَن خاض العُمانيون معارك التحرير البحرية في عصر اليعاربة؟","options":["الروم","البرتغاليين","المغول","الفرس"],"answer":1,"why":"حرّر اليعاربة السواحل والموانئ العُمانية من الاحتلال البرتغالي."},{"type":"mcq","q":"أيٌّ مما يأتي من أغراض الشعر التي ازدهرت في عصر اليعاربة؟","options":["الحماسة والبطولة","المسرحية الحديثة","الرواية الخيالية","المقالة الصحفية"],"answer":0,"why":"واكب شعر الحماسة والبطولة انتصارات العُمانيين ومعارك التحرير."},{"type":"mcq","q":"ما العلاقة بين «دُجاها» و«نهارُ» في البيت الشعري؟","options":["ترادف","طباق","سجع","توكيد"],"answer":1,"why":"الدجى هو الظلام، وبينه وبين النهار طباق يوضح شدة لمعان السيوف."}],"medium":[{"type":"mcq","q":"كيف كانت علاقة أئمة اليعاربة بالعلماء والأدباء؟","options":["علاقة تنافر وقطيعة","علاقة وثيقة تقوم على الرعاية والتكامل","لم يهتموا بالعلم","اقتصرت على التجارة"],"answer":1,"why":"قرّب الأئمة العلماء واستشاروهم، وكان بعض الأئمة أنفسهم علماء وأدباء."},{"type":"tfr","q":"اقتصر الشعر في عصر اليعاربة على شعر الحماسة والقتال فقط.","answer":false,"reasons":["لأنه تنوّع فشمل المديح والزهد والوعظ والوصف والرثاء إلى جانب الحماسة","لأن الشعر لم يوجد في عصر اليعاربة أصلًا","لأنه اقتصر على شعر الهجاء فقط"],"reason":0},{"type":"essay","q":"اذكر ثلاثة فنون نثرية ازدهرت في عصر اليعاربة.","model":"الرسائل الديوانية، وخطب الجهاد والوعظ، وفن النصائح للأئمة، والتأليف في الفقه والتاريخ واللغة."},{"type":"tfr","q":"كان بعض أئمة اليعاربة علماء وأدباء وشعراء متمكّنين.","answer":true,"reasons":["لأن بيئة العلم والأدب كانت راسخة في دولة اليعاربة، فجمع كثير من الأئمة بين الحكم والعلم","لأن الأئمة منعوا الشعر في عهدهم","لأنهم لم يتعلموا القراءة"],"reason":0},{"type":"mcq","q":"ما السمة اللغوية البارزة في شعر عصر اليعاربة؟","options":["استخدام الألفاظ العامية","جزالة الألفاظ وقوة التراكيب والصور البليغة","الاختصار المخلّ","الابتعاد عن التراث"],"answer":1,"why":"تميّز أدب اليعاربة بجزالة الألفاظ وقوة الأسلوب وجمال التصوير."},{"type":"essay","q":"اشرح الصورة الفنية في قول الشاعر: «مزّقَ السيفُ ثوبَها».","model":"شبّه الشاعر ظلام الليل بثوبٍ أسود يمزّقه بريق السيوف، مما يوحي بقوة المعركة وبسالة المقاتلين."},{"type":"tfr","q":"نشطت حلقات العلم في مدن عُمانية مثل نزوى والرستاق وصحار في عصر اليعاربة.","answer":true,"reasons":["لأن الأمن والاستقرار ورعاية الأئمة شجّعت المدارس وحلقات العلم في مختلف المدن العُمانية","لأن التعليم كان ممنوعًا في نزوى","لأن الرستاق لم تكن موجودة في ذلك العصر"],"reason":0}],"hard":[{"type":"mcq","q":"ما الدور التاريخي الذي أدّاه شعر البطولة في عصر اليعاربة؟","options":["التسلية فقط","توثيق معارك التحرير وبثّ الحماس والفخر الوطني","نقد اللغة العربية","وصف الأسواق فقط"],"answer":1,"why":"صار شعر البطولة سجلًا حيًا للانتصارات وحافزًا لرفع المعنويات."},{"type":"essay","q":"علّل: لماذا شهد عصر اليعاربة ازدهارًا كبيرًا في الأدب والعلم معًا؟","model":"بسبب توحيد عُمان وتحرير سواحلها مما حقّق الأمن والاستقرار، وبسبب رعاية الأئمة للعلماء والأدباء وتقريبهم وتشجيعهم."},{"type":"tfr","q":"يُعدّ فن «النصائح للأئمة» من أبرز الفنون النثرية التي ظهرت في عصر اليعاربة.","answer":true,"reasons":["لأن العلماء كانوا يوجّهون رسائل نصح صادقة للأئمة للحثّ على العدل والشورى والإصلاح","لأنه فن شعري يقتصر على الغزل","لأنه ظهر في القرن العشرين فقط"],"reason":0},{"type":"mcq","q":"ما أثر استخدام التشبيه «كأنّ دُجاها بالسيوفِ نهارُ» في المعنى؟","options":["يقلّل من شأن المعركة","يبرز كثرة السيوف ولمعانها حتى كأنها أضاءت ظلام الليل","يدلّ على هدوء الليل وسكونه","يعني أن المعركة توقّفت"],"answer":1,"why":"التشبيه يصور شدة بريق السيوف في المعركة حتى حولت الليل كأنه نهار."},{"type":"essay","q":"قارن بين موضوعات الشعر وموضوعات النثر في عصر اليعاربة.","model":"تناول الشعر الحماسة والانتصارات والمدح والزهد والوصف والرثاء، بينما تناول النثر الرسائل الديوانية وخطب الجهاد والنصائح للأئمة والمؤلفات الفقهية والتاريخية واللغوية."},{"type":"tfr","q":"انفصل الأدب في عصر اليعاربة عن قضايا المجتمع والوطن والدين.","answer":false,"reasons":["لأن الأدب اليعربي كان وثيق الصلة بقضايا التحرير والوطن والدين والإصلاح","لأن الأدباء لم يكتبوا عن عُمان أبدًا","لأن النثر كان باللغة الأجنبية"],"reason":0},{"type":"mcq","q":"أيُّ الفنون الآتية يدلّ على النهضة العلمية في عصر اليعاربة؟","options":["المصنّفات والموسوعات في الفقه والتاريخ واللغة","الرسوم المتحركة","المقالات الإلكترونية","القصص البوليسية"],"answer":0,"why":"أُلّفت في عصر اليعاربة كتب وموسوعات علمية ما زالت مراجع حتى اليوم."},{"type":"essay","q":"اذكر ثلاث خصائص فنية للأدب في عصر اليعاربة.","model":"١) الارتباط بقضايا الوطن والدين. ٢) جزالة الألفاظ وقوة التراكيب. ٣) العناية بالصور البلاغية والتشبيهات والمحسنات البديعية."},{"type":"tfr","q":"تُظهر العلاقة بين الأئمة والعلماء في عصر اليعاربة احترامًا متبادلًا ومشاركةً في النصح والشورى.","answer":true,"reasons":["لأن الأئمة قرّبوا العلماء واستشاروهم وتقبّلوا نصائحهم لإقامة العدل","لأن العلماء ابتعدوا عن المجتمع","لأن الأئمة لم يستشيروا أحدًا"],"reason":0},{"type":"essay","q":"في رأيك، كيف يمكن للأدب والشعر اليوم أن يؤدّيا دورًا وطنيًا مشابهًا لدورهما في عصر اليعاربة؟","model":"من خلال توثيق إنجازات الوطن، وتعزيز القيم والأخلاق والانتماء، وإبراز الهوية والتراث العُماني بلغة عربية فصيحة ومؤثرة."}]}},
  {"id":"g9-arabic-1-u2-2","grade":"g9","subject":"arabic","term":1,"unit":2,"no":4,"title":"التعبير: تصميم موضوع","summary":"شرح متحرك لخطوات تصميم الموضوع وعناصره الثلاثة (المقدمة والجوهر والخاتمة) بمثال تطبيقي، ثم أنشطة بثلاثة مستويات.","page":"lesson-topic-design.html","video":"","pdf":"","notes":["تصميم الموضوع: وضع خطّة منظّمة للأفكار والعناصر قبل البدء بكتابة النص الكامل.","نبدأ بقراءة رأس الموضوع بدقّة وتحديد الفكرة العامة حتى لا نخرج عن الموضوع.","يتكوّن تصميم الموضوع من ثلاثة أقسام: المقدّمة، والجوهر (العرض)، والخاتمة.","المقدّمة موجزة تمهّد للموضوع وتجذب انتباه القارئ دون الدخول في التفاصيل.","الجوهر هو القسم الأكبر، ويضمّ أفكارًا فرعية متسلسلة، تُدعَّم بالأمثلة والأدلة والشواهد.","الخاتمة موجزة وقد تأتي تلخيصًا لما كُتب، أو رأيًا شخصيًا وتوصية، أو سؤالًا للتفكير."],"exercises":["اذكر الأقسام الثلاثة الرئيسة لتصميم أي موضوع تعبير.","صمّم ثلاث أفكار فرعية لموضوع عن «المحافظة على البيئة العُمانية».","اكتب خاتمة مناسبة لموضوع عن «أهمية القراءة»."],"levels":{"easy":[{"type":"mcq","q":"ما المقصود بتصميم الموضوع في التعبير؟","options":["تلوين الصفحة فقط","وضع خطّة منظّمة للأفكار قبل الكتابة","نسخ نص من كتاب","كتابة جملة واحدة"],"answer":1,"why":"التصميم هو التخطيط المسبق لترتيب الأفكار قبل كتابة الموضوع الكامل."},{"type":"mcq","q":"ما القسم الأكبر في موضوع التعبير؟","options":["العنوان","المقدّمة","الجوهر (العرض)","الخاتمة"],"answer":2,"why":"الجوهر يضمّ الأفكار الفرعية وتفاصيلها والأمثلة والشواهد."},{"type":"mcq","q":"ما أول خطوة نبدأ بها عند تصميم موضوع؟","options":["كتابة الخاتمة","تحديد الفكرة العامة","حذف المقدّمة","إضافة الصور"],"answer":1,"why":"تحديد الفكرة العامة يضبط كل الفقرات ويمنع الخروج عن الموضوع."},{"type":"mcq","q":"بماذا نقوّي الأفكار الفرعية داخل الجوهر؟","options":["بالتكرار الممل","بالأمثلة والأدلة والشواهد","بتجاهل الترقيم","بالخروج عن الموضوع"],"answer":1,"why":"الشواهد كالآيات والأحاديث والأمثلة الواقعية تجعل الموضوع مقنعًا."}],"medium":[{"type":"mcq","q":"أيٌّ مما يأتي يُعدّ من خصائص المقدّمة الجيّدة؟","options":["أن تكون أطول من الجوهر","أن تمهّد للموضوع بإيجاز وتجذب القارئ","أن تحتوي على كل التفاصيل","أن تُكتب في آخر الصفحة"],"answer":1,"why":"المقدّمة بوابة موجزة وجذّابة تمهّد للموضوع دون حشو."},{"type":"tfr","q":"يُخصَّص لكل فكرة فرعية في الجوهر فقرةٌ مستقلةٌ وواضحة.","answer":true,"reasons":["لأن تخصيص فقرة لكل فكرة فرعية يمنع التداخل ويجعل الموضوع منظّمًا وسهل القراءة","لأن الموضوع كله يجب أن يكون فقرة واحدة بلا فواصل","لأن الأفكار الفرعية توضع في العنوان فقط"],"reason":0},{"type":"essay","q":"اذكر صورتين يمكن أن تأتي عليهما خاتمة الموضوع.","model":"يمكن أن تكون الخاتمة تلخيصًا موجزًا لأهم الأفكار، أو إبداء رأي شخصي وتوصية، أو طرح تساؤل للتفكير."},{"type":"tfr","q":"يجب أن تتقيّد الخاتمة بشكلٍ واحدٍ ثابتٍ وهو التلخيص فقط.","answer":false,"reasons":["لأن الخاتمة تتنوّع بين التلخيص، وإبداء الرأي والتوصية، وطرح التساؤلات","لأن الموضوع لا يحتاج إلى خاتمة أبدًا","لأن الخاتمة تُكتب قبل المقدّمة"],"reason":0},{"type":"mcq","q":"أيٌّ مما يأتي يُعدّ خطأً شائعًا يضعف تصميم الموضوع؟","options":["ترتيب الأفكار منطقيًا","تكرار نفس الفكرة في أكثر من فقرة","استخدام علامات الترقيم","الاستشهاد بآية مناسبة"],"answer":1,"why":"تكرار الأفكار يضعف الموضوع ويُظهر غياب التخطيط الجيّد."},{"type":"essay","q":"اقترح شاهدًا مناسبًا لموضوع عن «أهمية القراءة».","model":"قوله تعالى: ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ﴾ (أو أي حديث أو حكمة صحيحة تحثّ على القراءة والعلم)."},{"type":"tfr","q":"تساعد الروابط اللغوية وعلامات الترقيم على تماسك فقرات الموضوع.","answer":true,"reasons":["لأنها تربط بين الجمل والفقرات وتوضّح المعنى للقارئ","لأنها تُطيل الموضوع بلا فائدة","لأنها تُستخدم في المقدّمة فقط"],"reason":0}],"hard":[{"type":"mcq","q":"لماذا شُبّه تصميم الموضوع بالمخطّط الهندسي قبل البناء؟","options":["لأن كليهما يحتاج إلى أدوات هندسية","لأن التخطيط المسبق يضمن الترتيب والتماسك ويمنع التشتّت والتكرار","لأن الكتابة أصعب من البناء","لأن المخطّط يُلغي الحاجة للكتابة"],"answer":1,"why":"مثلما يضبط المخطّط شكل البناء، يضبط التصميم تسلسل الأفكار وتوازنها."},{"type":"essay","q":"صمّم مخطّطًا موجزًا (فكرة عامة + ٣ أفكار فرعية) لموضوع عن «تنظيم الوقت للطالب».","model":"الفكرة العامة: أثر تنظيم الوقت في تفوّق الطالب وراحته. الأفكار الفرعية: ١) مفهوم تنظيم الوقت وأهميته. ٢) خطوات إعداد جدول يومي متوازن. ٣) أثر تنظيم الوقت في النجاح الدراسي والحياة."},{"type":"tfr","q":"إدخال تفاصيل وشواهد الجوهر داخل المقدّمة يجعل الموضوع أكثر إيجازًا وتنظيمًا.","answer":false,"reasons":["لأن المقدّمة للتمهيد الموجز فقط، أما التفاصيل والشواهد فموضعها الجوهر","لأن الجوهر لا يحتوي على شواهد","لأن المقدّمة يجب أن تكون نصف الموضوع"],"reason":0},{"type":"mcq","q":"عند مراجعة تصميم موضوعك قبل الكتابة، ما السؤال الأهم الذي تطرحه على نفسك؟","options":["هل كل فكرة فرعية مرتبطة بالفكرة العامة ومرتّبة منطقيًا؟","هل خطّي جميل فقط؟","هل نسختُ مقدّمة محفوظة لا علاقة لها بالموضوع؟","هل حذفتُ كل الشواهد؟"],"answer":0,"why":"التأكد من ارتباط الأفكار الفرعية بالفكرة العامة يمنع الخروج عن الموضوع."},{"type":"essay","q":"اكتب مقدّمة جذّابة من جملتين لموضوع عن «العمل التطوّعي في المدرسة».","model":"مثال: العمل التطوّعي بذرة خيرٍ تثمر تعاونًا ومحبةً في المجتمع المدرسي. فكيف يبني التطوّع شخصية الطالب ويخدم وطنه؟"},{"type":"tfr","q":"الشاهد المختار يجب أن يرتبط ارتباطًا وثيقًا بالفكرة التي يدعمها.","answer":true,"reasons":["لأن الشاهد غير المناسب يشتّت القارئ ولا يخدم الإقناع","لأن أي آية أو بيت شعر يصلح لأي موضوع","لأن الشواهد لا علاقة لها بالأفكار"],"reason":0},{"type":"mcq","q":"أيُّ جملة مما يأتي تصلح خاتمةً لموضوع عن «أهمية القراءة»؟","options":["القراءة هي عملية فكّ الرموز المكتوبة.","فلنجعل الكتاب رفيقنا اليومي؛ لأن قارئ اليوم هو قائد الغد.","أولًا سنتحدث عن أنواع الكتب.","في المكتبة أرفف كثيرة."],"answer":1,"why":"تتضمّن توصيةً موجزةً وعبارةً مؤثّرةً تلخّص قيمة القراءة."},{"type":"essay","q":"ما الفرق بين «الفكرة العامة» و«الأفكار الفرعية» في تصميم الموضوع؟","model":"الفكرة العامة هي المحور الشامل الذي يدور حوله الموضوع كله، أما الأفكار الفرعية فهي الأجزاء المتفرّعة عنها والتي تُناقش في فقرات الجوهر."},{"type":"tfr","q":"تُعدّ المراجعة الأخيرة بعد الكتابة جزءًا مهمًا للتأكد من تسلسل الأفكار وسلامة اللغة.","answer":true,"reasons":["لأنها تكشف الأخطاء الإملائية والنحوية والتكرار وتضمن التزام النص بالتصميم","لأن المراجعة تُضيّع الوقت بلا فائدة","لأن الكاتب لا يخطئ أبدًا"],"reason":0},{"type":"essay","q":"اكتب خطوات تصميم الموضوع بالترتيب من البداية حتى النهاية.","model":"١) قراءة رأس الموضوع وتحديد الفكرة العامة. ٢) تصميم مقدّمة موجزة وجذّابة. ٣) تفريع أفكار الجوهر وتدعيمها بالأمثلة والشواهد. ٤) إعداد خاتمة مناسبة. ٥) الكتابة ثم المراجعة."}]}},
  {"id":"g9-arabic-1-u2-3","grade":"g9","subject":"arabic","term":1,"unit":2,"no":5,"title":"عُمان جوهرة جزيرة العرب","summary":"شرح متحرك لمقوّمات جمال عُمان وموقعها وتاريخها البحري وتراثها المعماري ومهارات الاستماع الواعي، ثم أنشطة بثلاثة مستويات.","page":"lesson-oman-jewel.html","video":"","pdf":"","notes":["تقع سلطنة عُمان في الركن الجنوبي الشرقي من شبه الجزيرة العربية وتطلّ على بحر عُمان وبحر العرب ومضيق هرمز.","تتميّز عُمان بتنوّع طبيعي فريد: جبال شاهقة (الجبل الأخضر وجبل شمس)، وشواطئ رملية، وصحارٍ ذهبية، وخريف ظفار.","نظام «الأفلاج» العُماني قنوات مائية هندسية عريقة أُدرج عددٌ منها في قائمة التراث العالمي لليونسكو.","اشتهر العُمانيون بالملاحة وبناء السفن والتجارة مع شرق إفريقيا والهند والصين ونشر القيم والأخلاق.","تزخر عُمان بالقلاع والحصون التاريخية مثل قلعة نزوى وحصن جبرين، كما يُعرف أهلها بكرم الضيافة والتسامح.","من مهارات الاستماع الواعي: الإنصات بهدوء، والتقاط الفكرة العامة، وتدوين التفاصيل، وتلخيص المسموع."],"exercises":["لماذا لُقّبت سلطنة عُمان بجوهرة جزيرة العرب؟","اذكر مظهرين من مظاهر التنوع الطبيعي في عُمان.","ما الخطوات الأربع لإتقان مهارة الاستماع الواعي؟"],"levels":{"easy":[{"type":"mcq","q":"أين تقع سلطنة عُمان في شبه الجزيرة العربية؟","options":["الشمال الغربي","الجنوب الشرقي","الشمال الشرقي","الوسط"],"answer":1,"why":"تقع عُمان في الركن الجنوبي الشرقي من شبه الجزيرة العربية."},{"type":"mcq","q":"ما النظام المائي العُماني العريق لريّ الواحات والمزارع؟","options":["الأفلاج","الأنهار الجليدية","البحيرات الصناعية","الأنفاق"],"answer":0,"why":"الأفلاج قنوات مائية هندسية دقيقة أُدرج عدد منها في التراث العالمي."},{"type":"mcq","q":"أيُّ محافظة عُمانية تشتهر بموسم الخريف الأخضر والشلالات؟","options":["مسندم","ظفار","البريمي","الوسطى"],"answer":1,"why":"تزدان محافظة ظفار في الجنوب بخريفها الأخضر الساحر وضبابها المنعش."},{"type":"mcq","q":"ما الخطوة الأولى في مهارة الاستماع الواعي؟","options":["المقاطعة","الإنصات والتركيز","الانشغال بالهاتف","تجاهل المتحدّث"],"answer":1,"why":"الإنصات بهدوء وتركيز هو أساس فهم النص المسموع."}],"medium":[{"type":"mcq","q":"أيُّ المسطحات المائية الآتية تُشرف عليها سلطنة عُمان؟","options":["البحر المتوسط","بحر عُمان وبحر العرب","البحر الأسود","المحيط الأطلسي"],"answer":1,"why":"تطلّ عُمان على بحر عُمان وبحر العرب والمحيط الهندي ومضيق هرمز."},{"type":"tfr","q":"اقتصرت وظيفة القلاع والحصون العُمانية قديمًا على الدفاع العسكري فقط.","answer":false,"reasons":["لأنها كانت أيضًا مراكز للعلم والقضاء وإدارة شؤون المجتمع إلى جانب الحماية","لأن عُمان لا توجد فيها قلاع وحصون","لأنها كانت مخصّصة للتجارة البحرية فقط"],"reason":0},{"type":"essay","q":"اذكر مثالين على المعالم الجبلية ومثالين على القلاع والحصون في عُمان.","model":"الجبال: الجبل الأخضر، وجبل شمس. القلاع والحصون: قلعة نزوى، وحصن جبرين."},{"type":"tfr","q":"أبحر العُمانيون بسفنهم التقليدية إلى شرق إفريقيا والهند والصين للتجارة والتواصل الحضاري.","answer":true,"reasons":["لأن موقع عُمان البحري ومهارة أهلها في الملاحة وبناء السفن جعلتها جسرًا تجاريًا وحضاريًا","لأن العُمانيين لم يعرفوا ركوب البحر","لأن تجارتهم اقتصرت على اليابسة فقط"],"reason":0},{"type":"mcq","q":"بماذا يُرحّب الإنسان العُماني بضيوفه تعبيرًا عن كرم الضيافة؟","options":["بالقهوة العُمانية والتمر والحلوى","بإغلاق الباب","بالسكوت","بترك الضيف وحده"],"answer":0,"why":"القهوة العُمانية والتمر والحلوى رمز أصيل لكرم الضيافة العُمانية."},{"type":"essay","q":"ما القيم الإنسانية التي تعكسها «الأفلاج» في المجتمع العُماني؟","model":"تعكس روح التعاون والتكافل والعدالة في توزيع المياه، إلى جانب الإبداع والابتكار الهندسي."},{"type":"tfr","q":"تدوين الكلمات المفتاحية أثناء الاستماع يساعد على تذكّر التفاصيل وتلخيص النص.","answer":true,"reasons":["لأن تدوين الأسماء والأماكن والأفكار الرئيسة يثبّت المعلومات ويسهّل استرجاعها","لأن التدوين يمنع الفهم تمامًا","لأن الاستماع لا يحتاج إلى تركيز"],"reason":0}],"hard":[{"type":"mcq","q":"ما الدور الحضاري الذي أدّاه البحّارة والتجار العُمانيون في أسفارهم؟","options":["نقل البضائع فقط دون أي تواصل","نشر القيم الإسلامية واللغة العربية بأخلاقهم وصدق تعاملهم","الانغلاق على أنفسهم","هدم الموانئ"],"answer":1,"why":"كان التجار العُمانيون سفراء للقيم الإسلامية والأمانة والتسامح في آسيا وشرق إفريقيا."},{"type":"essay","q":"اشرح كيف أسهم الموقع الجغرافي لعُمان في ازدهارها التاريخي والتجاري.","model":"موقعها في الجنوب الشرقي من شبه الجزيرة العربية وإشرافها على بحر عُمان وبحر العرب ومضيق هرمز جعل موانئها حلقة وصل تجارية وحضارية بين الشرق والغرب."},{"type":"tfr","q":"الجمع بين الأصالة والهوية الوطنية وبين الانفتاح والتسامح من أبرز سمات الإنسان العُماني.","answer":true,"reasons":["لأن العُمانيين يحافظون على تراثهم وقيمهم الأصيلة مع ترحيبهم وتعايشهم السلمي مع الآخرين","لأن الانفتاح يعني التخلي عن الهوية","لأن الأصالة تمنع التسامح"],"reason":0},{"type":"mcq","q":"أيُّ العوامل الآتية جعلت عُمان وجهةً سياحيةً متميّزةً عالميًا؟","options":["تشابه تضاريسها في كل مكان","تنوّع الطبيعة والتراث المعماري وكرم الضيافة والأمان","عدم وجود شواطئ فيها","قلة تاريخها"],"answer":1,"why":"تجمع عُمان بين الجبال والشواطئ والصحاري والقلاع والأمان وكرم أهلها."},{"type":"essay","q":"ما الفرق بين «السماع» العابر و«الاستماع الواعي»؟","model":"السماع العابر التقاط للأصوات دون تركيز مقصود، أما الاستماع الواعي فمهارة مقصودة تقوم على الإنصات والتركيز والتقاط الأفكار والتفاصيل وتلخيصها."},{"type":"tfr","q":"أُدرج عددٌ من الأفلاج العُمانية ضمن قائمة التراث العالمي لليونسكو لقيمتها الهندسية والتاريخية.","answer":true,"reasons":["لأنها تمثّل إبداعًا هندسيًا عريقًا ونظامًا اجتماعيًا فريدًا لإدارة المياه","لأنها بُنيت في العام الماضي فقط","لأنها تُستخدم في الملاحة البحرية"],"reason":0},{"type":"mcq","q":"بماذا تشتهر قلعة نزوى المعمارية؟","options":["ببرجها الدائري الضخم ومكانتها التاريخية","بكونها سفينة بحرية","بكونها جبلًا بركانيًا","بوقوعها وسط البحر"],"answer":0,"why":"تشتهر قلعة نزوى ببرجها الدائري الضخم وتاريخها العريق في عصر اليعاربة."},{"type":"essay","q":"لخّص في ثلاث جمل لماذا تستحق عُمان لقب «جوهرة جزيرة العرب».","model":"تستحق عُمان هذا اللقب لموقعها الاستراتيجي وتنوّع طبيعتها بين الجبال والشواطئ والصحاري وخريف ظفار، ولتاريخها البحري والمعماري العريق، وقبل كل ذلك لأخلاق أهلها في الكرم والتسامح."},{"type":"tfr","q":"مضيق هرمز الذي تشرف عليه عُمان يُعدّ من أهم الممرات المائية في العالم.","answer":true,"reasons":["لأنه يربط الخليج العربي ببحر عُمان والمحيط الهندي ويمثّل شريانًا تجاريًا عالميًا","لأنه نهر داخلي صغير","لأنه لا تمرّ به السفن"],"reason":0},{"type":"essay","q":"اقترح طريقتين يمكن لطالب الصف التاسع أن يُسهم بهما في الحفاظ على جمال عُمان وتراثها.","model":"الحفاظ على نظافة الشواطئ والمعالم السياحية، والتعريف بالتراث العُماني والأفلاج والقلاع بإيجابية واعتزاز."}]}},
  {"id":"g9-arabic-1-u2-4","grade":"g9","subject":"arabic","term":1,"unit":2,"no":6,"title":"من نصيحة الشيخ الخراسيني لأحد أئمة اليعاربة","summary":"شرح متحرك لرسالة الشيخ سعيد بن أحمد الخراسيني إلى الإمام ناصر بن مرشد ووصاياها وآداب النصح وأسلوبها، ثم أنشطة بثلاثة مستويات.","page":"lesson-khurasini-advice.html","video":"","pdf":"","notes":["صاحب النصيحة هو الشيخ العالم سعيد بن أحمد الخراسيني، ووجّهها إلى الإمام ناصر بن مرشد اليعربي.","أبرز وصايا الرسالة: تقوى الله ومراقبته في السر والعلن، وإقامة العدل بين القوي والضعيف.","دعت النصيحة إلى الرحمة والرفق بالرعية وتفقّد الضعفاء والمظلومين وعدم الاحتجاب عن أصحاب الحاجات.","أكّدت على مبدأ «الشورى» والاستعانة بأهل العلم والحكمة، وحسن اختيار الولاة الأمناء ومحاسبتهم.","حذّرت من البطانة السيئة والمتملّقين وذوي الأطماع الذين يخفون الحقائق.","يتميّز أسلوب الشيخ الخراسيني بالجمع بين الصدق واللطف والأدب، والتأثّر بالقرآن والسنة، وتوظيف الأمر والنهي للنصح والإرشاد."],"exercises":["من كاتب النصيحة، وإلى من وجّهها؟","اذكر أربع وصايا رئيسة تضمّنتها رسالة الشيخ الخراسيني.","ما الدروس التي نتعلّمها من أسلوب الشيخ الخراسيني في آداب النصيحة؟"],"levels":{"easy":[{"type":"mcq","q":"من كاتب رسالة النصيحة في هذا الدرس؟","options":["الجاحظ","الشيخ سعيد بن أحمد الخراسيني","البوصيري","سيبويه"],"answer":1,"why":"كاتب النصيحة هو الشيخ العالم سعيد بن أحمد الخراسيني."},{"type":"mcq","q":"إلى من وجّه الشيخ الخراسيني نصيحته؟","options":["الإمام ناصر بن مرشد","المتنبي","أبو تمام","الخليل بن أحمد"],"answer":0,"why":"وجّهها إلى الإمام ناصر بن مرشد مؤسّس دولة اليعاربة."},{"type":"mcq","q":"ما المبدأ الذي دعا إليه الشيخ للاستعانة بأهل العلم والحكمة؟","options":["الاستبداد","الشورى","التسرّع","العزلة"],"answer":1,"why":"دعا إلى التمسّك بمبدأ الشورى في القرارات المهمة."},{"type":"mcq","q":"ما أساس استقرار الدولة كما أكّد الشيخ الخراسيني؟","options":["العدل وتقوى الله","إهمال الضعفاء","تقريب المتملّقين","الاحتجاب عن الناس"],"answer":0,"why":"العدل ومراقبة الله في السر والعلن أساس استقرار البلاد."}],"medium":[{"type":"mcq","q":"ممّن حذّر الشيخ الخراسيني الإمام في نصيحته؟","options":["أهل العلم والخبرة","المتملّقين وذوي الأطماع","المظلومين","القضاة العادلين"],"answer":1,"why":"حذّره من البطانة السيئة التي تزيّن الباطل وتخفي الحقائق."},{"type":"tfr","q":"كانت نصيحة الشيخ الخراسيني انتقاصًا من الإمام ناصر بن مرشد.","answer":false,"reasons":["لأنها كانت تعاونًا صادقًا على البرّ والتقوى وتثبيتًا لأركان العدل في الدولة","لأن الشيخ لم يكتب رسالة أصلًا","لأن النصيحة ممنوعة في الإسلام"],"reason":0},{"type":"essay","q":"لماذا أوصى الشيخ الخراسيني الإمام بألّا يجعل بينه وبين رعيته حجابًا؟","model":"حتى يتمكّن الضعفاء وأصحاب الحاجات والمظلومون من الوصول إليه وإيصال شكواهم فينصفهم."},{"type":"tfr","q":"جمع الشيخ الخراسيني في نصيحته بين الجرأة في قول الحقّ واللطف والأدب في الخطاب.","answer":true,"reasons":["لأن النصيحة المؤثّرة تحتاج إلى إخلاص وصدق مع لين العبارة وحسن التوقير","لأن النصيحة لا تكون إلا بالشدة والغلظة","لأنه أخفى الحقائق عن الإمام"],"reason":0},{"type":"mcq","q":"ما الغرض البلاغي من أساليب الأمر والنهي في رسالة الشيخ الخراسيني؟","options":["التعجيز","السخرية","النصح والإرشاد","التمنّي"],"answer":2,"why":"جاءت أساليب الأمر والنهي بدافع المحبّة والإخلاص للنصح والإرشاد."},{"type":"essay","q":"اذكر اثنتين من سمات أسلوب الشيخ الخراسيني في الرسالة.","model":"وضوح الألفاظ وصدق العاطفة، والتأثّر بالقرآن الكريم والسنة النبوية، وتوظيف أساليب الأمر والنهي للنصح والإرشاد."},{"type":"tfr","q":"يكفي أن يكون الحاكم عادلًا وحده دون حاجة إلى متابعة ولاته وعمّاله.","answer":false,"reasons":["لأن الولاة ينفّذون الأحكام في المدن، فلا بدّ من حسن اختيارهم ومحاسبتهم حتى لا يظلموا الرعية","لأن الولاة لا يعملون في الدولة","لأن المحاسبة غير ضرورية"],"reason":0}],"hard":[{"type":"mcq","q":"على ماذا يدلّ توجيه الشيخ الخراسيني هذه النصيحة الصريحة للإمام وتقبّلها؟","options":["على ضعف الدولة","على مكانة العلماء وحرية الكلمة المسؤولة وعدل الأئمة في عصر اليعاربة","على غياب القوانين","على خصومة شخصية"],"answer":1,"why":"يعكس ذلك رقيّ العلاقة بين العلماء والحكام وتعاونهم على الحقّ."},{"type":"essay","q":"بيّن أثر تطبيق مبدأ «الشورى» في إدارة شؤون الدولة والمجتمع.","model":"الشورى تمنع الاستبداد، وتكشف الصواب عبر الاستفادة من عقول أهل العلم والخبرة، وتجمع الكلمة حول المصلحة العامة."},{"type":"tfr","q":"تأثّر الشيخ الخراسيني في عباراته ومعانيه بالقرآن الكريم والحديث النبوي الشريف.","answer":true,"reasons":["لأن مرجعيته علمية شرعية، فجاءت وصاياه بالعدل والشورى والرحمة مستمدّة من قيم القرآن والسنة","لأنه اعتمد على الأمثال الأجنبية فقط","لأنه لم يذكر تقوى الله في رسالته"],"reason":0},{"type":"mcq","q":"أيُّ الشروط الآتية يجعل النصيحة بين الأصدقاء والزملاء مؤثّرةً ومقبولةً كما تعلّمنا من الدرس؟","options":["التشهير أمام الجميع","الإخلاص والصدق ولين العبارة وقصد الإصلاح","اللوم المستمر بقسوة","الانتظار حتى تتفاقم المشكلة"],"answer":1,"why":"النصيحة باللطف والإخلاص تصل إلى القلوب وتحقّق الإصلاح."},{"type":"essay","q":"كيف ربط الشيخ الخراسيني بين «تقوى الله في السر والعلن» وبين «العدل في الحكم»؟","model":"لأن من يراقب الله في سرّه وعلنه لا يظلم أحدًا ولا يحابي قويًا على حساب ضعيف، فتكون التقوى الضمان الحقيقي للعدل."},{"type":"tfr","q":"خطر البطانة السيئة والمتملّقين يكمن في تزيين الباطل وإخفاء الحقائق عن صاحب القرار.","answer":true,"reasons":["لأن المتملّقين يقدّمون مصالحهم الشخصية ويمنعون وصول الحقيقة، مما يضرّ بالرعية والدولة","لأن المتملّقين يساعدون على كشف الحقيقة دائمًا","لأن البطانة لا تأثير لها على القرار"],"reason":0},{"type":"mcq","q":"إلى أيّ فنٍّ نثريٍّ ينتمي نص الشيخ الخراسيني؟","options":["القصة القصيرة","فن الرسائل والنصائح التراثية","المسرحية","المقالة العلمية"],"answer":1,"why":"ينتمي إلى فن النصائح والرسائل التراثية التي ازدهرت في عصر اليعاربة."},{"type":"essay","q":"قارن بين صفات الوالي الأمين وصفات البطانة السيئة كما حذّر منها الشيخ الخراسيني.","model":"الوالي الأمين صادقٌ عادلٌ ينفّذ الحق ويرحم الرعية، أما البطانة السيئة فمتملّقة ذات أطماع تزيّن الباطل وتخفي الحقائق."},{"type":"tfr","q":"العدل والرحمة قيمتان متكاملتان في بناء المجتمع المستقر.","answer":true,"reasons":["لأن العدل يحفظ الحقوق والرحمة تجبر القلوب وتعين الضعفاء والمحتاجين","لأن الرحمة تلغي العدل","لأن العدل يمنع الرحمة"],"reason":0},{"type":"essay","q":"اكتب نصيحة قصيرة من ثلاث جمل لزميلٍ تولّى رئاسة جماعةٍ مدرسية، مستفيدًا من قيم الشيخ الخراسيني.","model":"مثال: أخي العزيز، أوصيك بالعدل بين جميع زملائك، ومشاورة أعضاء الجماعة قبل اتخاذ القرارات، والرفق بهم وتقدير جهودهم؛ فبالتعاون والأمانة ينجح العمل."}]}},
  {"id":"g9-arabic-1-u1-2n","grade":"g9","subject":"arabic","term":1,"unit":1,"no":2,"title":"الأنشطة النحوية والصرفية: تطبيقات على ما سبقت دراسته","summary":"مراجعة متحركة للجملة الاسمية والفعلية وكان وإنّ وعلامات الإعراب والميزان الصرفي، ثم أنشطة بثلاثة مستويات.","page":"lesson-u1-grammar-review.html","video":"","pdf":"","notes":["الجملة الاسمية تتكوّن من مبتدأ وخبر مرفوعَين، ويأتي الخبر مفردًا أو جملةً أو شبه جملة.","كان وأخواتها أفعال ناسخة ترفع المبتدأ اسمًا لها وتنصب الخبر خبرًا لها.","إنّ وأخواتها حروف ناسخة تنصب المبتدأ اسمًا لها وترفع الخبر خبرًا لها.","المثنى يُرفع بالألف ويُنصب ويُجر بالياء، وجمع المذكر السالم يُرفع بالواو ويُنصب ويُجر بالياء، وجمع المؤنث السالم يُنصب بالكسرة.","الفعل المجرّد جميع حروفه أصلية في الماضي، والفعل المزيد زيد على أصوله حرف أو أكثر.","الميزان الصرفي (فَعَلَ) يوزن به أصل الكلمة، وما زيد فيها يُزاد في الميزان وما حُذف يُحذف منه."],"exercises":["أدخل «كان» مرة و«إنّ» مرة على جملة: «العلمُ نورٌ» مع الضبط.","بيّن نوع الفعل (مجرّد أم مزيد): كَتَبَ، أَكْرَمَ، اسْتَغْفَرَ.","زِنِ الكلمات الآتية صرفيًا: كاتِب، مَكْتوب، دَحْرَجَ."],"levels":{"easy":[{"type":"mcq","q":"ما عمل «كان وأخواتها» عند دخولها على الجملة الاسمية؟","options":["تنصب الاسم وترفع الخبر","ترفع الاسم وتنصب الخبر","تجرّ الاسم والخبر","لا تغيّر شيئًا"],"answer":1,"why":"كان وأخواتها ترفع المبتدأ اسمًا لها وتنصب الخبر."},{"type":"mcq","q":"ما إعراب «الصدقَ» في جملة: «إنَّ الصدقَ منجاةٌ»؟","options":["مبتدأ مرفوع","اسم إنّ منصوب بالفتحة","خبر إنّ مرفوع","فاعل مرفوع"],"answer":1,"why":"إنّ تنصب المبتدأ اسمًا لها وترفع الخبر."},{"type":"mcq","q":"ما علامة نصب جمع المؤنث السالم؟","options":["الفتحة","الكسرة","الياء","الألف"],"answer":1,"why":"جمع المؤنث السالم يُنصب بالكسرة نيابةً عن الفتحة."},{"type":"mcq","q":"ما وزن كلمة «كاتِب» في الميزان الصرفي؟","options":["فَعَلَ","فاعِل","مَفْعول","فَعيل"],"answer":1,"why":"أصلها كَتَبَ (فَعَلَ) وبزيادة الألف تصبح فاعِل."}],"medium":[{"type":"mcq","q":"ما نوع الخبر في جملة: «الطالبُ يقرأُ الدرسَ»؟","options":["خبر مفرد","خبر جملة فعلية","خبر شبه جملة","مفعول به"],"answer":1,"why":"جملة «يقرأُ الدرسَ» الفعلية في محل رفع خبر المبتدأ."},{"type":"tfr","q":"الفعل «اسْتَغْفَرَ» فعلٌ مجرّدٌ ثلاثيٌّ.","answer":false,"reasons":["لأن أصله «غَفَرَ» وزيدت عليه الألف والسين والتاء فهو مزيد بثلاثة أحرف","لأن جميع حروفه أصلية","لأنه اسم وليس فعلًا"],"reason":0},{"type":"essay","q":"أدخل «كان» مرة و«إنّ» مرة على جملة «الجوُّ معتدلٌ» واضبط الكلمتين.","model":"كان الجوُّ معتدلًا. إنَّ الجوَّ معتدلٌ."},{"type":"tfr","q":"المثنى يُرفع بالألف ويُنصب ويُجرّ بالياء.","answer":true,"reasons":["لأننا نقول: حضر الطالبانِ (بالألف)، ورأيتُ الطالبَينِ (بالياء)","لأن المثنى يُرفع بالواو","لأن المثنى يُنصب بالكسرة"],"reason":0},{"type":"mcq","q":"أيُّ الأفعال الآتية فعلٌ لازمٌ (يكتفي بفاعله)؟","options":["كَتَبَ","نامَ","قَرَأَ","شَرِبَ"],"answer":1,"why":"«نامَ الطفلُ» جملة تامة لا تحتاج إلى مفعول به."},{"type":"essay","q":"أعرب: «كان المعلمونَ مجتهدينَ».","model":"كان: فعل ماضٍ ناسخ. المعلمونَ: اسم كان مرفوع وعلامة رفعه الواو لأنه جمع مذكر سالم. مجتهدينَ: خبر كان منصوب وعلامة نصبه الياء لأنه جمع مذكر سالم."},{"type":"tfr","q":"لمعرفة حروف الفعل الأصلية والزائدة نردّه إلى الماضي مع الضمير «هو».","answer":true,"reasons":["لأن صيغة الماضي المفرد المذكر تجرّد الفعل من حروف المضارعة والضمائر المتصلة","لأننا نردّه إلى فعل الأمر دائمًا","لأن المضارع يكشف كل الحروف الأصلية وحده"],"reason":0}],"hard":[{"type":"mcq","q":"ما وزن الفعل «دَحْرَجَ» في الميزان الصرفي؟","options":["فَعَلَ","فَعْلَلَ","أَفْعَلَ","تَفَعَّلَ"],"answer":1,"why":"دَحْرَجَ فعل رباعي مجرّد يوزن على «فَعْلَلَ» بزيادة لام ثانية."},{"type":"essay","q":"فرّق بين عمل «كان» وعمل «إنّ» بمثالين من إنشائك.","model":"كان ترفع الاسم وتنصب الخبر (كان الطالبُ مجتهدًا)، أما إنّ فتنصب الاسم وترفع الخبر (إنَّ الطالبَ مجتهدٌ)."},{"type":"tfr","q":"في جملة «كافأَ المديرُ الطالباتِ» تُعرب «الطالباتِ» مفعولًا به منصوبًا وعلامة نصبه الكسرة.","answer":true,"reasons":["لأن «الطالباتِ» جمع مؤنث سالم يُنصب بالكسرة نيابةً عن الفتحة","لأنها اسم مجرور بحرف جر محذوف","لأنها فاعل مرفوع"],"reason":0},{"type":"mcq","q":"أيُّ الكلمات الآتية على وزن «مَفْعول»؟","options":["كاتِب","مَكْتوب","مَكْتَب","كِتاب"],"answer":1,"why":"مَكْتوب اسم مفعول من كَتَبَ على وزن مَفْعول."},{"type":"essay","q":"صنّف الأفعال الآتية إلى مجرّد ومزيد: جَلَسَ، أَكْرَمَ، قَاتَلَ، فَتَحَ.","model":"مجرّد: جَلَسَ، فَتَحَ. مزيد: أَكْرَمَ (بالهمزة)، قَاتَلَ (بالألف)."},{"type":"tfr","q":"الفعل المتعدّي يكتفي بفاعله ولا يحتاج إلى مفعول به ليتمّ المعنى.","answer":false,"reasons":["لأن الفعل المتعدّي يتجاوز الفاعل ويحتاج إلى مفعول به، أما اللازم فهو الذي يكتفي بفاعله","لأن كل الأفعال في العربية لازمة","لأن الفاعل لا يأتي مع الفعل المتعدّي"],"reason":0},{"type":"mcq","q":"ما علامة رفع جمع المذكر السالم في: «المهندسونَ مبدعونَ»؟","options":["الضمة","الألف","الواو","الياء"],"answer":2,"why":"جمع المذكر السالم يُرفع بالواو."},{"type":"essay","q":"حوّل الخبر المفرد إلى خبر جملة فعلية في: «الطالبُ مجتهدٌ في دروسه».","model":"الطالبُ يجتهدُ في دروسه."},{"type":"tfr","q":"إذا حُذف حرفٌ أصليٌّ من الكلمة فإن ما يقابله في الميزان الصرفي يُحذف أيضًا.","answer":true,"reasons":["لأن الميزان الصرفي مرآة للكلمة، مثل «قِفْ» من «وَقَفَ» وزنها «عِلْ» بحذف الفاء","لأن الميزان يبقى «فَعَلَ» دائمًا دون تغيير","لأن الحذف لا يحدث في العربية"],"reason":0},{"type":"essay","q":"أعرب: «إنَّ الطالبَينِ متفوّقانِ» إعرابًا تامًا.","model":"إنَّ: حرف ناسخ. الطالبَينِ: اسم إنّ منصوب وعلامة نصبه الياء لأنه مثنى. متفوّقانِ: خبر إنّ مرفوع وعلامة رفعه الألف لأنه مثنى."}]}},
  {"id":"g9-arabic-1-u1-3s","grade":"g9","subject":"arabic","term":1,"unit":1,"no":3,"title":"الأنشطة الإملائية: تطبيقات على ما سبقت دراسته","summary":"مراجعة متحركة لهمزتي الوصل والقطع والهمزة المتوسطة والتاء والهاء والتنوين وعلامات الترقيم، ثم أنشطة بثلاثة مستويات.","page":"lesson-u1-spelling-review.html","video":"","pdf":"","notes":["للتمييز بين همزة الوصل والقطع نضع حرف «الواو» قبل الكلمة: إن نُطقت الهمزة فهي قطع (وأكرم)، وإن سقطت فهي وصل (واستخرج).","الهمزة المتوسطة تُكتب حسب أقوى الحركتين: الكسرة (ئـ) > الضمة (ؤ) > الفتحة (أ) > السكون.","الهمزة المتوسطة المفتوحة بعد ألف مدّ أو واو مدّ تُكتب على السطر (قِراءة، مُروءة)، وبعد ياء ساكنة على نبرة (بِيئة).","التاء المربوطة (ة) تُنطق تاءً وصلًا وهاءً وقفًا، والمفتوحة (ت) تُنطق تاءً دائمًا، والهاء (ه) تُنطق هاءً دائمًا بلا نقطتين.","للتمييز بين التنوين والنون الأصلية نقف على الكلمة بالسكون؛ إن بقي المعنى سليمًا فهو تنوين (شكرًا ← شكر).","علامات الترقيم الأساسية تنظّم القراءة وتوضّح المعنى (النقطة، الفاصلة، الاستفهام، التعجب، النقطتان)."],"exercises":["بيّن نوع الهمزة (وصل أم قطع) مع السبب: استغفار، إحسان، اكتب، أحمد.","علّل سبب كتابة الهمزة المتوسطة في: بِئْر، مُؤْمِن، قِرَاءَة، هَيْئَة.","صوّب الخطأ الإملائي: «شكرن لك على هذِه المياة العذبة»."],"levels":{"easy":[{"type":"mcq","q":"ما نوع الهمزة في كلمة «استغفار»؟","options":["همزة قطع","همزة وصل","همزة متوسطة","همزة متطرفة"],"answer":1,"why":"مصدر الفعل السداسي همزته همزة وصل وتسقط عند وصلها بالواو (واستغفار)."},{"type":"mcq","q":"ما أقوى الحركات عند كتابة الهمزة المتوسطة؟","options":["الفتحة","الضمة","الكسرة","السكون"],"answer":2,"why":"الكسرة أقوى الحركات وتناسبها النبرة (ئـ)."},{"type":"mcq","q":"كيف تُكتب كلمة «مياه» في آخرها؟","options":["تاء مربوطة (ة)","تاء مفتوحة (ت)","هاء بلا نقطتين (ه)","نون"],"answer":2,"why":"تُنطق هاءً في الوصل والوقف (مياهُ البحر / مياه) فتُكتب هاءً بلا نقطتين."},{"type":"mcq","q":"أيُّ كتابةٍ مما يأتي صحيحة؟","options":["شكرن","شُكْرًا","شكرآ","شكرنًا"],"answer":1,"why":"التنوين لا يُكتب نونًا بل تنوين فتح فوق ألف زائدة."}],"medium":[{"type":"mcq","q":"لماذا كُتبت الهمزة المتوسطة على السطر في كلمة «قِرَاءَة»؟","options":["لأنها مكسورة","لأنها مفتوحة بعد ألف مدّ ساكنة","لأنها مضمومة","لأنها في أول الكلمة"],"answer":1,"why":"الهمزة المتوسطة المفتوحة بعد ألف مدّ تُكتب مفردةً على السطر."},{"type":"tfr","q":"كلمة «إِحْسَان» همزتها همزة وصل لأنها مصدر فعل رباعي.","answer":false,"reasons":["لأن ماضي وأمر ومصدر الفعل الرباعي همزتها همزة قطع (أحسنَ، أحسِنْ، إحسان)","لأنها فعل مضارع","لأنها تبدأ بأل التعريف"],"reason":0},{"type":"essay","q":"كيف نفرّق بين التاء المربوطة (ة) والهاء المربوطة (ه) في آخر الكلمة؟ أعطِ مثالًا لكل منهما.","model":"التاء المربوطة تُنطق تاءً عند الوصل وهاءً عند الوقف مثل «مدرسةُ العلم»، أما الهاء فتُنطق هاءً في الوصل والوقف بلا نقطتين مثل «مياهُ البحر»."},{"type":"tfr","q":"جميع الأفعال المضارعة المبدوءة بهمزة المتكلم (أكتبُ، أقرأُ) همزتها همزة قطع.","answer":true,"reasons":["لأن همزة المضارعة للمتكلم تُنطق وتُكتب دائمًا همزة قطع في كل الأفعال","لأنها همزة وصل","لأن المضارع لا يبدأ بهمزة أبدًا"],"reason":0},{"type":"mcq","q":"ما علامة الترقيم المناسبة بعد القول وقبل التعداد والتفصيل؟","options":["النقطة (.)","النقطتان الرأسيتان (:)","علامة الاستفهام (؟)","علامة التعجب (!)"],"answer":1,"why":"تُوضع النقطتان الرأسيتان بعد القول وقبل التعداد."},{"type":"essay","q":"علّل رسم الهمزة المتوسطة على نبرة في كلمة «بِئْر» وعلى واو في «مُؤْمِن».","model":"في «بِئْر» الهمزة ساكنة وما قبلها مكسور والكسرة أقوى من السكون فكُتبت على نبرة. وفي «مُؤْمِن» الهمزة ساكنة وما قبلها مضموم والضمة أقوى فكُتبت على واو."},{"type":"tfr","q":"تُكتب همزة كلمة «بِيئَة» على نبرة لأنها سبقت بياء ساكنة.","answer":true,"reasons":["لأن الياء الساكنة في الهمزة المتوسطة تُعامل معاملة الكسرة فتُكتب الهمزة على نبرة","لأنها همزة متطرفة","لأن قبلها ألف مدّ"],"reason":0}],"hard":[{"type":"mcq","q":"أيُّ الكلمات الآتية جميع همزاتها «همزات وصل»؟","options":["ابن، اسم، اجتمع","أحمد، إلى، أكرم","إحسان، استغفر، أكتبُ","إنّ، الكتاب، أخذ"],"answer":0,"why":"«ابن» و«اسم» من الأسماء السماعية، و«اجتمع» ماضٍ خماسي، وكلها همزات وصل."},{"type":"essay","q":"صوّب الأخطاء الإملائية في الجملة: «استقبلت المدرسه الضيوف بكل حفاوةن وشكرن».","model":"استقبلت المدرسةُ الضيوفَ بكلّ حفاوةٍ وشكرًا. (تصويب: المدرسة بالتاء المربوطة، وحفاوةٍ وشكرًا بالتنوين لا بالنون)."},{"type":"tfr","q":"في كلمة «مُرُوءَة» تُكتب الهمزة المتوسطة على السطر لأنها مفتوحة بعد واو مدّ ساكنة.","answer":true,"reasons":["لأن الهمزة المتوسطة المفتوحة بعد واو ساكنة تُكتب مفردةً على السطر","لأنها مضمومة بعد كسرة","لأنها في آخر الكلمة"],"reason":0},{"type":"mcq","q":"أيُّ اختبارٍ يُميّز بسهولة بين التنوين والنون الأصلية؟","options":["وضع الواو قبل الكلمة","الوقف على الكلمة بالسكون (حذف صوت النون)","إضافة أل التعريف فقط","عدّ حروف الكلمة"],"answer":1,"why":"عند الوقف إن بقي المعنى سليمًا فهو تنوين، وإن اختلّ فهي نون أصلية."},{"type":"essay","q":"رتّب الحركات الأربع من الأقوى إلى الأضعف مع ذكر الحرف المناسب لكل حركة في الهمزة المتوسطة.","model":"١) الكسرة (ئـ). ٢) الضمة (ؤ). ٣) الفتحة (أ). ٤) السكون."},{"type":"tfr","q":"التاء في جمع المؤنث السالم مثل «طالبات» تُكتب تاءً مربوطة.","answer":false,"reasons":["لأنها تُنطق تاءً في الوصل والوقف معًا فتُكتب تاءً مفتوحة (ت)","لأنها تُنطق هاءً عند الوقف","لأنها ليست تاءً أصلًا"],"reason":0},{"type":"mcq","q":"أيُّ جملةٍ مما يأتي خاليةٌ من الأخطاء الإملائية؟","options":["أجتهدُ في دروسي إجتهادًا كبيرن.","أجتهدُ في دروسي اجتهادًا كبيرًا.","اجتهدُ في دروسي إجتهادًا كبيرًا.","أجتهدُ في دروسي اجتهادن كبيرًا."],"answer":1,"why":"«أجتهدُ» قطع (مضارع للمتكلم)، و«اجتهادًا» وصل (مصدر خماسي)، و«كبيرًا» بالتنوين."},{"type":"essay","q":"اشرح سبب كتابة الهمزة في «سَأَلَ» و«سُئِلَ» و«مَسْأَلَة».","model":"«سَأَلَ» مفتوحة بعد فتح ← ألف. «سُئِلَ» مكسورة بعد ضم والكسرة أقوى ← نبرة. «مَسْأَلَة» مفتوحة بعد سكون والفتحة أقوى ← ألف."},{"type":"tfr","q":"تُكتب همزة «أل» التعريف همزة قطع دائمًا.","answer":false,"reasons":["لأن «أل» التعريف هي الحرف الوحيد الذي همزته همزة وصل، أما بقية الحروف فهمزتها قطع","لأن الحروف ليس فيها همزات","لأن «أل» فعل ثلاثي"],"reason":0},{"type":"essay","q":"اكتب فقرة قصيرة من جملتين تشتمل على همزة وصل وهمزة قطع وتاء مربوطة وعلامتي ترقيم مختلفتين.","model":"مثال: قال أحمدُ: «استعدّت المدرسةُ لاستقبال العام الجديد بحماسٍ!» (أحمد قطع، استعدت/المدرسة وصل، المدرسة مربوطة، النقطتان وعلامة التعجب)."}]}},
  {"id":"g9-arabic-1-u1-4w","grade":"g9","subject":"arabic","term":1,"unit":1,"no":4,"title":"التعبير: كتابة فقرة","summary":"شرح متحرك لمفهوم الفقرة ومكوّناتها الثلاثة (المفتاحية والداعمة والختامية) وشروطها الشكلية بمثال تطبيقي، ثم أنشطة بثلاثة مستويات.","page":"lesson-paragraph-writing.html","video":"","pdf":"","notes":["الفقرة: مجموعة جمل مترابطة تعالج فكرةً رئيسةً واحدةً فقط.","من شروطها الشكلية: ترك فراغ بمقدار كلمة في أول السطر الأول، وإنهاؤها بنقطة (.).","الجملة المفتاحية: تحمل الفكرة الرئيسة وتأتي غالبًا في بداية الفقرة.","الجمل الداعمة: تشرح الفكرة المفتاحية وتفصّلها بالأسباب والأمثلة.","الجملة الختامية: تلخّص الفقرة أو تذكر نتيجتها وتغلقها بإحكام.","نربط بين جمل الفقرة بأدوات الربط المناسبة (و، فـ، لذلك، كما أن) وعلامات الترقيم."],"exercises":["اذكر المكوّنات الثلاثة للفقرة السليمة.","اكتب جملة مفتاحية مناسبة لفقرة عن «أهمية المحافظة على الماء».","اكتب فقرة متكاملة من أربع جمل عن «فضل المعلم» مراعيًا الفراغ والروابط والترقيم."],"levels":{"easy":[{"type":"mcq","q":"كم فكرةً رئيسةً تعالج الفقرة الواحدة؟","options":["فكرة واحدة فقط","ثلاث أفكار مختلفة","خمس أفكار","بلا فكرة"],"answer":0,"why":"القاعدة الذهبية للفقرة: فكرة واحدة متكاملة لكل فقرة."},{"type":"mcq","q":"ماذا نترك في بداية السطر الأول من الفقرة؟","options":["سطرين فارغين","فراغًا بمقدار كلمة","علامة تعجب","نقطة"],"answer":1,"why":"ترك مسافة بمقدار كلمة في أول السطر يُميّز بداية الفقرة."},{"type":"mcq","q":"ما اسم الجملة التي تقدّم الفكرة الرئيسة للفقرة؟","options":["الجملة الختامية","الجملة المفتاحية","الجملة المعترضة","الجملة المنفية"],"answer":1,"why":"الجملة المفتاحية تفتح الفقرة وتحدّد فكرتها الرئيسة."},{"type":"mcq","q":"بأي علامة ترقيم تنتهي الفقرة التامة عادةً؟","options":["الفاصلة (،)","النقطة (.)","النقطتان (:)","الشرطة (-)"],"answer":1,"why":"تنتهي الفقرة بنقطة عند اكتمال فكرتها."}],"medium":[{"type":"mcq","q":"ما وظيفة «الجمل الداعمة» في الفقرة؟","options":["البدء بفكرة جديدة مختلفة","شرح الفكرة المفتاحية وتفصيلها بالأمثلة والأسباب","تكرار العنوان فقط","إلغاء الجملة المفتاحية"],"answer":1,"why":"الجمل الداعمة تفصّل وتشرح ما ورد في الجملة المفتاحية."},{"type":"tfr","q":"يجوز إدخال جملة لا علاقة لها بالفكرة الرئيسة داخل الفقرة لإطالتها.","answer":false,"reasons":["لأن ذلك يُعدّ حشوًا يضعف تماسك الفقرة ويشتّت القارئ","لأن طول الفقرة أهم من وضوحها","لأن الفقرة يجب أن تجمع موضوعات متفرقة"],"reason":0},{"type":"essay","q":"اذكر ثلاث أدوات ربط تساعد على تماسك الجمل داخل الفقرة.","model":"الواو، الفاء، ثم، لذلك، كما أن، بالإضافة إلى، غير أن."},{"type":"tfr","q":"تُستخدم الفاصلة المنقوطة (؛) بين جملتين تكون الثانية سببًا أو نتيجةً للأولى.","answer":true,"reasons":["لأن الفاصلة المنقوطة توضّح العلاقة السببية بين الجملتين داخل الفقرة","لأنها توضع فقط في نهاية الكتاب","لأنها بديل عن علامة الاستفهام"],"reason":0},{"type":"mcq","q":"أيُّ جملةٍ مما يأتي تصلح جملةً ختاميةً لفقرة عن الرياضة الصباحية؟","options":["للرياضة أنواع كثيرة في الملاعب.","لذلك يجدر بكلّ طالبٍ أن يخصّص دقائقَ يوميةً لممارسة الرياضة.","في المدرسة حصة للرياضة.","السباحة رياضة مائية."],"answer":1,"why":"تلخّص نتيجة الفقرة وتغلقها بأداة الربط «لذلك»."},{"type":"essay","q":"اكتب جملة مفتاحية مناسبة لفقرة تتحدث عن «أهمية التعاون بين الطلاب».","model":"مثال: للتعاون بين الطلاب أثرٌ كبيرٌ في تحقيق النجاح وتقوية روح الأخوّة داخل الصف."},{"type":"tfr","q":"الفقرة المتماسكة تُعدّ اللبنة الأساسية لبناء موضوع تعبير ناجح.","answer":true,"reasons":["لأن موضوع التعبير يتكوّن من مجموعة فقرات متسلسلة ومترابطة","لأن الموضوع لا يحتوي على فقرات","لأن الفقرة تُكتب في الخاتمة فقط"],"reason":0}],"hard":[{"type":"mcq","q":"أيُّ جملةٍ مما يأتي تُعدّ «دخيلةً» على فقرة تتحدث عن فوائد القراءة؟","options":["القراءة تثري الحصيلة اللغوية للطالب.","وتوسّع مداركه وتنمّي خياله.","تُعدّ كرة القدم أكثر الرياضات شعبيةً في العالم.","لذلك ينبغي تخصيص وقتٍ يوميٍّ للمطالعة."],"answer":2,"why":"الحديث عن كرة القدم خارج عن فكرة الفقرة الرئيسة (فوائد القراءة)."},{"type":"essay","q":"اشرح الفرق بين «الجملة المفتاحية» و«الجملة الختامية» في الفقرة.","model":"الجملة المفتاحية تأتي في البداية وتطرح الفكرة الرئيسة للفقرة، أما الجملة الختامية فتأتي في النهاية لتلخّص الفكرة أو تستنتج منها توصيةً أو نتيجة."},{"type":"tfr","q":"يُفضَّل عند الانتقال إلى فكرة جديدة أن نبدأ فقرةً جديدةً في سطرٍ جديدٍ مع ترك فراغ في بدايتها.","answer":true,"reasons":["لأن ذلك يفصل بين الأفكار بصريًا ومعنويًا ويجعل النص منظمًا ومريحًا للقارئ","لأن كل الأفكار يجب أن تُدمج في سطر واحد","لأن الفراغ يُترك في الفقرة الأولى فقط"],"reason":0},{"type":"mcq","q":"ما الخطأ الموجود في فقرةٍ مكتوبةٍ بلا فواصل ولا نقاط ولا أدوات ربط؟","options":["كثرة الشواهد","غياب التماسك وصعوبة فهم حدود الجمل","قصر الجمل أكثر من اللازم","وضوح الفكرة المفتاحية"],"answer":1,"why":"علامات الترقيم والروابط ضرورية لتمييز الجمل وربط المعاني."},{"type":"essay","q":"اكتب فقرةً متكاملةً (جملة مفتاحية + جملتان داعمتان + جملة ختامية) عن «برّ الوالدين».","model":"مثال: برّ الوالدين من أعظم القيم التي حثّ عليها ديننا الحنيف؛ فهو سببٌ لرضا الله تعالى وبركة العمر، كما ينشر المودّة والرحمة داخل الأسرة. لذلك يجب علينا طاعتهما والإحسان إليهما بالقول والعمل."},{"type":"tfr","q":"تكرار نفس الفكرة بألفاظ مختلفة داخل الفقرة يقوّيها ويزيدها جمالًا.","answer":false,"reasons":["لأن التكرار بلا فائدة يُعدّ حشوًا يضعف الفقرة، بل ينبغي تقديم تفاصيل أو أمثلة جديدة","لأن الجمل الداعمة يجب أن تكرّر الجملة المفتاحية حرفيًا","لأن التكرار بديل عن الروابط"],"reason":0},{"type":"mcq","q":"أيُّ ترتيبٍ مما يأتي يمثّل البناء الصحيح للفقرة؟","options":["ختامية ← داعمة ← مفتاحية","مفتاحية ← جمل داعمة ← ختامية","داعمة ← ختامية ← مفتاحية","مفتاحية فقط بلا دعم"],"answer":1,"why":"تبدأ الفقرة بالمفتاحية، تليها الداعمة الشارحة، وتُغلق بالختامية."},{"type":"essay","q":"أضف أدوات ربط وعلامات ترقيم مناسبة لجعل الجمل الآتية فقرة متماسكة: «الماء سر الحياة. نستخدمه للشرب والزراعة. يجب عدم الإسراف فيه».","model":"الماء سرُّ الحياة؛ فنحن نستخدمه للشرب والزراعة والنظافة، ولا غنى لكائنٍ حيٍّ عنه. لذلك يجب علينا الحفاظ عليه وعدم الإسراف فيه."},{"type":"tfr","q":"يمكن للجمل الداعمة أن تشمل أسبابًا أو أمثلةً واقعيةً أو نتائج توضّح الفكرة المفتاحية.","answer":true,"reasons":["لأن تنوّع وسائل الدعم يجعل الفقرة أوضح وأكثر إقناعًا للقارئ","لأن الجمل الداعمة لا يجوز فيها ذكر الأمثلة","لأن الأمثلة توضع في العنوان فقط"],"reason":0},{"type":"essay","q":"اذكر أربعة معايير تراجع بها فقرتك بعد الانتهاء من كتابتها.","model":"١) وحدة الفكرة وعدم وجود جمل دخيلة. ٢) وجود فراغ في البداية ونقطة في النهاية. ٣) استخدام أدوات الربط وعلامات الترقيم. ٤) سلامة الإملاء والنحو."}]}},
  {"id":"g9-arabic-1-u2-2g","grade":"g9","subject":"arabic","term":1,"unit":2,"no":2,"title":"الأنشطة النحوية والصرفية: جملة كاد وأخواتها","summary":"شرح متحرك لأفعال المقاربة والرجاء والشروع وعملها وشرط خبرها وحكم اقترانه بـ «أنْ»، ثم أنشطة بثلاثة مستويات.","page":"lesson-kada-and-sisters.html","video":"","pdf":"","notes":["كاد وأخواتها أفعال ناسخة تعمل عمل «كان»: ترفع المبتدأ اسمًا لها وتنصب الخبر خبرًا لها.","شرط أساسي: يجب أن يكون خبر كاد وأخواتها جملةً فعليةً فعلها مضارع.","أقسامها ثلاثة: أفعال المقاربة (كاد، أوشك، كرب)، وأفعال الرجاء (عسى، حرى، اخلولق)، وأفعال الشروع (شرع، بدأ، أخذ، طفق، أنشأ، جعل).","أفعال الشروع لا تعمل عمل كاد إلا بلفظ الماضي فقط.","حكم اقتران الخبر بـ «أنْ»: يقلّ مع (كاد، كرب)، ويكثر مع (عسى، أوشك)، ويجب مع (حرى، اخلولق)، ويمتنع مع أفعال الشروع كلها.","إذا لم يأتِ بعدها فعل مضارع (مثل: أخذَ الطالبُ الكتابَ) فهي أفعال تامة ترفع فاعلًا وتنصب مفعولًا به."],"exercises":["استخرج الفعل الناسخ واسمه وخبره في: «أوشكَ الفجرُ أن يطلعَ»، «بدأَ المعلمُ يشرحُ».","بيّن حكم اقتران الخبر بـ «أنْ» مع: كادَ، عَسَى، حَرَى، شَرَعَ.","فرّق إعرابيًا بين: «أخذَ الطالبُ يكتبُ» و«أخذَ الطالبُ القلمَ»."],"levels":{"easy":[{"type":"mcq","q":"ما الشرط الأساسي في خبر «كاد وأخواتها»؟","options":["أن يكون اسمًا مفردًا","أن يكون جملة فعلية فعلها مضارع","أن يكون شبه جملة","أن يكون فعلًا ماضيًا"],"answer":1,"why":"لا تعمل كاد وأخواتها إلا إذا كان خبرها جملة فعلية فعلها مضارع."},{"type":"mcq","q":"إلى أي قسم ينتمي الفعل «أوشكَ»؟","options":["أفعال المقاربة","أفعال الرجاء","أفعال الشروع","الأفعال المتعدية لمفعولين"],"answer":0,"why":"كاد وأوشك وكرب تدلّ على قرب وقوع الخبر فهي من أفعال المقاربة."},{"type":"mcq","q":"إلى أي قسم ينتمي الفعل «عَسَى»؟","options":["أفعال المقاربة","أفعال الرجاء","أفعال الشروع","الحروف الناسخة"],"answer":1,"why":"عسى وحرى واخلولق من أفعال الرجاء."},{"type":"mcq","q":"ما حكم اقتران خبر أفعال الشروع بـ «أنْ»؟","options":["يجب","يكثر","يقلّ","يمتنع"],"answer":3,"why":"يمتنع اقتران خبر أفعال الشروع بأنْ، فنقول: شرعَ الطالبُ يذاكرُ."}],"medium":[{"type":"mcq","q":"ما حكم اقتران خبر «عسى» و«أوشك» بـ «أنْ»؟","options":["يمتنع","يقلّ","يكثر","يجب"],"answer":2,"why":"يكثر اقتران خبر عسى وأوشك بأنْ مثل: عسى اللهُ أن يرحمَنا."},{"type":"tfr","q":"يصحّ أن نقول: «بدأَ الطالبُ أن يكتبَ الدرسَ».","answer":false,"reasons":["لأن «بدأَ» من أفعال الشروع التي يمتنع اقتران خبرها بـ «أنْ»، والصواب: بدأَ الطالبُ يكتبُ","لأن «بدأَ» من أفعال الرجاء","لأن «يكتبَ» فعل ماضٍ"],"reason":0},{"type":"essay","q":"أعرب: «كادَ المطرُ ينزلُ».","model":"كادَ: فعل ماضٍ ناقص ناسخ من أفعال المقاربة. المطرُ: اسم كاد مرفوع بالضمة. ينزلُ: فعل مضارع مرفوع وفاعله ضمير مستتر تقديره هو، والجملة الفعلية في محل نصب خبر كاد."},{"type":"tfr","q":"يجب اقتران خبر الفعل «حَرَى» بـ «أنْ».","answer":true,"reasons":["لأن «حرى» و«اخلولق» يجب اقتران خبرهما بأنْ، مثل: حرى السلامُ أن يعمَّ","لأن «حرى» من أفعال الشروع","لأن «أنْ» تمتنع مع كل أفعال الرجاء"],"reason":0},{"type":"mcq","q":"في أيّ جملة مما يأتي جاء الفعل «أخذَ» فعلًا ناقصًا من أفعال الشروع؟","options":["أخذَ الطالبُ الكتابَ","أخذَ الطالبُ يقرأُ الدرسَ","أخذَ المسافرُ حقيبتَه","أخذَ البائعُ النقودَ"],"answer":1,"why":"لأن خبره جاء جملة فعلية فعلها مضارع (يقرأُ) ودلّ على البدء."},{"type":"essay","q":"أدخل فعلًا من أفعال الرجاء على جملة «النجاحُ قريبٌ» وغيّر ما يلزم.","model":"عسى النجاحُ أن يقتربَ (أو: عسى النجاحُ أن يتحقّقَ)."},{"type":"tfr","q":"تعمل أفعال الشروع عمل «كاد» في صيغتَي الماضي والمضارع معًا.","answer":false,"reasons":["لأن أفعال الشروع لا تعمل عمل كاد إلا بلفظ الماضي فقط","لأنها تعمل في الأمر فقط","لأنها حروف وليست أفعالًا"],"reason":0}],"hard":[{"type":"mcq","q":"ما إعراب كلمة «المعلمُ» في جملة: «شرعَ المعلمُ يشرحُ الدرسَ»؟","options":["فاعل مرفوع","اسم شرع مرفوع بالضمة","مبتدأ مرفوع","مفعول به"],"answer":1,"why":"شرعَ هنا فعل ناقص من أفعال الشروع يرفع المبتدأ اسمًا له."},{"type":"essay","q":"فرّق في الإعراب بين «الكتابَ» في (١) «أخذَ الطالبُ الكتابَ» وبين «يكتبُ» في (٢) «أخذَ الطالبُ يكتبُ».","model":"في (١) «أخذَ» تام و«الكتابَ» مفعول به منصوب. وفي (٢) «أخذَ» ناقص من أفعال الشروع وجملة «يكتبُ» الفعلية في محل نصب خبر أخذ."},{"type":"tfr","q":"في جملة «يأخذُ الطالبُ يذاكرُ» يعمل الفعل «يأخذُ» عمل كاد وأخواتها.","answer":false,"reasons":["لأن أفعال الشروع يُشترط لعملها أن تكون بلفظ الماضي فقط (أخذَ لا يأخذُ)","لأن «يذاكرُ» ليس فعلًا مضارعًا","لأن الطالب مفعول به"],"reason":0},{"type":"mcq","q":"ما الجملة الصحيحة نحويًّا مما يأتي؟","options":["طفقَ المهندسونَ أن يبنوا الجسرَ","طفقَ المهندسينَ يبنونَ الجسرَ","طفقَ المهندسونَ يبنونَ الجسرَ","طفقَ المهندسونَ بانينَ الجسرَ"],"answer":2,"why":"«المهندسونَ» مرفوع بالواو اسم طفق، والخبر جملة فعلية مضارعة بلا «أنْ» لأن طفق من أفعال الشروع."},{"type":"essay","q":"صوّب الخطأ في الجملتين: (١) كادَ القطارُ واصلًا. (٢) حرى المطرُ ينزلُ.","model":"(١) كادَ القطارُ يصلُ (لأن الخبر يجب أن يكون جملة فعلية مضارعة). (٢) حرى المطرُ أن ينزلَ (لأن خبر حرى يجب اقترانه بأنْ)."},{"type":"tfr","q":"يقلّ اقتران خبر «كاد» و«كرب» بـ «أنْ»، لكنه جائز.","answer":true,"reasons":["لأن الأغلب تجرّده من «أنْ» مثل «كاد المطرُ ينزلُ»، ويجوز اقترانه بها على قلة","لأن «أنْ» ممنوعة تمامًا مع كاد","لأن «أنْ» واجبة مع كاد"],"reason":0},{"type":"mcq","q":"في قوله تعالى: ﴿وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ﴾، ما نوع «طَفِقَ»؟","options":["فعل مقاربة","فعل رجاء","فعل شروع","حرف ناسخ"],"answer":2,"why":"«طَفِقَ» من أفعال الشروع ومعناه بدأ."},{"type":"essay","q":"أدخل «أوشك» على جملة «الطلابُ متفوّقونَ» مع مراعاة الأكثر في اقتران الخبر بأنْ.","model":"أوشكَ الطلابُ أن يتفوّقوا. (الطلابُ اسم أوشك مرفوع، وجملة «أن يتفوّقوا» في محل نصب خبر أوشك)."},{"type":"tfr","q":"في جملة «عسى المتسابقونَ أن يفوزوا» تكون «أن يفوزوا» في محل رفع خبر عسى.","answer":false,"reasons":["لأن عسى تعمل عمل كان فتنصب الخبر، فتكون الجملة الفعلية في محل نصب خبر عسى لا رفع","لأن المتسابقون منصوب","لأن يفوزوا فعل ماضٍ"],"reason":0},{"type":"essay","q":"اذكر حالات اقتران خبر كاد وأخواتها بـ «أنْ» الأربع مع مثال واحد لكل حالة.","model":"١) يقلّ مع كاد وكرب (كاد المطر ينزل). ٢) يكثر مع عسى وأوشك (عسى الفرج أن يأتي). ٣) يجب مع حرى واخلولق (حرى الحق أن ينتصر). ٤) يمتنع مع أفعال الشروع (بدأ الطالب يقرأ)."}]}},
  {"id":"g9-arabic-1-u2-3s","grade":"g9","subject":"arabic","term":1,"unit":2,"no":3,"title":"الأنشطة الإملائية: الهمزة المتطرفة","summary":"شرح متحرك لقاعدة الهمزة المتطرفة وحالاتها الأربع (الألف والواو والياء والسطر) بأمثلة تطبيقية، ثم أنشطة بثلاثة مستويات.","page":"lesson-final-hamza.html","video":"","pdf":"","notes":["القاعدة الذهبية للهمزة المتطرفة: ننظر فقط إلى حركة الحرف الذي يسبقها مباشرة (ولا ننظر إلى حركة الهمزة نفسها).","إذا كان ما قبلها مفتوحًا تُكتب على ألف (أ)، مثل: قَرَأَ، بَدَأَ، مَلْجَأ، يَبْدَأُ.","إذا كان ما قبلها مضمومًا تُكتب على واو (ؤ)، مثل: يَجْرُؤُ، تَباطُؤ، لُؤْلُؤ، تَكَافُؤ.","إذا كان ما قبلها مكسورًا تُكتب على ياء غير منقوطة (ئ)، مثل: شَاطِئ، قَارِئ، هَادِئ، يُنْشِئ.","إذا كان ما قبلها ساكنًا (ساكنًا صحيحًا أو حرف مدّ) تُكتب مفردة على السطر (ء)، مثل: عِبْء، شَيْء، سَمَاء، هُدُوء، جَرِيء.","إذا سبقت الهمزة المتطرفة بواو مشدّدة مضمومة مثل «تَبَوُّء» تُكتب على السطر كراهة اجتماع واوين."],"exercises":["علّل رسم الهمزة المتطرفة في الكلمات الآتية: مَبْدَأ، تَكَافُؤ، قَارِئ، جَرِيء.","صوّب الخطأ الإملائي في: «اشتريتُ شيئًا من الشاطء وكان الجوُّ هادأً».","هاتِ مثالين لكل حالة من حالات الهمزة المتطرفة الأربع."],"levels":{"easy":[{"type":"mcq","q":"إلى ماذا ننظر عند كتابة الهمزة المتطرفة؟","options":["حركة الهمزة فقط","حركة الحرف الذي قبلها فقط","أقوى الحركتين","أول حرف في الكلمة"],"answer":1,"why":"الهمزة المتطرفة تتبع حركة الحرف السابق لها فقط."},{"type":"mcq","q":"أيُّ كتابةٍ مما يأتي صحيحة لكلمة «شيء»؟","options":["شيئ","شَيْء","شيأ","شيؤ"],"answer":1,"why":"الياء قبلها ساكنة فتُكتب الهمزة مفردةً على السطر."},{"type":"mcq","q":"كيف تُكتب الهمزة المتطرفة إذا كان ما قبلها مضمومًا؟","options":["على ألف (أ)","على واو (ؤ)","على ياء (ئ)","على السطر (ء)"],"answer":1,"why":"الضمة يناسبها الواو مثل: تباطُؤ، يجرُؤ."},{"type":"mcq","q":"كيف تُكتب الهمزة المتطرفة إذا كان ما قبلها مكسورًا مثل «شاطـ...»؟","options":["شاطِأ","شاطِؤ","شاطِئ","شاطِء"],"answer":2,"why":"الطاء مكسورة فتُكتب على ياء غير منقوطة (شاطِئ)."}],"medium":[{"type":"mcq","q":"لماذا كُتبت الهمزة المتطرفة على السطر في كلمة «جَرِيء»؟","options":["لأن ما قبلها مكسور","لأن ما قبلها ياء مدّ ساكنة","لأن ما قبلها مفتوح","لأنها مضمومة"],"answer":1,"why":"الياء في «جريء» حرف مدّ ساكن وليست حركة كسرة، فتُكتب الهمزة على السطر."},{"type":"tfr","q":"تُكتب الهمزة المتطرفة في «يَبْدَأُ» على واو لأن الهمزة مضمومة.","answer":false,"reasons":["لأننا في الهمزة المتطرفة ننظر لحركة ما قبلها فقط (الدال مفتوحة) فتُكتب على ألف","لأنها همزة متوسطة","لأن الدال مكسورة"],"reason":0},{"type":"essay","q":"علّل رسم الهمزة المتطرفة في: «مَلْجَأ»، «تَكَافُؤ»، «مُخْطِئ»، «دِفْء».","model":"مَلْجَأ: قبلها فتح ← ألف. تَكَافُؤ: قبلها ضم ← واو. مُخْطِئ: قبلها كسر ← ياء. دِفْء: قبلها سكون ← السطر."},{"type":"tfr","q":"تُوضع نقطتان تحت الياء التي تُرسم عليها الهمزة المتطرفة مثل «قارئ».","answer":false,"reasons":["لأنها تُرسم على ياء غير منقوطة (ئ) حتى لا تلتبس بالياء الأصلية","لأنها تُكتب على ألف","لأن النقطتين واجبتان دائمًا"],"reason":0},{"type":"mcq","q":"أيُّ الكلمات الآتية كُتبت همزتها المتطرفة على السطر لأن ما قبلها ساكن صحيح؟","options":["سَمَاء","هُدُوء","عِبْء","جَرِيء"],"answer":2,"why":"الباء في «عِبْء» حرف صحيح ساكن، أما الكلمات الأخرى فقبلها حروف مدّ."},{"type":"essay","q":"صوّب الخطأ الإملائي في الكلمتين: «الهدوؤ» و«مبدء».","model":"الهدوء (على السطر لأن قبلها واو مد ساكنة). مبدأ (على ألف لأن قبلها دال مفتوحة)."},{"type":"tfr","q":"في كلمة «تَبَوُّء» تُكتب الهمزة المتطرفة على السطر لأن ما قبلها واو مشدّدة مضمومة.","answer":true,"reasons":["لأن العرب كرهوا اجتماع واوين متتابعتين في الرسم فكتبوها على السطر","لأن قبلها فتحة","لأن قبلها كسرة"],"reason":0}],"hard":[{"type":"mcq","q":"أيُّ مجموعةٍ من الكلمات الآتية كُتبت جميع همزاتها المتطرفة كتابةً صحيحة؟","options":["شاطئ، تباطؤ، دِفء، يقرأُ","شاطء، تباطء، دفئ، يقرؤ","شاطئ، تباطؤ، شيئ، جريئ","ملجأ، هدوؤ، قارئ، مبدء"],"answer":0,"why":"شاطئ (قبلها كسر)، تباطؤ (قبلها ضم)، دفء (قبلها سكون)، يقرأ (قبلها فتح)."},{"type":"essay","q":"قارن بين كتابة الهمزة المتطرفة في «يَتَبَوَّأُ» و«التَّبَوُّء» مع بيان السبب.","model":"في «يَتَبَوَّأُ» ما قبل الهمزة واو مفتوحة فتُكتب على ألف، أما في «التَّبَوُّء» فما قبلها واو مشدّدة مضمومة فتُكتب على السطر منعًا لاجتماع واوين."},{"type":"tfr","q":"تتفق كلمتا «بَطِيء» و«هَادِئ» في صورة رسم الهمزة المتطرفة.","answer":false,"reasons":["لأن «بَطِيء» قبلها ياء مدّ ساكنة فتُكتب على السطر، أما «هَادِئ» فقبلها دال مكسورة فتُكتب على ياء","لأن كلتيهما على ألف","لأن كلتيهما على واو"],"reason":0},{"type":"mcq","q":"ما الفرق بين قاعدة الهمزة المتوسطة وقاعدة الهمزة المتطرفة؟","options":["المتوسطة تقارن بين حركتها وحركة ما قبلها، أما المتطرفة فتعتمد على حركة ما قبلها فقط","لا يوجد فرق بينهما","المتطرفة تعتمد على حركة الهمزة فقط","المتوسطة تُكتب على السطر دائمًا"],"answer":0,"why":"الهمزة المتوسطة تعتمد على أقوى الحركتين، والمتطرفة على حركة الحرف السابق فقط."},{"type":"essay","q":"صوّب الأخطاء في الجملة: «كان القارء يقرؤ بصوتٍ هادء في فناء المدرسة».","model":"كان القارئُ يقرأُ بصوتٍ هادئٍ في فناءِ المدرسة. (القارئ وهادئ على ياء، ويقرأ على ألف)."},{"type":"tfr","q":"تُكتب الهمزة المتطرفة على ألف في «نَبَأ» و«مَبْدَأ» و«يَنْشَأُ» للسبب نفسه.","answer":true,"reasons":["لأن الحرف الذي يسبق الهمزة في الكلمات الثلاث مفتوح","لأن الهمزة نفسها مفتوحة في الكلمات الثلاث","لأن قبلها ساكنًا"],"reason":0},{"type":"mcq","q":"أيُّ كلمةٍ مما يأتي كُتبت خطأً؟","options":["لُؤْلُؤ","مُتَكَافِئ","بُطْء","مَلِيئ"],"answer":3,"why":"الصواب «مَلِيء» على السطر لأن ما قبل الهمزة ياء مدّ ساكنة."},{"type":"essay","q":"هاتِ من عندك أربع كلمات تنتهي بهمزة متطرفة تمثّل الحالات الأربع (ألف، واو، ياء، سطر).","model":"مثال: قَرَأَ (ألف)، تَباطُؤ (واو)، شَاطِئ (ياء)، سَمَاء أو جُزْء (سطر)."},{"type":"tfr","q":"في كلمة «جُزْء» تُكتب الهمزة على السطر لأن الزاي ساكنة.","answer":true,"reasons":["لأن كل همزة متطرفة سبقها حرف ساكن تُكتب مفردةً على السطر","لأن الجيم مضمومة","لأن قبلها ألف مدّ"],"reason":0},{"type":"essay","q":"اشرح لزميلك في جملتين كيف يفرّق إملائيًا بين «قَارِئ» و«جَرِيء».","model":"في «قَارِئ» الحرف قبل الهمزة هو الراء المكسورة فتُكتب الهمزة على ياء غير منقوطة (ئ). أما في «جَرِيء» فالحرف قبل الهمزة هو ياء المدّ الساكنة فتُكتب الهمزة على السطر (ء)."}]}},
  {"id":"g9-arabic-1-u3-1","grade":"g9","subject":"arabic","term":1,"unit":3,"no":1,"title":"القراءة: المتنبي","summary":"شرح متحرك لحياة المتنبي ونشأته وعلاقته بسيف الدولة وخصائص شعره، ثم أنشطة بثلاثة مستويات.","page":"lesson-al-mutanabbi.html","video":"","pdf":"","notes":["هو أبو الطيب أحمد بن الحسين الجعفي، وُلد في الكوفة عام ٣٠٣هـ في العصر العباسي.","عُرف بالذكاء الحاد والاعتداد بالنفس والطموح العالي منذ صغره.","ارتبط اسمه بالأمير سيف الدولة الحمداني في حلب، وفي بلاطه أبدع أروع قصائده (السيفيات).","تميّز شعره بكثرة الحِكم والأمثال السائرة التي يردّدها الناس حتى اليوم.","من أبرز خصائص شعره: قوة الألفاظ، وعمق المعاني، والاعتزاز بالنفس، وصدق التجربة.","قُتل المتنبي عام ٣٥٤هـ وهو في طريقه إلى بغداد."],"exercises":["اذكر نسب المتنبي ومكان ولادته في العصر العباسي.","ما المقصود بـ «السيفيات» في شعر المتنبي؟","اذكر ثلاث خصائص فنية لشعر المتنبي."],"levels":{"easy":[{"type":"mcq","q":"ما الاسم الحقيقي لأبي الطيب المتنبي؟","options":["أحمد بن الحسين","عمرو بن بحر","سعيد الخراسيني","محمد البوصيري"],"answer":0,"why":"اسمه أبو الطيب أحمد بن الحسين الجعفي."},{"type":"mcq","q":"في أي مدينة وُلد المتنبي؟","options":["حلب","الكوفة","مسقط","القاهرة"],"answer":1,"why":"وُلد في الكوفة بالعراق عام ٣٠٣هـ."},{"type":"mcq","q":"بماذا سُمّيت قصائد المتنبي في بلاط سيف الدولة الحمداني؟","options":["الحمدانيات","السيفيات","المعلقات","البردة"],"answer":1,"why":"سُمّيت السيفيات نسبةً إلى سيف الدولة الحمداني."},{"type":"mcq","q":"في أي عصر أدبي عاش المتنبي؟","options":["الجاهلي","الأموي","العباسي","الحديث"],"answer":2,"why":"عاش في العصر العباسي (٣٠٣هـ – ٣٥٤هـ)."}],"medium":[{"type":"mcq","q":"لماذا ارتحل المتنبي إلى البادية في شبابه؟","options":["للتجارة فقط","لتعلّم فصاحة اللغة وصفائها","للهروب من القراءة","للزراعة"],"answer":1,"why":"أكسبته البادية فصاحة اللسان وقوة الألفاظ."},{"type":"tfr","q":"قضى المتنبي تسع سنواتٍ في بلاط سيف الدولة الحمداني في حلب.","answer":true,"reasons":["لأنها كانت أخصب مراحل حياته الشعرية وفيها أبدع السيفيات","لأنه لم يزر حلب أبدًا","لأنه عاش فيها أسبوعًا واحدًا"],"reason":0},{"type":"essay","q":"اذكر ثلاث خصائص فنية لشعر المتنبي.","model":"جزالة الألفاظ وقوتها، وكثرة الحِكم والأمثال السائرة، وعمق المعاني، والاعتزاز بالنفس."},{"type":"tfr","q":"اقتصر شعر المتنبي على المدح دون أن يتضمّن حِكمًا أو فخرًا.","answer":false,"reasons":["لأن شعره حافل بالحكم والأمثال السائرة والفخر والوصف والمدح","لأن المتنبي لم يكتب الشعر","لأنه كتب في النحو فقط"],"reason":0},{"type":"mcq","q":"على ماذا يدلّ قوله: «والسيفُ والرمحُ والقرطاسُ والقلمُ»؟","options":["جمعه بين الفروسية والشجاعة وبين العلم والأدب","اهتمامه بالزراعة","خوفه من السفر","تفضيله الصمت"],"answer":0,"why":"السيف والرمح رمز الفروسية، والقرطاس والقلم رمز العلم والأدب."},{"type":"essay","q":"اذكر بيتًا من حِكَم المتنبي السائرة واشرح معناه بإيجاز.","model":"«ما كلّ ما يتمنّى المرءُ يدركهُ / تجري الرياحُ بما لا تشتهي السفنُ»؛ ومعناه أن الإنسان لا يحقّق دائمًا كل ما يتمناه فقد تعترضه ظروف غير متوقّعة."},{"type":"tfr","q":"غادر المتنبي بلاط سيف الدولة بسبب وشايات الحسّاد.","answer":true,"reasons":["لأن كثرة الحسّاد والوشاة عكّرت صفو العلاقة بينهما فرحل إلى مصر","لأن سيف الدولة لم يكن يحب الشعر","لأنه اعتزل الشعر تمامًا"],"reason":0}],"hard":[{"type":"mcq","q":"ما دلالة قول المتنبي: «أنا الذي نظرَ الأعمى إلى أدبي»؟","options":["شدة الاعتزاز بشعره وانتشار صيته ووضوحه","التواضع الشديد","الشكوى من الفقر","وصف الطبيعة"],"answer":0,"why":"مبالغة شعرية بليغة تدل على شهرة شعره وقوته واعتداده بنفسه."},{"type":"essay","q":"كيف أثّرت نشأة المتنبي بين الكوفة والبادية في تكوينه الشعري؟","model":"أكسبته الكوفة الثقافة الواسعة وحلقات العلم، وأكسبته البادية فصاحة اللسان وجزالة الألفاظ وصفاء اللغة."},{"type":"tfr","q":"تحوّلت كثيرٌ من أبيات المتنبي إلى أمثالٍ يردّدها الناس لصدق تجربتها الإنسانية.","answer":true,"reasons":["لأن حِكمه نابعة من تجارب الحياة والطموح وتلامس واقع الإنسان في كل عصر","لأنها مكتوبة بلغة عامية","لأنها قصيرة جدًا فقط"],"reason":0},{"type":"mcq","q":"في أي عام توفي المتنبي؟","options":["٣٠٣هـ","٣٥٤هـ","١٧٠هـ","٥٠٠هـ"],"answer":1,"why":"قُتل عام ٣٥٤هـ في طريق عودته إلى بغداد."},{"type":"essay","q":"اشرح معنى قول المتنبي: «على قدرِ أهلِ العزمِ تأتي العزائمُ».","model":"الإنجازات والأعمال العظيمة تكون على قدر همّة أصحابها وعزيمتهم؛ فمن عظمت همّته عظمت أعماله."},{"type":"tfr","q":"تجمع «السيفيات» بين مدح سيف الدولة ووصف بطولاته ومعاركه ضد الروم.","answer":true,"reasons":["لأن المتنبي واكب معارك سيف الدولة وسجّلها بشعر حماسي رفيع","لأنها قصائد في وصف السفر فقط","لأنها في رثاء المدن"],"reason":0},{"type":"mcq","q":"أيُّ صفةٍ من الآتية تُعدّ المحرّك الأساس في حياة المتنبي وشعره؟","options":["الكسل","الطموح العالي والاعتداد بالنفس","العزلة عن الناس","الزهد في المجد"],"answer":1,"why":"كان الطموح والاعتزاز بالنفس أبرز ملامح شخصيته وشعره."},{"type":"essay","q":"لماذا وُصف المتنبي بأنه «ملأ الدنيا وشغل الناس»؟","model":"لأن شعره حظي باهتمام النقاد والقرّاء عبر العصور، وتنافس الناس في حفظ حِكمه وشرح ديوانه."},{"type":"tfr","q":"يُعدّ المتنبي من شعراء العصر الجاهلي.","answer":false,"reasons":["لأنه عاش في العصر العباسي (القرن الرابع الهجري)","لأنه عاش في العصر الحديث","لأنه من شعراء الأندلس"],"reason":0},{"type":"essay","q":"اكتب فقرة قصيرة توضّح فيها ما يمكن أن يتعلّمه طالب اليوم من طموح المتنبي واجتهاده.","model":"نتعلّم من المتنبي علوّ الهمّة والمثابرة في طلب العلم والقراءة، وتنمية الموهبة بالتدريب والاطّلاع، والسعي نحو التميّز بعزيمة قوية."}]}},
  {"id":"g9-arabic-1-u3-2","grade":"g9","subject":"arabic","term":1,"unit":3,"no":2,"title":"الأنشطة النحوية والصرفية: الأفعال المتعدية إلى مفعولين أصلهما المبتدأ والخبر","summary":"شرح متحرك للأفعال المتعدية إلى مفعولين أصلهما المبتدأ والخبر (ظنّ وأخواتها) وأقسامها وإعرابها، ثم أنشطة بثلاثة مستويات.","page":"lesson-dhanna-and-sisters.html","video":"","pdf":"","notes":["ظنّ وأخواتها أفعال ناسخة تدخل على الجملة الاسمية فتنصب المبتدأ مفعولًا به أول، وتنصب الخبر مفعولًا به ثانيًا.","إذا حذفتَ الفعل والفاعل عاد المفعولان جملةً اسميةً تامةً من مبتدأ وخبر (الامتحانُ سهلٌ).","أقسامها ثلاثة: أفعال اليقين (علم، رأى، وجد، ألفى)، وأفعال الظن والرجحان (ظنّ، حسب، خال، زعم)، وأفعال التحويل (جعل، صيّر، اتّخذ، ردّ).","«رأى» القلبية (بمعنى علم) تنصب مفعولين، أما «رأى» البصرية (بالعين) فتنصب مفعولًا واحدًا فقط.","«وجد» بمعنى عَلِم تنصب مفعولين، أما «وجد» بمعنى عثر على شيء فتنصب مفعولًا واحدًا.","يعمل المضارع والأمر من ظنّ وأخواتها عمل الماضي تمامًا."],"exercises":["أدخل فعلًا من أفعال اليقين على جملة: «العلمُ نافعٌ» مع الضبط.","فرّق بين «رأيتُ الحقَّ واضحًا» و«رأيتُ القمرَ ساطعًا».","أعرب: «جعلَ النجّارُ الخشبَ بابًا»."],"levels":{"easy":[{"type":"mcq","q":"ماذا تفعل «ظنّ وأخواتها» عند دخولها على الجملة الاسمية؟","options":["ترفع المبتدأ وتنصب الخبر","تنصب المبتدأ مفعولًا أول والخبر مفعولًا ثانيًا","تجرّ الاسمين","تنصب مفعولًا واحدًا فقط"],"answer":1,"why":"ظنّ وأخواتها تنصب مفعولين أصلهما المبتدأ والخبر."},{"type":"mcq","q":"أيُّ الأفعال الآتية من أفعال اليقين؟","options":["ظنَّ","عَلِمَ","جَعَلَ","زَعَمَ"],"answer":1,"why":"عَلِمَ ورأى ووجد وألفى من أفعال اليقين."},{"type":"mcq","q":"أيُّ الأفعال الآتية من أفعال التحويل؟","options":["حَسِبَ","خَالَ","صَيَّرَ","عَلِمَ"],"answer":2,"why":"جعل وصيّر واتخذ وردّ من أفعال التحويل."},{"type":"mcq","q":"أين المفعول به الأول في: «جعلَ النجّارُ الخشبَ بابًا»؟","options":["النجّارُ","الخشبَ","بابًا","جعلَ"],"answer":1,"why":"النجار فاعل، والخشب مفعول به أول، وبابًا مفعول به ثانٍ."}],"medium":[{"type":"mcq","q":"ما إعراب «ساطعًا» في جملة: «رأيتُ القمرَ ساطعًا»؟","options":["مفعول به ثانٍ","حال منصوبة","مبتدأ","نعت مرفوع"],"answer":1,"why":"«رأى» هنا بصرية (بالعين) تنصب مفعولًا واحدًا، و«ساطعًا» حال."},{"type":"tfr","q":"إذا حذفنا الفعل والفاعل من «علمتُ الصدقَ منجاةً» بقيت جملة اسمية تامة (الصدقُ منجاةٌ).","answer":true,"reasons":["لأن المفعولين في ظنّ وأخواتها أصلهما المبتدأ والخبر","لأنها تتحول إلى جملة فعلية","لأن المعنى يختلّ تمامًا"],"reason":0},{"type":"essay","q":"أدخل «علمتُ» على جملة «المهندسونَ مبدعونَ» مع تغيير ما يلزم.","model":"علمتُ المهندسينَ مبدعينَ. (نُصبا بالياء لأنهما جمع مذكر سالم)."},{"type":"tfr","q":"الفعل «وَجَدَ» في جملة «وجدَ الطالبُ قلمَهُ» ينصب مفعولين.","answer":false,"reasons":["لأنه بمعنى عثر على شيء ضائع فينصب مفعولًا به واحدًا فقط (قلمَهُ)","لأنه من أفعال التحويل","لأنه فعل لازم"],"reason":0},{"type":"mcq","q":"أيُّ جملةٍ مما يأتي فيها «رأى» قلبية تنصب مفعولين؟","options":["رأيتُ العصفورَ فوق الشجرة","رأيتُ الحقَّ واضحًا","رأيتُ صديقي في السوق","رأيتُ السيارةَ مسرعةً"],"answer":1,"why":"«رأيتُ الحقَّ واضحًا» بمعنى علمتُ وأدركتُ بعقلي، فتنصب مفعولين."},{"type":"essay","q":"أعرب: «اتّخذتُ الكتابَ صديقًا».","model":"اتّخذتُ: فعل ماضٍ والتاء فاعل. الكتابَ: مفعول به أول منصوب بالفتحة. صديقًا: مفعول به ثانٍ منصوب بالفتحة."},{"type":"tfr","q":"يعمل المضارع والأمر من «ظنّ وأخواتها» عمل الماضي في نصب مفعولين.","answer":true,"reasons":["لأننا نقول: أظنُّ الجوَّ باردًا، واجعلِ العلمَ هدفَكَ","لأنها لا تعمل إلا في الماضي فقط","لأن المضارع يرفع المفعولين"],"reason":0}],"hard":[{"type":"mcq","q":"ما الجملة الصحيحة نحويًّا بعد إدخال «ظنَّ» على «الطالبانِ مجتهدانِ»؟","options":["ظنَّ المعلمُ الطالبانِ مجتهدانِ","ظنَّ المعلمُ الطالبَينِ مجتهدَينِ","ظنَّ المعلمُ الطالبَينِ مجتهدانِ","ظنَّ المعلمُ الطالبانِ مجتهدَينِ"],"answer":1,"why":"المثنى يُنصب بالياء في المفعولين الأول والثاني."},{"type":"essay","q":"فرّق إعرابيًا بين «وجدتُ» في: (١) وجدتُ الصبرَ جميلًا. (٢) وجدتُ المفتاحَ.","model":"في (١) «وجد» قلبية بمعنى علم تنصب مفعولين (الصبرَ، جميلًا). وفي (٢) بمعنى عثر تنصب مفعولًا واحدًا (المفتاحَ)."},{"type":"tfr","q":"في قوله تعالى: ﴿وَوَجَدَكَ ضَالًّا فَهَدَىٰ﴾، الكاف مفعول به أول و«ضالًّا» مفعول به ثانٍ.","answer":true,"reasons":["لأن «وجد» هنا من أفعال اليقين نصبت الضمير المتصل الكاف مفعولًا أول و«ضالًّا» مفعولًا ثانيًا","لأن «وجد» فعل لازم","لأن الكاف فاعل"],"reason":0},{"type":"mcq","q":"أيُّ الأفعال الآتية يدلّ على الظن والرجحان؟","options":["أَلْفَى","صَيَّرَ","خَالَ","اتَّخَذَ"],"answer":2,"why":"خَالَ وظنّ وحسب وزعم من أفعال الظن والرجحان."},{"type":"essay","q":"احذف الفعل والفاعل من: «ألفى الباحثُ المعلومةَ دقيقةً» واكتب الجملة مضبوطةً بالشكل.","model":"المعلومةُ دقيقةٌ. (تعود مبتدأ وخبرًا مرفوعين بالضمة)."},{"type":"tfr","q":"الفعل «زَعَمَ» يُصنّف ضمن أفعال اليقين المؤكّد.","answer":false,"reasons":["لأن «زعم» من أفعال الظن والرجحان لا اليقين","لأنه من أفعال التحويل","لأنه فعل لازم"],"reason":0},{"type":"mcq","q":"ما نوع المفعول به الثاني في جملة: «علمتُ الطالبَ يجتهدُ»؟","options":["مفرد","جملة فعلية في محل نصب","شبه جملة","حال"],"answer":1,"why":"قد يأتي المفعول الثاني جملة فعلية في محل نصب تمامًا كالخبر."},{"type":"essay","q":"صوّب الخطأ النحوي في: «حسبتُ اللاعبونَ متعبونَ».","model":"حسبتُ اللاعبينَ متعبينَ. (لأنهما مفعول به أول وثانٍ منصوبان بالياء)."},{"type":"tfr","q":"تنصب «ظنّ وأخواتها» المفعولين حتى لو كان المفعول الأول ضميرًا متصلًا مثل «علمتُكَ صادقًا».","answer":true,"reasons":["لأن الكاف ضمير متصل مبني في محل نصب مفعول به أول، وصادقًا مفعول به ثانٍ","لأن الضمائر لا تقع مفعولًا به","لأن الكاف فاعل"],"reason":0},{"type":"essay","q":"اذكر أقسام «ظنّ وأخواتها» الثلاثة ومثّل بجملة تامة لكل قسم.","model":"اليقين: علمتُ الحقَّ منتصرًا. الظن: ظننتُ السفرَ قريبًا. التحويل: جعلَ اللهُ الصعبَ سهلًا."}]}},
  {"id":"g9-arabic-1-u3-3","grade":"g9","subject":"arabic","term":1,"unit":3,"no":3,"title":"الأنشطة الإملائية: تنوين الهمزة المتطرفة","summary":"شرح متحرك لقواعد تنوين الفتح في الكلمات المنتهية بهمزة متطرفة بجميع حالاتها، ثم أنشطة بثلاثة مستويات.","page":"lesson-tanween-final-hamza.html","video":"","pdf":"","notes":["في تنوين الضم والكسر لا تتغيّر صورة الهمزة المتطرفة (سماءٌ، سماءٍ، جزءٌ، جزءٍ).","التغيير يظهر فقط في «تنوين الفتح (النصب)» بحسب ما يسبق الهمزة.","الحالة ١: إذا كانت الهمزة على ألف (ملجأً) أو قبلها ألف مدّ (سماءً، مساءً) نضع التنوين على الهمزة ولا نزيد ألفًا بعدها.","الحالة ٢: إذا كانت الهمزة على السطر وقبلها حرف لا يتصل بما بعده (د، ذ، ر، ز، و) نزيد ألف التنوين وتبقى على السطر (جزءًا، هدوءًا، بدءًا).","الحالة ٣: إذا كانت الهمزة على السطر وقبلها حرف يتصل بما بعده (ب، ف، ي، ط...) تُكتب على نبرة ثم نزيد ألف التنوين (شيئًا، عبئًا، دفئًا، بطئًا).","الحالة ٤: إذا كانت الهمزة على ياء (شاطئًا) أو واو (تباطؤًا) نزيد ألف التنوين بعدها بشكل عادي."],"exercises":["نوّن الكلمات الآتية بتنوين الفتح: سماء، جزء، شيء، ملجأ، هدوء، شاطئ.","علّل لماذا لم نزد ألفًا بعد الهمزة في «مساءً» بينما زدناها في «جزءًا».","صوّب الخطأ الإملائي في: «رأيتُ شيأً جميلًا في سماءًا صافية»."],"levels":{"easy":[{"type":"mcq","q":"أيُّ كتابةٍ مما يأتي صحيحة لكلمة «سماء» منوّنةً بالفتح؟","options":["سماءًا","سماءً","سمائًا","سماأً"],"answer":1,"why":"لا تقع الهمزة بين ألفين، فنضع التنوين فوقها دون ألف."},{"type":"mcq","q":"كيف تُكتب كلمة «شيء» عند تنوينها بالفتح؟","options":["شيءًا","شيئًا","شيءً","شيأً"],"answer":1,"why":"الياء تتصل بما بعدها فتُكتب الهمزة على نبرة ثم ألف التنوين."},{"type":"mcq","q":"كيف تُكتب كلمة «جزء» عند تنوينها بالفتح؟","options":["جزئًا","جزءًا","جزءً","جزأً"],"answer":1,"why":"الزاي لا تتصل بما بعدها فتبقى الهمزة على السطر وتُزاد ألف التنوين."},{"type":"mcq","q":"كيف تُكتب كلمة «خطأ» عند تنوينها بالفتح؟","options":["خطأً","خطأًا","خطئًا","خطءًا"],"answer":0,"why":"الهمزة مرسومة على ألف أصلًا فلا نزيد ألفًا بعدها."}],"medium":[{"type":"mcq","q":"لماذا لم نزد ألف التنوين بعد الهمزة في «بِنَاءً»؟","options":["لأنها مرفوعة","لأن الهمزة لا تقع بين ألفين","لأنها همزة وصل","لأنها على واو"],"answer":1,"why":"قبلها ألف مدّ فلا نضع ألفًا ثانية بعدها."},{"type":"tfr","q":"تُكتب كلمة «هدوء» عند تنوين الفتح «هدوئًا» على نبرة.","answer":false,"reasons":["لأن الواو لا تتصل بما بعدها فتُكتب «هدوءًا» على السطر مع ألف","لأن قبلها ألفًا","لأنها لا تُنوَّن أبدًا"],"reason":0},{"type":"essay","q":"نوّن الكلمات الآتية بالفتح: عِبْء، مَسَاء، بَدْء، مَلْجَأ.","model":"عِبْئًا، مَسَاءً، بَدْءًا، مَلْجَأً."},{"type":"tfr","q":"في تنوين الضم والكسر تبقى صورة الهمزة المتطرفة كما هي دون تغيير.","answer":true,"reasons":["لأن التغيير يرتبط بألف تنوين النصب فقط، فنقول: شيءٌ وشيءٍ","لأن تنوين الضم يضيف ألفًا","لأن الكلمات المنتهية بهمزة لا تُرفع"],"reason":0},{"type":"mcq","q":"أيُّ الكلمات الآتية تُكتب همزتها على نبرة عند تنوين الفتح؟","options":["ضَوْء","دِفْء","سَمَاء","نَبَأ"],"answer":1,"why":"الفاء في «دِفْء» تتصل بما بعدها فتُكتب «دِفْئًا»."},{"type":"essay","q":"علّل اختلاف كتابة الهمزة عند التنوين بين «جُزْءًا» و«عِبْئًا».","model":"في «جزءًا» الحرف قبل الهمزة (الزاي) لا يتصل بما بعده فبقيت على السطر، أما في «عبئًا» فالباء تتصل بالألف فكُتبت الهمزة على نبرة."},{"type":"tfr","q":"تُكتب كلمة «جَرِيء» عند تنوين الفتح «جَرِيئًا».","answer":true,"reasons":["لأن الياء قبل الهمزة تتصل بألف التنوين فتُكتب الهمزة على نبرة","لأن قبلها واوًا","لأنها مرسومة على ألف"],"reason":0}],"hard":[{"type":"mcq","q":"أيُّ مجموعةٍ مما يأتي كُتبت جميع كلماتها كتابةً إملائيةً صحيحة؟","options":["مساءً، ضوءًا، شيئًا، ملجأً","مساءًا، ضوئًا، شيءًا، ملجأًا","مساءً، ضوئًا، شيئًا، خطأًا","بناءًا، جزءًا، دفئًا، نبأً"],"answer":0,"why":"كل كلمة فيها طبّقت القاعدة بدقة."},{"type":"essay","q":"صوّب الأخطاء في الجملة: «رأيتُ ضوئًا ساطعًا في سماءًا صافيةً ولم أجد شيءًا مخيفًا».","model":"رأيتُ ضوءًا ساطعًا في سماءً صافيةً ولم أجد شيئًا مخيفًا."},{"type":"tfr","q":"تُكتب كلمة «لُؤْلُؤ» عند تنوين الفتح «لُؤْلُؤًا» بزيادة ألف التنوين.","answer":true,"reasons":["لأن الهمزة على واو وليست على ألف ولا مسبوقة بألف فتُزاد ألف التنوين","لأن الواو تتصل بالألف","لأن قبلها ألفًا"],"reason":0},{"type":"mcq","q":"أيُّ جملةٍ مما يأتي خاليةٌ من الخطأ الإملائي؟","options":["اتّخذتُ مبدأًا كريمًا.","أنجزتُ جزءً كبيرًا من العمل.","شعرتُ بدفءٍ فوجدتُ ملجأً آمنًا.","قرأتُ نبأًا سعيدًا."],"answer":2,"why":"«بدفءٍ» مجرورة فلا تتغير، و«ملجأً» فوق ألف فلا تُزاد ألف."},{"type":"essay","q":"نوّن الكلمات الآتية بالفتح مع ذكر السبب لكل كلمة: بُطْء، هَواء، رِدْء، قارِئ.","model":"بُطْئًا (الطاء تتصل)، هَواءً (قبلها ألف)، رِدْءًا (الدال لا تتصل)، قارِئًا (مرسومة على ياء فتُزاد ألف)."},{"type":"tfr","q":"الحروف التي لا تتصل بما بعدها هي: أ، د، ذ، ر، ز، و.","answer":true,"reasons":["لذلك إذا سبقت الهمزة المتطرفة على السطر بواحد منها (غير الألف) تبقى على السطر عند تنوين الفتح","لأن كل حروف العربية تتصل بما بعدها","لأن الباء والياء لا تتصلان"],"reason":0},{"type":"mcq","q":"ما الصواب عند تنوين كلمة «هَنِيء» بالفتح؟","options":["هنيءًا","هنيئًا","هنيءً","هنيأً"],"answer":1,"why":"الياء تتصل بألف التنوين فتُكتب الهمزة على نبرة."},{"type":"essay","q":"اشرح قاعدة «عدم وقوع الهمزة بين ألفين» بمثالين.","model":"إذا سبقت الهمزة المتطرفة بألف مدّ مثل «سماء» و«مساء» لا نزيد ألف تنوين بعدها فنكتبها «سماءً» و«مساءً»."},{"type":"tfr","q":"في كلمة «شاطِئًا» حُوّلت الهمزة من السطر إلى نبرة.","answer":false,"reasons":["لأنها في «شاطئ» مرسومة أصلًا على ياء قبل التنوين وزيدت ألف التنوين بعدها","لأنها كانت على واو","لأن قبلها ألفًا"],"reason":0},{"type":"essay","q":"اكتب جملتين من إنشائك تشتملان على أربع كلمات منوّنة بالفتح تمثّل حالات تنوين الهمزة المتطرفة الأربع.","model":"مثال: قضيتُ مساءً هادئًا، وقرأتُ جزءًا من كتابٍ يحمل مبدأً ساميًا وشيئًا من الحكمة."}]}},
  {"id":"g9-arabic-1-u3-4","grade":"g9","subject":"arabic","term":1,"unit":3,"no":4,"title":"التعبير: تصميم موضوع وكتابته","summary":"شرح متحرك لمرحلة تحويل مخطّط الموضوع إلى نص مكتوب متماسك مع المراجعة والتحرير، ثم أنشطة بثلاثة مستويات.","page":"lesson-topic-design-writing.html","video":"","pdf":"","notes":["كتابة الموضوع تمرّ بمرحلتين متكاملتين: التصميم (المخطّط)، ثم التحرير (الكتابة والتوسيع).","نحوّل كل فكرة فرعية في المخطّط إلى فقرة مستقلة تبدأ بجملة مفتاحية وتُدعَّم بالأمثلة والشواهد.","نستخدم أدوات الربط بين الفقرات (ومن ناحية أخرى، وعلاوةً على ذلك، وختامًا) لتحقيق التسلسل المنطقي.","نحرص على تنوّع الأساليب (الخبر، الاستفهام، التعجب) ووضوح الألفاظ والبعد عن العامية.","نوظّف علامات الترقيم بدقّة ونراعي الشكل الخارجي (العنوان، الفراغ في أول كل فقرة).","المراجعة النهائية خطوة أساسية لتصحيح الأخطاء الإملائية والنحوية وحذف التكرار."],"exercises":["كيف نحوّل الفكرة الفرعية في المخطّط إلى فقرة متكاملة عند الكتابة؟","اذكر ثلاث أدوات ربط تُستخدم للانتقال بين الفقرات.","صمّم واكتب موضوعًا قصيرًا من ثلاث فقرات عن «برّ الوالدين»."],"levels":{"easy":[{"type":"mcq","q":"ماذا تصبح كلّ فكرة فرعية في المخطّط عند كتابة الموضوع؟","options":["فقرة مستقلة","كلمة واحدة","عنوانًا جديدًا","تُحذف عند الكتابة"],"answer":0,"why":"كل فكرة فرعية تُوسَّع في فقرة مستقلة متماسكة."},{"type":"mcq","q":"أيُّ عبارةٍ مما يأتي من روابط الانتقال للخاتمة؟","options":["أولًا","وخلاصة القول","لأن","أين"],"answer":1,"why":"«وخلاصة القول» و«وفي الختام» تمهّدان للخاتمة."},{"type":"mcq","q":"ما الخطوة الأخيرة بعد الانتهاء من كتابة الموضوع؟","options":["المراجعة والتحرير","حذف المقدمة","ترك النص بلا قراءة","مسح الترقيم"],"answer":0,"why":"المراجعة تضمن سلامة اللغة والإملاء وتسلسل الأفكار."},{"type":"mcq","q":"بماذا نُحيط الشاهد القرآني أو الحديث أو بيت الشعر داخل النص؟","options":["بلا علامات","بعلامتَي تنصيص أو قوسين","بخطوط عشوائية","بعلامات استفهام"],"answer":1,"why":"وضع الشاهد بين علامتَي تنصيص يميّزه ويحفظ أمانة النقل."}],"medium":[{"type":"mcq","q":"كيف نوسّع الفكرة الفرعية داخل الفقرة دون حشو أو تكرار؟","options":["بإعادة الجملة نفسها ثلاث مرات","بالإجابة عن أسئلة: لماذا؟ وكيف؟ وما النتيجة؟","بكتابة كلمات عامية","بتقليص الفقرة لسطر واحد"],"answer":1,"why":"طرح الأسئلة الذكية يولّد تفاصيل وأسبابًا وأمثلة ثرية."},{"type":"tfr","q":"يُفضَّل تنويع الأساليب بين الخبر والاستفهام والتعجب لإبعاد الملل عن القارئ.","answer":true,"reasons":["لأن تنويع الأساليب يُضفي حيوية وتشويقًا على النص","لأن الأسلوب الخبري ممنوع","لأن الاستفهام لا يُستخدم في التعبير"],"reason":0},{"type":"essay","q":"اذكر أربع أدوات ربط تُستخدم للانتقال بين فقرات الموضوع.","model":"وعلاوةً على ذلك، ومن ناحية أخرى، وبالمقابل، غير أن، وخلاصة القول، وفي الختام."},{"type":"tfr","q":"يكفي وضع الشاهد في الفقرة دون تمهيد له أو ربطه بالفكرة.","answer":false,"reasons":["لأن الشاهد يجب أن يُمهَّد له ويُربط بالفكرة التي يدعمها ليخدم الإقناع","لأن الشواهد لا علاقة لها بالأفكار","لأن الشواهد تُوضع في العنوان"],"reason":0},{"type":"mcq","q":"أين نكتب عنوان الموضوع عادةً؟","options":["في نهاية الصفحة","في منتصف السطر الأول","داخل الخاتمة","في الهامش"],"answer":1,"why":"كتابة العنوان في منتصف السطر الأول جزء من التنظيم الشكلي."},{"type":"essay","q":"ما الأشياء الأربعة التي تتفحّصها أثناء مرحلة المراجعة النهائية؟","model":"١) سلامة الإملاء والنحو. ٢) تسلسل الأفكار وترابطها. ٣) علامات الترقيم والروابط. ٤) خلوّ النص من التكرار والحشو."},{"type":"tfr","q":"استخدام الألفاظ العامية في موضوع التعبير يرفع من قيمته الأدبية.","answer":false,"reasons":["لأن موضوع التعبير يُكتب بلغة عربية فصيحة سلسة وواضحة","لأن العامية هي الفصحى","لأن الفصحى لا تُفهم"],"reason":0}],"hard":[{"type":"mcq","q":"أيُّ أداة ربط مناسبة عند الانتقال إلى فكرةٍ مقابلةٍ أو مختلفة؟","options":["وعلاوة على ذلك","وعلى النقيض من ذلك","وفي الختام","وأولًا"],"answer":1,"why":"«وعلى النقيض من ذلك» و«غير أن» تُستعملان للمقابلة."},{"type":"essay","q":"وسّع الفكرة الآتية إلى فقرة من ثلاث جمل باستخدام (لماذا؟ وما النتيجة؟): «الحفاظ على نظافة المدرسة واجب كل طالب».","model":"الحفاظ على نظافة المدرسة واجب كل طالب؛ لأن البيئة النظيفة تحمي صحتنا وتبعث النشاط والراحة في النفوس أثناء التعلم. وعندما يتعاون الجميع في النظافة تصبح مدرستنا مكانًا جميلًا نفخر به."},{"type":"tfr","q":"التخطيط الجيّد يختصر وقت الكتابة ويمنع توقّف الطالب حائرًا في منتصف الموضوع.","answer":true,"reasons":["لأن الأفكار والشواهد تكون مرتّبة أمامه مسبقًا فينتقل بسلاسة من فقرة لأخرى","لأن التخطيط يُلغي الكتابة","لأن التخطيط يطيل وقت الحيرة"],"reason":0},{"type":"mcq","q":"ما أثر وجود تشبيه مناسب في موضوع التعبير مثل «التطوّع بذرة خيرٍ تثمر عطاءً»؟","options":["يُضعف المعنى","يُجمّل الأسلوب ويقرّب الفكرة للقارئ","يُعدّ خطأً نحويًا","يُشتّت الموضوع"],"answer":1,"why":"التصوير البلاغي المعتدل يزيد النص جمالًا وتأثيرًا."},{"type":"essay","q":"مهّد للآية الكريمة ﴿وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَىٰ﴾ بجملة مناسبة داخل فقرة عن التعاون.","model":"مثال: وقد دعا ديننا الحنيف إلى تكاتف أفراد المجتمع في أعمال الخير بقوله تعالى: ﴿وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَىٰ﴾."},{"type":"tfr","q":"مرحلة التحرير والكتابة تسبق مرحلة التصميم والتخطيط.","answer":false,"reasons":["لأن التصميم والتخطيط يأتيان أولًا لرسم مسار الأفكار ثم تأتي الكتابة والتحرير","لأنهما غير مرتبطتين","لأن التحرير هو العنوان فقط"],"reason":0},{"type":"mcq","q":"إذا اكتشفتَ أثناء المراجعة أن فقرتين تكرّران المعنى نفسه، فماذا تفعل؟","options":["تتركهما كما هما","تدمجهما أو تستبدل إحداهما بفكرة جديدة مرتبطة بالموضوع","تحذف الموضوع كله","تضيف فقرة ثالثة مكررة"],"answer":1,"why":"إزالة التكرار تحافظ على قوة الموضوع وتماسكه."},{"type":"essay","q":"قارن بين «التصميم» و«التحرير» في كتابة الموضوع.","model":"التصميم هو وضع الخطة والعناصر والأفكار الرئيسة والفرعية بإيجاز، أما التحرير فهو تحويل تلك الخطة إلى فقرات مكتوبة موسّعة بلغة فصيحة وروابط وترقيم."},{"type":"tfr","q":"ترك مسافة بمقدار كلمة في بداية كل فقرة يساعد القارئ على التمييز البصري بين الأفكار.","answer":true,"reasons":["لأنه يحدّد بوضوح بداية كل فكرة فرعية جديدة في الصفحة","لأنه يقلل عدد الكلمات","لأنه يُستخدم في الشعر فقط"],"reason":0},{"type":"essay","q":"صمّم ثم اكتب فقرتين موجزتين (مقدمة وجوهر) عن «أهمية استثمار الإجازة الصيفية».","model":"مثال: الإجازة الصيفية فرصة ذهبية لتجديد النشاط وتطوير المهارات، فكيف نستثمرها بذكاء؟ يمكن للطالب أن يوازن فيها بين الراحة وتعلّم مهارة جديدة كالقراءة أو البرمجة أو الرياضة؛ مما يعود عليه بالنفع والمتعة معًا."}]}},
  {"id":"g9-arabic-1-u3-5","grade":"g9","subject":"arabic","term":1,"unit":3,"no":5,"title":"النص الأدبي: لوحة الزمن","summary":"شرح متحرك لقصيدة «لوحة الزمن» لأبي الطيب المتنبي وأفكارها وحكمها وصورها الجمالية، ثم أنشطة بثلاثة مستويات.","page":"lesson-lawhat-alzaman.html","video":"","pdf":"","notes":["قائل قصيدة «لوحة الزمن» هو أبو الطيب المتنبي، وغرضها الحكمة والتأمل في الحياة وتقلّب الدهر.","يؤكّد الشاعر في المطلع أن الناس جميعًا عانوا من تقلّب الزمان ومفارقاته عبر العصور.","الزمان يجمع بين الفرح والحزن، فلا يدوم صفوه لأحد، والغدر والظلم من صور اختلال القيم بين الناس.","يشبّه الشاعر شجاعة النفس وإقدامها بصفات الكرام، ويدعو إلى الثبات أمام الشدائد.","تزخر القصيدة بالمحسنات البديعية كالطباق (سرّ / ساء، الصغير / الكبير) لإبراز تناقضات الحياة.","أسلوبها حكيمٌ جزلٌ يجمع بين التجربة الذاتية والحكمة الإنسانية الشاملة."],"exercises":["ما الفكرة العامة التي تدور حولها قصيدة «لوحة الزمن»؟","استخرج طباقًا من أبيات القصيدة وبيّن أثره في المعنى.","بماذا يوصي المتنبي الإنسان في مواجهة تقلّبات الزمان؟"],"levels":{"easy":[{"type":"mcq","q":"من قائل قصيدة «لوحة الزمن»؟","options":["أبو تمام","أبو الطيب المتنبي","شرف الدين البوصيري","الجاحظ"],"answer":1,"why":"القصيدة من أشهر قصائد الحكمة لأبي الطيب المتنبي."},{"type":"mcq","q":"ما الغرض الشعري لقصيدة «لوحة الزمن»؟","options":["الحكمة والتأمل في الحياة","الرثاء","المدح النبوي","الوصف الطبيعي"],"answer":0,"why":"تتناول تقلّبات الزمن وأحوال الناس وتدعو للشجاعة وعزّة النفس."},{"type":"mcq","q":"ما معنى «عناهم» في قول المتنبي «وعناهم من شأنه ما عنانا»؟","options":["أفرحهم","أتعبهم وأهمّهم","أغناهم","أضحكهم"],"answer":1,"why":"عناهم أي أتعبهم وأشقاهم من تقلّب الزمن."},{"type":"mcq","q":"ما العلاقة البلاغية بين «الصغير» و«العظيم»؟","options":["ترادف","طباق","سجع","جناس"],"answer":1,"why":"كلمتان متضادتان بينهما طباق يوضّح المعنى ويبرزه."}],"medium":[{"type":"mcq","q":"ما نوع الصورة الفنية في قول الشاعر: «صحبَ الناسُ ذا الزمانا»؟","options":["استعارة مكنية تشخّص الزمان كصاحب","تشبيه بليغ","طباق","أسلوب نهي"],"answer":0,"why":"شبّه الزمان بإنسان يُصاحَب وحذف المشبّه به ورمز له بـ «صحب»."},{"type":"tfr","q":"يرى المتنبي أن تقلّبات الزمن أمرٌ يختصّ بجيله فقط دون الأجيال السابقة.","answer":false,"reasons":["لأنه قال «صحب الناس قبلنا ذا الزمانا» مؤكدًا أن الأجيال كلها عانت تقلّب الدهر","لأنه لم يتحدث عن الزمن","لأنه قال إن الزمن ثابت لا يتغير"],"reason":0},{"type":"essay","q":"اشرح البيت: «وتعظمُ في عينِ الصغيرِ صغارُها / وتصغرُ في عينِ العظيمِ العظائمُ».","model":"الأمور البسيطة تبدو كبيرةً وصعبةً أمام ضعيف الهمّة، أما صاحب الهمّة العالية فتهون أمامه أعظم الصعاب."},{"type":"tfr","q":"أكثر المتنبي من الطباق والمقابلة في القصيدة لإبراز تناقضات الحياة والناس.","answer":true,"reasons":["لأن المقارنة بين الأضداد (الفرح والحزن، الصغير والعظيم) تقوّي أثر الحكمة وتوضّح المعنى","لأن الطباق يضعف الشعر","لأنه لم يستخدم أي محسن بديعي"],"reason":0},{"type":"mcq","q":"بماذا يوصي المتنبي الإنسان في مواجهة الشدائد وتقلّب الزمن؟","options":["بالاستسلام والخوف","بالشجاعة والثبات وعلوّ الهمّة","بالانخداع بالمظاهر","بالابتعاد عن العمل"],"answer":1,"why":"يدعو إلى علوّ الهمّة والثبات وعزّة النفس."},{"type":"essay","q":"ما أثر تشخيص الزمان في قوله «صحبَ الناسُ ذا الزمانا»؟","model":"يجعل الزمان كائنًا حيًّا يُعاشَر، مما يقرّب صورة طول الخبرة بتقلّباته ومواقفه مع البشر."},{"type":"tfr","q":"تجمع عاطفة القصيدة بين التأمّل في تقلّب الدنيا وبين الاعتزاز بالنفس وعلوّ الهمّة.","answer":true,"reasons":["لأن الشاعر يتأمل مفارقات الدهر ثم يرتفع فوقها بعزّة النفس والشجاعة","لأن العاطفة هي الاستسلام فقط","لأن القصيدة فكاهية ساخرة"],"reason":0}],"hard":[{"type":"mcq","q":"ما دلالة «ذا» في قول المتنبي «صحبَ الناسُ قبلنا ذا الزمانا»؟","options":["اسم إشارة بمعنى هذا الزمان","حرف جر","فعل ماضٍ","أداة استفهام"],"answer":0,"why":"«ذا» اسم إشارة مبني بمعنى «هذا» يشير إلى الزمان المعروف بتقلّبه."},{"type":"essay","q":"كيف تبرز القصيدة قيمة الوعي والفطنة في التعامل مع الناس؟","model":"تنبّه إلى أن طبائع الناس متفاوتة بين الوفاء والغدر، وأن العاقل لا ينخدع بالمظاهر بل يزن الناس بأخلاقهم ومروءتهم."},{"type":"tfr","q":"يُعدّ بيت «وتعظم في عين الصغير صغارها...» مثالًا على المقابلة البلاغية.","answer":true,"reasons":["لأنه قابل بين (تعظم/تصغر) و(الصغير/العظيم) و(صغارها/العظائم) في الشطرين","لأنه يحتوي على ترادف فقط","لأنه أسلوب استفهام"],"reason":0},{"type":"mcq","q":"لماذا سمّي الدرس بـ «لوحة الزمن»؟","options":["لأن المتنبي رسم بالكلمات صورةً شاملةً لتقلّبات الزمن وأحوال البشر فيه","لأنها تتحدث عن رسّام مشهور","لأنها تصف ساعةً حائطية","لأنها قصة قصيرة"],"answer":0,"why":"الأبيات تشكّل لوحةً شعريةً معبّرةً عن الحياة وتقلّباتها."},{"type":"essay","q":"استخلص قيمتين إيجابيتين من قصيدة «لوحة الزمن» وبيّن كيف تطبّقهما في حياتك الدراسية.","model":"١) علوّ الهمّة: عدم الخوف من المواد الصعبة ومواجهتها بالاجتهاد. ٢) الصبر والثبات: عدم الاستسلام عند أول تعثّر بل الاستمرار حتى النجاح."},{"type":"tfr","q":"تقاس عظمة الإنسان عند المتنبي بكبر همّته وثباته لا بصغر مشكلاته.","answer":true,"reasons":["لأن العظيم تصغر في عينه العظائم بفضل همّته وعزيمته","لأن المتنبي يقيس العظمة بالمال فقط","لأنه يدعو للخوف من الصعاب"],"reason":0},{"type":"mcq","q":"أيُّ سمةٍ من الآتية ليست من خصائص أسلوب قصيدة «لوحة الزمن»؟","options":["جزالة الألفاظ","تكثيف الحكمة","الاعتماد على الألفاظ العامية","توظيف الطباق والمقابلة"],"answer":2,"why":"القصيدة مكتوبة بلغة عربية فصيحة جزلة رفيعة."},{"type":"essay","q":"قارن بين موقف الجبان وموقف الشجاع أمام الشدائد كما صوّره المتنبي.","model":"الجبان يستعظم الصغائر ويخاف قبل وقوع الخطر، أما الشجاع صاحب الهمّة العالية فتصغر أمامه العظائم ويواجهها بثبات."},{"type":"tfr","q":"قوله «وعناهم من شأنه ما عنانا» يبعث التسلية والمواساة للنفس.","answer":true,"reasons":["لأن معرفة أن تقلّب الزمن سنةٌ شملت كل الأجيال تخفّف من وقع الشدائد","لأنه يدعو لليأس","لأنه يصف فرحًا دائمًا"],"reason":0},{"type":"essay","q":"اكتب شرحًا أدبيًّا موجزًا لبيت المطلع «صحبَ الناسُ قبلنا ذا الزمانا / وعناهم من شأنه ما عنانا».","model":"عاش الناس قبلنا مع هذا الزمن وتقلّباته، وأصابهم من متاعبه ومفارقاته مثل ما يصيبنا اليوم؛ فهذه طبيعة الدنيا التي لا تصفو لأحد."}]}},
  {"id":"g9-arabic-1-u4-1","grade":"g9","subject":"arabic","term":1,"unit":4,"no":1,"title":"القراءة: قرآن الفجر","summary":"شرح متحرك لنص «قرآن الفجر» وأفكاره وصوره الأدبية وقيمه الروحية، ثم أنشطة بثلاثة مستويات.","page":"lesson-quran-alfajr.html","video":"","pdf":"","notes":["يستلهم النص عنوانه من قوله تعالى: ﴿إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا﴾ (سورة الإسراء).","يصف النص جمال لحظة الفجر حين ينقشع الظلام ويعمّ السكون والصفاء في الكون.","في وقت الفجر يكون الذهن صافيًا والقلب حاضرًا، فتترك تلاوة القرآن أثرًا عميقًا في النفس.","يربط النص بين صلاة الفجر والنشاط والبركة في يوم الإنسان وعمله.","يمتاز أسلوب النص بالعاطفة الروحية الصادقة والصور الحسية (الضوء، النسيم، السكون، صوت التلاوة).","يدعو النص إلى اغتنام ساعات البكور والبعد عن الكسل والسهر غير المفيد."],"exercises":["ما الآية الكريمة التي استُلهم منها عنوان الدرس؟","لماذا يكون أثر تلاوة القرآن في وقت الفجر أعمق في النفس؟","اذكر صورتين جماليتين تبرزان روعة وقت الفجر."],"levels":{"easy":[{"type":"mcq","q":"من أي سورة استُلهم عنوان درس «قرآن الفجر»؟","options":["الفاتحة","الإسراء","الكهف","يوسف"],"answer":1,"why":"قال تعالى في سورة الإسراء: ﴿إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا﴾."},{"type":"mcq","q":"من الذين يشهدون قرآن الفجر؟","options":["ملائكة الليل والنهار","الشعراء فقط","التجار","المسافرون"],"answer":0,"why":"تلتقي ملائكة الليل وملائكة النهار عند صلاة الفجر."},{"type":"mcq","q":"ما أثر البكور والاستيقاظ مبكرًا في يوم الإنسان؟","options":["الكسل والتعب","البركة في الوقت والنشاط والإنجاز","ضياع الوقت","تشتّت الذهن"],"answer":1,"why":"قال ﷺ: «اللهم بارك لأمتي في بكورها»."},{"type":"mcq","q":"ما العلاقة البلاغية بين «الظلام» و«النور» في النص؟","options":["ترادف","طباق","جناس","سجع"],"answer":1,"why":"طباق يبرز جمال انبلاج الفجر وتبدّد الظلام."}],"medium":[{"type":"mcq","q":"لماذا تكون تلاوة القرآن والمذاكرة في الفجر أعمق أثرًا؟","options":["لصفاء الذهن وهدوء الكون وخلوّه من الضجيج","لأن الوقت قصير","لكثرة المشاغل","بسبب السهر"],"answer":0,"why":"يكون العقل مرتاحًا والنفس هادئة مستعدة للتدبر والفهم."},{"type":"tfr","q":"يقتصر أثر وقت الفجر على الجانب الروحي دون أي أثر في النشاط والعمل.","answer":false,"reasons":["لأنه يمنح بركةً في الوقت ونشاطًا في الجسد وإنجازًا في الدراسة والعمل","لأن العمل ممنوع صباحًا","لأن الفجر وقت النوم"],"reason":0},{"type":"essay","q":"صف مظهرين من مظاهر جمال الطبيعة عند انبلاج الفجر كما وردت في الدرس.","model":"تسلّل خيوط النور الأولى وسط الظلام، وهبوب النسيم النقي العليل، وسكون الكون واستعداد الطيور للطيران."},{"type":"tfr","q":"توظيف الصور الحسية (النور والنسيم وصوت التلاوة) يقرّب مشاعر النص إلى القارئ.","answer":true,"reasons":["لأنها تخاطب البصر والسمع والشعور فتجعل القارئ يعيش أجواء الفجر","لأنها تُضعف الأسلوب","لأنها تُستخدم في الشعر فقط"],"reason":0},{"type":"mcq","q":"ما العادة التي ينبغي للطالب تجنّبها ليستفيد من بركة الفجر؟","options":["القراءة","السهر الطويل غير المفيد","تنظيم الوقت","الرياضة الصباحية"],"answer":1,"why":"السهر الطويل يحرم الطالب من صلاة الفجر ونشاط البكور."},{"type":"essay","q":"اذكر اثنتين من سمات أسلوب نص «قرآن الفجر».","model":"صدق العاطفة الروحية، وجمال الصور الحسية الموحية، والتأثّر بألفاظ القرآن الكريم."},{"type":"tfr","q":"يرمز الفجر في الأدب إلى الأمل والتجدّد وبداية يومٍ جديد.","answer":true,"reasons":["لأن انقشاع الظلام بنور الصباح يبعث التفاؤل والطمأنينة","لأنه يرمز للغفلة","لأنه يرمز للنهاية"],"reason":0}],"hard":[{"type":"mcq","q":"ما دلالة تشبيه الكون عند الفجر بـ «محرابٍ هادئ»؟","options":["إيحاء بالخشوع والسكينة وقدسية اللحظة","وصف لبناء قديم","كثرة الضجيج","حرارة الجو"],"answer":0,"why":"المحراب موضع العبادة والسكينة، والتشبيه يبرز صفاء اللحظة وخشوعها."},{"type":"essay","q":"كيف توفّق كطالب بين الاستفادة من وقت الفجر وبين جدول مذاكرتك اليومي؟","model":"أنظم نومي مبكرًا، وأستيقظ لصلاة الفجر وتلاوة ورد قصير من القرآن، ثم أستثمر هدوء الصباح في مراجعة أهم الدروس بتركيز عالٍ."},{"type":"tfr","q":"تُعدّ لحظة الفجر نقطة التقاءٍ بين عالم الطبيعة الهادئ وعالم الروح الخاشع.","answer":true,"reasons":["لأن صفاء الطبيعة وسكونها يعينان القلب على الخشوع والتدبّر","لأن الطبيعة لا علاقة لها بالشعور","لأن الفجر وقت ضوضاء"],"reason":0},{"type":"mcq","q":"أيُّ حديثٍ شريفٍ يؤكّد القيمة العملية لوقت الفجر؟","options":["«اللهم بارك لأمتي في بكورها»","«المسلم من سلم المسلمون من لسانه»","«تبسمك في وجه أخيك صدقة»","«اطلبوا العلم»"],"answer":0,"why":"يدلّ الحديث صراحةً على البركة في ساعات الصباح الباكر."},{"type":"essay","q":"ما أثر الطباق بين «الظلام» و«الفجر» في إيصال رسالة النص؟","model":"يبرز التحوّل من السكون والغفلة إلى النور واليقظة والأمل، ويؤكّد أن بعد كل ظلامٍ فجرًا مشرقًا."},{"type":"tfr","q":"العاطفة السائدة في نص «قرآن الفجر» هي الحزن والتشاؤم.","answer":false,"reasons":["لأن العاطفة السائدة هي السكينة الإيمانية والأمل والطمأنينة","لأنه نص رثائي","لأنه نص هجائي"],"reason":0},{"type":"mcq","q":"أيُّ عبارةٍ مما يأتي تلخّص الرسالة التربوية للدرس؟","options":["السهر أساس التفوق","اغتنام ساعات البكور يصنع يومًا مباركًا ومنجزًا","القراءة في المساء فقط","الابتعاد عن التأمل"],"answer":1,"why":"النص يدعو لاستثمار الفجر روحيًا وعلميًا وعمليًا."},{"type":"essay","q":"فسّر قوله تعالى: ﴿إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا﴾ بأسلوبك.","model":"إن تلاوة القرآن في صلاة الفجر لحظةٌ مباركةٌ تحضرها وتشهدها ملائكة الليل والنهار معًا لعظم فضلها."},{"type":"tfr","q":"التأثّر بألفاظ القرآن الكريم ومعانيه يُكسب النص الأدبي رصانةً وجمالًا.","answer":true,"reasons":["لأن القرآن قمة الفصاحة والبيان فيمنح النص عمقًا وتأثيرًا روحيًا","لأنه يضعف الأسلوب","لأنه يمنع الصور الفنية"],"reason":0},{"type":"essay","q":"اكتب ثلاث جمل تصف فيها صباحًا عُمانيًّا هادئًا عند الفجر.","model":"مثال: عند الفجر تنساب خيوط النور فوق الجبال، ويهبّ نسيمٌ عليلٌ يحمل صوت الأذان وتلاوة القرآن، فتستيقظ القرية بنشاطٍ وأملٍ ليومٍ جديدٍ مبارك."}]}},
  {"id":"g9-arabic-1-u4-2","grade":"g9","subject":"arabic","term":1,"unit":4,"no":2,"title":"الأنشطة النحوية والصرفية: الأفعال المتعدية إلى مفعولين ليس أصلهما المبتدأ والخبر","summary":"شرح متحرك للأفعال المتعدية إلى مفعولين ليس أصلهما المبتدأ والخبر (أعطى وأخواتها) والفرق بينها وبين ظنّ وأخواتها، ثم أنشطة بثلاثة مستويات.","page":"lesson-aata-and-sisters.html","video":"","pdf":"","notes":["تنصب «أعطى وأخواتها» مفعولين ليس أصلهما المبتدأ والخبر.","أشهرها: أَعْطَى، مَنَحَ، وَهَبَ، كَسَا، أَلْبَسَ، مَنَعَ، سَأَلَ.","اختبار التمييز: إذا حذفتَ الفعل والفاعل لا تتكوّن جملة اسمية مفيدة (لا يصحّ: الفقيرُ صدقةٌ!).","مثال: «كسا الربيعُ الأرضَ خضرةً»؛ الأرضَ مفعول به أول، وخضرةً مفعول به ثانٍ.","يعمل المضارع والأمر منها عمل الماضي تمامًا (يمنحُ المعلمُ الطالبَ جائزةً).","عند بنائها للمجهول يصبح المفعول الأول نائب فاعل مرفوعًا، ويبقى المفعول الثاني منصوبًا (أُعْطِيَ الفقيرُ صدقةً)."],"exercises":["استخرج الفاعل والمفعولين في: «منحَ المعلمُ المتفوّقَ جائزةً».","قارن بين «علمتُ العلمَ نورًا» و«أعطيتُ الفقيرَ مالًا».","ابنِ الجملة الآتية للمجهول: «كسَا الربيعُ الأرضَ خضرةً»."],"levels":{"easy":[{"type":"mcq","q":"أيُّ الأفعال الآتية ينصب مفعولين ليس أصلهما المبتدأ والخبر؟","options":["عَلِمَ","وَهَبَ","ظَنَّ","صَيَّرَ"],"answer":1,"why":"وَهَبَ وأعطى ومنح وكسا تنصب مفعولين ليس أصلهما مبتدأ وخبرًا."},{"type":"mcq","q":"أين المفعول به الأول في: «منحَ المعلمُ الطالبَ جائزةً»؟","options":["المعلمُ","الطالبَ","جائزةً","منحَ"],"answer":1,"why":"المعلم فاعل، والطالب مفعول به أول، وجائزة مفعول به ثانٍ."},{"type":"mcq","q":"ما إعراب «خضرةً» في: «كسَا الربيعُ الأرضَ خضرةً»؟","options":["حال منصوبة","مفعول به ثانٍ منصوب","تمييز","نعت"],"answer":1,"why":"كسا تنصب مفعولين: الأرضَ (أول) وخضرةً (ثانٍ)."},{"type":"mcq","q":"هل يصحّ تحويل مفعولَي «أعطى الغنيُّ الفقيرَ مالًا» إلى مبتدأ وخبر؟","options":["نعم","لا يصحّ (الفقير مال جملة خاطئة)","في المضارع فقط","في الجمع فقط"],"answer":1,"why":"لذلك يُسمى هذا الباب ما ليس أصله مبتدأ وخبرًا."}],"medium":[{"type":"mcq","q":"ما إعراب «العافيةَ» في جملة: «أسألُ اللهَ العافيةَ»؟","options":["مفعول به أول","مفعول به ثانٍ منصوب بالفتحة","فاعل","حال"],"answer":1,"why":"سأل هنا تنصب مفعولين: لفظ الجلالة (أول) والعافية (ثانٍ)."},{"type":"tfr","q":"عند بناء «أعطى الغنيُّ الفقيرَ صدقةً» للمجهول تصبح: «أُعْطِيَ الفقيرُ صدقةً».","answer":true,"reasons":["لأن المفعول الأول يصبح نائب فاعل مرفوعًا ويبقى الثاني منصوبًا","لأن المفعولين يُرفعان معًا","لأن الفعل لا يُبنى للمجهول"],"reason":0},{"type":"essay","q":"أعرب: «وهبَ اللهُ الإنسانَ عقلًا».","model":"وهبَ: فعل ماضٍ. اللهُ: لفظ الجلالة فاعل مرفوع. الإنسانَ: مفعول به أول منصوب بالفتحة. عقلًا: مفعول به ثانٍ منصوب بالفتحة."},{"type":"tfr","q":"الفعل «مَنَعَ» ينصب مفعولين أصلهما المبتدأ والخبر.","answer":false,"reasons":["لأنه ينصب مفعولين ليس أصلهما المبتدأ والخبر، مثل: منعتُ المهملَ الجائزةَ","لأنه فعل لازم","لأنه من أخوات كان"],"reason":0},{"type":"mcq","q":"ما الجملة الصحيحة نحويًّا؟","options":["منحَ المديرُ المتفوّقونَ جوائزَ","منحَ المديرُ المتفوّقينَ جوائزَ","منحَ المديرَ المتفوّقينَ جوائزٌ","منحَ المديرُ المتفوّقانِ جوائزَ"],"answer":1,"why":"المتفوّقين مفعول به أول منصوب بالياء لأنه جمع مذكر سالم."},{"type":"essay","q":"ابنِ الجملة الآتية للمجهول مع الضبط: «ألبسَ الأبُ الطفلَ ثوبًا».","model":"أُلْبِسَ الطفلُ ثوبًا. (الطفلُ نائب فاعل مرفوع بالضمة، وثوبًا مفعول به ثانٍ منصوب)."},{"type":"tfr","q":"في جملة «أعطيتُكَ هديةً» الضمير «الكاف» في محل نصب مفعول به أول.","answer":true,"reasons":["لأن التاء فاعل، والكاف مفعول به أول، وهديةً مفعول به ثانٍ","لأن الكاف فاعل","لأن هديةً فاعل"],"reason":0}],"hard":[{"type":"mcq","q":"أيُّ جملةٍ مما يأتي فيها فعلان ينصب أحدهما مفعولين أصلهما مبتدأ وخبر، والآخر ليس أصلهما؟","options":["علمتُ الصدقَ نافعًا وأعطيتُ الفقيرَ مالًا","قرأتُ كتابًا وكتبتُ درسًا","نام الطفلُ وصحا","كان الجوُّ جميلًا"],"answer":0,"why":"«علمتُ» من أخوات ظن، و«أعطيتُ» من أخوات أعطى."},{"type":"essay","q":"اشرح كيف تميّز عمليًا بين مفعولَي «ظنّ وأخواتها» ومفعولَي «أعطى وأخواتها».","model":"بحذف الفعل والفاعل؛ فإن تكوّنت جملة اسمية مفيدة من مبتدأ وخبر فهما من أخوات ظن، وإن لم تتكوّن فهما من أخوات أعطى."},{"type":"tfr","q":"في قوله تعالى: ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾، الكاف مفعول به أول و«الكوثرَ» مفعول به ثانٍ.","answer":true,"reasons":["لأن «أعطى» نصبت الضمير الكاف مفعولًا أول و«الكوثرَ» مفعولًا ثانيًا","لأن الكاف فاعل","لأن الكوثر مبتدأ"],"reason":0},{"type":"mcq","q":"ما إعراب «جائزتَينِ» في: «مُنِحَ الطالبُ جائزتَينِ»؟","options":["نائب فاعل","مفعول به ثانٍ منصوب بالياء","مفعول به أول","خبر مرفوع"],"answer":1,"why":"الطالب نائب فاعل، وجائزتين مفعول به ثانٍ منصوب بالياء لأنه مثنى."},{"type":"essay","q":"صوّب الخطأ النحوي في: «أُعْطِيَ الفائزينَ جوائزًا».","model":"أُعْطِيَ الفائزونَ جوائزَ. (الفائزون نائب فاعل مرفوع بالواو، وجوائز ممنوع من الصرف فلا يُنوّن)."},{"type":"tfr","q":"تعمل «أعطى وأخواتها» في الزمن الماضي فقط ولا تعمل في المضارع والأمر.","answer":false,"reasons":["لأنها تعمل في الماضي والمضارع والأمر جميعًا","لأنها حروف ناسخة","لأنها لا تنصب مفعولين"],"reason":0},{"type":"mcq","q":"ما المفعولان في: «ألبسَ العلمُ صاحبَهُ وقارًا»؟","options":["العلم وصاحبه","صاحبَهُ ووقارًا","العلم ووقارًا","ألبس والعلم"],"answer":1,"why":"العلم فاعل، وصاحبه مفعول أول، ووقارًا مفعول ثانٍ."},{"type":"essay","q":"حوّل «سأل» من فعل ينصب مفعولًا واحدًا إلى فعل ينصب مفعولين في جملتين.","model":"مفعول واحد: سألتُ المعلمَ عن الدرس. مفعولان: سألتُ اللهَ التوفيقَ."},{"type":"tfr","q":"في جملة «يَكسو الثلجُ القممَ بياضًا» يعمل المضارع «يكسو» عمل الماضي «كسا».","answer":true,"reasons":["لأنه نصب مفعولين: القممَ (أول) وبياضًا (ثانٍ)","لأن المضارع يرفع المفعولين","لأن بياضًا فاعل"],"reason":0},{"type":"essay","q":"كوّن ثلاث جمل تامة باستخدام الأفعال: مَنَحَ، كَسَا، مَنَعَ، وحدّد المفعولين في كل جملة.","model":"مثال: منحَ المعلمُ الطالبَ شهادةً (الطالب، شهادة). كسا المطرُ الصحراءَ جمالًا (الصحراء، جمالًا). منعَ الحارسُ الزائرَ الدخولَ (الزائر، الدخول)."}]}},
  {"id":"g9-arabic-1-u4-3","grade":"g9","subject":"arabic","term":1,"unit":4,"no":3,"title":"الأنشطة الإملائية: رسم الألف في أواخر الأسماء","summary":"شرح متحرك لقواعد كتابة الألف اللينة في أواخر الأسماء الثلاثية وفوق الثلاثية والأسماء الأعجمية، ثم أنشطة بثلاثة مستويات.","page":"lesson-alif-end-nouns.html","video":"","pdf":"","notes":["في الاسم الثلاثي ننظر إلى أصل الألف (بالتثنية أو الجمع أو المفرد): إن كان أصلها واوًا كُتبت قائمة (عصا ← عصوان)، وإن كان ياءً كُتبت مقصورة (فتى ← فتيان).","في الاسم غير الثلاثي (أكثر من ثلاثة أحرف) تُكتب الألف مقصورةً (ى) مثل: مستشفى، مصطفى، سلمى، منتدى.","استثناء مهم في غير الثلاثي: إذا سبقت الألف ياءٌ تُكتب قائمةً (ا) كراهة اجتماع ياءين، مثل: هدايا، دنيا، قضايا، مرايا.","كلمة «يحيى» (اسم العَلَم) تُكتب مقصورةً رغم سبقها بياء للتمييز بينها وبين الفعل «يحيا».","الأسماء الأعجمية تُكتب ألفها قائمة (أمريكا، فرنسا، إيطاليا) ما عدا خمسة: موسى، عيسى، كسرى، بخارى، متّى.","الأسماء المبنية تُكتب قائمة (هذا، أنا، مهما) ما عدا: متى، لدى، أنّى، الأُلى."],"exercises":["علّل رسم الألف في أواخر الأسماء الآتية: عصا، هدى، مستشفى، هدايا، يحيى.","كيف نعرف أصل الألف في الاسم الثلاثي؟ طبّق على «ربا» و«قرى».","صوّب الخطأ الإملائي: «زار مصطفا المستشفا واشترى هدايى»."],"levels":{"easy":[{"type":"mcq","q":"لماذا كُتبت الألف مقصورة في «فَتَى»؟","options":["لأنه ثلاثي أصل ألفه ياء","لأنه ثلاثي أصل ألفه واو","لأنه فوق ثلاثي","لأنه اسم أعجمي"],"answer":0,"why":"مثنى فتى هو فتيان، فأصل الألف ياء."},{"type":"mcq","q":"كيف تُكتب كلمة «مستشفـ...»؟","options":["مستشفا","مستشفى","مستشفئ","مستشفي"],"answer":1,"why":"اسم فوق ثلاثي لم تسبق ألفه ياء فتُكتب مقصورة."},{"type":"mcq","q":"لماذا كُتبت الألف قائمة في «دُنْيَا»؟","options":["لأنها ثلاثية","لأنها فوق ثلاثي وسبقت ألفها ياء","لأنها فعل","لأنها اسم مبني"],"answer":1,"why":"في غير الثلاثي إذا سبقت الألف ياء تُكتب قائمة."},{"type":"mcq","q":"أيُّ الأسماء الأعجمية الآتية تُكتب ألفه مقصورة؟","options":["أمريكا","عيسى","أوروبا","آسيا"],"answer":1,"why":"عيسى وموسى وكسرى وبخارى ومتى تُكتب ألفها مقصورة."}],"medium":[{"type":"mcq","q":"كيف نفرّق إملائيًا بين «يحيى» (اسم شخص) و«يحيا» (الفعل المضارع)؟","options":["الاسم مقصورة والفعل قائمة","كلاهما قائمة","كلاهما مقصورة","الاسم قائمة والفعل مقصورة"],"answer":0,"why":"كُتب العلم «يحيى» مقصورًا للتمييز بينه وبين الفعل «يحيا»."},{"type":"tfr","q":"تُكتب ألف الاسم الثلاثي «قُرَى» مقصورة لأن مفردها «قرية» فأصل الألف ياء.","answer":true,"reasons":["لأن ردّ الجمع إلى المفرد يكشف أصل الألف (قرية = ياء)","لأنها فوق ثلاثي","لأن أصلها واو"],"reason":0},{"type":"essay","q":"علّل رسم الألف في أواخر الأسماء الآتية: رُبَا، هُدَى، مُنْتَدَى، قَضَايَا.","model":"ربا: ثلاثي أصلها واو (ربوة). هدى: ثلاثي أصلها ياء (يهدي). منتدى: فوق ثلاثي بلا ياء قبله. قضايا: فوق ثلاثي قبلها ياء."},{"type":"tfr","q":"جميع الأسماء المبنية المنتهية بألف تُكتب مقصورة.","answer":false,"reasons":["لأن الأصل فيها أن تُكتب قائمة (أنا، هذا) ما عدا أربعة (متى، لدى، أنّى، الأُلى)","لأنها لا تنتهي بألف","لأنها تُكتب بالتاء"],"reason":0},{"type":"mcq","q":"أيُّ مجموعة كلمات مما يأتي كُتبت كلها صحيحة؟","options":["عصا، مصطفى، هدايا، موسى","عصى، مصطفا، هدايى، موسا","عصا، مصطفا، هدايا، عيسا","فتا، مستشفى، دنيا، يحيى"],"answer":0,"why":"كل كلمة فيها مطابقة للقاعدة تمامًا."},{"type":"essay","q":"صوّب الأخطاء في الجملة: «ذهب مصطفا إلى المستشفا ليشتري هدايى لـ يحيا».","model":"ذهب مصطفى إلى المستشفى ليشتري هدايا لـ يحيى."},{"type":"tfr","q":"في الاسم غير الثلاثي نحتاج دائمًا لمعرفة أصل الألف (واو أم ياء).","answer":false,"reasons":["لأن في غير الثلاثي ننظر فقط هل قبلها ياء أم لا، دون البحث عن أصلها","لأن غير الثلاثي كله قائمة","لأن غير الثلاثي لا ينتهي بألف"],"reason":0}],"hard":[{"type":"mcq","q":"ما أصل الألف في «ذُرَا» (جمع ذروة) وكيف تُكتب؟","options":["أصلها واو فتُكتب قائمة (ذُرا)","أصلها ياء فتُكتب مقصورة (ذُرى)","فوق ثلاثي","اسم أعجمي"],"answer":0,"why":"مفردها ذروة فأصلها واو وتُكتب قائمة."},{"type":"essay","q":"اشرح لماذا كُتبت «رُؤْيَا» قائمة بينما كُتبت «سَلْمَى» مقصورة.","model":"كلاهما فوق ثلاثي، لكن «رؤيا» سبقت ألفها ياء فكُتبت قائمة، أما «سلمى» فلم تسبقها ياء فكُتبت مقصورة."},{"type":"tfr","q":"كلمة «مَتَى» من الأسماء المبنية التي تُكتب ألفها مقصورة.","answer":true,"reasons":["لأن متى ولدى وأنّى والأُلى مستثناة من الأسماء المبنية فتُكتب مقصورة","لأنها اسم أعجمي","لأنها فعل ثلاثي"],"reason":0},{"type":"mcq","q":"ما الصواب في الجملة: «........ الطالبُ حياةً كريمةً، واسمه ........»؟","options":["يحيا / يحيى","يحيى / يحيا","يحيا / يحيا","يحيى / يحيى"],"answer":0,"why":"الأول فعل مضارع (يحيا) والثاني اسم علم (يحيى)."},{"type":"essay","q":"اذكر الأسماء الأعجمية الخمسة التي تُكتب ألفها مقصورة.","model":"موسى، عيسى، كسرى، بخارى، متّى."},{"type":"tfr","q":"تُكتب «مَرَايَا» بألف قائمة رغم أنها أكثر من ثلاثة أحرف لأن قبل الألف ياء.","answer":true,"reasons":["لأن العرب تكره اجتماع ياءين في آخر الاسم غير الثلاثي فتُكتب الألف قائمة","لأنها اسم أعجمي","لأنها مثنى"],"reason":0},{"type":"mcq","q":"أيُّ الكلمات الآتية ثلاثية أصل ألفها واو؟","options":["عُلا","نَدى","قُرى","رَحى"],"answer":0,"why":"عُلا من العلوّ فأصلها واو، أما ندى وقرى ورحى فأصلها ياء."},{"type":"essay","q":"اذكر ثلاث طرق عملية لمعرفة أصل الألف في الاسم الثلاثي مع مثال لكل طريقة.","model":"التثنية (عصا ← عصوان)، الجمع (فتى ← فتية)، ردّ الجمع للمفرد (قرى ← قرية)."},{"type":"tfr","q":"كلمة «بُخارَى» من الأسماء الأعجمية التي تُكتب بألف قائمة.","answer":false,"reasons":["لأن بخارى من الأسماء الأعجمية الخمسة المستثناة التي تُكتب بألف مقصورة","لأنها اسم مبني","لأنها ثلاثية"],"reason":0},{"type":"essay","q":"اكتب جملتين تحتويان على أربعة أسماء منتهية بألف تمثّل: ثلاثي واوي، ثلاثي يائي، فوق ثلاثي بلا ياء، وفوق ثلاثي قبله ياء.","model":"مثال: حمل الفتى عصا طويلة في رحلته إلى المستشفى، وقدّم هدايا للمرضى."}]}},
  {"id":"g9-arabic-1-u4-4","grade":"g9","subject":"arabic","term":1,"unit":4,"no":4,"title":"التعبير: التلخيص","summary":"شرح متحرك لمهارة التلخيص وشروطها وخطواتها العملية بمثال محلول، ثم أنشطة بثلاثة مستويات.","page":"lesson-summarizing.html","video":"","pdf":"","notes":["التلخيص: إعادة صياغة النص الأصلي في عددٍ أقلّ من الكلمات مع الحفاظ على أفكاره الرئيسة دون إخلال.","خطواته: القراءة الفاحصة، ثم تحديد الأفكار الرئيسة في كل فقرة، ثم حذف الشواهد والتكرار والأمثلة الجانبية.","تُصاغ الأفكار بأسلوب المُلخِّص الخاص مع استخدام الروابط المناسبة.","لا نضيف في التلخيص آراءنا الشخصية ولا معلومات غير موجودة في النص الأصلي (الأمانة العلمية).","يتراوح طول الملخّص عادةً بين ربع النص الأصلي وثلثه.","تُختتم العملية بمراجعة الملخّص ومقارنته بالأصل للتأكد من سلامة المعنى واللغة."],"exercises":["عرّف التلخيص واذكر أهمّ ما نحذفه أثناء التلخيص.","ما المقصود بالأمانة العلمية عند تلخيص نص؟","لخّص فقرةً من خمسة أسطر في سطرين بأسلوبك."],"levels":{"easy":[{"type":"mcq","q":"ما المقصود بالتلخيص؟","options":["نسخ النص كما هو","إعادة صياغة الأفكار الرئيسة بإيجاز وبأسلوبك","إطالة النص","ترجمة النص"],"answer":1,"why":"التلخيص يختصر النص في أفكاره الأساسية بأسلوبك الخاص."},{"type":"mcq","q":"كم يبلغ حجم الملخّص الجيّد عادةً؟","options":["ضعف الأصل","بين رُبع النص الأصلي وثُلثه","نفس عدد الكلمات","كلمة واحدة"],"answer":1,"why":"يتراوح الملخّص الجيّد بين ربع الأصل وثلثه."},{"type":"mcq","q":"أيٌّ مما يأتي نحذفه أثناء التلخيص؟","options":["الأفكار الرئيسة","التكرار والأمثلة التفصيلية","النتائج المهمة","الروابط اللغوية"],"answer":1,"why":"نحذف التكرار والحشو والأمثلة الجانبية ونبقي الجوهر."},{"type":"mcq","q":"ما أول خطوة نبدأ بها عند تلخيص نص؟","options":["الحذف العشوائي","القراءة الفاحصة وفهم النص","كتابة رأينا الشخصي","حذف الفقرة الأولى"],"answer":1,"why":"الفهم الدقيق للنص هو أساس استخراج أفكاره الرئيسة."}],"medium":[{"type":"mcq","q":"ما المقصود بـ «الأمانة العلمية» في التلخيص؟","options":["نقل أفكار الكاتب دون تحريف أو إضافة آراء شخصية","نسخ النص كاملًا","تغيير رأي الكاتب","إضافة قصص من عندنا"],"answer":0,"why":"الملخِّص أمين على أفكار الكاتب ولا يضيف من خارج النص."},{"type":"tfr","q":"التلخيص يعني نسخ جمل متفرقة من النص الأصلي ولصقها معًا.","answer":false,"reasons":["لأن التلخيص يتطلب إعادة صياغة الأفكار بأسلوبك الخاص وربطها بتماسك","لأن التلخيص لا يعتمد على النص","لأن النسخ هو الأفضل دائمًا"],"reason":0},{"type":"essay","q":"اذكر خطوات التلخيص الخمس بالترتيب.","model":"١) القراءة الفاحصة. ٢) تحديد الأفكار الرئيسة. ٣) حذف التكرار والشواهد والزوائد. ٤) الصياغة بأسلوبك الخاص وربط الجمل. ٥) المراجعة والمقارنة بالأصل."},{"type":"tfr","q":"تُحذف الجمل الاعتراضية والمترادفات المكررة عند التلخيص.","answer":true,"reasons":["لأن حذفها يختصر النص دون الإخلال بالأفكار الأساسية","لأنها هي الأفكار الرئيسة","لأنها تُطيل الملخّص"],"reason":0},{"type":"mcq","q":"ما فائدة مقارنة الملخّص بالنص الأصلي في النهاية؟","options":["التأكد من عدم سقوط فكرة رئيسة وسلامة المعنى","إطالة الملخّص","حذف الروابط","إضافة آراء شخصية"],"answer":0,"why":"المراجعة تضمن شمول الملخّص للأفكار الأساسية ودقتها."},{"type":"essay","q":"لخّص الجملة الآتية في أقل من عشر كلمات: «الماء عنصرٌ أساسيٌّ لا تستطيع الكائنات الحية من إنسان وحيوان ونبات أن تعيش بدونه يومًا واحدًا».","model":"الماء أساس حياة جميع الكائنات الحية."},{"type":"tfr","q":"تساعد أدوات الربط في التلخيص على جعل الملخّص نصًّا مترابطًا لا جملًا مفكّكة.","answer":true,"reasons":["لأن الروابط تجمع الأفكار المستخلصة في نسيج واحد سلس","لأن الروابط تُحذف دائمًا في التلخيص","لأن التلخيص يُكتب نقاطًا مبعثرة فقط"],"reason":0}],"hard":[{"type":"mcq","q":"إذا حذف الطالب فكرةً رئيسةً من النص أثناء التلخيص، فما الخلل الذي وقع فيه؟","options":["إيجاز مخلّ بالمعنى","أمانة علمية","إتقان التلخيص","حسن الصياغة"],"answer":0,"why":"التلخيص يجب أن يوجز دون الإخلال بالأفكار الرئيسة."},{"type":"essay","q":"لماذا نحتاج إلى قراءة النص مرتين قبل البدء بكتابة الملخّص؟","model":"القراءة الأولى للفهم العام للموضوع، والثانية لقراءة متأنّية تحدّد الأفكار الرئيسة وتميّزها من التفاصيل الجانبية."},{"type":"tfr","q":"يجوز في التلخيص تغيير ترتيب أفكار الكاتب إذا لم يكن هناك داعٍ لذلك.","answer":false,"reasons":["لأن الحفاظ على تسلسل أفكار الكاتب يحفظ بناء النص وأمانة النقل","لأن الترتيب العشوائي أفضل","لأن النص لا ترتيب له"],"reason":0},{"type":"mcq","q":"أيُّ سلوكٍ مما يأتي يُعدّ صحيحًا عند تلخيص مقالٍ طويل؟","options":["إضافة معلومات من الإنترنت","دمج الجمل المتشابهة في عبارة واحدة موجزة","إبقاء كل الشواهد والأمثلة","كتابة رأي شخصي في الخاتمة"],"answer":1,"why":"دمج الجمل المتشابهة في عبارة شاملة من أهم مهارات التلخيص."},{"type":"essay","q":"لخّص النص التالي في سطرين: «الرياضة تحفظ صحة الجسم وتقوّي العضلات وتنشّط الدورة الدموية، كما أنها تروّح عن النفس وتخفّف التوتر، وتعلّم الشباب التعاون والانضباط واحترام القواعد».","model":"تحفظ الرياضة صحة الجسم ونشاطه، وتخفّف التوتر النفسي، وتغرس في الشباب قيم التعاون والانضباط."},{"type":"tfr","q":"تُعدّ مهارة التلخيص أداةً فعّالةً للمذاكرة وتثبيت المعلومات الدراسية.","answer":true,"reasons":["لأن إعادة صياغة الدرس بأسلوبك وبإيجاز ترسّخ الفهم وتسهّل المراجعة","لأنها تُنسي المعلومات","لأنها تستغرق وقتًا أطول من حفظ الكتاب"],"reason":0},{"type":"mcq","q":"ما الفرق بين «التلخيص» و«النقد»؟","options":["التلخيص ينقل أفكار النص بأمانة بلا رأي شخصي، أما النقد فيبدي رأيًا وتقييمًا","لا يوجد فرق","النقد أقصر دائمًا","التلخيص يعارض الكاتب"],"answer":0,"why":"التلخيص موضوعي محايد، بينما النقد يتضمّن الحكم والتقييم."},{"type":"essay","q":"اذكر ثلاثة أخطاء شائعة يقع فيها الطلاب عند التلخيص.","model":"١) النسخ الحرفي بدل الصياغة بأسلوبهم. ٢) إدخال الآراء الشخصية. ٣) الإيجاز المخلّ الذي يسقط فكرة رئيسة."},{"type":"tfr","q":"استخدام اللغة الفصيحة الدقيقة شرطٌ في كتابة الملخّص.","answer":true,"reasons":["لأن الدقة اللغوية توصل المعنى بأقل عدد من الكلمات بوضوح","لأن الملخّص يُكتب بالعامية","لأن اللغة لا تؤثر في التلخيص"],"reason":0},{"type":"essay","q":"اشرح كيف تتعامل مع الأمثلة والشواهد الطويلة عند تلخيص نص.","model":"نحذف الأمثلة والشواهد التفصيلية ونكتفي بالفكرة العامة التي جاءت تلك الأمثلة لإثباتها."}]}},
  {"id":"g9-arabic-1-u4-5","grade":"g9","subject":"arabic","term":1,"unit":4,"no":5,"title":"الاستماع: مريم الصناع","summary":"شرح متحرك لأفكار نص الاستماع «مريم الصناع» وقيمه الإنسانية ومهارات فهم المسموع، ثم أنشطة بثلاثة مستويات.","page":"lesson-maryam-alsanaa.html","video":"","pdf":"","notes":["«الصناع» في اللغة تعني المرأة الماهرة الحاذقة المتقِنة لعمل يدها وصنعتها.","يسلّط نص الاستماع الضوء على نموذجٍ مضيءٍ للمرأة المنتجة المتقنة لعملها.","أبرز القيم في النص: إتقان العمل، والاعتماد على النفس، والصبر والمثابرة، وخدمة الأسرة والمجتمع.","العمل الحرفي الشريف مصدرُ عزّةٍ وكرامةٍ وليس عيبًا، وهو ركيزةٌ لحفظ التراث والاقتصاد.","يعكس النص دور المرأة الفاعل في بناء المجتمع وتربية الأجيال والإنتاج.","لإتقان نص الاستماع: ننصت بتركيز، ونلتقط صفات الشخصية والأحداث الرئيسة، ونستخلص القيم."],"exercises":["ما معنى كلمة «الصَّنَاع» في اللغة؟","اذكر ثلاث قيم إيجابية جسّدتها شخصية مريم الصناع.","كيف يُسهم إتقان الحرف اليدوية في خدمة المجتمع وحفظ التراث؟"],"levels":{"easy":[{"type":"mcq","q":"ما معنى كلمة «الصَّنَاع» في اللغة العربية؟","options":["الماهرة المتقِنة لعمل يديها","الكسولة","الكثيرة السفر","البائعة فقط"],"answer":0,"why":"الصَّنَاع صفة تدل على البراعة والحذق في الصنعة."},{"type":"mcq","q":"ما القيمة الكبرى التي يبرزها نص «مريم الصناع»؟","options":["إتقان العمل والاعتماد على النفس","الاعتماد على الآخرين","تضييع الوقت","الافتخار بالمال فقط"],"answer":0,"why":"النص يحتفي بالعمل الشريف وإتقانه وكرامة الإنسان العامل."},{"type":"mcq","q":"أيُّ حديثٍ شريفٍ يرتبط مباشرةً برسالة هذا الدرس؟","options":["«إن الله يحب إذا عمل أحدكم عملًا أن يتقنه»","«الوقت كالسيف»","«العلم نور»","«القناعة كنز»"],"answer":0,"why":"يؤكّد الحديث قيمة الإتقان في كل عمل."},{"type":"mcq","q":"ما الخطوة المهمة بعد الاستماع لنص قصصي؟","options":["نسيان أحداثه","استخلاص القيم والصفات الإيجابية","مقاطعة المتحدث","عدم التدوين"],"answer":1,"why":"الهدف من الاستماع الواعي هو الفهم واستخلاص العبر والقيم."}],"medium":[{"type":"mcq","q":"ماذا يمنح العمل الشريف للإنسان كما يوضّح الدرس؟","options":["العزّة والكرامة والاستقلال","الضعف","الخجل","العزلة"],"answer":0,"why":"العمل الشريف يحفظ كرامة الإنسان ويغنيه عن السؤال."},{"type":"tfr","q":"تقتصر الحرف اليدوية على كونها مصدر رزق دون أي دور ثقافي أو تراثي.","answer":false,"reasons":["لأنها تحفظ هوية الوطن وتراث الأجداد إلى جانب دعم الاقتصاد","لأن الحرف اليدوية غير مفيدة","لأنها لا علاقة لها بالتراث"],"reason":0},{"type":"essay","q":"اذكر أربع قيم إيجابية نتعلّمها من شخصية مريم الصناع.","model":"إتقان العمل، والاعتماد على النفس، والصبر والمثابرة، والأمانة، وخدمة الأسرة والمجتمع."},{"type":"tfr","q":"يُبرز النص دور المرأة الفاعل في الإنتاج وبناء المجتمع.","answer":true,"reasons":["لأن المرأة شريكة أساسية في التنمية والعمل وتربية الأجيال","لأن النص لم يتحدث عن المرأة","لأن العمل خاص بالرجال فقط"],"reason":0},{"type":"mcq","q":"كيف يظهر الإتقان في عمل الطالب المدرسي؟","options":["بكتابة الواجب بسرعة وبلا مراجعة","بالتنظيم والدقة والفهم العميق","بالنقل من الزملاء","بتأجيل المذاكرة"],"answer":1,"why":"الدقة والفهم والمراجعة هي صور إتقان الطالب."},{"type":"essay","q":"لماذا لُقّبت مريم بـ «الصَّنَاع»؟","model":"لبراعتها وحذقها وإتقانها الفائق لعمل يديها وصنعتها."},{"type":"tfr","q":"المثابرة والصبر ضروريان لاكتساب المهارة والوصول إلى الإتقان.","answer":true,"reasons":["لأن الإتقان ثمرة التدريب المستمر والصبر على الصعوبات","لأن الإتقان يأتي بلا تعلّم","لأن الصبر يمنع النجاح"],"reason":0}],"hard":[{"type":"mcq","q":"أيُّ عبارةٍ مما يأتي تعبّر عن الفكرة الرئيسة لدرس «مريم الصناع»؟","options":["إتقان العمل الشريف يصنع كرامة الإنسان ويبني المجتمع","المهن اليدوية أقل شأنًا من غيرها","العمل لا يحتاج إلى صبر","التراث لا علاقة له بالحاضر"],"answer":0,"why":"النص يرفع من شأن العمل المتقن والاعتماد على النفس."},{"type":"essay","q":"كيف يمكن للمجتمع اليوم دعم أصحاب الحرف اليدوية والمهن؟","model":"بالتشجيع والتدريب، وإقامة المعارض، وتقدير منتجاتهم، وغرس احترام العمل المهني في نفوس الشباب."},{"type":"tfr","q":"تُعدّ الأمانة جزءًا لا يتجزأ من إتقان العمل.","answer":true,"reasons":["لأن العامل الأمين يُخلص في عمله ولا يغشّ فيه، مما يحقّق الإتقان الحقيقي","لأن الأمانة لا علاقة لها بالجودة","لأن السرعة أهم من الأمانة"],"reason":0},{"type":"mcq","q":"ما دلالة ربط الإتقان بمحبة الله في الحديث الشريف؟","options":["تحويل العمل الدنيوي المتقن إلى عبادة يؤجر عليها الإنسان","قصر الإتقان على المسجد فقط","عدم أهمية المهارة","إلغاء العمل اليدوي"],"answer":0,"why":"الإتقان بإخلاص يرفع قيمة العمل الدنيوي ويجعله مثابًا عليه."},{"type":"essay","q":"قارن بين شخصٍ يؤدي عمله كيفما اتفق وشخصٍ يتقن عمله كـ «مريم الصناع».","model":"الأول ينتج عملًا ضعيفًا لا يرضي الناس ولا يطوّر نفسه، أما الثاني فيكسب احترام الناس وثقتهم ويشعر بالفخر والرضا ويحقق النجاح."},{"type":"tfr","q":"الاعتماد على النفس يبني شخصيةً قويةً قادرةً على مواجهة تحديات الحياة.","answer":true,"reasons":["لأنه يُعلّم الإنسان المسؤولية والمبادرة وتطوير مهاراته","لأنه يضعف الثقة بالنفس","لأنه يمنع التعاون"],"reason":0},{"type":"mcq","q":"عند الاستماع لسيرة شخصية ناجحة، أيّ سؤالٍ يساعدك على استخلاص العبرة؟","options":["كم عدد صفحات النص؟","ما القيم التي قادت الشخصية للنجاح وكيف أطبّقها؟","ما لون الغلاف؟","هل الاسم طويل؟"],"answer":1,"why":"التركيز على القيم والدروس المستفادة يحقق غاية الاستماع الواعي."},{"type":"essay","q":"اذكر مثالين لحرف تقليدية عُمانية عريقة يجب الحفاظ عليها.","model":"مثل صناعة الفخار، وصناعة الخناجر والفضيات، والسعفيات، وبناء السفن التقليدية، والنسيج العُماني."},{"type":"tfr","q":"العمل اليدوي الشريف لا يقلّ قيمةً ولا شرفًا عن أي وظيفة أخرى.","answer":true,"reasons":["لأن كل عمل نافع ومتقن يخدم المجتمع ويكرم صاحبه","لأن العمل اليدوي أقل قيمة","لأن المجتمع لا يحتاج للحرفيين"],"reason":0},{"type":"essay","q":"اكتب ثلاث نصائح لزملائك لغرس ثقافة الإتقان في الدراسة والحياة.","model":"١) أخلص النية وتجنّب الاستعجال في أداء المهام. ٢) طوّر مهاراتك باستمرار ولا ترضَ بالحد الأدنى. ٣) راجع عملك قبل تسليمه لتتأكد من جودته."}]}},
  {"id":"g9-arabic-1-u4-6","grade":"g9","subject":"arabic","term":1,"unit":4,"no":6,"title":"اقرأ واستمتع: في العلم","summary":"شرح متحرك لنص «في العلم» وفضل العلم وآداب طالبه والمقارنة بين العلم والمال، ثم أنشطة بثلاثة مستويات.","page":"lesson-fi-alilm.html","video":"","pdf":"","notes":["العلم هو النور الذي يهدي العقل ويميّز به الإنسان بين الحقّ والباطل والنافع والضار.","رفع الإسلام مكانة العلماء فقال تعالى: ﴿يَرْفَعِ اللَّهُ الَّذِينَ آمَنُوا مِنكُمْ وَالَّذِينَ أُوتُوا الْعِلْمَ دَرَجَاتٍ﴾.","العلم خيرٌ من المال: لأن العلم يحرسك وأنت تحرس المال، والعلم يزداد بالإنفاق والمال ينقص به.","من آداب طالب العلم: الإخلاص، والتواضع، واحترام المعلم، والصبر والمثابرة، والعمل بما تعلّم.","العلم بلا أخلاق قد يصبح أداة ضرر، أما العلم المقترن بالأخلاق فيبني الحضارة ويسعد البشرية.","تتقدّم الأمم بقدر استثمارها في التعليم والبحث والابتكار."],"exercises":["اذكر فرقَين بين العلم والمال كما ورد في الدرس.","ما أبرز آداب طالب العلم التي ينبغي التحلّي بها؟","لماذا لا بدّ أن يقترن العلم بالأخلاق؟"],"levels":{"easy":[{"type":"mcq","q":"لماذا يُعدّ العلم خيرًا من المال؟","options":["لأن العلم يحرسك وأنت تحرس المال","لأن المال لا ينقص أبدًا","لأن العلم ينقص بالإنفاق","لأن المال يبقى بعد الموت"],"answer":0,"why":"العلم يحفظ صاحبه ويزداد بالتعليم بخلاف المال."},{"type":"mcq","q":"ما أول كلمة نزلت في القرآن الكريم دلالةً على مكانة العلم؟","options":["اكتب","اقرأ","سافر","اعمل"],"answer":1,"why":"أول ما نزل من القرآن قوله تعالى: ﴿اقْرَأْ بِاسْمِ رَبِّكَ﴾."},{"type":"mcq","q":"أيٌّ مما يأتي من آداب طالب العلم؟","options":["الغرور","التواضع واحترام المعلم","التسرّع","إخفاء العلم"],"answer":1,"why":"التواضع والإخلاص واحترام المعلمين من أبرز آداب المتعلم."},{"type":"mcq","q":"ما ثمرة العلم الحقيقية؟","options":["حفظ الأوراق فقط","العمل به ونفع الناس","التباهي","الابتعاد عن المجتمع"],"answer":1,"why":"العلم بلا عمل كالشجرة بلا ثمر."}],"medium":[{"type":"mcq","q":"ما الذي يحدث إذا انفصل العلم عن الأخلاق؟","options":["يزداد نفعه","قد يصبح أداة ضرر وهدم","يختفي تمامًا","يبني الحضارة دائمًا"],"answer":1,"why":"الأخلاق هي التي توجّه العلم لخدمة الإنسان لا إيذائه."},{"type":"tfr","q":"العلم يزداد كلّما بذلته وعلّمتَه للناس، بينما المال ينقص بالإنفاق.","answer":true,"reasons":["لأن تعليم الناس يثبّت العلم ويوسّعه ويجعله صدقة جارية","لأن العلم ينقص بالتعليم","لأن المال يزداد بالصرف العشوائي"],"reason":0},{"type":"essay","q":"اذكر فرقَين بين العلم والمال.","model":"١) العلم يحرسك وأنت تحرس المال. ٢) العلم يزداد بالإنفاق والمال ينقص به. ٣) العلم يبقى أثره بعد الموت."},{"type":"tfr","q":"كلّما ازداد الإنسان علمًا حقيقيًا ازداد غرورًا وتكبرًا على الناس.","answer":false,"reasons":["لأن العلم الحقيقي يورث التواضع والحلم لمعرفة الإنسان سعة ما لا يعلم","لأن التواضع يمنع التعلم","لأن الغرور من آداب المتعلم"],"reason":0},{"type":"mcq","q":"بماذا تنهض الأمم وتملك مفاتيح المستقبل؟","options":["بالتعليم والبحث والابتكار","بالكسل والاعتماد على الغير","بإهمال العلماء","بتقليد الآخرين بلا فهم"],"answer":0,"why":"الاستثمار في التعليم والبحث أساس نهضة الأمم."},{"type":"essay","q":"اذكر ثلاثًا من آداب طالب العلم.","model":"الإخلاص لله، والتواضع، واحترام المعلمين، والصبر على مشقة التعلم، والعمل بما تعلّم."},{"type":"tfr","q":"الجمع بين «العلم نور» و«الجهل ظلام» يجمع بين التشبيه والطباق.","answer":true,"reasons":["لأن فيه تشبيهًا للعلم بالنور والجهل بالظلام، وطباقًا بين النور والظلام","لأنه خالٍ من الصور","لأنه سجع فقط"],"reason":0}],"hard":[{"type":"mcq","q":"ما دلالة تشبيه العالِم العامل بـ «الشجرة المثمرة»؟","options":["أنه ينفع الناس بعلمه ويجني المجتمع ثماره","أنه يقف في مكان واحد","أنه لا يحتاج للتعلم","أنه يبحث عن المال فقط"],"answer":0,"why":"العالم العامل يفيد غيره بعلمه تمامًا كالشجرة التي يُنتفع بثمرها وظلها."},{"type":"essay","q":"اشرح كيف يكون العلم «صدقةً جارية» يبقى أثرها بعد وفاة الإنسان.","model":"عندما يعلّم الإنسان غيره علمًا نافعًا أو يؤلّف كتابًا أو يبتكر نفعًا للناس، يستمر الأجر والأثر الحسن حتى بعد وفاته."},{"type":"tfr","q":"يُعدّ الصبر والمثابرة من شروط تحصيل العلم النافع.","answer":true,"reasons":["لأن طلب العلم يحتاج إلى جهد متواصل وتدريب وعدم استعجال للنتائج","لأن العلم يُنال بلا جهد","لأن الصبر يعطّل الفهم"],"reason":0},{"type":"mcq","q":"أيُّ آيةٍ كريمةٍ تؤكّد رفعة مكانة العلماء؟","options":["﴿يَرْفَعِ اللَّهُ الَّذِينَ آمَنُوا مِنكُمْ وَالَّذِينَ أُوتُوا الْعِلْمَ دَرَجَاتٍ﴾","﴿وَالشَّمْسِ وَضُحَاهَا﴾","﴿وَالْعَصْرِ﴾","﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ﴾"],"answer":0,"why":"تصرح الآية برفعة درجات أهل الإيمان والعلم."},{"type":"essay","q":"بيّن العلاقة التكاملية بين العلم والأخلاق بمثال من الواقع الحديث.","model":"الطبيب الماهر يحتاج للأمانة والرحمة ليعالج المرضى بإخلاص، ومبرمج الحاسوب يحتاج للأخلاق ليستخدم تقنيته في النفع لا في الإضرار بالناس."},{"type":"tfr","q":"تقتصر مهمة طالب العلم على اجتياز الاختبار دون حاجة لفهم العلم أو تطبيقه.","answer":false,"reasons":["لأن الغاية الأسمى من العلم هي الفهم وبناء العقل والعمل النافع لخدمة الوطن","لأن الفهم غير مهم","لأن الاختبار هو نهاية التعلم"],"reason":0},{"type":"mcq","q":"لماذا شُبّه العلماء بـ «مصابيح الهداية»؟","options":["لأنهم ينيرون للناس طريق الحقّ والمعرفة ويبدّدون ظلام الجهل","لأنهم يعملون ليلًا فقط","لأنهم يصنعون المصابيح","لأنهم يعتزلون الناس"],"answer":0,"why":"المصباح يبدّد الظلام، والعالم يهدي الناس بعلمه."},{"type":"essay","q":"كيف تردّ على من يقول إن المال وحده يكفي لبناء نهضة الأوطان دون علم؟","model":"المال بلا علم قد يُساء استثماره وينفد، أما العلم فيُحسن إدارة الموارد ويبتكر الحلول ويصنع الثروة المستدامة ويبني الإنسان."},{"type":"tfr","q":"احترام المعلم وتقدير جهده يعكس نضج طالب العلم وحسن أدبه.","answer":true,"reasons":["لأن المعلم هو الوسيلة التي يصل بها العلم إلى الطالب ويستحق التوقير","لأن المعلم لا دور له","لأن الاحترام غير مرتبط بالعلم"],"reason":0},{"type":"essay","q":"اكتب شعارًا موجزًا من جملة واحدة يشجّع زملاءك على حب العلم وطلب المعرفة.","model":"مثال: «بالعلم نرتقي، وبالأخلاق نسمو، وبالمثابرة نصنع مستقبل عُمان المشرق»."}]}},
  {"id":"g9-arabic-1-u5-1","grade":"g9","subject":"arabic","term":1,"unit":5,"no":1,"title":"القراءة: القصة في القرآن الكريم","summary":"شرح متحرك لمفهوم القصة في القرآن الكريم وأنواعها وخصائصها الفنية وأهدافها، ثم أنشطة بثلاثة مستويات.","page":"lesson-quranic-story.html","video":"","pdf":"","notes":["القصة القرآنية أسلوب رباني رفيع يهدف إلى الهداية والعظة وتثبيت القلوب، وليس لمجرد التسلية.","من أنواعها: قصص الأنبياء (كنوح ويوسف وموسى عليهم السلام)، وقصص الأمم السابقة، وقصص الصالحين (كأهل الكهف).","تمتاز القصة القرآنية بالصدق الواقعي التام، لأنها وحيٌ من الله تعالى.","من خصائصها الفنية: الإيجاز المعجز، وجمال الحوار، والتصوير الحيّ للمواقف، وترك التفاصيل غير المؤثرة في العبرة.","تكرار بعض القصص في أكثر من سورة يهدف لبيان جانبٍ جديدٍ يناسب سياق كل سورة.","أبرز أهدافها: إثبات صدق النبوة، وتسلية النبي والمؤمنين، وبيان عاقبة الصبر والظلم."],"exercises":["ما الفرق بين القصة القرآنية والقصة الأدبية الخيالية؟","لماذا تتكرّر بعض القصص في أكثر من سورة في القرآن الكريم؟","اذكر ثلاث خصائص فنية للقصة في القرآن الكريم."],"levels":{"easy":[{"type":"mcq","q":"ما الغاية الكبرى من القصة في القرآن الكريم؟","options":["التسلية فقط","الهداية والعظة وتثبيت القلوب","الخيال الأدبي","جمع الأخبار فقط"],"answer":1,"why":"تهدف القصة القرآنية إلى الهداية والاعتبار وتثبيت الإيمان."},{"type":"mcq","q":"بماذا تمتاز القصة القرآنية عن القصص الأدبية الخيالية؟","options":["بالصدق الواقعي التام","بكثرة الخيال","بإهمال العبرة","بالغموض"],"answer":0,"why":"أحداثها حقائق واقعية وليست من نسج الخيال."},{"type":"mcq","q":"أيٌّ مما يأتي مثال على «قصص الصالحين» في القرآن؟","options":["أصحاب الكهف","غزوة بدر","قصة فرعون","قارون"],"answer":0,"why":"أصحاب الكهف نموذج للشباب المؤمن الصالح."},{"type":"mcq","q":"ما السورة التي وردت فيها قصة نبيٍّ كاملةً في موضع واحد؟","options":["سورة يوسف","سورة الفاتحة","سورة الإخلاص","سورة الناس"],"answer":0,"why":"سورة يوسف عرضت قصة يوسف عليه السلام كاملةً بتسلسل بديع."}],"medium":[{"type":"mcq","q":"لماذا لم يذكر القرآن تفاصيل مثل لون كلب أهل الكهف؟","options":["لأن التركيز على العبرة والإيمان لا على التفاصيل غير المؤثرة","لأنه نسيها","لأن القصة قصيرة","لعدم وجود كلب"],"answer":0,"why":"من خصائص القصة القرآنية الإيجاز والتركيز على موضع العبرة."},{"type":"tfr","q":"تكرار قصة موسى عليه السلام في عدة سور يُعدّ تكرارًا حرفيًا بلا فائدة جديدة.","answer":false,"reasons":["لأن كل موضع يعرض زاوية جديدة بأسلوب يناسب موضوع السورة وسياقها","لأنها لم ترد إلا مرة واحدة","لأن التكرار للزينة فقط"],"reason":0},{"type":"essay","q":"اذكر ثلاث خصائص فنية للقصة في القرآن الكريم.","model":"الصدق الواقعي، وجمال التصوير الفني الحي، وقوة الحوار الكاشف للشخصيات، والإيجاز والتركيز على العبرة."},{"type":"tfr","q":"يؤدّي الحوار في القصة القرآنية دورًا مهمًا في كشف نفسيات الشخصيات ومواقفها.","answer":true,"reasons":["لأن الحوار ينقل الصراع بين الحق والباطل بحيوية وإقناع كما في حوار موسى وفرعون","لأن القصة القرآنية تخلو من الحوار","لأن الحوار للخيال فقط"],"reason":0},{"type":"mcq","q":"أيُّ قيمةٍ نتعلّمها من قصة يوسف عليه السلام؟","options":["العفة والصبر وحسن التدبير","التسرّع","اليأس","الانتقام"],"answer":0,"why":"جسّدت قصة يوسف العفة والصبر والعفو وحسن الإدارة."},{"type":"essay","q":"اذكر الأنواع الثلاثة الرئيسة للقصص في القرآن الكريم مع مثال لكل نوع.","model":"١) قصص الأنبياء (يوسف وموسى). ٢) قصص الصالحين (أصحاب الكهف ومريم). ٣) أحداث السيرة النبوية (غزوة بدر وأحد)."},{"type":"tfr","q":"من أهداف القصة القرآنية تسلية النبي ﷺ وتثبيت فؤاده على الدعوة.","answer":true,"reasons":["لقوله تعالى: ﴿وَكُلًّا نَّقُصُّ عَلَيْكَ مِنْ أَنبَاءِ الرُّسُلِ مَا نُثَبِّتُ بِهِ فُؤَادَكَ﴾","لأنها لم تُنزل في عهد النبي ﷺ","لأنها للتسلية العابرة فقط"],"reason":0}],"hard":[{"type":"mcq","q":"ما دلالة تنوّع الأسلوب عند تكرار القصة القرآنية في أكثر من سورة؟","options":["إعجاز القرآن البياني وملاءمة كل عرض لسياق السورة","اختلاف الوقائع","ضعف الترابط","نقص المعلومات"],"answer":0,"why":"يُظهر الإعجاز البلاغي للقرآن وتوظيف القصة لخدمة هدف كل سورة."},{"type":"essay","q":"قارن بين القصة القرآنية والقصة الأدبية من حيث: المصدر، والواقعية، والهدف.","model":"القصة القرآنية مصدرها الوحي، وواقعيتها صادقة مطلقة، وهدفها الهداية والعظة. أما القصة الأدبية فمصدرها الإنسان، وقد تعتمد على الخيال، وهدفها المتعة الأدبية أو الفكرة الاجتماعية."},{"type":"tfr","q":"التصوير الفني في القصة القرآنية يجعل القارئ كأنه يشاهد الموقف حيًّا أمام عينيه.","answer":true,"reasons":["لأن الألفاظ القرآنية ترسم الحركة والصوت والمشهد بدقة معجزة","لأن القصة القرآنية خالية من الصور","لأنها جمل علمية جافة"],"reason":0},{"type":"mcq","q":"أيُّ سمةٍ تبرز في قصة أصحاب الكهف؟","options":["الثبات على الحق والإيمان في وجه الفتنة","حبّ المال","الكسل","الغفلة"],"answer":0,"why":"ضرب أصحاب الكهف أروع مثال في ثبات الشباب على عقيدتهم."},{"type":"essay","q":"كيف تتحوّل القصة القرآنية إلى منهج عملي لحياة الطالب اليوم؟","model":"بالاقتداء بقيمها: الصبر عند الشدائد، والعفة والأمانة في السلوك، والثبات على المبادئ، والتوكل على الله مع الأخذ بالأسباب."},{"type":"tfr","q":"تقتصر القصة القرآنية على قصص الأنبياء وحدهم.","answer":false,"reasons":["لأنها تشمل أيضًا قصص الصالحين والأمم السابقة وأحداثًا من السيرة النبوية","لأنها لا تذكر الأنبياء","لأنها تذكر نبيًا واحدًا فقط"],"reason":0},{"type":"mcq","q":"لماذا وُصفت قصة يوسف عليه السلام بأنها «أحسن القصص»؟","options":["لجمال بنائها المتكامل وعمق عبرها في الصبر والعفة والعفو","لأنها أقصر سورة","لأنها بلا حوار","لأنها خيالية"],"answer":0,"why":"جمعت كل عناصر الإبداع القصصي والتربوي في سورة واحدة متكاملة."},{"type":"essay","q":"علّل: لماذا يُعرض القرآن عن تحديد بعض الأزمنة والأمكنة في قصصه؟","model":"لأن العبرة الإنسانية صالحة لكل زمان ومكان، فلا تُقيد القصة بزمان أو مكان محدد إلا حين يخدم ذلك المعنى."},{"type":"tfr","q":"تُبيّن القصة القرآنية سنن الله الثابتة في نصرة الحق وعاقبة الظلم.","answer":true,"reasons":["لأن مصير الطغاة كفرعون ونصرة الأنبياء يؤكدان أن العاقبة للمتقين","لأنها لا تتحدث عن الظلم","لأن السنن الإلهية متناقضة"],"reason":0},{"type":"essay","q":"اختر قصة قرآنية تحبها واذكر في سطرين أبرز عبرة استفدتها منها.","model":"مثال: قصة نبي الله يوسف عليه السلام؛ تعلّمت منها أن الصبر وحسن الظن بالله والعفو عند المقدرة تقود الإنسان إلى الرفعة والنجاح."}]}},
  {"id":"g9-arabic-1-u5-3","grade":"g9","subject":"arabic","term":1,"unit":5,"no":3,"title":"الأنشطة الإملائية: تطبيقات على رسم الهمزة المتطرفة وكتابة الألف في أواخر الأسماء","summary":"تطبيقات متحركة شاملة تراجع وتدمج قواعد الهمزة المتطرفة وتنوينها ورسم الألف في أواخر الأسماء، ثم أنشطة بثلاثة مستويات.","page":"lesson-u5-spelling-apps.html","video":"","pdf":"","notes":["الهمزة المتطرفة تتبع حركة الحرف الذي قبلها فقط: فتح (أ)، ضم (ؤ)، كسر (ئ)، سكون أو مدّ (ء).","تنوين الفتح في الهمزة المتطرفة: بلا ألف بعد ألف أو فوق ألف (سماءً، ملجأً)، سطر+ألف بعد حرف لا يتصل (جزءًا)، نبرة+ألف بعد حرف يتصل (شيئًا).","الألف في آخر الاسم الثلاثي: قائمة إن كان أصلها واوًا (عصا، ربا)، ومقصورة إن كان أصلها ياءً (فتى، هدى، قرى).","الألف في آخر الاسم غير الثلاثي: مقصورة (مستشفى، مصطفى)، إلا إذا سبقتها ياء فتُكتب قائمة (هدايا، دنيا) ما عدا العلم (يحيى).","الأسماء الأعجمية قائمة ما عدا: موسى، عيسى، كسرى، بخارى، متّى.","المراجعة التطبيقية للنصوص واكتشاف الأخطاء الإملائية هي أفضل وسيلة لتثبيت القاعدة."],"exercises":["صوّب الأخطاء في الجملة: «أهدى مصطفا شيئًا جميلًا لـ يحيا في سماءًا صافية».","علّل رسم آخر الكلمات: قارِئ، ضوءًا، عُلا، قضايا.","نوّن بالفتح: مبدأ، عبء، هدوء، مساء."],"levels":{"easy":[{"type":"mcq","q":"أيُّ الكلمات الآتية كُتبت خطأً؟","options":["شاطئ","سماءً","هدايى","جزءًا"],"answer":2,"why":"الصواب «هدايا» بألف قائمة لأنها فوق ثلاثي وسبقت ألفها ياء."},{"type":"mcq","q":"ما الصواب عند تنوين «مَلْجَأ» بالفتح؟","options":["ملجأً","ملجأًا","ملجئًا","ملجءًا"],"answer":0,"why":"الهمزة فوق ألف فلا نزيد ألفًا ثانية."},{"type":"mcq","q":"ما الصواب في كتابة اسم الشخص «يحيى»؟","options":["يحيى","يحيا","يحيأ","يحيء"],"answer":0,"why":"العلم يحيى يُكتب مقصورًا ليمتاز عن الفعل يحيا."},{"type":"mcq","q":"لماذا كُتبت الهمزة على السطر في «بَطِيء»؟","options":["لأن ما قبلها ياء مدّ ساكنة","لأن ما قبلها مكسور","لأنها مفتوحة","لأنها مضمومة"],"answer":0,"why":"الياء هنا حرف مدّ ساكن فتُكتب الهمزة على السطر."}],"medium":[{"type":"mcq","q":"أيُّ جملةٍ مما يأتي خالية تمامًا من الأخطاء الإملائية؟","options":["قدّم يحيى هدايا رائعةً مساءً.","قدّم يحيا هدايى رائعةً مساءًا.","قدّم يحيى هدايا رائعةً مساءًا.","قدّم يحيا هدايا رائعةً مساءً."],"answer":0,"why":"يحيى (علم مقصورة)، هدايا (قبلها ياء)، مساءً (بلا ألف ثانية)."},{"type":"tfr","q":"تُكتب «عُلا» بألف قائمة لأن أصل ألفها واو (من العلوّ).","answer":true,"reasons":["لأن الاسم الثلاثي الذي أصل ألفه واو تُكتب ألفه قائمة","لأنها فوق ثلاثي","لأنها اسم أعجمي"],"reason":0},{"type":"essay","q":"صوّب الأخطاء الإملائية في الجملة: «قرأ الفتا جزءً من القصة في الميناءِ بهدوئٍ».","model":"قرأ الفتى جزءًا من القصة في الميناءِ بهدوءٍ. (الفتى، جزءًا، بهدوءٍ)."},{"type":"tfr","q":"في كلمة «عِبْئًا» تُكتب الهمزة على نبرة لأن الباء تتصل بألف التنوين.","answer":true,"reasons":["لأن الحرف الساكن قبل الهمزة يتصل بما بعده فتُكتب على نبرة","لأن الباء لا تتصل","لأن قبلها ألفًا"],"reason":0},{"type":"mcq","q":"ما الصواب في تنوين «ضَوْء» بالفتح؟","options":["ضوئًا","ضوءًا","ضوءً","ضوأً"],"answer":1,"why":"الواو لا تتصل بما بعدها فتبقى الهمزة على السطر مع ألف التنوين."},{"type":"essay","q":"علّل كتابة آخر كل كلمة: «قُرَى»، «مُسْتَشْفَى»، «قَارِئ»، «شَيْئًا».","model":"قرى: ثلاثي أصلها ياء (قرية). مستشفى: فوق ثلاثي بلا ياء قبله. قارئ: همزة متطرفة قبلها كسرة. شيئًا: همزة متطرفة منوّنة بالفتح قبلها ياء تتصل."},{"type":"tfr","q":"كلمة «موسى» تُكتب بألف قائمة لأنها اسم أعجمي.","answer":false,"reasons":["لأن موسى وعيسى وكسرى وبخارى ومتّى مستثناة من الأسماء الأعجمية وتُكتب مقصورة","لأنها اسم عربي ثلاثي","لأن قبلها ياء"],"reason":0}],"hard":[{"type":"mcq","q":"أيُّ مجموعةٍ مما يأتي كلها صحيحة إملائيًا؟","options":["دِفئًا، بَدءًا، مَبْدأً، مَساءً","دِفءًا، بَدئًا، مَبْدأًا، مَساءًا","دِفئًا، بَدئًا، مَبْدأً، مَساءً","دِفءًا، بَدءًا، مَبْدأً، مَساءًا"],"answer":0,"why":"كل كلمة فيها طبّقت قاعدة تنوين الهمزة المتطرفة بدقة."},{"type":"essay","q":"صوّب جميع الأخطاء الإملائية في الفقرة: «ذهب مصطفا وعيسا إلى القرا، وحملا عصى طويلةً، وتأملا سماءًا مليئةً بالنجوم».","model":"ذهب مصطفى وعيسى إلى القرى، وحملا عصا طويلةً، وتأملا سماءً مليئةً بالنجوم."},{"type":"tfr","q":"الهمزة المتطرفة في «مُتَكَافِئ» تُكتب على ياء غير منقوطة، وعند تنوينها بالفتح تصبح «متكافئًا».","answer":true,"reasons":["لأن الفاء مكسورة فتُكتب على ياء، وعند التنوين بالفتح تُزاد ألف التنوين","لأن الفاء ساكنة","لأنها تُكتب على واو"],"reason":0},{"type":"mcq","q":"ما الفرق الإملائي الصحيح بين «قضايا» و«سلوى»؟","options":["قضايا قائمة لأن قبلها ياء، وسلوى مقصورة لأن قبلها واو","كلاهما مقصورة","كلاهما قائمة","قضايا ثلاثية"],"answer":0,"why":"كلاهما فوق ثلاثي، فـ «قضايا» سبقتها ياء فصارت قائمة."},{"type":"essay","q":"نوّن الكلمات الآتية بالفتح مع ذكر السبب: بِنَاء، بُطْء، رِدْء، خَطَأ.","model":"بناءً (قبلها ألف)، بطئًا (الطاء تتصل)، ردءًا (الدال لا تتصل)، خطأً (فوق ألف)."},{"type":"tfr","q":"تُكتب «يَقْرَأُ» على واو لأن الهمزة مضمومة.","answer":false,"reasons":["لأن الهمزة المتطرفة تتبع حركة ما قبلها (الراء مفتوحة) فتُكتب على ألف","لأنها همزة متوسطة","لأن الراء مضمومة"],"reason":0},{"type":"mcq","q":"أيُّ كلمةٍ مما يأتي أصل ألفها واو؟","options":["رُبَا","هُدَى","فَتَى","نَدَى"],"answer":0,"why":"مفردها ربوة فأصلها واو وتُكتب قائمة."},{"type":"essay","q":"اشرح لزميلك الفرق بين كتابة «جَرِيء» و«هَادِئ» قبل التنوين وبعد تنوين الفتح.","model":"قبل التنوين: «جريء» على السطر (قبلها ياء مد ساكنة) و«هادئ» على ياء (قبلها دال مكسورة). وبعد تنوين الفتح تصبحان: «جريئًا» و«هادئًا»."},{"type":"tfr","q":"جميع الكلمات: (موسى، عيسى، متى، لدى) تُكتب ألفها مقصورة.","answer":true,"reasons":["لأن موسى وعيسى من الأعجمي المستثنى، ومتى ولدى من المبني المستثنى","لأنها كلها أسماء ثلاثية عربية","لأن قبلها ياء"],"reason":0},{"type":"essay","q":"اكتب جملتين صحيحتين إملائيًا توظّف فيهما: اسمًا ثلاثيًا واوي الألف، واسمًا فوق ثلاثي مقصورًا، وهمزة متطرفة منوّنة بالفتح على نبرة.","model":"مثال: حمل الراعي عصا في طريقه إلى المستشفى، واشترى شيئًا نافعًا للمريض."}]}},
  {"id":"g9-arabic-1-u5-4","grade":"g9","subject":"arabic","term":1,"unit":5,"no":4,"title":"التعبير: تلخيص موضوع","summary":"شرح تطبيقي متحرك لكيفية تلخيص موضوع كامل متعدّد الفقرات مع نموذج عملي، ثم أنشطة بثلاثة مستويات.","page":"lesson-topic-summary.html","video":"","pdf":"","notes":["عند تلخيص موضوع كامل متعدّد الفقرات، نتعامل مع كل فقرة على حدة أولًا.","نستخرج من كل فقرة فكرتها الرئيسة في جملة واحدة موجزة.","نحذف التفاصيل المتكررة والأمثلة والشواهد الطويلة من كل فقرة.","نجمع الجمل المستخرجة ونربط بينها بأدوات ربط مناسبة في فقرة أو فقرتين متماسكتين.","نحافظ على ترتيب الأفكار الأصلي وعلى الأمانة العلمية دون إضافة آراء شخصية.","نختم بقراءة الملخّص للتأكد من سلاسته واكتمال معناه وحجمه المناسب (الربع إلى الثلث)."],"exercises":["كيف نبدأ بتلخيص موضوع مكوّن من أربع فقرات؟","ما الفرق بين تلخيص فقرة واحدة وتلخيص موضوع كامل؟","لخّص درسًا قرأته هذا الأسبوع في خمسة أسطر بأسلوبك."],"levels":{"easy":[{"type":"mcq","q":"كيف نتعامل مع موضوع طويل متعدّد الفقرات عند تلخيصه؟","options":["نلخّص الفقرة الأولى فقط","نستخرج فكرة كل فقرة في جملة ثم ندمجها","نحذف الفقرات الأخيرة","ننسخ النص كاملًا"],"answer":1,"why":"تقسيم الموضوع إلى فقرات واستخراج فكرة كل فقرة يضمن شمول الملخّص."},{"type":"mcq","q":"ما الذي يجعل جمل الملخّص مترابطة وسلسة بعد دمجها؟","options":["أدوات الربط وعلامات الترقيم","تكرار الكلمات","كتابة جمل عامية","ترك النص بلا فواصل"],"answer":0,"why":"الروابط مثل (لذلك، كما أن، ومن ثمّ) تدمج الجمل في نسيج واحد."},{"type":"mcq","q":"ماذا نفعل بالأمثلة والإحصاءات التفصيلية في كل فقرة؟","options":["نحذفها ونبقي الفكرة الرئيسة","ننسخها كلها","نضعها في العنوان","نكرّرها مرتين"],"answer":0,"why":"التلخيص يحتفظ بالأفكار الأساسية ويحذف التفاصيل الفرعية."},{"type":"mcq","q":"هل نحتفظ بترتيب أفكار الكاتب الأصلي عند التلخيص؟","options":["نعم، التزامًا بالأمانة","لا، نغيّره عشوائيًا","نبدأ بالخاتمة دائمًا","نحذف المقدمة"],"answer":0,"why":"الحفاظ على تسلسل أفكار الكاتب من شروط التلخيص الدقيق."}],"medium":[{"type":"mcq","q":"ما فائدة ترقيم الفقرات وكتابة جملة موجزة في الهامش لكل فقرة؟","options":["تسهيل السيطرة على الموضوع وعدم سقوط أي فكرة رئيسة","إطالة وقت التلخيص","إضافة أفكار خارجية","حذف العنوان"],"answer":0,"why":"هذه الطريقة المنظمة تضمن تلخيصًا شاملًا ومتوازنًا."},{"type":"tfr","q":"يمكن دمج أفكار ثلاث فقرات قصيرة في فقرة واحدة متماسكة عند التلخيص.","answer":true,"reasons":["لأن التلخيص يوجز الموضوع ويجمع أفكاره المتقاربة بسلاسة","لأن عدد فقرات الملخّص يجب أن يساوي الأصل دائمًا","لأن الدمج ممنوع"],"reason":0},{"type":"essay","q":"لخّص الأفكار الثلاث الآتية في جملتين مترابطتين: ١) القراءة غذاء العقل. ٢) المكتبة توفّر كتبًا متنوعة. ٣) يجب تخصيص وقت يومي للمطالعة.","model":"القراءة غذاء العقل، وتوفّر المكتبة كتبًا متنوعة لتنميتها؛ لذلك ينبغي تخصيص وقت يومي للمطالعة."},{"type":"tfr","q":"إذا كان النص الأصلي صفحتين، فإن ملخّصه المناسب يكون حوالي نصف صفحة.","answer":true,"reasons":["لأن حجم الملخّص الجيّد يتراوح بين ربع الأصل وثلثه (حوالي نصف صفحة من صفحتين)","لأن الملخّص يجب أن يكون صفحتين","لأن الملخّص كلمة واحدة"],"reason":0},{"type":"mcq","q":"أيُّ رابطٍ مما يأتي يناسب ربط نتيجةٍ بسببٍ داخل الملخّص؟","options":["لذلك / ومن ثَمّ","أين","متى","كم"],"answer":0,"why":"«لذلك» و«ومن ثَمّ» يربطان النتيجة بالسبب."},{"type":"essay","q":"اذكر الخطوات الأربع العملية لتلخيص موضوع متعدّد الفقرات.","model":"١) قراءة الموضوع وترقيم فقراته. ٢) استخراج فكرة كل فقرة في جملة موجزة. ٣) دمج الجمل بأدوات الربط بأسلوبك. ٤) المراجعة اللغوية ومقارنة الملخّص بالأصل."},{"type":"tfr","q":"تُعدّ إضافة رأي الطالب الشخصي في نهاية تلخيص الموضوع شرطًا أساسيًا.","answer":false,"reasons":["لأن التلخيص يلتزم بالأمانة العلمية ولا يضيف آراء من خارج النص الأصلي","لأن الرأي الشخصي هو التلخيص","لأن أفكار الكاتب غير مهمة"],"reason":0}],"hard":[{"type":"mcq","q":"ما العيب في ملخّصٍ جُمعت فيه الجمل المفتاحية لكل فقرة كما هي دون روابط؟","options":["يبدو مفكّكًا ومنسوخًا لا متماسكًا بأسلوب الطالب","يكون طويلًا جدًا","يخلو من الأفكار","يكون خياليًا"],"answer":0,"why":"لا بد من إعادة الصياغة والربط اللغوي ليصبح نصًا متماسكًا."},{"type":"essay","q":"اشرح كيف تتحقّق من جودة ملخّصك بعد الانتهاء من كتابته.","model":"أقارنه بالنص الأصلي للتأكد من وجود كل الأفكار الرئيسة، ومن عدم وجود آراء خارجية، ومن مناسبة الحجم (الربع إلى الثلث)، ثم أراجع الإملاء والنحو والترقيم."},{"type":"tfr","q":"قد تحتوي فقرتان في النص الأصلي على فكرة متقاربة فيمكن دمجهما في جملة واحدة في الملخّص.","answer":true,"reasons":["لأن الدمج الذكي يمنع التكرار ويحقق الإيجاز المطلوب","لأن كل فقرة يجب أن تصبح صفحتين","لأن الدمج يغيّر معنى النص دائمًا"],"reason":0},{"type":"mcq","q":"عند تلخيص موضوع علمي، أيّ عنصرٍ يجب الحفاظ عليه بدقة؟","options":["الأمثلة الطريفة","الحقائق والنتائج العلمية الرئيسة","المقدمات الإنشائية الطويلة","التكرار"],"answer":1,"why":"الحقائق والنتائج هي جوهر النص العلمي."},{"type":"essay","q":"لخّص في سطرين: «الإنترنت وسيلة عظيمة للتعلم والبحث والتواصل مع العالم بسرعة فائقة. غير أن الاستخدام المفرط له دون ضوابط يضيّع الوقت ويؤذي البصر. ومن هنا تبرز أهمية الاستخدام الواعي والمتوازن».","model":"يُعدّ الإنترنت وسيلةً مفيدةً للتعلم والتواصل، لكنّ الإفراط فيه يضيّع الوقت ويضرّ بالصحة، لذا ينبغي استخدامه بوعي وتوازن."},{"type":"tfr","q":"قراءة الموضوع كاملًا قبل البدء باستخراج أفكار الفقرات تمنع الفهم الجزئي الخاطئ.","answer":true,"reasons":["لأن النظرة الشاملة تكشف الفكرة العامة وتوضح علاقة الفقرات ببعضها","لأن القراءة الأولى غير ضرورية","لأن التلخيص يبدأ من السطر الأخير"],"reason":0},{"type":"mcq","q":"ما أثر استخدام الكلمات الدقيقة الجامعة في التلخيص؟","options":["توصيل المعنى بأقل عدد من الكلمات دون إخلال","إطالة النص","إدخال الغموض","حذف المعنى"],"answer":0,"why":"الدقة اللغوية تساعد على الإيجاز الواضح."},{"type":"essay","q":"ما الفرق بين «تلخيص موضوع» و«كتابة موضوع جديد»؟","model":"في تلخيص موضوع نلتزم بأفكار الكاتب الأصلي بأمانة ونوجزها بأسلوبنا، أما في كتابة موضوع جديد فنبتكر أفكارنا وشواهدنا ونوسّعها."},{"type":"tfr","q":"تغيير معنى فكرة الكاتب أثناء اختصارها يُعدّ إخلالًا بشرط الأمانة العلمية.","answer":true,"reasons":["لأن الملخّص يجب أن يحفظ جوهر المعنى الأصلي بدقة دون تحريف","لأن الاختصار يبيح تغيير المعنى","لأن المعنى غير مهم"],"reason":0},{"type":"essay","q":"اكتب ثلاث نصائح لزميلك لتلخيص درس تاريخي طويل قبل الاختبار.","model":"١) قسّم الدرس إلى عناوين وفقرات. ٢) اكتب فكرة كل فقرة وأهم التواريخ والأحداث في جملة موجزة. ٣) اربطها في ملخّص قصير وراجعه قبل الاختبار."}]}},
  {"id":"g9-arabic-1-u5-5","grade":"g9","subject":"arabic","term":1,"unit":5,"no":5,"title":"النص الأدبي: يا كوكبًا ما كان أقصر عمره","summary":"شرح متحرك لقصيدة «يا كوكبًا ما كان أقصر عمره» لأبي الحسن التهامي وأفكارها وعاطفتها وصورها الجمالية، ثم أنشطة بثلاثة مستويات.","page":"lesson-ya-kawkaban.html","video":"","pdf":"","notes":["قائل القصيدة هو الشاعر أبو الحسن التهامي، وغرضها «الرثاء» (رثاء ابنه الصغير الذي توفي في صباه).","في المطلع يشبّه ابنه بالكوكب المضيء قصير العمر: «يا كوكبًا ما كان أقصر عمره / وكذاك عمر كواكب الأسحار».","كما يشبّهه بالهلال الذي لم يكتمل بدرًا حتى أسرع إليه الخسوف والرحيل.","يعبّر الشاعر عن عمق الحزن والفجيعة، لكنه يمزج حزنه بالتسليم بقضاء الله وقدره.","من أساليبها: النداء للتحسّر (يا كوكبًا)، والتعجب (ما كان أقصر عمره)، والتشبيه البليغ والاستعارة.","تمتاز القصيدة بصدق العاطفة الأبوية وسهولة الألفاظ ورقة الإيقاع الموسيقي."],"exercises":["من قائل قصيدة «يا كوكبًا ما كان أقصر عمره» وما مناسبتها؟","اشرح التشبيه في مطلع القصيدة.","كيف مزج الشاعر بين حزنه الشديد وبين الإيمان والتسليم بقضاء الله؟"],"levels":{"easy":[{"type":"mcq","q":"من قائل قصيدة «يا كوكبًا ما كان أقصر عمره»؟","options":["أبو الطيب المتنبي","أبو الحسن التهامي","أبو تمام","البوصيري"],"answer":1,"why":"قالها أبو الحسن التهامي في رثاء ابنه الصغير."},{"type":"mcq","q":"ما الغرض الشعري لقصيدة «يا كوكبًا ما كان أقصر عمره»؟","options":["الفخر","الرثاء","الوصف","المدح"],"answer":1,"why":"رثى فيها ابنه الذي توفي صغيرًا."},{"type":"mcq","q":"ما المقصود بـ «الأسحار» في البيت الأول؟","options":["أوقات آخر الليل قبيل الفجر","أوقات الظهيرة","فصل الصيف","النجوم البعيدة"],"answer":0,"why":"الأسحار جمع سَحَر وهو الوقت الذي يسبق الفجر."},{"type":"mcq","q":"ما أسلوب «ما كان أقصر عمره»؟","options":["أسلوب نهي","أسلوب تعجّب","أسلوب شرط","أسلوب أمر"],"answer":1,"why":"أسلوب تعجب يبرز قصر حياة ابنه وسرعة رحيله."}],"medium":[{"type":"mcq","q":"لماذا شبّه الشاعر ابنه بـ «كواكب الأسحار» تحديدًا؟","options":["لأنها تضيء قليلًا قبيل الفجر ثم تختفي سريعًا كعمر ابنه القصير","لأنها تبقى طوال النهار","لأنها مظلمة","لأنها لا تُرى"],"answer":0,"why":"كواكب الفجر تشرق فترة قصيرة ثم تأفل سريعًا، فوافقت حال ابنه."},{"type":"tfr","q":"النداء في «يا كوكبًا» غرضه التحسّر والألم على فقد الابن.","answer":true,"reasons":["لأن الشاعر ينادي ابنه المتوفى بقلب مفجوع متحسّر","لأنه يطلب منه الحضور فقط","لأنه أسلوب سخرية"],"reason":0},{"type":"essay","q":"اشرح صورة تشبيه الابن بـ «الهلال» كما وردت في القصيدة.","model":"شبّه الشاعر ابنه الصغير بالهلال الذي ينتظر الناس اكتماله بدرًا، لكن الموت عاجله قبل أن يبلغ تمام شبابه وعطائه."},{"type":"tfr","q":"خلت قصيدة التهامي من الحكمة والتأمّل في حقيقة الدنيا والموت.","answer":false,"reasons":["لأن الشاعر ارتقى بحزنه إلى التأمل والحكمة فبيّن أن الدنيا دار فناء والجميع عابرون","لأنها قصيدة مدح","لأنها تتحدث عن السفر فقط"],"reason":0},{"type":"mcq","q":"ما الحقل الدلالي الذي استمدّ منه الشاعر أبرز صوره في القصيدة؟","options":["السماء والضوء (الكوكب، الأسحار، الهلال، البدر)","البحار والسفن","المعارك والسيوف","الأسواق والتجارة"],"answer":0,"why":"صور السماء والضياء ترفع مكانة الابن وتبرز بهاءه في قلب أبيه."},{"type":"essay","q":"اذكر ثلاث خصائص فنية لأسلوب التهامي في هذه القصيدة.","model":"صدق العاطفة الأبوية، ورقة الألفاظ وسهولتها، وجمال الصور المستمدّة من السماء، وعذوبة الإيقاع الحزين."},{"type":"tfr","q":"امتزج حزن الشاعر في القصيدة بالتسليم والرضا بقضاء الله وقدره.","answer":true,"reasons":["لأن الإيمان بالقدر يواسي المؤمن ويخفّف عنه وقع الفجيعة","لأن الشاعر رفض الصبر","لأن القصيدة تخلو من العاطفة"],"reason":0}],"hard":[{"type":"mcq","q":"ما نوع الصورة الفنية في مناداة الابن بقوله «يا كوكبًا»؟","options":["استعارة تصريحية (شبّه ابنه بالكوكب وحذف المشبّه)","طباق","جناس","سجع"],"answer":0,"why":"صرّح بالمشبّه به (الكوكب) وحذف المشبّه (الابن) فهي استعارة تصريحية."},{"type":"essay","q":"لماذا عُدّت قصيدة التهامي من أصدق وأشهر قصائد الرثاء في الأدب العربي؟","model":"لأنها نابعة من تجربة أبوية حقيقية مفجعة، بعيدة عن التكلّف، وجمعت بين رقة التعبير وعمق التصوير والحكمة المؤثّرة."},{"type":"tfr","q":"يرمز «البدر» في القصيدة إلى مرحلة اكتمال الشباب والعطاء التي لم يبلغها الابن.","answer":true,"reasons":["لأن الهلال يكبر ليصبح بدرًا، وكذلك الطفل يكبر ليصبح شابًا ناضجًا","لأن البدر يرمز للظلام","لأن البدر يرمز للطفولة"],"reason":0},{"type":"mcq","q":"ما أثر الجمع بين النداء والتعجب في مطلع القصيدة؟","options":["تكثيف مشاعر الفجيعة وإثارة تعاطف القارئ منذ اللحظة الأولى","إخفاء العاطفة","إدخال الفكاهة","تقديم معلومة علمية"],"answer":0,"why":"يفتح المطلع بصرخة وجدانية صادقة تشدّ القارئ مباشرةً."},{"type":"essay","q":"كيف تعبّر القصيدة عن التوازن بين الحزن الفطري وبين الصبر الإيماني؟","model":"لم يُنكر الشاعر ألمه وحزنه الطبيعي كأبٍ مفجوع، لكنه قابل المصيبة بالتأمّل في فناء الدنيا والرضا بقضاء الله."},{"type":"tfr","q":"يظهر في القصيدة تكلّفٌ لغويٌّ وألفاظٌ غريبةٌ يصعب فهمها.","answer":false,"reasons":["لأن ألفاظها رقيقة سهلة عذبة تلائم صدق العاطفة الأبوية","لأنها مكتوبة بالعامية","لأن الرثاء لا يُفهم"],"reason":0},{"type":"mcq","q":"أيُّ بيتٍ يعكس قانون الحياة الذي استخلصه الشاعر من موت ابنه؟","options":["أن الدنيا دار فناء وزوال وأن الجميع فيها عابرون","أن الشباب يدوم للأبد","أن الكواكب لا تختفي","أن المال يمنع الموت"],"answer":0,"why":"استخلص التهامي حكمة فناء الدنيا ومصير البشر جميعًا."},{"type":"essay","q":"اشرح البيت الأول بأسلوبك الأدبي: «يا كوكبًا ما كان أقصر عمره / وكذاك عمر كواكب الأسحار».","model":"ينادي الشاعر ابنه الراحل مشبّهًا إياه بالكوكب المضيء، متعجبًا بحسرةٍ من قصر عمره، فهكذا شأن نجوم الفجر التي تلمع قليلًا ثم تغيب سريعًا."},{"type":"tfr","q":"التصوير بالنجوم والكواكب في الرثاء يوحي بسموّ مكانة المرثي ونقائه.","answer":true,"reasons":["لأن الكوكب عالٍ مضيء نقيّ، فيعبّر عن حب الأب وتقديره لابنه","لأنه يوحي بالانخفاض","لأنه يوحي بالظلام"],"reason":0},{"type":"essay","q":"قارن بإيجاز بين غرض قصيدة «يا سماء» للبوصيري وغرض قصيدة «يا كوكبًا» للتهامي.","model":"قصيدة «يا سماء» غرضها المدح النبوي وعاطفتها التعظيم والشوق، أما قصيدة «يا كوكبًا» فغرضها الرثاء وعاطفتها الحزن الأبوي والأسى والصبر."}]}},
  {"id":"g9-arabic-1-u6-1","grade":"g9","subject":"arabic","term":1,"unit":6,"no":1,"title":"القراءة: سيرة بقلم صاحبها","summary":"شرح متحرك لفن السيرة الذاتية والفرق بينها وبين السيرة الغيرية وخصائصها الفنية، ثم أنشطة بثلاثة مستويات.","page":"lesson-autobiography.html","video":"","pdf":"","notes":["السيرة الذاتية: فن أدبي نثري يروي فيه الكاتب قصة حياته أو جانبًا منها بقلمه وبضمير المتكلم (أنا).","السيرة الغيرية (ترجمة العلم): يكتبها مؤلّف آخر عن شخصية مشهورة بضمير الغائب (هو).","من أشهر السير الذاتية في الأدب العربي: كتاب «الأيام» لطه حسين.","من خصائص السيرة الذاتية: الصدق والصراحة، والتسلسل الزمني، والجمع بين السرد والوصف والتأمل.","تُعدّ السيرة الذاتية وثيقةً إنسانيةً وتاريخيةً تعكس بيئة الكاتب وعصره وتجاربه.","من أهداف كتابتها: نقل الخبرات والتجارب للأجيال، وتوثيق مرحلة تاريخية، والاعتراف بفضل الآخرين."],"exercises":["قارن بين السيرة الذاتية والسيرة الغيرية من حيث الكاتب والضمير المستخدم.","اذكر ثلاث خصائص فنية لفن السيرة الذاتية.","ما الفائدة التي يجنيها القارئ من قراءة السير الذاتية للأدباء والعلماء؟"],"levels":{"easy":[{"type":"mcq","q":"ما المقصود بالسيرة الذاتية؟","options":["نص يكتب فيه الكاتب قصة حياته بنفسه","نص يكتبه مؤلف عن شخص آخر","قصيدة مدح","معجم لغوي"],"answer":0,"why":"السيرة الذاتية هي سيرة بقلم صاحبها."},{"type":"mcq","q":"ما الضمير الغالب استخدامه في السيرة الذاتية؟","options":["ضمير المتكلم (أنا)","ضمير الغائب (هو)","ضمير المخاطب (أنت)","ضمير الغائبين (هم)"],"answer":0,"why":"لأن الكاتب يروي أحداث حياته بنفسه."},{"type":"mcq","q":"من مؤلّف السيرة الذاتية الشهيرة «الأيام»؟","options":["الجاحظ","طه حسين","المتنبي","البوصيري"],"answer":1,"why":"كتب الأديب طه حسين سيرته الذاتية الشهيرة «الأيام»."},{"type":"mcq","q":"ما الشرط الأهم لكي يثق القارئ بالسيرة الذاتية؟","options":["الصدق والصراحة","المبالغة والتفاخر","الخيال البعيد","الغموض"],"answer":0,"why":"الصدق والتواضع يمنحان السيرة الذاتية قيمة إنسانية وتاريخية."}],"medium":[{"type":"mcq","q":"ما الفرق الجوهري بين السيرة الذاتية والسيرة الغيرية؟","options":["الذاتية يكتبها الشخص عن نفسه والغيرية يكتبها غيره عنه","الذاتية شعر والغيرية نثر","الذاتية قصيرة دائمًا","لا يوجد فرق"],"answer":0,"why":"في الذاتية الكاتب هو البطل، وفي الغيرية المؤلف يكتب عن شخصية أخرى."},{"type":"tfr","q":"تُعدّ السيرة الذاتية وثيقةً اجتماعيةً وتاريخيةً تعكس ملامح عصر الكاتب.","answer":true,"reasons":["لأنها تصف العادات والمدارس والحياة اليومية في الزمن الذي عاش فيه الكاتب","لأنها لا تذكر أي أماكن","لأنها خيالية بالكامل"],"reason":0},{"type":"essay","q":"اذكر ثلاثة أهداف لكتابة السيرة الذاتية.","model":"١) نقل الخبرات والتجارب للأجيال. ٢) توثيق مرحلة تاريخية واجتماعية. ٣) التعبير عن الوفاء والامتنان لمن أثّروا في حياة الكاتب."},{"type":"tfr","q":"ينبغي لكاتب السيرة الذاتية أن يذكر نجاحاته فقط ويُخفي كل إخفاقاته وتحدياته.","answer":false,"reasons":["لأن ذكر التحديات والإخفاقات وكيف تغلّب عليها يمنح السيرة صدقًا وفائدة تربوية","لأن التحديات لا تهم القارئ","لأن السيرة للمبالغة فقط"],"reason":0},{"type":"mcq","q":"ما الأساليب التي تمزج بينها السيرة الذاتية عادةً؟","options":["السرد والوصف والتأمل الشخصي","الأرقام فقط","الأوامر فقط","القوافي فقط"],"answer":0,"why":"تجمع السيرة بين حكاية الأحداث ووصف الأماكن وتأمل التجارب."},{"type":"essay","q":"قارن بين «سيرة بقلم صاحبها» و«ترجمة علم» من حيث الضمير والكاتب.","model":"في السيرة الذاتية الكاتب هو صاحب الحياة ويستخدم ضمير المتكلم (أنا)، أما في ترجمة العلم فالكاتب شخص آخر ويستخدم ضمير الغائب (هو)."},{"type":"tfr","q":"يُعدّ التسلسل الزمني من الطفولة إلى النضج من أبرز طرق بناء السيرة الذاتية.","answer":true,"reasons":["لأنه يجعل تطور شخصية الكاتب وتجاربه واضحًا ومترابطًا للقارئ","لأن السيرة لا ترتيب لها","لأنها تبدأ دائمًا من المستقبل"],"reason":0}],"hard":[{"type":"mcq","q":"لماذا يتعاطف القارئ مع السيرة الذاتية الصادقة أكثر من غيرها؟","options":["لأنها تكشف الجانب الإنساني الحقيقي للتحديات والنجاح بلا تصنّع","لأنها مليئة بالمبالغات","لأنها قصيرة جدًا","لأنها تخلو من المشاعر"],"answer":0,"why":"الصدق الإنساني يلامس القارئ ويشعره بقرب التجربة."},{"type":"essay","q":"ما الفوائد التي يجنيها طالب الصف التاسع من قراءة السير الذاتية للعلماء والأدباء؟","model":"يتعلّم منهم الصبر والمثابرة، ويستفيد من تجاربهم في التغلب على الصعاب، ويتعرّف تاريخ مجتمعهم وثقافته، ويستلهم القدوة الحسنة."},{"type":"tfr","q":"كتب طه حسين «الأيام» بضمير الغائب (الصبي) رغم أنها سيرة ذاتية، وهذا أسلوب فني خاص للموضوعية.","answer":true,"reasons":["لأنه أراد أن ينظر إلى طفولته بنظرة موضوعية كأنه يتحدث عن شخص آخر، وإن كان الأصل في السيرة الذاتية ضمير المتكلم","لأنها ليست سيرته الذاتية","لأن ضمير المتكلم ممنوع"],"reason":0},{"type":"mcq","q":"أيُّ جملةٍ مما يأتي تمثّل أسلوب «السيرة الذاتية»؟","options":["وُلد الخليل في البصرة ونشأ محبًّا للعلم.","لن أنسى أول يومٍ دخلتُ فيه مدرستي وأنا أحمل حقيبتي بشغف.","تقع سلطنة عُمان في الجنوب الشرقي.","المفعول المطلق مصدر منصوب."],"answer":1,"why":"تروي موقفًا شخصيًا بضمير المتكلم (أنا) ومشاعر صادقة."},{"type":"essay","q":"اكتب فقرة قصيرة من ثلاث جمل من سيرتك الذاتية عن موقفٍ دراسيٍّ لا تنساه.","model":"مثال: لن أنسى يوم شاركتُ لأول مرة في الإذاعة المدرسية؛ فقد كنتُ متوترًا في البداية، لكن تشجيع معلمي منحني الثقة، وتعلّمتُ يومها أن الجرأة تبدأ بخطوة."},{"type":"tfr","q":"الاعتراف بفضل الوالدين والمعلمين في السيرة الذاتية يعكس قيمة الوفاء والتواضع.","answer":true,"reasons":["لأن النجاح ثمرة جهد الفرد ودعم أسرته ومعلميه، وذكرهم دليل وفاء","لأن الكاتب لا يذكر غير نفسه","لأن الوفاء يضعف السيرة"],"reason":0},{"type":"mcq","q":"متى تتحول السيرة الذاتية إلى مصدر تاريخي مهم؟","options":["حين توثّق بصدق أحداث العصر وحياة المجتمع وتقاليده","حين تعتمد على الخيال فقط","حين تخلو من التواريخ والأماكن","حين تكون من سطر واحد"],"answer":0,"why":"التوثيق الصادق للبيئة والعصر يمنحها قيمة تاريخية عالية."},{"type":"essay","q":"اذكر ثلاثة عناصر يجب توافرها عند كتابة موقف من سيرتك الذاتية.","model":"١) استخدام ضمير المتكلم. ٢) تحديد الزمان والمكان والأحداث بصدق. ٣) التعبير عن المشاعر والدرس المستفاد."},{"type":"tfr","q":"السيرة الذاتية تُصنّف ضمن فنون الشعر العمودي.","answer":false,"reasons":["لأنها فن أدبي نثري يعتمد على السرد والوصف والتأمل","لأنها مسرحية غنائية","لأنها معجم مصطلحات"],"reason":0},{"type":"essay","q":"اشرح كيف يوازن كاتب السيرة الذاتية بين ذكر إنجازاته وبين التواضع.","model":"يذكر إنجازاته كحقائق موضوعية يبيّن فيها الجهد والتعلّم ومن ساعدوه، دون تفاخر مبالغ فيه أو تقليل من شأن الآخرين."}]}},
  {"id":"g9-arabic-1-u6-3","grade":"g9","subject":"arabic","term":1,"unit":6,"no":3,"title":"الأنشطة الإملائية: رسم الألف في أواخر الأفعال","summary":"شرح متحرك لقواعد كتابة الألف اللينة في أواخر الأفعال الثلاثية وفوق الثلاثية، ثم أنشطة بثلاثة مستويات.","page":"lesson-alif-end-verbs.html","video":"","pdf":"","notes":["في الفعل الثلاثي نبحث عن أصل الألف بإسناده إلى تاء الفاعل أو ردّه للمضارع أو المصدر.","إذا كان أصل الألف واوًا تُكتب قائمة (ا): دَعَا (يدعو، دعوتُ)، نَمَا (ينمو)، سَمَا (يسمو)، نَجَا (ينجو).","إذا كان أصل الألف ياءً تُكتب مقصورة (ى): رَمَى (يرمي، رميتُ)، مَشَى (يمشي)، قَضَى (يقضي)، هَدَى (يهدي).","في الفعل فوق الثلاثي (رباعي، خماسي، سداسي) تُكتب الألف مقصورة (ى) مثل: أَعْطَى، اهْتَدَى، اسْتَدْعَى، اشْتَرَى.","استثناء في الفعل فوق الثلاثي: إذا سبقت الألف ياءٌ تُكتب قائمة (ا)، مثل: أَحْيَا، اسْتَحْيَا، يَحْيَا.","تُعدّ تاء الفاعل (دعوتُ / رميتُ) أدقّ اختبارٍ لمعرفة أصل الألف في الفعل الثلاثي (مثل: سَعَى ← سَعَيْتُ فهي ياء)."],"exercises":["علّل رسم الألف في أواخر الأفعال: دَعَا، مَشَى، اشْتَرَى، أَحْيَا.","كيف نعرف أصل الألف في الفعل «سَعَى» رغم أن مضارعه «يَسْعَى»؟","صوّب الخطأ الإملائي: «دعى المؤمنُ ربّه ثم مشا إلى المسجد واستحى من الخطأ»."],"levels":{"easy":[{"type":"mcq","q":"كيف يُكتب الفعل الماضي من «يَنْمُو»؟","options":["نَمَا","نَمَى","نَمَأ","نَمَء"],"answer":0,"why":"أصل الألف واو (ينمو، نموتُ) فتُكتب قائمة."},{"type":"mcq","q":"كيف يُكتب الفعل الماضي من «يَبْنِي»؟","options":["بَنَا","بَنَى","بَنَأ","بَنَء"],"answer":1,"why":"أصل الألف ياء (يبني، بنيتُ) فتُكتب مقصورة."},{"type":"mcq","q":"كيف يُكتب الفعل «اسْتَدْعـ...»؟","options":["استدعا","استدعى","استدعئ","استدعي"],"answer":1,"why":"فعل سداسي (فوق ثلاثي) لم تسبق ألفه ياء فتُكتب مقصورة."},{"type":"mcq","q":"كيف يُكتب الفعل «اسْتَحْيـ...»؟","options":["استحيا","استحيى","استحيأ","استحيء"],"answer":0,"why":"فعل فوق ثلاثي سبقت ألفه ياء فتُكتب قائمة."}],"medium":[{"type":"mcq","q":"أيُّ اختبارٍ يكشف أصل الألف في الفعل «سَعَى» بدقة؟","options":["إسناده لتاء الفاعل: سَعَيْتُ","مضارعه: يَسْعَى","الأمر منه: اسْعَ","عدّ حروفه"],"answer":0,"why":"في المضارع تبقى ألفًا، أما مع تاء الفاعل «سعيتُ» فتظهر الياء بوضوح."},{"type":"tfr","q":"تُكتب الألف في الفعل «رَمَى» مقصورة، فإذا اتصل به ضمير تصبح قائمة: «رَمَاهُ».","answer":true,"reasons":["لأن الألف تصبح متوسطة وليست متطرفة فتُكتب قائمة","لأن أصلها واو","لأن الضمير يحذف الألف"],"reason":0},{"type":"essay","q":"علّل رسم الألف في الأفعال الآتية: نَجَا، قَضَى، اهْتَدَى، أَحْيَا.","model":"نجا: ثلاثي أصلها واو (ينجو). قضى: ثلاثي أصلها ياء (يقضي). اهتدى: فوق ثلاثي بلا ياء قبله. أحيا: فوق ثلاثي قبلها ياء."},{"type":"tfr","q":"الفعل «أَعْطَى» كُتبت ألفه مقصورة لأن أصلها ياء.","answer":false,"reasons":["لأنه فعل رباعي (فوق ثلاثي) لم تسبق ألفه ياء، فلا نبحث عن أصل الألف في غير الثلاثي","لأنه ثلاثي واوي","لأن قبله ياء"],"reason":0},{"type":"mcq","q":"أيُّ مجموعة أفعال مما يأتي كُتبت كلها صحيحة؟","options":["دعا، مشى، اشترى، أحيا","دعى، مشا، اشترا، أحيى","سما، بكا، انتهى، استحيا","عفا، هدا، أعطى، يحيا"],"answer":0,"why":"كل فعل فيها مطابق للقاعدة الإملائية بدقة."},{"type":"essay","q":"صوّب الأخطاء في الجملة: «دعى المسلمُ ربّه ثم مشا إلى المسجد واشترى كتابًا وأحيى ليلَهُ بالقراءة».","model":"دعا المسلمُ ربّه ثم مشى إلى المسجد واشترى كتابًا وأحيا ليلَهُ بالقراءة."},{"type":"tfr","q":"الفعل «عَفَا» كُتبت ألفه قائمة لأن مضارعه «يَعْفُو».","answer":true,"reasons":["لأنه فعل ثلاثي أصل ألفه واو (عفوتُ / يعفو)","لأنه فعل رباعي","لأن قبله ياء"],"reason":0}],"hard":[{"type":"mcq","q":"ما الصواب في: «........ اللهُ الأرضَ بالمطرِ، و........ المؤمنُ إلى الخيرِ»؟","options":["أحيا / سعى","أحيى / سعا","أحيا / سعا","أحيى / سعى"],"answer":0,"why":"أحيا (فوق ثلاثي قبلها ياء ← ا)، سعى (ثلاثي سعيتُ ← ى)."},{"type":"essay","q":"فرّق بين رسم «عَصَا» و«عَصَى» مع ذكر نوع كل كلمة وسبب كتابة الألف.","model":"«عَصَا» اسم ثلاثي أصل ألفه واو (عصوان) فتُكتب قائمة. «عَصَى» فعل ثلاثي أصل ألفه ياء (يعصي) فتُكتب مقصورة."},{"type":"tfr","q":"في الفعل «ارْتَضَى» تُكتب الألف مقصورة رغم أن مصدره «الرِّضْوَان» فيه واو.","answer":true,"reasons":["لأن «ارتضى» خماسي (فوق ثلاثي)، وفي غير الثلاثي تُكتب الألف مقصورة بغض النظر عن أصلها ما لم تسبقها ياء","لأن أصلها ياء","لأنه ثلاثي"],"reason":0},{"type":"mcq","q":"أيُّ فعلٍ مما يأتي أصل ألفه واو؟","options":["سَمَا","هَدَى","بَكَى","رَأَى"],"answer":0,"why":"سما ← يسمو / سموتُ (واو)."},{"type":"essay","q":"أدخل ضمير الغائب «ـهُ» على الأفعال: رَمَى، هَدَى، اشْتَرَى، واكتبها صحيحة.","model":"رَمَاهُ، هَدَاهُ، اشْتَرَاهُ. (تُكتب الألف قائمة لتوسطها)."},{"type":"tfr","q":"الفعل «أَعْيَا» كُتبت ألفه قائمة لأنها مسبوقة بياء في فعل فوق ثلاثي.","answer":true,"reasons":["لأن الفعل رباعي وسبقت ألفه ياء فتُكتب قائمة","لأنه ثلاثي واوي","لأنه اسم أعجمي"],"reason":0},{"type":"mcq","q":"ما أصل الألف في الفعل «رَضِيَ»؟","options":["أصلها ياء (تظهر في الماضي نفسه)","أصلها واو","لا ينتهي بألف أصلًا","فوق ثلاثي"],"answer":2,"why":"«رَضِيَ» ينتهي بياء مكسور ما قبلها وليس بألف لينة."},{"type":"essay","q":"هاتِ أربعة أفعال ماضية تمثّل: ثلاثي واوي، ثلاثي يائي، فوق ثلاثي بلا ياء، وفوق ثلاثي قبله ياء.","model":"مثال: دَعَا، مَشَى، اسْتَدْعَى، اسْتَحْيَا."},{"type":"tfr","q":"الفعل «نَسِيَ» يُصنّف ضمن الأفعال المنتهية بألف مقصورة.","answer":false,"reasons":["لأنه ينتهي بياء أصلية منطوقة (نَسِيَ) وليست ألفًا لينة","لأنه ينتهي بألف قائمة","لأنه فوق ثلاثي"],"reason":0},{"type":"essay","q":"اكتب فقرة من جملتين توظّف فيها ثلاثة أفعال منتهية بألف لينة بأنواع مختلفة.","model":"مثال: دعا الطالبُ ربّه بالتوفيق، وسعى بجدٍّ في مذاكرته، حتى اهتدى إلى طريق التفوّق والنجاح."}]}},
  {"id":"g9-arabic-1-u6-5","grade":"g9","subject":"arabic","term":1,"unit":6,"no":5,"title":"الاستماع: علم الآثار في عصر الفضاء","summary":"شرح متحرك لنص الاستماع «علم الآثار في عصر الفضاء» وتكامل التقنية الحديثة مع البحث الأثري، ثم أنشطة بثلاثة مستويات.","page":"lesson-archaeology-space.html","video":"","pdf":"","notes":["علم الآثار هو العلم الذي يدرس بقايا الحضارات القديمة لفهم تاريخ الإنسان وتطوّره.","في الماضي اعتمد علماء الآثار على الحفر اليدوي والبحث الميداني البطيء والمكلف.","في عصر الفضاء، أتاح «الاستشعار عن بُعد» والأقمار الصناعية تصوير سطح الأرض بدقة فائقة.","تستطيع الأشعة تحت الحمراء والرادارات الفضائية رصد معالم مدفونة تحت الرمال والغابات.","أسهمت هذه التقنية في اكتشاف طرق تجارية قديمة ومدن أثرية (كطرق اللبان والمدن المدفونة في رمال الجزيرة العربية).","تساعد تقنيات الفضاء أيضًا في مراقبة المواقع الأثرية وحمايتها من التلف والتعديات."],"exercises":["كيف غيّرت الأقمار الصناعية طريقة عمل علماء الآثار؟","ما المقصود بتقنية «الاستشعار عن بُعد»؟","اذكر فائدتين لتوظيف علوم الفضاء في خدمة علم الآثار."],"levels":{"easy":[{"type":"mcq","q":"ما العلم الذي يدرس بقايا الحضارات القديمة لفهم تاريخ الإنسان؟","options":["علم الفلك","علم الآثار","علم النبات","علم الصرف"],"answer":1,"why":"علم الآثار يدرس المخلفات المادية للحضارات القديمة."},{"type":"mcq","q":"ما التقنية التي تستخدمها الأقمار الصناعية لرصد المعالم المدفونة؟","options":["الاستشعار عن بُعد","الحفر اليدوي","المجهر فقط","الرسم اليدوي"],"answer":0,"why":"الاستشعار عن بُعد يكشف ما تحت الرمال والغابات من الفضاء."},{"type":"mcq","q":"ماذا ساعدت صور الأقمار الصناعية على تتبّعه في الجزيرة العربية؟","options":["طرق قوافل اللبان والمدن المدفونة","أعماق المحيط المتجمد","الجبال الجليدية","القطارات الحديثة"],"answer":0,"why":"كشفت مسارات طرق التجارة القديمة ومواقع مدفونة تحت الرمال."},{"type":"mcq","q":"ما الفكرة العلمية الكبرى التي يؤكّدها هذا الدرس؟","options":["تكامل العلوم والتقنية الحديثة","انفصال التاريخ عن العلم","الاستغناء عن العلماء","إهمال التراث"],"answer":0,"why":"تعاون الفضاء والفيزياء والحاسوب مع علم الآثار نموذج لتكامل العلوم."}],"medium":[{"type":"mcq","q":"كيف تختلف طريقة التنقيب حديثًا عن الماضي؟","options":["حديثًا توفّر الأقمار الصناعية الوقت والجهد وتحدّد المواقع بدقة قبل الحفر","قديمًا كانت أسرع","لا يوجد أي فرق","حديثًا لا يوجد حفر أبدًا"],"answer":0,"why":"تختصر التقنية الفضائية سنوات من البحث العشوائي."},{"type":"tfr","q":"تستطيع الرادارات الفضائية والأشعة تحت الحمراء رصد أساسات مبانٍ مدفونة تحت الرمال.","answer":true,"reasons":["لأنها تلتقط فروقًا دقيقة في التربة وطبقات الأرض لا تراها العين المجردة","لأن الرمال شفافة كالزجاج","لأنها تعتمد على الكاميرا العادية فقط"],"reason":0},{"type":"essay","q":"اذكر فائدتين لاستخدام الأقمار الصناعية في مجال الآثار.","model":"١) اكتشاف المدن والطرق الأثرية المدفونة وتوفير الوقت والجهد. ٢) مراقبة المواقع الأثرية وحمايتها من التلف والتعديات."},{"type":"tfr","q":"أغنت الأقمار الصناعية تمامًا عن عمل علماء الآثار على الأرض.","answer":false,"reasons":["لأن القمر الصناعي يحدّد الموقع، ثم ينزل العلماء للتنقيب الدقيق ودراسة اللقى الأثرية","لأن الأقمار تحفر الأرض بنفسها","لأن الآثار موجودة في الفضاء"],"reason":0},{"type":"mcq","q":"ما الذي ينبغي للطالب التركيز عليه عند الاستماع إلى نصٍّ علمي؟","options":["المصطلحات العلمية والمقارنات والنتائج","الألفاظ العامية","تجاهل التفاصيل","عدّ عدد الكلمات"],"answer":0,"why":"تدوين المصطلحات والمقارنات يسهّل فهم النص العلمي وتلخيصه."},{"type":"essay","q":"كيف يسهم الحفاظ على المواقع الأثرية في خدمة الحاضر والمستقبل؟","model":"يحفظ هوية الوطن وتاريخه العريق، ويُثري البحث العلمي، ويدعم السياحة الثقافية والاقتصاد الوطني."},{"type":"tfr","q":"تُستخدم صور الأقمار الصناعية أيضًا في رصد التعديات والأضرار البيئية على المواقع الأثرية.","answer":true,"reasons":["لأن المراقبة المستمرة من الفضاء تنبّه الجهات المختصة لحماية المواقع وصيانتها","لأنها تُستخدم في الطقس فقط","لأن المواقع الأثرية لا تحتاج حماية"],"reason":0}],"hard":[{"type":"mcq","q":"لماذا كان اكتشاف الآثار في الصحاري الشاسعة صعبًا جدًا قبل عصر الفضاء؟","options":["لاتساع المساحات وتغطية الرمال المتحركة للمعالم القديمة","لعدم وجود آثار في الصحاري","لكثرة الأنهار فيها","لصغر مساحتها"],"answer":0,"why":"الرمال الشاسعة تخفي المعالم ويصعب مسحها يدويًا."},{"type":"essay","q":"اشرح بمثال من الدرس كيف تتكامل العلوم الإنسانية مع العلوم التطبيقية.","model":"يتكامل علم الآثار والتاريخ (علم إنساني) مع تكنولوجيا الفضاء والرادار والحاسوب (علوم تطبيقية) لاكتشاف الحضارات القديمة وحمايتها."},{"type":"tfr","q":"تُظهر صور الاستشعار عن بُعد مجاري الأنهار الجافة القديمة التي قامت حولها الحضارات.","answer":true,"reasons":["لأن خصائص التربة والرطوبة تحت الرمال تكشف مسارات الأنهار القديمة فتدلّ على مواطن الاستيطان","لأن الأنهار الجافة تلمع ليلًا","لأنها لا تُرى أبدًا"],"reason":0},{"type":"mcq","q":"ما العلاقة بين عنوان الدرس «علم الآثار في عصر الفضاء» ومضمونه؟","options":["عنوان مشوّق يجمع بين الماضي (الآثار) والحاضر المتطور (الفضاء)","عنوان لا علاقة له بالنص","يتحدث عن آثار فوق القمر فقط","يتحدث عن الخيال العلمي فقط"],"answer":0,"why":"المفارقة اللطيفة بين الآثار والفضاء تجذب القارئ وتلخّص الفكرة."},{"type":"essay","q":"كيف توظّف سلطنة عُمان التقنية الحديثة في التعريف بمواقعها الأثرية كطرق اللبان؟","model":"من خلال توثيقها رقميًا وبصور الأقمار الصناعية، وإنشاء متاحف ومواقع إلكترونية تفاعلية، وحمايتها لصالح التراث العالمي والسياحة."},{"type":"tfr","q":"تُقلّل تقنية الاستشعار عن بُعد من التكلفة المادية والزمنية للبحث الأثري.","answer":true,"reasons":["لأنها توجّه الحفر مباشرة نحو المواقع المؤكدة بدل البحث العشوائي طويل الأمد","لأنها تزيد العشوائية","لأنها تبطئ العمل"],"reason":0},{"type":"mcq","q":"أيُّ مهارةٍ مما يأتي يحتاجها عالم الآثار في القرن الحادي والعشرين؟","options":["الجمع بين المعرفة التاريخية ومهارات التقنية وتحليل البيانات","الكتابة بالريشة فقط","الابتعاد عن الحاسوب","رفض التعاون العلمي"],"answer":0,"why":"عالم اليوم يجمع بين تخصصه والتقنيات الحديثة."},{"type":"essay","q":"لخّص في جملتين الفكرة العامة لنص «علم الآثار في عصر الفضاء».","model":"أحدثت الأقمار الصناعية وتقنية الاستشعار عن بُعد ثورةً في علم الآثار؛ إذ مكّنت العلماء من اكتشاف المدن والطرق المدفونة بدقة، وأسهمت في مراقبة التراث الإنساني وحمايته."},{"type":"tfr","q":"يقتصر نفع الاكتشافات الأثرية على العلماء وحدهم دون المجتمع.","answer":false,"reasons":["لأنها تُثري الثقافة العامة وتعزّز الهوية الوطنية وتنشّط السياحة الثقافية","لأن الآثار تُخفى عن الناس","لأنها بلا قيمة"],"reason":0},{"type":"essay","q":"اقترح تقنيةً حديثةً أخرى (غير الأقمار الصناعية) يمكن أن تساعد في عرض الآثار للطلاب، وبيّن كيف.","model":"مثل تقنية الواقع الافتراضي (VR) أو النماذج ثلاثية الأبعاد، التي تتيح للطلاب التجوّل داخل القلاع والمدن الأثرية القديمة من داخل الصف."}]}},
  {"id":"g9-arabic-1-u6-6","grade":"g9","subject":"arabic","term":1,"unit":6,"no":6,"title":"اقرأ واستمتع: ألم تغتمض عيناك","summary":"شرح متحرك لنص «ألم تغتمض عيناك» للشاعر الأعشى وأفكاره ومعانيه وصوره الشعرية، ثم أنشطة بثلاثة مستويات.","page":"lesson-alam-taghtamid.html","video":"","pdf":"","notes":["قائل الأبيات هو الشاعر الجاهلي ميمون بن قيس المعروف بـ «الأعشى» ويلقّب بـ «صنّاجة العرب» لجمال موسيقى شعره.","يبدأ النص باستفهامٍ تقريريٍّ يصف فيه الأرق وطول الليل: «ألم تغتمض عيناك ليلة أرمدا / وبتَّ كما باتَ السليمُ مسهّدا».","«الأرمد» من أصابه الرمد في عينه، و«السليم» كنايةٌ وتفاؤلٌ عن اللديغ الذي لا ينام من شدة الألم.","يبيّن الشاعر أن أرقه ليس بسبب مرضٍ جسدي، بل بسبب الهمّ والتفكير والشوق.","يمتاز شعر الأعشى بجرسٍ موسيقيٍّ عذبٍ، ووضوح الألفاظ، وجمال التشبيه والتصوير.","تعكس الأبيات صدق المشاعر الإنسانية وعمق الخبرة بالحياة في الشعر العربي القديم."],"exercises":["لماذا لُقّب الشاعر الأعشى بـ «صنّاجة العرب»؟","ما معنى «السليم» في البيت الأول، ولماذا أطلقته العرب على اللديغ؟","اشرح التشبيه في مطلع القصيدة."],"levels":{"easy":[{"type":"mcq","q":"من قائل بيت: «ألم تغتمض عيناك ليلة أرمدا»؟","options":["المتنبي","الأعشى (ميمون بن قيس)","البوصيري","التهامي"],"answer":1,"why":"هو الشاعر الجاهلي ميمون بن قيس المعروف بالأعشى."},{"type":"mcq","q":"بماذا لُقّب الأعشى في تاريخ الأدب العربي؟","options":["صنّاجة العرب","أمير النثر","شيخ النحاة","الجاحظ"],"answer":0,"why":"لُقّب بصناجة العرب لجودة إيقاعه وموسيقى شعره."},{"type":"mcq","q":"ما المقصود بـ «السليم» في قول الأعشى «كما بات السليم مسهدا»؟","options":["اللديغ (من باب التفاؤل)","المعافى تمامًا","الطفل الصغير","المسافر"],"answer":0,"why":"تطلق العرب لفظ السليم على اللديغ تفاؤلًا بنجاته وسلامته."},{"type":"mcq","q":"ما معنى كلمة «مسهّدًا»؟","options":["ساهرًا لا ينام من الأرق","نائمًا بعمق","سعيدًا","مسرعًا"],"answer":0,"why":"السهاد هو الأرق وعدم النوم."}],"medium":[{"type":"mcq","q":"ما سبب الأرق الذي يشتكي منه الأعشى في الأبيات؟","options":["هموم النفس والذكريات والتفكير","الرمد الجسدي فقط","ضجيج السوق","المرض الشديد"],"answer":0,"why":"بيّن أن أرقه نفسي بسبب الهمّ لا بسبب مرض جسدي."},{"type":"tfr","q":"لُقّب الأعشى بـ «صنّاجة العرب» لعذوبة موسيقى شعره وحسن إيقاعه.","answer":true,"reasons":["لأن المغنّين كانوا يتغنّون بأشعاره لتناغم ألفاظها وسلاسة أوزانها","لأنه لم ينظم الشعر","لأنه كان كاتب نثر فقط"],"reason":0},{"type":"essay","q":"اشرح التشبيه في قول الأعشى: «وبتَّ كما باتَ السليمُ مسهّدا».","model":"شبّه الشاعر نفسه في سهره وأرقه باللديغ الذي يبيت ساهرًا طوال الليل لا يغمض له جفن، مما يبرز شدة همّه."},{"type":"tfr","q":"يُسمّى خطاب الشاعر لنفسه كأنها شخص آخر في البلاغة «التجريد».","answer":true,"reasons":["لأن الشاعر ينتزع من نفسه شخصًا آخر يخاطبه بـ «عيناك» و«بتَّ» لتنفيس همّه","لأنه يُسمّى طباقًا","لأنه خطأ نحوي"],"reason":0},{"type":"mcq","q":"ما الغرض من الاستفهام في «ألم تغتمض عيناك»؟","options":["التقرير والتأكيد على أرقه","طلب معلومة يجهلها","السخرية","التخيير"],"answer":0,"why":"الاستفهام المنفي «ألم» يفيد التقرير وتأكيد السهر."},{"type":"essay","q":"لماذا أطلقت العرب لفظ «السليم» على اللديغ؟","model":"من باب التفاؤل وحسن الفأل له بالسلامة والنجاة من السمّ."},{"type":"tfr","q":"ينتمي الشاعر الأعشى إلى شعراء العصر الحديث.","answer":false,"reasons":["لأنه من كبار شعراء العصر الجاهلي قبل الإسلام","لأنه من العصر العباسي","لأنه شاعر معاصر"],"reason":0}],"hard":[{"type":"mcq","q":"ما دلالة تشبيه ليلة الشاعر بـ «ليلة أرمدا»؟","options":["بيان شدة تعب عينيه من السهر وطول الليل","أنه ذهب للطبيب","أن الليل كان قصيرًا","أنه نام مبكرًا"],"answer":0,"why":"الأرمد لا يغمض عينه من الألم، فشبّه الشاعر ليلته بليلته لشدة الأرق."},{"type":"essay","q":"اذكر ثلاث خصائص فنية تبرز في أبيات الأعشى «ألم تغتمض عيناك».","model":"١) عذوبة الإيقاع والموسيقى. ٢) براعة التشبيه الحسي المؤثر. ٣) صدق العاطفة الإنسانية وسهولة الألفاظ."},{"type":"tfr","q":"يُعدّ تصوير طول الليل عند المهموم من الموضوعات المشتركة في الشعر الجاهلي.","answer":true,"reasons":["لأنه ظهر عند شعراء كبار كالأعشى وامرئ القيس والنابغة للتعبير عن الهمّ والأرق","لأن الأعشى وحده ذكر الليل","لأن الليل لا يُذكر في الشعر الجاهلي"],"reason":0},{"type":"mcq","q":"ما أثر أسلوب «التجريد» في قوله «ألم تغتمض عيناك»؟","options":["إظهار حوار داخلي يبوح فيه الشاعر بألمه ويشرك القارئ في مشاعره","إخفاء المعنى","إطالة البيت بلا فائدة","تحويل الشعر إلى نثر"],"answer":0,"why":"التجريد يجعل القارئ يعيش مناجاة الشاعر لنفسه."},{"type":"essay","q":"اشرح البيت الأول بأسلوبك الأدبي: «ألم تغتمض عيناك ليلة أرمدا / وبتَّ كما بات السليم مسهدا».","model":"يخاطب الشاعر نفسه متسائلًا بألم: ألم تنم عيناك هذه الليلة كما يسهر المصاب بالرمد، وقضيتَ ليلك مؤرّقًا كاللديغ الذي لا يذوق طعم النوم؟"},{"type":"tfr","q":"تُعدّ الألف «أرمدا» و«مسهدا» في نهاية الشطرين ألف الإطلاق الشعرية لإشباع الفتحة.","answer":true,"reasons":["لأنها تمنح البيت امتدادًا موسيقيًا عذبًا يتناسب مع جو الحزن والأرق","لأنها ألف المثنى","لأنها خطأ إملائي"],"reason":0},{"type":"mcq","q":"أيُّ وصفٍ مما يأتي ينطبق على لغة الأعشى في هذا النص؟","options":["سلسة موسيقية قريبة من النفس","غامضة متكلّفة","عامية","علمية جافة"],"answer":0,"why":"امتاز الأعشى بعذوبة اللفظ والموسيقى."},{"type":"essay","q":"قارن بين أثر «مرض الجسد» وأثر «همّ النفس» في حرمان الإنسان من النوم كما فهمت من النص.","model":"مرض الجسد يزول بالدواء، أما همّ النفس والذكريات فيُطيل السهر ويُتعب القلب والعين معًا."},{"type":"tfr","q":"العاطفة السائدة في مطلع قصيدة «ألم تغتمض عيناك» هي الفرح والمرح.","answer":false,"reasons":["لأن العاطفة هي القلق والأرق والشكوى من الهمّ وطول الليل","لأنها قصيدة فخر حربي","لأنها قصيدة هجاء"],"reason":0},{"type":"essay","q":"اذكر مثالًا آخر من لغتنا اليومية نستخدم فيه ألفاظًا متفائلةً على طريقة العرب في «السليم».","model":"مثل تسمية الأعمى «بصيرًا» أو «كريم العين»، أو تسمية الصحراء المهلكة «مفازة» تفاؤلًا بالفوز والنجاة."}]}},
  {"id":"g9-arabic-1-u7-1","grade":"g9","subject":"arabic","term":1,"unit":7,"no":1,"title":"القراءة: كتاب تحفة الأعيان بسيرة أهل عُمان","summary":"شرح متحرك لكتاب «تحفة الأعيان بسيرة أهل عُمان» ومؤلفه ومنهجه التاريخي وأهميته، ثم أنشطة بثلاثة مستويات.","page":"lesson-tuhfat-alayan.html","video":"","pdf":"","notes":["مؤلف كتاب «تحفة الأعيان بسيرة أهل عُمان» هو الإمام العالِم عبد الله بن حميد السالمي (نور الدين السالمي).","يُعدّ الكتاب من أهم وأشمل المصادر الموثوقة في تاريخ عُمان منذ دخول الإسلام حتى عصر المؤلف.","اعتمد الإمام السالمي في تأليفه على التحقيق والتثبّت والرجوع إلى المصادر والوثائق والروايات الموثوقة.","لم يكتفِ بسرد الأحداث السياسية، بل تناول سيرة العلماء والأئمة والحياة الاجتماعية والعلمية في عُمان.","تميّز أسلوبه بالوضوح والرصانة والموضوعية والإنصاف في الحكم على الأحداث والشخصيات.","لا يزال الكتاب مرجعًا أساسيًا لكل باحث ومؤرخ في تاريخ سلطنة عُمان والخليج العربي."],"exercises":["من مؤلف كتاب «تحفة الأعيان بسيرة أهل عُمان»؟","اذكر اثنتين من خصائص منهج الإمام السالمي في كتابة التاريخ.","لماذا يُعدّ الكتاب مرجعًا مهمًا للباحثين حتى اليوم؟"],"levels":{"easy":[{"type":"mcq","q":"من مؤلف كتاب «تحفة الأعيان بسيرة أهل عُمان»؟","options":["الإمام نور الدين السالمي","الجاحظ","الخليل بن أحمد","البوصيري"],"answer":0,"why":"ألّفه الإمام عبد الله بن حميد السالمي."},{"type":"mcq","q":"ما الموضوع الرئيس لكتاب «تحفة الأعيان»؟","options":["تاريخ عُمان وسير أئمتها وعلمائها","علم النحو","علم الطب","الخيال العلمي"],"answer":0,"why":"يُعدّ من أشمل المصادر في التاريخ العُماني."},{"type":"mcq","q":"علامَ اعتمد الإمام السالمي في توثيق الأحداث التاريخية؟","options":["التحرّي والوثائق والروايات الموثوقة","القصص الخيالية","التخمين","الترجمة الحرفية فقط"],"answer":0,"why":"التزم بالمنهج العلمي التحقيقي الدقيق."},{"type":"mcq","q":"ما السمة الأسلوبية البارزة في «تحفة الأعيان»؟","options":["الفصاحة والوضوح والموضوعية","الغموض والتعقيد","العامية","التكلّف"],"answer":0,"why":"جاءت عباراته فصيحة رصينة واضحة."}],"medium":[{"type":"mcq","q":"ما دافع الإمام السالمي من تأليف «تحفة الأعيان»؟","options":["حفظ تاريخ عُمان واستخلاص العبر للأجيال","التسلية فقط","وصف الرحلات الأجنبية","جمع الأمثال فقط"],"answer":0,"why":"أراد توثيق تاريخ وطنه وإفادة الأجيال بعبره."},{"type":"tfr","q":"اقتصر كتاب «تحفة الأعيان» على سرد المعارك السياسية دون ذكر العلماء والأدب.","answer":false,"reasons":["لأنه أورد سير العلماء والأدباء والقصائد والرسائل إلى جانب التاريخ السياسي","لأنه كتاب شعر فقط","لأنه لم يذكر عُمان"],"reason":0},{"type":"essay","q":"اذكر ثلاث سمات لمنهج الإمام السالمي في كتاب «تحفة الأعيان».","model":"التحقيق والتثبّت من الروايات، والإنصاف والموضوعية، والترتيب الزمني، والجمع بين التاريخ وسير العلماء والأدب."},{"type":"tfr","q":"لم يمنع فقدان البصر الإمامَ السالميَّ من التأليف العلمي الغزير وخدمة وطنه.","answer":true,"reasons":["لأنه امتلك همّة عالية وذاكرة قوية فألّف كتبًا خالدة في التاريخ والفقه والأدب","لأنه لم يؤلّف سوى صفحة واحدة","لأنه اعتزل العلم"],"reason":0},{"type":"mcq","q":"كيف رتّب الإمام السالمي أحداث التاريخ العُماني في كتابه؟","options":["ترتيبًا زمنيًا متسلسلًا","ترتيبًا عشوائيًا","حسب طول الأسماء","بلا ترتيب"],"answer":0,"why":"الترتيب الزمني يوضح تسلسل العصور والدول العُمانية."},{"type":"essay","q":"لماذا لا يستغني الباحث في تاريخ عُمان اليوم عن كتاب «تحفة الأعيان»؟","model":"لأنه مصدر أصيل شامل موثوق يغطي قرونًا طويلة من التاريخ العُماني بمنهج علمي منصف."},{"type":"tfr","q":"يرى الإمام السالمي أن التاريخ مدرسةٌ يتعلّم منها الناس أسباب الوحدة والقوة.","answer":true,"reasons":["لأن دراسة التاريخ تكشف سنن النجاح وأسباب الضعف فتُفيد الحاضر والمستقبل","لأن التاريخ للتسلية فقط","لأن التاريخ لا يفيد الحاضر"],"reason":0}],"hard":[{"type":"mcq","q":"ما القيمة المزدوجة التي يقدّمها كتاب «تحفة الأعيان» للقارئ؟","options":["القيمة التاريخية الموثّقة والقيمة الأدبية والتراثية","القيمة الرياضية فقط","القيمة الخيالية","لا قيمة له"],"answer":0,"why":"يجمع بين دقة التأريخ وجمال النصوص والقصائد والرسائل."},{"type":"essay","q":"استخلص درسين من سيرة الإمام نور الدين السالمي يقتدي بهما طالب اليوم.","model":"١) التغلب على الصعاب بالإرادة والهمّة العالية. ٢) الأمانة العلمية والتحرّي قبل نقل أي معلومة."},{"type":"tfr","q":"مقابلة الروايات التاريخية والتحقّق منها قبل إثباتها من أهم أسس المنهج العلمي في التأريخ.","answer":true,"reasons":["لأنها تمنع تسلّل الأخبار غير الصحيحة وتضمن موثوقية الكتاب","لأنها تضيّع الوقت","لأن المؤرخ يكتب كل ما يسمع بلا تدقيق"],"reason":0},{"type":"mcq","q":"أيُّ عبارةٍ تصف علاقة الكتاب بالهوية العُمانية؟","options":["يحفظ ذاكرة الوطن ويُبرز إسهامات أهل عُمان الحضارية والعلمية","يتحدث عن دول أخرى فقط","يهمل التراث العُماني","كتاب قصص خيالية"],"answer":0,"why":"يعرّف الأجيال بتاريخ أجدادهم وإنجازاتهم."},{"type":"essay","q":"قارن بين كتابة التاريخ بمنهج «التحقيق والإنصاف» وبين كتابته بالعاطفة والتعصّب.","model":"المنهج التحقيقي المنصف ينتج مرجعًا علميًا موثوقًا يحترمه الباحثون عبر العصور كـ «تحفة الأعيان»، أما التعصّب فيشوّه الحقائق ويفقد المصداقية."},{"type":"tfr","q":"تضمّن «تحفة الأعيان» ذكر دولة اليعاربة وإنجازاتها في تاريخ عُمان.","answer":true,"reasons":["لأنه يؤرخ للدول والأئمة المتعاقبين في عُمان عبر العصور","لأنه توقف قبل عصر اليعاربة","لأنه كتاب جغرافيا"],"reason":0},{"type":"mcq","q":"ماذا يعني وصف أسلوب الإمام السالمي بـ «الرصين»؟","options":["القويّ المتماسك البعيد عن الابتذال والتعقيد","الغامض الذي لا يُفهم","العامي","المليء بالأخطاء"],"answer":0,"why":"الرصانة تعني قوة الأسلوب ووضوحه وفصاحته."},{"type":"essay","q":"كيف يسهم الاطّلاع على كتب التاريخ الوطني في تعزيز انتماء الشباب؟","model":"عندما يعرف الشباب تضحيات أجدادهم ومنجزاتهم العلمية والحضارية، يزداد اعتزازهم بوطنهم ورغبتهم في مواصلة البناء."},{"type":"tfr","q":"يمكن للباحث المعاصر الاستفادة من «تحفة الأعيان» في دراسة الحياة الاجتماعية والعلمية في عُمان قديمًا.","answer":true,"reasons":["لأنه وثّق أحوال المجتمع وحلقات العلم وسير العلماء إلى جانب السياسة","لأنه لم يذكر المجتمع أبدًا","لأنه مفقود اليوم"],"reason":0},{"type":"essay","q":"اكتب بطاقة تعريف موجزة من ثلاثة أسطر لكتاب «تحفة الأعيان بسيرة أهل عُمان».","model":"الكتاب: تحفة الأعيان بسيرة أهل عُمان. المؤلف: الإمام نور الدين السالمي. الموضوع: موسوعة تاريخية موثوقة تؤرخ لعُمان وأئمتها وعلمائها بأسلوب فصيح ومنهج تحقيقي منصف."}]}},
  {"id":"g9-arabic-1-u7-2","grade":"g9","subject":"arabic","term":1,"unit":7,"no":2,"title":"الأنشطة النحوية والصرفية: المفعول فيه","summary":"شرح متحرك للمفعول فيه (ظرفَي الزمان والمكان) وشروط نصبه والمعرب والمبني وإعرابه، ثم أنشطة بثلاثة مستويات.","page":"lesson-mafool-fih.html","video":"","pdf":"","notes":["المفعول فيه (الظرف): اسم منصوب يُذكر لبيان زمان وقوع الفعل أو مكانه بتقدير معنى «في».","ظرف الزمان يجيب عن «متى؟»، مثل: صباحًا، مساءً، ليلًا، يومًا، ساعةً، شتاءً، قبل، بعد.","ظرف المكان يجيب عن «أين؟»، مثل: أمام، خلف، فوق، تحت، يمين، شمال، بين، عند.","شرط نصبه مفعولًا فيه: أن يتضمّن معنى «في» (سافرتُ يومَ الجمعة = في يوم الجمعة). فإن لم يتضمّن معنى «في» أُعرب حسب موقعه (يومُ الجمعةِ مباركٌ ← مبتدأ).","الظرف المتصرّف يقع ظرفًا وغير ظرف (يوم، ساعة)، وغير المتصرّف لا يُستعمل إلا ظرفًا أو مجرورًا بـ «مِن» (قبل، بعد، عند، فوق).","من الظروف المبنية في محل نصب: أمسِ، الآنَ، حيثُ، إذْ، إذا، هنا، ثَمَّ."],"exercises":["استخرج المفعول فيه وبيّن نوعه في: «أستيقظُ فجرًا وأجلسُ أمامَ مكتبي».","فرّق إعرابيًا بين «يوم» في: (١) سافرتُ يومَ الخميس. (٢) يومُ الخميس جميلٌ.","أعرب: «وقفَ العصفورُ فوقَ الغصنِ»."],"levels":{"easy":[{"type":"mcq","q":"ما الاسم الآخر للمفعول فيه؟","options":["الحال","الظرف (زمان أو مكان)","المفعول المطلق","التمييز"],"answer":1,"why":"المفعول فيه هو ظرف الزمان أو ظرف المكان."},{"type":"mcq","q":"أين ظرف الزمان في جملة: «استيقظَ الفلاحُ فجرًا»؟","options":["استيقظَ","الفلاحُ","فجرًا","لا يوجد"],"answer":2,"why":"«فجرًا» تبيّن زمان الاستيقاظ وتجيب عن متى."},{"type":"mcq","q":"أين ظرف المكان في جملة: «وقفَ الطائرُ فوقَ الغصنِ»؟","options":["وقفَ","الطائرُ","فوقَ","الغصنِ"],"answer":2,"why":"«فوقَ» ظرف مكان منصوب بالفتحة وهو مضاف."},{"type":"mcq","q":"ما الحرف الذي يتضمّن المفعول فيه معناه دائمًا؟","options":["على","في","إلى","عَن"],"answer":1,"why":"المفعول فيه يكون بتقدير «في» (سافرتُ صباحًا = في الصباح)."}],"medium":[{"type":"mcq","q":"ما إعراب «يومُ» في: «يومُ العيدِ سعيدٌ»؟","options":["ظرف زمان منصوب","مبتدأ مرفوع بالضمة","مفعول به","خبر"],"answer":1,"why":"لا تتضمن معنى «في» فتُعرب حسب موقعها مبتدأ."},{"type":"tfr","q":"الظرف «قَبْلَ» يُستعمل للزمان فقط ولا يأتي للمكان أبدًا.","answer":false,"reasons":["لأنه ظرف مشترك يحدّد معناه ما بعده: قبل الفجر (زمان)، قبل المسجد (مكان)","لأنه للمكان فقط","لأنه ليس ظرفًا"],"reason":0},{"type":"essay","q":"أعرب «ليلًا» في: «أضاءَ القمرُ السماءَ ليلًا».","model":"ليلًا: مفعول فيه (ظرف زمان) منصوب وعلامة نصبه الفتحة الظاهرة على آخره."},{"type":"tfr","q":"الظرف «أمسِ» مبني على الكسر في محل نصب مفعول فيه.","answer":true,"reasons":["لأنه من الظروف المبنية مثل: أمسِ، الآنَ، حيثُ، هنا","لأنه معرب بالفتحة","لأنه مرفوع"],"reason":0},{"type":"mcq","q":"أيُّ الكلمات الآتية ظرفٌ متصرّفٌ (يقع ظرفًا وغير ظرف)؟","options":["ساعة","عند","حيث","الآن"],"answer":0,"why":"«ساعة» تقع ظرفًا (قرأتُ ساعةً) ومبتدأ (الساعةُ ثمينةٌ)."},{"type":"essay","q":"وظّف كلمة «عندَ» مرةً ظرف زمان ومرةً ظرف مكان في جملتين.","model":"ظرف زمان: سألتقيك عندَ الفجرِ. ظرف مكان: انتظرتك عندَ بابِ المدرسة."},{"type":"tfr","q":"الاسم الذي يأتي بعد الظروف المضافة مثل «أمامَ البيتِ» يُعرب مضافًا إليه مجرورًا.","answer":true,"reasons":["لأن «أمامَ» مضاف و«البيتِ» مضاف إليه مجرور بالكسرة","لأنه مفعول به","لأنه فاعل"],"reason":0}],"hard":[{"type":"mcq","q":"في أيّ جملة مما يأتي وقعت كلمة «ساعة» مفعولًا فيه؟","options":["الساعةُ دقيقةٌ","اشتريتُ ساعةً جديدةً","ذاكرتُ دروسي ساعةً","نظرتُ إلى الساعةِ"],"answer":2,"why":"«ذاكرتُ دروسي ساعةً» بتقدير «في ساعة» فتُعرب مفعولًا فيه."},{"type":"essay","q":"فرّق في الإعراب بين «صباح» في: (١) سافرتُ صباحًا. (٢) أشرقَ الصباحُ.","model":"في (١) «صباحًا» مفعول فيه ظرف زمان منصوب بالفتحة. وفي (٢) «الصباحُ» فاعل مرفوع بالضمة."},{"type":"tfr","q":"الظرف «حيثُ» مبني على الضم في محل نصب مفعول فيه ظرف مكان.","answer":true,"reasons":["لأن «حيثُ» يلازم الضم ويدل على المكان في محل نصب","لأنه ظرف زمان","لأنه معرب"],"reason":0},{"type":"mcq","q":"ما إعراب «بينَ» في: «المسجدُ بينَ البيوتِ»؟","options":["ظرف زمان","مفعول فيه ظرف مكان منصوب وهو مضاف","فاعل","حال"],"answer":1,"why":"تبيّن المكان بتقدير «في» وهي مضافة إلى البيوت."},{"type":"essay","q":"أعرب: «جلستُ حيثُ يجلسُ العلماءُ».","model":"جلستُ: فعل ماضٍ والتاء فاعل. حيثُ: ظرف مكان مبني على الضم في محل نصب مفعول فيه."},{"type":"tfr","q":"الظروف غير المتصرّفة لا تخرج عن الظرفية إلا مجرورةً بحرف الجر مثل «مِن قبلُ».","answer":true,"reasons":["لأنها لا تقع مبتدأ ولا فاعلًا ولا مفعولًا به","لأنها تقع فاعلًا دائمًا","لأنها لا تُجرّ أبدًا"],"reason":0},{"type":"mcq","q":"أيُّ جملةٍ تضمّ ظرف زمان وظرف مكان معًا؟","options":["وقفتُ أمامَ البابِ صباحًا","قرأتُ كتابًا مفيدًا","اجتهدتُ رغبةً في النجاح","فرحتُ فرحًا شديدًا"],"answer":0,"why":"«أمامَ» ظرف مكان و«صباحًا» ظرف زمان."},{"type":"essay","q":"فرّق بين المفعول فيه والمفعول لأجله والمفعول المطلق بمثال لكل واحد.","model":"المفعول فيه (متى/أين): سافرتُ صباحًا. المفعول لأجله (لماذا): سافرتُ طلبًا للعلم. المفعول المطلق (من لفظ الفعل): سافرتُ سفرًا طويلًا."},{"type":"tfr","q":"في جملة «سرتُ ميلًا» تُعرب كلمة «ميلًا» ظرف مكان منصوبًا.","answer":true,"reasons":["لأنها تدلّ على مقدار مكاني وقع فيه السير","لأنها ظرف زمان","لأنها حال"],"reason":0},{"type":"essay","q":"كوّن جملة تشتمل على ظرف مكان مضاف، وأخرى تشتمل على ظرف زمان مبني.","model":"ظرف مكان مضاف: وضعتُ الكتابَ فوقَ الطاولةِ. ظرف زمان مبني: وصلَ صديقي أمسِ (أو الآنَ)."}]}},
  {"id":"g9-arabic-1-u7-3","grade":"g9","subject":"arabic","term":1,"unit":7,"no":3,"title":"الأنشطة الإملائية: تطبيقات على رسم الهمزة المتطرفة وكتابة الألف في أواخر الأسماء والأفعال","summary":"تطبيقات متحركة جامعة لقواعد الهمزة المتطرفة والألف في أواخر الأسماء والأفعال، ثم أنشطة بثلاثة مستويات.","page":"lesson-u7-spelling-apps.html","video":"","pdf":"","notes":["الهمزة المتطرفة تُكتب حسب حركة الحرف السابق فقط: فتح (أ)، ضم (ؤ)، كسر (ئ)، سكون أو مد (ء).","تنوين الفتح في الهمزة المتطرفة: بلا ألف بعد ألف أو فوق ألف (سماءً، خطأً)، سطر+ألف بعد حرف لا يتصل (جزءًا)، نبرة+ألف بعد حرف يتصل (شيئًا).","الألف في الثلاثي (أسماء وأفعال): أصلها واو ← (ا) مثل عصا ودعا، أصلها ياء ← (ى) مثل فتى ومشى.","الألف في فوق الثلاثي (أسماء وأفعال): مقصورة (ى) مثل مستشفى واشترى، إلا إذا سبقتها ياء فتُكتب قائمة (ا) مثل هدايا وأحيا (ما عدا العلم يحيى).","عند اتصال ضمير بالفعل المنتهي بألف مقصورة تُرسم قائمة (اشترى ← اشتراه).","المقارنة بين المتشابهات مثل (عَصَا الاسم / عَصَى الفعل، ويَحْيَى العلم / يَحْيَا الفعل) تحمي من الأخطاء الشائعة."],"exercises":["صوّب الأخطاء في الفقرة: «دعى يحيى ربّه مساءًا ثم مشا إلى المستشفا واشترى شيئًا نافعًا».","علّل رسم آخر الكلمات: نَجَا، رَمَاهُ، هَادِئ، قَضَايَا.","صنّف الكلمات حسب سبب رسم ألفها: سَمَا، سَعَى، اسْتَحْيَا، مُنْتَدَى."],"levels":{"easy":[{"type":"mcq","q":"أيُّ الكلمات الآتية كُتبت خطأً؟","options":["دعا","اهتدى","اشترىه","شيئًا"],"answer":2,"why":"الصواب «اشتراه» بألف قائمة لاتصال الضمير بها."},{"type":"mcq","q":"ما الصواب في: «........ اللهُ الأرضَ بالمطرِ»؟","options":["أحيا","أحيى","أحيأ","أحيء"],"answer":0,"why":"فعل فوق ثلاثي سبقت ألفه ياء فتُكتب قائمة."},{"type":"mcq","q":"ما الصواب في: «قرأتُ ........ من الكتابِ»؟","options":["جزئًا","جزءًا","جزءً","جزأً"],"answer":1,"why":"الزاي لا تتصل فتبقى الهمزة على السطر مع ألف التنوين."},{"type":"mcq","q":"لماذا كُتبت «قَضَى» مقصورة؟","options":["فعل ثلاثي أصل ألفه ياء (يقضي)","فعل رباعي","أصلها واو","اسم أعجمي"],"answer":0,"why":"قضى ← يقضي / قضيتُ فأصلها ياء."}],"medium":[{"type":"mcq","q":"أيُّ جملةٍ مما يأتي خالية تمامًا من الأخطاء الإملائية؟","options":["سعى مصطفى بهدوءٍ حتى نال شيئًا عظيمًا.","سعا مصطفا بهدوئٍ حتى نال شيءًا عظيمًا.","سعى مصطفا بهدوءٍ حتى نال شيئًا عظيمًا.","سعا مصطفى بهدوءٍ حتى نال شيءًا عظيمًا."],"answer":0,"why":"سعى (سعيتُ)، مصطفى (فوق ثلاثي)، بهدوءٍ (مد ساكن)، شيئًا (نبرة)."},{"type":"tfr","q":"يتشابه الاسم غير الثلاثي والفعل غير الثلاثي في قاعدة رسم الألف اللينة في آخرهما.","answer":true,"reasons":["لأن كليهما تُكتب ألفه مقصورة إلا إذا سبقتها ياء فتُكتب قائمة (باستثناء العلم يحيى)","لأنهما يختلفان تمامًا","لأن الفعل فوق الثلاثي كله قائمة"],"reason":0},{"type":"essay","q":"صوّب الأخطاء في الجملة: «استحى الفتا من خطأًا وقع فيه فدعى ربّه واستغفره».","model":"استحيا الفتى من خطأٍ وقع فيه فدعا ربّه واستغفره."},{"type":"tfr","q":"عندما نقول «رَمَاهُ» كُتبت الألف قائمة لأن أصل ألف «رمى» واو.","answer":false,"reasons":["لأن أصلها ياء، وإنما كُتبت قائمة لأنها صارت متوسطة لاتصالها بضمير الغائب","لأنها اسم أعجمي","لأنها فوق ثلاثي"],"reason":0},{"type":"mcq","q":"ما الفرق الإملائي الصحيح بين «يحيى» و«يحيا»؟","options":["يحيى اسم علم، ويحيا فعل مضارع","كلاهما فعل","كلاهما اسم علم","لا فرق"],"answer":0,"why":"كُتب الاسم مقصورًا للتمييز بينه وبين الفعل."},{"type":"essay","q":"علّل رسم آخر كل كلمة: «سَمَا»، «مُنْتَدَى»، «مَرَايَا»، «بُطْئًا».","model":"سما: فعل ثلاثي واوي (يسمو). منتدى: اسم فوق ثلاثي بلا ياء. مرايا: اسم فوق ثلاثي قبله ياء. بطئًا: همزة متطرفة منوّنة بالفتح قبلها طاء تتصل."},{"type":"tfr","q":"كلمة «مَلِيء» تُكتب همزتها على السطر لأن قبلها ياء مدّ ساكنة.","answer":true,"reasons":["لأن ياء المد الساكنة تقتضي كتابة الهمزة المتطرفة على السطر","لأن قبلها كسرة","لأنها همزة متوسطة"],"reason":0}],"hard":[{"type":"mcq","q":"أيُّ مجموعة كلمات كلها صحيحة إملائيًا؟","options":["نَمَا، قَضَى، اسْتَدْعَى، اسْتَحْيَا","نَمَى، قَضَا، اسْتَدْعَا، اسْتَحْيَى","عَفَى، بَنَا، أَعْطَى، أَحْيَا","دَعَا، مَشَا، اهْتَدَى، أَحْيَا"],"answer":0,"why":"كل الأفعال الأربعة مطابقة تمامًا للقاعدة."},{"type":"essay","q":"صوّب جميع الأخطاء الإملائية في الفقرة: «مشا يحيى على الشاطء مساءًا، ورأى شيئًا يلمع كاللؤلؤ، فأعطىه لأخيه عيسا».","model":"مشى يحيى على الشاطئ مساءً، ورأى شيئًا يلمع كاللؤلؤ، فأعطاه لأخيه عيسى."},{"type":"tfr","q":"الجمع بين «عَصَا» (اسم) و«عَصَى» (فعل) يوضّح أهمية فهم معنى الكلمة قبل رسم ألفها.","answer":true,"reasons":["لأن المعنى يحدّد نوع الكلمة وأصل ألفها (عصوان مقابل يعصي)","لأنهما بنفس المعنى","لأن كلاهما فعل"],"reason":0},{"type":"mcq","q":"ما الصواب عند تنوين «شَاطِئ» و«سَمَاء» بالفتح على الترتيب؟","options":["شاطئًا، سماءً","شاطءًا، سماءًا","شاطئًا، سماءًا","شاطئً، سماءً"],"answer":0,"why":"شاطئ على ياء فتُزاد ألف، وسماء قبلها ألف فلا تُزاد ألف."},{"type":"essay","q":"اكتب قاعدة جامعة في سطرين تشرح رسم الألف في أواخر الأسماء والأفعال معًا.","model":"في الثلاثي (اسمًا وفعلًا) تُكتب الألف قائمة إذا كان أصلها واوًا ومقصورة إذا كان أصلها ياءً. وفي فوق الثلاثي تُكتب مقصورة دائمًا إلا إذا سبقتها ياء فتُكتب قائمة (باستثناء العلم يحيى)."},{"type":"tfr","q":"في جملة «بنى المهندسُ بناءً شامخًا» كُتبت «بنى» مقصورة و«بناءً» بلا ألف بعد الهمزة.","answer":true,"reasons":["لأن «بنى» فعل ثلاثي يائي (يبني)، و«بناءً» همزة متطرفة مسبوقة بألف مدّ","لأن «بنى» رباعي","لأن «بناءً» تحتاج ألفًا ثانية"],"reason":0},{"type":"mcq","q":"أيُّ فعلٍ مما يأتي أصل ألفه ياء؟","options":["سَعَى","نَجَا","عَلَا","سَمَا"],"answer":0,"why":"سعى ← سعيتُ (ياء)، أما البقية فواوية (نجوتُ، علوتُ، سموتُ)."},{"type":"essay","q":"فسّر لماذا تختلف كتابة الهمزة في «دِفْئًا» عن «بَدْءًا».","model":"لأن الفاء في «دفء» تتصل بألف التنوين فتُكتب الهمزة على نبرة، أما الدال في «بدء» فلا تتصل بما بعدها فتبقى الهمزة على السطر."},{"type":"tfr","q":"الفعل «يَبْدَأُ» تُكتب همزته على ألف لأن الدال قبلها مفتوحة.","answer":true,"reasons":["لأن الهمزة المتطرفة تتبع حركة الحرف السابق لها فقط","لأن الهمزة مفتوحة","لأن الدال مضمومة"],"reason":0},{"type":"essay","q":"ألفْ فقرة قصيرة من جملتين تضمّ فعلًا ثلاثيًا واويًا، وفعلًا فوق ثلاثي مقصورًا، واسمًا منتهيًا بهمزة متطرفة منوّنة بالفتح.","model":"مثال: نجا المسافرُ من العاصفة، واشترى طعامًا وشيئًا من الماء ثم استراح مساءً."}]}},
  {"id":"g9-arabic-1-u7-4","grade":"g9","subject":"arabic","term":1,"unit":7,"no":4,"title":"التعبير: كيفية عرض كتاب","summary":"شرح متحرك لمهارة عرض كتاب وعناصرها الأساسية وخطواتها بمثال تطبيقي، ثم أنشطة بثلاثة مستويات.","page":"lesson-book-review.html","video":"","pdf":"","notes":["عرض الكتاب: نص منظّم يعرّف القارئ بكتابٍ معيّنٍ ومؤلفه وموضوعه وأهم أفكاره وتقييمه.","العنصر الأول (البيانات التعريفية): عنوان الكتاب، اسم المؤلف، دار النشر، سنة الطبع، وعدد الصفحات.","العنصر الثاني (المضمون): الفكرة العامة للكتاب، وأبرز فصوله أو أبوابه بإيجاز، والجمهور المستهدف.","العنصر الثالث (الأسلوب والمنهج): كيف عرض المؤلف أفكاره؟ هل أسلوبه سهل ومشوّق وموثّق؟","العنصر الرابع (التقييم والرأي الشخصي): بيان جوانب القوة والفائدة، وملاحظات موضوعية إن وُجدت، وتوصية بالقراءة.","نراعي عند العرض الأمانة والموضوعية وعدم حرق نهاية القصة أو الرواية إذا كان الكتاب قصصيًا."],"exercises":["اذكر البيانات التعريفية الأساسية التي نبدأ بها عرض أي كتاب.","ما الفرق بين «تلخيص كتاب» و«عرض كتاب»؟","اكتب عرضًا موجزًا من ستة أسطر لكتابٍ قرأته وأعجبك."],"levels":{"easy":[{"type":"mcq","q":"أيٌّ مما يأتي يدخل ضمن «البيانات التعريفية» في عرض الكتاب؟","options":["عنوان الكتاب والمؤلف ودار النشر وسنة الطبع","رأي القارئ فقط","ملخص الفصل الأخير","أسماء أصدقائك"],"answer":0,"why":"البيانات التعريفية تتيح للقارئ التعرّف على الكتاب والوصول إليه."},{"type":"mcq","q":"بماذا يختلف «عرض الكتاب» عن «التلخيص»؟","options":["عرض الكتاب يشتمل على التقييم والرأي الموضوعي","التلخيص أطول من الكتاب","عرض الكتاب لا يذكر المؤلف","لا يوجد فرق"],"answer":0,"why":"التلخيص محايد بلا رأي، أما عرض الكتاب فيضم تقييمًا وتوصية."},{"type":"mcq","q":"ما الذي يجب تجنّبه عند عرض قصة أو رواية؟","options":["ذكر اسم المؤلف","كشف نهاية القصة وحرق التشويق","ذكر الموضوع العام","تقييم الأسلوب"],"answer":1,"why":"إخفاء النهاية يحافظ على متعة القارئ وتشويقه."},{"type":"mcq","q":"ما الشرط الأخلاقي الأساسي قبل كتابة عرض لكتاب ما؟","options":["أن تكون قد قرأت الكتاب بنفسك","أن تقرأ الغلاف فقط","أن تنسخ عرضًا من غيرك","أن تنتقده بقسوة"],"answer":0,"why":"الأمانة العلمية تقتضي قراءة الكتاب وفهمه قبل عرضه."}],"medium":[{"type":"mcq","q":"ماذا نذكر في قسم «الأسلوب والمنهج» عند عرض كتاب؟","options":["وضوح اللغة وتنظيم الفصول وتوظيف الشواهد والصور","سعر الكتاب فقط","لون الغلاف فقط","وزن الكتاب"],"answer":0,"why":"وصف المنهج والأسلوب يبيّن للقارئ طبيعة الكتاب وسهولته."},{"type":"tfr","q":"تحديد الجمهور المستهدف من الكتاب (طلاب، باحثون، عموم القراء) جزء مفيد في عرض الكتاب.","answer":true,"reasons":["لأنه يساعد القارئ على معرفة هل الكتاب مناسب لمستواه واهتماماته","لأن كل الكتب تناسب الأطفال فقط","لأنه لا فائدة منه"],"reason":0},{"type":"essay","q":"اذكر العناصر الأربعة الرئيسة لعرض أي كتاب بالترتيب.","model":"١) البيانات التعريفية. ٢) الفكرة العامة وأبرز الأبواب. ٣) وصف الأسلوب والمنهج. ٤) التقييم الموضوعي والتوصية."},{"type":"tfr","q":"ينبغي أن يكون النقد والتقييم في عرض الكتاب موضوعيًا ومؤدّبًا يبرز جوانب القوة والملاحظات بإنصاف.","answer":true,"reasons":["لأن الموضوعية والإنصاف تكسبان العرض مصداقية لدى القارئ","لأن العرض للمدح المبالغ فيه فقط","لأن النقد يجب أن يكون قاسيًا"],"reason":0},{"type":"mcq","q":"أين نضع التوصية بقراءة الكتاب في عرض الكتاب؟","options":["في الخاتمة","قبل العنوان","لا تُذكر التوصية","في منتصف البيانات"],"answer":0,"why":"التوصية خلاصة طبيعية بعد استعراض المضمون والتقييم."},{"type":"essay","q":"لماذا نذكر «دار النشر وسنة الطبع» في البيانات التعريفية للكتاب؟","model":"لمساعدة القارئ على اقتناء الطبعة الصحيحة من المكتبة، ومعرفة حداثة المعلومات في الكتاب."},{"type":"tfr","q":"عرض الكتاب يعني نسخ فهرس الكتاب كاملًا دون شرح أو تقييم.","answer":false,"reasons":["لأنه نص منظّم يقدّم تعريفًا وخلاصة مركّزة وتقييمًا موضوعيًا بأسلوب الكاتب","لأن الفهرس يكفي وحده","لأن الشرح ممنوع"],"reason":0}],"hard":[{"type":"mcq","q":"إذا كان الكتاب علميًا، ما أبرز جانبٍ تركّز عليه عند تقييم منهجه؟","options":["دقة المعلومات وتوثيق المصادر ووضوح الأمثلة","جمال القوافي","حرق نهاية القصة","طول العنوان"],"answer":0,"why":"الكتاب العلمي يُقيّم بدقته وتوثيقه ووضوح عرضه."},{"type":"essay","q":"اكتب عرضًا موجزًا من أربعة أسطر لكتابٍ دراسيٍّ أو ثقافيٍّ قرأته.","model":"مثال: كتاب «الأيام» للأديب طه حسين (دار المعارف). يروي فيه الكاتب سيرته الذاتية منذ طفولته في القرية حتى دراسته بالأزهر بأسلوب أدبي عذب ومؤثّر. وهو كتاب ملهم في الإرادة أنصح كل طالب بقراءته."},{"type":"tfr","q":"الاقتباس الموجز لجملةٍ جميلةٍ من الكتاب أثناء عرضه يزيد القارئ تشوّقًا لاقتنائه.","answer":true,"reasons":["لأنه يعطي القارئ نموذجًا حيًا لأسلوب المؤلف وعمق أفكاره","لأن الاقتباس ممنوع في عرض الكتب","لأنه يفسد العرض"],"reason":0},{"type":"mcq","q":"ما الغاية الثقافية من نشر عروض الكتب في المكتبة المدرسية أو الإذاعة؟","options":["نشر ثقافة القراءة ومساعدة الطلاب على اختيار كتب نافعة","إضاعة وقت الحصة","الاستغناء عن قراءة الكتب","إخفاء الكتب"],"answer":0,"why":"عروض الكتب تفتح شهية الطلاب للقراءة وتوجّههم لأفضل الكتب."},{"type":"essay","q":"قارن بين «عرض كتاب» و«ملخّص درس» من حيث الغرض والبناء.","model":"ملخّص الدرس يهدف لتثبيت المعلومات للمذاكرة ولا يضم رأيًا شخصيًا، أما عرض الكتاب فيهدف للتعريف بالكتاب وتشجيع القراء عليه ويضم بيانات ببليوغرافية وتقييمًا وتوصية."},{"type":"tfr","q":"قراءة مقدمة الكتاب وفهرسه مع تصفّح فصوله تساعد العارض على فهم خطة المؤلف.","answer":true,"reasons":["لأن المقدمة تكشف هدف المؤلف والفهرس يوضّح بناء الكتاب وأبوابه","لأن المقدمة غير مهمة","لأن الفهرس لا علاقة له بالموضوع"],"reason":0},{"type":"mcq","q":"أيُّ عبارةٍ تصلح خاتمةً لعرض كتابٍ تاريخي؟","options":["كتاب موثّق بأسلوب سلس، أنصح به كل مهتم بتاريخ وطنه.","الكتاب يحتوي على أوراق بيضاء.","لا أعرف عن ماذا يتحدث الكتاب.","انتهى العرض."],"answer":0,"why":"تجمع بين التقييم الموضوعي والتوصية المحدّدة."},{"type":"essay","q":"كيف تبدي ملاحظةً نقديةً على كتابٍ بأسلوب موضوعي ومؤدّب؟","model":"أذكر جوانب التميّز أولًا، ثم أطرح الملاحظة بلطف وموضوعية، مثل: «ورغم ثراء الكتاب بالمعلومات، تمنّيتُ لو أضاف المؤلف خرائط توضيحية أكثر لتسهيل الفهم على الناشئة»."},{"type":"tfr","q":"عرض الكتاب فنٌّ حديثٌ لا يفيد إلا الصحفيين فقط.","answer":false,"reasons":["لأنه مهارة مفيدة لكل طالب وباحث وقارئ لتنظيم فهمه ومشاركة المعرفة","لأنه خاص بالمكتبات فقط","لأنه لا يُدرّس في المدارس"],"reason":0},{"type":"essay","q":"صمّم بطاقة عرض سريعة من ٤ نقاط لكتاب «البيان والتبيين» للجاحظ.","model":"١) الكتاب: البيان والتبيين. ٢) المؤلف: الجاحظ. ٣) المضمون: موسوعة أدبية في الفصاحة والخطابة والبلاغة العربية مدعّمة بالشواهد. ٤) التقييم: مرجع أساسي قيّم لكل محب للغة العربية والأدب."}]}},
  {"id":"g9-arabic-1-u7-5","grade":"g9","subject":"arabic","term":1,"unit":7,"no":5,"title":"النص الأدبي: أبا تمام – أين تكون؟","summary":"شرح متحرك لقصيدة «أبا تمام – أين تكون؟» ورمزيتها وأساليبها وصورها البلاغية، ثم أنشطة بثلاثة مستويات.","page":"lesson-aba-tammam.html","video":"","pdf":"","notes":["أبو تمام (حبيب بن أوس الطائي) من أعظم شعراء العصر العباسي، واشتهر بقصيدته الخالدة في فتح عمورية: «السيف أصدق أنباءً من الكتب».","في قصيدة «أبا تمام – أين تكون؟» يستدعي الشاعر المعاصر شخصية أبي تمام بوصفها رمزًا للبطولة والشعر الصادق والمجد العربي.","النداء بحذف الأداة «أبا تمام» يوحي بالقرب العاطفي والروحي من الشاعر القديم وتراثه.","الاستفهام «أين تكون؟» غرضه التحسّر والشوق إلى أيام العزّة والقوة والأصالة.","يقارن النص بين ماضٍ مشرقٍ حافلٍ بالبطولات والبيان، وبين واقعٍ يحتاج إلى استنهاض الهمم.","يمتاز الأسلوب بتوظيف الرمز التراثي، والمزج بين الأساليب الإنشائية (النداء والاستفهام)، وصدق العاطفة القومية."],"exercises":["لماذا اختار الشاعر شخصية «أبي تمام» تحديدًا لمخاطبتها في القصيدة؟","ما دلالة حذف أداة النداء في «أبا تمام»؟ وما الغرض من الاستفهام «أين تكون؟»؟","كيف يوظّف الشاعر التراث العربي لخدمة قضايا الحاضر؟"],"levels":{"easy":[{"type":"mcq","q":"من هو أبو تمام الذي يخاطبه الشاعر في القصيدة؟","options":["شاعر عباسي شهير (حبيب بن أوس الطائي)","كاتب قصة قصيرة","عالم رياضيات","مؤرخ عُماني"],"answer":0,"why":"أبو تمام من أعظم شعراء العصر العباسي وصاحب بائية عمورية."},{"type":"mcq","q":"ما دلالة حذف أداة النداء في «أبا تمام»؟","options":["قربه من قلب الشاعر وروحه","بُعده","تجاهله","الغضب منه"],"answer":0,"why":"حذف أداة النداء يُشعر بقرب المنادى وحضوره في الوجدان."},{"type":"mcq","q":"ما الغرض البلاغي من الاستفهام «أين تكون؟»؟","options":["التحسّر والشوق إلى زمن المجد والعزّة","طلب موقع جغرافي","التعجيز","النفي فقط"],"answer":0,"why":"يتحسّر الشاعر ويشتاق إلى روح البطولة التي جسّدها شعر أبي تمام."},{"type":"mcq","q":"ما أشهر قصيدة للشاعر أبي تمام ارتبطت ببطولات العرب؟","options":["قصيدة فتح عمورية","البردة","الهمزية","المعلقات"],"answer":0,"why":"مطلعها الخالد: «السيفُ أصدقُ أنباءً من الكتبِ»."}],"medium":[{"type":"mcq","q":"ماذا يُسمّى استحضار شخصية تاريخية كأبي تمام في قصيدة معاصرة للتعبير عن قيمة نبيلة؟","options":["توظيف الرمز التراثي","التلخيص","السرد العلمي","الترجمة"],"answer":0,"why":"استدعاء الرموز التراثية يُثري القصيدة بعمق تاريخي ودلالي."},{"type":"tfr","q":"يخاطب الشاعر أبا تمام لكي يعرّف القارئ بتاريخ ميلاده ووفاته فقط.","answer":false,"reasons":["لأنه يستدعيه رمزًا للعزّة والبطولة والكلمة الصادقة لاستنهاض همّة الحاضر","لأن القصيدة ترجمة علم","لأن أبا تمام شاعر معاصر"],"reason":0},{"type":"essay","q":"اشرح دلالة عنوان القصيدة «أبا تمام – أين تكون؟».","model":"يجمع العنوان بين نداءٍ محذوف الأداة يدلّ على القرب العاطفي من أبي تمام وتراثه، واستفهامٍ غرضه التحسّر والشوق إلى أمجاد الماضي وروح البطولة."},{"type":"tfr","q":"أكثرت القصيدة من الأساليب الإنشائية (النداء والاستفهام) لإثارة العاطفة وإشراك القارئ.","answer":true,"reasons":["لأن الإنشاء يحرّك المشاعر ويجعل النص حوارًا وجدانيًا حيًّا","لأن الأساليب الإنشائية تضعف الشعر","لأنها نص علمي"],"reason":0},{"type":"mcq","q":"ما المقابلة الأساسية التي بُنيت عليها القصيدة؟","options":["بين مجد الماضي المشرق وواقع الحاضر المتطلّع للنهضة","بين الصيف والشتاء","بين البحر والصحراء","بين العلم والمال"],"answer":0,"why":"استدعاء الماضي المشرق يهدف لتحفيز الحاضر نحو النهضة."},{"type":"essay","q":"ما دور الشعر والكلمة الصادقة في حياة الأمة كما يبرز في النص؟","model":"الشعر الصادق يوثّق البطولات، ويحفظ ذاكرة الأمة وهويتها، ويوقظ الهمم ويبعث الأمل والعزيمة في النفوس."},{"type":"tfr","q":"تجمع عاطفة القصيدة بين الاعتزاز بالتاريخ وبين الشوق والأمل في تجدّد المجد.","answer":true,"reasons":["لأن الشاعر يفخر بتراث أبي تمام ويتطلع لنهضة جديدة لأمته","لأنها عاطفة يأس مطلق","لأنها قصيدة ساخرة"],"reason":0}],"hard":[{"type":"mcq","q":"ما إعراب «أبا» في قوله «أبا تمام»؟","options":["منادى منصوب وعلامة نصبه الألف لأنه من الأسماء الخمسة","فاعل مرفوع","مبتدأ مرفوع","مجرور بالياء"],"answer":0,"why":"منادى مضاف منصوب بالألف لأنه من الأسماء الخمسة."},{"type":"essay","q":"كيف ينجح الشاعر المعاصر في الربط بين التراث العربي القديم وبين قضايا الحاضر؟","model":"باستدعاء شخصيات وأحداث مشرقة من التراث كأبي تمام وفتح عمورية وجعلها رموزًا حيّةً للقيم والهمّة التي يحتاجها الإنسان اليوم."},{"type":"tfr","q":"استحضار التراث في الشعر الحديث يعني الانغلاق على الماضي ونسيان الحاضر.","answer":false,"reasons":["لأنه يهدف لاستلهام القوة والهوية من الماضي لخدمة الحاضر وبناء المستقبل","لأن التراث لا علاقة له بالحاضر","لأن الشعر الحديث يرفض التراث"],"reason":0},{"type":"mcq","q":"ما أثر استحضار مطلع أبي تمام «السيف أصدق أنباء من الكتب» في ذهن القارئ؟","options":["استدعاء معاني الحسم والعزيمة والانتصار","إثارة الضحك","وصف الطبيعة","الحديث عن السفر"],"answer":0,"why":"البيت رمز تاريخي راسخ للعزم والانتصار."},{"type":"essay","q":"قارن بين أسلوب النداء في «يا سماءً» (للبوصيري) وفي «أبا تمام» (في هذه القصيدة).","model":"في «يا سماءً» ذُكرت أداة النداء «يا» للتعظيم والرفعة، أما في «أبا تمام» فحُذفت الأداة للإيحاء بالقرب الوجداني والحوار المباشر."},{"type":"tfr","q":"يُضفي التناص واستدعاء الرموز التراثية عمقًا ثقافيًا وفنيًا على القصيدة.","answer":true,"reasons":["لأنه يشحن الألفاظ بدلالات تاريخية ووجدانية غنية تختصر معاني كثيرة","لأنه يقلل من قيمة القصيدة","لأنه يُصعّب الفهم بلا فائدة"],"reason":0},{"type":"mcq","q":"أيُّ قيمةٍ تربويةٍ نتعلّمها من العلاقة بالتراث في هذا النص؟","options":["الاعتزاز بالهوية واستلهام أمجاد الأجداد للعمل والنهضة","الاكتفاء بالتفاخر بلا عمل","نسيان التاريخ","تقليد الآخرين"],"answer":0,"why":"الفخر الإيجابي بالتراث يدفعنا للبناء والاجتهاد اليوم."},{"type":"essay","q":"تخيّل أنك تخاطب عالِمًا أو شاعرًا عربيًا قديمًا على طريقة هذا النص، فاكتب سطرين تحاوره فيهما.","model":"مثال: «خليلَ العلمِ، أين ترى لغتنا اليوم؟ إنّها ما زالت تنبض بالجمال، ونحن نحمل أمانتها لنرفع شأنها بالعلم والإبداع»."},{"type":"tfr","q":"الاستفهام في الشعر الوجداني قد يخرج عن طلب المعرفة إلى أغراض بلاغية كالشوق والتحسّر.","answer":true,"reasons":["كما في «أين تكون؟» التي تعبّر عن الشوق والحنين لا عن جهل بمكان"],"reason":0},{"type":"essay","q":"لخّص الفكرة العامة لقصيدة «أبا تمام – أين تكون؟» في جملتين.","model":"يستحضر الشاعر شخصية أبي تمام رمزًا للشعر الصادق والمجد العربي، متحسّرًا على غياب روح البطولة، وداعيًا إلى استلهام التراث المشرق لاستنهاض الهمم في الحاضر."}]}},
  {"id":"g9-arabic-1-u8-1","grade":"g9","subject":"arabic","term":1,"unit":8,"no":1,"title":"القراءة: من الخيال العلمي","summary":"شرح متحرك لمفهوم أدب الخيال العلمي وخصائصه ودوره في إلهام المخترعين، ثم أنشطة بثلاثة مستويات.","page":"lesson-sci-fi.html","video":"","pdf":"","notes":["أدب الخيال العلمي: فن أدبي يمزج بين المعرفة العلمية الدقيقة والخيال الإبداعي لتصوير مستقبلٍ محتمل أو اختراعاتٍ متوقّعة.","يختلف عن الخيال الخرافي (الأسطوري) في أنه يستند إلى قوانين العلم ومنطقه لا إلى السحر والمستحيل.","من أبرز موضوعاته: رحلات الفضاء، والروبوتات والذكاء الاصطناعي، والمدن المستقبلية، وعلوم الطب والطاقة.","كثير من الاختراعات الحديثة (كالغواصات والأقمار الصناعية ومكالمات الفيديو) كانت يومًا أفكارًا في قصص الخيال العلمي.","أهميته للطلاب: ينمّي التفكير الإبداعي، ويثير حبّ الاستطلاع العلمي، ويدعو للتفكير في أخلاقيات التقنية.","يمتاز أسلوبه بالتشويق، وتوظيف المصطلحات العلمية بسلاسة، وبناء حبكة مشوّقة."],"exercises":["ما الفرق بين «الخيال العلمي» و«الخيال الخرافي»؟","اذكر اختراعَين حديثَين كانا في البداية فكرةً في أدب الخيال العلمي.","كيف ينمّي أدب الخيال العلمي مهارات التفكير لدى الطالب؟"],"levels":{"easy":[{"type":"mcq","q":"ما الذي يجمع بينه أدب الخيال العلمي؟","options":["المعرفة العلمية والخيال الإبداعي","الخرافة والسحر فقط","الأرقام بلا قصة","التاريخ القديم فقط"],"answer":0,"why":"يمزج الخيال العلمي بين العلم الصحيح والخيال المستقبلي."},{"type":"mcq","q":"بماذا يختلف الخيال العلمي عن الخيال الخرافي؟","options":["يستند إلى قوانين العلم ومنطقه","يعتمد على السحر","لا يحتاج للتفكير","يخلو من الأحداث"],"answer":0,"why":"الخيال العلمي ينطلق من أسس علمية ممكنة."},{"type":"mcq","q":"أيٌّ مما يأتي من موضوعات الخيال العلمي؟","options":["رحلات الفضاء والروبوتات","المديح النبوي","شرح المعاجم","قواعد الإملاء"],"answer":0,"why":"يتناول الفضاء والذكاء الاصطناعي والطب المستقبلي."},{"type":"mcq","q":"ما فائدة قراءة الخيال العلمي للطلاب؟","options":["تنمية الإبداع وحب الاستطلاع العلمي","إضعاف اللغة","الخوف من العلم","نسيان الدروس"],"answer":0,"why":"يحفّز الخيال العلمي على التفكير المبدع وحب العلوم."}],"medium":[{"type":"mcq","q":"كيف أثّر أدب الخيال العلمي في مسيرة المخترعين؟","options":["ألهمهم بأفكار مستقبلية تحوّلت لاحقًا إلى اختراعات حقيقية","منعهم من البحث","أغلق المختبرات","لم يؤثر أبدًا"],"answer":0,"why":"الغواصات والأقمار الصناعية ومكالمات الفيديو بدأت أفكارًا خيالية علمية."},{"type":"tfr","q":"قصص البساط الطائر والمصباح السحري تُعدّ من أدب الخيال العلمي.","answer":false,"reasons":["لأنها تنتمي للخيال الخرافي الأسطوري الذي لا يستند إلى قوانين علمية","لأنها تعتمد على الفيزياء","لأنها قصص واقعية"],"reason":0},{"type":"essay","q":"اذكر ثلاثة موضوعات يتناولها أدب الخيال العلمي.","model":"استكشاف الفضاء والكواكب، والروبوتات والذكاء الاصطناعي، والمدن المستقبلية، وتطوّر الطب والطاقة."},{"type":"tfr","q":"يطرح الخيال العلمي تساؤلاتٍ أخلاقيةً حول كيفية توجيه التقنية لخدمة الإنسان.","answer":true,"reasons":["لأنه ينبّه إلى ضرورة اقتران التقدم التقني بالأخلاق وحماية البيئة والإنسان","لأنه يهمل الأخلاق دائمًا","لأنه يرفض التقنية كلها"],"reason":0},{"type":"mcq","q":"ما السؤال المفتاحي الذي يبدأ منه كاتب الخيال العلمي قصته غالبًا؟","options":["ماذا لو تطوّر هذا العلم في المستقبل؟","كم عدد صفحات الكتاب؟","أين تقع المدرسة؟","متى ننام؟"],"answer":0,"why":"سؤال «ماذا لو؟» العلمي يفتح آفاق التخيل المستقبلي."},{"type":"essay","q":"علّل: لماذا نقول إن «خيال اليوم قد يصبح حقيقة الغد»؟","model":"لأن كثيرًا من الأفكار التي تخيّلها الأدباء اعتمادًا على العلم تحوّلت بفضل البحث والابتكار إلى اختراعات واقعية كالغواصات والأقمار الصناعية."},{"type":"tfr","q":"يمتاز أسلوب قصص الخيال العلمي بتبسيط المصطلحات العلمية داخل حبكة مشوّقة.","answer":true,"reasons":["لأنها تجمع بين المتعة القصصية والفائدة المعرفية للقارئ","لأنها تستخدم لغة غير مفهومة","لأنها تخلو من الأحداث"],"reason":0}],"hard":[{"type":"mcq","q":"ما الدور الذي يؤدّيه الخيال في عملية الابتكار العلمي؟","options":["يفتح آفاقًا جديدة للبحث ويصنع تصوّرات يسعى العلماء لتحقيقها","يعطّل التفكير المنطقي","يُلغي التجارب العلمية","يقتصر على الرسم"],"answer":0,"why":"الخيال المنضبط بالعلم هو الشرارة الأولى للاختراع."},{"type":"essay","q":"قارن بين «الخيال العلمي» و«الخيال الخرافي» من حيث الأساس والهدف.","model":"الخيال العلمي أساسه النظريات العلمية وهدفه استشراف المستقبل وتحفيز الإبداع والوعي، أما الخيال الخرافي فأساسه الخوارق والسحر وهدفه التسلية أو الرمز الأسطوري."},{"type":"tfr","q":"الذكاء الاصطناعي والروبوتات من الموضوعات التي انتقلت من الخيال العلمي إلى واقعنا المعاصر.","answer":true,"reasons":["لأنها كانت تُصوَّر في قصص القرن العشرين وأصبحت اليوم جزءًا من حياتنا اليومية","لأنها ما زالت مستحيلة تمامًا","لأنها من الخرافات"],"reason":0},{"type":"mcq","q":"أيُّ فكرةٍ مما يأتي تصلح نواةً لقصة خيال علمي؟","options":["ابتكار محطة طاقة شمسية في المدار لتزويد الأرض بالكهرباء النظيفة","فارس يطير على تنين سحري","وصف سوق شعبي قديم","قواعد المفعول به"],"answer":0,"why":"تستند إلى فكرة علمية قابلة للتطوير المستقبلي."},{"type":"essay","q":"تخيّل اختراعًا علميًا مفيدًا للتعليم بعد عشرين عامًا وصفه في سطرين.","model":"مثال: نظارة تعليمية ذكية تتيح للطلاب التجوّل افتراضيًا داخل جسم الإنسان أو الكواكب لفهم دروس العلوم واللغة العربية بتفاعل حيّ."},{"type":"tfr","q":"يجمع كاتب الخيال العلمي بين الثقافة العلمية والمهارة الأدبية.","answer":true,"reasons":["لأنه يحتاج للعلم لضبط فكرته، وللأدب لنسج قصة مشوّقة مؤثرة","لأنه لا يحتاج للقراءة العلمية","لأنه لا يحتاج للأدب"],"reason":0},{"type":"mcq","q":"ما المقصود بـ «استشراف المستقبل» في هذا الدرس؟","options":["التطلّع العلمي الواعي لما يمكن أن يؤول إليه العالم والتقنية مستقبلًا","التنجيم والغيب","نسيان الماضي","رفض التطور"],"answer":0,"why":"الاستشراف العلمي يقوم على المعطيات والاتجاهات العلمية."},{"type":"essay","q":"كيف يسهم الخيال العلمي في توعية الناس بقضايا البيئة؟","model":"من خلال تصوير مستقبل الأرض إذا أُهملت البيئة مقابل مستقبلها المزدهر عند الاعتماد على الطاقة النظيفة وحماية الطبيعة."},{"type":"tfr","q":"لا علاقة بين الأدب والعلوم الحديثة فكل منهما يعيش في عالم منفصل.","answer":false,"reasons":["لأن أدب الخيال العلمي دليل حيّ على التقاء الأدب بالعلم وتكاملهما","لأن الأدب يمنع العلم","لأن العلم يلغي الأدب"],"reason":0},{"type":"essay","q":"لخّص في جملتين الفائدة التربوية من إدراج درس «من الخيال العلمي» في منهج الصف التاسع.","model":"يدرّب الطلاب على التفكير الإبداعي والربط بين اللغة العربية والعلوم الحديثة، ويحفّزهم على الابتكار والتفكير المسؤول في مستقبل التقنية."}]}},
  {"id":"g9-arabic-1-u8-2","grade":"g9","subject":"arabic","term":1,"unit":8,"no":2,"title":"الأنشطة النحوية والصرفية: مراجعة لما سبقت دراسته","summary":"مراجعة متحركة شاملة لجميع دروس النحو في الفصل الأول للصف التاسع مع مقارنات وتدريبات، ثم أنشطة بثلاثة مستويات.","page":"lesson-u8-grammar-review.html","video":"","pdf":"","notes":["كاد وأخواتها (مقاربة، رجاء، شروع): تعمل عمل كان بشرط أن يكون خبرها جملة فعلية فعلها مضارع.","ظنّ وأخواتها (يقين، ظن، تحويل): تنصب مفعولين أصلهما المبتدأ والخبر (علمتُ العلمَ نورًا).","أعطى وأخواتها (أعطى، منح، وهب، كسا، ألبس، سأل، منع): تنصب مفعولين ليس أصلهما المبتدأ والخبر.","المفعول لأجله: مصدر قلبي منصوب يبيّن سبب الفعل ويجيب عن «لماذا؟» (أجتهدُ رغبةً في النجاح).","المفعول المطلق: مصدر منصوب من لفظ الفعل يؤكّده أو يبيّن نوعه أو عدده (فرحتُ فرحًا / قفزتُ قفزتين).","المفعول فيه (الظرف): اسم منصوب بتقدير «في» يبيّن زمان الفعل (متى؟) أو مكانه (أين؟)."],"exercises":["فرّق بين المفاعيل الثلاثة في: «ذاكرتُ مذاكرةً جيدةً صباحًا رغبةً في التفوّق».","قارن بين «كادَ» و«ظنَّ» و«منحَ» من حيث عمل كل فعل في الجملة.","أعرب: «عسى المجتهدُ أن ينجحَ»، و«منحَ المعلمُ الطالبَ جائزةً»."],"levels":{"easy":[{"type":"mcq","q":"أيُّ فعلٍ مما يأتي من أفعال الشروع؟","options":["شرعَ","عسى","علمَ","أعطى"],"answer":0,"why":"شرع وبدأ وأخذ وطفق من أفعال الشروع."},{"type":"mcq","q":"أين المفعول المطلق في: «اجتهدَ الطالبُ اجتهادًا طلبًا للنجاحِ صباحًا»؟","options":["اجتهادًا","طلبًا","صباحًا","الطالبُ"],"answer":0,"why":"«اجتهادًا» مصدر من لفظ الفعل اجتهدَ."},{"type":"mcq","q":"ما السؤال الذي نعرف به المفعول لأجله؟","options":["لماذا؟","أين؟","متى؟","كيف؟"],"answer":0,"why":"المفعول لأجله يبيّن سبب وقوع الفعل."},{"type":"mcq","q":"أيُّ فعلٍ ينصب مفعولين أصلهما المبتدأ والخبر؟","options":["جَعَلَ (التحويل)","مَنَحَ","كَسَا","بَدَأَ"],"answer":0,"why":"جعل من أخوات ظن (أفعال التحويل)."}],"medium":[{"type":"mcq","q":"ما إعراب «قلمَهُ» في: «أخذَ الطالبُ قلمَهُ»؟","options":["خبر أخذ","مفعول به منصوب","اسم أخذ","ظرف مكان"],"answer":1,"why":"أخذ هنا فعل تام لأن بعده اسمًا لا جملة فعلية مضارعة."},{"type":"tfr","q":"في جملة «سافرتُ يومَ الجمعةِ» كلمة «يومَ» مفعول فيه منصوب.","answer":true,"reasons":["لأنها تبيّن زمان السفر بتقدير «في يوم الجمعة»","لأنها فاعل","لأنها مفعول لأجله"],"reason":0},{"type":"essay","q":"استخرج المفاعيل الثلاثة من الجملة وبيّن نوع كل منها: «قَرَأتُ قراءةً متأنيةً مساءً حبًّا في المعرفة».","model":"قراءةً: مفعول مطلق (مبيّن للنوع). مساءً: مفعول فيه (ظرف زمان). حبًّا: مفعول لأجله."},{"type":"tfr","q":"يمتنع اقتران خبر «عَسَى» بـ «أنْ».","answer":false,"reasons":["لأن اقتران خبر «عسى» بأنْ يكثر، أما الذي يمتنع فهو أفعال الشروع","لأن عسى من أفعال الشروع","لأن عسى لا خبر لها"],"reason":0},{"type":"mcq","q":"ما علامة نصب المفعول المطلق في: «سجدتُ سجدتَينِ»؟","options":["الياء لأنه مثنى","الفتحة","الكسرة","الألف"],"answer":0,"why":"سجدتَينِ مثنى يُنصب بالياء."},{"type":"essay","q":"أعرب: «منحَ اللهُ الإنسانَ عقلًا».","model":"منحَ: فعل ماضٍ. اللهُ: فاعل مرفوع. الإنسانَ: مفعول به أول منصوب بالفتحة. عقلًا: مفعول به ثانٍ منصوب بالفتحة."},{"type":"tfr","q":"في جملة «رأيتُ العلمَ نورًا» تنصب «رأى» مفعولين لأنها قلبية بمعنى علم.","answer":true,"reasons":["لأن الرؤية هنا عقلية قلبية وليست بالعين","لأنها بصرية","لأنها فعل لازم"],"reason":0}],"hard":[{"type":"mcq","q":"أيُّ جملةٍ مما يأتي فيها «نائب عن المفعول المطلق»؟","options":["أحببتُ وطني كلَّ الحُبِّ","وقفتُ احترامًا للمعلم","جلستُ أمامَ البيتِ","كادَ المطرُ ينزلُ"],"answer":0,"why":"«كلَّ» مضافة إلى المصدر فتُعرب نائبًا عن المفعول المطلق."},{"type":"essay","q":"صوّب الأخطاء النحوية في الجمل الثلاث: (١) بدأَ الطالبُ أن يقرأَ. (٢) ظننتُ الطالبانِ غائبانِ. (٣) أُعْطِيَ المتفوّقينَ جوائزَ.","model":"(١) بدأَ الطالبُ يقرأُ (يمتنع اقتران الشروع بأنْ). (٢) ظننتُ الطالبَينِ غائبَينِ. (٣) أُعْطِيَ المتفوّقونَ جوائزَ."},{"type":"tfr","q":"إذا فقد المفعول لأجله شرط اتحاد الزمن مع الفعل وجب جرّه بحرف الجر.","answer":true,"reasons":["كما في: أعددتُ الحقيبةَ للسفرِ غدًا","لأنه يُنصب رغم اختلاف الزمن","لأنه يصير حالًا"],"reason":0},{"type":"mcq","q":"ما إعراب «حيثُ» في: «اجلسْ حيثُ يطيبُ لكَ»؟","options":["ظرف مكان مبني على الضم في محل نصب","مبتدأ","فاعل","مفعول لأجله"],"answer":0,"why":"حيثُ من الظروف المبنية على الضم في محل نصب."},{"type":"essay","q":"قارن بين عمل «كادَ» وعمل «ظنَّ» مع مثال لكل فعل.","model":"كادَ ترفع الاسم وتنصب الخبر ويشترط أن يكون خبرها جملة فعلية مضارعة (كادَ المطرُ ينزلُ). أما ظنَّ فتنصب مفعولين أصلهما مبتدأ وخبر (ظننتُ الجوَّ باردًا)."},{"type":"tfr","q":"في جملة «يلجأ الناسُ إلى المصايفِ خَشْيَةَ الحرِّ» تُعرب «خشيةَ» مفعولًا لأجله مضافًا منصوبًا بفتحة واحدة.","answer":true,"reasons":["لأن الإضافة تحذف التنوين، وهي مصدر قلبي يبيّن سبب اللجوء","لأنها حال","لأنها مفعول فيه"],"reason":0},{"type":"mcq","q":"أيُّ جملةٍ تشتمل على فعلٍ ناسخٍ من أخوات كاد؟","options":["أوشكَ الليلُ أن ينقضيَ","أعطى الغنيُّ الفقيرَ","علمتُ الصدقَ منجاةً","سافرتُ يومَ الخميسِ"],"answer":0,"why":"«أوشك» من أفعال المقاربة وخبره «أن ينقضيَ»."},{"type":"essay","q":"أعرب «فوقَ» و«خشيةَ» في: «وقفَ الحارسُ فوقَ البرجِ خشيةَ الغزوِ».","model":"فوقَ: مفعول فيه ظرف مكان منصوب بالفتحة وهو مضاف. خشيةَ: مفعول لأجله منصوب بالفتحة وهو مضاف."},{"type":"tfr","q":"كل اسم يدلّ على زمان مثل «يوم» يُعرب دائمًا ظرف زمان مهما كان موقعه في الجملة.","answer":false,"reasons":["لأنه متصرّف، فإن لم يتضمّن معنى «في» أُعرب حسب موقعه (مثل: يومُ العيدِ جميلٌ ← مبتدأ)","لأنه غير متصرّف","لأنه مبني"],"reason":0},{"type":"essay","q":"كوّن فقرة قصيرة من جملتين تشتمل على: فعل من أخوات كاد، ومفعول لأجله، وظرف زمان.","model":"مثال: بدأَ الطلابُ يذاكرونَ صباحًا رغبةً في التفوّقِ، وقد أوشكَ الاختبارُ أن يبدأَ."}]}},
  {"id":"g9-arabic-1-u8-3","grade":"g9","subject":"arabic","term":1,"unit":8,"no":3,"title":"الأنشطة الإملائية: تدريبات على علامات الترقيم","summary":"تدريبات متحركة شاملة على مواضع علامات الترقيم وأثرها في وضوح المعنى، ثم أنشطة بثلاثة مستويات.","page":"lesson-punctuation-practice.html","video":"","pdf":"","notes":["النقطة (.): توضع في نهاية الجملة التامة المعنى وفي نهاية الفقرة.","الفاصلة (،): توضع بين الجمل القصيرة المترابطة، وبين أقسام الشيء، وبعد المنادى.","الفاصلة المنقوطة (؛): توضع بين جملتين تكون إحداهما سببًا أو نتيجةً للأخرى.","النقطتان الرأسيتان (:): توضعان بعد القول، وقبل التعداد والتفصيل، وقبل التمثيل والتعريف.","علامة الاستفهام (؟) بعد السؤال، وعلامة التعجب (!) بعد الدهشة والتأثر، وعلامتا التنصيص (« ») للكلام المنقول حرفيًا.","الشرطتان (– ... –) توضع بينهما الجملة الاعتراضية (مثل: قال النبي – صلى الله عليه وسلم –)."],"exercises":["ضع علامات الترقيم المناسبة: «قال المعلم يا أبنائي اجتهدوا لأن العلم نور فهل أنتم مستعدون».","ما الفرق في الاستخدام بين الفاصلة (،) والفاصلة المنقوطة (؛)؟","مثّل لجملة تحتوي على شرطتَي الاعتراض وعلامتَي التنصيص."],"levels":{"easy":[{"type":"mcq","q":"أين توضع النقطة (.)؟","options":["في نهاية الجملة التامة والفقرة","بعد المنادى","بعد القول","قبل التعداد"],"answer":0,"why":"النقطة علامة الوقف التام في نهاية الجملة أو الفقرة."},{"type":"mcq","q":"ما العلامة المناسبة في الفراغ: «نجح الطالبُ ...... لأنه اجتهدَ»؟","options":["؛","؟","!",":"],"answer":0,"why":"الثانية سبب للأولى فنضع الفاصلة المنقوطة."},{"type":"mcq","q":"ما العلامة المناسبة في الفراغ: «ما أروعَ الخريفَ في صلالة ......»؟","options":["!","؟","،",":"],"answer":0,"why":"أسلوب تعجب يختم بعلامة التعجب (!)."},{"type":"mcq","q":"ما العلامة التي يُحصر بينها الكلام المنقول حرفيًا؟","options":["علامتا التنصيص (« »)","الفاصلة","النقطة","الاستفهام"],"answer":0,"why":"تدلّ علامتا التنصيص على أمانة النقل الحرفي."}],"medium":[{"type":"mcq","q":"ما العلامة المناسبة بعد المنادى في: «يا طالبُ ...... نظّمْ وقتَكَ»؟","options":["الفاصلة (،)","علامة الاستفهام (؟)","النقطة (.)","علامة الحذف"],"answer":0,"why":"توضع الفاصلة بعد المنادى."},{"type":"tfr","q":"تُوضع الجملة الاعتراضية مثل «صلى الله عليه وسلم» بين شرطتين (– ... –).","answer":true,"reasons":["لأن الشرطتين تحصران الجملة الاعتراضية التي يصح المعنى بدونها","لأنها توضع بين علامتي استفهام","لأنها توضع بعد نقطة"],"reason":0},{"type":"essay","q":"أعد كتابة الجملة بوضع علامات الترقيم المناسبة: «قال أبي يا بني احفظ وقتك لأن الوقت ثمين».","model":"قال أبي: «يا بني، احفظ وقتك؛ لأن الوقت ثمين»."},{"type":"tfr","q":"تُوضع النقطتان الرأسيتان (:) في نهاية السؤال.","answer":false,"reasons":["لأن نهاية السؤال توضع فيها علامة الاستفهام (؟)، أما النقطتان فبعد القول وقبل التعداد","لأن السؤال يختم بنقطة","لأن النقطتين توضعان بعد التعجب"],"reason":0},{"type":"mcq","q":"كم نقطة تتكوّن منها «علامة الحذف»؟","options":["ثلاث نقاط (...)","نقطة واحدة","خمس نقاط","نقطتان"],"answer":0,"why":"تُكتب علامة الحذف ثلاث نقاط متجاورة فقط."},{"type":"essay","q":"اذكر ثلاثة مواضع لاستخدام النقطتين الرأسيتين (:).","model":"١) بعد القول (قال:). ٢) قبل التعداد والتفصيل. ٣) قبل التعريف أو المثال."},{"type":"tfr","q":"تساعد علامات الترقيم على إزالة اللبس وتحديد المعنى المقصود في الجملة.","answer":true,"reasons":["لأنها تبيّن حدود الجمل والوقف والتعجب والاستفهام والسبب","لأنها للزينة الشكلية فقط","لأنها تغيّر الإملاء"],"reason":0}],"hard":[{"type":"mcq","q":"ما العلامة المناسبة في نهاية: «أتعقّ والديك وقد ربياك صغيرًا ......»؟","options":["؟!",".","،",":"],"answer":0,"why":"استفهام استنكاري تعجبي تجتمع فيه (؟!)."},{"type":"essay","q":"ضع علامات الترقيم في الفقرة: «أركان الإسلام خمسة الشهادة والصلاة والزكاة والصوم والحج فما أعظم هذا الدين».","model":"أركان الإسلام خمسة: الشهادة، والصلاة، والزكاة، والصوم، والحج؛ فما أعظم هذا الدين!"},{"type":"tfr","q":"تُستخدم الفاصلة (،) بين أقسام الشيء وأنواعه عند التعداد.","answer":true,"reasons":["مثل: فصول السنة أربعة: الصيف، والخريف، والشتاء، والربيع","لأن التعداد يُفصل بنقطة","لأن التعداد بلا فواصل"],"reason":0},{"type":"mcq","q":"أين نضع القوسين ( ) عادةً؟","options":["حول كلمة تفسيرية أو رقم أو مصطلح توضيحي","في بداية السطر دائمًا","بعد قال مباشرة","بدل النقطة"],"answer":0,"why":"القوسان يحصران التفسير أو التوضيح الإضافي."},{"type":"essay","q":"فرّق بمثالين بين استخدام الفاصلة (،) واستخدام الفاصلة المنقوطة (؛).","model":"الفاصلة للترابط والتعداد: قرأ خالدٌ، وكتبَ واجبَه. المنقوطة للسبب والنتيجة: نجح خالدٌ؛ لأنه اجتهدَ."},{"type":"tfr","q":"ترك النص بلا علامات ترقيم قد يُسبب سوء فهم للقارئ.","answer":true,"reasons":["لأن القارئ لا يعرف أين تنتهي الجملة ولا يميّز السؤال من الخبر أو السبب","لأن القارئ يخمن دائمًا بسهولة","لأن الترقيم غير مهم"],"reason":0},{"type":"mcq","q":"أيُّ جملةٍ استُخدمت فيها علامات الترقيم استخدامًا صحيحًا بالكامل؟","options":["قال الحكيم: «الصبرُ مفتاحُ الفرجِ».","قال الحكيم، الصبر مفتاح الفرج؟","قال الحكيم؛ الصبر مفتاح الفرج!","قال الحكيم. الصبر مفتاح الفرج:"],"answer":0,"why":"نقطتان بعد القول، وتنصيص للحكمة، ونقطة في النهاية."},{"type":"essay","q":"أدخل جملةً اعتراضيةً بين شرطتين في الجملة الآتية: «الإمام السالمي مؤرخ عُماني جليل».","model":"الإمام السالمي – رحمه الله – مؤرخ عُماني جليل."},{"type":"tfr","q":"تُوضع علامة التنصيص حول النص إذا نقلناه بتصرّف وبأسلوبنا الخاص.","answer":false,"reasons":["لأن التنصيص يُستخدم للنقل الحرفي فقط، أما النقل بالتصرّف فلا يُحصر بين علامتي تنصيص","لأنه يُوضع حول كل جملة في المقال","لأنه خاص بالأسئلة"],"reason":0},{"type":"essay","q":"اكتب فقرة من ثلاث جمل توظّف فيها خمس علامات ترقيم مختلفة.","model":"مثال: سألني أخي: «هل قرأتَ كتابًا اليوم؟» فأجبتُه: نعم، قرأتُ قصةً ممتعةً؛ لأنني أحبّ المطالعة، فما أجمل القراءة!"}]}},
  {"id":"g9-arabic-1-u8-4","grade":"g9","subject":"arabic","term":1,"unit":8,"no":4,"title":"التعبير: حكاية قصة","summary":"شرح متحرك لعناصر القصة القصيرة وخطوات كتابتها (البداية والعقدة والحل) وتوظيف الحوار والوصف، ثم أنشطة بثلاثة مستويات.","page":"lesson-storytelling.html","video":"","pdf":"","notes":["القصة القصيرة: فن أدبي نثري يروي حادثةً أو مجموعة أحداث مترابطة تقع لشخصيات في زمان ومكان محددين.","عناصر القصة الأساسية: الشخصيات (رئيسة وثانوية)، والزمان والمكان، والأحداث (الحبكة)، والعقدة (المشكلة)، والحل.","البداية تمهّد للقصة وتقدّم الشخصيات والبيئة وتشدّ انتباه القارئ.","العقدة (الذروة) هي لحظة تأزّم المشكلة التي يبلغ عندها التشويق أقصاه.","الحل (النهاية) يأتي مقنعًا ومنطقيًا ويكشف المغزى أو العبرة دون وعظٍ مباشرٍ مملّ.","نوظّف في كتابة القصة السرد والوصف والحوار، مع اختيار عنوان مشوّق ولغة سلسة."],"exercises":["اذكر العناصر الخمسة الأساسية للقصة القصيرة.","ما المقصود بـ «العقدة» في بناء القصة؟","اكتب قصة قصيرة من عشر أسطر حول موقفٍ تعلّمتَ منه قيمة «الأمانة»."],"levels":{"easy":[{"type":"mcq","q":"أيٌّ مما يأتي ليس من عناصر القصة الأساسية؟","options":["الشخصيات","الزمان والمكان","العقدة والحل","جدول الضرب"],"answer":3,"why":"عناصر القصة: الشخصيات، والزمان والمكان، والأحداث، والعقدة، والحل."},{"type":"mcq","q":"ما المقصود بـ «العقدة» في القصة؟","options":["لحظة تأزّم المشكلة وذروة التشويق","أول سطر في القصة","اسم المؤلف","نهاية القصة"],"answer":0,"why":"العقدة هي ذروة الصراع أو المشكلة التي يواجهها البطل."},{"type":"mcq","q":"ما نوعا الشخصيات في القصة القصيرة؟","options":["رئيسة وثانوية","ماضية ومضارعة","مرفوعة ومنصوبة","مفردة ومثناة"],"answer":0,"why":"تضم القصة شخصية رئيسة (البطل) وشخصيات ثانوية مساندة."},{"type":"mcq","q":"ما فائدة الحوار داخل القصة؟","options":["كسر الرتابة وكشف طباع الشخصيات ومشاعرها","إخفاء الأحداث","إلغاء السرد","إطالة العنوان"],"answer":0,"why":"الحوار يمنح القصة حيوية وواقعية."}],"medium":[{"type":"mcq","q":"كيف ينبغي أن تظهر «العبرة» في القصة الناجحة؟","options":["يستنتجها القارئ بسلاسة من الأحداث وسلوك البطل","بخطبة وعظية طويلة مملة","بلا علاقة بالقصة","في العنوان فقط"],"answer":0,"why":"الفن القصصي يوصل القيم عبر الحدث لا الوعظ المباشر الثقيل."},{"type":"tfr","q":"تحديد الزمان والمكان في بداية القصة يساعد القارئ على تخيّل الأحداث ومعايشتها.","answer":true,"reasons":["لأنه يرسم المسرح الذي تتحرك فيه الشخصيات بوضوح","لأن القصة لا تحتاج زمانًا ولا مكانًا","لأنه يحرق النهاية"],"reason":0},{"type":"essay","q":"اذكر العناصر الخمسة الأساسية لبناء القصة القصيرة.","model":"الشخصيات، والزمان والمكان، والأحداث (الحبكة)، والعقدة (الذروة)، والحل (النهاية)."},{"type":"tfr","q":"يُفضّل أن يكشف عنوان القصة القصيرة نهايتها والحل منذ البداية.","answer":false,"reasons":["لأن العنوان الجيّد يكون مشوّقًا وغامضًا قليلًا دون أن يحرق النهاية","لأن التشويق غير مهم","لأن العنوان يجب أن يكون فقرة كاملة"],"reason":0},{"type":"mcq","q":"ما وظيفة «الوصف» في القصة؟","options":["تصوير ملامح المكان والشخصيات والمشاعر ليراها القارئ","سرد التواريخ فقط","كتابة الأسئلة فقط","حذف الشخصيات"],"answer":0,"why":"الوصف يرسم الصورة الحسية والنفسية للمشهد."},{"type":"essay","q":"اقترح بداية مشوّقة وعقدة مناسبة لقصة بعنوان «المفتاح المفقود».","model":"البداية: في صباح يوم الامتحان، بحث سامي في حقيبته فلم يجد مفتاح خزانته التي تحوي أوراقه. العقدة: لم يبقَ على جرس الاختبار سوى عشر دقائق والخزانة مغلقة بإحكام!"},{"type":"tfr","q":"تسلسل الأحداث المنطقي يربط بين البداية والعقدة والحل في وحدة متماسكة.","answer":true,"reasons":["لأن كل حدث يمهّد لما بعده حتى يصل القارئ لحل مقنع","لأن الأحداث العشوائية أفضل","لأن القصة بلا ترتيب"],"reason":0}],"hard":[{"type":"mcq","q":"أيُّ بدايةٍ مما يأتي أكثر تشويقًا لقصة قصيرة؟","options":["«توقّف القارب فجأةً وسط الضباب، ولم نعد نرى الشاطئ!»","«القارب وسيلة نقل بحرية.»","«سأكتب لكم قصة عن البحر.»","«البحر مالح.»"],"answer":0,"why":"تبدأ بحدث حيّ ومثير يشدّ القارئ منذ الجملة الأولى."},{"type":"essay","q":"فرّق بين «السرد» و«الوصف» و«الحوار» داخل القصة القصيرة.","model":"السرد هو حكاية الأفعال والأحداث المتتابعة، والوصف هو رسم صور الأماكن والشخصيات والمشاعر، والحوار هو تبادل الكلام بين الشخصيات."},{"type":"tfr","q":"قد يأتي الحل في القصة مفتوحًا أحيانًا ليترك للقارئ مجالًا للتفكير والتأمل.","answer":true,"reasons":["لأن النهاية المفتوحة أسلوب قصصي فني يثير خيال القارئ","لأن القصة يجب أن تنتهي دائمًا بجملة واحدة ثابتة","لأن الحل غير موجود أبدًا"],"reason":0},{"type":"mcq","q":"لماذا نكتفي بعددٍ محدودٍ من الشخصيات في القصة القصيرة؟","options":["لتحقيق التركيز والتكثيف وتجنّب تشتّت القارئ","لعدم وجود أسماء","لأنها شعر","لأن الحوار ممنوع"],"answer":0,"why":"القصة القصيرة تقوم على التركيز حول حدث واحد وشخصيات محدودة."},{"type":"essay","q":"حوّل العبارة السردية الآتية إلى حوار قصير: «أخبر خالدٌ صديقه بأنه وجد محفظةً ويريد تسليمها للإدارة».","model":"قال خالدٌ لصديقه: «لقد وجدتُ هذه المحفظة في الساحة، سأسلّمها فورًا لإدارة المدرسة». ابتسم صديقه وقال: «أحسنتَ يا خالد، هذه هي الأمانة!»."},{"type":"tfr","q":"الشخصيات الثانوية في القصة لا دور لها ويمكن حذفها دائمًا.","answer":false,"reasons":["لأنها تساعد في تحريك الأحداث وإبراز صفات الشخصية الرئيسة","لأنها أهم من البطل دائمًا","لأن القصة بلا شخصيات"],"reason":0},{"type":"mcq","q":"ما الذي يجعل نهاية القصة «غير مقنعة»؟","options":["ظهور حلّ مفاجئ غير منطقي لا يرتبط بالأحداث السابقة","ارتباط الحل بسلوك البطل","وضوح المغزى","اختصار النهاية"],"answer":0,"why":"الحل الجيّد ينبع طبيعيًا من تصاعد الأحداث."},{"type":"essay","q":"اذكر ثلاثة أخطاء ينبغي تجنّبها عند كتابة قصة قصيرة.","model":"١) الإطالة المملة في البداية دون حدث. ٢) حشد شخصيات كثيرة بلا دور. ٣) تقديم حل غير منطقي أو وعظ مباشر ثقيل."},{"type":"tfr","q":"يمكن للكاتب أن يروي القصة بضمير المتكلم (أنا) أو بضمير الغائب (هو).","answer":true,"reasons":["لأن كلا الضميرين أسلوب سردي شائع يختاره الكاتب حسب زاوية الرؤية","لأن القصة تُروى بضمير المخاطب فقط","لأن ضمير المتكلم للسيرة فقط"],"reason":0},{"type":"essay","q":"اكتب قصة قصيرة جدًا (٥ أسطر) مكتملة العناصر (بداية، عقدة، حل) حول قيمة «التعاون».","model":"في صباح يوم ممطر، انقلب صندوق الكتب من يد سلمى في ساحة المدرسة فتناثرت الأوراق وبدأ المطر يبلّلها. وقفت حائرةً لا تستطيع جمعها وحدها قبل أن تتلف. أسرع زملاؤها نحوها فحمل بعضهم المظلات وجمع آخرون الكتب بسرعة. وفي لحظات عادت الكتب سالمةً إلى مكانها، وابتسمت سلمى شاكرةً لهم روح التعاون."}]}},
  {"id":"g9-arabic-1-u8-5","grade":"g9","subject":"arabic","term":1,"unit":8,"no":5,"title":"الاستماع: الرازي","summary":"شرح متحرك لسيرة العالم الطبيب أبي بكر الرازي وإنجازاته الطبية والعلمية، ثم أنشطة بثلاثة مستويات.","page":"lesson-al-razi.html","video":"","pdf":"","notes":["أبو بكر محمد بن زكريا الرازي (٢٥١هـ – ٣١٣هـ) من أعظم أطباء وعلماء الحضارة الإسلامية والعالم.","وُلد في مدينة الريّ، وتعلّم الطب والفلسفة والكيمياء، وتولّى رئاسة مستشفى بغداد (البيمارستان العضدي).","يُعدّ رائد «الطب التجريبي والملاحظة السريرية»، فكان يدوّن ملاحظاته بدقة عن كل مريض.","من أشهر اكتشافاته: أول من فرّق علميًا بدقة بين مرضَي «الجدري» و«الحصبة»، واستخدم خيوط الجراحة.","من أشهر مؤلفاته: موسوعة «الحاوي في الطب» التي تُرجمت إلى اللاتينية ودُرّست في جامعات أوروبا قرونًا.","ابتكر تجربةً ذكيةً لاختيار أصحّ موقعٍ لبناء مستشفى بغداد بتعليق قطع لحم في أنحاء المدينة لمعرفة أنقى هواء."],"exercises":["كيف اختار الرازي أنسب موقع لبناء مستشفى بغداد؟","اذكر إنجازَين طبيَّين بارزَين لأبي بكر الرازي.","ما اسم الموسوعة الطبية الأشهر للرازي، وما أثرها في العالم؟"],"levels":{"easy":[{"type":"mcq","q":"من هو مؤلّف موسوعة «الحاوي في الطب»؟","options":["أبو بكر الرازي","الجاحظ","المتنبي","الخليل بن أحمد"],"answer":0,"why":"ألّف الرازي موسوعة الحاوي التي أصبحت مرجعًا عالميًا."},{"type":"mcq","q":"بين أي مرضَين كان الرازي أول من فرّق علميًا بدقة؟","options":["الجدري والحصبة","الصداع والزكام","الحساسية والربو","الأرق والتعب"],"answer":0,"why":"رسالته في الجدري والحصبة من أعظم إنجازات الطب."},{"type":"mcq","q":"بماذا يُعرف المنهج الذي أسّسه الرازي في الطب؟","options":["الطب التجريبي والملاحظة السريرية","الطب الخرافي","العلاج بالتخمين","الطب الشعري"],"answer":0,"why":"اعتمد التجربة ومتابعة أعراض المريض وتدوينها."},{"type":"mcq","q":"كيف كان يعامل الرازي المرضى الفقراء؟","options":["يعالجهم مجانًا ويعطف عليهم","يرفض علاجهم","يطلب منهم مالًا كثيرًا","لا يستقبلهم"],"answer":0,"why":"كان مثالًا للرحمة والإنسانية في مهنة الطب."}],"medium":[{"type":"mcq","q":"لماذا علّق الرازي قطع لحم في أحياء بغداد قبل بناء المستشفى؟","options":["لاختيار المكان الأنقى هواءً حيث يتأخّر فساد اللحم","لبيع اللحم","لإطعام الطيور","للزينة"],"answer":0,"why":"تأخّر فساد اللحم يدلّ على نقاء الهواء وصلاحيته للمرضى."},{"type":"tfr","q":"دُرّست مؤلفات الرازي الطبية في جامعات أوروبا لعدة قرون بعد ترجمتها للاتينية.","answer":true,"reasons":["لأنها كانت أدقّ وأشمل المراجع الطبية في العالم آنذاك","لأنها لم تُترجم أبدًا","لأنها كتب شعر"],"reason":0},{"type":"essay","q":"اذكر ثلاثة إنجازات طبية وعلمية لأبي بكر الرازي.","model":"١) التفريق العلمي بين الجدري والحصبة. ٢) تأليف موسوعة «الحاوي في الطب». ٣) تأسيس الطب التجريبي والملاحظة السريرية، واستخدام خيوط الجراحة."},{"type":"tfr","q":"اهتمّ الرازي بالجانب النفسي للمريض وأثره في سرعة الشفاء.","answer":true,"reasons":["لأنه كان يراعي نفسية المريض ويعامله بلطف ليدعم علاجه الجسدي","لأنه أهمل نفسية المريض","لأنه لم يعالج المرضى مباشرة"],"reason":0},{"type":"mcq","q":"في أي مدينة وُلد أبو بكر الرازي؟","options":["مدينة الريّ","الكوفة","مسقط","قرطبة"],"answer":0,"why":"وُلد في مدينة الريّ ونُسب إليها (الرازي)."},{"type":"essay","q":"اشرح باختصار تجربة الرازي الذكية لاختيار موقع مستشفى بغداد.","model":"علّق قطع لحم طازجة في مناطق مختلفة من بغداد وراقبها، فاختار المنطقة التي بقي فيها اللحم سليمًا أطول وقت؛ لأن هواءها أنقى وأصحّ للمرضى."},{"type":"tfr","q":"اكتفى الرازي بنقل كلام الأطباء القدامى دون أن يجرّب أو يلاحظ بنفسه.","answer":false,"reasons":["لأنه كان رائد المنهج التجريبي والملاحظة السريرية وتدوين ملفات المرضى","لأنه لم يقرأ كتابًا","لأنه لم يعمل في مستشفى"],"reason":0}],"hard":[{"type":"mcq","q":"ما الدلالة العلمية لتجربة قطع اللحم التي ابتكرها الرازي؟","options":["وعيه المبكر بعلاقة نقاء البيئة والهواء بصحة الإنسان ومنع العدوى","أن اللحم يعالج المرض","أن المستشفى يُبنى في الأسواق","أنها مجرد صدفة"],"answer":0,"why":"تثبت عبقريته في التفكير التجريبي والوقاية الصحية."},{"type":"essay","q":"كيف جمع الرازي بين «عبقرية العالِم» و«إنسانية الطبيب»؟","model":"جمع بين الدقة العلمية والابتكار والتأليف الغزير، وبين الرحمة بالمرضى وعلاج الفقراء مجانًا والرفق بهم."},{"type":"tfr","q":"يُعدّ تدوين الرازي لملاحظاته اليومية حول حالة كل مريض أصلًا لفكرة «الملف الطبي» الحديث.","answer":true,"reasons":["لأن متابعة الأعراض وتطوّر العلاج كتابيًا هي جوهر الممارسة الطبية الحديثة","لأنه لم يكتب ملاحظات أبدًا","لأنه اعتمد على الذاكرة فقط"],"reason":0},{"type":"mcq","q":"أيُّ علمٍ آخر أبدع فيه الرازي إلى جانب الطب؟","options":["الكيمياء والفلسفة","الملاحة البحرية","علم العروض","علم الآثار"],"answer":0,"why":"كان الرازي عالِمًا موسوعيًّا برع في الطب والكيمياء والفلسفة."},{"type":"essay","q":"ما الأثر الحضاري لترجمة كتب علماء المسلمين كالرازي إلى اللغات الأوروبية؟","model":"أسهمت في نقل المنهج العلمي التجريبي وبناء النهضة الطبية والعلمية الحديثة في أوروبا والعالم."},{"type":"tfr","q":"الجمع بين العلم التخصصي والأخلاق المهنية هو ما يصنع القدوة في كل مجال.","answer":true,"reasons":["كما جسّد الرازي في إتقانه للطب ورحمته بالفقراء والمرضى","لأن الأخلاق لا علاقة لها بالطب","لأن الطبيب يحتاج للمال فقط"],"reason":0},{"type":"mcq","q":"ما معنى كلمة «البيمارستان» في التراث الإسلامي؟","options":["المستشفى","المكتبة","السوق","القلعة"],"answer":0,"why":"البيمارستان هو المستشفى، وقد تولى الرازي رئاسة مستشفى بغداد."},{"type":"essay","q":"اذكر قيمتين علميتين تتعلّمهما من منهج الرازي وتطبّقهما في دراستك للعلوم.","model":"١) الملاحظة الدقيقة والتجربة قبل إطلاق الأحكام. ٢) التدوين المنظّم للنتائج والبحث المستمر."},{"type":"tfr","q":"ألّف الرازي أكثر من مئتي كتاب ورسالة في الطب والعلوم.","answer":true,"reasons":["مما يعكس غزارة علمه واجتهاده وخدمته الطويلة للمعرفة","لأنه لم يؤلف سوى كتاب واحد","لأنه لم يكتب شيئًا"],"reason":0},{"type":"essay","q":"اكتب تعريفًا موجزًا من سطرين لأبي بكر الرازي على طريقة «ترجمة علم».","model":"وُلد أبو بكر محمد بن زكريا الرازي في الريّ عام ٢٥١هـ، ونبغ في الطب والكيمياء. أسّس المنهج التجريبي، وفرّق بين الجدري والحصبة، وألّف «الحاوي في الطب»، وتوفي عام ٣١٣هـ تاركًا أثرًا عالميًا خالدًا."}]}},
  {"id":"g9-arabic-1-u8-6","grade":"g9","subject":"arabic","term":1,"unit":8,"no":6,"title":"النص الأدبي: حسن المجالسة وسوؤها","summary":"شرح متحرك لنص «حسن المجالسة وسوؤها» وأثر الصحبة وآداب المجالس وجماليات النص، ثم أنشطة بثلاثة مستويات.","page":"lesson-good-company.html","video":"","pdf":"","notes":["يتناول النص أثر الصحبة والمجالسة في تشكيل أخلاق الإنسان وسلوكه وسمعته بين الناس.","الجليس الصالح كحامل المسك: ينفعك بعلمه ونصيحته وأخلاقه، ويحفظ سمعتك في غيابك.","جليس السوء كنافخ الكير: يؤذيك بلسانه أو يجرك إلى المعاصي أو يسيء إلى سمعتك.","من آداب المجالسة الحسنة: حسن الاستماع، وحفظ اللسان من الغيبة، ولطف الكلام، والتوقير، وإفشاء السلام.","يقوم النص على المقابلة البلاغية بين صفات الجليس الصالح وصفات جليس السوء لإبراز الفارق الكبير بينهما.","العبرة التربوية: حسن اختيار الأصدقاء في المدرسة والحياة أساسٌ للنجاح والاستقامة."],"exercises":["قارن بين أثر الجليس الصالح وأثر جليس السوء كما ورد في النص.","اذكر ثلاثًا من آداب المجالسة الحسنة.","ما أثر المقابلة البلاغية في إيصال فكرة النص؟"],"levels":{"easy":[{"type":"mcq","q":"بماذا شُبّه الجليس الصالح في الحديث الشريف؟","options":["بحامل المسك","بنافخ الكير","بالسحاب","بالسيف"],"answer":0,"why":"لأنه ينفع صاحبه بالخير والسمعة الطيبة كرائحة المسك."},{"type":"mcq","q":"بماذا شُبّه جليس السوء؟","options":["بنافخ الكير","بحامل المسك","بالقمر","بالنهر"],"answer":0,"why":"لأنه يؤذي صاحبه في أخلاقه أو سمعته."},{"type":"mcq","q":"ما العلاقة البلاغية بين «حُسن» و«سوء» في عنوان النص؟","options":["طباق","ترادف","جناس","سجع"],"answer":0,"why":"كلمتان متضادتان بينهما طباق يوضّح المعنى."},{"type":"mcq","q":"أيٌّ مما يأتي من آداب المجالس؟","options":["حسن الاستماع وحفظ اللسان","الغيبة والنميمة","مقاطعة المتحدث","التهامس دون الثالث"],"answer":0,"why":"المجلس الحسن يقوم على الاحترام وحفظ اللسان والأمانة."}],"medium":[{"type":"mcq","q":"لماذا نُهي عن «التناجي» (تهامس اثنين دون ثالثهما) في المجلس؟","options":["لأن ذلك يُحزنه ويثير الشك في نفسه","لأنه يرفع الصوت","لأنه يطيل المجلس","لأنه يضيّع الكتب"],"answer":0,"why":"التناجي يجرح مشاعر الثالث ويهدم الثقة في المجلس."},{"type":"tfr","q":"تقتصر فكرة «المجالسة» اليوم على اللقاءات الحضورية فقط ولا تشمل مجموعات الهاتف ومواقع التواصل.","answer":false,"reasons":["لأن الحسابات والمجموعات الرقمية تؤثر في الفكر والسلوك تمامًا كالجليس الواقعي","لأن الهاتف لا يُستخدم للتواصل","لأن الإنترنت لا يؤثر في الأخلاق"],"reason":0},{"type":"essay","q":"اذكر أربعًا من آداب المجالسة الحسنة.","model":"إفشاء السلام، وطلاقة الوجه، وحسن الاستماع دون مقاطعة، وحفظ اللسان عن الغيبة، وحفظ أسرار المجلس، والتفسّح للقادمين."},{"type":"tfr","q":"«المجالس بالأمانات» يعني وجوب حفظ أسرار المجلس وعدم إفشائها.","answer":true,"reasons":["لأن إفشاء أسرار المجالس خيانة للأمانة ويفسد العلاقات بين الناس","لأن الأسرار تُنشر للجميع","لأن الأمانة في المال فقط"],"reason":0},{"type":"mcq","q":"كيف يؤثر جليس السوء فيك حتى لو لم تفعل مثل أخطائه؟","options":["يسيء إلى سمعتك بين الناس ويجرّك تدريجيًا لتقليده","يزيدك علمًا","يحفظ أسرارك","يرفع مكانتك"],"answer":0,"why":"كنافخ الكير: إن لم يحرق ثيابك أصابك من رائحته الخبيثة."},{"type":"essay","q":"قارن بين أثر الجليس الصالح وأثر جليس السوء في حياة الطالب المدرسية.","model":"الجليس الصالح يشجّع على المذاكرة والأخلاق الحسنة ويحفظ الوقت، أما جليس السوء فيضيّع الوقت ويشجّع على الإهمال والسلوك الخاطئ."},{"type":"tfr","q":"تُبرز المقابلة بين حسن المجالسة وسوئها الفارق العميق بين طريق النجاح وطريق الضرر.","answer":true,"reasons":["لأن عرض الضدين معًا يجعل القارئ يدرك قيمة الاختيار الصحيح","لأن المقابلة تضعف المعنى","لأن النص لم يقارن بينهما"],"reason":0}],"hard":[{"type":"mcq","q":"ما دلالة المثل العربي «الصاحبُ ساحبٌ»؟","options":["أن الصديق يجرّ صديقه بطباعه وسلوكه نحو الخير أو الشر","أن الصديق يحمل الحقيبة","أن الصداقة لا تؤثر في أحد","أن السفر يحتاج لصاحب"],"answer":0,"why":"المخالطة الطويلة تنقل الطباع والعادات بين الأصدقاء."},{"type":"essay","q":"كيف تختار أصدقاءك في المدرسة وعلى الإنترنت استنادًا إلى هذا الدرس؟","model":"أختار من يتّسمون بالصدق والأدب والجدّ في الدراسة، وأبتعد عن المجالس والمجموعات التي فيها غيبة أو سخرية أو تضييع للوقت."},{"type":"tfr","q":"التشبيه التمثيلي في «حامل المسك ونافخ الكير» يقرّب المعنى المعنوي بصورة حسية واضحة.","answer":true,"reasons":["لأنه جسّد أثر الصحبة الخفيّ بصورة الرائحة الطيبة مقابل الشرر والدخان","لأنه خالٍ من التصوير","لأنه أسلوب استفهام"],"reason":0},{"type":"mcq","q":"ما التصرف الأمثل إذا تحوّل مجلسٌ تجلس فيه إلى غيبةٍ وسخرية؟","options":["تغيّر الموضوع بلطف أو تنصحهم أو تغادر المجلس","تشاركهم السخرية","تسكت راضيًا","تسجّل كلامهم"],"answer":0,"why":"إنكار السوء بلطف أو مغادرة المجلس يحفظ دينك وأخلاقك."},{"type":"essay","q":"اشرح معنى القول: «المجالس مدارس» بأسلوبك.","model":"لأن الإنسان يتعلّم في المجالس الصالحة الأدب والحكمة والخبرة من أهل العلم والفضل، مثلما يتعلّم في المدرسة."},{"type":"tfr","q":"إكرام الضيف والتفسّح له في المجلس من مظاهر حسن المجالسة.","answer":true,"reasons":["لأنه يشعر القادم بالترحيب والاحترام ويعزّز المودة بين الحاضرين","لأنه يمنع الجلوس","لأنه خاص بالأقارب فقط"],"reason":0},{"type":"mcq","q":"أيُّ صفةٍ تُعدّ الأهم عند اختيار الجليس الصالح؟","options":["الصدق والأخلاق الحسنة وحبّ الخير","كثرة المال فقط","الشهرة فقط","كثرة المزاح غير المنضبط"],"answer":0,"why":"الأخلاق والصدق هما أساس الصحبة النافعة الدائمة."},{"type":"essay","q":"اذكر موقفًا من حياتك المدرسية استفدتَ فيه من نصيحة صديقٍ صالح.","model":"مثال: عندما تردّدتُ في المشاركة بمسابقة علمية، شجّعني صديقي وساعدني في التحضير حتى حقّقتُ مركزًا متقدمًا."},{"type":"tfr","q":"حسن الاستماع للآخرين دون مقاطعة يعكس أدب الجليس ورقيّ شخصيته.","answer":true,"reasons":["لأن الإنصات يدل على الاحترام ويساعد على الفهم الصحيح قبل الرد","لأن المقاطعة دليل ذكاء","لأن الاستماع لا علاقة له بالمجلس"],"reason":0},{"type":"essay","q":"اكتب ثلاث قواعد ذهبية لـ «مجلس طلابي ناجح ومفيد».","model":"١) الترحيب والسلام وحسن الإنصات للجميع. ٢) الحديث فيما ينفع والبعد عن الغيبة والسخرية. ٣) احترام الآراء وحفظ أسرار المجلس."}]}},
  {"id":"g9-arabic-1-u8-7","grade":"g9","subject":"arabic","term":1,"unit":8,"no":7,"title":"اقرأ واستمتع: حذق طبيب","summary":"شرح متحرك لقصة «حذق طبيب» التراثية وقيم الذكاء والتشخيص الدقيق وأثر النفسية في الشفاء، ثم أنشطة بثلاثة مستويات.","page":"lesson-clever-doctor.html","video":"","pdf":"","notes":["«الحِذْق» في اللغة يعني المهارة الفائقة، والذكاء، وسرعة الفهم وإتقان الصنعة.","تروي قصة «حذق طبيب» موقفًا تراثيًا لطيفًا لطبيبٍ ذكيٍّ استطاع تشخيص حالة مريضٍ عجز عنه غيره.","اعتمد الطبيب على قوة الملاحظة وفهم نفسية المريض، وليس على الأدوية التقليدية وحدها.","تؤكّد القصة العلاقة الوثيقة بين الحالة النفسية والحالة الجسدية في الطب العربي الإسلامي القديم.","تتوافر في القصة عناصر السرد المشوّق: البداية، والعقدة (حيرة الأطباء)، والحل الذكي المدهش.","من العبر المستفادة: التفكير الإبداعي والملاحظة الدقيقة يحلّان أعقد المشكلات."],"exercises":["ما معنى كلمة «حِذْق» في عنوان القصة؟","كيف نجح الطبيب في علاج المريض حين عجز غيره؟","ما العلاقة بين هذا النص وبين ما درسناه في درس «الرازي»؟"],"levels":{"easy":[{"type":"mcq","q":"ما معنى «حِذْق» في قولنا «حذق طبيب»؟","options":["البراعة والمهارة والفطنة","الكسل","الغضب","النسيان"],"answer":0,"why":"الحذق يدل على الإتقان التام والذكاء في الصنعة."},{"type":"mcq","q":"ما الخطوة التي أتقنها الطبيب قبل تقديم العلاج؟","options":["التشخيص الدقيق والملاحظة الهادئة","التسرّع في وصف الدواء","مغادرة المريض","تجاهل كلام المريض"],"answer":0,"why":"التشخيص الصحيح نصف العلاج."},{"type":"mcq","q":"على أي جانبٍ ركّز الطبيب إلى جانب العلاج الجسدي؟","options":["الجانب النفسي للمريض","جمع المال","السفر","الشعر"],"answer":0,"why":"أدرك أن الوهم أو الحالة النفسية مفتاح شفاء المريض."},{"type":"mcq","q":"إلى أي فن أدبي ينتمي نص «حذق طبيب»؟","options":["القصة التراثية القصيرة","القصيدة العمودية","المعجم المختص","الخطبة الحربية"],"answer":0,"why":"قصة تراثية موجزة مكتملة العناصر."}],"medium":[{"type":"mcq","q":"لماذا عجز غيره من الأطباء عن علاج المريض في البداية؟","options":["لأنهم اكتفوا بالأدوية التقليدية دون فهم السبب النفسي","لأنهم لم يزوروا المريض","لأن المريض رفض الحديث","لأن الدواء مفقود"],"answer":0,"why":"الطبيب الحاذق نظر لما وراء الأعراض الظاهرة."},{"type":"tfr","q":"تؤكّد قصة «حذق طبيب» العلاقة الوثيقة بين الحالة النفسية وصحة الجسد.","answer":true,"reasons":["لأن تحسّن نفسية المريض وزوال الوهم قاد إلى شفائه التام","لأن النفسية لا تؤثر في الجسد","لأن القصة تتحدث عن السفر"],"reason":0},{"type":"essay","q":"ما الرابط بين درس «الرازي» وقصة «حذق طبيب» في الوحدة الثامنة؟","model":"كلاهما يبرز عراقة الطب العربي الإسلامي، واعتماده على الملاحظة الدقيقة، والذكاء في التشخيص، والاهتمام بالجانب النفسي والإنساني للمريض."},{"type":"tfr","q":"تخلو قصة «حذق طبيب» من عنصرَي العقدة والحل.","answer":false,"reasons":["لأن فيها عقدة واضحة (عجز الأطباء عن علاج المريض) وحلًّا ذكيًا مدهشًا من الطبيب الحاذق","لأنها ليست قصة","لأنها مجرد تعداد"],"reason":0},{"type":"mcq","q":"ما المهارة الحياتية التي يرسّخها هذا النص في أذهان الطلاب؟","options":["التفكير الإبداعي والملاحظة الدقيقة لحلّ المشكلات","الاستسلام عند أول عقبة","التسرّع في الحكم","إهمال التفاصيل"],"answer":0,"why":"التفكير خارج الصندوق والملاحظة يحلّان المشكلات الصعبة."},{"type":"essay","q":"اشرح العبارة: «التشخيص الصحيح هو نصف العلاج».","model":"لأن معرفة السبب الحقيقي للمشكلة أو المرض توجّه الطبيب نحو العلاج المناسب مباشرة بدل التجربة العشوائية غير المفيدة."},{"type":"tfr","q":"الطبيب الماهر لا يكتفي بحفظ الكتب بل يضيف إليها الفطنة وحسن الاستماع للمريض.","answer":true,"reasons":["لأن كل مريض له ظروفه ونفسيته التي تكشفها الملاحظة والإنصات","لأن الكتب لا تفيد الطبيب","لأن الإنصات يضيّع الوقت"],"reason":0}],"hard":[{"type":"mcq","q":"ما الأثر الأدبي للنهاية الذكية في قصة «حذق طبيب»؟","options":["إدهاش القارئ وترسيخ قيمة الفطنة والعلم في ذهنه","إصابة القارئ بالملل","تشتيت الفكرة","إخفاء المغزى"],"answer":0,"why":"الحل الذكي يمنح القصة متعة وإقناعًا."},{"type":"essay","q":"كيف تطبّق مبدأ «التشخيص قبل العلاج» إذا واجهتَ صعوبةً في مادة دراسية؟","model":"أحدّد أولًا سبب الصعوبة بدقة (هل هو نقص في الأساسيات، أم قلة التدريب، أم تشتّت أثناء المذاكرة؟) ثم أضع خطةً مناسبة تعالج السبب مباشرة."},{"type":"tfr","q":"استخدم الأطباء العرب المسلمون العلاج النفسي والإيحاء الإيجابي قبل قرون من الطب النفسي الحديث.","answer":true,"reasons":["كما تثبت قصص التراث الطبي وممارسات الرازي وابن سينا","لأنهم لم يعرفوا أثر النفسية","لأنهم منعوا الحديث مع المريض"],"reason":0},{"type":"mcq","q":"ما السمة الأسلوبية التي تجعل القصص التراثية القصيرة مثل «حذق طبيب» ممتعةً حتى اليوم؟","options":["الإيجاز، والتركيز على الموقف الذكي، ووضوح العبرة","الإطالة المملة","الغموض","كثرة الشخصيات"],"answer":0,"why":"التكثيف وذكاء الموقف يمنحان القصة خلودًا وجاذبية."},{"type":"essay","q":"استخرج من القصة ثلاث صفاتٍ يجب أن يتحلّى بها الطبيب الناجح.","model":"١) العلم الواسع والخبرة. ٢) قوة الملاحظة والفطنة في التشخيص. ٣) اللطف والرحمة وفهم نفسية المريض."},{"type":"tfr","q":"الحوار القصير داخل القصة التراثية يسهم في كشف ذكاء الطبيب وحكمته.","answer":true,"reasons":["لأنه ينقل طريقة إقناع الطبيب للمريض بأسلوب حيّ ومباشر","لأن الحوار يضعف القصة","لأن القصة تخلو من الحوار"],"reason":0},{"type":"mcq","q":"أيُّ وصفٍ يليق بعبارة «حذق طبيب»؟","options":["تركيب إضافي نكرة يفيد التعظيم والإشادة بمهارته","جملة فعلية","أسلوب نهي","أسلوب استفهام"],"answer":0,"why":"تنكير «طبيب» يوسّع الإشادة بمهارة الأطباء الحاذقين."},{"type":"essay","q":"لخّص قصة «حذق طبيب» وعبرتها في سطرين بأسلوبك.","model":"استطاع طبيبٌ حاذقٌ بقوة ملاحظته وفهمه لنفسية المريض أن يشخّص علّته ويعالجها بحيلةٍ علميةٍ ذكيةٍ عجز عنها غيره؛ مما يثبت أن الفطنة والتفكير الإبداعي مفتاح حلّ أعقد المشكلات."},{"type":"tfr","q":"وُضع نص «حذق طبيب» في قسم «اقرأ واستمتع» لتنمية حب القراءة الحرة وتذوّق طرائف التراث.","answer":true,"reasons":["لأنه يجمع بين المتعة القصصية والفائدة العلمية واللغوية","لأنه للحفظ الإجباري فقط","لأنه نص نحوي"],"reason":0},{"type":"essay","q":"اكتب عنوانًا بديلًا مشوّقًا لقصة «حذق طبيب» وعلّل اختيارك.","model":"مثال: «الدواء الذي لم يكن في الزجاجة»؛ لأنه يثير فضول القارئ ويشير إلى ذكاء الطبيب وعلاجه النفسي دون كشف تفاصيل الحل."}]}},
  {"id":"g9-arabic-2-u1-1","grade":"g9","subject":"arabic","term":2,"unit":1,"no":1,"title":"القراءة: من وحي الخريف في صلالة","summary":"شرح متحرك بـ SVG لدرس القراءة: من وحي الخريف في صلالة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-khareef-salalah.html","video":"","pdf":"","notes":["يمزج النص بين وصف خريف صلالة (الرذاذ والضباب والخضرة والعيون) وجمال التصوير الأدبي.","التشخيص وتوظيف الحواس الخمس سرّ حيوية النص الوصفي.","عاطفة النص هي الإعجاب بجمال الطبيعة والاعتزاز بالوطن."],"exercises":["اذكر ثلاث سمات طبيعية تميّز خريف صلالة كما وردت في النص.","اشرح جمال التصوير في عبارة: «تلفّ السحب قمم الجبال بوشاح أبيض».","كيف وظّف الكاتب الحواس في نقل أجواء الخريف؟ أعطِ مثالين."],"levels":{"easy":[{"type":"mcq","q":"ما المقصود بـ«الرذاذ» في وصف خريف صلالة؟","options":["المطر الخفيف الناعم المستمر","الرياح الرملية الحارة","الثلوج الكثيفة","العواصف الرعدية الشديدة"],"answer":0,"why":"الرذاذ هو المطر الخفيف الذي يميّز خريف ظفار."},{"type":"mcq","q":"ما اللون الغالب الذي يرسمه النص لجبال صلالة في الخريف؟","options":["الأصفر الصحراوي","الأخضر المكسو بالضباب الأبيض","الأسود الداكن","الرمادي القاحل"],"answer":1,"why":"تكتسي الجبال بساطًا أخضر يلفّه الضباب الأبيض."},{"type":"mcq","q":"قول الكاتب «تكتسي الجبال حُلّةً خضراء» يُعدّ صورةً فنيةً تقوم على:","options":["السجع الصوتي فقط","المقابلة اللفظية","التشخيص والاستعارة","الترادف"],"answer":2,"why":"شُبّهت الجبال بإنسان يرتدي ثوبًا أخضر."},{"type":"mcq","q":"ما الحاسة التي يستثيرها وصف «خرير العيون المائية»؟","options":["الشم","التذوق","اللمس","السمع"],"answer":3,"why":"الخرير هو صوت جريان الماء."}],"medium":[{"type":"mcq","q":"ما العاطفة الرئيسة المسيطرة على نص «من وحي الخريف في صلالة»؟","options":["الإعجاب بجمال الطبيعة والاعتزاز بالوطن","الحزن واليأس","الغضب والعتاب","الخوف والتردد"],"answer":0,"why":"النص يحتفي بروعة الخريف وجمال عُمان."},{"type":"mcq","q":"ما معنى كلمة «وحي» في عنوان الدرس؟","options":["السرعة الفائقة","الإلهام والأثر النفسي الجميل","الابتعاد والهجر","الصوت المرتفع"],"answer":1,"why":"الوحي هنا ما يُلهمه المنظر الطبيعي للأديب."},{"type":"mcq","q":"أي مما يأتي من العيون المائية الشهيرة في محافظة ظفار؟","options":["بحيرة قارون","نهر النيل","عين رزات وعين حمران","شلالات نياجرا"],"answer":2,"why":"رزات وحمران وصحلنوت من أشهر عيون صلالة."},{"type":"tfr","q":"يعتمد النص الوصفي الناجح على حاسة البصر وحدها دون بقية الحواس.","answer":false,"reasons":["بل يدمج البصر والسمع واللمس والشم ليكون الوصف حيًّا","نعم البصر وحده يكفي","يعتمد على السمع فقط"],"reason":0},{"type":"tfr","q":"التشخيص في الوصف الأدبي يمنح عناصر الطبيعة حركةً وحياةً تشدّ القارئ.","answer":true,"reasons":["يجعل النص جافًا","مثل جعل الجبال تكتسي والنسائم تداعب الوجوه","يُمنع في النثر"],"reason":1},{"type":"essay","q":"اذكر ثلاث سمات طبيعية تميّز خريف صلالة كما وردت في النص.","model":"١) تساقط الرذاذ وانتشار الضباب. ٢) اكتساء الجبال والسهول بالخضرة الكثيفة. ٣) تدفق العيون المائية واعتدال الطقس."},{"type":"essay","q":"اشرح جمال التصوير في عبارة: «تلفّ السحب قمم الجبال بوشاح أبيض».","model":"شبّه الكاتب السحب والضباب بوشاح أبيض يلتف حول قمم الجبال، مما يبرز جمال المشهد ورقته ويوحي بالدفء والألفة."}],"hard":[{"type":"mcq","q":"ما نوع النص «من وحي الخريف في صلالة»؟","options":["قصيدة عمودية","مسرحية هزلية","تقرير مالي","نص نثري وصفي أدبي"],"answer":3,"why":"هو مقالة نثرية وصفية أدبية."},{"type":"mcq","q":"ما فائدة توظيف الحواس المتعددة في النص الوصفي؟","options":["جعل القارئ يعيش المشهد كأنه حاضر فيه","إطالة النص بلا فائدة","إخفاء الفكرة الرئيسة","تقليل وضوح المعنى"],"answer":0,"why":"الحواس تحوّل الكلمات إلى تجربة حسية حيّة."},{"type":"mcq","q":"ما علاقة عنوان النص بمضمونه؟","options":["عنوان غامض لا صلة له بالنص","عنوان موحٍ يلخّص مصدر إلهام الكاتب في وصف الخريف","عنوان علمي بحت","عنوان يعارض المضمون"],"answer":1,"why":"العنوان يمهّد لجو الإلهام والوصف الطبيعي."},{"type":"mcq","q":"أي الأسلوبين يغلب على نقل المشاهد والحقائق في النص الوصفي؟","options":["أسلوب النهي فقط","أسلوب الأمر فقط","الأسلوب الخبري","أسلوب القسم فقط"],"answer":2,"why":"الأسلوب الخبري هو الأساس في الوصف والتقرير."},{"type":"tfr","q":"موسم الخريف في صلالة يوافق أشهر الصيف فلكيًا ويتميّز بالرذاذ واعتدال الجو.","answer":true,"reasons":["يتميّز بالجفاف الشديد","يحدث في الشتاء فقط","وهو ما يجعل ظفار وجهةً سياحيةً فريدةً في المنطقة"],"reason":2},{"type":"tfr","q":"النص الأدبي الوصفي يخلو تمامًا من الصور الفنية والتشبيهات.","answer":false,"reasons":["بل تقوم جماليته على التشبيهات والاستعارات والألفاظ الموحية","نعم يخلو منها","تقتصر على الشعر فقط"],"reason":0},{"type":"tfr","q":"يُعدّ تنظيم الوصف من العام إلى الخاص سمةً فنيةً تزيد النص وضوحًا.","answer":true,"reasons":["العشوائية أفضل في الوصف","حيث يبدأ بالمشهد الكلي ثم ينتقل للتفاصيل الدقيقة","يجب البدء بالخاتمة"],"reason":1},{"type":"essay","q":"كيف وظّف الكاتب الحواس في نقل أجواء الخريف؟ أعطِ مثالين.","model":"حاسة البصر في وصف الخضرة والضباب، وحاسة السمع في خرير المياه، وحاسة اللمس في برودة الرذاذ."},{"type":"essay","q":"ما الأثر السياحي والاقتصادي لموسم الخريف في محافظة ظفار؟","model":"يجذب آلاف الزوار من داخل عُمان وخارجها، فينشّط السياحة والتجارة والتعريف بالتراث العُماني."},{"type":"essay","q":"اكتب ثلاث جمل وصفية من إنشائك تصف فيها منظرًا طبيعيًا زرتَه في سلطنة عُمان.","model":"وقفتُ على شاطئ القرم وقت الغروب، فإذا بأمواج البحر تتلألأ بلون الذهب، والنسيم العليل يداعب الوجوه بينما تحلّق النوارس فوق الأفق الهادئ."}]}},
  {"id":"g9-arabic-2-u1-2","grade":"g9","subject":"arabic","term":2,"unit":1,"no":2,"title":"الأنشطة النحوية والصرفية: تطبيقات على ما سبقت دراسته","summary":"شرح متحرك بـ SVG لدرس الأنشطة النحوية والصرفية: تطبيقات على ما سبقت دراسته (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-arabic-t2-u1-grammar-review.html","video":"","pdf":"","notes":["كان وأخواتها: ترفع الاسم وتنصب الخبر | إنّ وأخواتها: تنصب الاسم وترفع الخبر.","المفعول المطلق من لفظ الفعل، والمفعول لأجله يبيّن سبب الفعل.","لتحديد المجرد والمزيد ردّ الفعل إلى الماضي المفرد المذكر (هو) أولًا."],"exercises":["أدخل «كان» مرة و«إنّ» مرة أخرى على الجملة: «الطالبان مجتهدان» مع ضبط التغيير.","أعرب ما تحته خط: «اجتهدَ العُمانيونَ اجتهادًا عظيمًا رغبةً في بناء الوطن» (اجتهادًا، رغبةً).","زِن الكلمات الآتية صرفيًا: استخرجَ، انكسرَ، قِفْ، مكاتب."],"levels":{"easy":[{"type":"mcq","q":"في جملة «إنّ المعلمينَ مخلصونَ»، ما إعراب كلمة «المعلمين»؟","options":["مبتدأ مرفوع بالواو","اسم إنّ منصوب وعلامة نصبه الياء","خبر إنّ مرفوع","فاعل مرفوع"],"answer":1,"why":"إنّ تنصب اسمها، وجمع المذكر السالم يُنصب بالياء."},{"type":"mcq","q":"ما نوع المفعول في كلمة «حرصًا» في جملة: «أقرأُ الكتبَ حرصًا على العلم»؟","options":["مفعول به ثانٍ","مفعول مطلق","مفعول لأجله","مفعول فيه"],"answer":2,"why":"تبيّن سبب القراءة (جواب: لماذا أقرأ؟)."},{"type":"mcq","q":"ما علامة نصب جمع المؤنث السالم في جملة: «شجّع المعلمُ الطالباتِ»؟","options":["الألف","الفتحة الظاهرة","الياء","الكسرة نيابةً عن الفتحة"],"answer":3,"why":"جمع المؤنث السالم يُنصب بالكسرة."},{"type":"mcq","q":"ما الوزن الصرفي للفعل «استغفرَ»؟","options":["استفعلَ","افتعلَ","انفعلَ","تفعّلَ"],"answer":0,"why":"أصله «غفر» (فعل) وزيدت الألف والسين والتاء."}],"medium":[{"type":"mcq","q":"الفعل «يذهبون» يُصنّف صرفيًا على أنه فعل:","options":["مزيد بحرفين","ثلاثي مجرد (أصله ذهب)","رباعي مجرد","مزيد بثلاثة أحرف"],"answer":1,"why":"ياء المضارعة وواو الجماعة ليست من حروف الزيادة."},{"type":"mcq","q":"في جملة «ظننتُ الامتحانَ سهلًا»، المفعولان أصلهما:","options":["جار ومجرور","ليس أصلهما مبتدأ وخبرًا","مبتدأ وخبر (الامتحانُ سهلٌ)","فعل وفاعل"],"answer":2,"why":"ظنّ وأخواتها تدخل على الجملة الاسمية."},{"type":"mcq","q":"ما نوع المفعول المطلق في: «انتصر الفريقُ انتصارًا باهرًا»؟","options":["مفعول لأجله","مؤكّد للفعل","مبيّن للعدد","مبيّن للنوع"],"answer":3,"why":"وُصف المصدر «انتصارًا» بصفة «باهرًا» فبيّن نوعه."},{"type":"tfr","q":"أحرف المضارعة والضمائر المتصلة تُعدّ من حروف الزيادة عند تصنيف الفعل لمجرد ومزيد.","answer":false,"reasons":["نعم تُعدّ زيادة","لا تُعدّ زيادة؛ نرد الفعل للماضي (هو) أولًا","الضمائر فقط تُعد زيادة"],"reason":1},{"type":"tfr","q":"جمع المؤنث السالم يُنصب وعلامة نصبه الكسرة نيابةً عن الفتحة.","answer":true,"reasons":["يُنصب بالياء","بل يُنصب بالفتحة","مثل: كرّمت المدرسةُ المتفوقاتِ"],"reason":2},{"type":"essay","q":"أدخل «كان» مرة و«إنّ» مرة أخرى على الجملة: «الطالبان مجتهدان» مع ضبط التغيير.","model":"كان الطالبان مجتهدَين. إنّ الطالبَين مجتهدان."},{"type":"essay","q":"أعرب ما تحته خط: «اجتهدَ العُمانيونَ اجتهادًا عظيمًا رغبةً في بناء الوطن» (اجتهادًا، رغبةً).","model":"اجتهادًا: مفعول مطلق منصوب وعلامة نصبه الفتحة. رغبةً: مفعول لأجله منصوب وعلامة نصبه الفتحة."}],"hard":[{"type":"mcq","q":"أي الأفعال الآتية ينصب مفعولين ليس أصلهما مبتدأ وخبرًا؟","options":["منحَ","علمَ","ظنّ","حسبَ"],"answer":0,"why":"منح من أخوات أعطى (لا يصح أن تقول الطالبُ جائزةٌ)."},{"type":"mcq","q":"ما الوزن الصرفي لفعل الأمر «قُلْ»؟","options":["عِلْ","فُلْ","فَعْ","افْعَلْ"],"answer":1,"why":"أصله قال (فعل) وحُذفت عينه (الألف) فبقي فُلْ."},{"type":"mcq","q":"عند دخول «أصبح» على الجملة «المهندسون بارعون» تصبح:","options":["أصبح المهندسينَ بارعينَ","أصبح المهندسينَ بارعونَ","أصبح المهندسونَ بارعينَ","أصبح المهندسونَ بارعونَ"],"answer":2,"why":"أصبح من أخوات كان: ترفع الاسم بالواو وتنصب الخبر بالياء."},{"type":"mcq","q":"تُجمع حروف الزيادة في اللغة العربية في كلمة:","options":["قواعد","أنيتُ","أبجد","سألتمونيها"],"answer":3,"why":"سألتمونيها تجمع حروف الزيادة العشرة."},{"type":"tfr","q":"الفعل «كسا» ينصب مفعولين أصلهما مبتدأ وخبر.","answer":false,"reasons":["بل ليس أصلهما مبتدأ وخبرًا (من أخوات أعطى)","نعم أصلهما مبتدأ وخبر","فعل لازم لا ينصب مفعولًا"],"reason":0},{"type":"tfr","q":"المفعول المطلق يكون مصدرًا مأخوذًا من لفظ الفعل المذكور قبله.","answer":true,"reasons":["لا يشترط أن يكون من لفظ الفعل","مثل: قرأتُ الدرسَ قراءةً متأنيةً","يكون مرفوعًا دائمًا"],"reason":1},{"type":"tfr","q":"عند حذف حرف أصلي من الكلمة يُحذف ما يقابله في الميزان الصرفي.","answer":true,"reasons":["تُحذف الفاء دائمًا","يبقى الميزان كاملًا","مثل: وَصَلَ (فعل) ← صِلْ (عِلْ)"],"reason":2},{"type":"essay","q":"زِن الكلمات الآتية صرفيًا: استخرجَ، انكسرَ، قِفْ، مكاتب.","model":"استخرج: استفعل. انكسر: انفعل. قِفْ: عِلْ. مكاتب: مفاعل."},{"type":"essay","q":"ميّز الفعل المجرد من المزيد في: يلعبون، يتقدّم، دحرجَ، أكرَمَ.","model":"يلعبون (لعب): ثلاثي مجرد. دحرج: رباعي مجرد. يتقدّم (تقدّم): ثلاثي مزيد بحرفين. أكرم: ثلاثي مزيد بحرف (الهمزة)."},{"type":"essay","q":"فرّق بين «رأيتُ العلمَ نورًا» و«أعطيتُ المحتاجَ مالًا» من حيث أصل المفعولين.","model":"في الأولى أصلهما مبتدأ وخبر (العلمُ نورٌ)، وفي الثانية ليس أصلهما مبتدأ وخبرًا (لا يصح: المحتاجُ مالٌ)."}]}},
  {"id":"g9-arabic-2-u1-3","grade":"g9","subject":"arabic","term":2,"unit":1,"no":3,"title":"الأنشطة الإملائية: تطبيقات على الهمزة المتوسطة","summary":"شرح متحرك بـ SVG لدرس الأنشطة الإملائية: تطبيقات على الهمزة المتوسطة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-middle-hamza-applications.html","video":"","pdf":"","notes":["سلم قوة الحركات: الكسرة (ئـ) > الضمة (ؤ) > الفتحة (أ) > السكون.","استثناءان مهمان: مفتوحة بعد ألف أو واو مد ← على السطر (قراءة، مروءة)؛ وبعد ياء ساكنة ← على نبرة (بيئة، هيئة).","انتبه لتغيّر الهمزة مع الضمير حسب الإعراب: أبناؤُنا (رفع)، أبناءَنا (نصب)، أبنائِنا (جر)."],"exercises":["علّل سبب رسم الهمزة المتوسطة في كل كلمة: سُئِل، رَأْس، مُؤْمِن، عَبَاءَة.","وظّف كلمة «شعراؤنا» في ثلاث جمل بحيث تكون مرة مرفوعة ومرة منصوبة ومرة مجرورة مع ضبط الهمزة.","صوّب الأخطاء الإملائية في الجملة: «تفاأل الطّلابُ بالبيأةِ النّظيفةِ وطرحوا أسألةً مفيدةً»."],"levels":{"easy":[{"type":"mcq","q":"ما سبب كتابة الهمزة على واو في كلمة «فُؤَاد»؟","options":["لأنها ساكنة بعد كسر","لأنها مضمومة وما قبلها مفتوح","لأنها مفتوحة وما قبلها مضموم والضمة أقوى من الفتحة","لأن قبلها ألف مد"],"answer":2,"why":"حركة الهمزة فتحة وما قبلها ضمة، والضمة أقوى."},{"type":"mcq","q":"أي الكلمات الآتية كُتبت همزتها المتوسطة كتابةً صحيحةً؟","options":["مُرُوأَة","مُرُؤَة","مُرُئَة","مُرُوءَة"],"answer":3,"why":"همزة مفتوحة بعد واو مد ساكنة تُكتب مفردةً على السطر."},{"type":"mcq","q":"أكمل الجملة بالرسم الإملائي الصحيح: «أحبّ ...... المخلصين»:","options":["أبناءَنا","أبناؤُنا","أبنائِنا","أبنأَنا"],"answer":0,"why":"مفعول به منصوب فتُفتح الهمزة بعد ألف مد وتُكتب على السطر."},{"type":"mcq","q":"لماذا كُتبت الهمزة على نبرة في كلمة «بِيئَة»؟","options":["لأنها مضمومة","لأنها مفتوحة بعد ياء مد ساكنة (تُعامل معاملة الكسرة)","لأنها ساكنة بعد فتح","لأن قبلها ألف"],"answer":1,"why":"الياء الساكنة قبل الهمزة المتوسطة توجب رسمها على نبرة."}],"medium":[{"type":"mcq","q":"أي الكلمات الآتية كُتبت همزتها على ألف لأنها مفتوحة بعد ساكن؟","options":["بِئْر","سُؤَال","مَسْأَلة","قِرَاءَة"],"answer":2,"why":"السين ساكنة والهمزة مفتوحة، والفتحة أقوى من السكون."},{"type":"mcq","q":"أكمل الجملة: «سلّمتُ على ...... الكرام»:","options":["أصدقأِنا","أصدقاؤُنا","أصدقاءَنا","أصدقائِنا"],"answer":3,"why":"اسم مجرور وعلامة جره الكسرة فتُكتب الهمزة على نبرة."},{"type":"mcq","q":"ما ترتيب الحركات من الأقوى إلى الأضعف في قاعدة الهمزة المتوسطة؟","options":["الكسرة ثم الضمة ثم الفتحة ثم السكون","الفتحة ثم الضمة ثم الكسرة ثم السكون","الضمة ثم الكسرة ثم الفتحة ثم السكون","السكون ثم الفتحة ثم الضمة ثم الكسرة"],"answer":0,"why":"الكسرة أقوى الحركات يليها الضمة ثم الفتحة ثم السكون."},{"type":"tfr","q":"الكسرة هي أقوى الحركات وتغلب الضمة والفتحة والسكون دائمًا.","answer":true,"reasons":["الفتحة أقوى الحركات","الضمة أقوى من الكسرة","فأينما وُجدت الكسرة على الهمزة أو قبلها كُتبت على نبرة"],"reason":2},{"type":"tfr","q":"تُكتب كلمة «قراءة» بهمزة على ألف هكذا: «قراأة».","answer":false,"reasons":["تُكتب مفردةً على السطر لأنها مفتوحة بعد ألف مد ساكنة","نعم على ألف","تُكتب على واو"],"reason":0},{"type":"essay","q":"علّل سبب رسم الهمزة المتوسطة في كل كلمة: سُئِل، رَأْس، مُؤْمِن، عَبَاءَة.","model":"سُئِل: مكسورة بعد ضم (الكسرة أقوى ← نبرة). رَأْس: ساكنة بعد فتح (الفتحة أقوى ← ألف). مُؤْمِن: ساكنة بعد ضم (الضمة أقوى ← واو). عَبَاءَة: مفتوحة بعد ألف مد (على السطر)."},{"type":"essay","q":"وظّف كلمة «شعراؤنا» في ثلاث جمل بحيث تكون مرة مرفوعة ومرة منصوبة ومرة مجرورة مع ضبط الهمزة.","model":"رفع: شعراؤُنا مبدعون. نصب: كرّمت الدولةُ شعراءَنا. جر: افتخرتُ بشعرائِنا."}],"hard":[{"type":"mcq","q":"ما سبب رسم الهمزة على السطر في كلمة «تَفَاءَل»؟","options":["لأنها مضمومة بعد ألف","لأنها مفتوحة بعد ألف مدّ ساكنة","لأنها ساكنة بعد فتح","لأنها مكسورة"],"answer":1,"why":"المفتوحة بعد ألف مد تُفرد على السطر."},{"type":"mcq","q":"أكمل الجملة: «...... هم أمل الوطن»:","options":["أبنائِنا","أبناءَنا","أبناؤُنا","أبناأُنا"],"answer":2,"why":"مبتدأ مرفوع فتُضم الهمزة وتُكتب على واو."},{"type":"mcq","q":"كلمة «يَئِسَ» رُسمت همزتها على نبرة لأنها:","options":["مضمومة بعد كسر","ساكنة وما قبلها مكسور","مفتوحة بعد ياء","مكسورة وما قبلها مفتوح والكسرة أقوى"],"answer":3,"why":"الكسرة أقوى من الفتحة فتُكتب على نبرة."},{"type":"mcq","q":"أي جملة من الآتي تخلو من أي خطأ إملائي؟","options":["سُئِل المؤمنُ عن مسألةٍ فبادرَ بالقراءةِ","سُؤِل المؤمنُ عن مسءلةٍ فبادرَ بالقراأةِ","سُئِل المأمنُ عن مسألةٍ فبادرَ بالقراءةِ","سُئِل المؤمنُ عن مسألةٍ فبادرَ بالقرائةِ"],"answer":0,"why":"سُئِل، المؤمن، مسألة، القراءة كلها مضبوطة وفق القاعدة."},{"type":"tfr","q":"تتغير كتابة همزة «علماؤنا» عند دخول حرف الجر لتصبح «علمائنا».","answer":true,"reasons":["تبقى على واو دائمًا","لأنها تصبح مجرورة ومكسورة فتُكتب على نبرة","تُكتب على السطر"],"reason":1},{"type":"tfr","q":"تُكتب الهمزة في كلمة «هَيْئَة» على نبرة لأنها سبقت بياء ساكنة.","answer":true,"reasons":["تُكتب على ألف","لأنها مضمومة","فالياء الساكنة تُعد بقوة الكسرة"],"reason":2},{"type":"tfr","q":"في كلمة «مُؤْمِن» كُتبت الهمزة على واو لأنها مضمومة بعد ساكن.","answer":false,"reasons":["بل لأنها ساكنة وما قبلها مضموم والضمة أقوى من السكون","نعم مضمومة بعد ساكن","لأن قبلها كسرة"],"reason":0},{"type":"essay","q":"صوّب الأخطاء الإملائية في الجملة: «تفاأل الطّلابُ بالبيأةِ النّظيفةِ وطرحوا أسألةً مفيدةً».","model":"الصواب: تفاءَل الطّلابُ بالبيئةِ النّظيفةِ وطرحوا أسئلةً مفيدةً."},{"type":"essay","q":"متى تُكتب الهمزة المتوسطة مفردةً على السطر؟ اذكر الحالتين مع مثال لكل حالة.","model":"١) إذا كانت مفتوحةً بعد ألف مد ساكنة (قراءة، تفاءل). ٢) إذا كانت مفتوحةً بعد واو مد ساكنة (مروءة، نبوءة)."},{"type":"essay","q":"اشرح لزميلك كيف يفرّق بين كتابة «مَسْأَلة» و«مَسْؤُول» باستخدام سلم قوة الحركات.","model":"في «مَسْأَلة» الهمزة مفتوحة بعد ساكن فتغلب الفتحة (ألف)؛ وفي «مَسْؤُول» الهمزة مضمومة بعد ساكن فتغلب الضمة (واو)."}]}},
  {"id":"g9-arabic-2-u1-4","grade":"g9","subject":"arabic","term":2,"unit":1,"no":4,"title":"التعبير: وصف منظر طبيعي","summary":"شرح متحرك بـ SVG لدرس التعبير: وصف منظر طبيعي (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-describing-landscape.html","video":"","pdf":"","notes":["خطّط للوصف: مكان وزمان ← زاوية منظمة (عام إلى خاص) ← حواس متعددة ← صور فنية ← خاتمة وجدانية.","الأفعال المضارعة والتشبيهات تبعث الحياة في المشهد، وتجنّب تكرار الصفات العامة.","قسّم نصك إلى فقرات واضبط علامات الترقيم والإملاء."],"exercises":["ضع مخططًا من ٣ أجزاء (مقدمة، عرض، خاتمة) لوصف منظر «شاطئ البحر وقت الغروب».","حوّل الجملة الجافة الآتية إلى وصف أدبي حي: «في القرية أشجار نخيل وماء جارٍ وعصافير».","اذكر أربع حواس يمكن توظيفها في وصف وادٍ عُماني مع مثال قصير لكل حاسة."],"levels":{"easy":[{"type":"mcq","q":"ما أول خطوة أساسية عند التخطيط لكتابة وصف منظر طبيعي؟","options":["نقل نص محفوظ لا علاقة له بالمكان","كتابة الخاتمة أولًا","تكرار كلمة جميل كثيرًا","تحديد المكان والزمان وزاوية الوصف"],"answer":3,"why":"تحديد الزمان والمكان وزاوية الوصف يضبط هيكل الموضوع."},{"type":"mcq","q":"ما فائدة استخدام الأفعال المضارعة مثل «تتمايل، تتدفق، تغرّد» في النص الوصفي؟","options":["إضفاء الحركة والحيوية والاستمرارية على المشهد","إلغاء الوصف البصري","جعل النص جامدًا","تقصير الجمل بلا معنى"],"answer":0,"why":"الفعل المضارع يدل على التجدد والاستمرار والحركة."},{"type":"mcq","q":"أي العبارات الآتية تمثّل وصفًا أدبيًا حيًّا وليس إخبارًا جافًا؟","options":["يوجد ماء ونخيل في المزرعة","تنساب مياه الفلج الصافية فتغسل جذور النخيل وتهمس بالحياة","المزرعة كبيرة جدًا","الماء بارد فقط"],"answer":1,"why":"توظّف الحركة والصورة الفنية والتشخيص."},{"type":"mcq","q":"ما العنصر المناسب لخاتمة موضوع وصف منظر طبيعي؟","options":["فتح موضوع جديد مختلف تمامًا","ذكر تعريف القواعد النحوية","بيان الأثر النفسي والتأمل في بديع صنع الله","سرد قائمة أسعار"],"answer":2,"why":"الخاتمة تلخّص الأثر الوجداني للمنظر في نفس الكاتب."}],"medium":[{"type":"mcq","q":"أي ترتيب يُعدّ الأنسب لتنظيم تفاصيل المنظر الطبيعي؟","options":["البدء بالتفاصيل دون ذكر المكان","الانتقال العشوائي بين التفاصيل","وصف عنصر واحد وتكراره عشر مرات","من المشهد العام إلى التفاصيل الدقيقة (أو من البعيد للقريب)"],"answer":3,"why":"التدرج المكاني يمنع التشتت ويساعد القارئ على التخيل."},{"type":"mcq","q":"عبارة «عبق الورد الجبلي يملأ الأرجاء» تخاطب حاسة:","options":["الشم","السمع","التذوق","البصر"],"answer":0,"why":"العبق هو الرائحة الطيبة."},{"type":"mcq","q":"ما العيب الأسلوبي الذي يجب تجنبه في كتابة الوصف الطبيعي؟","options":["استخدام علامات الترقيم","تكرار الصفات العامة مثل (جميل جدًا، رائع جدًا) دون تفاصيل حسية","توظيف التشبيه","تقسيم النص إلى فقرات"],"answer":1,"why":"الوصف القوي يُري القارئ الجمال بالتفاصيل لا بمجرد كلمة «جميل»."},{"type":"tfr","q":"يُفضّل في وصف المنظر الطبيعي الانتقال العشوائي بين التفاصيل دون ترتيب مكاني.","answer":false,"reasons":["بل يجب تنظيم زاوية الوصف (من العام للخاص أو من البعيد للقريب)","نعم العشوائية أجمل","الترتيب خاص بالتقارير فقط"],"reason":0},{"type":"tfr","q":"الأفعال المضارعة والصور الفنية تمنح النص الوصفي حركةً وجمالًا.","answer":true,"reasons":["تُضعف النص الوصفي","لأنها تنقل التجدد والحياة في عناصر الطبيعة","يُمنع استخدام التشبيه في التعبير"],"reason":1},{"type":"essay","q":"ضع مخططًا من ٣ أجزاء (مقدمة، عرض، خاتمة) لوصف منظر «شاطئ البحر وقت الغروب».","model":"المقدمة: تحديد الزمان والمكان والانطباع الأول. العرض: وصف قرص الشمس وألوان السماء (بصر)، صوت الأمواج (سمع)، نسمة البحر (لمس)، وحركة القوارب. الخاتمة: الشعور بالسكينة وشكر الله."},{"type":"essay","q":"حوّل الجملة الجافة الآتية إلى وصف أدبي حي: «في القرية أشجار نخيل وماء جارٍ وعصافير».","model":"تتمايل سعف النخيل الباسقة فوق ماء الفلج الرقراق، بينما تعزف العصافير فوق الأغصان ألحان الصباح العذبة."}],"hard":[{"type":"mcq","q":"أي علامات الترقيم تناسب نهاية جملة: «ما أروع منظر الشروق على شاطئ صور»؟","options":["الفاصلة المنقوطة (؛)","علامة الاستفهام (؟)","علامة التعجب (!)","النقطتان الرأسيتان (:)"],"answer":2,"why":"أسلوب التعجب يُختم بعلامة التعجب (!)."},{"type":"mcq","q":"ماذا نعني بـ«الربط بين المشهد الخارجي والمشاعر الداخلية»؟","options":["تجاهل المكان تمامًا","وصف المشاعر دون ذكر الطبيعة","وصف الطبيعة بلا أي شعور","إظهار كيف انعكس جمال الطبيعة سعادةً وسكينةً في نفس الكاتب"],"answer":3,"why":"الوصف الوجداني يمزج الخارجي بالداخلي."},{"type":"mcq","q":"يتكوّن موضوع التعبير الوصفي المنظم من:","options":["مقدمة وعرض (فقرتان أو أكثر) وخاتمة","جملة واحدة طويلة بلا نقاط","عناوين فقط","أسئلة وأجوبة فقط"],"answer":0,"why":"التقسيم إلى مقدمة وعرض وخاتمة أساس التنظيم."},{"type":"mcq","q":"أي جملة توظّف حاسة اللمس في وصف الطبيعة؟","options":["كان لون السماء أزرق","داعبت وجوهَنا نسمةٌ باردةٌ محمّلةٌ برذاذ الخريف","سمعنا صوت العصافير","شاهدنا القوارب من بعيد"],"answer":1,"why":"الشعور ببرودة النسيم والرذاذ يخاطب حاسة اللمس."},{"type":"tfr","q":"الخاتمة المناسبة للوصف الطبيعي تُعبّر عن الأثر النفسي للمنظر والتأمل في قدرة الخالق.","answer":true,"reasons":["تعيد كتابة المقدمة حرفيًا","تقتصر على كلمة انتهى","وهي تربط بين جمال المشهد وشعور الكاتب"],"reason":2},{"type":"tfr","q":"تكرار كلمة «جميل» في كل جملة دليل على قوة الأسلوب الوصفي.","answer":false,"reasons":["بل يُضعف الأسلوب؛ الأفضل استبدالها بتفاصيل حسية وصور موحية","نعم دليل قوة","لا بد من تكرارها"],"reason":0},{"type":"tfr","q":"تقسيم الموضوع إلى فقرات ووضع علامات الترقيم جزء أساسي من جودة التعبير.","answer":true,"reasons":["لا أهمية للفقرات","لأنه ينظم الأفكار ويسهّل القراءة والفهم","علامات الترقيم للاملاء فقط"],"reason":1},{"type":"essay","q":"اذكر أربع حواس يمكن توظيفها في وصف وادٍ عُماني مع مثال قصير لكل حاسة.","model":"البصر: صفاء المياه الزرقاء. السمع: خرير الماء. اللمس: برودة الماء والنسيم. الشم: رائحة الأعشاب والتربة الندية."},{"type":"essay","q":"ما الفرق بين «الوصف العلمي» و«الوصف الأدبي» لمنظر طبيعي؟","model":"العلمي ينقل حقائق وأرقامًا موضوعية بلا عاطفة (مثل ارتفاع الجبل ودرجة الحرارة)، أما الأدبي فيمزج المشهد بالمشاعر والصور الفنية والألفاظ الموحية."},{"type":"essay","q":"اكتب فقرة من ٤ أسطر تصف فيها حديقةً أو مزرعةً في الصباح الباكر.","model":"مع أول خيوط الفجر، استيقظت المزرعة على نسماتٍ باردةٍ تحمل عبق الليمون والياسمين. كانت قطرات الندى تتلألأ كحبات اللؤلؤ فوق الأوراق الخضراء، بينما ينساب ماء الفلج هادئًا يبعث في النفس سكينةً وصفاءً لا يوصفان."}]}},
  {"id":"g9-arabic-2-u1-5","grade":"g9","subject":"arabic","term":2,"unit":1,"no":5,"title":"في المعجم: معجم المعاني","summary":"شرح متحرك بـ SVG لدرس في المعجم: معجم المعاني (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-thesaurus-maani.html","video":"","pdf":"","notes":["معجم الألفاظ: هجائي (من اللفظ إلى المعنى) | معجم المعاني: موضوعي (من المعنى إلى اللفظ).","أشهر معاجم المعاني: «فقه اللغة» للثعالبي، و«المخصص» لابن سيده.","يُستخدم معجم المعاني لاختيار أدق لفظ يعبّر عن درجات المعنى في الكتابة والتعبير."],"exercises":["قارن بين «معجم الألفاظ» و«معجم المعاني» من حيث: أساس الترتيب، اتجاه البحث، ومثال واحد لكل منهما.","اشرح خطوات البحث عن لفظ مناسب لـ«شدة الحرّ وقت الظهيرة» في معجم المعاني.","اذكر ثلاثة أمثلة للألفاظ الدقيقة للأصوات الطبيعية التي تجمعها معاجم المعاني."],"levels":{"easy":[{"type":"mcq","q":"ما الأساس الذي تُرتَّب عليه الكلمات في «معجم المعاني»؟","options":["الموضوعات والأبواب الدلالية","الحرف الأول الهجائي فقط","الحرف الأخير (القافية)","عدد حروف الكلمة"],"answer":0,"why":"معجم المعاني يجمع الكلمات حسب معانيها وموضوعاتها."},{"type":"mcq","q":"مؤلف كتاب «فقه اللغة وسرّ العربية» هو:","options":["ابن منظور","أبو منصور الثعالبي","سيبويه","المتنبي"],"answer":1,"why":"الثعالبي هو مؤلف «فقه اللغة» أشهر معاجم المعاني."},{"type":"mcq","q":"متى يلجأ الكاتب إلى «معجم المعاني»؟","options":["عندما يجهل نطق كلمة أجنبية","عندما يريد معرفة وزن كلمة صرفي فقط","عندما يكون في ذهنه معنى ويريد اللفظ العربي الأدقّ له","لحساب عدد صفحات الكتاب"],"answer":2,"why":"معجم المعاني ينطلق من المعنى إلى اللفظ."},{"type":"mcq","q":"أي المعاجم الآتية يُعدّ من «معاجم المعاني»؟","options":["المعجم الوسيط","لسان العرب لابن منظور","القاموس المحيط للفيروزآبادي","المُخصَّص لابن سيده"],"answer":3,"why":"المخصص وفقه اللغة من معاجم المعاني، أما الباقي فمعاجم ألفاظ."}],"medium":[{"type":"mcq","q":"أي لفظ يُطلق على «صوت أوراق الشجر» عند تحركها بالرياح؟","options":["حفيف","خرير","زئير","صهيل"],"answer":0,"why":"الحفيف صوت الشجر، والخرير صوت الماء."},{"type":"mcq","q":"ما الفرق الجوهري بين «معجم الألفاظ» و«معجم المعاني»؟","options":["لا يوجد أي فرق بينهما","الألفاظ: من الكلمة للمعنى (هجائيًا)، والمعاني: من المعنى للكلمة (موضوعيًا)","معجم المعاني للأفعال فقط","معجم الألفاظ للشعر فقط"],"answer":1,"why":"يختلفان في اتجاه البحث وطريقة الترتيب."},{"type":"mcq","q":"للوصول سريعًا إلى لفظ في معجم المعاني نستخدم أولًا:","options":["الصفحة الأخيرة فقط","البحث بالجذر الثلاثي هجائيًا","فهرس الأبواب والموضوعات","الترتيب حسب القافية"],"answer":2,"why":"الفهرس الموضوعي يهديك إلى الباب المطلوب."},{"type":"tfr","q":"معجم المعاني يُرتّب الكلمات حسب الحروف الهجائية من الألف إلى الياء.","answer":false,"reasons":["نعم هجائيًا","بل يُرتّب حسب الموضوعات والأبواب الدلالية","يرتّب حسب الحرف الأخير"],"reason":1},{"type":"tfr","q":"يُعدّ كتاب «فقه اللغة» للثعالبي من أشهر معاجم المعاني في العربية.","answer":true,"reasons":["هو ديوان شعر","هو من معاجم الألفاظ الهجائية","حيث قسّم فيه الألفاظ إلى أبواب وفصول موضوعية دقيقة"],"reason":2},{"type":"essay","q":"قارن بين «معجم الألفاظ» و«معجم المعاني» من حيث: أساس الترتيب، اتجاه البحث، ومثال واحد لكل منهما.","model":"معجم الألفاظ: مرتّب هجائيًا، من اللفظ إلى المعنى، مثل المعجم الوسيط ولسان العرب. معجم المعاني: مرتّب موضوعيًا في أبواب، من المعنى إلى اللفظ، مثل فقه اللغة للثعالبي والمخصص لابن سيده."},{"type":"essay","q":"اشرح خطوات البحث عن لفظ مناسب لـ«شدة الحرّ وقت الظهيرة» في معجم المعاني.","model":"١) أحدد الموضوع العام (الزمن أو الحرّ والطقس). ٢) أفتح فهرس الأبواب لأجد باب الأوقات أو الحرّ. ٣) أقرأ الفصل فأجد اللفظ الدقيق مثل «الهاجرة»."}],"hard":[{"type":"mcq","q":"أي الكلمات الآتية تدل على «المطر شديد القَطْر العظيم»؟","options":["الندى","الطلّ","الرذاذ","الوابل"],"answer":3,"why":"الطلّ والرذاذ خفيفان، أما الوابل فالمطر الغزير عظيم القطر."},{"type":"mcq","q":"ما الكلمة الدقيقة لصوت جريان الماء في الفلج أو النهر؟","options":["خرير","حفيف","هزيم","طنين"],"answer":0,"why":"الخرير هو صوت جريان الماء."},{"type":"mcq","q":"ما الفائدة الكبرى لمعجم المعاني عند كتابة موضوع التعبير؟","options":["تقليل عدد الجمل","إثراء الثروة اللغوية واختيار اللفظ الأدق وتجنّب التكرار","تغيير قواعد الإعراب","إلغاء علامات الترقيم"],"answer":1,"why":"يوفر للكاتب مترادفات دقيقة لكل درجة معنى."},{"type":"mcq","q":"أي مما يأتي يُعدّ من معاجم «الألفاظ» وليس معاجم المعاني؟","options":["المخصّص","فقه اللغة","المعجم الوسيط","الألفاظ الكتابية"],"answer":2,"why":"المعجم الوسيط مرتّب هجائيًا حسب الألفاظ."},{"type":"tfr","q":"نستخدم معجم المعاني عندما نعرف المعنى ونبحث عن اللفظ الدقيق المعبّر عنه.","answer":true,"reasons":["بعكس معجم الألفاظ الذي نعرف فيه اللفظ ونبحث عن معناه","نستخدمه لمعرفة معنى كلمة غامضة فقط","لا يُستخدم في الكتابة"],"reason":0},{"type":"tfr","q":"معجم «لسان العرب» لابن منظور يُصنّف ضمن معاجم المعاني.","answer":false,"reasons":["نعم من معاجم المعاني","بل من معاجم الألفاظ المرتّبة هجائيًا (نظام القافية)","هو كتاب في التاريخ"],"reason":1},{"type":"tfr","q":"تُبرز معاجم المعاني دقة اللغة العربية في التمييز بين درجات المعنى الواحد كالمطر والأصوات.","answer":true,"reasons":["لا تذكر الأصوات","اللغة العربية ليس فيها تدرج","مثل التدرج من الطلّ والرذاذ إلى الوابل"],"reason":2},{"type":"essay","q":"اذكر ثلاثة أمثلة للألفاظ الدقيقة للأصوات الطبيعية التي تجمعها معاجم المعاني.","model":"خرير (صوت الماء)، حفيف (صوت أوراق الشجر)، قصف (صوت الرعد)، زئير (صوت الأسد)."},{"type":"essay","q":"كيف يستفيد طالب الصف التاسع من معجم المعاني في دروس التعبير؟","model":"يختار ألفاظًا دقيقة تناسب المعنى المقصود دون حشو، ويجد بدائل لغوية تمنع تكرار الكلمات وتزيد نصه جمالًا."},{"type":"essay","q":"رتّب ألفاظ المطر الآتية من الأخف إلى الأغزر: الوابل، الطلّ، الرذاذ.","model":"الطلّ (الأخف) ← الرذاذ ← الوابل (الأغزر والأعظم قطرًا)."}]}},
  {"id":"g9-arabic-2-u1-6","grade":"g9","subject":"arabic","term":2,"unit":1,"no":6,"title":"النص الأدبي: نزلت تجرّ إلى الغروب ذيولًا","summary":"شرح متحرك بـ SVG لدرس النص الأدبي: نزلت تجرّ إلى الغروب ذيولًا (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-sunset-poem-rusafi.html","video":"","pdf":"","notes":["الشاعر: معروف الرصافي (العصر الحديث) | الغرض: وصف غروب الشمس.","الصور البارزة: تشخيص الشمس (تجرّ ذيولًا) وتشبيه اصفرارها بالعاشق المتبول.","القصيدة تدمج تدرّج الألوان والهدوء الموسيقي والتأمل في عظمة الكون."],"exercises":["اشرح البيت الأول بأسلوبك: «نزلت تجرّ إلى الغروب ذيولًا · صفراءَ تشبه عاشقًا متبولًا».","وضّح صورتين فنيتين في القصيدة وبيّن أثرهما في المعنى.","تتبّع تدرّج الألوان في القصيدة من بداية الغروب حتى حلول الليل."],"levels":{"easy":[{"type":"mcq","q":"من قائل قصيدة «نزلت تجرّ إلى الغروب ذيولًا»؟","options":["أحمد شوقي","معروف الرصافي","عنترة بن شداد","أبو تمام"],"answer":1,"why":"الشاعر العراقي معروف الرصافي."},{"type":"mcq","q":"ما معنى كلمة «متبولًا» في البيت الأول؟","options":["سريع الحركة","سعيدًا ضاحكًا","أضناه الشوق والحب حتى اصفرّ لونه","قويّ البنية"],"answer":2,"why":"التبل هو السقم من الشوق، وشبّه به اصفرار الشمس."},{"type":"mcq","q":"ما الغرض الشعري الذي تنتمي إليه القصيدة؟","options":["الرثاء","الفخر الحربي","الهجاء","وصف الطبيعة (مشهد الغروب)"],"answer":3,"why":"القصيدة لوحة وصفية لمشهد غروب الشمس."},{"type":"mcq","q":"بمَ شبّه الشاعر الشمس في قوله «نزلت تجرّ إلى الغروب ذيولًا»؟","options":["بإنسان (فتاة) يمشي متمهلًا يجرّ ذيول ثوبه","بسفينة تغرق","بعاصفة رملية","بجبل صخري"],"answer":0,"why":"هذا تشخيص يبرز بطء الغروب ووقاره."}],"medium":[{"type":"mcq","q":"ما الدلالة الإيحائية للفعل «تجرّ» في مطلع القصيدة؟","options":["السرعة الفائقة","البطء والتمهّل في غروب الشمس","الاختفاء المفاجئ","العنف والشدة"],"answer":1,"why":"جرّ الذيول يوحي بالتمهل والهدوء."},{"type":"mcq","q":"ما العلاقة بين «الضياء» و«الظلام» في لوحة الغروب وإقبال الليل؟","options":["جناس ناقص","ترادف","طباق يبرز المعنى ويوضّحه بالتضاد","سجع"],"answer":2,"why":"الطباق يبرز جمال التحول بين النهار والليل."},{"type":"mcq","q":"بمَ ختم الشاعر وصفه لمشهد الغروب وإقبال الليل؟","options":["بالحديث عن السفر","بوصف الأسواق","بعتاب الأصدقاء","بالتأمل في عظمة الكون وقدرة الخالق"],"answer":3,"why":"انتقل من الوصف البصري إلى التأمل الفكري والإيماني."},{"type":"tfr","q":"شاعر قصيدة «نزلت تجرّ إلى الغروب ذيولًا» هو الشاعر العراقي معروف الرصافي.","answer":true,"reasons":["هو حافظ إبراهيم","هو المتنبي","وهو من أبرز شعراء العصر الحديث في الوصف والاجتماع"],"reason":2},{"type":"tfr","q":"اقتصرت القصيدة على الوصف الخارجي السطحي دون أي تأمل فكري أو عاطفي.","answer":false,"reasons":["بل مزجت بين الوصف الدقيق للألوان والتأمل العميق في عظمة الكون","نعم اقتصرت على السطح فقط","خلت من الوصف"],"reason":0},{"type":"essay","q":"اشرح البيت الأول بأسلوبك: «نزلت تجرّ إلى الغروب ذيولًا · صفراءَ تشبه عاشقًا متبولًا».","model":"تصوّر الأبيات الشمس وهي تنحدر ببطء نحو الغروب ساحبةً وراءها خيوط أشعتها كذيول ثوب طويل، وقد شحب لونها واصفرّ فأشبهت عاشقًا أضناه الشوق."},{"type":"essay","q":"وضّح صورتين فنيتين في القصيدة وبيّن أثرهما في المعنى.","model":"١) «نزلت تجرّ ذيولًا»: تشخيص يبرز هدوء الغروب ووقاره. ٢) «صفراءَ تشبه عاشقًا متبولًا»: تشبيه يبرز شحوب لون الشمس عند الغروب."}],"hard":[{"type":"mcq","q":"تُعدّ عبارة «صفراءَ تشبه عاشقًا متبولًا» من صور:","options":["التشبيه التام (بأداة التشبيه «تشبه»)","الاستفهام","الأمر","النهي"],"answer":0,"why":"ذُكر المشبّه والمشبّه به والأداة ووجه الشبه (الصفرة)."},{"type":"mcq","q":"ما الإحساس الذي تبعثه القافية المطلقة بالألف (ذيولًا، متبولًا)؟","options":["التوتر والضجيج","الهدوء والامتداد المناسب لسكون الغروب","الغضب الشديد","السخرية"],"answer":1,"why":"المدّ الصوتي في القافية يلائم هدوء المشهد."},{"type":"mcq","q":"أي الألوان يغلب على لوحة الغروب في القصيدة؟","options":["الرمادي فقط","الأخضر فقط","الأصفر والأحمر (الشفق) ثم سواد الليل وبريق النجوم","الأبيض فقط"],"answer":2,"why":"تدرج لوني دقيق يتابع مراحل الغروب."},{"type":"mcq","q":"في أي عصر عاش الشاعر معروف الرصافي؟","options":["العصر العباسي الأول","العصر الجاهلي","العصر الأموي","العصر الحديث"],"answer":3,"why":"عاش في أواخر القرن ١٩ والنصف الأول من القرن ٢٠."},{"type":"tfr","q":"تشبيه الشمس بعاشق متبول يبرز اصفرار لونها وضعف ضوئها عند الغروب.","answer":true,"reasons":["يبرز شدة حرارتها وقت الظهر","فوجه العاشق المُضنى يميل للاصفرار كشمس الغروب","يبرز سرعتها"],"reason":1},{"type":"tfr","q":"الفعل «تجرّ» في البيت الأول يوحي بسرعة اختفاء الشمس المفاجئة.","answer":false,"reasons":["يوحي بالغضب","نعم يوحي بالسرعة","بل يوحي بالتمهّل والبطء والوقار في الغروب"],"reason":2},{"type":"tfr","q":"التشخيص من أبرز الوسائل الفنية التي اعتمدها الرصافي في هذه القصيدة.","answer":true,"reasons":["حيث جعل الشمس تنزل وتجرّ ذيولها كأنها كائن حي","لم يستخدم التشخيص أبدًا","استخدم الأرقام فقط"],"reason":0},{"type":"essay","q":"تتبّع تدرّج الألوان في القصيدة من بداية الغروب حتى حلول الليل.","model":"تبدأ بالصفرة، ثم الحمرة القانية (الشفق)، ثم يبسط الليل سواده فتتلألأ النجوم البيضاء المضيئة في السماء."},{"type":"essay","q":"لماذا يربط الشعراء غالبًا بين وصف الطبيعة والتأمل في قدرة الله؟","model":"لأن دقة نظام الكون وتعاقب الليل والنهار وجمال الألوان تثير الدهشة وتدعو العقل للتفكّر في عظمة الخالق."},{"type":"essay","q":"وازن باختصار بين وصف الطبيعة في نص «من وحي الخريف في صلالة» (نثر) وقصيدة الرصافي (شعر).","model":"كلاهما يوظّف التشخيص والألوان والحواس، لكن نص صلالة نثر وصفي لخضرة الخريف ورذاذه، بينما قصيدة الرصافي شعر موزون مقفّى للوحة الغروب وإقبال الليل."}]}},
  {"id":"g9-arabic-2-u2-1","grade":"g9","subject":"arabic","term":2,"unit":2,"no":1,"title":"القراءة: عمر وعام الرمادة","summary":"شرح متحرك بـ SVG لدرس القراءة: عمر وعام الرمادة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-umar-year-of-famine.html","video":"","pdf":"","notes":["عام الرمادة (١٨ هـ): أزمة قحط ومجاعة في عهد عمر بن الخطاب رضي الله عنه.","القيادة المسؤولة: القدوة العملية + التخطيط السريع وجلب الإمدادات + التوزيع العادل + التفقد الليلي.","الجمع بين الأخذ بالأسباب والتضرع لله، وترسيخ قيمة التكافل وقت الأزمات."],"exercises":["اذكر ثلاثة إجراءات عملية اتخذها عمر بن الخطاب لإدارة أزمة عام الرمادة.","اشرح كيف توازن قصة عام الرمادة بين «الأخذ بالأسباب» و«التوكل على الله».","ما أثر قول عمر: «بئس الوالي أنا إن شبعت والناس جياع» في نفوس الرعية؟"],"levels":{"easy":[{"type":"mcq","q":"لماذا سُمّي العام الثامن عشر للهجرة بـ«عام الرمادة»؟","options":["لوقوع معركة كبيرة","لكثرة الأمطار والسيول","لأن الأرض اسودّت من الجفاف والريح كانت تذرو ترابًا كالرماد","لبناء مدينة جديدة"],"answer":2,"why":"الجفاف الشديد جعل الأرض تشبه الرماد."},{"type":"mcq","q":"ماذا حرّم عمر بن الخطاب رضي الله عنه على نفسه طوال أزمة عام الرمادة؟","options":["مراسلة الولاة","شرب الماء نهائيًا","الخروج من بيته","أكل السمن واللحم واللبن حتى يشبع الناس"],"answer":3,"why":"آلى ألا يأكل السمن واللحم ليشارك الرعية معاناتهم."},{"type":"mcq","q":"من الوالي الذي أرسل من مصر قافلة إغاثة عظيمة إلى المدينة؟","options":["عمرو بن العاص","خالد بن الوليد","طارق بن زياد","قتيبة بن مسلم"],"answer":0,"why":"استجاب عمرو بن العاص لرسالة عمر بقافلة ضخمة من مصر."},{"type":"mcq","q":"ماذا يدل قول عمر: «بئس الوالي أنا إن شبعتُ والناس جياع»؟","options":["رغبته في السفر","شعوره العميق بالمسؤولية ومشاركته الرعية في الشدة","كرهه للطعام","إهماله للإدارة"],"answer":1,"why":"يبرز معيار القيادة العادلة والقدوة العملية."}],"medium":[{"type":"mcq","q":"كم استمرت شدة عام الرمادة تقريبًا؟","options":["عشر سنوات","ثلاثة أيام فقط","نحو تسعة أشهر","أسبوعين"],"answer":2,"why":"استمرت الأزمة قرابة تسعة أشهر حتى أغاثهم الله."},{"type":"mcq","q":"بمَ جمع عمر رضي الله عنه في معالجة أزمة عام الرمادة؟","options":["إغلاق أبواب المدينة","الاكتفاء بالانتظار دون عمل","الاعتماد على المال فقط","بين الأخذ بالأسباب المادية (القوافل والتنظيم) والدعاء والاستسقاء"],"answer":3,"why":"وازن بين التخطيط الإداري واللجوء إلى الله."},{"type":"mcq","q":"ما الإجراء الفقهي الرحيم الذي اتخذه عمر في عام المجاعة؟","options":["إسقاط حدّ السرقة عن المضطر الجائع في عام المجاعة","مضاعفة العقوبات","منع دخول الوافدين","رفع الضرائب"],"answer":0,"why":"راعى مقاصد الشريعة في حفظ النفس والرحمة بالمضطر."},{"type":"tfr","q":"سُمّي عام الرمادة بهذا الاسم بسبب الجفاف الشديد الذي جعل الأرض تشبه الرماد.","answer":true,"reasons":["حيث انحبس المطر سنة ١٨ هـ وجفّت الأرض","بسبب بركان ثار في المدينة","بسبب كثرة الأمطار"],"reason":0},{"type":"tfr","q":"اكتفى عمر بن الخطاب بالدعاء ولم يرسل طلبًا للإغاثة من الولايات الأخرى.","answer":false,"reasons":["نعم اكتفى بالدعاء","بل أخذ بكل الأسباب وأرسل لولاته في مصر والشام والعراق ونظّم توزيع الطعام","أغلق حدود المدينة"],"reason":1},{"type":"essay","q":"اذكر ثلاثة إجراءات عملية اتخذها عمر بن الخطاب لإدارة أزمة عام الرمادة.","model":"١) مراسلة الولاة في مصر والشام والعراق لإرسال قوافل الطعام. ٢) تنظيم توزيع الطعام وإقامة قدور للوافدين. ٣) التفقد الليلي للأسر المتعففة ومشاركتهم التقشف."},{"type":"essay","q":"اشرح كيف توازن قصة عام الرمادة بين «الأخذ بالأسباب» و«التوكل على الله».","model":"أخذ عمر بكل الأسباب الإدارية والاقتصادية بجلب المؤن وتوزيعها بعدل، ثم خرج مع الناس لصلاة الاستسقاء متضرعًا إلى الله الذي أغاثهم بالمطر."}],"hard":[{"type":"mcq","q":"بمن توسّل عمر رضي الله عنه في صلاة الاستسقاء؟","options":["بأهل العراق فقط","بدعاء العباس بن عبد المطلب عمّ النبي ﷺ","بالتجار","بالشعراء"],"answer":1,"why":"قال: اللهم إنا نتوسل إليك بعمّ نبيّنا فاسقنا."},{"type":"mcq","q":"ما القيمة الاجتماعية التي يربطها النص بمجتمعنا العُماني وقت الأنواء المناخية؟","options":["التنافس على الاحتكار","الفردية والأنانية","التكافل والتآزر ومدّ يد العون للمتضررين","الانعزال عن الناس"],"answer":2,"why":"التكاتف وقت الشدائد قيمة إسلامية وعُمانية أصيلة."},{"type":"mcq","q":"ما معنى كلمة «القحط» الواردة في سياق النص؟","options":["كثرة المحاصيل","غزارة المطر","اعتدال الجو","انقطاع المطر وجفاف الأرض"],"answer":3,"why":"القحط والجدب هما انحباس المطر والجفاف."},{"type":"mcq","q":"ما دلالة عبارة «قافلة أولها في المدينة وآخرها في مصر»؟","options":["الكناية عن ضخامة الإمدادات وتواصل القوافل دون انقطاع","أن الطريق كان قصيرًا جدًا","أن القافلة ضلّت الطريق","أنها قافلة واحدة صغيرة"],"answer":0,"why":"تعبير بلاغي يدل على كثرة الإمدادات واتصالها."},{"type":"tfr","q":"مشاركة القائد لشعبه في المعاناة تعزّز الثقة والتماسك الاجتماعي في الأزمات.","answer":true,"reasons":["تُضعف هيبة القائد","لا أثر لها","وهو ما جسّده عمر بامتناعه عن السمن واللحم وتفقده الأسر بنفسه"],"reason":2},{"type":"tfr","q":"وقعت أزمة عام الرمادة في خلافة عمر بن الخطاب سنة ١٨ هـ.","answer":true,"reasons":["واستمرت قرابة تسعة أشهر حتى فرّج الله عنهم","وقعت في عهد الدولة العباسية","وقعت قبل الهجرة"],"reason":0},{"type":"tfr","q":"التكافل الاجتماعي في الأزمات مسؤولية الحاكم وحده ولا دور للأفراد فيه.","answer":false,"reasons":["نعم الحاكم وحده","بل هو مسؤولية مشتركة بين القيادة وأفراد المجتمع جميعًا","لا حاجة للتكافل"],"reason":1},{"type":"essay","q":"ما أثر قول عمر: «بئس الوالي أنا إن شبعت والناس جياع» في نفوس الرعية؟","model":"يبعث الطمأنينة والرضا في قلوب الناس، ويجعلهم يشعرون بالعدالة والمساواة والتلاحم مع قائدهم."},{"type":"essay","q":"اربط بين دروس عام الرمادة ومظاهر التكافل في سلطنة عُمان عند حدوث الأنواء المناخية.","model":"كما تكاتف المسلمون في عام الرمادة لإغاثة المحتاجين، يهبّ أبناء عُمان والجهات التطوعية معًا لفتح الطرق وإيواء المتضررين وتقديم المساعدات بروح أخوية واحدة."},{"type":"essay","q":"لماذا أسقط عمر رضي الله عنه حدّ السرقة في عام المجاعة؟","model":"تحقيقًا لمقاصد الشريعة في الرحمة ورفع الحرج عن المضطر الذي دفعه الجوع الشديد، فالشريعة قائمة على العدل والرحمة."}]}},
  {"id":"g9-arabic-2-u2-2","grade":"g9","subject":"arabic","term":2,"unit":2,"no":2,"title":"الأنشطة النحوية والصرفية: جملة لا النافية للجنس","summary":"شرح متحرك بـ SVG لدرس الأنشطة النحوية والصرفية: جملة لا النافية للجنس (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-la-nafiya-liljins.html","video":"","pdf":"","notes":["شروط عمل لا النافية للجنس: نكرتان + بلا فاصل + لم تُسبق بحرف جر.","المفرد (كلمة واحدة ولو مثنى/جمع): مبني على ما يُنصب به في محل نصب.","المضاف (بلا تنوين) والشبيه بالمضاف (منوّن): معربان منصوبان."],"exercises":["اذكر شروط عمل «لا النافية للجنس» الثلاثة مع مثال لجملة مستوفية للشروط.","قارن بين أنواع اسم لا الثلاثة في: «لا طالبَ مهملٌ»، «لا طالبَ علمٍ مهملٌ»، «لا طالبًا للعلمِ مهملٌ».","بيّن سبب إهمال «لا» في كل جملة وأعرب ما بعدها: (أ) لا الكسلُ نافعٌ ولا التهاونُ. (ب) سافرتُ بلا رفيقٍ."],"levels":{"easy":[{"type":"mcq","q":"ما نوع اسم لا النافية للجنس وإعرابه في: «لا منافقَ محبوبٌ»؟","options":["مبتدأ مرفوع","مضاف — منصوب بالفتحة","شبيه بالمضاف — منصوب","مفرد — مبني على الفتح في محل نصب"],"answer":3,"why":"كلمة واحدة نكرة غير مضافة ولا شبيهة بالمضاف فهي مفرد مبني."},{"type":"mcq","q":"ما نوع اسم لا في جملة: «لا طالبًا للعلمِ مهملٌ»؟","options":["شبيه بالمضاف (معرب منصوب)","مفرد (مبني)","مضاف (منصوب)","مهمل مرفوع"],"answer":0,"why":"وجود التنوين والجار والمجرور المتمم للمعنى يجعله شبيهًا بالمضاف."},{"type":"mcq","q":"ما نوع اسم لا في: «لا صانعَ معروفٍ نادمٌ»؟","options":["مفرد (مبني)","مضاف (معرب منصوب بالفتحة)","شبيه بالمضاف","فاعل"],"answer":1,"why":"«معروفٍ» مضاف إليه نكرة، فاسم لا مضاف منصوب."},{"type":"mcq","q":"ما إعراب كلمة «شكٍّ» في جملة: «العلمُ مفيدٌ بلا شكٍّ»؟","options":["خبر لا مرفوع","اسم لا مبني على الفتح","اسم مجرور بالباء وعلامة جره الكسرة (لا هنا مهملة)","مفعول به"],"answer":2,"why":"دخول حرف الجر (الباء) على لا يُلغي عملها."}],"medium":[{"type":"mcq","q":"لماذا أُهمِلت «لا» ووُجب تكرارها في: «لا في الصفِّ كسولٌ ولا مهملٌ»؟","options":["لأنها ناهية","لأنها سُبقت بحرف جر","لأن الاسم منصوب","لوجود فاصل (شبه الجملة في الصف) بين لا واسمها"],"answer":3,"why":"من شروط عملها ألا يفصل بينها وبين اسمها فاصل."},{"type":"mcq","q":"ما الإعراب الصحيح لـ«مجتهدِين» في: «لا مجتهدِينَ فاشلون»؟","options":["اسم لا مبني على الياء في محل نصب","اسم لا منصوب بالفتحة","مبتدأ مرفوع","خبر لا"],"answer":0,"why":"المفرد (ولو كان جمع مذكر سالمًا) يُبنى على ما يُنصب به (الياء)."},{"type":"mcq","q":"أي الجمل الآتية فيها اسم لا «مضافًا»؟","options":["لا متكبرَ محبوبٌ","لا ذا علمٍ متكبرٌ","لا ساعيًا للخيرِ خاسرٌ","لا الكسولُ ناجحٌ ولا المهملُ"],"answer":1,"why":"«ذا» من الأسماء الخمسة مضاف إلى «علمٍ»، منصوب بالألف."},{"type":"tfr","q":"اسم لا النافية للجنس «المفرد» يُقصد به ما ليس مضافًا ولا شبيهًا بالمضاف، حتى لو كان مثنى أو جمعًا.","answer":true,"reasons":["يقصد به المفرد العددي فقط","مثل: لا طالبَين مهملان (مبني على الياء في محل نصب)","المثنى يكون مضافًا دائمًا"],"reason":1},{"type":"tfr","q":"تعمل لا النافية للجنس إذا دخل عليها حرف الجر الباء مثل «بلا خوفٍ».","answer":false,"reasons":["تُرفع الكلمة بعدها","نعم تبقى عاملة","يُلغى عملها وتُجر الكلمة بعدها بحرف الجر"],"reason":2},{"type":"essay","q":"اذكر شروط عمل «لا النافية للجنس» الثلاثة مع مثال لجملة مستوفية للشروط.","model":"١) أن يكون اسمها وخبرها نكرتين. ٢) ألا يفصل بينها وبين اسمها فاصل. ٣) ألا تُسبق بحرف جر. مثال: لا مجتهدَ خاسرٌ."},{"type":"essay","q":"قارن بين أنواع اسم لا الثلاثة في: «لا طالبَ مهملٌ»، «لا طالبَ علمٍ مهملٌ»، «لا طالبًا للعلمِ مهملٌ».","model":"الأول مفرد مبني على الفتح في محل نصب. الثاني مضاف معرب منصوب بالفتحة. الثالث شبيه بالمضاف معرب منصوب بالفتحة."}],"hard":[{"type":"mcq","q":"كيف تُحوّل «لا طالبَ علمٍ كسولٌ» (مضاف) إلى شبيه بالمضاف؟","options":["لا الطالبُ كسولٌ","لا طالبَ كسولٌ","لا طالبًا علمًا كسولٌ (أو لا طالبًا للعلمِ كسولٌ)","بلا طالبِ علمٍ"],"answer":2,"why":"ننوّن الاسم ونأتي بمعمول أو جار ومجرور يتمم معناه."},{"type":"mcq","q":"ما حكم اسم لا المفرد إذا كان جمع مؤنث سالمًا مثل «لا مهملاتِ ناجحاتٌ»؟","options":["مجرور بالياء","مبني على الفتح","مرفوع بالضمة","مبني على الكسرة في محل نصب"],"answer":3,"why":"يُبنى على ما يُنصب به، وجمع المؤنث يُنصب بالكسرة."},{"type":"mcq","q":"أي الشروط الآتية ليس من شروط عمل لا النافية للجنس؟","options":["أن يكون اسمها معرفةً بـ«ال»","أن يكون اسمها وخبرها نكرتين","ألا يفصل بينها وبين اسمها فاصل","ألا تُسبق بحرف جر"],"answer":0,"why":"بل يُشترط أن يكون اسمها نكرة لا معرفة!"},{"type":"mcq","q":"ما إعراب كلمة «أحدٌ» في: «لا الخائنُ مأمونٌ ولا الكاذبُ» (إعراب الخائنُ)؟","options":["اسم لا مبني","مبتدأ مرفوع بالضمة (لا مهملة لأن الاسم معرفة)","اسم لا منصوب","خبر لا"],"answer":1,"why":"دخول «ال» التعريف يُلغي عمل لا ويعرب ما بعدها مبتدأً."},{"type":"tfr","q":"الفرق الظاهر بين المضاف والشبيه بالمضاف هو بقاء التنوين أو النون في الشبيه بالمضاف وحذفهما في المضاف.","answer":true,"reasons":["لا طالبَ علمٍ (مضاف بلا تنوين) مقابل لا طالبًا علمًا (شبيه منوّن)","المضاف يكون منوّنًا","لا فرق بينهما"],"reason":0},{"type":"tfr","q":"إذا فُصل بين «لا» واسمها بفاصل بطل عملها ووُجب تكرارها.","answer":true,"reasons":["تبقى عاملة","مثل: لا في الحديقةِ شجرٌ ولا زهرٌ","يُحذف خبرها"],"reason":1},{"type":"tfr","q":"اسم لا النافية للجنس في «لا صادقَ مكروهٌ» معرب منصوب بالفتحة.","answer":false,"reasons":["مرفوع بالضمة","نعم معرب منصوب","بل مفرد «مبني» على الفتح في محل نصب"],"reason":2},{"type":"essay","q":"بيّن سبب إهمال «لا» في كل جملة وأعرب ما بعدها: (أ) لا الكسلُ نافعٌ ولا التهاونُ. (ب) سافرتُ بلا رفيقٍ.","model":"(أ) لأن اسمها معرفة؛ الكسلُ: مبتدأ مرفوع بالضمة. (ب) لأنها سُبقت بحرف جر؛ رفيقٍ: اسم مجرور بالباء وعلامة جره الكسرة."},{"type":"essay","q":"ثنِّ اسم لا واجمعه جمع مذكر سالمًا في الجملة: «لا عاملَ مقصّرٌ».","model":"المثنى: لا عاملَين مقصّران. الجمع: لا عاملِينَ مقصّرون."},{"type":"essay","q":"أعرب الجملة الآتية إعرابًا تامًا: «لا قارئَ كتابٍ نادمٌ».","model":"لا: نافية للجنس. قارئَ: اسم لا منصوب بالفتحة (مضاف). كتابٍ: مضاف إليه مجرور بالكسرة. نادمٌ: خبر لا مرفوع بالضمة."}]}},
  {"id":"g9-arabic-2-u2-3","grade":"g9","subject":"arabic","term":2,"unit":2,"no":3,"title":"الأنشطة الإملائية: الوصل","summary":"شرح متحرك بـ SVG لدرس الأنشطة الإملائية: الوصل (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-arabic-word-joining.html","video":"","pdf":"","notes":["ما الاستفهامية بعد حرف الجر: تُوصل وتُحذف ألفها (عَمَّ، مِمَّ، فِيمَ، لِمَ، بِمَ، إلامَ، علامَ).","ما الموصولة: تُوصل وتبقى ألفها (مِمّا، عَمّا).","أنْ الناصبة+لا = ألّا | إنْ الشرطية+لا = إلّا | حين/يوم/وقت + إذ = حينئذٍ/يومئذٍ/وقتئذٍ."],"exercises":["فرّق إملائيًا ومعنويًا بين «عَمَّ» و«عَمّا» مع مثال لكل منهما.","صوّب الأخطاء الإملائية في الجملة: «إلى ما تنظر يا أخي؟ اجتهد أن لا تتأخر، ووقت أذٍ ستفرح».","أدخل حرف الجر «مِن» مرةً على «ما الاستفهامية» ومرةً على «ما الموصولة» ومرةً على «مَن» في جمل مفيدة."],"levels":{"easy":[{"type":"mcq","q":"ما الرسم الإملائي الصحيح عند سؤال صديقك: «عن + ما تبحث؟»","options":["عَمَّ تبحث؟","عَمّا تبحث؟","عن ما تبحث؟","عَمّاء تبحث؟"],"answer":0,"why":"ما استفهامية بعد حرف الجر فتُوصل وتُحذف ألفها."},{"type":"mcq","q":"أكمل الجملة بالرسم الصحيح: «تصدّقْ ...... أعطاك الله»:","options":["مِمَّ","مِمّا","من ما","مماء"],"answer":1,"why":"ما هنا موصولة (بمعنى الذي) فتُوصل وتبقى ألفها."},{"type":"mcq","q":"ما الرسم الصحيح لوصل الظرف «يوم» بـ«إذ»؟","options":["يومأذٍ","يوم إذٍ","يومئذٍ","يومءذٍ"],"answer":2,"why":"تُوصل «إذ» بالظروف وتُكتب همزتها على نبرة."},{"type":"mcq","q":"أكمل الجملة: «أوصيك ...... تتأخر عن الصلاة»:","options":["ألا","إلّا","أن لا","ألّا"],"answer":3,"why":"أنْ الناصبة + لا النافية = ألّا (بهمزة فوق الألف وتشديد اللام)."}],"medium":[{"type":"mcq","q":"ما التركيب الأصلي لكلمة «مِمَّن» في: «مِمَّن أخذتَ هذا الكتاب؟»","options":["مِن + مَن","مِن + ما","ما + مَن","مِمَّ + أنْ"],"answer":0,"why":"أُدغمت نون «مِن» في ميم «مَن» فصارت «مِمَّن»."},{"type":"mcq","q":"أي الجمل الآتية كُتبت فيها «ما» الاستفهامية كتابةً صحيحةً؟","options":["لِما غبتَ عن المدرسة أمس؟","لِمَ غبتَ عن المدرسة أمس؟","لِماء غبتَ عن المدرسة؟","لِ ما غبتَ؟"],"answer":1,"why":"تُحذف ألف ما الاستفهامية بعد اللام: لِمَ؟"},{"type":"mcq","q":"تُوصل «ما الكافّة» بـ«إنّ» فتُكتب:","options":["إمّا","إنّ ما","إنّما","أنما"],"answer":2,"why":"إنّ + ما الكافة = إنّما (مثل: إنّما الأعمال بالنيات)."},{"type":"tfr","q":"تُحذف ألف «ما الاستفهامية» وجوبًا إذا اتصلت بحرف جر مثل: بِمَ؟ لِمَ؟ عَمَّ؟","answer":true,"reasons":["تُحذف في الموصولة فقط","تبقى الألف دائمًا","تمييزًا لها عن «ما الموصولة» التي تبقى ألفها"],"reason":2},{"type":"tfr","q":"تُكتب «عَمَّ» بحذف الألف في جملة: «ابتعد عمّ يضرّك».","answer":false,"reasons":["هنا «ما» موصولة (بمعنى الذي) فتبقى ألفها: عَمّا يضرّك","نعم تُحذف الألف","تُفصل: عن ما"],"reason":0},{"type":"essay","q":"فرّق إملائيًا ومعنويًا بين «عَمَّ» و«عَمّا» مع مثال لكل منهما.","model":"«عَمَّ»: عن + ما الاستفهامية (تُحذف الألف)، مثل: عَمَّ تسأل؟ «عَمّا»: عن + ما الموصولة (تبقى الألف)، مثل: ابتعد عَمّا يغضب الله."},{"type":"essay","q":"صوّب الأخطاء الإملائية في الجملة: «إلى ما تنظر يا أخي؟ اجتهد أن لا تتأخر، ووقت أذٍ ستفرح».","model":"الصواب: إلامَ تنظر يا أخي؟ اجتهد ألّا تتأخر، ووقتئذٍ ستفرح."}],"hard":[{"type":"mcq","q":"ما الرسم الصحيح للعدد ٥٠٠ عند وصله بـ«مئة»؟","options":["خمس مئاة","خمسة مائة","خمسمأه","خمسمئة"],"answer":3,"why":"تُوصل الأعداد ٣–٩ بـ«مئة» فتُكتب خمسمئة."},{"type":"mcq","q":"أكمل الجملة: «ذاكرْ بجدٍّ و...... فلن تتفوّق»:","options":["إلّا","ألّا","إن ما","ألا"],"answer":0,"why":"إنْ الشرطية + لا = إلّا (بهمزة تحت الألف)."},{"type":"mcq","q":"أي الكلمات الآتية تُفصل فيها «أنْ» عن «لا»؟","options":["أريدُ ألّا تتأخرَ","أشهدُ أنْ لا إلهَ إلّا اللهُ","ينبغي ألّا تكذبَ","اجتهدْ وإلّا تندمْ"],"answer":1,"why":"«أنْ» المخففة من الثقيلة تُفصل عن «لا»."},{"type":"mcq","q":"ما الرسم الصحيح لوصل «في + ما» الاستفهامية؟","options":["في ما تفكّر؟","فِيما تفكّر؟","فِيمَ تفكّر؟","فِمَ تفكّر؟"],"answer":2,"why":"تُوصل في بـ ما الاستفهامية وتُحذف الألف: فِيمَ؟"},{"type":"tfr","q":"تُوصل الظروف مثل «حين، وقت، يوم» بـ«إذ» وتُكتب الهمزة على نبرة: حينئذٍ، وقتئذٍ.","answer":true,"reasons":["تُكتب على ألف","لأن الهمزة مكسورة بعد فتح فالكسرة أقوى فتُرسم على نبرة","تُكتب مفصولةً"],"reason":1},{"type":"tfr","q":"الفرق بين «ألّا» و«إلّا» أن «ألّا» أصلها (أنْ الناصبة + لا) و«إلّا» أصلها (إنْ الشرطية + لا).","answer":true,"reasons":["أصلهما ما + لا","كلاهما بمعنى واحد","لذلك تُفتح الهمزة في ألّا وتُكسر في إلّا"],"reason":2},{"type":"tfr","q":"تُكتب «حبّذا» مفصولةً هكذا: «حبّ ذا».","answer":false,"reasons":["بل تُوصل وجوبًا فتُكتب كلمة واحدة: حبّذا","نعم تُفصل","تُكتب حبذ"],"reason":0},{"type":"essay","q":"أدخل حرف الجر «مِن» مرةً على «ما الاستفهامية» ومرةً على «ما الموصولة» ومرةً على «مَن» في جمل مفيدة.","model":"استفهامية: مِمَّ يتكوّن الماء؟ موصولة: خذ مِمّا ينفعك. مَن: مِمَّن تعلّمت السباحة؟"},{"type":"essay","q":"اشرح سبب فصل «أنْ» عن «لا» في: «علمتُ أنْ لا نجاحَ للمهمل» ووصلها في: «يجب ألّا تهملَ».","model":"في الأولى «أنْ» مخففة من الثقيلة فتُفصل عن «لا»، وفي الثانية «أنْ» مصدرية ناصبة للمضارع فتُوصل بـ«لا» وتُدغم: ألّا."},{"type":"essay","q":"اكتب أربع كلمات موصولة من مواضع الوصل المختلفة في جمل قصيرة.","model":"١) لِمَ تأخرت؟ ٢) إنّما المؤمنون إخوة. ٣) حينئذٍ يفرح المجتهد. ٤) حبّذا الصدق والأمانة."}]}},
  {"id":"g9-arabic-2-u2-4","grade":"g9","subject":"arabic","term":2,"unit":2,"no":4,"title":"التعبير: وصف منظر طبيعي وكتابته","summary":"شرح متحرك بـ SVG لدرس التعبير: وصف منظر طبيعي وكتابته (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-writing-landscape-essay.html","video":"","pdf":"","notes":["حوّل المخطط إلى فقرات منظمة (مقدمة، عرض، خاتمة) مع ترك مسافة بادئة.","استخدم أدوات الربط المكاني، وامزج بين الجمل الاسمية (للثبات) والفعلية (للحركة).","نقّح نصك بحذف التكرار وضبط علامات الترقيم والإملاء قبل التسليم."],"exercises":["اكتب فقرة عرض (٤–٥ أسطر) تصف فيها «واديًا عُمانيًا» موظّفًا أدوات الربط المكاني وحاستَي البصر والسمع.","أضف علامات الترقيم المناسبة للفقرة الآتية: «وقفتُ على شاطئ السيب وقت الغروب فما أروع المشهد كانت الأمواج تتهادى بهدوء والطيور تعود إلى أعشاشها».","ما قائمة الفحص (٤ نقاط) التي تراجع بها نصك الوصفي قبل تسليمه للمعلم؟"],"levels":{"easy":[{"type":"mcq","q":"أي الجملتين أنسب لوصف «حركة الأمواج وتجددها» في النص الوصفي؟","options":["البحرُ واسعٌ","تتلاحق الأمواجُ الزرقاءُ وتداعب رمالَ الشاطئ","الشاطئُ رمليٌّ","الماءُ مالحٌ"],"answer":1,"why":"الجملة الفعلية بالمضارع تبرز الحركة والتجدد."},{"type":"mcq","q":"ما فائدة العبارات المكانية مثل «في الأفق البعيد، وعلى ضفاف الوادي»؟","options":["إخفاء المكان","زيادة عدد الكلمات بلا فائدة","تنظيم حركة عين القارئ وربط أجزاء المشهد بسلاسة","الانتقال لقصة أخرى"],"answer":2,"why":"أدوات الربط المكاني تحقق التماسك والوضوح البصري."},{"type":"mcq","q":"ما المرحلة الأخيرة التي لا بد منها قبل تسليم موضوع التعبير؟","options":["مسح الفقرات","حذف المقدمة","تغيير عنوان الموضوع","التنقيح والمراجعة الإملائية واللغوية وعلامات الترقيم"],"answer":3,"why":"التنقيح يكشف التكرار والأخطاء الإملائية."},{"type":"mcq","q":"أي علامة ترقيم توضع بين جملتين إحداهما سبب للأخرى؟","options":["الفاصلة المنقوطة (؛)","علامة الاستفهام (؟)","الشرطتان (- -)","القوسان ( )"],"answer":0,"why":"الفاصلة المنقوطة تربط السبب بالنتيجة."}],"medium":[{"type":"mcq","q":"في جملة: «تتلألأ البرك الفيروزية كالمرايا بين الصخور»، ما الجمال الفني؟","options":["ترادف","تشبيه البرك الصافية بالمرايا لشدة نقائها","استفهام","أمر"],"answer":1,"why":"تشبيه يبرز صفاء الماء وانعكاس الضوء عليه."},{"type":"mcq","q":"ما الأثر الإيجابي لترك مسافة بادئة في أول كل فقرة؟","options":["إلغاء علامات الترقيم","تقليل عدد الكلمات","تنظيم شكل النص وإبراز حدود كل فكرة بوضوح","تغيير المعنى"],"answer":2,"why":"المسافة البادئة من أصول تنظيم الفقرات."},{"type":"mcq","q":"أي جملة وظّفت «لا النافية للجنس» توظيفًا سليمًا في نص وصفي؟","options":["لا في الجبلِ منظرَ","لا المنظرُ أجملُ","بلا منظرَ أجملُ","لا منظرَ أجملُ من شروق الشمس فوق الجبل الأخضر"],"answer":3,"why":"اسمها «منظرَ» نكرة مفرد مبني على الفتح بلا فاصل."},{"type":"tfr","q":"المزج بين الجمل الاسمية (للثبات) والفعلية (للحركة) يجعل النص الوصفي أكثر حيويةً.","answer":true,"reasons":["فالجملة الاسمية تصف الثوابت والفعلية تنقل الحركة","يجب استخدام الجمل الاسمية فقط","يجب استخدام الفعل الماضي فقط"],"reason":0},{"type":"tfr","q":"لا حاجة لمراجعة النص وتنقيحه بعد الانتهاء من كتابة المسوّدة الأولى.","answer":false,"reasons":["نعم لا حاجة للمراجعة","المراجعة والتنقيح أساسيان لتصويب الإملاء وحذف التكرار وضبط الترقيم","المراجعة تضيع الوقت"],"reason":1},{"type":"essay","q":"اكتب فقرة عرض (٤–٥ أسطر) تصف فيها «واديًا عُمانيًا» موظّفًا أدوات الربط المكاني وحاستَي البصر والسمع.","model":"على امتداد الوادي تتلألأ البرك الفيروزية الصافية بين الصخور البيضاء، وفي الأعلى تتمايل أشجار النخيل الباسقة. وتحت ظلالها الوارفة ينساب الماء العذب بخرير هادئ يمتزج بزقزقة الطيور، فتشعر كأن الطبيعة تعزف لحنًا من السكينة."},{"type":"essay","q":"أضف علامات الترقيم المناسبة للفقرة الآتية: «وقفتُ على شاطئ السيب وقت الغروب فما أروع المشهد كانت الأمواج تتهادى بهدوء والطيور تعود إلى أعشاشها».","model":"وقفتُ على شاطئ السيب وقت الغروب، فما أروع المشهد! كانت الأمواج تتهادى بهدوء، والطيور تعود إلى أعشاشها."}],"hard":[{"type":"mcq","q":"ما الخطأ الذي يُنصح بتجنّبه عند كتابة المسوّدة؟","options":["تكديس النص كله في فقرة واحدة طويلة بلا نقاط أو فواصل","توظيف الحواس","استخدام تشبيهات واضحة","التخطيط المسبق"],"answer":0,"why":"تقسيم النص لفقرات يسهّل القراءة ويوضح البناء."},{"type":"mcq","q":"الجملة الاسمية في الوصف الطبيعي (مثل: السماءُ صافيةٌ) تدل غالبًا على:","options":["السرعة والاضطراب","الثبات والهدوء والدوام النسبي","التعجب فقط","الاستفهام"],"answer":1,"why":"الجملة الاسمية تفيد الثبوت والاستقرار."},{"type":"mcq","q":"أي لفظ أدقّ لوصف صوت جريان الماء في الفلج أثناء كتابة الوصف؟","options":["نباح","زئير","خرير","حفيف"],"answer":2,"why":"الخرير هو اللفظ العربي الدقيق لصوت الماء."},{"type":"mcq","q":"عند مراجعة نص وصفي وجدتَ كلمة «رائع» مكررةً ٥ مرات؛ ما التصرف الصحيح؟","options":["حذف النص كله","إضافة كلمة رائع مرة سادسة","تركها كما هي","استبدالها بألفاظ موحية وتفاصيل حسية متنوعة"],"answer":3,"why":"التنويع اللفظي يرفع جودة التعبير."},{"type":"tfr","q":"توظيف أدوات الربط المكاني يساعد القارئ على تخيّل تفاصيل المشهد بانتظام.","answer":true,"reasons":["خاص بالمسائل الرياضية","يربك القارئ","مثل: في الأفق، على اليمين، وتحت ظلال النخيل"],"reason":2},{"type":"tfr","q":"يُفضّل كتابة موضوع التعبير في فقرة واحدة متصلة دون فواصل.","answer":false,"reasons":["بل يُقسّم إلى مقدمة وعرض وخاتمة مع علامات الترقيم المناسبة","نعم فقرة واحدة أفضل","لا تُستخدم النقطة في التعبير"],"reason":0},{"type":"tfr","q":"يمكن توظيف القواعد النحوية والإملائية المدروسة داخل موضوع التعبير لرفع جودته.","answer":true,"reasons":["النحو منفصل عن التعبير","لأن التعبير هو التطبيق العملي لكل فروع اللغة","يُمنع استخدام لا النافية للجنس في التعبير"],"reason":1},{"type":"essay","q":"ما قائمة الفحص (٤ نقاط) التي تراجع بها نصك الوصفي قبل تسليمه للمعلم؟","model":"١) اكتمال المقدمة والعرض والخاتمة. ٢) توظيف الحواس والتشبيه وتجنب التكرار. ٣) سلامة الإملاء والنحو. ٤) وضع علامات الترقيم وتنظيم الفقرات."},{"type":"essay","q":"وظّف جملةً اسميةً وجملةً فعليةً معًا في وصف «سماء صلالة في الخريف».","model":"السماءُ ملتحفةٌ بالضباب الأبيض الكثيف (اسمية)، ويتساقط الرذاذُ الباردُ برفقٍ ليروي الجبالَ الخضراءَ (فعلية)."},{"type":"essay","q":"علّل: لماذا يُعدّ «التعبير» ثمرة جميع فروع اللغة العربية الأخرى؟","model":"لأنه يجمع القراءة (الأفكار والثروة اللغوية) والنحو (سلامة التركيب) والإملاء (صحة الرسم) والبلاغة (جمال التصوير) في نص واحد متكامل."}]}},
  {"id":"g9-arabic-2-u2-5","grade":"g9","subject":"arabic","term":2,"unit":2,"no":5,"title":"الاستماع: من خطاب صاحب الجلالة بمناسبة العيد الوطني السادس عشر","summary":"شرح متحرك بـ SVG لدرس الاستماع: من خطاب صاحب الجلالة بمناسبة العيد الوطني السادس عشر (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-national-day-speech-16.html","video":"","pdf":"","notes":["محور الخطاب: الإنسان العُماني المتعلّم والعمل المنتج هما أساس التنمية.","النهضة العُمانية تجمع بين الأصالة (الهوية والقيم) والمعاصرة (العلم والتقنية).","الاستماع الفعّال: إنصات + تدوين مفاتيح + انتباه للنبرة + تلخيص."],"exercises":["اذكر ثلاثة مبادئ رئيسة دعا إليها خطاب العيد الوطني السادس عشر.","اشرح المقصود بـ«التوازن بين الأصالة والمعاصرة» مع مثال من حياتنا في عُمان.","اذكر أربع آداب ومهارات للاستماع الفعّال عند سماع خطبة أو محاضرة."],"levels":{"easy":[{"type":"mcq","q":"ما المحور الرئيس الذي يؤكد عليه الخطاب السامي باعتباره الثروة الحقيقية للوطن؟","options":["إهمال التعليم","الاعتماد على الكسل","الإنسان العُماني المتعلّم والمخلص","ترك العمل المنتج"],"answer":2,"why":"بناء الإنسان وتأهيله هما أساس التنمية وغايتها."},{"type":"mcq","q":"كيف يوازن الخطاب بين الماضي والحاضر؟","options":["بالانعزال التام","بترك الهوية والتراث","برفض العلوم الحديثة","بالجمع بين التمسّك بالقيم والأصالة والأخذ بأسباب العلم الحديث"],"answer":3,"why":"الجمع الواعي بين الأصالة والمعاصرة سمة النهضة العُمانية."},{"type":"mcq","q":"ما دلالة استخدام ضمير الجماعة «إننا، وطننا» في الخطاب؟","options":["تعزيز روح الشراكة والانتماء والمسؤولية المشتركة","إبعاد المستمعين","الغموض اللغوي","التحدث عن الغائب"],"answer":0,"why":"ضمير المتكلمين يشرك جميع أبناء الوطن في البناء."},{"type":"mcq","q":"أي مما يأتي يُعدّ من مهارات الاستماع الفعّال للخطب؟","options":["الانشغال بالهاتف أثناء الاستماع","الإنصات وتدوين الكلمات المفتاحية واستخلاص الأفكار الرئيسة","مقاطعة المتحدث","حفظ النص دون فهم"],"answer":1,"why":"الإنصات وتدوين المفاتيح يضمنان الفهم العميق."}],"medium":[{"type":"mcq","q":"بأي مناسبة أُلقِي هذا الخطاب السامي؟","options":["افتتاح معرض كتاب","اليوم العالمي للغة فقط","العيد الوطني السادس عشر لسلطنة عُمان","ختام بطولة رياضية"],"answer":2,"why":"أُلقِي بمناسبة العيد الوطني السادس عشر (١٩٨٦م)."},{"type":"mcq","q":"ما موقف الخطاب من العمل في مختلف المهن الشريفة؟","options":["يقلّل من شأن المهن","يقتصر على مهنة واحدة","يشجّع على ترك العمل","يدعو الشباب للإقبال عليها بجدّ وإتقان وتقدير كل عمل منتج"],"answer":3,"why":"كل عمل شريف يسهم في نهضة الوطن محل تقدير."},{"type":"mcq","q":"من أبرز السمات الأسلوبية للخطاب السامي:","options":["جزالة الألفاظ ووضوح الأفكار والترابط المنطقي","العامية المفرطة","الغموض والتعقيد","غياب الترابط"],"answer":0,"why":"يُعد نموذجًا راقيًا لفن الخطابة العربية الفصيحة."},{"type":"tfr","q":"يؤكد الخطاب أن الثروة الحقيقية للأمة هي الإنسان المتعلم المؤهل لا الموارد المادية وحدها.","answer":true,"reasons":["بل الموارد المادية وحدها","فالإنسان هو صانع التنمية وغايتها","التعليم غير مهم للتنمية"],"reason":1},{"type":"tfr","q":"يدعو الخطاب إلى الأخذ بالعلم الحديث مع التخلي عن القيم العُمانية الأصيلة.","answer":false,"reasons":["يرفض العلم الحديث","نعم يدعو للتخلي عنها","بل يدعو إلى التوازن بين التمسّك بالأصالة والأخذ بالمعاصرة"],"reason":2},{"type":"essay","q":"اذكر ثلاثة مبادئ رئيسة دعا إليها خطاب العيد الوطني السادس عشر.","model":"١) الاهتمام ببناء الإنسان العُماني وتعليمه وتدريبه. ٢) الإقبال على العمل المنتج بإخلاص وإتقان. ٣) التوازن بين الأصالة العُمانية والأخذ بعلوم العصر."},{"type":"essay","q":"اشرح المقصود بـ«التوازن بين الأصالة والمعاصرة» مع مثال من حياتنا في عُمان.","model":"الأصالة هي الحفاظ على الدين واللغة والقيم والهوية العُمانية، والمعاصرة هي توظيف العلوم والتقنية الحديثة؛ مثل استخدام المنصات الرقمية في نشر العلم مع الالتزام بالسمت العُماني."}],"hard":[{"type":"mcq","q":"كيف يترجم طالب الصف التاسع رسالة الخطاب في حياته اليومية؟","options":["بتأجيل الواجبات","بالاجتهاد في الدراسة وإتقان العلم وخدمة مدرسته ومجتمعه","بإهدار الوقت","بعدم المشاركة"],"answer":1,"why":"الاجتهاد الدراسي هو أول خطوة لبناء الوطن."},{"type":"mcq","q":"ما أهمية «نبرة الصوت والتوكيد» أثناء الاستماع للخطبة؟","options":["تشتّت المستمع","لا فائدة منها","تساعد المستمع على تمييز الأفكار الأكثر أهمية والانفعال الصادق","تُستخدم في الشعر فقط"],"answer":2,"why":"التنغيم الصوتي يبرز مواضع التأكيد والأهمية."},{"type":"mcq","q":"بمَ ترتبط التنمية المستدامة في فكر الخطاب؟","options":["بإهمال الشباب","بالتمني دون عمل","بالاستهلاك فقط","بالتعليم والتدريب والعمل المخلص المستمر"],"answer":3,"why":"التعليم والعمل المنتج هما عماد الاستدامة."},{"type":"mcq","q":"ما الفن الأدبي الذي ينتمي إليه هذا النص؟","options":["فنّ الخطابة الوطنية","القصة الخيالية","الشعر الغنائي","المقال العلمي البحت"],"answer":0,"why":"هو خطاب وطني رسمي موجّه للجمهور."},{"type":"tfr","q":"تدوين الكلمات المفتاحية أثناء الاستماع يساعد على تلخيص الخطبة بدقة.","answer":true,"reasons":["لأنه يحفظ تسلسل الأفكار الرئيسة دون تشتت","يُفسد الاستماع","يُمنع أثناء الاستماع"],"reason":0},{"type":"tfr","q":"استخدام ضمير الجماعة «وطننا، أبناؤنا» يعزّز روح الانتماء والشراكة الوطنية.","answer":true,"reasons":["يدل على البعد","لأنه يجمع القائد والشعب في مسؤولية واحدة","لا أثر له في المعنى"],"reason":1},{"type":"tfr","q":"يقتصر دور الطالب في بناء الوطن على ما بعد التخرّج من الجامعة فقط.","answer":false,"reasons":["لا دور للطالب","نعم بعد التخرج فقط","بل يبدأ منذ الآن بالاجتهاد في طلب العلم والتحلي بالأخلاق وخدمة المجتمع"],"reason":2},{"type":"essay","q":"اذكر أربع آداب ومهارات للاستماع الفعّال عند سماع خطبة أو محاضرة.","model":"١) الإنصات باهتمام وعدم المقاطعة. ٢) تدوين الكلمات المفتاحية. ٣) ملاحظة نبرة المتحدث ومواضع التوكيد. ٤) تلخيص الأفكار الرئيسة ومناقشتها."},{"type":"essay","q":"ما أبرز السمات اللغوية والأسلوبية التي ميّزت الخطاب السامي؟","model":"فصاحة اللغة وجزالة الألفاظ، وضوح الأفكار وترابطها، وصدق العاطفة الوطنية، واستخدام ضمير الجماعة الدال على الشراكة."},{"type":"essay","q":"اكتب ثلاث خطوات عملية تبدأ بها اليوم لتكون طالبًا مساهمًا في نهضة وطنك.","model":"١) تنظيم وقتي والاجتهاد في دروسي. ٢) الحفاظ على نظافة مدرستي ومرافقها. ٣) المشاركة في المبادرات التطوعية والعلمية."}]}},
  {"id":"g9-arabic-2-u3-1","grade":"g9","subject":"arabic","term":2,"unit":3,"no":1,"title":"القراءة: عالمية الحضارة الإنسانية","summary":"شرح متحرك بـ SVG لدرس القراءة: عالمية الحضارة الإنسانية (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-universal-human-civilization.html","video":"","pdf":"","notes":["الحضارة الإنسانية بناء تراكمي مشترك بين الأمم.","الحضارة الإسلامية ترجمت ونقدت وأبدعت (الجبر، البصريات، الطب، الملاحة) ونقلت العلم للعالم.","التفاعل السليم = أخذ واعٍ وإبداع مع حفظ الهوية، لا انغلاق ولا تقليد أعمى."],"exercises":["علّل: لماذا تُوصف الحضارة الإنسانية بأنها «عالمية وتراكمية»؟","اذكر ثلاثة مجالات أبدع فيها العلماء المسلمون وأثروا في الحضارة العالمية مع مثال لعالم في كل مجال.","قارن بين «التفاعل الحضاري الواعي» و«التقليد الأعمى» و«الانغلاق»."],"levels":{"easy":[{"type":"mcq","q":"ما الفكرة المحورية في نص «عالمية الحضارة الإنسانية»؟","options":["التاريخ القديم لا علاقة له بالحاضر","الحضارة ملك لأمة واحدة فقط","التبادل الثقافي يضر بالعلم","الحضارة بناء إنساني مشترك تسهم فيه جميع الأمم بالأخذ والعطاء"],"answer":3,"why":"كل حضارة تبني على ما سبقها وتضيف إبداعها."},{"type":"mcq","q":"كيف تعامل العلماء المسلمون مع علوم الأمم السابقة؟","options":["ترجموها ونقدوها وصحّحوها وأبدعوا علومًا جديدةً فوقها","نقلوها دون فهم أو إضافة","رفضوا قراءتها تمامًا","أخفوها عن العالم"],"answer":0,"why":"تميّزوا بالنقد العلمي والإبداع مثل الجبر والبصريات."},{"type":"mcq","q":"أي مما يأتي يُعدّ من أبرز معابر انتقال العلوم العربية إلى أوروبا؟","options":["القطب الجنوبي","الأندلس وصقلية","أستراليا","أمريكا الجنوبية"],"answer":1,"why":"الأندلس وصقلية كانتا الجسر الرئيس لنقل العلوم."},{"type":"mcq","q":"ما المقصود بـ«التفاعل الحضاري الواعي»؟","options":["الانغلاق الكامل عن العالم","التقليد الأعمى لكل ما يأتي من الخارج","الاستفادة من العلوم النافعة مع الحفاظ على الهوية والقيم والإسهام بالإبداع","إهمال اللغة العربية"],"answer":2,"why":"التوازن بين الانفتاح العلمي وحفظ الهوية."}],"medium":[{"type":"mcq","q":"أي عالم مسلم أسّس علم الجبر ونُسبت إليه «الخوارزميات»؟","options":["الأصمعي","أبو الطيب المتنبي","عنترة بن شداد","محمد بن موسى الخوارزمي"],"answer":3,"why":"الخوارزمي رائد الجبر والخوارزميات."},{"type":"mcq","q":"ما المقصود بـ«التلاقح الفكري» بين الحضارات؟","options":["التفاعل الإيجابي المثمر الذي يولّد معرفةً وإبداعًا جديدًا","الصراع والحرب الدائمة","انعزال كل ثقافة وحدها","إلغاء اللغات"],"answer":0,"why":"التلاقح يعني الإخصاب والتفاعل المثمر."},{"type":"mcq","q":"كيف أسهمت سلطنة عُمان تاريخيًا في التواصل الحضاري؟","options":["بالعزلة عن البحار","عبر موانئها وأساطيلها التجارية السلمية نحو الهند والصين وشرق إفريقيا","برفض التجارة","بعدم بناء السفن"],"answer":1,"why":"كان العُمانيون سفراء للتجارة والعلم والتسامح."},{"type":"tfr","q":"الحضارة الإنسانية الحديثة قامت بجهد أمة واحدة فقط دون الاستفادة من غيرها.","answer":false,"reasons":["بدأت في القرن العشرين فقط","نعم بجهد أمة واحدة","بل هي ثمرة تراكم معرفي شاركت فيه أمم عديدة بينها الحضارة العربية الإسلامية"],"reason":2},{"type":"tfr","q":"اكتفى المسلمون بترجمة علوم اليونان والهند دون أي نقد أو إضافة علمية.","answer":false,"reasons":["بل نقدوها وصحّحوا أخطاءها وأسّسوا علومًا كالجبر والبصريات والمنهج التجريبي","نعم اكتفوا بالترجمة الحرفية","لم يترجموا شيئًا"],"reason":0},{"type":"essay","q":"علّل: لماذا تُوصف الحضارة الإنسانية بأنها «عالمية وتراكمية»؟","model":"لأنها ليست حكرًا على شعب واحد، بل تسلم كل أمة مشعل المعرفة للأخرى، فتستفيد اللاحقة من السابقة وتضيف إبداعها لصالح البشرية جمعاء."},{"type":"essay","q":"اذكر ثلاثة مجالات أبدع فيها العلماء المسلمون وأثروا في الحضارة العالمية مع مثال لعالم في كل مجال.","model":"١) الرياضيات: الخوارزمي (الجبر والخوارزميات). ٢) البصريات والفيزياء: ابن الهيثم. ٣) الطب: ابن سينا والرازي (أو الملاحة: أحمد بن ماجد)."}],"hard":[{"type":"mcq","q":"ما الخطر الناجم عن «التقليد الأعمى» للحضارات الأخرى؟","options":["تعزيز الثقة بالنفس","زيادة الابتكار العلمي","فقدان الهوية والشخصية والتحول إلى مجرد مستهلك","حفظ التراث"],"answer":2,"why":"التقليد الأعمى يضعف الإبداع والهوية."},{"type":"mcq","q":"ما نوع أسلوب نص «عالمية الحضارة الإنسانية»؟","options":["شعر غزلي","أسلوب قصصي خيالي","أسلوب هزلي ساخر","أسلوب فكري موضوعي يعتمد على الحجة والشواهد التاريخية"],"answer":3,"why":"مقالة فكرية تخاطب العقل بالبراهين."},{"type":"mcq","q":"من العالم المسلم الرائد في علم البصريات والمنهج التجريبي؟","options":["الحسن بن الهيثم","أمرؤ القيس","زهير بن أبي سلمى","جرير"],"answer":0,"why":"ابن الهيثم مؤسس علم البصريات الحديث."},{"type":"mcq","q":"كيف تعود أمتنا شريكًا فاعلًا في الحضارة العالمية المعاصرة؟","options":["بالاكتفاء بالتغني بالماضي دون عمل","بإتقان العلم والبحث والابتكار مع الالتزام بالقيم الإنسانية","بمقاطعة التقنية الحديثة","بالتقليد فقط"],"answer":1,"why":"المشاركة الحضارية تتطلب علمًا وابتكارًا وعملاً."},{"type":"tfr","q":"الانفتاح الحضاري الواعي يجمع بين اكتساب العلم الحديث والحفاظ على الهوية والقيم.","answer":true,"reasons":["يعني التقليد الأعمى","فلا انغلاق يحرمنا من التطور ولا تقليد أعمى يذيب هويتنا","يعني العزلة التامة"],"reason":1},{"type":"tfr","q":"أدّت الموانئ العُمانية دورًا مهمًا في التواصل الحضاري السلمي بين الشرق والغرب.","answer":true,"reasons":["اقتصر التواصل على الحروب","لم يكن لعُمان نشاط بحري","عبر التجارة البحرية مع الهند والصين وشرقي إفريقيا"],"reason":2},{"type":"tfr","q":"يعتمد المقال الفكري على الأدلة والشواهد المنطقية لإقناع القارئ.","answer":true,"reasons":["مع لغة واضحة وموضوعية وروابط منطقية","يعتمد على الخيال فقط","يخلو من الأدلة"],"reason":0},{"type":"essay","q":"قارن بين «التفاعل الحضاري الواعي» و«التقليد الأعمى» و«الانغلاق».","model":"التفاعل الواعي: أخذ العلوم النافعة مع حفظ الهوية والإبداع. التقليد الأعمى: اتباع الآخرين بلا تمييز مما يُفقد الهوية. الانغلاق: العزلة التي تؤدي للتخلف."},{"type":"essay","q":"كيف جسّدت سلطنة عُمان مفهوم التواصل الحضاري عبر التاريخ؟","model":"بموقعها البحري وموانئها المزدهرة (صحار وقلهات ومسقط) التي كانت مراكز لتبادل التجارة والعلوم والقيم السمحة مع الهند والصين وشرقي إفريقيا."},{"type":"essay","q":"ما الدور المطلوب من الشباب العُماني اليوم للمساهمة في الحضارة الإنسانية؟","model":"إتقان العلوم الحديثة والتقنية، والابتكار والبحث العلمي، والتمسك بالأخلاق العُمانية السمحة في تمثيل وطنهم أمام العالم."}]}},
  {"id":"g9-arabic-2-u3-2","grade":"g9","subject":"arabic","term":2,"unit":3,"no":2,"title":"الأنشطة النحوية والصرفية: تذكير الفعل وتأنيثه","summary":"شرح متحرك بـ SVG لدرس الأنشطة النحوية والصرفية: تذكير الفعل وتأنيثه (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-verb-gender-agreement.html","video":"","pdf":"","notes":["وجوب التأنيث (٢): مؤنث حقيقي متصل بالفعل، أو ضمير مستتر يعود لمؤنث (حقيقي أو مجازي).","جواز الوجهين (٣): مؤنث حقيقي مفصول، مؤنث مجازي ظاهر، جمع التكسير.","تُطبّق القواعد نفسها على الفاعل ونائب الفاعل."],"exercises":["اذكر حالتَي وجوب تأنيث الفعل مع مثال واضح لكل حالة.","اذكر ثلاث حالات لجواز تذكير الفعل وتأنيثه مع مثال لكل حالة.","فرّق بين حكم تأنيث الفعل في: «أزهرتِ الشجرةُ» و«الشجرةُ أزهرتْ» مع التعليل."],"levels":{"easy":[{"type":"mcq","q":"ما حكم تأنيث الفعل في جملة: «الشمسُ أشرقَتْ»؟","options":["واجب التأنيث (لأن الفاعل ضمير مستتر يعود لمؤنث)","جائز التأنيث والتذكير","واجب التذكير","ممتنع التأنيث"],"answer":0,"why":"الفاعل ضمير مستتر يعود على «الشمس» فيجب التأنيث حتى مع المجازي."},{"type":"mcq","q":"ما حكم تأنيث الفعل في جملة: «أشرقتِ الشمسُ»؟","options":["واجب التأنيث","جائز التأنيث والتذكير (لأن الفاعل مؤنث مجازي ظاهر)","واجب التذكير","لا يجوز تأنيثه"],"answer":1,"why":"«الشمس» اسم ظاهر مؤنث مجازي فيجوز طلعَ وطلعتْ."},{"type":"mcq","q":"ما حكم تأنيث الفعل في جملة: «نجحَتْ عائشةُ في الاختبار»؟","options":["واجب التذكير","جائز الوجهين","واجب التأنيث (مؤنث حقيقي متصل بالفعل)","ممتنع"],"answer":2,"why":"عائشة مؤنث حقيقي ولم يفصل بينه وبين الفعل فاصل."},{"type":"mcq","q":"ما حكم تأنيث الفعل في جملة: «حضرَ اليومَ المعلمةُ»؟","options":["جملة خاطئة تمامًا","واجب التذكير فقط","واجب التأنيث فقط","جائز التأنيث والتذكير لوجود فاصل بين الفعل والفاعل"],"answer":3,"why":"الفصل بـ«اليومَ» بين الفعل والمؤنث الحقيقي يجيز الوجهين."}],"medium":[{"type":"mcq","q":"أي الأسماء الآتية يُعدّ «مؤنثًا مجازيًا»؟","options":["الصحراء والدار والشمس","فاطمة والأم","الناقة والبقرة","الدجاجة والحمامة"],"answer":0,"why":"المؤنث المجازي لا يلد ولا يبيض."},{"type":"mcq","q":"في قوله تعالى ﴿قالتِ الأعرابُ آمنا﴾، ما سبب جواز تأنيث الفعل «قالت»؟","options":["لأنه مؤنث حقيقي متصل","لأن الفاعل «الأعراب» جمع تكسير","لأنه ضمير مستتر","لأنه جمع مذكر سالم"],"answer":1,"why":"جمع التكسير يجوز معه تذكير الفعل وتأنيثه."},{"type":"mcq","q":"أي الجمل الآتية يجب فيها «تذكير» الفعل؟","options":["سافرَتِ القوافلُ","أشرقتِ الشمسُ","أبدعَ المهندسونَ في المشروع","حضرَتْ في الصباحِ سلمى"],"answer":2,"why":"جمع المذكر السالم يجب معه تذكير الفعل."},{"type":"tfr","q":"إذا كان الفاعل ضميرًا مستترًا يعود على مؤنث مجازي مثل «السيارةُ انطلقَتْ» فإن تأنيث الفعل واجب.","answer":true,"reasons":["فمتى كان الفاعل ضميرًا مستترًا لمؤنث (حقيقي أو مجازي) وجب التأنيث","بل جائز الوجهين","بل يجب التذكير"],"reason":0},{"type":"tfr","q":"يجوز تذكير الفعل وتأنيثه إذا كان الفاعل جمع تكسير مثل: حضرَ/حضرَتِ الطلابُ.","answer":true,"reasons":["يجب التذكير فقط","لأن جمع التكسير يجوز تأويله بالجماعة","يجب التأنيث فقط"],"reason":1},{"type":"essay","q":"اذكر حالتَي وجوب تأنيث الفعل مع مثال واضح لكل حالة.","model":"١) إذا كان الفاعل ظاهرًا مؤنثًا حقيقيًا متصلًا بالفعل (نجحَتْ سارةُ). ٢) إذا كان الفاعل ضميرًا مستترًا يعود على مؤنث حقيقي أو مجازي (الشمسُ أشرقَتْ)."},{"type":"essay","q":"اذكر ثلاث حالات لجواز تذكير الفعل وتأنيثه مع مثال لكل حالة.","model":"١) مؤنث حقيقي مفصول بفاصل (حضرَ/حضرَتْ أمسِ مريمُ). ٢) مؤنث مجازي ظاهر (طلعَ/طلعَتِ الشمسُ). ٣) جمع تكسير (جاءَ/جاءَتِ العلماءُ)."}],"hard":[{"type":"mcq","q":"ما حكم تأنيث الفعل في: «كُرِّمَتْ الطالبةُ المتفوقةُ»؟","options":["لا علاقة لنائب الفاعل","جائز الوجهين","واجب التذكير","واجب التأنيث (نائب الفاعل مؤنث حقيقي متصل)"],"answer":3,"why":"نائب الفاعل يأخذ نفس أحكام الفاعل تمامًا."},{"type":"mcq","q":"كيف تُحوّل جملة «تفتّحَ الوردُ (الأزهارُ)» لجعل تأنيث الفعل «واجبًا»؟","options":["الأزهارُ تفتّحَتْ","تفتّحَتِ الأزهارُ","تفتّحَ في الحديقةِ الأزهارُ","ما تفتّحَ إلّا الأزهارُ"],"answer":0,"why":"بتقديم المؤنث ليصبح الفاعل ضميرًا مستترًا عائدًا عليه."},{"type":"mcq","q":"ما علامة تأنيث الفعل المضارع؟","options":["تاء ساكنة في آخره","تاء متحركة في أوله (تكتبُ)","ألف في آخره","نون في أوله"],"answer":1,"why":"المضارع يُؤنّث بالتاء في أوله، والماضي بالتاء الساكنة في آخره."},{"type":"mcq","q":"أي جملة من الآتي يجوز فيها حذف تاء التأنيث من الفعل؟","options":["فاطمةُ فازَتْ","فازَتْ فاطمةُ بالمسابقةِ","فازَتْ بالمسابقةِ فاطمةُ","الدارُ اتّسعَتْ"],"answer":2,"why":"لوجود فاصل (بالمسابقة) بين الفعل والفاعل المؤنث الحقيقي."},{"type":"tfr","q":"المؤنث الحقيقي هو كل اسم يدل على أنثى تلد أو تبيض.","answer":true,"reasons":["هو جمع التكسير","هو الجمادات فقط","مثل: الأم، المعلمة، الغزالة، الحمامة"],"reason":2},{"type":"tfr","q":"في جملة «كتبَتْ مريمُ الدرسَ» يجوز أن نقول «كتبَ مريمُ الدرسَ».","answer":false,"reasons":["التأنيث هنا واجب لأن «مريم» مؤنث حقيقي متصل بالفعل دون فاصل","نعم يجوز الوجهان","يجب التذكير"],"reason":0},{"type":"tfr","q":"أحكام تذكير الفعل وتأنيثه مع الفاعل تنطبق نفسها مع نائب الفاعل.","answer":true,"reasons":["لا تنطبق على نائب الفاعل","فالفعل المبني للمجهول يُؤنّث وجوبًا وجوازًا بنفس الشروط","المبني للمجهول يُذكّر دائمًا"],"reason":1},{"type":"essay","q":"فرّق بين حكم تأنيث الفعل في: «أزهرتِ الشجرةُ» و«الشجرةُ أزهرتْ» مع التعليل.","model":"في الأولى جائز لأن الفاعل ظاهر مؤنث مجازي (الشجرةُ). في الثانية واجب لأن الفاعل ضمير مستتر يعود على مؤنث."},{"type":"essay","q":"صوّب الخطأ النحوي في: «سافرَ ليلى إلى مسقط» و«النخلةُ أثمرَ».","model":"الصواب: سافرَتْ ليلى إلى مسقط (مؤنث حقيقي متصل ← واجب التأنيث)، والنخلةُ أثمرَتْ (ضمير مستتر لمؤنث ← واجب التأنيث)."},{"type":"essay","q":"حوّل الجملة «شاهدَ الجميعُ المباراةَ» إلى مبني للمجهول، وبيّن حكم تأنيث الفعل.","model":"شوهِدَتْ/شوهِدَ المباراةُ — حكم التأنيث جائز لأن نائب الفاعل «المباراة» مؤنث مجازي ظاهر."}]}},
  {"id":"g9-arabic-2-u3-3","grade":"g9","subject":"arabic","term":2,"unit":3,"no":3,"title":"الأنشطة الإملائية: تطبيقات على الهمزة المتطرفة","summary":"شرح متحرك بـ SVG لدرس الأنشطة الإملائية: تطبيقات على الهمزة المتطرفة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-final-hamza-applications.html","video":"","pdf":"","notes":["الهمزة المتطرفة = حركة ما قبلها فقط: كسرة→ئ، ضمة→ؤ، فتحة→أ، سكون/مد→ء.","احذر: شيء، بريء، جريء، بطيء ← على السطر بعد الياء!","تنوين النصب: سماءً (بلا ألف) | جزءًا وهدوءًا (لا يتصل) | شيئًا ودفئًا وعبئًا (يتصل ← نبرة)."],"exercises":["علّل رسم الهمزة المتطرفة في الكلمات الآتية: قَارِئ، مَبْدَأ، لُؤْلُؤ، وُضُوء.","نوّن الكلمات الآتية تنوين نصب مع بيان السبب: سماء، جزء، دفء، هواء.","صوّب الأخطاء الإملائية في الجملة: «رأيتُ شيئ جميلًا في شاطيء مسقط مساءًا»."],"levels":{"easy":[{"type":"mcq","q":"أي الكلمات الآتية كُتبت كتابةً إملائيةً صحيحةً؟","options":["شَيئ وبَريئ","شَيْء وبَرِيء","شَيأ وبَريأ","شَؤ وبَرؤ"],"answer":1,"why":"قبل الهمزة سكون/ياء مد فتُكتب مفردةً على السطر."},{"type":"mcq","q":"ما الرسم الصحيح لكلمة «سماء» عند تنوينها تنوين نصب؟","options":["سمائًا","سماءًا","سماءً","سماأً"],"answer":2,"why":"لا تقع الهمزة المتطرفة بين ألفين فنضع التنوين فوقها دون ألف."},{"type":"mcq","q":"ما الرسم الصحيح لكلمة «عِبْء» عند تنوينها تنوين نصب؟","options":["عِبْأً","عِبْءًا","عِبْءً","عِبْئًا"],"answer":3,"why":"الباء تتصل بما بعدها فتُكتب الهمزة على نبرة متصلة بألف التنوين."},{"type":"mcq","q":"ما الرسم الصحيح لكلمة «جُزْء» عند تنوينها تنوين نصب؟","options":["جُزْءًا","جُزْئًا","جُزْءً","جُزْأً"],"answer":0,"why":"الزاي لا تتصل بما بعدها فتبقى الهمزة على السطر وتُضاف الألف."}],"medium":[{"type":"mcq","q":"لماذا كُتبت الهمزة في «تَبَاطُؤ» على واو؟","options":["لأن الهمزة مضمومة","لأن الحرف الذي قبلها مضموم","لأن قبلها ساكن","لأن قبلها فتحة"],"answer":1,"why":"في الهمزة المتطرفة ننظر لحركة ما قبلها فقط."},{"type":"mcq","q":"ما سبب رسم الهمزة على ياء غير منقوطة في «شَاطِئ»؟","options":["لأن قبلها ساكن","لأن قبلها ياء مد","لأن الطاء التي قبلها مكسورة","لأنها مرفوعة"],"answer":2,"why":"الكسرة قبل الهمزة المتطرفة تناسبها الياء غير المنقوطة (ئ)."},{"type":"mcq","q":"أي جملة من الآتي تخلو تمامًا من أي خطأ إملائي؟","options":["قرأتُ جزءًا من كتابٍ مساءً، فوجدتُ شيئًا جميلاً","قرأتُ جزئًا من كتابٍ مفيدٍ مساءًا، فوجدتُ شيئ جميلًا","قرأتُ جزءً من كتابٍ مساءًا، فوجدتُ شيءًا جميلًا","قرأتُ جزءًا من كتابٍ مفيدٍ مساءً، فوجدتُ شيئًا جميلًا"],"answer":3,"why":"جزءًا (لا يتصل)، مساءً (بعد ألف بلا ألف)، شيئًا (يتصل ← نبرة)."},{"type":"tfr","q":"عند كتابة الهمزة المتطرفة ننظر إلى حركة الحرف الذي قبلها فقط دون النظر لحركة الهمزة.","answer":true,"reasons":["ننظر لحركة الهمزة فقط","فتُكتب على ياء بعد كسر، وواو بعد ضم، وألف بعد فتح، وعلى السطر بعد سكون","نقارن الحركتين كالمتوسطة"],"reason":1},{"type":"tfr","q":"تُكتب كلمة «مساء» عند تنوين النصب هكذا: «مساءًا» بألف بعد الهمزة.","answer":false,"reasons":["تُكتب مسائًا","نعم بألف بعد الهمزة","لا تُضاف ألف بعد الهمزة المسبوقة بألف؛ الصواب «مساءً»"],"reason":2},{"type":"essay","q":"علّل رسم الهمزة المتطرفة في الكلمات الآتية: قَارِئ، مَبْدَأ، لُؤْلُؤ، وُضُوء.","model":"قارئ: قبلها كسرة ← ياء. مبدأ: قبلها فتحة ← ألف. لؤلؤ: قبلها ضمة ← واو. وضوء: قبلها واو مد ساكنة ← على السطر."},{"type":"essay","q":"نوّن الكلمات الآتية تنوين نصب مع بيان السبب: سماء، جزء، دفء، هواء.","model":"سماءً (قبلها ألف فلا نضيف ألفًا). جزءًا (الزاي لا تتصل فتبقى على السطر+ألف). دفئًا (الفاء تتصل فتُكتب على نبرة+ألف). هواءً (قبلها ألف)."}],"hard":[{"type":"mcq","q":"ما مثنى كلمة «دِفْء» في حالة الرفع؟","options":["دِفْئان","دِفْءان","دِفْأن","دِفْؤن"],"answer":0,"why":"الفاء تتصل بما بعدها فتُكتب الهمزة على نبرة."},{"type":"mcq","q":"في كلمة «يَجْرُؤ» كُتبت الهمزة على واو لأن ما قبلها:","options":["مفتوح","مضموم","مكسور","ساكن"],"answer":1,"why":"الراء مضمومة فتُكتب على واو."},{"type":"mcq","q":"ما الرسم الصحيح لكلمة «هُدُوء» منصوبةً منوّنةً؟","options":["هُدُوءً","هُدُوئًا","هُدُوءًا","هُدُوأً"],"answer":2,"why":"الواو لا تتصل بما بعدها فتبقى الهمزة على السطر وتُضاف الألف."},{"type":"mcq","q":"ما القاعدة الأساسية التي تحكم رسم الهمزة المتطرفة؟","options":["نوع الكلمة اسمًا أم فعلًا","حركة الهمزة نفسها فقط","مقارنة الحركتين معًا","حركة الحرف الذي يسبقها فقط"],"answer":3,"why":"الهمزة المتطرفة تعتمد على حركة الحرف السابق لها فقط."},{"type":"tfr","q":"كلمة «بطيء» تُكتب همزتها على السطر لأن قبلها ياء مدّ ساكنة.","answer":true,"reasons":["ومثلها: جريء، بريء، مضيء","تُكتب على ياء هكذا: بطيئ","تُكتب على ألف"],"reason":0},{"type":"tfr","q":"عند تنوين «شَيْء» بالفتح تُكتب «شَيْئًا» على نبرة لأن الياء تتصل بما بعدها.","answer":true,"reasons":["تُكتب شيءًا","وكذلك دفئًا وعبئًا وبطئًا","تُكتب شيءً"],"reason":1},{"type":"tfr","q":"في كلمة «مَلْجَأ» كُتبت الهمزة على ألف لأن الجيم قبلها مفتوحة.","answer":true,"reasons":["لأنها مرفوعة","لأن اللام ساكنة","والفتحة تناسبها الألف"],"reason":2},{"type":"essay","q":"صوّب الأخطاء الإملائية في الجملة: «رأيتُ شيئ جميلًا في شاطيء مسقط مساءًا».","model":"الصواب: رأيتُ شيئًا جميلًا في شاطئ مسقط مساءً."},{"type":"essay","q":"فرّق إملائيًا بين «مُخْطِئ» و«بَطِيء» موضّحًا سبب الاختلاف.","model":"في «مُخْطِئ» قبل الهمزة طاء مكسورة فتُكتب على ياء غير منقوطة (ئ)؛ وفي «بَطِيء» قبلها ياء مد ساكنة فتُكتب على السطر بعد الياء."},{"type":"essay","q":"ثنِّ الكلمات الآتية في حالة الرفع: عِبْء، جُزْء، شاطئ.","model":"عبئان (الباء تتصل)، جزءان (الزاي لا تتصل)، شاطئان."}]}},
  {"id":"g9-arabic-2-u3-4","grade":"g9","subject":"arabic","term":2,"unit":3,"no":4,"title":"التعبير: مناقشة قضية","summary":"شرح متحرك بـ SVG لدرس التعبير: مناقشة قضية (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-discussing-an-issue.html","video":"","pdf":"","notes":["مناقشة القضية = مقدمة ← مؤيدون بأدلتهم ← معارضون بأدلتهم ← خاتمة برأي متوازن وحلول.","استخدم روابط الحجاج: في المقابل، غير أنّ، ولذلك، وخلاصة القول.","الموضوعية تعني نقد الفكرة بالدليل واحترام الرأي الآخر وتجنّب التعميم."],"exercises":["ضع مخططًا لمقال يناقش قضية «العمل التطوعي لطلاب المدارس» (مقدمة، مؤيدون، معارضون، خاتمة).","اذكر أربع عبارات ربط حجاجية تُستخدم في مقال مناقشة القضية مع وظيفة كل منها.","ما الفرق بين «الرأي المجرد» و«الحجة المقنعة»؟ أعطِ مثالًا."],"levels":{"easy":[{"type":"mcq","q":"ما السمة الأساسية التي تميّز مقال «مناقشة قضية» عن غيره؟","options":["الهجوم على المخالفين دون دليل","وصف الألوان والمناظر فقط","عرض الرأيين المؤيد والمعارض بموضوعية وأدلة ثم الترجيح المتوازن","سرد حكاية خيالية"],"answer":2,"why":"الموضوعية وتعدّد وجهات النظر بالأدلة أساس المقال النقاشي."},{"type":"mcq","q":"أي العبارات الآتية تُستخدم للانتقال من الرأي المؤيد إلى الرأي المعارض؟","options":["أولًا وقبل كل شيء...","كان يا ما كان...","في أفق السماء البعيد...","في المقابل يرى فريق آخر أنّ..."],"answer":3,"why":"«في المقابل» أداة ربط حجاجي للمقابلة بين الآراء."},{"type":"mcq","q":"ما أفضل خاتمة لمقال يناقش قضيةً خلافيةً كاستخدام الإنترنت للطلاب؟","options":["تقديم موقف متوازن يجمع الفوائد مع ضوابط وحلول عملية","تكرار المقدمة حرفيًا","شتم أحد الفريقين","ترك المقال دون نهاية"],"answer":0,"why":"الخاتمة الناجحة ترجّح حلًا عمليًا متوازنًا."},{"type":"mcq","q":"لماذا يُعدّ ذكر الأدلة والشواهد ضروريًا في مناقشة القضية؟","options":["لإطالة المقال فقط","لتحويل الرأي الشخصي إلى حجة مقنعة تخاطب العقل","لإرباك القارئ","لتجنّب ذكر الرأي الآخر"],"answer":1,"why":"الدليل هو الذي يمنح الرأي مصداقية وإقناعًا."}],"medium":[{"type":"mcq","q":"ما المبدأ الأخلاقي الأهم في أدب الحوار والمناقشة؟","options":["التعميم المطلق دون استثناء","السخرية من المخالف","نقد الفكرة بالدليل واحترام صاحب الرأي المخالف","رفع الصوت والانفعال"],"answer":2,"why":"الحوار الراقي يناقش الأفكار لا الأشخاص."},{"type":"mcq","q":"أي قضية مما يلي تصلح لمقال «مناقشة قضية»؟","options":["جدول ضرب العدد ٥","عدد أيام الأسبوع","عاصمة سلطنة عُمان","أثر الألعاب الإلكترونية على التحصيل الدراسي للطلاب"],"answer":3,"why":"القضية النقاشية هي موضوع قابل لاختلاف وجهات النظر."},{"type":"mcq","q":"ما وظيفة أداة الربط «لذلك / ومن ثمّ» في المقال النقاشي؟","options":["ربط السبب بالنتيجة والاستنتاج","وصف المكان","الاستفهام","التعجب"],"answer":0,"why":"تُستخدم للانتقال من الدليل إلى النتيجة المنطقية."},{"type":"tfr","q":"في مقال مناقشة القضية نكتفي بعرض رأينا الشخصي ونتجاهل الرأي المخالف تمامًا.","answer":false,"reasons":["نذكر المعارضين فقط","نعم نكتفي برأينا فقط","بل نعرض الرأيين بإنصاف وأدلة ثم نرجّح الموقف المتوازن"],"reason":2},{"type":"tfr","q":"استخدام روابط مثل «في المقابل، غير أنّ، لذلك» يعزّز تماسك المقال النقاشي.","answer":true,"reasons":["لأنها توضّح العلاقات المنطقية بين الآراء والأدلة","يُضعف المقال","تُستخدم في الشعر فقط"],"reason":0},{"type":"essay","q":"ضع مخططًا لمقال يناقش قضية «العمل التطوعي لطلاب المدارس» (مقدمة، مؤيدون، معارضون، خاتمة).","model":"المقدمة: أهمية التطوع وتساؤل حول أثره على الدراسة. المؤيدون: يبني الشخصية وروح الانتماء ويكسب مهارات عملية. المعارضون/المتحفظون: يخشون استهلاك وقت المذاكرة إن لم يُنظَّم. الخاتمة: التطوع مفيد جدًا عند تنظيمه في الإجازات وعطلة نهاية الأسبوع."},{"type":"essay","q":"اذكر أربع عبارات ربط حجاجية تُستخدم في مقال مناقشة القضية مع وظيفة كل منها.","model":"١) «يرى فريقٌ أنّ»: لعرض الرأي الأول. ٢) «في المقابل / غير أنّ»: للانتقال للرأي الآخر. ٣) «ولذلك / ومن ثمّ»: للاستنتاج. ٤) «وخلاصة القول»: للختام والترجيح."}],"hard":[{"type":"mcq","q":"أي عبارة تمثّل لغةً موضوعيةً هادئةً في المناقشة؟","options":["كل من يستخدم الهاتف فاشل تمامًا","تشير التجارب إلى أنّ تنظيم الوقت يقلّل من سلبيات التقنية","رأيي هو الصحيح الوحيد في العالم","المعارضون لا يفهمون شيئًا"],"answer":1,"why":"الموضوعية تتجنب التعميم والانفعال."},{"type":"mcq","q":"ما الترتيب المنطقي لفقرات مقال مناقشة قضية؟","options":["حجج المؤيدين فقط دون مقدمة","خاتمة ← مقدمة ← عرض","مقدمة ← حجج المؤيدين ← حجج المعارضين ← خاتمة وحل متوازن","أسئلة فقط دون إجابات"],"answer":2,"why":"التسلسل المنطقي يسهّل الإقناع."},{"type":"mcq","q":"من أنواع الأدلة التي تقوّي المقال النقاشي:","options":["استخدام الألوان","المبالغات الخيالية","تكرار نفس الجملة","الأمثلة الواقعية والإحصاءات والتعليل المنطقي"],"answer":3,"why":"الأدلة العقلية والواقعية والإحصائية تزيد الإقناع."},{"type":"mcq","q":"عبارة «وخلاصة القول» تُستخدم عادةً في بداية:","options":["الخاتمة","المقدمة","العنوان","المشهد الوصفي"],"answer":0,"why":"تُمهّد للخلاصة والترجيح في الخاتمة."},{"type":"tfr","q":"نقد الفكرة لا يعني الإساءة إلى صاحبها.","answer":true,"reasons":["لا فرق بين الفكرة وصاحبها","وهذا من أهم آداب الحوار والمناقشة الموضوعية","السخرية تقوّي الحجة"],"reason":1},{"type":"tfr","q":"القضية التي تصلح للمناقشة هي حقيقة علمية ثابتة لا خلاف فيها مثل دوران الأرض.","answer":false,"reasons":["العمليات الحسابية أنسب","نعم الحقائق الثابتة أنسب","بل موضوع اجتماعي أو فكري تتعدد حوله الآراء والحلول"],"reason":2},{"type":"tfr","q":"الخاتمة القوية في مقال المناقشة تقدّم توصيات وحلولًا عمليةً قابلةً للتطبيق.","answer":true,"reasons":["لتُثمر المناقشة فائدةً حقيقيةً للقارئ والمجتمع","تكتفي بكلمة شكرًا","تفتح قضيةً جديدةً"],"reason":0},{"type":"essay","q":"ما الفرق بين «الرأي المجرد» و«الحجة المقنعة»؟ أعطِ مثالًا.","model":"الرأي المجرد جملة بلا دليل (القراءة مفيدة). الحجة المقنعة مدعومة بدليل (القراءة توسّع الثروة اللغوية وتزيد درجات التعبير والفهم كما أثبتت الدراسات التربوية)."},{"type":"essay","q":"صوّب العبارة المتعصّبة الآتية لتصبح موضوعيةً: «التعلم الإلكتروني فاشل تمامًا ولا فائدة منه لأي طالب».","model":"التصويب: «رغم فوائد التعلم الإلكتروني في المرونة وتوفير المصادر، إلا أنه يواجه تحديات كضعف التفاعل المباشر إن لم يُدمج بالتعليم الصفي»."},{"type":"essay","q":"اكتب خاتمةً متوازنةً (٣ أسطر) لقضية «استخدام الذكاء الاصطناعي في مساعدة الطلاب».","model":"وخلاصة القول، إنّ الذكاء الاصطناعي أداة تعليمية واعدة إذا استُخدم للفهم والشرح والمراجعة، لكن الاعتماد الكلي عليه في حل الواجبات يُضعف مهارات الطالب؛ لذا فإن الحل الأمثل هو التوظيف الواعي تحت توجيه المعلم والأسرة."}]}},
  {"id":"g9-arabic-2-u3-5","grade":"g9","subject":"arabic","term":2,"unit":3,"no":5,"title":"النص الأدبي: اليد لا تجيد وحدها التصفيق","summary":"شرح متحرك بـ SVG لدرس النص الأدبي: اليد لا تجيد وحدها التصفيق (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-one-hand-cannot-clap.html","video":"","pdf":"","notes":["العنوان «اليد لا تجيد وحدها التصفيق» كناية عن قيمة التعاون والتآزر.","الأفكار: ضعف الفردية، قوة الاتحاد، والتحذير من الفرقة.","القيمة تتوافق مع الإسلام ﴿وتعاونوا على البر والتقوى﴾ وتراث «العونة» العُماني."],"exercises":["اشرح دلالة العنوان «اليد لا تجيد وحدها التصفيق» واربطه بموقف من حياتك المدرسية.","اذكر ثلاث فوائد للتعاون والعمل الجماعي في المجتمع.","وضّح جمال التصوير في عبارة «اليد لا تجيد وحدها التصفيق»."],"levels":{"easy":[{"type":"mcq","q":"عمّ يُكنّي عنوان القصيدة «اليد لا تجيد وحدها التصفيق»؟","options":["عن العمل الفردي المنعزل","عن أهمية التمارين الرياضية لليد","عن الصمت في المجالس","عن ضرورة التعاون وعدم قدرة الفرد على الإنجاز الكبير وحده"],"answer":3,"why":"التصفيق يحتاج يدين معًا، وهي كناية عن التعاون."},{"type":"mcq","q":"ما القيمة المركزية التي تدعو إليها القصيدة؟","options":["التعاون والتآزر والوحدة","التنافس السلبي والأنانية","العزلة عن الناس","التقليد الأعمى"],"answer":0,"why":"القصيدة كلها تدور حول فضل التعاون والوحدة."},{"type":"mcq","q":"ما أثر الفرقة والخلاف كما تحذّر منه القصيدة؟","options":["زيادة الإنتاج","تشتيت الجهود وضعف القوة وضياع الأهداف","تحقيق النصر السريع","توفير الوقت"],"answer":1,"why":"الفرقة تُضعف المجتمع وتُفشل المشاريع."},{"type":"mcq","q":"أي آية قرآنية تتوافق مباشرةً مع مضمون القصيدة؟","options":["﴿قل هو الله أحد﴾","﴿وإذا قيل لهم لا تفسدوا﴾","﴿وتعاونوا على البر والتقوى﴾","﴿اقرأ باسم ربك﴾"],"answer":2,"why":"الآية تأمر بالتعاون في الخير تمامًا كرسالة القصيدة."}],"medium":[{"type":"mcq","q":"من المظاهر التراثية العُمانية التي تجسّد معنى القصيدة:","options":["إهمال العمل الجماعي","الانعزال عن الجيران","احتكار السلع","«العونة» وتعاون أهل القرية في الأفلاج والمزارع"],"answer":3,"why":"العونة تقليد عُماني أصيل للتعاون المجتمعي."},{"type":"mcq","q":"ما الغرض البلاغي من المقابلة بين «الجماعة» و«الفردية» في النص؟","options":["توضيح المعنى وإبراز تفوّق التعاون على العزلة","إخفاء الفكرة","إطالة الأبيات بلا معنى","الانتقال لموضوع آخر"],"answer":0,"why":"بضدّها تتميّز الأشياء وتبرز القيمة."},{"type":"mcq","q":"ما نوع الأسلوب في جملة «اليد لا تجيد وحدها التصفيق»؟","options":["أسلوب استفهام","أسلوب خبري لتقرير حقيقة وحكمة عامة","أسلوب تعجب","أسلوب نداء"],"answer":1,"why":"جملة خبرية منفية تقرّر حقيقة بديهية."},{"type":"tfr","q":"عنوان القصيدة «اليد لا تجيد وحدها التصفيق» كناية بليغة عن أهمية التعاون.","answer":true,"reasons":["لأن التصفيق لا يتم إلا باجتماع اليدين معًا","يُقصد به المعنى الحرفي فقط","يدعو إلى العزلة"],"reason":0},{"type":"tfr","q":"تدعو القصيدة إلى أن يعمل كل إنسان منعزلًا عن مجتمعه ليكون أقوى.","answer":false,"reasons":["نعم تدعو للعزلة","بل تؤكد أن الفرد ضعيف بمفرده وقويّ بتعاونه مع إخوانه","التعاون يضعف الإنسان"],"reason":1},{"type":"essay","q":"اشرح دلالة العنوان «اليد لا تجيد وحدها التصفيق» واربطه بموقف من حياتك المدرسية.","model":"يدل العنوان على أن الفرد لا ينجز الأعمال العظيمة وحده، بل بتضافر الجهود؛ ومثاله في المدرسة تنظيم معرض علمي أو فريق كرة قدم لا ينجح إلا بتعاون جميع أعضائه."},{"type":"essay","q":"اذكر ثلاث فوائد للتعاون والعمل الجماعي في المجتمع.","model":"١) إنجاز الأعمال الكبيرة بوقت وجهد أقل. ٢) تبادل الخبرات وتكامل المهارات. ٣) نشر المحبة والتماسك الاجتماعي."}],"hard":[{"type":"mcq","q":"كيف تُسهم الصور الحسية المألوفة في نجاح القصيدة؟","options":["تُبعد القارئ","تعقّد الفهم","تقرّب المعنى المجرد إلى الذهن وتجعله مؤثرًا سهل التذكر","تُضعف الإيقاع"],"answer":2,"why":"الصورة المحسوسة كالتصفيق باليدين تختصر صفحات من الشرح."},{"type":"mcq","q":"ما الصفة الغالبة على لغة القصيدة وألفاظها؟","options":["العامية غير الفصيحة","الغرابة والغموض الشديد","الألفاظ العلمية البحتة","الوضوح والسلاسة وقربها من وجدان القارئ"],"answer":3,"why":"لغة شعرية حديثة واضحة ومباشرة."},{"type":"mcq","q":"كيف تطبّق رسالة القصيدة في مشروع جماعي بمدرستك؟","options":["بتوزيع المهام بعدل وتبادل الأفكار ومساعدة الزملاء","بالاستئثار بالعمل كله ورفض آراء الآخرين","بترك العمل لزميل واحد","بالخلاف المستمر"],"answer":0,"why":"العمل الجماعي الناجح يقوم على التنظيم والتكامل."},{"type":"mcq","q":"ما العلاقة بين «الوحدة» و«القوة» في فكر القصيدة؟","options":["علاقة تضاد","علاقة سبب ونتيجة (فالوحدة تصنع القوة)","لا علاقة بينهما","الوحدة تسبب الضعف"],"answer":1,"why":"الاتحاد هو السبب المباشر للقوة والإنجاز."},{"type":"tfr","q":"توظيف المقابلة بين «الاتحاد» و«الفرقة» يزيد المعنى وضوحًا وتأثيرًا.","answer":true,"reasons":["لا يُستخدم في الشعر","يُضعف المعنى","لأن الضدّ يُظهر حسن الضد"],"reason":2},{"type":"tfr","q":"تنسجم رسالة القصيدة مع قيم الإسلام والتراث العُماني كالسبلة والعونة.","answer":true,"reasons":["فالتكافل والتعاون ركيزة إسلامية وعُمانية أصيلة","تتعارض مع التراث","خاصة بمجتمع آخر"],"reason":0},{"type":"tfr","q":"الأسلوب الخبري في «اليد لا تجيد وحدها التصفيق» يهدف إلى تقرير حكمة حياتية صادقة.","answer":true,"reasons":["هو أسلوب استفهام","ليقتنع القارئ بديهيًا بضرورة التآزر","هو أسلوب نهي"],"reason":1},{"type":"essay","q":"وضّح جمال التصوير في عبارة «اليد لا تجيد وحدها التصفيق».","model":"كناية حسية جميلة عن قيمة التعاون، حيث استعار حقيقة بديهية يدركها كل إنسان ليبرهن أن النجاح ثمرة التآزر."},{"type":"essay","q":"كيف يتجلّى معنى القصيدة في التراث العُماني المعاصر والقديم؟","model":"في تقليد «العونة» الذي يتكاتف فيه أهل القرية في صيانة الأفلاج والحصاد، وفي المبادرات التطوعية الشبابية الحديثة في عُمان."},{"type":"essay","q":"أعطِ مثالين يوضّحان الفرق بين «التعاون المثمر» و«الاتكالية السلبية» في فريق العمل.","model":"التعاون المثمر: كل عضو يؤدي دوره بمسؤولية ويساعد غيره. الاتكالية السلبية: اعتماد طالب على زملائه ليكتبوا عنه الواجب دون أن يشارك."}]}},
  {"id":"g9-arabic-2-u4-1","grade":"g9","subject":"arabic","term":2,"unit":4,"no":1,"title":"القراءة: رسالة إلى ابني","summary":"شرح متحرك بـ SVG لدرس القراءة: رسالة إلى ابني (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-letter-to-my-son.html","video":"","pdf":"","notes":["الكاتب: أحمد أمين | الفن: أدب الرسائل التربوية.","ركائز النجاح في الرسالة: العقل + الحرية المسؤولة + اختيار العمل (ميل وقدرة ونفع) + السعادة في أداء الواجب.","الأسلوب: سهل ممتنع، نداء التحبب (أي بنيّ)، ومزج العاطفة بالإقناع العقلي."],"exercises":["اذكر أربع وصايا رئيسة قدّمها أحمد أمين لابنه في الرسالة.","اشرح كيف تطبّق معايير الكاتب الثلاثة عند اختيار تخصصك المستقبلي في المرحلة الثانوية والجامعة.","لماذا ربط الكاتب بين «السعادة» و«القيام بالواجب»؟"],"levels":{"easy":[{"type":"mcq","q":"من كاتب نص «رسالة إلى ابني»؟","options":["الأديب المصري أحمد أمين","طه حسين","عباس العقاد","الجاحظ"],"answer":0,"why":"الأديب والمفكّر أحمد أمين (صاحب فيض الخاطر)."},{"type":"mcq","q":"ما السلاحان العظيمان اللذان يذكّر الكاتب ابنه بأن الله منحهما له؟","options":["المال والجاه","العقل والحرية المسؤولة","السرعة والقوة الجسدية فقط","الحظ والمصادفة"],"answer":1,"why":"العقل للتمييز والحرية للاختيار المسؤول."},{"type":"mcq","q":"وفق النص، ما المعايير الثلاثة لاختيار العمل المناسب؟","options":["تقليد الأصدقاء فقط","الراتب وحده دون رغبة","الميل الشخصي، والقدرة، وفائدة المجتمع","أسهل عمل بلا جهد"],"answer":2,"why":"تجمع بين الرغبة والاستعداد وخدمة الوطن."},{"type":"mcq","q":"أين تكمن «السعادة الحقيقية» في نظر الكاتب؟","options":["في الإسراف واللهو","في الكسل والراحة الدائمة","في تجنّب كل مسؤولية","في القيام بالواجب والشعور بالإنجاز بعد العمل الشريف"],"answer":3,"why":"السعادة ثمرة الإنجاز وأداء الواجب."}],"medium":[{"type":"mcq","q":"ما الغرض البلاغي من نداء الأب لابنه بـ«أي بُنيّ»؟","options":["التحبّب والإشفاق وتهيئة النفس لقبول النصيحة","التوبيخ والغضب","التعجب","الاستفهام"],"answer":0,"why":"التصغير «بُنيّ» يفيض حنانًا ومحبةً أبويةً."},{"type":"mcq","q":"ما الفن النثري الذي ينتمي إليه النص؟","options":["المسرحية","فنّ الرسائل الأدبية التربوية","السيرة الذاتية","التقرير العلمي"],"answer":1,"why":"رسالة أدبية من أب إلى ابنه."},{"type":"mcq","q":"بمَ يتميّز أسلوب أحمد أمين في هذه الرسالة؟","options":["بالسجع المتكلّف","بالألفاظ الغريبة المعقدة","بالوضوح والسلاسة (السهل الممتنع) والمزج بين العاطفة والإقناع العقلي","بالغموض"],"answer":2,"why":"أسلوبه سلس فصيح يقنع العقل ويؤثر في القلب."},{"type":"tfr","q":"يرى أحمد أمين أن السعادة الحقيقية تكون في الكسل وتجنّب العمل الشاق.","answer":false,"reasons":["نعم في الكسل","بل في القيام بالواجب والشعور بالإنجاز بعد العمل الشريف","في جمع المال فقط"],"reason":1},{"type":"tfr","q":"استخدام صيغة التصغير «بُنيّ» يدل على المحبة والحنان الأبوي.","answer":true,"reasons":["يدل على الغضب","يدل على السخرية","ويفتح قلب الابن لتلقي النصائح برضا"],"reason":2},{"type":"essay","q":"اذكر أربع وصايا رئيسة قدّمها أحمد أمين لابنه في الرسالة.","model":"١) استثمار العقل والحرية المسؤولة. ٢) اختيار العمل وفق الميل والقدرة ونفع المجتمع. ٣) إدراك أن السعادة في أداء الواجب. ٤) التحلي بالأخلاق العملية واختيار الصديق الصالح."},{"type":"essay","q":"اشرح كيف تطبّق معايير الكاتب الثلاثة عند اختيار تخصصك المستقبلي في المرحلة الثانوية والجامعة.","model":"أبحث عن التخصص الذي أحبه (الميل)، وأملك فيه مهارة وتفوقًا (القدرة)، ويحتاج إليه وطني عُمان وسوق العمل (نفع المجتمع)."}],"hard":[{"type":"mcq","q":"كيف ينظر الكاتب إلى «الأخلاق» في رسالته؟","options":["خاصة بكبار السن","قواعد للحفظ في الاختبار فقط","شيء ثانوي بعد المال","سلوك عملي يظهر في الصدق والمعاملة لا مجرد كلام نظري"],"answer":3,"why":"الأخلاق الحقيقية تُترجم إلى أفعال ومواقف."},{"type":"mcq","q":"ما الغرض البلاغي من أساليب الأمر والنهي في الرسالة؟","options":["النصح والإرشاد والتحذير المشفق","الإلزام القسري والتهديد","التعجيز","التمني"],"answer":0,"why":"أمر الأب لابنه في الرسالة غرضه النصح والإرشاد."},{"type":"mcq","q":"لماذا يرفض الكاتب الاستسلام لفكرة «الحظ والظروف»؟","options":["لأن الظروف لا وجود لها","لأن الإنسان مسؤول عن صناعة مستقبله بعقله وإرادته واجتهاده","لأن العمل غير مهم","لأن الحرية بلا حدود"],"answer":1,"why":"يدعو للإيجابية وتحمّل المسؤولية."},{"type":"mcq","q":"ما أثر «الصديق الصالح» كما توحيه الوصايا التربوية؟","options":["يُضعف الطموح","لا أثر للصديق على الإنسان","يعين على الخير والاجتهاد ويرتقي بأخلاق صاحبه","يمنع النجاح"],"answer":2,"why":"الصاحب يؤثر بعمق في السلوك والطموح."},{"type":"tfr","q":"ينصح الكاتب باختيار المهنة حسب تقليد الأصدقاء بغضّ النظر عن الميل والقدرة.","answer":false,"reasons":["بل وفق الميل والقدرة وفائدة المجتمع","نعم حسب تقليد الأصدقاء","بالقرعة العشوائية"],"reason":0},{"type":"tfr","q":"جمع الكاتب في رسالته بين العاطفة الأبوية الصادقة والحجة العقلية المقنعة.","answer":true,"reasons":["خلت من العاطفة","مما جعل نصائحه مؤثرة ومقنعة للشباب","خلت من التعليل"],"reason":1},{"type":"tfr","q":"الحرية في فكر الكاتب تعني التفلّت من الواجبات وعدم الالتزام بأي قاعدة.","answer":false,"reasons":["تعني إهمال الدراسة","نعم بلا أي ضابط","بل هي حرية مسؤولة منضبطة بالعقل والأخلاق"],"reason":2},{"type":"essay","q":"لماذا ربط الكاتب بين «السعادة» و«القيام بالواجب»؟","model":"لأن الكسل يورث الملل والفراغ، بينما إتقان الواجب يبعث في النفس الرضا والثقة والفرح بالإنجاز."},{"type":"essay","q":"استخرج سمتين أسلوبيتين من رسالة أحمد أمين مع مثال لكل سمة.","model":"١) النداء للتحبب («أي بنيّ»). ٢) السهولة والوضوح والمزج بين الأمر للنصح والتعليل العقلي."},{"type":"essay","q":"اكتب فقرة قصيرة (٣ أسطر) توجه فيها نصيحةً لأخيك الأصغر بأسلوب «رسالة إلى ابني».","model":"أي أخي العزيز، اجعل من وقتك كنزًا لا يُهدر، وابحث عن سعادتك في إتقان دروسك ومساعدة أسرتك؛ فالعقل والاجتهاد هما جناحاك للوصول إلى أحلامك."}]}},
  {"id":"g9-arabic-2-u4-2","grade":"g9","subject":"arabic","term":2,"unit":4,"no":2,"title":"الأنشطة النحوية والصرفية: اسم الفاعل","summary":"شرح متحرك بـ SVG لدرس الأنشطة النحوية والصرفية: اسم الفاعل (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-ism-al-fail.html","video":"","pdf":"","notes":["الثلاثي ← فاعِل (كاتِب، قائل، آخِذ، مادّ، قاضٍ).","غير الثلاثي ← مُـ + كسر ما قبل الآخر (مُعلِّم، مُجتهِد، مُستخرِج).","في الناقص (قاضٍ): تُحذف الياء نكرةً رفعًا وجرًا، وتثبت نصبًا ومع «ال» والإضافة."],"exercises":["صُغ اسم الفاعل من الأفعال الآتية مع الضبط: شَكَرَ، نامَ، أخلَصَ، استقبَلَ، سعى.","علّل حذف الياء في «هذا رامٍ ماهرٌ» وإثباتها في «رأيتُ راميًا ماهرًا».","استخرج أسماء الفاعلين واذكر فعل كل منها: «المعلّمُ المخلصُ ساعٍ لبناءِ جيلٍ واعٍ ومُنتِجٍ»."],"levels":{"easy":[{"type":"mcq","q":"ما اسم الفاعل من الفعل الثلاثي الأجوف «صامَ»؟","options":["مَصوم","صائِم","مُصيم","صوّام"],"answer":1,"why":"تُقلب ألف الأجوف همزةً على نبرة: صائم."},{"type":"mcq","q":"ما اسم الفاعل من الفعل غير الثلاثي «استغفرَ»؟","options":["مُستغفَر","غافِر","مُستغفِر","غفور"],"answer":2,"why":"من غير الثلاثي: ميم مضمومة وكسر ما قبل الآخر (مُستغفِر)."},{"type":"mcq","q":"أكمل الجملة بالصياغة الصحيحة: «مررتُ بـ ...... إلى الخير»:","options":["مدعوّ","داعي","داعيًا","داعٍ"],"answer":3,"why":"اسم فاعل ناقص نكرة في حالة جر فتُحذف ياؤه ويُنوّن بالكسر."},{"type":"mcq","q":"ما الفعل الذي اشتُقّ منه اسم الفاعل «مُكرِم»؟","options":["أكرَمَ (رباعي)","كرُمَ (ثلاثي)","تكرّمَ","استكرمَ"],"answer":0,"why":"بما أنه يبدأ بميم مضمومة فهو من غير الثلاثي (أكرم ← يُكرم ← مُكرِم)."}],"medium":[{"type":"mcq","q":"ما اسم الفاعل من الفعل «أخَذَ»؟","options":["مأخوذ","آخِذ","مُؤخِذ","أخّاذ"],"answer":1,"why":"همزة + ألف فاعل تُدمجان في همزة مد: آخِذ."},{"type":"mcq","q":"ما اسم الفاعل من الفعل الثلاثي المضعّف «شَدَّ»؟","options":["مُشِدّ","مشدود","شادّ","شديد"],"answer":2,"why":"يبقى التضعيف على وزن فاعل: شادّ."},{"type":"mcq","q":"أكمل الجملة: «رأيتُ ...... عادلًا في المحكمة»:","options":["مقضيًا","قاضٍ","قاضي","قاضيًا"],"answer":3,"why":"في حالة النصب تثبت الياء مع تنوين الفتح: قاضيًا."},{"type":"tfr","q":"يُصاغ اسم الفاعل من الفعل غير الثلاثي بإبدال حرف المضارعة ميمًا مضمومةً وفتح ما قبل الآخر.","answer":false,"reasons":["بميم مفتوحة","نعم بفتح ما قبل الآخر","بل بـ«كسر» ما قبل الآخر (فتح ما قبل الآخر لاسم المفعول)"],"reason":2},{"type":"tfr","q":"تُحذف ياء اسم الفاعل المشتق من الثلاثي الناقص (مثل قاضٍ) إذا كان نكرةً مرفوعًا أو مجرورًا.","answer":true,"reasons":["ويُعوّض عنها بتنوين الكسر: جاء قاضٍ، سلمتُ على قاضٍ","تُحذف في النصب فقط","لا تُحذف أبدًا"],"reason":0},{"type":"essay","q":"صُغ اسم الفاعل من الأفعال الآتية مع الضبط: شَكَرَ، نامَ، أخلَصَ، استقبَلَ، سعى.","model":"شاكِر، نائِم، مُخلِص، مُستقبِل، ساعٍ (أو الساعي)."},{"type":"essay","q":"علّل حذف الياء في «هذا رامٍ ماهرٌ» وإثباتها في «رأيتُ راميًا ماهرًا».","model":"في الأولى نكرة مرفوع فتُحذف الياء ويُنوّن بالكسر، وفي الثانية منصوب فتثبت الياء."}],"hard":[{"type":"mcq","q":"أي الكلمات الآتية يُعدّ اسم فاعل من فعل ثلاثي؟","options":["الكاتِبات","المُعلِّمون","المُجتهِد","المُستخرِج"],"answer":0,"why":"مفردها كاتبة على وزن فاعلة من الثلاثي كتبَ."},{"type":"mcq","q":"ما وزن اسم الفاعل «ساعٍ» بعد حذف الياء؟","options":["فاعِل","فاعٍ","مُفعِل","فَعيل"],"answer":1,"why":"حُذفت لام الكلمة (الياء) فيُحذف ما يقابلها في الميزان: فاعٍ."},{"type":"mcq","q":"في جملة «أنا مُختارٌ صديقي بعناية»، كلمة «مُختار» تُعدّ:","options":["مصدرًا ميميًا","اسم مفعول","اسم فاعل (لأنه دلّ على من قام بالاختيار)","ظرف مكان"],"answer":2,"why":"السياق يدل على أن المتكلم هو الذي قام بالاختيار."},{"type":"mcq","q":"ما اسم الفاعل من الفعل «تعلّمَ»؟","options":["مُعلِّم","عالِم","معلوم","مُتعلِّم"],"answer":3,"why":"تعلّمَ ← يتعلّم ← مُتعلِّم (بميم مضمومة وكسر ما قبل الآخر)."},{"type":"tfr","q":"اسم الفاعل من الفعل «باعَ» هو «بائِع» بقلب الألف همزةً.","answer":true,"reasons":["هو بايِع","وهكذا في كل ثلاثي أجوف كقال وقائل ونام ونائم","هو مَبيع"],"reason":1},{"type":"tfr","q":"يُعرب اسم الفاعل فاعلًا دائمًا في كل الجمل.","answer":false,"reasons":["يُعرب مفعولًا به دائمًا","نعم فاعلًا دائمًا","بل يُعرب حسب موقعه في الجملة (مبتدأ، خبر، فاعل، مفعول به...)"],"reason":2},{"type":"tfr","q":"الفعل «مُجتهِد» مشتق من فعل خماسي هو «اجتهدَ».","answer":true,"reasons":["اجتهد ← يجتهد ← مُجتهِد","مشتق من ثلاثي جهد","مشتق من رباعي"],"reason":0},{"type":"essay","q":"استخرج أسماء الفاعلين واذكر فعل كل منها: «المعلّمُ المخلصُ ساعٍ لبناءِ جيلٍ واعٍ ومُنتِجٍ».","model":"المعلّم (علّم)، المخلص (أخلص)، ساعٍ (سعى)، واعٍ (وعى)، مُنتِج (أنتج)."},{"type":"essay","q":"فرّق بين «مُعلِّم» و«عالِم» من حيث الفعل الذي اشتُقّ منه كل منهما وطريقة الصياغة.","model":"«عالِم» من الثلاثي «عَلِمَ» على وزن فاعل؛ أما «مُعلِّم» فمن الرباعي «علّمَ» بميم مضمومة وكسر ما قبل الآخر."},{"type":"essay","q":"وظّف كلمة «مُحتلّ» في جملتين بحيث تكون في الأولى اسم فاعل وفي الثانية اسم مفعول.","model":"اسم فاعل: قاوم الشعبُ العدوَّ المحتلَّ (هو الذي احتل). اسم مفعول: الأرضُ المحتلّةُ ستعودُ لأهلها (وقع عليها الاحتلال)."}]}},
  {"id":"g9-arabic-2-u4-3","grade":"g9","subject":"arabic","term":2,"unit":4,"no":3,"title":"الأنشطة الإملائية: تطبيقات على همزتَي الوصل والقطع","summary":"شرح متحرك بـ SVG لدرس الأنشطة الإملائية: تطبيقات على همزتَي الوصل والقطع (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-wasl-qat-applications.html","video":"","pdf":"","notes":["اختبار «وَ»: سقطت الهمزة ← وصل (ا) | ظهرت ← قطع (أ/إ).","الأفعال: ٤ قطع دائمًا | ٥ و٦ وصل دائمًا | أمر ٣ وصل | مضارع المتكلم قطع.","الأسماء كلها قطع عدا ٩ (اسم، ابن، ابنة، امرؤ، امرأة، اثنان، اثنتان...)، والحروف كلها قطع عدا «ال»."],"exercises":["صنّف الكلمات الآتية إلى همزة وصل وهمزة قطع مع التعليل: إكرام، انطلاق، اكتبْ، أستعملُ، اثنان.","صوّب الأخطاء الإملائية في الجملة: «إستقبلَ أحمدُ إبنَ عمّه إستقبالًا رائعًا، وابدأ بمساعدته».","اشرح قاعدة الأفعال (٣، ٤، ٥، ٦) في همزتَي الوصل والقطع في جدول مختصر."],"levels":{"easy":[{"type":"mcq","q":"أي الكلمات الآتية همزتها «همزة وصل»؟","options":["أحمد وأكرم وإنسان","إكرام وإحسان وإلى","استخدام واجتهاد واسم","أكتبُ وأستغفرُ"],"answer":2,"why":"استخدام (مصدر سداسي)، اجتهاد (مصدر خماسي)، اسم (من الأسماء التسعة)."},{"type":"mcq","q":"ما سبب كتابة همزة القطع في كلمة «إِحسان»؟","options":["لأنها حرف","لأنها مصدر خماسي","لأنها أمر ثلاثي","لأنها مصدر لفعل رباعي (أحسنَ)"],"answer":3,"why":"الفعل الرباعي ومصدره وأمره همزتها قطع دائمًا."},{"type":"mcq","q":"أي الجمل الآتية كُتبت جميع همزاتها كتابةً صحيحةً؟","options":["اجتهدْ في دروسك، وأحسنْ إلى والديك، واستمعْ لنصح معلمك","إجتهدْ في دروسك، واحسنْ إلى والديك، وإستمعْ لنصح معلمك","اجتهدْ في دروسك، وأحسنْ الى والديك، وإستمعْ لنصح معلمك","أجتهدْ في دروسك، وأحسنْ إلى والديك، واستمعْ لنصح معلمك"],"answer":0,"why":"اجتهد (أمر خماسي: وصل)، أحسن (أمر رباعي: قطع)، استمع (أمر خماسي: وصل)."},{"type":"mcq","q":"لماذا كُتبت الهمزة همزة قطع في «أَستغفرُ الله» رغم أن الفعل سداسي؟","options":["لأنه أمر سداسي","لأنه فعل مضارع مبدوء بهمزة المتكلم (أنا)","لأنه ماضٍ سداسي","لأنه مصدر"],"answer":1,"why":"همزة المضارعة للمتكلم قطع دائمًا في كل الأفعال."}],"medium":[{"type":"mcq","q":"ما نوع الهمزة في فعل الأمر الثلاثي «اقرأْ» و«اكتبْ»؟","options":["همزة مد","همزة قطع","همزة وصل","همزة متطرفة"],"answer":2,"why":"أمر الفعل الثلاثي همزته وصل."},{"type":"mcq","q":"أي الأسماء الآتية همزته «همزة وصل»؟","options":["أرض وأسد","أبناء وأسماء","إبراهيم وأحمد","امرأة واثنان وابن"],"answer":3,"why":"الأسماء التسعة السماعية (اسم، ابن، ابنة، امرؤ، امرأة، اثنان، اثنتان...) وصل."},{"type":"mcq","q":"كلمة «أَبناء» (جمع ابن) همزتها:","options":["همزة قطع (لأن الجمع لا يتبع استثناء المفرد)","همزة وصل","لا همزة فيها","همزة متوسطة"],"answer":0,"why":"ابن وابنان وصل، أما الجمع «أبناء» فقطع!"},{"type":"tfr","q":"الفعل الرباعي (ماضيه وأمره ومصدره) همزته همزة قطع دائمًا.","answer":true,"reasons":["مثل: أكرَمَ، أكرِمْ، إكرامًا","همزته وصل دائمًا","أمره فقط وصل"],"reason":0},{"type":"tfr","q":"تُكتب كلمة «استقبال» بهمزة قطع هكذا: «إستقبال».","answer":false,"reasons":["نعم بهمزة قطع","هي مصدر سداسي همزته وصل: استقبال (بلا همزة)","تُكتب أستقبال"],"reason":1},{"type":"essay","q":"صنّف الكلمات الآتية إلى همزة وصل وهمزة قطع مع التعليل: إكرام، انطلاق، اكتبْ، أستعملُ، اثنان.","model":"وصل: انطلاق (مصدر خماسي)، اكتبْ (أمر ثلاثي)، اثنان (من الأسماء التسعة). قطع: إكرام (مصدر رباعي)، أستعملُ (مضارع للمتكلم)."},{"type":"essay","q":"صوّب الأخطاء الإملائية في الجملة: «إستقبلَ أحمدُ إبنَ عمّه إستقبالًا رائعًا، وابدأ بمساعدته».","model":"الصواب: استقبلَ أحمدُ ابنَ عمّه استقبالًا رائعًا، وابدأْ بمساعدته (استقبل واستقبال سداسيان وصل، وابن وصل، وابدأ أمر ثلاثي وصل)."}],"hard":[{"type":"mcq","q":"الحرف الوحيد في اللغة العربية الذي همزته «وصل» هو:","options":["إلى","ال التعريف","إنّ","أو"],"answer":1,"why":"جميع الحروف قطع عدا «ال» التعريف."},{"type":"mcq","q":"ما الرسم الصحيح لمصدر الفعل «انطلقَ»؟","options":["أنطلاق","إنطلاق (قطع)","انطلاق (وصل)","نطلاق"],"answer":2,"why":"مصدر الفعل الخماسي همزته وصل."},{"type":"mcq","q":"ما نوع الهمزة في كلمة «إِدارة»؟","options":["حرف","همزة وصل (خماسي)","همزة وصل (ثلاثي)","همزة قطع (مصدر رباعي من أدارَ)"],"answer":3,"why":"أدارَ رباعي ← مصدره إدارة همزته قطع."},{"type":"mcq","q":"للتفريق السريع بين همزة الوصل والقطع نضع قبل الكلمة:","options":["حرف الواو أو الفاء ثم ننطقها","حرف الميم","ال التعريف","تاء التأنيث"],"answer":0,"why":"إذا اختفت في النطق بعد الواو فهي وصل، وإذا ظهرت فهي قطع."},{"type":"tfr","q":"جميع الحروف المبدوءة بهمزة همزتها قطع عدا «ال» التعريف.","answer":true,"reasons":["إلى همزتها وصل","كل الحروف وصل","مثل إلى، إنّ، أو، إلّا (قطع) مقابل الكتاب (وصل)"],"reason":2},{"type":"tfr","q":"فعل الأمر من الثلاثي (مثل: اكتبْ، اجلسْ) همزته همزة قطع.","answer":false,"reasons":["بل همزة وصل (اكتبْ، اجلسْ)","نعم همزة قطع","فقط إذا كان معتلًا"],"reason":0},{"type":"tfr","q":"كلمة «انتصار» إذا سُمّيت بها فتاة (عَلَمًا) تُكتب بهمزة قطع: إنتصار.","answer":true,"reasons":["تبقى وصلًا دائمًا","لأنها نُقلت من المصدرية إلى العلمية، والأعلام قطع","تُحذف ألفها"],"reason":1},{"type":"essay","q":"اشرح قاعدة الأفعال (٣، ٤، ٥، ٦) في همزتَي الوصل والقطع في جدول مختصر.","model":"الثلاثي: ماضيه ومصدره قطع وأمره وصل. الرباعي: ماضيه وأمره ومصدره قطع. الخماسي والسداسي: ماضيهما وأمرهما ومصدرهما وصل. مضارع المتكلم: قطع دائمًا."},{"type":"essay","q":"علّل اختلاف الهمزة بين «ابن» و«أبناء»، وبين «استمعَ» و«أستمعُ».","model":"«ابن» من الأسماء التسعة فوصل، وجمعه «أبناء» قطع. «استمعَ» ماضٍ خماسي فوصل، و«أستمعُ» مضارع للمتكلم فقطع."},{"type":"essay","q":"اكتب ثلاث جمل مفيدة من إنشائك تحتوي كل منها على همزة وصل وهمزة قطع معًا.","model":"١) استمعْ إلى نصيحة أبيك. ٢) أكرَمَ العُمانيون الضيفَ إكرامًا عظيمًا. ٣) انطلقَ أحمدُ إلى المدرسةِ مبكرًا."}]}},
  {"id":"g9-arabic-2-u4-4","grade":"g9","subject":"arabic","term":2,"unit":4,"no":4,"title":"التعبير: كيفية كتابة التقرير","summary":"شرح متحرك بـ SVG لدرس التعبير: كيفية كتابة التقرير (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-how-to-write-report.html","video":"","pdf":"","notes":["عناصر التقرير: عنوان + مقدمة (ماذا/متى/أين/من/لماذا) + وقائع متسلسلة + إيجابيات وتحديات + توصيات + اسم وتاريخ.","لغة التقرير: موضوعية، دقيقة بالأرقام، موجزة، ومحايدة.","الأمانة في ذكر الإيجابيات والتحديات والتوصيات تصنع قيمة التقرير."],"exercises":["اذكر العناصر الستة الأساسية لبناء التقرير بالترتيب الصحيح.","قارن في جدول بين «التقرير» و«المقال الوصفي الأدبي» من حيث: الهدف، اللغة، والعاطفة.","صُغ مقدمةً نموذجيةً (٣ أسطر) لتقرير عن «ورشة البرمجة في مختبر الحاسوب بالمدرسة»."],"levels":{"easy":[{"type":"mcq","q":"ما السمة اللغوية الأهم التي تميّز «التقرير» عن النص الأدبي الوصفي؟","options":["سرد أحداث خيالية","كثرة التشبيهات والعاطفة المبالغ فيها","استخدام القافية والوزن","الموضوعية والدقة والاعتماد على الحقائق والأرقام دون خيال"],"answer":3,"why":"التقرير كتابة وظيفية تنقل الواقع بدقة وموضوعية."},{"type":"mcq","q":"أي الأسئلة الآتية تُجيب عنها «مقدمة التقرير»؟","options":["ماذا؟ متى؟ أين؟ من المشاركون؟ ولماذا؟","ما رأي الشعراء في المكان؟","كيف أُعرب الفعل الماضي؟","ما التوصيات النهائية فقط؟"],"answer":0,"why":"المقدمة تحدد الإطار الزمني والمكاني والهدف والمشاركين."},{"type":"mcq","q":"كيف يُفضّل عرض الوقائع في «صلب التقرير»؟","options":["بعشوائية ودون ترتيب","بتسلسل زمني منطقي ونقاط واضحة وحقائق دقيقة","في جملة واحدة طويلة","بإخفاء الأرقام"],"answer":1,"why":"التسلسل الزمني والتعداد النقطي يسهّلان قراءة التقرير."},{"type":"mcq","q":"ما الفائدة من ذكر «التوصيات والمقترحات» في نهاية التقرير؟","options":["انتقاد الأشخاص","إطالة عدد الصفحات فقط","تقديم حلول عملية لتطوير العمل وتفادي الصعوبات مستقبلًا","إعادة كتابة المقدمة"],"answer":2,"why":"التوصيات تحوّل التقرير إلى أداة تطوير حقيقية."}],"medium":[{"type":"mcq","q":"ماذا يُكتب في ختام التقرير الرسمي أسفل الصفحة؟","options":["لا يُكتب أي توثيق","بيت شعر عن الغروب","قائمة أمنيات","اسم مُعدّ التقرير وصفته وتاريخ الإعداد"],"answer":3,"why":"التوثيق بالاسم والصفة والتاريخ يمنح التقرير رسمية وموثوقية."},{"type":"mcq","q":"أي العبارات الآتية أنسب لأسلوب التقرير الرسمي؟","options":["شارك ٣٥ طالبًا في الورشة التي استمرت ساعتين وحققت تفاعلًا ملحوظًا","كانت الورشة كالحلم الجميل الذي يطير بنا في السماء","يا لها من رحلة أسطورية لا مثيل لها!","أظن أن العدد كان كبيرًا جدًا ربما ألف طالب"],"answer":0,"why":"الأولى دقيقة بالأرقام ومحايدة ومباشرة."},{"type":"mcq","q":"هل يُذكر في التقرير الصعوبات أو السلبيات التي واجهت النشاط؟","options":["لا تُذكر أبدًا","نعم بأدب وموضوعية بهدف معالجتها مستقبلًا","تُذكر بأسلوب جارح وشخصي","يُكتفى بالسلبيات فقط"],"answer":1,"why":"الأمانة الموضوعية تقتضي ذكر الإيجابيات والتحديات."},{"type":"tfr","q":"يقوم التقرير الناجح على الخيال الواسع وكثرة الاستعارات الشعرية.","answer":false,"reasons":["نعم على الخيال","بل على الحقائق والأرقام والموضوعية والإيجاز","يجمع الشعر والنثر"],"reason":1},{"type":"tfr","q":"تُجيب مقدمة التقرير عن: متى وأين تمّ النشاط ومن شارك فيه وما هدفه.","answer":true,"reasons":["تُترك فارغة","تذكر التوصيات فقط","لتضع القارئ فورًا في صورة الإطار الكامل للحدث"],"reason":2},{"type":"essay","q":"اذكر العناصر الستة الأساسية لبناء التقرير بالترتيب الصحيح.","model":"١) العنوان الدقيق. ٢) المقدمة (الزمان، المكان، المشاركون، الهدف). ٣) عرض الوقائع والأنشطة بتسلسل زمني. ٤) الإيجابيات والتحديات. ٥) النتائج والتوصيات. ٦) اسم مُعدّ التقرير وصفته والتاريخ."},{"type":"essay","q":"قارن في جدول بين «التقرير» و«المقال الوصفي الأدبي» من حيث: الهدف، اللغة، والعاطفة.","model":"التقرير: هدفه نقل حقائق وتقييم عمل، لغته مباشرة وموجزة بأرقام، وموضوعي بلا عاطفة زائدة. المقال الوصفي: هدفه التصوير والإمتاع، لغته موحية بصور فنية، وتظهر فيه عاطفة الكاتب."}],"hard":[{"type":"mcq","q":"أي مما يأتي يُعدّ عنوانًا دقيقًا ومناسبًا لتقرير مدرسي؟","options":["يوم في حياتي","رحلة رائعة جدًا!","تقرير عن زيارة طلاب الصف التاسع إلى متحف عُمان عبر الزمان","موضوع عام"],"answer":2,"why":"العنوان الدقيق يحدد موضوع التقرير والفئة والمكان."},{"type":"mcq","q":"من أنواع التقارير الشائعة في الحياة العملية والمدرسية:","options":["حكاية شعبية","قصيدة رثاء","رواية بوليسية","تقرير زيارة، تقرير نشاط، تقرير علمي أو إداري"],"answer":3,"why":"التقرير يشمل الزيارات والأنشطة والدراسات الإدارية والعلمية."},{"type":"mcq","q":"لماذا يُنصح بتجنّب المبالغة والألفاظ العاطفية في التقرير؟","options":["لأنها تُضعف مصداقية التقرير وموضوعيته","لأنها تجعل التقرير أقصر","لأنها مطلوبة في التقارير فقط","لأنها تزيد الدقة"],"answer":0,"why":"المصداقية تقوم على الوقائع الموثّقة لا الانفعال."},{"type":"mcq","q":"أي عنصر يأتي مباشرةً بعد عرض الوقائع والإيجابيات والتحديات في التقرير؟","options":["العنوان","النتائج والتوصيات والمقترحات","المقدمة","تحديد المكان"],"answer":1,"why":"النتائج والتوصيات تُبنى على ما رُصد في العرض."},{"type":"tfr","q":"ذكر الصعوبات والتحديات بأسلوب موضوعي مع توصيات لعلاجها يرفع قيمة التقرير.","answer":true,"reasons":["لأنه يساعد الجهة المسؤولة على تحسين الأداء مستقبلًا","يُفسد التقرير","يُعدّ خطأً إداريًا"],"reason":0},{"type":"tfr","q":"كتابة اسم مُعدّ التقرير والتاريخ في نهايته خطوة ضرورية لتوثيقه.","answer":true,"reasons":["غير مطلوبة أبدًا","حتى يُعرف مصدر المعلومات وتاريخ رصدها","تُكتب في العنوان فقط"],"reason":1},{"type":"tfr","q":"يُفضّل ترتيب وقائع التقرير ترتيبًا زمنيًا متسلسلًا وبنقاط منظمة.","answer":true,"reasons":["تُكتب كلها في سطر واحد","الترتيب العشوائي أفضل","لتسهيل القراءة السريعة وفهم سير الأحداث بدقة"],"reason":2},{"type":"essay","q":"صُغ مقدمةً نموذجيةً (٣ أسطر) لتقرير عن «ورشة البرمجة في مختبر الحاسوب بالمدرسة».","model":"في يوم الثلاثاء الموافق ١٥ مارس، نظّم النادي العلمي بمدرستنا ورشةً تدريبيةً في أساسيات البرمجة بمختبر الحاسوب، بمشاركة ٣٠ طالبًا من الصف التاسع، بهدف تنمية مهارات التفكير المنطقي والبرمجي لديهم."},{"type":"essay","q":"اكتب توصيتين عمليتين يمكن إدراجهما في نهاية تقرير عن «رحلة مدرسية إلى متحف عُمان عبر الزمان».","model":"١) زيادة مدة الزيارة ساعةً إضافيةً لإتاحة وقت أطول لاستكشاف القاعات التفاعلية. ٢) تكليف الطلاب بملخص معرفي مصوّر لتعميم الفائدة في الإذاعة المدرسية."},{"type":"essay","q":"لماذا تُعدّ «الموضوعية والأمانة» أهم صفة في كاتب التقرير؟","model":"لأن القرارات الإدارية أو التربوية تُبنى على ما ورد في التقرير، فإذا شابه تحيّز أو مبالغة أدّى إلى قرارات خاطئة."}]}},
  {"id":"g9-arabic-2-u4-5","grade":"g9","subject":"arabic","term":2,"unit":4,"no":5,"title":"الاستماع: من مخاطر التلوث الكيميائي (حرق القمامة في الأحياء السكنية)","summary":"شرح متحرك بـ SVG لدرس الاستماع: من مخاطر التلوث الكيميائي (حرق القمامة في الأحياء السكنية) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-chemical-pollution-burning-waste.html","video":"","pdf":"","notes":["حرق القمامة يطلق سمومًا كيميائية (CO، ديوكسينات، جسيمات دقيقة) تضر التنفس والبيئة.","الأشد تضررًا: الأطفال، مرضى الربو، وكبار السن.","الحل الحضاري: الفرز + إعادة التدوير + المرادم الهندسية الآمنة، عملًا بقاعدة «لا ضرر ولا ضرار»."],"exercises":["اذكر ثلاثة أضرار صحية وبيئية ناتجة عن حرق القمامة في الأحياء السكنية.","اقترح ثلاثة حلول عملية للحد من ظاهرة حرق النفايات في مجتمعك المحلي.","فسّر لماذا يكون حرق «البلاستيك والبطاريات» أخطر بكثير من حرق أوراق الشجر الجافة."],"levels":{"easy":[{"type":"mcq","q":"ما الخطر الرئيس لحرق النفايات البلاستيكية والمنزلية في الأحياء السكنية؟","options":["انبعاث غازات كيميائية سامة ومسرطنة تلوّث الهواء وتضرّ بالصحة","زيادة خصوبة التربة","تنقية الهواء من الغبار","تقليل حرارة الجو"],"answer":0,"why":"حرق البلاستيك يطلق الديوكسينات وأول أكسيد الكربون والجسيمات السامة."},{"type":"mcq","q":"أي الفئات الآتية أكثر عرضةً للضرر المباشر من دخان حرق القمامة؟","options":["النباتات البلاستيكية","الأطفال ومرضى الربو وكبار السن","الصخور الجبلية","السيارات"],"answer":1,"why":"الجهاز التنفسي للأطفال وكبار السن ومرضى الربو أشد تأثرًا."},{"type":"mcq","q":"ما الغاز السام الناتج عن الاحتراق غير الكامل الذي يقلّل وصول الأكسجين إلى الدم؟","options":["غاز الهيليوم","غاز الأكسجين (O₂)","أول أكسيد الكربون (CO)","بخار الماء النقي"],"answer":2,"why":"أول أكسيد الكربون غاز خانق وسام ناتج عن الاحتراق غير الكامل."},{"type":"mcq","q":"كيف يؤثر الرماد الناتج عن حرق القمامة على البيئة إلى جانب تلوث الهواء؟","options":["يمنع التلوث","يحوّل التربة إلى ذهب","يزيد نقاء مياه الأفلاج","يلوّث التربة والمزروعات وقد يتسرّب إلى المياه الجوفية"],"answer":3,"why":"تحتوي بقايا الحرق على معادن ثقيلة وسموم تلوّث التربة والماء."}],"medium":[{"type":"mcq","q":"ما البديل الحضاري الآمن للتخلص من النفايات بدل حرقها؟","options":["الفرز وإعادة التدوير ونقلها إلى مرادم هندسية آمنة","دفنها في ساحة البيت","رميها في الأودية","حرقها ليلًا فقط"],"answer":0,"why":"إعادة التدوير والإدارة البيئية السليمة تحمي الصحة والبيئة."},{"type":"mcq","q":"ما الجهة المتخصصة في إدارة النفايات وحماية البيئة من التلوث في سلطنة عُمان؟","options":["المكتبات العامة","الشركة العُمانية القابضة لخدمات البيئة (بيئة) والجهات البيئية المختصة","الأندية الرياضية","محطات القطارات"],"answer":1,"why":"شركة «بيئة» تدير النفايات والمرادم الهندسية في عُمان."},{"type":"mcq","q":"ما القاعدة الشرعية التي تنطبق مباشرةً على منع حرق القمامة قرب بيوت الجيران؟","options":["تجاهل حقوق الجار","الإسراف في الاستهلاك","«لا ضرر ولا ضرار»","إهمال النظافة"],"answer":2,"why":"إيذاء الجيران بالدخان السام يناقض قاعدة «لا ضرر ولا ضرار»."},{"type":"tfr","q":"حرق القمامة البلاستيكية في ساحة المنزل طريقة آمنة واقتصادية للتخلص من النفايات.","answer":false,"reasons":["آمنة إذا كانت في المساء","نعم طريقة آمنة","بل طريقة خطيرة جدًا تطلق غازات سامة ومسرطنة تلوث الهواء والتربة"],"reason":2},{"type":"tfr","q":"يمتد ضرر حرق النفايات ليشمل تلوث الهواء والتربة والمياه الجوفية معًا.","answer":true,"reasons":["بسبب تصاعد الغازات السامة وتساقط الرماد الملوّث على الأرض","يقتصر على الرائحة فقط","لا يضر بالتربة"],"reason":0},{"type":"essay","q":"اذكر ثلاثة أضرار صحية وبيئية ناتجة عن حرق القمامة في الأحياء السكنية.","model":"١) أمراض الجهاز التنفسي وتهيّج الربو والعيون. ٢) انبعاث غازات سامة كأول أكسيد الكربون والديوكسينات. ٣) تلوث التربة والمياه الجوفية وخطر اندلاع الحرائق."},{"type":"essay","q":"اقترح ثلاثة حلول عملية للحد من ظاهرة حرق النفايات في مجتمعك المحلي.","model":"١) الالتزام بوضع النفايات في الحاويات المخصصة ونقلها للمرادم الهندسية. ٢) نشر ثقافة الفرز وإعادة التدوير في البيوت والمدارس. ٣) التوعية المجتمعية والإبلاغ عن الحرق العشوائي."}],"hard":[{"type":"mcq","q":"ما أفضل طريقة لتنظيم ملاحظاتك أثناء الاستماع لنص بيئي علمي؟","options":["التركيز على اسم المتحدث فقط","كتابة جملة واحدة عشوائية","عدم تدوين أي ملاحظة","تقسيمها إلى: المشكلة، الأضرار الصحية والبيئية، والحلول المقترحة"],"answer":3,"why":"التنظيم الثلاثي يرسّخ الفهم والاستيعاب."},{"type":"mcq","q":"ما العلاقة بين حرق النفايات وظاهرة «المطر الحمضي»؟","options":["تتصاعد أكاسيد الكبريت والنيتروجين فتذوب في السحب مكوّنةً أمطارًا حمضية","حرق النفايات يمنع المطر الحمضي","لا علاقة بينهما","يزيد نسبة الأكسجين"],"answer":0,"why":"أكاسيد الكبريت والنيتروجين تسبب تلوث الهواء والمطر الحمضي."},{"type":"mcq","q":"أي سلوك مما يلي يطبّق مبدأ «قلّل، أعد الاستخدام، أعد التدوير» في المدرسة؟","options":["حرق أوراق الامتحانات خلف المدرسة","فرز الأوراق والعبوات البلاستيكية في حاويات التدوير المخصصة","رمي البلاستيك في الشارع","شراء عبوات بلاستيكية يوميًا ورميها"],"answer":1,"why":"الفرز المنظم هو الخطوة الأولى لإعادة التدوير."},{"type":"mcq","q":"نوع نص الاستماع «من مخاطر التلوث الكيميائي» هو نص:","options":["شعري غزلي","قصصي خيالي","علمي توعوي بيئي","تاريخي قديم"],"answer":2,"why":"يقدم حقائق علمية بهدف التوعية البيئية والصحية."},{"type":"tfr","q":"تُعدّ إعادة التدوير وفرز النفايات من أفضل الحلول الحضارية لتقليل التلوث الكيميائي.","answer":true,"reasons":["تزيد التلوث","لأنها تقلل حجم النفايات وتعيد الاستفادة من المواد بأمان","أخطر من الحرق"],"reason":1},{"type":"tfr","q":"الأطفال ومرضى الربو هم من أكثر الفئات تضررًا من استنشاق دخان حرق القمامة.","answer":true,"reasons":["الدخان يفيد التنفس","لا يتأثر الأطفال بالدخان","لحساسية جهازهم التنفسي تجاه الغازات السامة والجسيمات الدقيقة"],"reason":2},{"type":"tfr","q":"لا علاقة لتعاليم الإسلام بحماية البيئة ومنع إيذاء الجيران بالدخان.","answer":false,"reasons":["بل حرّم الإسلام الأذى بقاعدة «لا ضرر ولا ضرار» وأمر بإماطة الأذى والنظافة","نعم لا علاقة","يقتصر على الأماكن البعيدة"],"reason":0},{"type":"essay","q":"فسّر لماذا يكون حرق «البلاستيك والبطاريات» أخطر بكثير من حرق أوراق الشجر الجافة.","model":"لأن البلاستيك والبطاريات مركّبات كيميائية ومعادن ثقيلة تطلق عند احتراقها سمومًا خطيرة مثل الديوكسينات وأبخرة المعادن التي تسبب أمراضًا مزمنة ومسرطنة."},{"type":"essay","q":"كيف يرتبط هذا الدرس بما درسته في مادة الكيمياء حول تلوث الهواء والغلاف الجوي؟","model":"كلاهما يوضّح أن الاحتراق غير الكامل للمواد يطلق غازات ضارة (CO، SO₂، NO₂) تلوّث الغلاف الجوي وتؤذي الإنسان والبيئة."},{"type":"essay","q":"اكتب شعارًا توعويًا قصيرًا مع نصيحة من سطرين لتعليقه في مدرستك ضد حرق النفايات.","model":"الشعار: «هواءٌ نقيٌّ.. حياةٌ آمنة». النصيحة: لا تشعل النار في النفايات، فدخانها سمٌّ يصل إلى رئتَي أطفالك وجيرانك؛ افرز نفاياتك وضعها في الحاوية المخصصة لنحمي عُمان الجميلة."}]}},
  {"id":"g9-arabic-2-u5-1","grade":"g9","subject":"arabic","term":2,"unit":5,"no":1,"title":"القراءة: دور العُمانيين في نشر الإسلام في الهند","summary":"شرح متحرك بـ SVG لدرس القراءة: دور العُمانيين في نشر الإسلام في الهند (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-omanis-islam-in-india.html","video":"","pdf":"","notes":["نشر العُمانيون الإسلام في الهند سلميًا بالتجارة والأمانة والقدوة والمساواة.","الشواهد: المسعودي (١٠ آلاف في سيمور)، القاضي بدر الدين، الناخوذة حسن (بناء مسجد جامع).","المفردات: القدح المعلّى (الدور الأبرز)، الناخوذة (ربان السفينة)، زُهاء (نحو)، الأصقاع (النواحي)."],"exercises":["كيف أسهم الموقع الجغرافي لعُمان في قيام العُمانيين بدورهم الحضاري في الهند؟","اذكر ثلاثة أدلة تاريخية من النص تثبت المكانة الرفيعة للعُمانيين في الهند.","فسّر لماذا وجد أهل الهند في الإسلام ملاذًا اجتماعيًا."],"levels":{"easy":[{"type":"mcq","q":"ما الوسيلة الرئيسة التي نشر بها العُمانيون الإسلام في الهند؟","options":["الحروب والغزو العسكري","التجارة السلمية والأخلاق الحسنة والقدوة العملية","إكراه السكان","العزلة والانغلاق"],"answer":1,"why":"الصدق والأمانة وحسن المعاملة هي التي حبّبت أهل الهند في الإسلام."},{"type":"mcq","q":"ما معنى عبارة «القِدْح المُعلّى» الواردة في النص؟","options":["المكانة الضعيفة","الوعاء الفارغ","الدور الأبرز والمكانة العليا والنصيب الأوفر","الميناء الصغير"],"answer":2,"why":"تعبير عربي أصيل يدل على السبق والمكانة العليا."},{"type":"mcq","q":"ما معنى كلمة «الناخوذة» في التراث البحري العُماني؟","options":["حارس الميناء","صانع الشباك","بائع التوابل","ربّان السفينة وقائدها"],"answer":3,"why":"الناخوذة حسن كان ربّانًا عُمانيًا بنى مسجدًا جامعًا في الهند."},{"type":"mcq","q":"من الرحالة الجغرافي الذي ذكر وجود نحو عشرة آلاف عُماني في ميناء «سيمور» بالهند؟","options":["المسعودي","ابن خلدون","المتنبي","الأصمعي"],"answer":0,"why":"شاهد المسعودي ميناء سيمور ووثّق كثرة العُمانيين فيها."}],"medium":[{"type":"mcq","q":"لماذا أقبل كثير من سكان الهند على الدخول في الإسلام طوعًا؟","options":["خوفًا من السفن","لما وجدوا فيه من مساواة وعدالة تنقذهم من الطبقية ولصدق التجار العُمانيين","لأسباب مناخية","بتقليد أعمى"],"answer":1,"why":"العدالة الاجتماعية والمساواة كانتا نقطة جذب كبرى."},{"type":"mcq","q":"ما معنى كلمة «زُهاء» في عبارة «زُهاء عشرة آلاف»؟","options":["ضعف العدد","أقل من عشرة","ما يقرب من (نحو)","بالضبط دون زيادة"],"answer":2,"why":"زهاء تفيد التقريب العددي."},{"type":"mcq","q":"ما مفرد كلمة «الأصقاع» ومعناها؟","options":["صَغار — وتعني الصغر","صَقيع — وتعني الثلج","سَقْف — وتعني السطح","صُقْع — وتعني الناحية والجهة"],"answer":3,"why":"الأصقاع هي النواحي والأماكن البعيدة."},{"type":"tfr","q":"انتشر الإسلام في الهند على يد العُمانيين بالحكمة والقدوة الحسنة والتجارة السلمية لا بالعنف.","answer":true,"reasons":["فقد جذب صدقهم وأمانتهم وعدالة الإسلام قلوب أهل الهند","انتشر بالحرب فقط","لم يصل العُمانيون للهند"],"reason":0},{"type":"tfr","q":"تعني كلمة «الناخوذة» القاضي في المحكمة.","answer":false,"reasons":["نعم تعني القاضي","بل تعني ربّان السفينة وقائدها","تعني التاجر البري"],"reason":1},{"type":"essay","q":"كيف أسهم الموقع الجغرافي لعُمان في قيام العُمانيين بدورهم الحضاري في الهند؟","model":"إطلالة عُمان على بحر العرب والمحيط الهندي وسواحلها الممتدة وموانئها المزدهرة كصحار جعلت العُمانيين مهرةً في الملاحة، فوصلوا بأساطيلهم إلى الهند وشرقي إفريقيا."},{"type":"essay","q":"اذكر ثلاثة أدلة تاريخية من النص تثبت المكانة الرفيعة للعُمانيين في الهند.","model":"١) وجود نحو عشرة آلاف عُماني في ميناء سيمور بشهادة المسعودي. ٢) تولّي القاضي العُماني بدر الدين القضاء في منجرور واتخاذ قادة أساطيل منهم. ٣) بناء الناخوذة حسن لمسجد جامع كبير على الساحل الهندي."}],"hard":[{"type":"mcq","q":"ما الذي يدل على ثقة حكام الهند بالتجار العُمانيين؟","options":["اتخاذهم قادةً للأساطيل وتولي بعضهم القضاء كالقاضي بدر الدين في منجرور","منعهم من دخول الموانئ","فرض ضرائب مضاعفة عليهم","إبعادهم عن السواحل"],"answer":0,"why":"تولي القضاء وقيادة الأساطيل دليل ثقة ومكانة سامية."},{"type":"mcq","q":"كيف أثّر دخول العُمانيين في الإسلام على أهداف رحلاتهم البحرية؟","options":["توقفت رحلاتهم البحرية","تطورت من مجرد تجارة وملاحة لتصبح رسالةً ساميةً لنشر الإسلام والحضارة","اقتصرت على الصيد القريب","لم يتغير شيء"],"answer":1,"why":"أصبح نشر الإسلام من أسمى مقاصدهم مع التجارة."},{"type":"mcq","q":"من الذي بنى مسجدًا جامعًا كبيرًا على الساحل الهندي كما ورد في النص؟","options":["أحمد بن ماجد","عمرو بن العاص","الناخوذة حسن العُماني","عباس بن فرناس"],"answer":2,"why":"الناخوذة حسن أحد الملاحين العُمانيين."},{"type":"mcq","q":"ما موقف البرتغاليين من الوجود الإسلامي والعربي في الهند؟","options":["انسحبوا فورًا دون صراع","ساعدوا في بناء المساجد","تحالفوا مع التجار العُمانيين","حاولوا القضاء عليه لأنه يهدد نفوذهم التجاري والسياسي"],"answer":3,"why":"قاوم المسلمون والعُمانيون السيطرة البرتغالية."},{"type":"tfr","q":"وثّق الرحالة العرب كالمسعودي والمقدسي ازدهار الموانئ العُمانية وحضور العُمانيين في الهند.","answer":true,"reasons":["كانت مجرد أساطير","لم يذكرهم أي رحالة","وهو دليل تاريخي موثّق على عظمة الدور الحضاري العُماني"],"reason":2},{"type":"tfr","q":"اقتصر أثر العُمانيين في الهند على بيع السلع دون أي أثر علمي أو ديني أو عمراني.","answer":false,"reasons":["بل بنوا المساجد وتولّوا القضاء ونشروا العلم والإسلام والحضارة","نعم اقتصر على البيع فقط","لم يبنوا مساجد"],"reason":0},{"type":"tfr","q":"امتدّ دور العُمانيين في نشر الإسلام من سواحل الهند إلى الجزر المحيطة بها في المحيط الهندي.","answer":true,"reasons":["توقف عند ميناء واحد فقط","بفضل نشاطهم البحري الواسع ومهارتهم الملاحية","لم يتجاوز بحر عُمان"],"reason":1},{"type":"essay","q":"فسّر لماذا وجد أهل الهند في الإسلام ملاذًا اجتماعيًا.","model":"لأن الإسلام نادى بالمساواة والعدالة وكرامة الإنسان، مما أنقذ كثيرًا منهم من نظام الطبقية والعنصرية."},{"type":"essay","q":"اشرح معاني المفردات الآتية: القدح المعلّى، الناخوذة، زُهاء، الأصقاع.","model":"القدح المعلّى: الدور الأبرز والمكانة العليا. الناخوذة: ربان السفينة. زهاء: ما يقرب من. الأصقاع: النواحي والأماكن."},{"type":"essay","q":"ما الدرس الذي يستلهمه الطالب العُماني اليوم من سيرة التجار العُمانيين في الهند؟","model":"أن الأخلاق الرفيعة (الصدق والأمانة والتسامح وإتقان العمل) هي أعظم سفير للدين والوطن في أي مكان في العالم."}]}},
  {"id":"g9-arabic-2-u5-2","grade":"g9","subject":"arabic","term":2,"unit":5,"no":2,"title":"الأنشطة النحوية والصرفية: اسم المفعول","summary":"شرح متحرك بـ SVG لدرس الأنشطة النحوية والصرفية: اسم المفعول (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-ism-al-mafool.html","video":"","pdf":"","notes":["يُشتق اسم المفعول من المبني للمجهول (كُتِبَ ← مَكتوب).","الثلاثي: مَفعول | الأجوف: مَقول، مَبيع | الناقص: مَدعوّ، مَبنيّ (تشديد الآخر).","غير الثلاثي: مُـ + فتح ما قبل الآخر (مُكرَم، مُستخرَج، مُتقَن)."],"exercises":["صُغ اسم المفعول من الأفعال الآتية مع الضبط: فُهِمَ، صِيمَ، رُجِيَ، أُكرِمَ، اسْتُعمِلَ.","قارن بين اسم الفاعل واسم المفعول من الأفعال الآتية: باعَ، دعا، علّمَ، استقبلَ.","استخرج أسماء المفعولين واذكر فعل كل منها مبنيًا للمجهول: «العلمُ المَوروثُ والمُنظَّمُ كنزٌ مَصونٌ ومُحترَمٌ»."],"levels":{"easy":[{"type":"mcq","q":"ما اسم المفعول من الفعل الثلاثي الأجوف «بِيعَ» (باعَ)؟","options":["مَبيوع","بائِع","مَبيع","مُباع"],"answer":2,"why":"مضارعه يَبيع ← نبدل الياء ميمًا مفتوحةً: مَبيع."},{"type":"mcq","q":"ما اسم المفعول من الفعل الثلاثي الناقص «دُعِيَ» (دعا)؟","options":["مُدعى","داعٍ","مَدعيّ","مَدعوّ"],"answer":3,"why":"أصل الألف واو (يدعو) ← مَدعوّ بتشديد الواو."},{"type":"mcq","q":"ما اسم المفعول من الفعل غير الثلاثي «اسْتُخرِجَ»؟","options":["مُستخرَج","مُستخرِج","مَخروج","خارِج"],"answer":0,"why":"من غير الثلاثي: ميم مضمومة وفتح ما قبل الآخر (مُستخرَج)."},{"type":"mcq","q":"ما اسم المفعول من الفعل الناقص «بُنِيَ» (بنى)؟","options":["بانٍ","مَبنيّ","مَبنيو","مُبنًى"],"answer":1,"why":"مضارعه يَبني ← ميم مفتوحة وتشديد الياء: مَبنيّ."}],"medium":[{"type":"mcq","q":"من أي فعل يُشتق اسم المفعول؟","options":["الأحرف الناسخة","الفعل المبني للمعلوم فقط","الفعل المبني للمجهول","الأسماء الجامدة"],"answer":2,"why":"يُشتق اسم المفعول من الفعل المبني للمجهول (مثل كُتِبَ ← مكتوب)."},{"type":"mcq","q":"ما اسم المفعول من الفعل «قِيلَ» (قالَ)؟","options":["مُقال","قائِل","مَقوول","مَقول"],"answer":3,"why":"يَقول ← ميم مفتوحة: مَقول."},{"type":"mcq","q":"ما الفرق الصرفي بين «مُعلِّم» و«مُعلَّم»؟","options":["مُعلِّم (بكسر اللام) اسم فاعل، ومُعلَّم (بفتح اللام) اسم مفعول","كلاهما اسم فاعل","كلاهما اسم مفعول","الأول ثلاثي والثاني رباعي"],"answer":0,"why":"الكسر قبل الآخر لاسم الفاعل والفتح لاسم المفعول."},{"type":"tfr","q":"يُشتق اسم المفعول من الفعل المبني للمجهول للدلالة على من وقع عليه الفعل.","answer":true,"reasons":["يُشتق من المبني للمعلوم فقط","فإذا قيل ما فعل «مَسموع» نكتب «سُمِعَ» مبنيًا للمجهول","يدل على من قام بالفعل"],"reason":1},{"type":"tfr","q":"اسم المفعول من الفعل «باعَ» هو «مَبيوع».","answer":false,"reasons":["الصواب بائع","نعم مبيوع","الصواب «مَبيع» بحذف واو مفعول"],"reason":2},{"type":"essay","q":"صُغ اسم المفعول من الأفعال الآتية مع الضبط: فُهِمَ، صِيمَ، رُجِيَ، أُكرِمَ، اسْتُعمِلَ.","model":"مَفهوم، مَصوم، مَرجوّ، مُكرَم، مُستعمَل."},{"type":"essay","q":"قارن بين اسم الفاعل واسم المفعول من الأفعال الآتية: باعَ، دعا، علّمَ، استقبلَ.","model":"باع: بائع / مَبيع. دعا: داعٍ / مَدعوّ. علّم: مُعلِّم / مُعلَّم. استقبل: مُستقبِل / مُستقبَل."}],"hard":[{"type":"mcq","q":"ما الفعل المبني للمجهول الذي اشتُق منه اسم المفعول «مُتقَن»؟","options":["تُقِنَ","أُتقِنَ","تَقتنَ","اتّقنَ"],"answer":1,"why":"بما أنه يبدأ بميم مضمومة فهو من الرباعي المبني للمجهول «أُتقِنَ»."},{"type":"mcq","q":"أي الكلمات الآتية يُعدّ اسم مفعول من فعل ثلاثي صحيح مضعّف؟","options":["مُشَدَّد","شادّ ومادّ","مَشدود ومَمدود","مَقول"],"answer":2,"why":"يُفكّ التضعيف في اسم المفعول الثلاثي: شُدَّ ← مَشدود."},{"type":"mcq","q":"في جملة «الكتابُ مُختارٌ بعنايةٍ للقراءة»، كلمة «مُختار» تُعدّ:","options":["فعلًا ماضيًا","اسم فاعل","ظرف زمان","اسم مفعول (لأن الكتاب وقع عليه الاختيار)"],"answer":3,"why":"السياق يبيّن أن الكتاب وقع عليه فعل الاختيار."},{"type":"mcq","q":"أي الجمل الآتية تحتوي على اسم مفعول من فعل غير ثلاثي؟","options":["النفطُ مُستخرَجٌ من باطن الأرض","الحقُّ مَنصورٌ دائمًا","البيتُ مَبنيّ بالحجارة","الدرسُ مَفهومٌ"],"answer":0,"why":"مُستخرَج من السداسي اسْتُخرِجَ (ميم مضمومة وفتح ما قبل الآخر)."},{"type":"tfr","q":"يُصاغ اسم المفعول من الفعل غير الثلاثي بميم مضمومة وفتح ما قبل الآخر.","answer":true,"reasons":["مثل: أُكرِمَ ← مُكرَم، اسْتُعمِلَ ← مُستعمَل","بكسر ما قبل الآخر","على وزن مفعول"],"reason":0},{"type":"tfr","q":"اسم المفعول من الفعل الثلاثي الناقص «قَضى» هو «مَقضيّ» بتشديد الياء.","answer":true,"reasons":["هو قاضٍ","لأن مضارعه يَقضي (أصل الألف ياء) فتُشدّد الياء: مَقضيّ","هو مَقضوّ"],"reason":1},{"type":"tfr","q":"الفرق بين «مُحترِم» و«مُحترَم» أن الأولى اسم مفعول والثانية اسم فاعل.","answer":false,"reasons":["كلاهما اسم مفعول","نعم صحيح","العكس تمامًا: مُحترِم (كسر) اسم فاعل، ومُحترَم (فتح) اسم مفعول"],"reason":2},{"type":"essay","q":"استخرج أسماء المفعولين واذكر فعل كل منها مبنيًا للمجهول: «العلمُ المَوروثُ والمُنظَّمُ كنزٌ مَصونٌ ومُحترَمٌ».","model":"الموروث (وُرِثَ)، المُنظَّم (نُظِّمَ)، مَصون (صِينَ)، مُحترَم (احْتُرِمَ)."},{"type":"essay","q":"اشرح قاعدة صياغة اسم المفعول من الثلاثي الأجوف والناقص بمثالين لكل منهما.","model":"الأجوف: نأتي بالمضارع ونبدل حرفه الأول ميمًا مفتوحة (قال←يقول←مَقول، باع←يبيع←مَبيع). الناقص: نبدل حرف المضارعة ميمًا مفتوحة ونشدّد الآخر (دعا←يدعو←مَدعوّ، بنى←يبني←مَبنيّ)."},{"type":"essay","q":"صوّب الخطأ الصرفي في الجملة: «هذا البيت مَبنيو بإتقان، والبضاعة مَبيوعة في السوق».","model":"الصواب: هذا البيت مَبنيّ بإتقان، والبضاعة مَبيعة في السوق."}]}},
  {"id":"g9-arabic-2-u5-3","grade":"g9","subject":"arabic","term":2,"unit":5,"no":3,"title":"الأنشطة الإملائية: تطبيقات على علامات الترقيم","summary":"شرح متحرك بـ SVG لدرس الأنشطة الإملائية: تطبيقات على علامات الترقيم (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-punctuation-applications.html","video":"","pdf":"","notes":["(،) للتتابع والنداء والأقسام | (؛) بين السبب والنتيجة.","(:) بعد القول وقبل التفصيل | (.) نهاية الجملة التامة والسؤال غير المباشر.","(– –) للجملة الاعتراضية | (« ») للنقل الحرفي | (؟) للسؤال المباشر | (!) للتعجب."],"exercises":["ضع علامات الترقيم المناسبة في الفقرة الآتية: «قال الوالد لابنه يا بني حافظ على صلاتك لأنها عماد الدين فما أسعد المؤمن بها».","فرّق في جدول بين استخدام «الفاصلة (،)» و«الفاصلة المنقوطة (؛)» مع مثال لكل منهما.","وظّف الشرطتين (– –) وعلامتَي التنصيص (« ») في جملة واحدة صحيحة."],"levels":{"easy":[{"type":"mcq","q":"ما علامة الترقيم المناسبة في الفراغ: «اجتهدَ سالمٌ في دراسته ( ) فحققَ المركز الأول»؟","options":["علامة الحذف (...)","علامة الاستفهام (؟)","النقطتان الرأسيتان (:)","الفاصلة المنقوطة (؛)"],"answer":3,"why":"الجملة الثانية نتيجة للأولى فتناسبها الفاصلة المنقوطة."},{"type":"mcq","q":"ما علامة الترقيم التي توضع بينها الجملة الاعتراضية مثل «رحمه الله»؟","options":["الشرطتان (– –)","علامتا التنصيص (« »)","النقطتان الرأسيتان (:)","علامة التعجب (!)"],"answer":0,"why":"تُحصر الجملة الاعتراضية بين شرطتين."},{"type":"mcq","q":"ما علامة الترقيم المناسبة بعد كلمة «قال» في: «قال الحكيم ( ) الصدق منجاة»؟","options":["الفاصلة المنقوطة (؛)","النقطتان الرأسيتان (:)","علامة الاستفهام (؟)","النقطة (.)"],"answer":1,"why":"النقطتان الرأسيتان توضعان بعد القول وقبل التفصيل."},{"type":"mcq","q":"متى نستخدم علامتَي التنصيص (« »)؟","options":["بعد المنادى","في نهاية السؤال","عند نقل كلام بنصّه الحرفي دون تغيير","لحذف جزء من النص"],"answer":2,"why":"التنصيص يحفظ الأمانة العلمية في النقل الحرفي."}],"medium":[{"type":"mcq","q":"ما علامة الترقيم المناسبة في نهاية جملة: «سألني المعلم عن موعد تسليم التقرير ( )»؟","options":["النقطتان (:)","علامة الاستفهام (؟)","علامة التعجب (!)","النقطة (.)"],"answer":3,"why":"هذه جملة خبرية (استفهام غير مباشر) فتنتهي بنقطة لا بعلامة استفهام!"},{"type":"mcq","q":"ما علامة الترقيم التي توضع بعد المنادى في: «يا طالبَ العلمِ ( ) أخلِص نيتك»؟","options":["الفاصلة (،)","النقطة (.)","علامة الاستفهام (؟)","النقطتان (:)"],"answer":0,"why":"توضع الفاصلة بعد المنادى."},{"type":"mcq","q":"ما علامة الترقيم المناسبة لبيان أن هناك كلامًا محذوفًا من نص مقتبس؟","options":["الشرطة الواحدة (-)","علامة الحذف (...)","علامة التعجب (!)","الفاصلة المنقوطة (؛)"],"answer":1,"why":"النقاط الثلاث المتتابعة (...) تدل على الحذف."},{"type":"tfr","q":"توضع علامة الاستفهام (؟) في نهاية جملة: «استفسر الطالب عن موعد الاختبار».","answer":false,"reasons":["توضع علامة تعجب","نعم توضع علامة استفهام","هذه جملة خبرية تنتهي بنقطة (.)؛ علامة الاستفهام للسؤال المباشر فقط"],"reason":2},{"type":"tfr","q":"توضع الفاصلة المنقوطة (؛) بين جملتين تكون إحداهما سببًا أو نتيجةً للأخرى.","answer":true,"reasons":["مثل: أمارس الرياضة؛ لأنها تقوّي الجسم","توضع بعد المنادى","توضع بعد القول"],"reason":0},{"type":"essay","q":"ضع علامات الترقيم المناسبة في الفقرة الآتية: «قال الوالد لابنه يا بني حافظ على صلاتك لأنها عماد الدين فما أسعد المؤمن بها».","model":"قال الوالد لابنه: «يا بنيّ، حافظ على صلاتك؛ لأنها عماد الدين. فما أسعد المؤمن بها!»."},{"type":"essay","q":"فرّق في جدول بين استخدام «الفاصلة (،)» و«الفاصلة المنقوطة (؛)» مع مثال لكل منهما.","model":"الفاصلة (،): بين الجمل المتعاطفة والأقسام وبعد المنادى (يا سالم، اقرأ). الفاصلة المنقوطة (؛): بين السبب والنتيجة (أقرأ؛ لأزداد علمًا)."}],"hard":[{"type":"mcq","q":"أين توضع «الفاصلة» و«النقطة» بالنسبة للمسافات في الكتابة الرقمية واليدوية؟","options":["في سطر منفصل","تُترك مسافة قبلها ولا مسافة بعدها","تلتصق بالكلمة التي قبلها وتُترك مسافة بعدها","لا أهمية للمسافات"],"answer":2,"why":"القاعدة الطباعية: لا مسافة قبل العلامة ومسافة بعدها."},{"type":"mcq","q":"أي جملة استُخدمت فيها علامات الترقيم استخدامًا صحيحًا بالكامل؟","options":["أحبّ القراءة: لأنها تنمّي العقل، وتوسّع الأفق؟","أحبّ القراءة؟ لأنها تنمّي العقل: وتوسّع الأفق!","أحبّ القراءة. لأنها تنمّي العقل؛ وتوسّع الأفق؟","أحبّ القراءة؛ لأنها تنمّي العقل، وتوسّع الأفق."],"answer":3,"why":"فاصلة منقوطة قبل السبب، فاصلة بين المتعاطفين، ونقطة في النهاية."},{"type":"mcq","q":"ما علامة الترقيم التي تجمع الاستفهام مع الدهشة والاستنكار في: «أتهملُ واجبك وتنتظر النجاح ( )»؟","options":["(؟!)","(؛)","(:)","(...)"],"answer":0,"why":"تُستخدم (؟!) للاستفهام التعجبي الاستنكاري."},{"type":"mcq","q":"تُستخدم الأقواس الهلالية ( ) عادةً في النصوص لـ:","options":["نهاية الفقرة","تفسير كلمة غامضة أو ذكر تاريخ أو رقم أو مصطلح","النداء","الربط بين السبب والنتيجة"],"answer":1,"why":"القوسان يوضحان الكلمة أو يحددان التواريخ والمصطلحات."},{"type":"tfr","q":"الشرطتان (– –) تحصران الجملة الاعتراضية التي يمكن حذفها دون أن يختل أصل المعنى.","answer":true,"reasons":["تحصران الآيات القرآنية","مثل: الصحابي الجليل – رضي الله عنه – ضرب أروع مثل في العدل","توضعان في نهاية الجملة"],"reason":1},{"type":"tfr","q":"يمكن الاستغناء تمامًا عن علامات الترقيم لأنها لا تؤثر على فهم المعنى.","answer":false,"reasons":["خاصة بالصحف فقط","نعم مجرد زينة شكلية","بل تغيّر المعنى جذريًا وتنظّم القراءة وتمنع اللبس"],"reason":2},{"type":"tfr","q":"توضع النقطتان الرأسيتان (:) قبل ذكر أقسام الشيء وتفصيله وبعد أفعال القول.","answer":true,"reasons":["مثل: الكلمة ثلاثة أقسام: اسم، وفعل، وحرف","توضع في نهاية الجملة التامة","توضع قبل «لأن»"],"reason":0},{"type":"essay","q":"وظّف الشرطتين (– –) وعلامتَي التنصيص (« ») في جملة واحدة صحيحة.","model":"قال عمر بن الخطاب – رضي الله عنه –: «بئس الوالي أنا إن شبعتُ والناس جياع»."},{"type":"essay","q":"اشرح لماذا تختلف علامة الترقيم في نهاية: «هل زرتَ قلعة نزوى؟» و«أخبرني هل زرتَ قلعة نزوى.».","model":"الأولى سؤال مباشر فتنتهي بعلامة استفهام (؟)، والثانية جملة طلبية/خبرية غير مباشرة فتنتهي بنقطة (.)."},{"type":"essay","q":"اذكر أربع فوائد عملية لاستخدام علامات الترقيم في كتابة التقارير والمقالات.","model":"١) توضيح المعنى ومنع اللبس. ٢) تنظيم القراءة وتحديد مواضع الوقف. ٣) إظهار الانفعال (سؤال، تعجب). ٤) التمييز بين كلام الكاتب والكلام المنقول."}]}},
  {"id":"g9-arabic-2-u5-4","grade":"g9","subject":"arabic","term":2,"unit":5,"no":4,"title":"التعبير: كتابة التقرير","summary":"شرح متحرك بـ SVG لدرس التعبير: كتابة التقرير (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-writing-a-report.html","video":"","pdf":"","notes":["اجمع البيانات والأرقام ميدانيًا قبل التحرير.","رتّب الوقائع زمنيًا بتعداد واضح، واربط كل تحدٍّ بتوصية عملية.","اختم بالتوثيق (الاسم والصفة والتاريخ) وراجع الترقيم والإملاء."],"exercises":["اكتب تقريرًا مختصرًا مكتمل العناصر (عنوان، مقدمة، ٣ وقائع، إيجابية وتحدٍّ، توصية، وتوثيق) عن «ندوة القراءة في مدرستك».","حوّل العبارة العاطفية الآتية إلى لغة تقرير موضوعية: «كانت رحلتنا للمتحف أسطورية ورهيبة وأعجبت كل الناس بلا استثناء».","اربط كل تحدٍّ بتوصية عملية مناسبة: (أ) تأخر وصول الحافلة ٢٠ دقيقة. (ب) عدم كفاية مقاعد القاعة للضيوف."],"levels":{"easy":[{"type":"mcq","q":"ما أفضل طريقة لربط «التوصيات» بقسم «التحديات» في التقرير؟","options":["أن تقدّم كل توصية حلًا عمليًا مباشرًا لأحد التحديات التي رُصدت","أن تكون التوصيات منفصلة تمامًا عن موضوع التقرير","ألا نذكر توصيات أبدًا","أن نكرّر الشكوى دون حل"],"answer":0,"why":"التوصية العملية تعالج التحدي الذي واجه التنفيذ."},{"type":"mcq","q":"أي جملة من الآتي صيغت بلغة تقرير احترافية دقيقة؟","options":["زرعنا أشجارًا كثيرة جدًا وكان اليوم خرافيًا كالجنة","تمّت زراعة ٦٠ شتلةً بمشاركة ٤٥ طالبًا خلال ساعتين","ربما شارك بعض الطلاب في وقت ما","الشمس كانت تغضب علينا بشدة"],"answer":1,"why":"الأولى موضوعية ودقيقة بالأرقام والزمن."},{"type":"mcq","q":"لماذا يُنصح بجمع الملاحظات والأرقام «أثناء» تنفيذ النشاط؟","options":["لتأليف أرقام تقديرية","لإضاعة وقت النشاط","لضمان دقة الحقائق وعدم نسيان التفاصيل المهمة عند كتابة التقرير","لإلغاء المقدمة"],"answer":2,"why":"التدوين الميداني يمنح التقرير مصداقية عالية."},{"type":"mcq","q":"عند مواجهة تحدٍّ مثل «ارتفاع حرارة الشمس الساعة ١٠ صباحًا»، ما التوصية الأنسب؟","options":["انتقاد الطقس","إلغاء الأنشطة نهائيًا","تجاهل المشكلة","البدء المبكر للنشاط الساعة ٧:٣٠ صباحًا في المرات القادمة"],"answer":3,"why":"توصية عملية واقعية تعالج السبب مباشرة."}],"medium":[{"type":"mcq","q":"أي علامة ترقيم توضع بعد العناوين الفرعية داخل التقرير مثل «النتائج» و«التوصيات»؟","options":["النقطتان الرأسيتان (:)","علامة الاستفهام (؟)","علامة التعجب (!)","الفاصلة المنقوطة (؛)"],"answer":0,"why":"قبل التفصيل والتعداد توضع النقطتان الرأسيتان (:)."},{"type":"mcq","q":"ما الترتيب الصحيح لفقرات التقرير الكامل؟","options":["التوثيق ← التوصيات ← العنوان ← المقدمة","العنوان ← المقدمة ← الوقائع ← الإيجابيات والتحديات ← النتائج والتوصيات ← التوثيق","الوقائع فقط دون عنوان أو مقدمة","التحديات ← العنوان ← الخاتمة"],"answer":1,"why":"التدرج المنطقي من الإطار العام إلى التفاصيل ثم التقييم والتوصيات."},{"type":"mcq","q":"أي مما يأتي يُعدّ خطأً في أسلوب كتابة التقرير؟","options":["ذكر الأرقام والتواريخ","استخدام التعداد الرقمي","استخدام عبارات انفعالية ومبالغات شخصية وتوجيه لوم جارح","كتابة اسم مُعدّ التقرير في النهاية"],"answer":2,"why":"التقرير يتطلب الحياد والأدب المهني."},{"type":"tfr","q":"التوصية الجيدة في التقرير تكون عمليةً ومرتبطةً بالتحديات التي ظهرت أثناء التنفيذ.","answer":true,"reasons":["مثل التوصية بالبدء المبكر عند رصد ارتفاع الحرارة","تكون أمنيات عامة غير مرتبطة بالتقرير","تُكتب في المقدمة فقط"],"reason":0},{"type":"tfr","q":"يُفضّل في كتابة التقرير استخدام التعداد النقطي أو الرقمي لعرض الفعاليات والتوصيات.","answer":true,"reasons":["يُمنع التعداد في التقارير","لأنه يجعل التقرير سهل القراءة السريعة والتنظيم","يُكتب كله في سطر واحد"],"reason":1},{"type":"essay","q":"اكتب تقريرًا مختصرًا مكتمل العناصر (عنوان، مقدمة، ٣ وقائع، إيجابية وتحدٍّ، توصية، وتوثيق) عن «ندوة القراءة في مدرستك».","model":"العنوان: تقرير عن ندوة القراءة المدرسية. المقدمة: يوم الأربعاء ١٢ مارس، نظّمت جماعة اللغة العربية ندوةً بالقاعة الكبرى بمشاركة ٥٠ طالبًا لتشجيع القراءة. الوقائع: ١) كلمة افتتاحية (٨:٣٠). ٢) عرض تجارب قرائية لثلاثة طلاب (٩:٠٠). ٣) مسابقة ثقافية وتوزيع كتب (٩:٤٥). الإيجابيات: تفاعل مميز. التحدي: ضيق وقت الأسئلة. التوصية: تمديد وقت المناقشة ١٥ دقيقة مستقبلًا. مُعدّ التقرير: مقرر الجماعة — ١٣ مارس."},{"type":"essay","q":"حوّل العبارة العاطفية الآتية إلى لغة تقرير موضوعية: «كانت رحلتنا للمتحف أسطورية ورهيبة وأعجبت كل الناس بلا استثناء».","model":"التصويب: «حظيت الزيارة العلمية للمتحف بتفاعل إيجابي ملحوظ من الطلاب، وأسهمت في تعزيز معارفهم التاريخية»."}],"hard":[{"type":"mcq","q":"في تقرير عن مسابقة ثقافية، عبارة «تفاعل الطلاب وحسن التنظيم» تنتمي إلى قسم:","options":["العنوان","التحديات","التوثيق","الإيجابيات"],"answer":3,"why":"هي من نقاط القوة والإنجاز في النشاط."},{"type":"mcq","q":"ما فائدة استخدام الأفعال المبنية للمجهول أو المحايدة مثل «تمّ توزيع، نُفِّذت، يُوصى» في التقارير؟","options":["تُضفي طابعًا رسميًا وموضوعيًا محايدًا على التقرير","تخفي المعلومات","تُضعف اللغة","تجعل التقرير قصيدةً"],"answer":0,"why":"اللغة المحايدة تبرز الحدث والعمل لا الشخص."},{"type":"mcq","q":"ماذا نضع في سطر «التوثيق» أسفل التقرير؟","options":["عنوان المنزل فقط","اسم مُعدّ التقرير وصفته وتاريخ إعداده","درجة الطالب","قائمة المراجع الشعرية"],"answer":1,"why":"التوثيق يحدد المسؤول عن التقرير وتاريخه."},{"type":"mcq","q":"إذا طُلب منك كتابة تقرير عن «اليوم المفتوح للعلوم»، ما أول ما تكتبه؟","options":["التوقيع","التوصيات","عنوانًا دقيقًا ومحددًا يعكس موضوع التقرير","السلبيات"],"answer":2,"why":"العنوان الدقيق هو المدخل الأول لأي تقرير."},{"type":"tfr","q":"يمكن تأليف أرقام تقريبية غير حقيقية في التقرير لجعل النشاط يبدو أنجح.","answer":false,"reasons":["الأرقام غير مهمة","نعم لا بأس بالتأليف","الأمانة والدقة شرطان أساسيان في التقرير الوظيفي"],"reason":2},{"type":"tfr","q":"توظيف علامات الترقيم بدقة يرفع وضوح التقرير ومظهره المهني.","answer":true,"reasons":["خاصة النقطتين قبل التفصيل والنقاط والفواصل","لا تُستخدم علامات الترقيم في التقارير","تُستخدم علامة التعجب في كل سطر"],"reason":0},{"type":"tfr","q":"توجيه اللوم الشخصي الجارح للمنظمين من سمات التقرير الموضوعي الناجح.","answer":false,"reasons":["نعم مطلوب جدًا","بل تُعرض التحديات بأدب وحياد وبهدف التطوير لا التجريح","يزيد الموضوعية"],"reason":1},{"type":"essay","q":"اربط كل تحدٍّ بتوصية عملية مناسبة: (أ) تأخر وصول الحافلة ٢٠ دقيقة. (ب) عدم كفاية مقاعد القاعة للضيوف.","model":"(أ) تأكيد موعد الحافلة قبل يوم وتحديد وقت التجمع مبكرًا. (ب) حصر عدد المدعوين مسبقًا وتجهيز مقاعد إضافية احتياطية."},{"type":"essay","q":"لماذا يُعدّ التقرير مهارةً مهمةً ليس للمدرسة فقط بل للمستقبل المهني أيضًا؟","model":"لأن كل المهن (الهندسة، الطب، الإدارة، التعليم، الإعلام) تعتمد على كتابة تقارير دقيقة لمتابعة المشاريع واتخاذ القرارات."},{"type":"essay","q":"اذكر أربعة أخطاء شائعة يجب تجنّبها عند تحرير التقرير النهائي.","model":"١) غياب الأرقام والتواريخ الدقيقة. ٢) الخلط بين التقرير والوصف العاطفي. ٣) إهمال ذكر التوصيات أو التوثيق. ٤) الأخطاء الإملائية وإهمال علامات الترقيم."}]}},
  {"id":"g9-arabic-2-u5-5","grade":"g9","subject":"arabic","term":2,"unit":5,"no":5,"title":"النص الأدبي: عهد الإمام ناصر بن مرشد إلى والي الصير","summary":"شرح متحرك بـ SVG لدرس النص الأدبي: عهد الإمام ناصر بن مرشد إلى والي الصير (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-imam-nasir-covenant.html","video":"","pdf":"","notes":["صاحب العهد: الإمام ناصر بن مرشد اليعربي (مؤسس دولة اليعاربة).","ركائز العهد: تقوى الله + العدل والمساواة + الرفق بالرعية + الشورى.","السمات الفنية: جزالة اللفظ، الإيجاز، التأثر بالقرآن، الطباق والتوازن الموسيقي."],"exercises":["اذكر أربعة مبادئ للحكم الرشيد تضمّنها عهد الإمام ناصر بن مرشد إلى والي الصير.","بيّن ثلاث سمات أدبية وأسلوبية تميّز بها نص العهد.","علّل: لماذا بدأ الإمام عهده بالوصية بتقوى الله قبل سائر الأوامر الإدارية؟"],"levels":{"easy":[{"type":"mcq","q":"من صاحب العهد الموجّه إلى والي الصير؟","options":["عمر بن الخطاب","الإمام ناصر بن مرشد اليعربي","هارون الرشيد","أحمد بن ماجد"],"answer":1,"why":"الإمام ناصر بن مرشد مؤسس دولة اليعاربة في عُمان."},{"type":"mcq","q":"ما الفن النثري الذي ينتمي إليه النص؟","options":["الشعر الحر","القصة القصيرة","فنّ العهود والرسائل الديوانية (النثر السياسي)","المسرحية"],"answer":2,"why":"العهد رسالة توجيهية رسمية من الحاكم إلى واليه."},{"type":"mcq","q":"بمَ بدأ الإمام ناصر بن مرشد وصاياه لوالي الصير؟","options":["بالسفر للخارج","بجمع الأموال","ببناء القصور","بتقوى الله في السر والعلن"],"answer":3,"why":"التقوى هي الأساس الأخلاقي لكل أمانة وعدل."},{"type":"mcq","q":"ما المقصود بـ«العدل» الذي أوصى به الإمام في عهده؟","options":["المساواة بين الناس وإنصاف المظلوم دون محاباة لقوي أو قريب","تفضيل الأغنياء","التشدد مع الضعفاء فقط","إهمال القضاء"],"answer":0,"why":"العدل يساوي بين القوي والضعيف أمام الحق."}],"medium":[{"type":"mcq","q":"ما الدلالة البلاغية للجمع بين «السرّ والعلن» أو «القوي والضعيف» في النص؟","options":["ترادف غير مفيد","طباق يفيد الشمول والعموم ويبرز المعنى ويؤكده","غموض في العبارة","سجع فارغ"],"answer":1,"why":"الطباق يؤكد شمول التقوى لكل الأحوال وشمول العدل لكل الناس."},{"type":"mcq","q":"ما موقف العهد من مبدأ «الشورى»؟","options":["يقصرها على الأمور المالية فقط","يمنع المشورة","يوصي الوالي بمشاورة أهل العلم والرأي وتجنّب الاستبداد","لا يذكر الشورى"],"answer":2,"why":"الشورى ركيزة أساسية في القيادة الرشيدة."},{"type":"mcq","q":"من أبرز السمات الأسلوبية في عهد الإمام ناصر بن مرشد:","options":["الخيال الأسطوري","العامية والحشو","التعقيد والغموض","جزالة الألفاظ، والإيجاز، والتأثر بالقرآن الكريم، والتوازن الموسيقي"],"answer":3,"why":"يمثل ذروة النثر السياسي العُماني الفصيح."},{"type":"tfr","q":"الإمام ناصر بن مرشد هو مؤسس دولة اليعاربة وموحّد عُمان.","answer":true,"reasons":["هو من شعراء الجاهلية","وتولى الإمامة سنة ١٦٢٤م ووضع أسس دولة قوية عادلة","هو والٍ في الأندلس"],"reason":1},{"type":"tfr","q":"يقتصر العهد على أمور الضرائب فقط ولا يتطرق للأخلاق والعدل.","answer":false,"reasons":["هو نص وصفي للطبيعة","نعم للضرائب فقط","بل يقوم أساسًا على التقوى والعدل والرفق والشورى ورعاية الرعية"],"reason":2},{"type":"essay","q":"اذكر أربعة مبادئ للحكم الرشيد تضمّنها عهد الإمام ناصر بن مرشد إلى والي الصير.","model":"١) تقوى الله في السر والعلن. ٢) إقامة العدل والمساواة بين القوي والضعيف. ٣) الرفق بالرعية وتفقّد حاجاتهم. ٤) الشورى مع أهل العلم والأمر بالمعروف."},{"type":"essay","q":"بيّن ثلاث سمات أدبية وأسلوبية تميّز بها نص العهد.","model":"١) فصاحة اللغة وجزالة الألفاظ مع الإيجاز. ٢) التأثر بالقرآن الكريم والسنة النبوية. ٣) استخدام الطباق والتوازن الموسيقي لتثبيت المعاني."}],"hard":[{"type":"mcq","q":"ما الدور التاريخي الشهير للإمام ناصر بن مرشد في عُمان؟","options":["توحيد عُمان وتأسيس دولة اليعاربة وبدء تحرير السواحل من البرتغاليين","اكتشاف الأشعة السينية","بناء مدينة بغداد","تأليف معجم لسان العرب"],"answer":0,"why":"وحّد عُمان وأسس دولة اليعاربة (١٦٢٤م)."},{"type":"mcq","q":"كيف ينظر العهد إلى علاقة الوالي بالرعية؟","options":["علاقة تسلط واحتجاب عنهم","علاقة رفق ورحمة وتفقد لحاجاتهم وفتح الباب لهم","علاقة تجاهل تام","علاقة شدة دائمة"],"answer":1,"why":"القيادة أمانة وخدمة للناس."},{"type":"mcq","q":"ما الغرض البلاغي لأفعال الأمر الواردة في العهد؟","options":["السخرية","التعجيز","التوجيه والإلزام التربوي والإداري بالخير والعدل","التمني المستحيل"],"answer":2,"why":"هي أوامر توجيهية من إمام إلى واليه."},{"type":"mcq","q":"كيف نطبّق قيم هذا العهد في حياتنا المدرسية؟","options":["بالكسل","بالتحيز للأصدقاء فقط","بتجاهل آراء الزملاء","بالأمانة والعدل والرفق والتشاور عند تولي أي مسؤولية طلابية"],"answer":3,"why":"كل موقع مسؤولية يحتاج العدل والأمانة والشورى."},{"type":"tfr","q":"توظيف الطباق مثل (السرّ × العلن) في النص يفيد شمول المراقبة لله في كل الأحوال.","answer":true,"reasons":["ويزيد العبارة قوةً ووضوحًا في الذهن","يُضعف العبارة","لا دلالة له"],"reason":0},{"type":"tfr","q":"يمتاز أسلوب عهد الإمام ناصر بن مرشد بالجزالة والإيجاز والتأثر بأساليب القرآن والسنة.","answer":true,"reasons":["يمتاز بالعامية والحشو","كما يقتدي بعهود الخلفاء الراشدين لولاتهم","يخلو من البلاغة"],"reason":1},{"type":"tfr","q":"القيادة في التصور الإسلامي والعُماني أمانة ومسؤولية وخدمة للناس لا تسلط عليهم.","answer":true,"reasons":["بلا أي مسؤولية","بل هي تسلط مطلق","وهذا جوهر كل الوصايا الواردة في عهد والي الصير"],"reason":2},{"type":"essay","q":"علّل: لماذا بدأ الإمام عهده بالوصية بتقوى الله قبل سائر الأوامر الإدارية؟","model":"لأن تقوى الله هي الرقيب الداخلي الذي يحفظ الأمانة ويمنع الظلم والهوى في السر والعلن، ومن اتقى الله أقام العدل في كل شيء."},{"type":"essay","q":"ما القيمة التاريخية لوثيقة عهد الإمام ناصر بن مرشد بالنسبة لسلطنة عُمان؟","model":"تُوثّق نضج الفكر الإداري والسياسي العُماني المبكر، وتؤكد أن دولة اليعاربة قامت على العدل والمؤسسية والشورى وحفظ الحقوق."},{"type":"essay","q":"تخيّل أنك اختِرتَ رئيسًا لمجلس طلاب مدرستك؛ اكتب ثلاث وصايا مستوحاة من العهد تلتزم بها.","model":"١) أن أتعامل بعدل وإنصاف مع جميع الطلاب بلا محاباة. ٢) أن أستمع لآراء زملائي وأتشاور معهم. ٣) أن أكون قدوةً في الأمانة والرفق والالتزام."}]}},
  {"id":"g9-arabic-2-u6-1","grade":"g9","subject":"arabic","term":2,"unit":6,"no":1,"title":"القراءة: اللغة تلد الحضارة","summary":"شرح متحرك بـ SVG لدرس القراءة: اللغة تلد الحضارة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-language-births-civilization.html","video":"","pdf":"","notes":["اللغة تلد الحضارة: استعارة تبرز أن اللغة وعاء الفكر وصانعة الحضارة وذاكرة الأمة.","العربية لغة علمية غنية بالاشتقاق، وأثبتت تاريخيًا قدرتها على قيادة العلوم.","واجبنا: القراءة، الكتابة السليمة، إثراء المحتوى العربي الرقمي، والتوازن مع اللغات الأجنبية."],"exercises":["اشرح المقصود بعنوان الدرس «اللغة تلد الحضارة» مبينًا الجمال الفني فيه.","اذكر ثلاثة مقومات تجعل اللغة العربية قادرةً على مواكبة علوم العصر الحديث.","كيف نوفّق بين «تعلّم اللغة الإنجليزية واللغات الحديثة» وبين «الحفاظ على لغتنا العربية»؟"],"levels":{"easy":[{"type":"mcq","q":"ما الصورة الفنية في عنوان النص «اللغة تلد الحضارة»؟","options":["طباق","ترادف لفظي","استعارة مكنية شبّهت اللغة بأمٍّ تلد الحضارة وترعاها","جناس تام"],"answer":2,"why":"حُذف المشبه به (الأم) وأُشير إليه بلازمه (تلد)."},{"type":"mcq","q":"لماذا تُعدّ اللغة أساسًا لقيام أي حضارة إنسانية؟","options":["لأنها بديل عن العمل","لأنها تُستخدم في الشعر فقط","لأنها تمنع التواصل","لأنها وعاء الفكر وأداة حفظ العلوم ونقل الخبرات وتنظيم المجتمع"],"answer":3,"why":"لا يمكن بناء علم أو تعاون مجتمعي دون لغة دقيقة."},{"type":"mcq","q":"ما الميزة اللغوية التي تمنح العربية قدرةً فائقةً على توليد مصطلحات علمية جديدة؟","options":["نظام الاشتقاق الغني (مثل: حاسوب من حسب، وهاتف من هتف)","قلة عدد حروفها","عدم وجود قواعد فيها","الاعتماد على لغة واحدة فقط"],"answer":0,"why":"الاشتقاق يولّد كلمات دقيقة من الجذور العربية الأصيلة."},{"type":"mcq","q":"ما الموقف المتوازن تجاه تعلّم اللغات الأجنبية؟","options":["نهمل العربية تمامًا لصالحها","نتعلمها للاستفادة من العلوم والتواصل مع الاعتزاز بلغتنا الأم وإتقانها","نرفض تعلم أي لغة أجنبية","نخلط اللغات في كل جملة"],"answer":1,"why":"الانفتاح الواعي يجمع الاعتزاز بالعربية وإتقان لغات العالم."}],"medium":[{"type":"mcq","q":"ما الدليل التاريخي على أن اللغة العربية لغة علم وحضارة؟","options":["أنها خالية من المصطلحات","أنها أقدم لغة مكتوبة فقط","استيعابها وإبداعها في الطب والفلك والرياضيات والبصريات في العصر الذهبي","أنها لغة محادثة فقط"],"answer":2,"why":"كانت العربية لغة العلم العالمية لقرون طويلة."},{"type":"mcq","q":"ما العلاقة بين ثراء لغة الإنسان وقدرته على التفكير؟","options":["اللغة تُضعف التفكير","علاقة عكسية","لا علاقة بينهما","علاقة طردية: كلما دقّت اللغة اتضح التفكير وزاد الإبداع"],"answer":3,"why":"الإنسان يفكّر بالكلمات والمفاهيم اللغوية."},{"type":"mcq","q":"من أبرز التحديات المعاصرة التي تواجه اللغة العربية:","options":["ضعف المحتوى العلمي الرقمي وشيوع الكتابة الركيكة في وسائل التواصل","قلة المتحدثين بها في العالم","عجزها عن الاشتقاق","خلوّها من المعاجم"],"answer":0,"why":"التحدي الحقيقي في الإنتاج العلمي والرقمي العربي."},{"type":"tfr","q":"العجز عن إنتاج مصطلحات علمية حديثة سببه قصور في اللغة العربية نفسها.","answer":false,"reasons":["العربية لا تقبل الاشتقاق","نعم العربية عاجزة","بل العربية غنية جدًا بالاشتقاق، والقصور في الإنتاج العلمي والبحثي لأبنائها"],"reason":2},{"type":"tfr","q":"تعلّم اللغات الأجنبية نافع بشرط ألا يكون على حساب إهمال اللغة العربية الأم.","answer":true,"reasons":["فالمثقف الواعي يعتز بلغته وينفتح على لغات العالم","يجب إهمال العربية","يجب منع تعلم اللغات الأجنبية"],"reason":0},{"type":"essay","q":"اشرح المقصود بعنوان الدرس «اللغة تلد الحضارة» مبينًا الجمال الفني فيه.","model":"شبّه الكاتب اللغة بالأم التي تلد الحضارة وترعاها؛ لأن اللغة هي وعاء الفكر وأداة حفظ العلوم ونقل الخبرات التي تقوم عليها كل حضارة."},{"type":"essay","q":"اذكر ثلاثة مقومات تجعل اللغة العربية قادرةً على مواكبة علوم العصر الحديث.","model":"١) نظام الاشتقاق الخصب لتوليد المصطلحات. ٢) ثراء المفردات والمرونة في التعريب. ٣) تجربتها التاريخية الناجحة في استيعاب علوم العالم."}],"hard":[{"type":"mcq","q":"كيف يُسهم الشباب اليوم عمليًا في تعزيز مكانة العربية؟","options":["بالكتابة بحروف لاتينية بدل العربية","بإنتاج محتوى علمي وتعليمي رقمي عربي رصين والحرص على الكتابة السليمة","بترك القراءة","بالتخلي عن الفصحى"],"answer":1,"why":"إثراء الإنترنت بالعلم العربي يرفع مكانة اللغة."},{"type":"mcq","q":"ما المقصود بوصف اللغة بأنها «ذاكرة الأمة»؟","options":["أنها كتاب تاريخ واحد","أنها تقتصر على الماضي فقط","أنها تحفظ تاريخ الأمة ودينها وتراثها وعلومها عبر الأجيال","أنها لا تتطور"],"answer":2,"why":"بفضل اللغة تتواصل الأجيال وتقرأ تراثها."},{"type":"mcq","q":"نوع نص «اللغة تلد الحضارة» هو:","options":["قصيدة رثاء","تقرير ميداني","قصة خيالية","مقال فكري ثقافي"],"answer":3,"why":"يناقش قضية فكرية حضارية بالأدلة."},{"type":"mcq","q":"عندما تضعف اللغة لدى أمة ما، فإن النتيجة المباشرة تكون:","options":["ضعف التفكير والإبداع وتراجع الهوية الحضارية","ازدهار العلوم فورًا","زيادة الاستقلالية","لا يحدث أي تأثير"],"answer":0,"why":"تراجع اللغة ينعكس مباشرةً على الفكر والهوية."},{"type":"tfr","q":"اللغة ليست مجرد أداة تواصل سطحي بل هي وعاء الفكر ومحرك الحضارة.","answer":true,"reasons":["مجرد أصوات بلا أثر فكري","لأن التفكير والإبداع ونقل العلوم كلها تتم عبر اللغة","خاصة بالأدب فقط"],"reason":1},{"type":"tfr","q":"بناء منصات ومحتوى تعليمي عربي رصين على الإنترنت يُعدّ خدمةً حضاريةً للغة العربية.","answer":true,"reasons":["يضر باللغة","لا فائدة منه","لأنه يعالج فجوة المحتوى الرقمي العربي ويدعم الطلاب"],"reason":2},{"type":"tfr","q":"أثبت التاريخ في العصر الذهبي أن العربية قادرة على استيعاب جميع العلوم التجريبية والنظرية.","answer":true,"reasons":["حيث أُلّفت بها أمهات كتب الطب والرياضيات والفلك والبصريات","اقتصر دورها على الشعر فقط","لم تُستخدم في العلوم"],"reason":0},{"type":"essay","q":"كيف نوفّق بين «تعلّم اللغة الإنجليزية واللغات الحديثة» وبين «الحفاظ على لغتنا العربية»؟","model":"بإتقان العربية أولًا واستخدامها في التواصل والكتابة والبحث مع الاعتزاز بها، وتعلّم اللغات الأخرى كوسيلة للانفتاح العلمي والمهني دون إهمال هويتنا."},{"type":"essay","q":"اقترح ثلاث مبادرات طلابية لخدمة اللغة العربية في مدرستك أو عبر الإنترنت.","model":"١) إنشاء نادٍ للقراءة وتلخيص الكتب العلمية بالعربية. ٢) بناء منصات ومحتوى تعليمي عربي رقمي سليم. ٣) إطلاق حملة للكتابة العربية السليمة دون أخطاء إملائية."},{"type":"essay","q":"علّل: لماذا تحرص الدول المتقدمة علميًا على تدريس العلوم بلُغتها الأم؟","model":"لأن فهم الطالب للعلوم وتفكيره الإبداعي يكونان أعمق وأسرع حين يتعلم بلغته التي يفكّر بها منذ طفولته."}]}},
  {"id":"g9-arabic-2-u6-2","grade":"g9","subject":"arabic","term":2,"unit":6,"no":2,"title":"الأنشطة النحوية والصرفية: صيغ المبالغة","summary":"شرح متحرك بـ SVG لدرس الأنشطة النحوية والصرفية: صيغ المبالغة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-intensive-participles.html","video":"","pdf":"","notes":["أوزان صيغ المبالغة الخمسة: فَعّال، مِفْعال، فَعُول، فَعِيل، فَعِل.","تدل على كثرة الفعل وشدته، وتُعرب حسب موقعها في الجملة.","انتبه للسياق في وزن «مِفْعال» للتفريق بين صيغة المبالغة واسم الآلة (مِنشار، مِذياع)."],"exercises":["اذكر الأوزان الخمسة القياسية لصيغ المبالغة مع مثال مضبوط لكل وزن.","حوّل أسماء الفاعلين الآتية إلى صيغ مبالغة واذكر وزن كل منها: صادِق، شاكِر، سامِع، غافِر، ياقِظ.","وظّف كلمة «مِذياع» في جملتين بحيث تكون في الأولى صيغة مبالغة وفي الثانية اسم آلة."],"levels":{"easy":[{"type":"mcq","q":"أي الأوزان الآتية «ليس» من الأوزان القياسية الخمسة لصيغ المبالغة؟","options":["فَعِل","فَعّال","مِفْعال","مَفعول"],"answer":3,"why":"مَفعول هو وزن اسم المفعول من الثلاثي وليس صيغة مبالغة."},{"type":"mcq","q":"ما وزن صيغة المبالغة في كلمة «مِقدام» (كثير الإقدام والشجاعة)؟","options":["مِفْعال","فَعّال","فَعُول","فَعِيل"],"answer":0,"why":"مِقدام على وزن مِفْعال (من الفعل الرباعي أقدمَ)."},{"type":"mcq","q":"أي الكلمات الآتية صيغة مبالغة على وزن «فَعِل»؟","options":["كاتِب وقارِئ","حَذِر وفَطِن","مَكتوب","غفّار"],"answer":1,"why":"حَذِر وفَطِن بفتح الفاء وكسر العين على وزن فَعِل."},{"type":"mcq","q":"حوّل اسم الفاعل «شاكِر» إلى صيغة مبالغة مناسبة:","options":["مُشكِر","مَشكور (مفعول)","شَكور (فَعُول)","شُكر"],"answer":2,"why":"شَكور على وزن فَعُول تدل على كثرة الشكر."}],"medium":[{"type":"mcq","q":"في جملة: «هذا الصحفيّ مِنشارٌ للأخبار الصادقة»، كلمة «مِنشار» تُعدّ:","options":["ظرف مكان","اسم آلة","اسم مفعول","صيغة مبالغة على وزن مِفْعال (كثير النشر)"],"answer":3,"why":"السياق يدل على إنسان كثير نشر الأخبار لا أداة قطع!"},{"type":"mcq","q":"ما صيغة المبالغة من الفعل «عَلِمَ» على وزن «فَعّال»؟","options":["عَلّام","عالِم","مَعلوم","مُعلِّم"],"answer":0,"why":"عَلّام على وزن فَعّال (مثل: علّام الغيوب)."},{"type":"mcq","q":"استخرج صيغة المبالغة ووزنها في: «المؤمنُ صَبورٌ عند الشدائد»:","options":["المؤمن — مُفعِل","صَبور — فَعُول","الشدائد — فعائل","لا توجد صيغة مبالغة"],"answer":1,"why":"صَبور على وزن فَعُول من الفعل صَبَرَ."},{"type":"tfr","q":"الأوزان القياسية الخمسة لصيغ المبالغة هي: فَعّال، مِفْعال، فَعُول، فَعِيل، فَعِل.","answer":true,"reasons":["وتجمعها عبارة: هو مقوال كذاب وأنت حذر والله غفور رحيم","هي ثلاثة أوزان فقط","منها مفعول وفاعل"],"reason":0},{"type":"tfr","q":"كلمة «مِنشار» في جملة «قطع النجارُ الخشبَ بالمِنشار» تُعدّ صيغة مبالغة.","answer":false,"reasons":["نعم صيغة مبالغة","هنا هي «اسم آلة» لأنها تدل على أداة القطع لا على كثرة الفعل","هي اسم فاعل"],"reason":1},{"type":"essay","q":"اذكر الأوزان الخمسة القياسية لصيغ المبالغة مع مثال مضبوط لكل وزن.","model":"١) فَعّال: غفّار. ٢) مِفْعال: مِعطاء. ٣) فَعُول: صَبور. ٤) فَعِيل: رَحيم. ٥) فَعِل: حَذِر."},{"type":"essay","q":"حوّل أسماء الفاعلين الآتية إلى صيغ مبالغة واذكر وزن كل منها: صادِق، شاكِر، سامِع، غافِر، ياقِظ.","model":"صَدوق (فَعُول)، شَكور (فَعُول)، سَميع (فَعِيل)، غَفّار/غَفور (فَعّال/فَعُول)، يَقِظ (فَعِل)."}],"hard":[{"type":"mcq","q":"من أي فعل اشتُقّت صيغة المبالغة «نَذير» و«بَشير»؟","options":["اسْتَنذَرَ","نَظَرَ وبَصُرَ","أنذرَ وبشّرَ (رباعيّين)","تَناذَرَ"],"answer":2,"why":"بعض صيغ المبالغة تُشتق من الرباعي مثل أنذر←نذير وأعطى←معطاء."},{"type":"mcq","q":"أي الجمل الآتية تحتوي على صيغتَي مبالغة مختلفتَي الوزن؟","options":["المعلمُ مخلصٌ مجتهدٌ","الطالبُ كاتبٌ فاهمٌ","البابُ مفتوحٌ والكتابُ مقروءٌ","إنّ اللهَ غفورٌ رحيمٌ"],"answer":3,"why":"غفور (فَعُول) ورحيم (فَعِيل)."},{"type":"mcq","q":"ما معنى كلمة «نَسّاء» في عنوان درس «نسّاء يكتشف أشعة لن ينساها التاريخ»؟","options":["كثير النسيان (صيغة مبالغة على وزن فَعّال)","اسم فاعل","اسم مفعول","جمع امرأة"],"answer":0,"why":"نَسّاء (بتشديد السين) صيغة مبالغة من نسيَ تعني كثير النسيان!"},{"type":"mcq","q":"كيف تُعرب كلمة «حَذِرًا» في جملة: «كنْ حَذِرًا في قيادة السيارة»؟","options":["فاعل مرفوع","خبر كان منصوب وعلامة نصبه الفتحة","مضاف إليه","مبتدأ"],"answer":1,"why":"صيغ المبالغة تُعرب حسب موقعها في الجملة."},{"type":"tfr","q":"تُشتق صيغ المبالغة من الثلاثي غالبًا، وقد تأتي قليلًا من الرباعي مثل مِعطاء ونَذير.","answer":true,"reasons":["لا تأتي من الرباعي أبدًا","تُشتق من السداسي فقط","مِعطاء من أعطى، مِقدام من أقدم، نذير من أنذر"],"reason":2},{"type":"tfr","q":"الفرق بين «عالِم» و«عَلّام» أن «عَلّام» تفيد الكثرة والمبالغة في العلم.","answer":true,"reasons":["فاسم الفاعل يدل على الحدث وصيغة المبالغة تدل على كثرته وشدته","لا فرق في المعنى","عالم أقوى مبالغة"],"reason":0},{"type":"tfr","q":"صيغ المبالغة لا تُثنّى ولا تُجمع ولا تُؤنّث.","answer":false,"reasons":["نعم تبقى مفردة مذكرة دائمًا","بل تُؤنّث وتُثنّى وتُجمع مثل: صبورة، صبوران، صبورون","تُجمع جمع تكسير فقط"],"reason":1},{"type":"essay","q":"وظّف كلمة «مِذياع» في جملتين بحيث تكون في الأولى صيغة مبالغة وفي الثانية اسم آلة.","model":"مبالغة: لا تصاحب رجلًا مِذياعًا للأسرار. اسم آلة: استمعتُ إلى نشرة الأخبار عبر المِذياع."},{"type":"essay","q":"استخرج صيغ المبالغة واذكر وزنها وفعلها: «المؤمنُ الحقُّ قوّالٌ للصدق، مِعطاءٌ للمحتاج، فَطِنٌ لما يدور حوله، بصيرٌ بعواقب الأمور».","model":"قوّال (فَعّال، قال)، مِعطاء (مِفْعال، أعطى)، فَطِن (فَعِل، فطن)، بصير (فَعِيل، بصر)."},{"type":"essay","q":"فسّر البلاغة في استخدام صيغ المبالغة في قوله تعالى: ﴿إنّ اللهَ كان غفورًا رحيمًا﴾ بدلًا من «غافرًا راحمًا».","model":"لأن «غفور ورحيم» صيغتا مبالغة تدلان على سعة مغفرة الله وكثرة رحمته ودوامها بعباده بما لا يؤديه اسم الفاعل وحده."}]}},
  {"id":"g9-arabic-2-u6-3","grade":"g9","subject":"arabic","term":2,"unit":6,"no":3,"title":"الأنشطة الإملائية: تطبيقات على كتابة الألف في أواخر الأسماء والأفعال","summary":"شرح متحرك بـ SVG لدرس الأنشطة الإملائية: تطبيقات على كتابة الألف في أواخر الأسماء والأفعال (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-alif-layyina-applications.html","video":"","pdf":"","notes":["الثلاثي: واو ← (ا) دعا، عصا | ياء ← (ى) رمى، فتى.","فوق الثلاثي: (ى) دائمًا (مستشفى، اهتدى) إلا بعد ياء فتُكتب (ا) (دنيا، هدايا، استحيا).","يُستثنى العَلَم (يحيى)، والأسماء الأعجمية الـ ٥ (موسى، عيسى...)، والحروف الـ ٤ (إلى، على، بلى، حتى)."],"exercises":["علّل رسم الألف اللينة في الكلمات الآتية: سَما، قَضى، مُستشفى، قَضايا.","صوّب الأخطاء الإملائية في الجملة: «دعى مصطفى ربّه في المستشفا أن يحفظ قضايى الأمة ويجعلها علا».","فرّق إملائيًا بين «يحيا» و«يحيى» في جملة واحدة مفيدة مع بيان السبب."],"levels":{"easy":[{"type":"mcq","q":"ما سبب كتابة الألف قائمةً (ا) في الفعل «نَما»؟","options":["لأنه ثلاثي وأصل ألفه واو (ينمو)","لأنه فوق ثلاثي","لأن قبله ياء","لأنه اسم أعجمي"],"answer":0,"why":"مضارعه «ينمو» فأصل الألف واو فتُكتب قائمة."},{"type":"mcq","q":"ما سبب كتابة الألف قائمةً (ا) في كلمة «هَدايا»؟","options":["لأنها ثلاثية أصلها واو","لأنها فوق ثلاثية وسُبقت ألفها بياء","لأنها حرف","لأنها اسم أعجمي"],"answer":1,"why":"في فوق الثلاثي إذا سبقت الألف ياء تُكتب قائمةً (ا)."},{"type":"mcq","q":"أي الكلمات الآتية كُتبت ألفها كتابةً صحيحةً؟","options":["دعى ونمى ورمى","استدعا ومستشفا وهدايى","استدعى ومستشفى وهدايا","على وإلا وحتا"],"answer":2,"why":"استدعى ومستشفى (فوق ثلاثي بلا ياء ← ى)، وهدايا (بعد ياء ← ا)."},{"type":"mcq","q":"أكمل الجملة بالرسم الصحيح: «...... الطالبُ ...... حياةً كريمةً»:","options":["يَحيى / يَحيى","يَحيى / يَحيا","يَحيا / يَحيا","يَحيا / يَحيى"],"answer":3,"why":"الفعل يَحيا بألف قائمة، والاسم العلم يَحيى بألف مقصورة للتفريق!"}],"medium":[{"type":"mcq","q":"ما سبب كتابة الألف مقصورةً (ى) في الاسم «قُرى»؟","options":["لأنه ثلاثي وأصل ألفه ياء (مفردها قرية)","لأنه فوق ثلاثي","لأنه سبق بياء","لأنه أصلها واو"],"answer":0,"why":"مفرد «قُرى» هو «قرية» فتظهر الياء."},{"type":"mcq","q":"ما الرسم الصحيح لكلمة «العصا» عند تجريدها من «ال»؟","options":["عَصى","عَصا (بألف قائمة لأن مثناها عصوان)","عَصاء","عَصي"],"answer":1,"why":"المثنى «عصوان» يكشف أن أصل الألف واو."},{"type":"mcq","q":"أي الأسماء الأعجمية الآتية تُكتب ألفه مقصورةً (ى) استثناءً؟","options":["أمريكا وبريطانيا","فرنسا وإيطاليا","موسى وعيسى وكسرى","آسيا وإفريقيا"],"answer":2,"why":"الأعجمية تُكتب (ا) عدا خمسة منها موسى وعيسى وكسرى."},{"type":"tfr","q":"تُكتب الألف اللينة في الفعل «دعا» مقصورةً هكذا: «دعى».","answer":false,"reasons":["نعم دعى","تُكتب قائمةً «دعا» لأن أصلها واو (يدعو، دعوتُ)","تُكتب دعاء"],"reason":1},{"type":"tfr","q":"في الأسماء والأفعال فوق الثلاثية تُكتب الألف مقصورةً (ى) ما لم تسبقها ياء.","answer":true,"reasons":["نبحث عن أصلها دائمًا","تُكتب قائمةً دائمًا","مثل: مستشفى واهتدى (ى)، ودنيا وهدايا (ا لأن قبلها ياء)"],"reason":2},{"type":"essay","q":"علّل رسم الألف اللينة في الكلمات الآتية: سَما، قَضى، مُستشفى، قَضايا.","model":"سَما: ثلاثي أصله واو (يسمو ← ا). قَضى: ثلاثي أصله ياء (يقضي ← ى). مستشفى: فوق ثلاثي لم تسبق ألفه بياء (ى). قضايا: فوق ثلاثي سبقت ألفه بياء (ا)."},{"type":"essay","q":"صوّب الأخطاء الإملائية في الجملة: «دعى مصطفى ربّه في المستشفا أن يحفظ قضايى الأمة ويجعلها علا».","model":"الصواب: دعا مصطفى ربّه في المستشفى أن يحفظ قضايا الأمة ويجعلها عُلا."}],"hard":[{"type":"mcq","q":"ما سبب رسم الألف مقصورةً في الفعل «سَعى»؟","options":["لأن أصلها واو","لأنه رباعي","لأن قبلها ياء","لأنه ثلاثي وأصل ألفه ياء (المصدر السعي / سعيتُ)"],"answer":3,"why":"سعيتُ والمصدر السعي يثبتان أن أصل الألف ياء."},{"type":"mcq","q":"كيف تُكتب كلمة «بنى» عند اتصالها بالضمير «ها»؟","options":["بَناها (تُكتب قائمةً لأنها صارت متوسطة)","بَنىها","بَنيها","بَنءها"],"answer":0,"why":"الألف المقصورة تتحول لقائمة عند اتصال الفعل بضمير نصب."},{"type":"mcq","q":"ما الحروف الأربعة التي تُكتب ألفها مقصورةً (ى)؟","options":["لا، ما، يا، إلّا","إلى، على، بلى، حتى","في، مِن، عن، إلى","هل، لم، لن، على"],"answer":1,"why":"جميع الحروف قائمة الألف عدا: إلى، على، بلى، حتى."},{"type":"mcq","q":"ما سبب كتابة الألف قائمةً في الفعل «استحيا»؟","options":["لأنه اسم علم","لأنه ثلاثي أصل ألفه واو","لأنه فوق ثلاثي وسبقت ألفه ياء","لأنه حرف"],"answer":2,"why":"كل فوق ثلاثي سبقت ألفه ياء يُكتب بقائمة (استحيا، أعيا)."},{"type":"tfr","q":"الاسم العَلَم «يحيى» يُكتب بألف مقصورة للتفريق بينه وبين الفعل «يحيا».","answer":true,"reasons":["فالفعل «يحيا» يلتزم قاعدة الياء (ا)، والعلم «يحيى» استُثني للتمييز","كلاهما يُكتب بألف قائمة","كلاهما يُكتب بمقصورة"],"reason":0},{"type":"tfr","q":"تُكتب كلمة «موسى» و«عيسى» بألف مقصورة رغم أنهما اسمان أعجميان.","answer":true,"reasons":["تُكتبان بألف قائمة","لأنهما من الأسماء الأعجمية الخمسة المستثناة (موسى، عيسى، كسرى، بخارى، متى)","لأنهما حروف"],"reason":1},{"type":"tfr","q":"لمعرفة أصل الألف في اسم ثلاثي مثل «فتى» أو «عصا» نأتي بالمثنى (فتيان، عصوان).","answer":true,"reasons":["نحذف الحرف الأول","نأتي بالماضي فقط","فتظهر الياء في فتيان والواو في عصوان مباشرة"],"reason":2},{"type":"essay","q":"فرّق إملائيًا بين «يحيا» و«يحيى» في جملة واحدة مفيدة مع بيان السبب.","model":"«يحيا يحيى حياةً طيبةً»؛ الأول فعل سُبقت ألفه بياء فتُكتب قائمة (ا)، والثاني اسم عَلَم كُتب مقصورة (ى) للتفريق بين الاسم والفعل."},{"type":"essay","q":"كيف تميّز أصل الألف في الفعل «سعى» رغم أن مضارعه «يسعى» ينتهي بألف أيضًا؟","model":"بإسناده لتاء الفاعل «سعيتُ» أو الإتيان بالمصدر «السعي»، فتظهر الياء بوضوح."},{"type":"essay","q":"اكتب ثلاث كلمات ثلاثية أصل ألفها واو، وثلاث كلمات فوق ثلاثية سبقت ألفها بياء.","model":"ثلاثي واوي: دعا، سما، عصا. فوق ثلاثي بعد ياء: دنيا، هدايا، استحيا."}]}},
  {"id":"g9-arabic-2-u6-4","grade":"g9","subject":"arabic","term":2,"unit":6,"no":4,"title":"التعبير: تعبير حرّ","summary":"شرح متحرك بـ SVG لدرس التعبير: تعبير حرّ (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-free-composition.html","video":"","pdf":"","notes":["التعبير الحر = اختيار موضوع محدد يهمك + قالب مناسب (مقال/قصة/رسالة) + تخطيط وتنظيم.","اجذب القارئ بعنوان موحٍ ومقدمة حية وتجنّب المقدمات المحفوظة والنسخ.","أبرز أسلوبك الأصيل وراجع النص لغويًا وإملائيًا وترقيميًا قبل التسليم."],"exercises":["اذكر أربع خطوات متسلسلة لكتابة موضوع تعبير حر ناجح.","اقترح عنوانًا جاذبًا وفكرتين رئيستين لموضوع تعبير حر حول «هوايتك المفضلة».","قارن بين «التعبير الوظيفي (مثل التقرير)» و«التعبير الحر الإبداعي»."],"levels":{"easy":[{"type":"mcq","q":"ما المقصود بـ«التعبير الحرّ»؟","options":["الكتابة بلا أي قواعد إملائية أو تنظيم","اختيار الطالب لموضوع وقالب يناسب ميوله مع الالتزام بالتنظيم وسلامة اللغة","نسخ مقال جاهز من الإنترنت","كتابة كلمات متفرقة بلا معنى"],"answer":1,"why":"الحرية في اختيار الموضوع والقالب مع الانضباط الفني واللغوي."},{"type":"mcq","q":"أي العنوانين أنسب وأكثر جاذبيةً لموضوع تعبير حر عن القراءة؟","options":["الكتاب","موضوع تعبير عن القراءة","صفحاتٌ تفتحُ نوافذَ العالم","كلام عن القراءة"],"answer":2,"why":"العنوان الموحي القصير يشدّ القارئ ويدل على الإبداع."},{"type":"mcq","q":"ما فائدة «العصف الذهني» وتخطيط خريطة الأفكار قبل البدء بالكتابة؟","options":["إلغاء المقدمة","إضاعة الوقت","تقليص الأفكار الجيدة","تنظيم الأفكار ومنع التشتّت وتكرار الجمل أثناء التحرير"],"answer":3,"why":"دقيقتان من التخطيط تجعلان النص متماسكًا ومنظمًا."},{"type":"mcq","q":"إذا أراد الطالب التعبير عن «موقف مؤثّر مرّ به في مسابقة رياضية»، فما القالب الأنسب؟","options":["قصة قصيرة (سردية)","تقرير مالي","جدول إحصائي","تعريف معجمي"],"answer":0,"why":"الموقف الإنساني ذو الأحداث يناسبه قالب القصة القصيرة."}],"medium":[{"type":"mcq","q":"أي موضوع مما يأتي يُعدّ «محددًا وناجحًا» أكثر للكتابة في صفحتين؟","options":["العالم كله منذ بدايته","كيف غيّرت هواية البرمجة طريقة تفكيري","العلوم جميعها","التاريخ الإنساني كاملًا"],"answer":1,"why":"الموضوع المحدد يتيح عمقًا وصدقًا بدل العموميات السطحية."},{"type":"mcq","q":"ما أفضل طريقة لبدء مقدمة موضوع تعبير حر؟","options":["عبارة: سأكتب اليوم عن...","مقدمة محفوظة مكررة لا صلة لها بالموضوع","سؤال مثير أو موقف واقعي قصير يشدّ انتباه القارئ","الخاتمة مباشرة"],"answer":2,"why":"الافتتاحية الحية تجذب القارئ وتدخل في صلب الفكرة."},{"type":"mcq","q":"لماذا يُعدّ «النسخ الحرفي» من الإنترنت مفسدًا لهدف التعبير الحرّ؟","options":["لا يفسده أبدًا","لأنه قصير جدًا","لأنه لا يحتوي على نقاط","لأنه يلغي صوت الطالب الأصيل ويحرمه من تنمية مهارة التفكير والكتابة"],"answer":3,"why":"قيمة التعبير الحر في أصالة فكر الكاتب وأسلوبه."},{"type":"tfr","q":"يعني التعبير الحر أن يكتب الطالب كيفما اتفق دون مراعاة للفقرات أو الإملاء أو علامات الترقيم.","answer":false,"reasons":["الإملاء غير مهم في الحر","نعم بلا أي قواعد","الحرية في اختيار الموضوع والقالب، مع الالتزام الكامل بتنظيم الفقرات وسلامة اللغة"],"reason":2},{"type":"tfr","q":"اختيار موضوع محدد يرتبط بتجربة الطالب أو اهتمامه يجعل كتابته أكثر صدقًا وإبداعًا.","answer":true,"reasons":["لأنه يكتب من واقع معرفته وشغفه لا من عموميات محفوظة","الموضوع الغامض العام أفضل","يجب اختيار موضوع لا يعرف عنه شيئًا"],"reason":0},{"type":"essay","q":"اذكر أربع خطوات متسلسلة لكتابة موضوع تعبير حر ناجح.","model":"١) اختيار موضوع محدد يهمك والقالب الأنسب له. ٢) العصف الذهني وتخطيط الأفكار. ٣) كتابة عنوان جاذب ومقدمة وعرض مترابط وخاتمة. ٤) المراجعة الذاتية للإملاء والنحو والترقيم."},{"type":"essay","q":"اقترح عنوانًا جاذبًا وفكرتين رئيستين لموضوع تعبير حر حول «هوايتك المفضلة».","model":"العنوان: «شغفي الصغير.. نافذتي للإبداع». الفكرة ١: كيف بدأت الهواية وما المهارات التي أكسبتني إياها. الفكرة ٢: كيف أوازن بينها وبين دراستي وطموحي المستقبلي بها."}],"hard":[{"type":"mcq","q":"ما الخطوة الأخيرة الضرورية قبل تسليم موضوع التعبير الحر؟","options":["قراءة النص كاملًا لمراجعة وضوح الأفكار والإملاء وعلامات الترقيم","حذف العنوان","دمج الفقرات في فقرة واحدة","إضافة كلمات غامضة"],"answer":0,"why":"المراجعة الذاتية ترفع جودة النص بشكل كبير."},{"type":"mcq","q":"إذا أراد طالب توجيه نصيحة لأصدقائه حول تنظيم الوقت، فما القالب المناسب؟","options":["خريطة جغرافية","رسالة أدبية أو مقال توجيهي","معادلة جبرية","سرد أسطوري"],"answer":1,"why":"الرسالة أو المقال التوجيهي يناسبان النصيحة المباشرة."},{"type":"mcq","q":"تتضمن عناصر القصة القصيرة في التعبير الحر:","options":["الأرقام فقط","التوصيات والتوقيع فقط","الشخصيات، والزمان والمكان، والأحداث، والعقدة، والحل","العنوان وحده"],"answer":2,"why":"هذه هي العناصر الفنية الأساسية للقصة القصيرة."},{"type":"mcq","q":"كيف ينعكس إتقان دروس النحو والإملاء على التعبير الحر؟","options":["يُستخدم في النحو فقط","لا علاقة للنحو بالتعبير الحر","يقيّد الإبداع","يجعل الكتابة فصيحةً سليمةً واضحة المعنى ومؤثرةً في القارئ"],"answer":3,"why":"اللغة السليمة هي الأداة التي تحمل الإبداع الفكري."},{"type":"tfr","q":"يمكن للطالب في التعبير الحر أن يختار القالب الأنسب لفكرته كالمقال أو القصة أو الرسالة.","answer":true,"reasons":["يجب أن يكون مقالًا فقط","تبعًا لطبيعة الفكرة والهدف منها","يجب أن يكون شعرًا فقط"],"reason":1},{"type":"tfr","q":"العصف الذهني وتنظيم الأفكار في مسوّدة قصيرة يمنع التشتت والتكرار.","answer":true,"reasons":["يُستخدم في الرياضيات فقط","يضيّع وقت الطالب بلا فائدة","ويمنح النص تسلسلًا منطقيًا واضحًا"],"reason":2},{"type":"tfr","q":"العنوان الموحي القصير يثير فضول القارئ ويلخّص روح النص.","answer":true,"reasons":["مثل «شاشة تصنع مستقبلًا» بدل «موضوع عن الحاسوب»","العنوان غير ضروري","الأفضل عنوان طويل جدًا"],"reason":0},{"type":"essay","q":"قارن بين «التعبير الوظيفي (مثل التقرير)» و«التعبير الحر الإبداعي».","model":"التقرير مقيد بشكل محدد ولغة موضوعية محايدة لنقل حقائق عملية؛ أما التعبير الحر فيتيح اختيار الموضوع والقالب وإبراز العاطفة والأسلوب الأدبي الأصيل."},{"type":"essay","q":"اكتب مقدمةً مشوّقةً (٣ أسطر) لموضوع تعبير حر بعنوان «حلمٌ بدأ من مكتبة المدرسة».","model":"هل تصدّق أن كتابًا واحدًا قد يغيّر مسار حياتك بالكامل؟ في ظهيرة يومٍ عاديٍّ بمكتبة المدرسة، التقطتُ كتابًا عن الفلك بالصدفة، ومنذ تلك اللحظة لم تعد النجوم مجرد نقاطٍ مضيئةٍ في السماء، بل صارت حلمًا أسعى لتحقيقه!"},{"type":"essay","q":"كيف تتجنّب الوقوع في «المقدمات المحفوظة المكررة» عند كتابة التعبير؟","model":"بالدخول المباشر إلى فكرة الموضوع عبر سؤال مثير، أو موقف واقعي قصير، أو صورة معبّرة ترتبط بالعنوان نفسه."}]}},
  {"id":"g9-arabic-2-u6-5","grade":"g9","subject":"arabic","term":2,"unit":6,"no":5,"title":"الاستماع: عباس بن فرناس رائد الفضاء","summary":"شرح متحرك بـ SVG لدرس الاستماع: عباس بن فرناس رائد الفضاء (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-abbas-ibn-firnas.html","video":"","pdf":"","notes":["عباس بن فرناس (حكيم الأندلس): أول من نفّذ تجربة طيران علمية، ونجا منها بعد تحليل خطأ الهبوط (الذيل).","اختراعاته: الزجاج من الرمل والعدسات، الساعة المائية، والقبة السماوية.","كرّمه العالم بتسمية فوهة قمرية باسمه؛ وسيرته درس في الشجاعة العلمية والابتكار."],"exercises":["اذكر أربعة إنجازات واختراعات علمية لـ«عباس بن فرناس» غير تجربة الطيران.","اشرح باختصار كيف نفّذ ابن فرناس تجربة الطيران، وما السبب العلمي لإصابته عند الهبوط.","كيف نردّ على من يستهين بتجربة ابن فرناس لأنها انتهت بسقوط عند الهبوط؟"],"levels":{"easy":[{"type":"mcq","q":"أين عاش العالم المخترع عباس بن فرناس؟","options":["في أمريكا","في الصين","في قرطبة بالأندلس (القرن ٣ هـ / ٩ م)","في أوروبا الحديثة فقط"],"answer":2,"why":"عاش في قرطبة بالأندلس ولُقّب بحكيم الأندلس."},{"type":"mcq","q":"ما الخطأ الهندسي الذي تسبّب في إصابة ابن فرناس عند «الهبوط» في تجربة الطيران؟","options":["أنه قفز في البحر","عدم وجود رياح","أنه لم يصنع جناحين","إغفاله دور «الذيل» في توازن الطائر وتهدئة سرعة الهبوط"],"answer":3,"why":"نجح في التحليق لكن غياب الذيل صعّب الهبوط الآمن."},{"type":"mcq","q":"أي مما يأتي «ليس» من اختراعات عباس بن فرناس؟","options":["المحرك البخاري الحديث","صناعة الزجاج الشفاف من الرمل والعدسات","الساعة المائية (الميقاتة)","القبة السماوية الفلكية"],"answer":0,"why":"المحرك البخاري اختُرع بعده بقرون طويلة."},{"type":"mcq","q":"كيف كرّم العالم الحديث والاتحاد الفلكي الدولي عباس بن فرناس؟","options":["أخفوا اسمه من الكتب","أطلقوا اسمه على فوهة على سطح القمر","نسبوا اختراعه لغيره","لم يُكرَّم أبدًا"],"answer":1,"why":"توجد فوهة قمرية رسمية باسم «Ibn Firnas»."}],"medium":[{"type":"mcq","q":"ما الحقيقة التاريخية حول مصير عباس بن فرناس بعد تجربة الطيران؟","options":["توقف عن العلم تمامًا","مات في نفس اللحظة","أصيب في ظهره لكنه نجا وعاش بعدها سنواتٍ طويلةً","لم يجرّب الطيران قط"],"answer":2,"why":"الشائعة بموته فورًا غير صحيحة تاريخيًا."},{"type":"mcq","q":"ما المنهج الذي اعتمد عليه ابن فرناس قبل صنع الجناحين؟","options":["الاعتماد على الحظ","المغامرة العشوائية بلا دراسة","تقليد السفن فقط","ملاحظة الطبيعة ودراسة تشريح أجنحة الطيور وحركة الهواء علميًا"],"answer":3,"why":"جمع بين الدراسة العلمية والتجربة العملية."},{"type":"mcq","q":"ما المقصود بـ«القبة السماوية» التي صمّمها عباس بن فرناس في بيته؟","options":["غرفة مجهزة بمجسمات للنجوم والكواكب والغيوم والبرق والرعد لتعليم الفلك","مرصد حديث بالتلسكوب","قبة مسجد فقط","خيمة صحراوية"],"answer":0,"why":"كانت أول محاكاة تعليمية (بلانيتاريوم) في التاريخ!"},{"type":"tfr","q":"اعتمد عباس بن فرناس في تجربة الطيران على دراسة علمية لحركة الطيور والهواء.","answer":true,"reasons":["فصمّم جناحين متناسبين وحلّق لمسافة واضحة قبل الهبوط","كانت قفزة عشوائية بلا تفكير","لم يقم بأي تجربة"],"reason":0},{"type":"tfr","q":"توفي عباس بن فرناس فور سقوطه في تجربة الطيران.","answer":false,"reasons":["نعم توفي فورًا","بل أُصيب في ظهره ونجا وعاش بعدها سنواتٍ طويلةً","سقط في البحر"],"reason":1},{"type":"essay","q":"اذكر أربعة إنجازات واختراعات علمية لـ«عباس بن فرناس» غير تجربة الطيران.","model":"١) صناعة الزجاج الشفاف من الرمل والحجارة. ٢) صناعة العدسات الطبية لتحسين الرؤية. ٣) ابتكار الساعة المائية (الميقاتة). ٤) تصميم القبة السماوية الفلكية في منزله."},{"type":"essay","q":"اشرح باختصار كيف نفّذ ابن فرناس تجربة الطيران، وما السبب العلمي لإصابته عند الهبوط.","model":"درس أجنحة الطيور والرياح وصنع جناحين من الحرير والريش، وقفز من مرتفع الرصافة فحلّق مسافةً جيدةً، لكنه أصيب عند الهبوط لأنه أغفل دور «الذيل» في التوازن وتخفيف سرعة النزول."}],"hard":[{"type":"mcq","q":"ما اللقب الذي عُرف به عباس بن فرناس لسعة علمه وموسوعيته؟","options":["أمير الشعراء","حكيم الأندلس","المعلم الأول","أبو الطب"],"answer":1,"why":"لُقّب بحكيم الأندلس لتعدّد علومه وابتكاراته."},{"type":"mcq","q":"ما القيمة العلمية الأهم التي نتعلمها من محاولة ابن فرناس للطيران؟","options":["التقليد دون ابتكار","الخوف من أي محاولة جديدة","الشجاعة العلمية والتعلّم من أخطاء التجربة الأولى لتمهيد الطريق للمستقبل","الاستسلام عند أول صعوبة"],"answer":2,"why":"التجربة والتحليل هما طريق التقدم العلمي."},{"type":"mcq","q":"ما فائدة الساعة المائية (الميقاتة) التي ابتكرها ابن فرناس؟","options":["توجيه السفن","قياس وزن الحبوب","صناعة الزجاج","قياس الوقت بدقة حتى في الليل أو الأيام الغائمة دون شمس"],"answer":3,"why":"كانت بديلًا دقيقًا عن الساعة الشمسية."},{"type":"mcq","q":"بمَ ربط ابن فرناس بين الفيزياء والبصريات في أحد اختراعاته؟","options":["صناعة الزجاج الصافي من الرمل والعدسات الطبية لتصحيح البصر","بناء الجسور","تأليف المعاجم","كتابة القصائد"],"answer":0,"why":"سبق عصره في صناعة الزجاج والعدسات."},{"type":"tfr","q":"ابتكر عباس بن فرناس طريقةً لصناعة الزجاج الشفاف من الرمل والعدسات الطبية.","answer":true,"reasons":["عمل في الشعر فقط","لم يخترع شيئًا سوى الجناحين","إلى جانب الساعة المائية والقبة السماوية الفلكية"],"reason":2},{"type":"tfr","q":"أطلق الاتحاد الفلكي الدولي اسم «ابن فرناس» على فوهة على سطح القمر تقديرًا لريادته.","answer":true,"reasons":["وهو اعتراف عالمي بإسهامه في تاريخ الطيران والعلوم","لم يُكرّم عالميًا","أطلقوا اسمه على محيط"],"reason":0},{"type":"tfr","q":"الفشل الجزئي في التجربة العلمية يعني وجوب التوقف عن البحث والابتكار.","answer":false,"reasons":["نعم يجب التوقف فورًا","بل هو خطوة للتعلم وتحليل الخطأ والوصول للنجاح كما حدث في تطور الطيران","العلم لا يعرف التجربة"],"reason":1},{"type":"essay","q":"كيف نردّ على من يستهين بتجربة ابن فرناس لأنها انتهت بسقوط عند الهبوط؟","model":"التجربة الأولى في أي علم نادرًا ما تكون كاملة؛ لقد أثبت ابن فرناس إمكانية التحليق بالعلم والملاحظة، وكشف العالم من تجربته أهمية الذيل والتوازن، ولذلك كرّمه العالم بتسمية فوهة قمرية باسمه."},{"type":"essay","q":"اذكر ثلاث صفات لشخصية المخترع والباحث الناجح مستلهمة من سيرة ابن فرناس.","model":"١) الملاحظة الدقيقة للطبيعة والفضول العلمي. ٢) الشجاعة والمبادرة بالتجربة العملية. ٣) الموسوعية وربط العلوم المختلفة معًا."},{"type":"essay","q":"اربط بين درس «عباس بن فرناس» ودرس «عالمية الحضارة الإنسانية» الذي درسته سابقًا.","model":"إنجازات ابن فرناس في الطيران والبصريات والفلك مثال حيّ على إسهام العلماء العرب المسلمين في بناء الحضارة الإنسانية وتمهيد الطريق للعلوم الحديثة."}]}},
  {"id":"g9-arabic-2-u7-1","grade":"g9","subject":"arabic","term":2,"unit":7,"no":1,"title":"القراءة: نسّاء يكتشف أشعة لن ينساها التاريخ","summary":"شرح متحرك بـ SVG لدرس القراءة: نسّاء يكتشف أشعة لن ينساها التاريخ (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-roentgen-xrays-story.html","video":"","pdf":"","notes":["فيلهلم رونتجن (١٨٩٥م) اكتشف الأشعة السينية (X = س رمز المجهول) بفضل الملاحظة الدقيقة وظل المفتاح.","استخداماتها: الطب (العظام والأسنان) والأمن (المطارات) والتجارة والصناعة.","وهب رونتجن اكتشافه مجانًا للبشرية ونال أول جائزة نوبل في الفيزياء."],"exercises":["اشرح العلاقة بين اسم الأشعة بالإنجليزية (X-rays) واسمها بالعربية (الأشعة السينية).","اذكر ثلاثة استخدامات طبية واستخدامين غير طبيين للأشعة السينية.","كيف ساعدت «الملاحظة الدقيقة» رونتجن في اكتشاف الأشعة السينية رغم نسيانه؟"],"levels":{"easy":[{"type":"mcq","q":"من العالم الذي اكتشف الأشعة السينية (X-rays)؟","options":["توماس إديسون","إسحاق نيوتن","لويس باستور","العالم الألماني فيلهلم رونتجن"],"answer":3,"why":"فيلهلم رونتجن اكتشفها عام ١٨٩٥م ونال بها أول جائزة نوبل في الفيزياء."},{"type":"mcq","q":"لماذا أطلق النص على رونتجن صفة «نسّاء»؟","options":["لكثرة نسيانه لمواعيد طعامه وما يريد فعله لشدة انغماسه في أبحاثه","لأنه نسي اسمه","لأنه لم يدرس الفيزياء","لأنه لم يجرِ تجارب"],"answer":0,"why":"نسّاء صيغة مبالغة على وزن فعّال تعني كثير النسيان."},{"type":"mcq","q":"ما العلاقة البلاغية بين «نسّاء» و«لن ينساها» في عنوان الدرس؟","options":["ترادف","طباق يثير التشويق ويبرز المفارقة الجميلة","سجع","استفهام"],"answer":1,"why":"المفارقة بين كثرة نسيانه وخلود اكتشافه تشدّ القارئ."},{"type":"mcq","q":"لماذا سُمّيت هذه الأشعة بـ«الأشعة السينية (X-rays)»؟","options":["لأنها سريعة جدًا فقط","نسبةً إلى مدينة تبدأ بحرف السين","نسبةً إلى رمز المجهول (X في الإنجليزية و«س» في العربية) لجهله بطبيعتها أولًا","نسبةً لاسم زوجته"],"answer":2,"why":"X و«س» هما رمزا المجهول في الرياضيات."}],"medium":[{"type":"mcq","q":"ما الدور الذي لعبه «مفتاح مكتب رونتجن» في قصة الاكتشاف؟","options":["لم يكن له أي دور","فتح به باب المختبر فقط","كسر به الأنبوب الزجاجي","ظهر ظلّ المفتاح المعدني واضحًا على اللوح الفوتوغرافي بعد تحميضه مما أكد نفاذ الأشعة"],"answer":3,"why":"ظهور ظل المفتاح عبر الغلاف أثبت وجود أشعة نافذة تخترق الورق."},{"type":"mcq","q":"أي مما يأتي «ليس» من استخدامات الأشعة السينية في الطب؟","options":["توليد الكهرباء في السدود","تصوير الكسور في العظام","كشف تسوس الأسنان","تحديد موضع الأجسام المعدنية المبتلعة"],"answer":0,"why":"توليد الكهرباء ليس من استخدامات الأشعة السينية."},{"type":"mcq","q":"كيف تُسهم الأشعة السينية في تعزيز الثقة التجارية والأمنية؟","options":["في طهي الطعام","في فحص الحقائب بالمطارات وكشف أوراق النقد واللؤلؤ المزيف","في زراعة الأشجار","في قياس سرعة الرياح"],"answer":1,"why":"تكشف بنية المواد الداخلية دون إتلافها."},{"type":"tfr","q":"سُمّيت الأشعة السينية بهذا الاسم لأن «س» بالعربية تقابل «X» بالإنجليزية رمزًا للمجهول.","answer":true,"reasons":["سميت نسبة لاسمه","فقد أطلق عليها رونتجن أشعة X لأنه لم يعرف طبيعتها في البداية","سميت نسبة للونها"],"reason":1},{"type":"tfr","q":"الصدفة وحدها دون ملاحظة وعقل علمي مستعد تكفي لتحقيق الاكتشافات الكبرى.","answer":false,"reasons":["لم يكن رونتجن عالمًا","نعم الصدفة وحدها تكفي","الصدفة لا تنفع إلا عقلًا متيقظًا ملاحظًا ومثابرًا كعقل رونتجن"],"reason":2},{"type":"essay","q":"اشرح العلاقة بين اسم الأشعة بالإنجليزية (X-rays) واسمها بالعربية (الأشعة السينية).","model":"أطلق عليها رونتجن «X» وهو رمز المجهول في الرياضيات الإنجليزية لجهله بطبيعتها أولًا، وعند التعريب استُخدم رمز المجهول في الجبر العربي «س» فسمّيت «الأشعة السينية»."},{"type":"essay","q":"اذكر ثلاثة استخدامات طبية واستخدامين غير طبيين للأشعة السينية.","model":"طبية: ١) تصوير كسور العظام. ٢) فحص الأسنان. ٣) كشف الأجسام المعدنية المبتلعة. غير طبية: ١) فحص الحقائب في المطارات. ٢) كشف النقود المزيفة والشقوق في المعادن."}],"hard":[{"type":"mcq","q":"ما الموقف الأخلاقي العظيم الذي اتخذه رونتجن بعد اكتشافه؟","options":["أخفى الاكتشاف عشرين سنة","باع الاكتشاف بأعلى ثمن ومنع المستشفيات منه","رفض احتكار براءة الاختراع ووهب الاكتشاف مجانًا لخدمة البشرية","دمّر أجهزته"],"answer":2,"why":"ضرب مثلًا عالميًا في نبل العلماء."},{"type":"mcq","q":"ما أول صورة طبية شهيرة التقطها رونتجن بالأشعة السينية؟","options":["صورة لشجرة","صورة لأسد","صورة لمدينة برلين","صورة لعظام يد زوجته وخاتمها المعدني"],"answer":3,"why":"أذهلت صورة عظام يد زوجته العالم أجمع."},{"type":"mcq","q":"ما معنى كلمة «المحارة» في سياق الكشف عن اللؤلؤ؟","options":["الصدفة البحرية التي يتكوّن بداخلها اللؤلؤ","الشبكة الحديدية","السفينة الكبيرة","موج البحر"],"answer":0,"why":"المحارة هي الصدفة البحرية."},{"type":"mcq","q":"ما نوع أسلوب نص «نسّاء يكتشف أشعة لن ينساها التاريخ»؟","options":["أسلوب قانوني جاف","أسلوب علمي متأدّب يجمع التشويق القصصي والحقائق العلمية","شعر عمودي","تقرير مالي"],"answer":1,"why":"يبسّط قصة اكتشاف علمي بلغة أدبية مشوّقة."},{"type":"tfr","q":"تُستخدم الأشعة السينية في المجال الطبي لتصوير العظام والأسنان، وفي المطارات لفحص الحقائب.","answer":true,"reasons":["بفضل قدرتها على اختراق الأنسجة والورق وتوقفها عند العظام والمعادن","تقتصر على الطب فقط","لا تخترق الورق"],"reason":0},{"type":"tfr","q":"احتكر رونتجن براءة اختراع الأشعة السينية ليحقق ثروةً شخصيةً ضخمةً.","answer":false,"reasons":["نعم احتكرها","بل رفض احتكارها ووهب اكتشافه مجانًا للبشرية جمعاء","باعها لشركة واحدة"],"reason":1},{"type":"tfr","q":"كلمة «نسّاء» في عنوان الدرس صيغة مبالغة على وزن «فَعّال».","answer":true,"reasons":["هي اسم آلة","هي جمع امرأة","وتعني كثير النسيان (من الفعل نسيَ)"],"reason":2},{"type":"essay","q":"كيف ساعدت «الملاحظة الدقيقة» رونتجن في اكتشاف الأشعة السينية رغم نسيانه؟","model":"حين رأى ظل المفتاح على اللوح الفوتوغرافي وتوهّج الشاشة في الظلام، لم يتجاهل الظاهرة بل تتبّع سببها بالتجارب المنظمة حتى كشف الأشعة."},{"type":"essay","q":"ما القيمة الأخلاقية التي نستخلصها من رفض رونتجن احتكار براءة اختراع الأشعة السينية؟","model":"أن العلم رسالة إنسانية سامية تهدف لخدمة البشرية وتخفيف آلام المرضى قبل السعي للمكاسب المادية."},{"type":"essay","q":"وضّح الجمال الفني في عنوان الدرس «نسّاء يكتشف أشعة لن ينساها التاريخ».","model":"جمع بين «نسّاء» (كثير النسيان) و«لن ينساها» في طباق لفظي ومعنوي طريف يشد انتباه القارئ ويلخّص مفارقة القصة."}]}},
  {"id":"g9-arabic-2-u7-2","grade":"g9","subject":"arabic","term":2,"unit":7,"no":2,"title":"الأنشطة النحوية والصرفية: اسما المكان والزمان واسم الآلة","summary":"شرح متحرك بـ SVG لدرس الأنشطة النحوية والصرفية: اسما المكان والزمان واسم الآلة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-place-time-tool-nouns.html","video":"","pdf":"","notes":["المكان والزمان (ثلاثي): مَفْعَل (يَكتُب/يَلعَب/سعى) | مَفْعِل (يَجلِس/وَعَدَ).","المكان والزمان (غير ثلاثي): مُـ + فتح ما قبل الآخر (مُلتقى، مُستشفى)، والسياق يميّزها عن اسم المفعول.","اسم الآلة: قياسي قديم (مِفْعَل، مِفْعال، مِفْعَلة)، قياسي حديث (فَعّالة، فاعول، فاعلة)، وجامد (قلم، سيف، فأس)."],"exercises":["صُغ اسم المكان أو الزمان من الأفعال الآتية مع الضبط وبيان الوزن: لَعِبَ، وَعَدَ، هَبَطَ، جَرى، اجتَمَعَ.","وظّف كلمة «مُستقبَل» في ثلاث جمل بحيث تكون: (١) اسم زمان، (٢) اسم مكان، (٣) اسم مفعول.","صنّف أسماء الآلة الآتية إلى قياسي (واذكر وزنه) وجامد: مِبرد، سِكّين، حاسوب، مِسطرة، قَلَم، طابعة."],"levels":{"easy":[{"type":"mcq","q":"ما وزن اسم المكان «مَوقِف» ولماذا كُسرت ما قبل آخره؟","options":["مَفْعِل — لأنه من فعل ثلاثي مثال واوي (وَقَفَ)","مَفْعَل — لأنه مضموم العين","مِفْعال — لأنه اسم آلة","مُفعَل — لأنه رباعي"],"answer":0,"why":"المثال الواوي مثل وقف ووعد وولد يأتي على مَفْعِل."},{"type":"mcq","q":"في جملة: «الفجرُ مَطلَعُ النورِ»، كلمة «مَطلَع» تُعدّ:","options":["اسم مكان","اسم زمان (لوجود قرينة الزمن: الفجر)","اسم آلة","اسم مفعول"],"answer":1,"why":"دلت الجملة على وقت طلوع النور."},{"type":"mcq","q":"ما وزن اسم المكان «مَسعًى» ولماذا فُتحت عينه؟","options":["مُفعَل — لأنه خماسي","مَفْعِل — لأنه مثال واوي","مَفْعَل — لأنه من فعل ثلاثي معتل الآخر (سعى)","فاعِل"],"answer":2,"why":"الثلاثي الناقص (معتل الآخر) يأتي دائمًا على مَفْعَل."},{"type":"mcq","q":"أي الكلمات الآتية يُعدّ «اسم آلة جامدًا (سماعيًا)»؟","options":["حاسوب وطابعة","مِفتاح ومِنشار","غَسّالة وثَلّاجة","قَلَم وسَيف وفأس"],"answer":3,"why":"قلم وسيف وفأس أسماء آلة جامدة ليست مشتقة من أفعال."}],"medium":[{"type":"mcq","q":"ما وزن اسم الآلة الحديث في كلمة «حاسوب»؟","options":["فاعول","مِفْعال","فَعّالة","مِفْعَل"],"answer":0,"why":"حاسوب وصاروخ على وزن فاعول من الأوزان الحديثة."},{"type":"mcq","q":"في جملة: «صحارُ مُلتقى التجّارِ قديمًا»، كلمة «مُلتقى» تُعدّ:","options":["اسم زمان","اسم مكان من فعل غير ثلاثي (التقى)","اسم مفعول","اسم آلة"],"answer":1,"why":"دلت على المكان (صحار) وصيغت بميم مضمومة وفتح ما قبل الآخر."},{"type":"mcq","q":"ما اسم المكان من الفعل «جَلَسَ» (مضارعه يَجلِسُ)؟","options":["مِجلاس","مَجلَس (مَفْعَل)","مَجلِس (مَفْعِل)","جالِس"],"answer":2,"why":"مكسور العين في المضارع فيأتي على مَفْعِل."},{"type":"tfr","q":"يأتي اسم المكان والزمان من الفعل الثلاثي الناقص (مثل سعى ورمى) على وزن «مَفْعَل» بفتح العين دائمًا.","answer":true,"reasons":["يأتي على مِفْعال","يأتي على مَفْعِل بالكسر","مثل: مَسعى، مَرمى، مَجرى، مَأوى"],"reason":2},{"type":"tfr","q":"يُفرّق بين اسم المكان واسم الزمان واسم المفعول في غير الثلاثي (مثل مُلتقى ومُستخرَج) عن طريق السياق.","answer":true,"reasons":["لأن صياغتها واحدة: ميم مضمومة وفتح ما قبل الآخر","تختلف في الوزن تمامًا","لا يمكن التفريق بينها"],"reason":0},{"type":"essay","q":"صُغ اسم المكان أو الزمان من الأفعال الآتية مع الضبط وبيان الوزن: لَعِبَ، وَعَدَ، هَبَطَ، جَرى، اجتَمَعَ.","model":"مَلعَب (مَفْعَل)، مَوعِد (مَفْعِل)، مَهبِط (مَفْعِل)، مَجرى (مَفْعَل)، مُجتَمَع (مُفتَعَل — غير ثلاثي)."},{"type":"essay","q":"وظّف كلمة «مُستقبَل» في ثلاث جمل بحيث تكون: (١) اسم زمان، (٢) اسم مكان، (٣) اسم مفعول.","model":"١) زمان: الصباحُ مُستقبَلُ اليومِ الجديد. ٢) مكان: قاعةُ المطارِ مُستقبَلُ الضيوف. ٣) مفعول: الضيفُ مُستقبَلٌ بحفاوةٍ في عُمان."}],"hard":[{"type":"mcq","q":"ما وزن اسم الآلة «مِسطرة»؟","options":["فاعلة","مَفْعَل","فَعّالة","مِفْعَلة"],"answer":3,"why":"مِسطرة ومِكنسة على وزن مِفْعَلة (ميم مكسورة)."},{"type":"mcq","q":"في جملة: «البضاعةُ مُستخرَجةٌ من الميناء»، كلمة «مُستخرَجة» تُعدّ:","options":["اسم مفعول (لأنها وقع عليها الاستخراج)","اسم مكان","اسم زمان","اسم آلة"],"answer":0,"why":"السياق يدل على ما وقع عليه الفعل (البضاعة)."},{"type":"mcq","q":"أي الكلمات الآتية «اسم مكان» لحقته تاء التأنيث؟","options":["ثَلّاجة وغَسّالة","مَكتبة ومَدرسة ومَزرعة","ساقية وطابعة","مِكنسة ومِمحاة"],"answer":1,"why":"مَكتبة ومَدرسة (بميم مفتوحة) تدلان على مكان الكتابة والدراسة."},{"type":"mcq","q":"ما وزن اسم الآلة في كلمة «غَسّالة»؟","options":["مَفْعَلة","مِفْعَلة","فَعّالة (وزن قياسي حديث)","فاعلة"],"answer":2,"why":"غسالة وثلاجة وسيارة على وزن فَعّالة القياسي الحديث."},{"type":"tfr","q":"كلمة «مِنشار» و«مِفتاح» تبدآن بميم مفتوحة مثل اسم المكان.","answer":false,"reasons":["نعم بميم مفتوحة","بل تبدآن بميم مكسورة (مِـ) على وزن مِفْعال","بميم مضمومة"],"reason":1},{"type":"tfr","q":"كلمة «سَيف» و«قَلَم» من أسماء الآلة الجامدة (السماعية).","answer":true,"reasons":["هي أسماء مكان","هي مشتقة على وزن مِفْعَل","لأنها ليست مشتقة من فعل ولا تخضع لأوزان قياسية"],"reason":2},{"type":"tfr","q":"الوزن «فَعّالة» (مثل ثَلّاجة وغَسّالة) من الأوزان القياسية الحديثة التي أقرّها مجمع اللغة العربية.","answer":true,"reasons":["لمواكبة المخترعات والآلات الحديثة بأسماء عربية فصيحة","هو وزن غير عربي","هو وزن اسم الزمان"],"reason":0},{"type":"essay","q":"صنّف أسماء الآلة الآتية إلى قياسي (واذكر وزنه) وجامد: مِبرد، سِكّين، حاسوب، مِسطرة، قَلَم، طابعة.","model":"قياسي: مِبرد (مِفْعَل)، حاسوب (فاعول)، مِسطرة (مِفْعَلة)، طابعة (فاعلة). جامد: سِكّين، قَلَم."},{"type":"essay","q":"علّل مجيء «مَكتَب» بفتح التاء ومجيء «مَجلِس» بكسر اللام.","model":"«مَكتَب» مضارعه يَكتُبُ (مضموم العين ← مَفْعَل)، أما «مَجلِس» فمضارعه يَجلِسُ (مكسور العين ← مَفْعِل)."},{"type":"essay","q":"اشرح كيف تفرّق بين «مَكنسة» و«مِكنسة» أو بين «مَفْعَلة» للمكان و«مِفْعَلة» للآلة.","model":"اسم المكان ميمه مفتوحة (مَدرسة، مَكتبة: مكان الفعل)، أما اسم الآلة فميمه مكسورة (مِكنسة، مِسطرة: أداة الفعل)."}]}},
  {"id":"g9-arabic-2-u7-3","grade":"g9","subject":"arabic","term":2,"unit":7,"no":3,"title":"الأنشطة الإملائية: تطبيقات إملائية شاملة","summary":"شرح متحرك بـ SVG لدرس الأنشطة الإملائية: تطبيقات إملائية شاملة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-spelling-review-u7.html","video":"","pdf":"","notes":["الوصل/القطع: ٤ قطع | ٥ و٦ وأمر ٣ وصل | مضارع أنا قطع.","الهمزات: المتوسطة (سلم القوة + بيئة وقراءة) | المتطرفة (ما قبلها فقط + سماءً وجزءًا وشيئًا).","الألف اللينة: ثلاثي (واو→ا، ياء→ى) | فوق ثلاثي (ى إلا بعد ياء→ا، وعلم يحيى ى)."],"exercises":["صوّب جميع الأخطاء الإملائية في الفقرة الآتية (٦ أخطاء): «إتجهَ أحمدُ إلى المستشفا مساءًا، وسئلَ الطبيبَ عَمّا يعانيه أخوه؟ فدعى له بالشفاء».","علّل رسم كل كلمة مما يلي: مَشِيئَة، بَرِيء، إِحسان، اهتدى.","فرّق إملائيًا بين: (أ) «ألّا» و«إلّا»، (ب) «لِمَ» و«لِما» في جمل مفيدة."],"levels":{"easy":[{"type":"mcq","q":"أي جملة من الآتي تخلو تمامًا من أي خطأ إملائي؟","options":["إستقبلَ يحيا ضيوفَه مساءًا، ودعى لهم بالخير في الدنى.","استقبلَ يحيى ضيوفَه مساءً، ودعا لهم بالخير في الدنيا.","استقبلَ يحيى ضيوفَه مساءًا، ودعا لهم في الدنيا.","إستقبلَ يحيى ضيوفَه مساءً، ودعى لهم في الدنيا."],"answer":1,"why":"استقبل (وصل)، يحيى (علم: ى)، مساءً (بلا ألف)، دعا (واو: ا)، الدنيا (بعد ياء: ا)."},{"type":"mcq","q":"ما التصويب الصحيح للجملة: «عَمّا تبحث يا صديقي؟» (بغرض السؤال)","options":["عَمّاء تبحث يا صديقي؟","عن ما تبحث يا صديقي؟","عَمَّ تبحث يا صديقي؟","تبقى كما هي"],"answer":2,"why":"ما الاستفهامية بعد «عن» تُوصل وتُحذف ألفها."},{"type":"mcq","q":"أكمل الفراغات بالرسم الصحيح: «رأيتُ ...... مجتهدًا في ...... جميلة»:","options":["شَئًا / بِيئَةٍ","شَيءًا / بِيأَةٍ","شَيئًا / بِيءَةٍ","شَيْئًا / بِيئَةٍ"],"answer":3,"why":"شيئًا (الياء تتصل ← نبرة+ألف)، بيئة (بعد ياء ساكنة ← نبرة)."},{"type":"mcq","q":"أي مجموعة كلمات جميعها صحيحة إملائيًا؟","options":["استخدام، إكرام، قراءة، شاطئ","إستخدام، اكرام، قراأة، شاطيء","استخدام، إكرام، قرائة، شاطئ","إستخدام، إكرام، قراءة، شاطئ"],"answer":0,"why":"استخدام (وصل)، إكرام (رباعي قطع)، قراءة (سطر)، شاطئ (بعد كسر: ئ)."}],"medium":[{"type":"mcq","q":"ما التصويب الإملائي لكلمة «مُتفائل» في جملة «المؤمن متفائل»؟","options":["مُتَفاءَل","مُتَفائِل (صحيحة كما هي على نبرة لأنها مكسورة بعد ألف مد)","مُتَفاؤِل","مُتَفاأل"],"answer":1,"why":"الهمزة مكسورة والكسرة أقوى الحركات فتُكتب على نبرة."},{"type":"mcq","q":"أكمل الجملة بالرسم الصحيح: «قرأتُ ...... من الكتاب ......»:","options":["جُزْءً / مَساءً","جُزْئًا / مَساءًا","جُزْءًا / مَساءً","جُزْءًا / مَساءًا"],"answer":2,"why":"جزءًا (الزاي لا تتصل)، مساءً (بعد ألف بلا ألف)."},{"type":"mcq","q":"ما علامة الترقيم المناسبة في: «أوصيك ألّا تهمل واجبك ( ) لأنّ التفوّق ثمرة الجدّ»؟","options":["الشرطتان","علامة الاستفهام (؟)","النقطتان الرأسيتان (:)","الفاصلة المنقوطة (؛)"],"answer":3,"why":"الجملة الثانية تعليل وسبب للأولى."},{"type":"tfr","q":"في جملة «ابتعدْ عَمَّ يضرّك» يجب إثبات ألف «ما» لأنها موصولة فتُكتب «عَمّا».","answer":true,"reasons":["فحذف الألف خاص بـ«ما الاستفهامية» فقط","تُحذف الألف هنا أيضًا","تُكتب عن ما"],"reason":0},{"type":"tfr","q":"تُكتب كلمة «مُرُوءَة» بهمزة على واو هكذا: «مروؤة».","answer":false,"reasons":["نعم على واو","بل مفردةً على السطر لأنها مفتوحة بعد واو مد ساكنة","تُكتب على نبرة"],"reason":1},{"type":"essay","q":"صوّب جميع الأخطاء الإملائية في الفقرة الآتية (٦ أخطاء): «إتجهَ أحمدُ إلى المستشفا مساءًا، وسئلَ الطبيبَ عَمّا يعانيه أخوه؟ فدعى له بالشفاء».","model":"الصواب: اتّجهَ أحمدُ إلى المستشفى مساءً، وسألَ الطبيبَ عَمَّ يعانيه أخوه، فدعا له بالشفاء."},{"type":"essay","q":"علّل رسم كل كلمة مما يلي: مَشِيئَة، بَرِيء، إِحسان، اهتدى.","model":"مشيئة: متوسطة مفتوحة بعد ياء ساكنة (نبرة). بريء: متطرفة بعد ياء مد ساكنة (سطر). إحسان: مصدر رباعي (قطع). اهتدى: فوق ثلاثي لم تسبق ألفه ياء (مقصورة ى)."}],"hard":[{"type":"mcq","q":"ما سبب كتابة الألف قائمةً في «رَماها» رغم أنها مقصورة في «رَمى»؟","options":["لأنها لم تعد متطرفة بعد اتصالها بالضمير «ها»","لأن أصلها واو","لأنها فوق ثلاثية","لأنها اسم أعجمي"],"answer":0,"why":"الألف المقصورة تصبح قائمةً إذا توسطت الكلمة باتصال ضمير."},{"type":"mcq","q":"أكمل الجملة: «شكرَ المديرُ ...... المخلصينَ»:","options":["أبناؤُنا","أبناءَنا","أبنائِنا","أبنأَنا"],"answer":1,"why":"مفعول به منصوب فتُفتح الهمزة بعد ألف مد وتُكتب على السطر."},{"type":"mcq","q":"أي الكلمات الآتية همزتها همزة «قطع»؟","options":["اجتهاد واثنان وابن","استمعَ وانطلاق واسم","أَستمعُ وإِدارة وإِلى","استغفار واكتبْ والمدرسة"],"answer":2,"why":"أستمع (مضارع للمتكلم)، إدارة (مصدر رباعي)، إلى (حرف)."},{"type":"mcq","q":"ما الرسم الصحيح لوصل «حين + إذ»؟","options":["حينءذٍ","حين إذ","حينأذٍ","حينئذٍ"],"answer":3,"why":"تُوصل وتُرسم الهمزة على نبرة لأنها مكسورة."},{"type":"tfr","q":"أمر الفعل الثلاثي (مثل: اقرأْ، اكتبْ) همزته وصل، بينما مضارع المتكلم منه (أقرأُ، أكتبُ) همزته قطع.","answer":true,"reasons":["كلاهما قطع","كلاهما وصل","مقارنة أساسية تمنع الخلط بين الأمر والمضارع"],"reason":2},{"type":"tfr","q":"تُكتب الألف اللينة مقصورةً في «قضايا» هكذا: «قضايى».","answer":false,"reasons":["بل قائمةً «قضايا» لأن قبلها ياءً في كلمة فوق ثلاثية","نعم قضايى","تُكتب قضاياء"],"reason":0},{"type":"tfr","q":"عند تنوين «عِبْء» بالفتح تُكتب «عِبْئًا» على نبرة لأن الباء تتصل بما بعدها.","answer":true,"reasons":["تُكتب عبءًا","بخلاف «جُزْءًا» لأن الزاي لا تتصل بما بعدها","تُكتب عبءً"],"reason":1},{"type":"essay","q":"فرّق إملائيًا بين: (أ) «ألّا» و«إلّا»، (ب) «لِمَ» و«لِما» في جمل مفيدة.","model":"(أ) أنصحك ألّا تتكاسل (أنْ+لا) | اجتهدْ وإلّا تندمْ (إنْ+لا). (ب) لِمَ تأخرتَ؟ (استفهامية) | استمعْ لِما يقوله معلمك (موصولة)."},{"type":"essay","q":"أعد كتابة الجملة بضبط همزة «علماء» في الحالات الثلاث: «...... عُمان مبدعون، ونقدّر ......، ونستفيد من ......».","model":"علماؤُنا (رفع)، علماءَنا (نصب)، علمائِنا (جر)."},{"type":"essay","q":"لخّص في ٤ نقاط ذهبية أهم قواعد الإملاء التي تراجع بها أي نص قبل تسليمه.","model":"١) اختبار «وَ» للوصل والقطع. ٢) سلم القوة للهمزة المتوسطة وحركة ما قبلها للمتطرفة. ٣) أصل الألف في الثلاثي والياء قبلها في فوق الثلاثي. ٤) ضبط (عَمَّ/عَمّا) وعلامات الترقيم."}]}},
  {"id":"g9-arabic-2-u7-4","grade":"g9","subject":"arabic","term":2,"unit":7,"no":4,"title":"التعبير: نص حواري","summary":"شرح متحرك بـ SVG لدرس التعبير: نص حواري (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-dialogue-text-intro.html","video":"","pdf":"","notes":["النص الحواري = تمهيد قصير + أدوار في أسطر مستقلة (– أو الاسم:) + جمل قصيرة فصيحة + خاتمة.","وظّف علامات الترقيم (؟ ! : –) والإرشادات القوسية (مبتسمًا) لزيادة الحيوية.","أظهر آداب الحوار البناء وتناسب اللغة مع الشخصيات."],"exercises":["اذكر العناصر الخمسة الأساسية لبناء النص الحواري المنظم.","حوّل المعلومة الآتية إلى ٣ أسطر حوارية بين طالب ومعلمه: «سأل طالب معلمه عن أفضل وقت للمذاكرة فنصحه بساعات الفجر لصفاء الذهن».","ما علامات الترقيم الأربع الأكثر استخدامًا في النصوص الحوارية؟ ووضّح وظيفة كل منها."],"levels":{"easy":[{"type":"mcq","q":"كيف يُنسَّق تبادل الأدوار بين الشخصيات في النص الحواري؟","options":["يُكتب بلا علامات ترقيم","يُدمج كلام الجميع في فقرة واحدة بلا فواصل","يبدأ كل متحدث في سطر مستقل مسبوقًا بشرطة (–) أو باسمه ونقطتين (:)","يُذكر اسم المتحدث في النهاية فقط"],"answer":2,"why":"استقلال السطر مع الشرطة أو الاسم والنقطتين يمنع التداخل."},{"type":"mcq","q":"ما المقصود بـ«الحوار الداخلي» في الأدب؟","options":["خطبة أمام الجمهور","حوار بين عشرة أشخاص","مقابلة إذاعية","حديث الشخصية مع نفسها وتفكيرها الصامت"],"answer":3,"why":"الحوار الداخلي (المونولوج) يدور داخل نفس الشخصية."},{"type":"mcq","q":"ما السمة الأنسب لطول الجمل في النص الحواري؟","options":["جمل قصيرة ورشيقة ومتنوعة تشبه الحديث الطبيعي الحيّ","جمل طويلة جدًا تمتد لصفحة كاملة لكل متحدث","كلمة واحدة فقط في كل النص","أرقام دون كلمات"],"answer":0,"why":"الجمل القصيرة تمنح الحوار سرعةً وحيويةً وواقعيةً."},{"type":"mcq","q":"ما فائدة وضع عبارات مثل (مبتسمًا) أو (متعجبًا) بين قوسين في الحوار؟","options":["إطالة النص دون معنى","نقل الانفعال وحركة الشخصية ليبدو الحوار حيًّا وواقعيًا","تغيير موضوع الحوار","إلغاء علامة التعجب"],"answer":1,"why":"الإرشادات القوسية تنقل نبرة الصوت وتعبيرات الوجه."}],"medium":[{"type":"mcq","q":"ما وظيفة «التمهيد السردي القصير» في بداية النص الحواري؟","options":["ذكر كل تفاصيل الحوار مسبقًا","كتابة النتيجة النهائية","تحديد الزمان والمكان والشخصيات وموضوع الحوار بإيجاز","شرح قواعد النحو"],"answer":2,"why":"التمهيد يضع القارئ في أجواء المشهد قبل بدء الكلام."},{"type":"mcq","q":"أي عبارة تعكس «أدب الحوار الراقي» بين صديقين مختلفين في الرأي؟","options":["أنت لا تفهم شيئًا","كلامك خطأ تمامًا ولا قيمة له","اصمت واستمع لي وحدي","وجهة نظرك جديرة بالتقدير، لكنني أرى جانبًا آخر للموضوع"],"answer":3,"why":"الاحترام المتبادل أساس الحوار البناء."},{"type":"mcq","q":"ما أكثر علامات الترقيم حضورًا في النصوص الحوارية؟","options":["النقطتان (:) والشرطة (–) وعلامتا الاستفهام (؟) والتعجب (!)","النقطة فقط","القوسان المزهران فقط","الفاصلة المنقوطة فقط"],"answer":0,"why":"الحوار مليء بالأسئلة والردود والانفعالات."},{"type":"tfr","q":"في النص الحواري يُكتب كلام جميع الشخصيات في فقرة واحدة متصلة دون فصل أسطر.","answer":false,"reasons":["نعم في فقرة واحدة","بل يبدأ دور كل متحدث في سطر جديد مسبوق بشرطة أو بالاسم ونقطتين","لا يُكتب اسم المتحدث أبدًا"],"reason":1},{"type":"tfr","q":"الجمل القصيرة الرشيقة تجعل الحوار أكثر حيويةً وواقعيةً من الخطب الطويلة.","answer":true,"reasons":["الحوار لا يحتوي أسئلة","الخطب الطويلة أجمل في الحوار","لأنها تحاكي تبادل الكلام الطبيعي بين الناس"],"reason":2},{"type":"essay","q":"اذكر العناصر الخمسة الأساسية لبناء النص الحواري المنظم.","model":"١) التمهيد السردي القصير (زمان ومكان وشخصيات). ٢) تحديد الشخصيات المتحاورة. ٣) موضوع واضح للحوار. ٤) تبادل الأدوار بأسطر مستقلة وعلامات ترقيم. ٥) خاتمة بخلاصة أو اتفاق."},{"type":"essay","q":"حوّل المعلومة الآتية إلى ٣ أسطر حوارية بين طالب ومعلمه: «سأل طالب معلمه عن أفضل وقت للمذاكرة فنصحه بساعات الفجر لصفاء الذهن».","model":"في نهاية الحصة، اقترب ناصر من معلمه وسأله:\nناصر: أستاذي، ما أفضل وقتٍ للمذاكرة وحفظ الدروس؟\nالمعلم (مبتسمًا): ساعات الفجر الأولى يا ناصر؛ فالعقل يكون صافيًا والجو هادئًا، فاستثمرها جيدًا!"}],"hard":[{"type":"mcq","q":"ما الفرق الأساسي بين «النص الحواري» و«المقال النقاشي»؟","options":["لا فرق بينهما مطلقًا","الحوار يوزّع الآراء على شخصيات متفاعلة بأسطر مستقلة، والمقال بفقرات بصوت الكاتب","الحوار لا يناقش قضايا","المقال يُكتب بالعامية"],"answer":1,"why":"القالب الشكلي وتعدد الأصوات يميزان النص الحواري."},{"type":"mcq","q":"بمَ يُستحسن أن يُختم النص الحواري الهادف؟","options":["بشجار بين الشخصيتين","بقطع الحوار فجأةً دون معنى","بخلاصة متوازنة أو اتفاق إيجابي يثمر فائدةً للقارئ","بتكرار السطر الأول"],"answer":2,"why":"الخاتمة المقنعة تمنح الحوار قيمةً تربويةً وفكريةً."},{"type":"mcq","q":"ما الشرط اللغوي المطلوب في النص الحواري المدرسي؟","options":["إهمال الإملاء","استخدام العامية المفرطة","استخدام ألفاظ غريبة معقدة لا تُفهم","استخدام لغة عربية فصيحة سهلة وملائمة لعمر الشخصيات ومقامها"],"answer":3,"why":"الفصيحة السهلة تجمع السلامة اللغوية والواقعية."},{"type":"mcq","q":"أين يُستخدم النص الحواري بكثرة في حياتنا الثقافية والإعلامية؟","options":["في القصص والمسرحيات والمقابلات الصحفية والإذاعية","في جداول الضرب فقط","في الفواتير التجارية فقط","في خرائط الطقس"],"answer":0,"why":"الحوار ركيزة المسرح والقصة والصحافة."},{"type":"tfr","q":"تناسب لغة الشخصية في الحوار مع عمرها وثقافتها دليل على براعة الكاتب.","answer":true,"reasons":["مع المحافظة على سلامة اللغة العربية الفصيحة","جميع الشخصيات تتحدث بأسلوب واحد جامد","يجب استخدام العامية"],"reason":0},{"type":"tfr","q":"التمهيد السردي القصير في بداية الحوار يحدد الزمان والمكان والشخصيات ومناسبة الحديث.","answer":true,"reasons":["يجب أن يكون أطول من الحوار نفسه","في سطرين موجزين يهيّئان القارئ للدخول في الحوار","يُوضع في النهاية"],"reason":1},{"type":"tfr","q":"الحوار الداخلي يعني حديث الإنسان مع نفسه والتفكير في قراراته.","answer":true,"reasons":["يعني المقابلة التلفزيونية","يعني الحوار داخل البيت فقط","بخلاف الحوار الخارجي الذي يدور بين شخصين فأكثر"],"reason":2},{"type":"essay","q":"ما علامات الترقيم الأربع الأكثر استخدامًا في النصوص الحوارية؟ ووضّح وظيفة كل منها.","model":"١) الشرطة (–) أو النقطتان (:): لبدء دور المتحدث. ٢) الاستفهام (؟): للأسئلة. ٣) التعجب (!): للدهشة والانفعال. ٤) القوسان ( ): لوصف حركة أو انفعال المتحدث."},{"type":"essay","q":"اذكر ثلاث آداب للحوار البناء يجب أن تظهر في النصوص الحوارية الهادفة.","model":"١) حسن الاستماع وعدم المقاطعة. ٢) احترام الرأي المخالف ومناقشته بالدليل. ٣) استخدام عبارات مهذبة والوصول إلى خلاصة مفيدة."},{"type":"essay","q":"قارن باختصار بين «الحوار الخارجي» و«الحوار الداخلي» مع مثال لكل منهما.","model":"الحوار الخارجي: بين شخصين فأكثر مثل نقاش صديقين عن الرياضة. الحوار الداخلي: حديث الشخص مع نفسه مثل طالب يراجع ضميره قبل اتخاذ قرار مهم."}]}},
  {"id":"g9-arabic-2-u7-5","grade":"g9","subject":"arabic","term":2,"unit":7,"no":5,"title":"النص الأدبي: روضة الحمى","summary":"شرح متحرك بـ SVG لدرس النص الأدبي: روضة الحمى (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-rawdat-al-hima.html","video":"","pdf":"","notes":["العنوان: الروضة (الجمال والخصب) + الحمى (الوطن والديار المحمية).","يمتزج الوصف الطبيعي الحيّ (أزهار، نسيم عليل، ندى، شدو) بعاطفة الحنين والانتماء.","جماليات القصيدة: التشخيص، التشبيه، الألفاظ الرقيقة، والموسيقى الخارجية والداخلية."],"exercises":["اشرح دلالة العنوان «روضة الحمى» مبينًا الارتباط بين اللفظتين.","اذكر أربعة عناصر طبيعية رسمت لوحة «روضة الحمى» في القصيدة.","وضّح صورتين فنيتين من أجواء القصيدة وبيّن أثرهما الجمالي."],"levels":{"easy":[{"type":"mcq","q":"ما معنى كلمتَي «الروضة» و«الحِمى» في عنوان القصيدة؟","options":["الروضة: الليل، والحمى: النهار","الروضة: الصحراء، والحمى: المرض","الروضة: البحر، والحمى: الجبل","الروضة: الأرض الخضراء المزهرة، والحمى: الديار المحمية العزيزة"],"answer":3,"why":"يجمع العنوان بين جمال الطبيعة وقدسية الوطن والديار."},{"type":"mcq","q":"ما العاطفتان المتمازجتان في قصيدة «روضة الحمى»؟","options":["الإعجاب بجمال الطبيعة والحنين الصادق إلى الديار والأحبة","الغضب والانتقام","اليأس والملل","السخرية والهجاء"],"answer":0,"why":"يمتزج الوصف الطبيعي بالوجدان والشوق للديار."},{"type":"mcq","q":"ما معنى وصف النسيم بـ«العليل» في الشعر العربي؟","options":["العاصف الشديد","اللطيف الرقيق المنعش (وليس المريض!)","الحارّ المحرق","الساكن المنقطع"],"answer":1,"why":"نسيم عليل أي لطيف ليّن الهبوب."},{"type":"mcq","q":"قول الشاعر «تبتسم الأزهار وتهمس النسائم» يُعدّ من صور:","options":["الجناس","الطباق","التشخيص (إضفاء صفات الإنسان على الطبيعة)","التعليل العلمي"],"answer":2,"why":"يجعل الطبيعة كائنًا حيًّا يشعر ويتفاعل مع الشاعر."}],"medium":[{"type":"mcq","q":"ما معنى «الأريج» أو «الشذا» في معجم وصف الطبيعة؟","options":["ارتفاع الجبل","صوت الرعد","لون السماء","الرائحة العطرة الطيبة"],"answer":3,"why":"الأريج والشذا هما العطر الفوّاح."},{"type":"mcq","q":"ما نوع الموسيقى التي تتحقق من «وحدة الوزن والقافية» في القصيدة؟","options":["الموسيقى الخارجية (الظاهرة)","الموسيقى الداخلية فقط","النثر المرسل","الخطابة"],"answer":0,"why":"الوزن والقافية يصنعان الإيقاع الخارجي للقصيدة."},{"type":"mcq","q":"بمَ يُشبّه الشعراء غالبًا قطرات الندى المتلألئة فوق أوراق الروضة صباحًا؟","options":["بالدخان الأسود","باللآلئ والدرر المنثورة","بالحجارة الثقيلة","بالرماد"],"answer":1,"why":"تشبيه يبرز صفاءها وبريقها تحت نور الصباح."},{"type":"tfr","q":"كلمة «عليل» حين توصف بها «النسائم» تعني اللطيفة المنعشة لا المريضة.","answer":true,"reasons":["تعني الهواء الملوّث","تعني الرياح العاصفة","وهو استعمال فصيح شهير في الشعر العربي"],"reason":2},{"type":"tfr","q":"خلت قصيدة «روضة الحمى» من العاطفة واقتصرت على تعداد أسماء النباتات فقط.","answer":false,"reasons":["بل فاضت بعاطفة الإعجاب والحنين للديار وامتزجت الطبيعة بالوجدان","نعم خلت من العاطفة","هي نص علمي زراعي"],"reason":0},{"type":"essay","q":"اشرح دلالة العنوان «روضة الحمى» مبينًا الارتباط بين اللفظتين.","model":"الروضة تدل على الجمال والخصب والخضرة، والحمى يدل على الوطن والديار المحمية؛ فالعنوان يجمع جمال الطبيعة بقدسية الانتماء للوطن."},{"type":"essay","q":"اذكر أربعة عناصر طبيعية رسمت لوحة «روضة الحمى» في القصيدة.","model":"١) الأزهار المتفتحة والألوان الزاهية. ٢) النسيم العليل المحمّل بالعطر. ٣) تغريد الطيور (الشدو) فوق الأغصان. ٤) قطرات الندى المتلألئة صباحًا."}],"hard":[{"type":"mcq","q":"ما دلالة الفعل «يشدو» عند الحديث عن الطيور في الروضة؟","options":["يبني العش فقط","يطير بعيدًا بصمت","يغرّد ويغني بصوت عذب جميل","يختبئ خائفًا"],"answer":2,"why":"الشدو هو الغناء والتغريد العذب."},{"type":"mcq","q":"كيف تُسهم الألفاظ الرقيقة المختارة في نجاح قصيدة «روضة الحمى»؟","options":["تُلغي الخيال","تُصعّب الفهم","تُبعد القارئ عن المعنى","تُحدث موسيقى داخلية وتنسجم مع جو البهجة والحنين"],"answer":3,"why":"تلاؤم الألفاظ مع العاطفة سرّ الجمال الشعري."},{"type":"mcq","q":"ما القيمة التربوية والبيئية التي تغرسها القصيدة في الطالب؟","options":["تذوّق جمال الطبيعة والاعتزاز بالوطن والمحافظة على المساحات الخضراء","إهمال الحدائق","الابتعاد عن القراءة","تجاهل البيئة"],"answer":0,"why":"حب الطبيعة يقود تلقائيًا للمحافظة عليها."},{"type":"mcq","q":"ما الغرض الشعري الذي تنتمي إليه قصيدة «روضة الحمى»؟","options":["الرثاء","وصف الطبيعة الممتزج بالحنين للديار","الهجاء","الفخر الحربي"],"answer":1,"why":"تجمع بين جمال الوصف وعاطفة الحنين."},{"type":"tfr","q":"تشخيص عناصر الطبيعة (مثل ابتسام الأزهار وهمس النسيم) يمنح القصيدة حياةً وحركةً.","answer":true,"reasons":["يُعد عيبًا بلاغيًا","ويجعل القارئ يتفاعل وجدانيًا مع المشهد","لا يوجد في الشعر"],"reason":1},{"type":"tfr","q":"تتحقق الموسيقى الشعرية في القصيدة عبر الوزن والقافية (خارجية) وتناغم الألفاظ والصور (داخلية).","answer":true,"reasons":["لا موسيقى في الشعر","الموسيقى في القافية فقط","وكلاهما ينسجم مع رقة موضوع الطبيعة والحنين"],"reason":2},{"type":"tfr","q":"تُعبّر كلمة «الحِمى» في التراث الشعري عن المكان المحمي العزيز المرتبط بالوطن والذكريات.","answer":true,"reasons":["لذلك ارتبطت بمشاعر الشوق والانتماء","تعني الصحراء المقفرة فقط","تعني الغربة"],"reason":0},{"type":"essay","q":"وضّح صورتين فنيتين من أجواء القصيدة وبيّن أثرهما الجمالي.","model":"١) تشخيص الأزهار بالابتسام والنسيم بالهمس: يبعث الحياة والأنس في المكان. ٢) تشبيه قطرات الندى باللآلئ: يبرز الصفاء والبريق."},{"type":"essay","q":"كيف تحققت الموسيقى الشعرية (الخارجية والداخلية) في القصيدة؟","model":"الخارجية: بوحدة الوزن الشعري والقافية العذبة المنسجمة مع الهدوء. الداخلية: بانتقاء الألفاظ الرقيقة وتناغم الحروف وترابط الصور."},{"type":"essay","q":"صف في ثلاثة أسطر «روضةً أو بستانًا عُمانيًا» مستوحيًا أسلوب قصيدة روضة الحمى.","model":"في بستانِ قريتنا تتعانقُ سعفُ النخيل مع أزهارِ الليمون، ويهبُّ النسيمُ العليلُ محمّلًا بشذا التراب النديّ، فتشدو العصافيرُ كأنها ترحّب بكل زائرٍ محبٍّ لهذا الحمى الجميل."}]}},
  {"id":"g9-arabic-2-u8-1","grade":"g9","subject":"arabic","term":2,"unit":8,"no":1,"title":"القراءة: محبة الأرض","summary":"شرح متحرك بـ SVG لدرس القراءة: محبة الأرض (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-love-of-the-land.html","video":"","pdf":"","notes":["الأرض مصدر الحياة والأمن الغذائي والهوية، وتبادل الإنسان عطاءً بعطاء.","الأفلاج والمدرجات والنخيل شواهد عريقة على محبة العُماني لأرضه.","الجمع بين محبة الأرض والتقنية الحديثة (الري الذكي) يصنع زراعةً مستدامةً."],"exercises":["اذكر ثلاث فوائد اقتصادية واجتماعية وبيئية للاهتمام بالأرض والزراعة.","كيف جسّد العُمانيون «محبة الأرض» في تراثهم الزراعي؟ اذكر مثالين.","اشرح جمال التشبيه حين يوصف ارتباط الإنسان بأرضه كعلاقة «الابن بأمه»."],"levels":{"easy":[{"type":"mcq","q":"ما الفكرة المحورية التي يدور حولها نص «محبة الأرض»؟","options":["قيمة الأرض والارتباط بها وإعمارها بالعمل الصابر باعتبارها مصدر الحياة والانتماء","هجر القرى وإهمال الزراعة","التخلي عن العمل اليدوي","الاعتماد على الاستيراد وحده"],"answer":0,"why":"الأرض مصدر الرزق والأمن الغذائي والهوية الوطنية."},{"type":"mcq","q":"بمَ يُشبّه الأدباء الأرض في سياق عطائها المستمر للإنسان؟","options":["بالصخرة الصماء التي لا فائدة منها","بالأم الحنون المعطاءة التي تغذّي أبناءها وتحتضنهم","بالسحابة العابرة","بالآلة الجامدة"],"answer":1,"why":"تشبيه يبرز الحنان والعطاء والوفاء."},{"type":"mcq","q":"ما القيمتان اللتان تجسّدهما شخصية الفلاح المخلص في النص؟","options":["اليأس والشكوى","التسرّع والكسل","الصبر والأمل والعمل الشريف المتواصل","إهمال الوقت"],"answer":2,"why":"الزراعة مدرسة في الصبر والتوكل والإتقان."},{"type":"mcq","q":"ما الأهمية الإستراتيجية للزراعة والاهتمام بالأرض في العصر الحاضر؟","options":["إهدار المياه","إنقاص فرص العمل","زيادة التصحر","تحقيق الأمن الغذائي والاستقلال الاقتصادي وحماية البيئة"],"answer":3,"why":"الأمن الغذائي ركيزة أساسية لقوة أي دولة."}],"medium":[{"type":"mcq","q":"من أبرز شواهد محبة العُمانيين لأرضهم وإبداعهم الزراعي عبر التاريخ:","options":["نظام الأفلاج والمدرجات الجبلية وزراعة النخيل","تدمير الغابات","إهمال مصادر المياه","ترك الزراعة بالكامل"],"answer":0,"why":"الأفلاج والمدرجات شاهد عالمي على الإبداع الزراعي العُماني."},{"type":"mcq","q":"كيف يمكن توظيف التقنية الحديثة لخدمة محبة الأرض اليوم؟","options":["بهدم المزارع وبناء المصانع مكانها فقط","باستخدام الري بالتنقيط والبيوت المحمية والزراعة الذكية لترشيد الماء وزيادة الإنتاج","بالري العشوائي المسرف","بعدم استخدام العلم في الزراعة"],"answer":1,"why":"الزراعة الذكية تجمع الأصالة والمعاصرة."},{"type":"mcq","q":"ما العاطفة الغالبة على نص «محبة الأرض»؟","options":["السخرية","الحزن واليأس التام","الوفاء للأرض وتقدير العمل الشريف والانتماء للوطن","اللامبالاة"],"answer":2,"why":"النص يحتفي بالعمل والعطاء والانتماء."},{"type":"tfr","q":"إعمار الأرض بالزراعة والعمل الشريف يسهم في تحقيق الأمن الغذائي للوطن.","answer":true,"reasons":["ويعزّز الاكتفاء الذاتي والاستقرار الاقتصادي","يُضعف الأمن الغذائي","لا علاقة للزراعة بالأمن الغذائي"],"reason":0},{"type":"tfr","q":"التطور التقني الحديث يتعارض تمامًا مع الاهتمام بالأرض والزراعة.","answer":false,"reasons":["نعم يتعارضان","بل التقنية الحديثة كالري بالتنقيط والزراعة الذكية تطوّر الزراعة وتزيد إنتاجها","الزراعة للماضي فقط"],"reason":1},{"type":"essay","q":"اذكر ثلاث فوائد اقتصادية واجتماعية وبيئية للاهتمام بالأرض والزراعة.","model":"١) اقتصادية: تحقيق الأمن الغذائي وتوفير فرص العمل والدخل. ٢) اجتماعية: تعزيز الانتماء والاستقرار الأسري. ٣) بيئية: تنقية الهواء ومكافحة التصحر."},{"type":"essay","q":"كيف جسّد العُمانيون «محبة الأرض» في تراثهم الزراعي؟ اذكر مثالين.","model":"١) هندسة الأفلاج وتوزيع مياهها بعدل ودقة. ٢) بناء المدرجات الزراعية في الجبل الأخضر والاهتمام بزراعة النخيل واللبان."}],"hard":[{"type":"mcq","q":"ما موقف النص من هجر الأرض الزراعية وإهمالها؟","options":["لا يتطرق إليه","يشجّع عليه","يراه دليل تقدم","يحذّر منه ويدعو للتمسّك بالأرض وإعمارها"],"answer":3,"why":"إهمال الأرض يُضعف الإنتاج ويقطع الصلة بالجذور."},{"type":"mcq","q":"كيف يعبّر طالب الصف التاسع عمليًا عن «محبة الأرض»؟","options":["بالمشاركة في التشجير وترشيد استهلاك الماء واحترام المزارعين","بقطف الأشجار وإتلاف الحدائق","بإهدار الماء","برمي النفايات في الأودية"],"answer":0,"why":"السلوك البيئي الواعي هو الترجمة العملية لمحبة الأرض."},{"type":"mcq","q":"قال النبي ﷺ: «ما من مسلم يغرس غرسًا أو يزرع زرعًا فيأكل منه طير أو إنسان أو بهيمة إلا كان له به صدقة»؛ يربط هذا الحديث الزراعة بـ:","options":["المشقة بلا فائدة","الأجر الدائم والصدقة الجارية ونفع الكائنات","الأمر الثانوي","تضييع الوقت"],"answer":1,"why":"الإسلام يشجّع على الغرس وإعمار الأرض ويجعله صدقة."},{"type":"mcq","q":"ما العلاقة بين «جهد الفلاح» و«عطاء الأرض» في النص؟","options":["لا علاقة بينهما","علاقة صراع وعداوة","علاقة تكامل ووفاء (فكلما أخلص الفلاح في خدمتها جادت عليه بالخير)","الأرض تعطي بلا أي جهد"],"answer":2,"why":"العطاء ثمرة الإخلاص والجدّ."},{"type":"tfr","q":"يمثّل نظام الأفلاج العُماني شاهدًا حضاريًا على محبة العُمانيين لأرضهم وعدالتهم في توزيع الماء.","answer":true,"reasons":["لا علاقة للأفلاج بالزراعة","الأفلاج حديثة العهد فقط","وقد أُدرج عدد من الأفلاج العُمانية في قائمة التراث العالمي"],"reason":2},{"type":"tfr","q":"العمل الزراعي يعلّم الإنسان الصبر والأمل والتوكل على الله.","answer":true,"reasons":["لأن المزارع يغرس البذرة ويرعاها بثقة وأمل حتى تثمر","يعلّم التسرّع فقط","لا يحتاج صبرًا"],"reason":0},{"type":"tfr","q":"محبة الأرض تقتصر على التغني بها بالكلمات دون عمل أو محافظة على البيئة.","answer":false,"reasons":["نعم تكفي الكلمات","بل تُثبت بالعمل والإعمار والتشجير وحماية التربة والماء","لا تحتاج عملًا"],"reason":1},{"type":"essay","q":"اشرح جمال التشبيه حين يوصف ارتباط الإنسان بأرضه كعلاقة «الابن بأمه».","model":"لأن الأم تحتضن أبناءها وتغذيهم وتمنحهم الأمان، والأرض كذلك تحتضن الإنسان وتطعمه من خيراتها وتستحق منه البرّ والوفاء والحماية."},{"type":"essay","q":"اقترح طريقتين لتوظيف التقنية الحديثة في مزارع سلطنة عُمان.","model":"١) أنظمة الري الذكي بالتنقيط لتوفير المياه. ٢) البيوت المحمية المبرّدة والزراعة المائية للإنتاج طوال العام."},{"type":"essay","q":"ما واجبك تجاه المزارع والبيئة الزراعية في مجتمعك؟","model":"تقدير جهده واحترام مهنته الشريفة، وشراء المنتجات العُمانية المحلية لدعمه، والحفاظ على الماء والأشجار ونظافة المزارع والأفلاج."}]}},
  {"id":"g9-arabic-2-u8-2","grade":"g9","subject":"arabic","term":2,"unit":8,"no":2,"title":"الأنشطة النحوية والصرفية: تطبيقات شاملة على ما سبقت دراسته","summary":"شرح متحرك بـ SVG لدرس الأنشطة النحوية والصرفية: تطبيقات شاملة على ما سبقت دراسته (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-arabic-t2-u8-grammar-review.html","video":"","pdf":"","notes":["لا النافية للجنس: مفرد (مبني) | مضاف وشبيه بالمضاف (معرب منصوب).","تأنيث الفعل: واجب (حقيقي متصل / ضمير مستتر) | جائز (حقيقي مفصول / مجازي ظاهر / جمع تكسير).","المشتقات: فاعل (فاعِل / مُـ+كسر)، مفعول (مَفعول / مُـ+فتح)، مبالغة (٥ أوزان)، مكان/زمان (مَفْعَل/مَفْعِل/مُـ+فتح)، آلة (قياسي وجامد)."],"exercises":["استخرج من الفقرة: (اسم لا وحدّد نوعه، اسم فاعل، اسم مفعول، صيغة مبالغة، اسم مكان، اسم آلة): «لا قارئَ كتابٍ خاسرٌ؛ فالمكتبةُ مَنهلُ العلمِ، والمثقّفُ الصبورُ باحثٌ بالمِنظارِ عن الحقيقةِ المَكنونةِ».","صُغ من الفعل «استخرجَ» في ثلاث جمل: اسم فاعل، واسم مفعول، واسم مكان.","بيّن حكم تأنيث الفعل في الجملتين مع التعليل: (أ) جاءتِ القوافلُ. (ب) جاءَتْ فاطمةُ."],"levels":{"easy":[{"type":"mcq","q":"في جملة: «لا ساعيًا للخيرِ نادمٌ»، ما نوع اسم لا وإعرابه؟","options":["مفرد — مبني على الفتح","شبيه بالمضاف — معرب منصوب بالفتحة","مضاف — منصوب","مبتدأ مرفوع"],"answer":1,"why":"منوّن وبعده جار ومجرور يتمم معناه فهو شبيه بالمضاف."},{"type":"mcq","q":"ما حكم تأنيث الفعل في جملة: «الحديقةُ أزهرَتْ»؟","options":["واجب التذكير","جائز التأنيث والتذكير","واجب التأنيث (الفاعل ضمير مستتر يعود لمؤنث)","ممتنع"],"answer":2,"why":"تقدّم المؤنث المجازي فصار الفاعل ضميرًا مستترًا فيجب التأنيث."},{"type":"mcq","q":"ما اسم المفعول الصحيح من الفعلين «بِيعَ» و«رُجِيَ» على الترتيب؟","options":["مُباع ومُرجى","بائِع وراجٍ","مَبيوع ومَرجيّ","مَبيع ومَرجوّ"],"answer":3,"why":"الأجوف اليائي ← مَبيع، والناقص الواوي ← مَرجوّ."},{"type":"mcq","q":"أي الكلمات الآتية «اسم فاعل» من فعل غير ثلاثي؟","options":["مُتقِن ومُستقبِل","مُتقَن ومُستقبَل","كاتِب وقارِئ","مِقدام وصَبور"],"answer":0,"why":"ميم مضمومة وكسر ما قبل الآخر."}],"medium":[{"type":"mcq","q":"في جملة: «استمعتُ للأخبار عبر المِذياع»، كلمة «المِذياع» تُعدّ:","options":["صيغة مبالغة","اسم آلة قياسيًا على وزن مِفْعال","اسم مكان","اسم مفعول"],"answer":1,"why":"دلت في السياق على جهاز الراديو (أداة الاستماع)."},{"type":"mcq","q":"ما نوع المشتق «مَوعِد» ووزنه في: «المغربُ مَوعِدُ الإفطارِ»؟","options":["اسم آلة","اسم مكان على وزن مَفْعَل","اسم زمان على وزن مَفْعِل","صيغة مبالغة"],"answer":2,"why":"دلت على الزمن وصيغت من المثال الواوي «وَعَدَ» على مَفْعِل."},{"type":"mcq","q":"أي الجمل الآتية فيها اسم لا «مفردًا مبنيًا»؟","options":["نجحَ بلا شكٍّ","لا طالبَ علمٍ مهملٌ","لا قارئًا كتابًا نادمٌ","لا منافقَ محبوبٌ"],"answer":3,"why":"كلمة واحدة نكرة غير مضافة ولا شبيهة بالمضاف."},{"type":"tfr","q":"الفرق بين «مُنتِج» و«مُنتَج» أن الأولى اسم فاعل والثانية اسم مفعول.","answer":true,"reasons":["كلاهما اسم فاعل","بكسر ما قبل الآخر لاسم الفاعل وفتحه لاسم المفعول","الأولى اسم آلة"],"reason":1},{"type":"tfr","q":"في جملة «أشرقَتِ الشمسُ» تأنيث الفعل واجب.","answer":false,"reasons":["بل واجب التذكير","نعم واجب","بل جائز لأن الفاعل ظاهر مؤنث مجازي (أشرقَ/أشرقتِ الشمسُ)"],"reason":2},{"type":"essay","q":"استخرج من الفقرة: (اسم لا وحدّد نوعه، اسم فاعل، اسم مفعول، صيغة مبالغة، اسم مكان، اسم آلة): «لا قارئَ كتابٍ خاسرٌ؛ فالمكتبةُ مَنهلُ العلمِ، والمثقّفُ الصبورُ باحثٌ بالمِنظارِ عن الحقيقةِ المَكنونةِ».","model":"اسم لا: قارئَ (مضاف منصوب). اسم مكان: المكتبة، مَنهل. اسم مفعول: المثقّف (غير ثلاثي)، المكنونة (ثلاثي). صيغة مبالغة: الصبور (فعول). اسم فاعل: باحث (ثلاثي). اسم آلة: المنظار (مفعال)."},{"type":"essay","q":"صُغ من الفعل «استخرجَ» في ثلاث جمل: اسم فاعل، واسم مفعول، واسم مكان.","model":"اسم فاعل: المهندسُ مُستخرِجٌ النفطَ. اسم مفعول: النفطُ مُستخرَجٌ من الأرض. اسم مكان: الحقلُ مُستخرَجُ النفطِ."}],"hard":[{"type":"mcq","q":"ما صيغة المبالغة ووزنها في: «المؤمنُ يَقِظٌ حَذِرٌ»؟","options":["يَقِظ وحَذِر — على وزن فَعِل","المؤمن — مُفعِل","لا توجد صيغة مبالغة","على وزن فاعِل"],"answer":0,"why":"يَقِظ وحَذِر بفتح الفاء وكسر العين على وزن فَعِل."},{"type":"mcq","q":"في جملة: «المدرسةُ مُلتقى الطلابِ صباحًا»، كلمة «مُلتقى» تُعدّ:","options":["اسم مفعول","اسم مكان (بسبب المبتدأ المدرسة)","اسم آلة","صيغة مبالغة"],"answer":1,"why":"أخبرت عن مكان التقاء الطلاب."},{"type":"mcq","q":"أي الكلمات الآتية «اسم آلة جامد»؟","options":["مِفتاح ومِسطرة","حاسوب وطابعة","فأس وقَلَم","غَسّالة ومِكنسة"],"answer":2,"why":"فأس وقلم ليسا مشتقين من فعل ولا وزن قياسي."},{"type":"mcq","q":"ما الفعل المبني للمجهول لاسم المفعول «مُستعمَل»؟","options":["أُعمِلَ","عُمِلَ","عومِلَ","اسْتُعمِلَ"],"answer":3,"why":"بميم مضمومة وفتح ما قبل الآخر فهو من السداسي اسْتُعمِلَ."},{"type":"tfr","q":"اسم لا النافية للجنس في «لا مجتهدِينَ فاشلون» مبني على الياء في محل نصب.","answer":true,"reasons":["لأنه مفرد (غير مضاف ولا شبيه بالمضاف) فيُبنى على ما يُنصب به","مرفوع بالواو","منصوب بالفتحة"],"reason":0},{"type":"tfr","q":"وزن «مَفْعِل» (بكسر العين) يأتي من الثلاثي المثال الواوي مثل وَقَفَ←مَوقِف، ومن مكسور العين في المضارع مثل نَزَلَ←مَنزِل.","answer":true,"reasons":["يأتي من الناقص فقط","بينما يأتي مَفْعَل (بالفتح) من المفتوح والمضموم والناقص","يأتي من غير الثلاثي"],"reason":1},{"type":"tfr","q":"تُعرب جميع المشتقات (اسم الفاعل، اسم المفعول، صيغ المبالغة، المكان والزمان والآلة) حسب موقعها في الجملة.","answer":true,"reasons":["تكون مبنية دائمًا","تُعرب دائمًا فاعلًا","قد تكون مبتدأً أو خبرًا أو فاعلًا أو نعتًا أو مجرورًا"],"reason":2},{"type":"essay","q":"بيّن حكم تأنيث الفعل في الجملتين مع التعليل: (أ) جاءتِ القوافلُ. (ب) جاءَتْ فاطمةُ.","model":"(أ) جائز الوجهين لأن الفاعل جمع تكسير. (ب) واجب التأنيث لأن الفاعل مؤنث حقيقي متصل بالفعل."},{"type":"essay","q":"أعرب ما تحته خط: «لا مؤمنَ كاذبٌ» و«سافرتُ بلا زادٍ» (مؤمنَ، زادٍ).","model":"مؤمنَ: اسم لا النافية للجنس مبني على الفتح في محل نصب. زادٍ: اسم مجرور بالباء وعلامة جره الكسرة (لأن لا مهملة لسبقها بحرف جر)."},{"type":"essay","q":"اذكر أربع كلمات على وزن «مِفْعال» اثنتين منها صيغتا مبالغة واثنتين اسما آلة في جمل قصيرة.","model":"مبالغة: خالدٌ مِعطاءٌ للخير، الفارسُ مِقدامٌ. آلة: فتحتُ البابَ بالمِفتاحِ، قستُ الحرارةَ بالمِقياسِ."}]}},
  {"id":"g9-arabic-2-u8-3","grade":"g9","subject":"arabic","term":2,"unit":8,"no":3,"title":"الأنشطة الإملائية: إملاء اختباري","summary":"شرح متحرك بـ SVG لدرس الأنشطة الإملائية: إملاء اختباري (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-dictation-assessment.html","video":"","pdf":"","notes":["استمع للقراءة الأولى كاملًا، ثم اكتب بتطبيق القواعد، ثم راجع في القراءة الأخيرة.","فرّق بالتنوين بين (ة) و(ه)، وبالوقف الساكن بين التنوين والنون الأصلية.","تذكّر: هذا، لكنّ، ذلك، أولئك (بلا ألف مكتوبة) | بالعلم (تبقى الألف) | للعلم (تُحذف الألف)."],"exercises":["صوّب جميع الأخطاء في الفقرة الإملائية الآتية (٨ أخطاء): «هاذا الطالبُ إجتهدَ كثيرن، وكتبَ شئ جميلًا عن حياه الفلاحين، ودعى لهم بلخير مساءًا».","اشرح كيف تفرّق إملائيًا بين: (أ) «مياه» و«حياة»، (ب) «شكرًا» و«مؤمنًا».","أدخل «الباء» مرة و«اللام الجارة» مرة على الكلمات: (اللغة، الصدق، العلم)."],"levels":{"easy":[{"type":"mcq","q":"أي الكلمات الآتية كُتبت بهاء مربوطة صحيحة (بلا نقطتين)؟","options":["حياة ومكتبه","مدرسه وحديقه","مياه ووجْه وفواكه","طالبه ومعلمه"],"answer":2,"why":"عند تنوينها تبقى هاءً: مياهٌ، وجْهٌ، فواكهٌ."},{"type":"mcq","q":"ما الرسم الصحيح لإدخال حرف الجر «الباء» على كلمة «القلم»؟","options":["بل القلم","بلقلمِ","ب القلم","بالقلمِ (تبقى الألف)"],"answer":3,"why":"مع الباء والفاء والكاف والواو لا تُحذف ألف «ال»."},{"type":"mcq","q":"ما الرسم الصحيح لإدخال «اللام الجارة» على كلمة «الليل»؟","options":["لِلَّيلِ (تُحذف همزة الوصل فتلتقي لامان)","للاليل","لليلل","لِالليل"],"answer":0,"why":"عند دخول اللام على ما يبدأ بـ«ال» تُحذف همزة الوصل (وإن بدأ بلام حُذفت اللام الثانية منعًا لثلاث لامات)."},{"type":"mcq","q":"أي جملة من الآتي خالية تمامًا من الأخطاء الإملائية؟","options":["شكرن لك يا صديقي على هدايىكَ الجميلة، فقد أسعدتني كثيرن.","شكرًا لك يا صديقي على هداياكَ الجميلة؛ فقد أسعدتني كثيرًا.","شكرًا لك يا صديقي على هداياكَ الجميله؛ فقد أسعدتني كثيرن.","شكرن لك يا صديقي على هداياكَ الجميلة؛ فقد أسعدتني كثيرًا."],"answer":1,"why":"شكرًا وكثيرًا بالتنوين، هداياك بألف قائمة، الجميلة بتاء مربوطة."}],"medium":[{"type":"mcq","q":"كيف نفرّق بسرعة بين «التنوين» و«النون الأصلية» في نهاية الكلمة؟","options":["نحذف الحرف الأول","نكتبها نونًا دائمًا","نقف على الكلمة ساكنةً: إن اختفت النون فتنوين، وإن بقيت فنون أصلية","لا فرق بينهما"],"answer":2,"why":"اختبار الوقف الساكن يكشف التنوين فورًا (كتابًا ← كتاب)."},{"type":"mcq","q":"ما الرسم الصحيح لكلمة «فجأة» وكلمة «مكتبة» عند تنوينهما بالفتح؟","options":["فجأتا ومكتبتا","فجأةًا ومكتبةًا","فجئتن ومكتبتن","فجأةً ومكتبةً (بلا ألف بعد التاء المربوطة)"],"answer":3,"why":"لا تُزاد ألف تنوين النصب بعد التاء المربوطة أبدًا."},{"type":"mcq","q":"أي جملة ضُبطت فيها همزتا الوصل والقطع بدقة؟","options":["استمعْ إلى نصيحةِ معلمك، وأحسنْ إدارةَ وقتك.","إستمعْ الى نصيحةِ معلمك، واحسنْ ادارةَ وقتك.","استمعْ إلى نصيحةِ معلمك، واحسنْ إدارةَ وقتك.","إستمعْ إلى نصيحةِ معلمك، وأحسنْ إدارهَ وقتك."],"answer":0,"why":"استمع (أمر خماسي: وصل)، إلى (حرف: قطع)، أحسن وإدارة (رباعي: قطع)."},{"type":"tfr","q":"تُضاف ألف تنوين النصب بعد التاء المربوطة مثل: «مدرسةًا».","answer":false,"reasons":["تُكتب مدرستن","نعم تُضاف دائمًا","لا تُضاف ألف بعد التاء المربوطة؛ الصواب «مدرسةً»"],"reason":2},{"type":"tfr","q":"الهاء المربوطة (مثل مياه ووجْه) لا توضع فوقها نقطتان وتُنطق هاءً في الوقف والوصل.","answer":true,"reasons":["بخلاف التاء المربوطة (مدرسة) التي تُنطق تاءً عند الوصل والتنوين","توضع فوقها نقطتان","تُنطق تاءً عند التنوين"],"reason":0},{"type":"essay","q":"صوّب جميع الأخطاء في الفقرة الإملائية الآتية (٨ أخطاء): «هاذا الطالبُ إجتهدَ كثيرن، وكتبَ شئ جميلًا عن حياه الفلاحين، ودعى لهم بلخير مساءًا».","model":"الصواب: هذا الطالبُ اجتهدَ كثيرًا، وكتبَ شيئًا جميلًا عن حياةِ الفلاحين، ودعا لهم بالخيرِ مساءً."},{"type":"essay","q":"اشرح كيف تفرّق إملائيًا بين: (أ) «مياه» و«حياة»، (ب) «شكرًا» و«مؤمنًا».","model":"(أ) «مياهٌ» تبقى هاءً عند التنوين فتُكتب بلا نقطتين (ه)، و«حياةٌ» تُنطق تاءً عند التنوين فتُكتب بنقطتين (ة). (ب) «شكرًا» عند الوقف «شكر» فالنون تنوين، أما «مؤمنًا» عند الوقف «مؤمن» فالنون أصلية ثم جاء تنوين الفتح."}],"hard":[{"type":"mcq","q":"في جملة الإملاء: «ما أجملَ شاطئَ صورٍ مساءً ( )»، ما علامة الترقيم المناسبة؟","options":["علامة الاستفهام (؟)","علامة التعجب (!)","الفاصلة المنقوطة (؛)","النقطتان الرأسيتان (:)"],"answer":1,"why":"أسلوب تعجب يُختم بعلامة التعجب (!)."},{"type":"mcq","q":"ما التصويب الصحيح لكلمة «هؤلا» في جملة «هؤلا طلاب مجتهدون»؟","options":["هؤلائ","هاؤلاء","هؤلاءِ (تُنطق الألف ولا تُكتب، وتُكتب الهمزة على السطر)","هؤلاءا"],"answer":2,"why":"«هؤلاء» من الكلمات التي فيها ألف تُنطق ولا تُكتب."},{"type":"mcq","q":"أي الكلمات الآتية فيها حرف «يُنطق ولا يُكتب»؟","options":["الشمس، القمر","الكتاب، المدرسة","عمرو، أولو","هذا، هذه، لكنّ، أولئك، الله"],"answer":3,"why":"في هذه الكلمات ألف مد تُنطق ولا تُكتب."},{"type":"mcq","q":"ما الخطوة الأولى الموصى بها عند بدء المعلم قراءة نص الإملاء الاختباري؟","options":["الإنصات التام للقراءة الأولى لفهم المعنى والسياق وعلامات الترقيم قبل الكتابة","الكتابة السريعة قبل أن ينتهي المعلم من القراءة الأولى","تجاهل علامات الترقيم","ترك الفراغات دون مراجعة"],"answer":0,"why":"فهم السياق في القراءة الأولى يمنع أخطاء الترقيم والهمزات."},{"type":"tfr","q":"عند دخول حرف الجر «الباء» على كلمة تبدأ بـ«ال» مثل «العلم» تُكتب «بالعلم» دون حذف الألف.","answer":true,"reasons":["تُحذف الألف فتُكتب بلعلم","بينما تُحذف الألف مع اللام الجارة فقط: لِلعلم","تُحذف اللام"],"reason":1},{"type":"tfr","q":"كلمات مثل «هذا، لكنّ، ذلك، أولئك» تحتوي ألفًا تُنطق ولا تُكتب.","answer":true,"reasons":["لا تحتوي أي مد","تُكتب فيها الألف: هاذا، لاكن","وهي من أشهر كلمات الإملاء الاختباري"],"reason":2},{"type":"tfr","q":"لا فائدة من القراءة الأخيرة لمراجعة نص الإملاء بعد الانتهاء من الكتابة.","answer":false,"reasons":["القراءة الأخيرة تكشف نسيان النقاط والهمزات وعلامات الترقيم وتنقذ الدرجة","نعم لا فائدة منها","تضيع الوقت فقط"],"reason":0},{"type":"essay","q":"أدخل «الباء» مرة و«اللام الجارة» مرة على الكلمات: (اللغة، الصدق، العلم).","model":"بالباء: باللغة، بالصدق، بالعلم. باللام: للّغة، للصدق، للعلم."},{"type":"essay","q":"اكتب أربع كلمات فيها ألف «تُنطق ولا تُكتب»، وكلمتين فيهما حرف «يُكتب ولا يُنطق».","model":"تُنطق ولا تُكتب: هذا، ذلك، لكنّ، الرحمن (أو أولئك). يُكتب ولا يُنطق: واو «عمرو» وواو «أولئك» (أو الألف الفارقة في كتبوا)."},{"type":"essay","q":"صمّم قائمة مراجعة سريعة من ٥ نقاط يفحص بها الطالب ورقة الإملاء الاختباري قبل تسليمها.","model":"١) الهمزات (وصل/قطع، متوسطة، متطرفة). ٢) الألف اللينة في آخر الكلمات. ٣) التاء المربوطة والهاء والتنوين. ٤) الكلمات ذات الحروف المنطوقة غير المكتوبة (هذا، لكن). ٥) علامات الترقيم والخط الواضح."}]}},
  {"id":"g9-arabic-2-u8-4","grade":"g9","subject":"arabic","term":2,"unit":8,"no":4,"title":"التعبير: كتابة نص حواري","summary":"شرح متحرك بـ SVG لدرس التعبير: كتابة نص حواري (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-writing-dialogue-text.html","video":"","pdf":"","notes":["ابدأ بتمهيد موجز (سطران) يحدد الزمان والمكان والشخصيات وشرارة الحوار.","وزّع الأدوار بتوازن في أسطر مستقلة، بجمل قصيرة فصيحة وإرشادات قوسية وترقيم دقيق.","اختم باقتناع أو اتفاق عملي، وراجع النص إملائيًا قبل التسليم."],"exercises":["اكتب نصًا حواريًا كاملًا (تمهيد + ٦ أدوار متبادلة + خاتمة) بين طالبَين في مدرستك حول «أهمية القراءة اليومية».","صوّب الترقيم والتنسيق في الحوار الآتي: «سأل سالم أخاه هل أعددت جدول المذاكرة فقال له لم أبدأ بعد لأنني مشغول باللعب».","اذكر أربعة أخطاء شائعة في كتابة النص الحواري وكيفية تجنّبها."],"levels":{"easy":[{"type":"mcq","q":"ما الذي يصنع التشويق والحيوية في النص الحواري عند كتابته؟","options":["غياب الموضوع المحدد","تكرار نفس الجملة من الطرفين","إلقاء خطبة طويلة من شخص واحد وصمت الآخر","وجود تباين لطيف في الآراء أو تساؤلات حقيقية تتطور نحو الإقناع"],"answer":3,"why":"تفاعل الأسئلة والردود وتطور القناعة يشدّ القارئ."},{"type":"mcq","q":"كيف نتجنّب أن يتحوّل النص الحواري إلى «قصة سردية»؟","options":["بأن يكون التمهيد موجزًا جدًا ويأخذ تبادل الكلام النصيب الأكبر","بحذف جميع الشخصيات","بإلغاء علامات الترقيم","بكتابة ١٠ صفحات تمهيدًا"],"answer":0,"why":"التمهيد مجرد مدخل قصير (سطر أو سطرين) للحوار."},{"type":"mcq","q":"أي ردّ مما يلي يعكس توازن الأدوار والإقناع الهادئ في نص حواري؟","options":["حمد: اسكت ولا تتكلم عن الماء أبدًا!","حمد: قطرة فوق قطرة تصنع مئات اللترات، ويمكننا توفيرها بالري بالتنقيط وإغلاق الصنبور.","حمد: لا أعرف.","حمد: نعم نعم نعم."],"answer":1,"why":"رد موجز ومقنع ومهذب ويقدّم حلًا عمليًا."},{"type":"mcq","q":"ما فائدة جملة «(مبتسمًا باقتناع)» في خاتمة النص الحواري؟","options":["لا معنى لها","تدل على الغضب","توضّح تغيّر حالة الشخصية النفسية واقتناعها بأسلوب طبيعي حيّ","تفسد الحوار"],"answer":2,"why":"تبيّن الإرشادات القوسية الأثر النفسي للحوار."}],"medium":[{"type":"mcq","q":"أي جملة حوارية ضُبطت فيها علامات الترقيم بدقة؟","options":["ماجد؛ وهل يكفي إغلاق الصنبور لتوفير كل هذا الماء!","ماجد متعجبًا وهل يكفي إغلاق الصنبور لتوفير كل هذا الماء.","ماجد! وهل يكفي إغلاق الصنبور لتوفير كل هذا الماء:","ماجد (متعجبًا): وهل يكفي إغلاق الصنبور لتوفير كل هذا الماء؟"],"answer":3,"why":"الاسم + قوس الانفعال + النقطتان + السؤال + علامة الاستفهام."},{"type":"mcq","q":"ما الخطأ الشائع الذي يضعف النص الحواري المدرسي؟","options":["استئثار شخصية واحدة بالكلام الطويل بينما تكتفي الأخرى بـ«نعم» و«لا»","استخدام جمل قصيرة","تحديد المكان في التمهيد","وضع خاتمة مقنعة"],"answer":0,"why":"الحوار الناجح متوازن ومثمر بين الطرفين."},{"type":"mcq","q":"عند كتابة حوار حول «الاستعداد للاختبارات»، ما أفضل خاتمة؟","options":["ترك الحوار في منتصف السؤال","اتفاق الصديقين على وضع جدول مذاكرة منظم والالتزام به","الاتفاق على إهمال الدراسة","الخلاف والانصراف بغضب"],"answer":1,"why":"الخاتمة الإيجابية العملية تحقق هدف الحوار التربوي."},{"type":"tfr","q":"يجب أن يكون كلام الشخصيتين متوازنًا ومتفاعلًا لا مجرد خطبة من طرف واحد.","answer":true,"reasons":["حتى يحقق النص طبيعة الحوار الحي وتبادل الأفكار","الأفضل أن تتكلم شخصية واحدة فقط","التوازن غير مطلوب"],"reason":0},{"type":"tfr","q":"يُفضّل أن ينتهي النص الحواري التربوي بخلاصة أو اتفاق عملي نافع.","answer":true,"reasons":["الأفضل قطعه فجأة بلا نهاية","مما يترك أثرًا إيجابيًا واضحًا لدى القارئ","يجب أن ينتهي بشجار"],"reason":1},{"type":"essay","q":"اكتب نصًا حواريًا كاملًا (تمهيد + ٦ أدوار متبادلة + خاتمة) بين طالبَين في مدرستك حول «أهمية القراءة اليومية».","model":"في استراحة المدرسة، وجد راشدٌ زميله سعيدًا يقرأ كتابًا شيّقًا فدار بينهما هذا الحوار:\nراشد: ما هذا الكتاب الذي يشغلك يا سعيد؟\nسعيد (مبتسمًا): إنه كتاب عن الملاح العُماني أحمد بن ماجد؛ أنصحك بقراءته!\nراشد (متعجبًا): ألا تملّ من القراءة في وقت الفراغ؟\nسعيد: أبدًا! خصّصتُ ١٥ دقيقةً فقط يوميًا، فصارت متعةً وساعدتني حتى في دروس التعبير.\nراشد: فكرة جميلة! هل أستعيره منك بعد أن تنتهي؟\nسعيد: بكل سرور يا صديقي، وسنتبادل الكتب كل أسبوع!"},{"type":"essay","q":"صوّب الترقيم والتنسيق في الحوار الآتي: «سأل سالم أخاه هل أعددت جدول المذاكرة فقال له لم أبدأ بعد لأنني مشغول باللعب».","model":"سالم: هل أعددتَ جدول المذاكرة؟\nأخوه: لم أبدأ بعدُ؛ لأنني كنتُ مشغولًا باللعب."}],"hard":[{"type":"mcq","q":"أي مما يأتي يجب التحقق منه في «قائمة الفحص النهائية» للنص الحواري؟","options":["حذف التمهيد دائمًا","كتابة الحوار بالعامية فقط","استقلال كل دور في سطر، وسلامة الإملاء والترقيم، ووضوح الخاتمة","إزالة علامات الاستفهام"],"answer":2,"why":"التنسيق واللغة والبناء هي معايير التقييم الأساسية."},{"type":"mcq","q":"أين نضع النقطتين الرأسيتين (:) في النص الحواري؟","options":["في منتصف الكلمة","في نهاية السؤال","قبل كلمة «لأن»","مباشرةً بعد اسم المتحدث (أو بعد قوس الانفعال التابع لاسمه)"],"answer":3,"why":"تُمهّد النقطتان لكلام المتحدث المباشر."},{"type":"mcq","q":"توظيف جملة «لا حياةَ بلا ماءٍ» داخل حوار عن ترشيد المياه يُعدّ:","options":["توظيفًا لغويًا موفقًا يجمع النحو (لا النافية للجنس) وقوة الفكرة","خطأً نحويًا","حشوًا زائدًا","خروجًا عن الموضوع"],"answer":0,"why":"الربط بين النحو والتعبير يرفع القيمة الفنية للنص."},{"type":"mcq","q":"ما الطول المناسب للتمهيد السردي في بداية النص الحواري؟","options":["صفحة كاملة","سطر إلى سطرين يحددان الزمان والمكان والشخصيات وسبب الحديث","خمس فقرات","لا يُذكر الزمان أو المكان أبدًا"],"answer":1,"why":"الإيجاز في التمهيد يدخل القارئ سريعًا إلى الحوار."},{"type":"tfr","q":"استخدام العامية في كتابة النص الحواري المدرسي أدقّ من العربية الفصيحة السهلة.","answer":false,"reasons":["الفصحى ممنوعة في الحوار","نعم العامية أفضل","المطلوب في التعبير المدرسي الفصيحة السهلة السليمة"],"reason":2},{"type":"tfr","q":"الإرشادات القوسية القصيرة مثل (مبتسمًا) و(مفكرًا) تضفي حركةً وواقعيةً على الحوار.","answer":true,"reasons":["لأنها تنقل لغة الجسد ونبرة الصوت للقارئ","تُفسد شكل الحوار","تُستخدم في التقارير فقط"],"reason":0},{"type":"tfr","q":"يمكن الاستغناء عن علامات الاستفهام والتعجب في النص الحواري.","answer":false,"reasons":["نعم لا حاجة لها","بل هي ضرورية جدًا لإبراز نبرة السؤال والدهشة والانفعال في الحوار","نستخدم النقطة فقط"],"reason":1},{"type":"essay","q":"اذكر أربعة أخطاء شائعة في كتابة النص الحواري وكيفية تجنّبها.","model":"١) إطالة التمهيد (تجنبه بالاكتفاء بسطرين). ٢) دمج الأدوار في فقرة واحدة (اجعل كل دور في سطر). ٣) إطالة كلام شخصية واحدة (اجعل الردود قصيرة متوازنة). ٤) إهمال الترقيم والخاتمة (اضبط ؟ ! : واختم باتفاق واضح)."},{"type":"essay","q":"أضف إرشادات قوسية مناسبة وعلامات ترقيم لكل جملة: (أ) المعلم ما أروع هذا المشروع العلمي. (ب) الطالب هل حقًا نال إعجابك يا أستاذي.","model":"(أ) المعلم (بإعجاب): ما أروعَ هذا المشروعَ العلميّ! (ب) الطالب (مسرورًا): هل حقًا نال إعجابك يا أستاذي؟"},{"type":"essay","q":"لماذا يُعدّ إتقان كتابة الحوار مهارةً نافعةً للطالب في حياته العملية؟","model":"لأنه يدربه على تنظيم الأفكار، وحسن الاستماع، وعرض الحجج بأدب وإيجاز، وهي مهارات أساسية في المقابلات والعمل الجماعي والإعلام."}]}},
  {"id":"g9-arabic-2-u8-5","grade":"g9","subject":"arabic","term":2,"unit":8,"no":5,"title":"الاستماع: القِرى عند العرب","summary":"شرح متحرك بـ SVG لدرس الاستماع: القِرى عند العرب (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-arab-hospitality-qira.html","video":"","pdf":"","notes":["القِرى (بكسر القاف) = إكرام الضيف | نار القِرى كانت تُوقد ليلًا لهداية المسافرين.","الإسلام جعل إكرام الضيف من علامات الإيمان، مع النهي عن الإسراف والتبذير.","تتجلى القيمة في السبلة العُمانية والقهوة والتمر والترحيب البشوش، مع التزام آداب الضيف والمضيف."],"exercises":["عرّف «القِرى»، وبيّن كيف مارسه العرب قديمًا وكيف ارتقى به الإسلام.","قارن بين «الكرم المحمود» و«الإسراف المذموم» عند استضافة الضيوف.","اذكر ثلاثة مظاهر لإكرام الضيف في المجتمع العُماني المعاصر."],"levels":{"easy":[{"type":"mcq","q":"ما معنى كلمة «القِرى» في اللغة العربية؟","options":["إكرام الضيف وما يُقدَّم له من طعام وحسن ضيافة","جمع قرية (قُرى)","القراءة السريعة","السفر البعيد"],"answer":0,"why":"القِرى (بكسر القاف) هو إكرام الضيف؛ أما القُرى (بضمها) فجمع قرية!"},{"type":"mcq","q":"لماذا كان العرب قديمًا يشعلون «نار القِرى» فوق المرتفعات ليلًا؟","options":["لإخافة الضيوف","لهداية المسافرين وعابري السبيل إلى منازلهم لإكرامهم وإطعامهم","للاحتفال فقط","لقياس درجة الحرارة"],"answer":1,"why":"كانت نار القِرى علامةً للكرم وإرشادًا للمسافر في الصحراء."},{"type":"mcq","q":"من الصحابي أو الشخصية العربية التي يُضرب بها المثل في الجود وإكرام الضيف؟","options":["أبو لهب","قارون","حاتم الطائي","أشعب"],"answer":2,"why":"يُقال في المثل العربي الشهير: «أكرم من حاتم الطائي»."},{"type":"mcq","q":"كيف ارتقى الإسلام بقيمة إكرام الضيف؟","options":["جعلها عادةً بلا أجر","ألغاها تمامًا","قصرها على الأغنياء فقط","ربطها بالإيمان بالله واليوم الآخر وجعلها عبادةً وأجرًا"],"answer":3,"why":"قال ﷺ: «من كان يؤمن بالله واليوم الآخر فليكرم ضيفه»."}],"medium":[{"type":"mcq","q":"ما أول وأجمل مظهر من مظاهر إكرام الضيف حتى قبل تقديم الطعام؟","options":["طلاقة الوجه والابتسامة وحسن الترحيب وطيب الحديث","التفاخر بثمن الأثاث","الصمت والعبوس","الإسراف وإلقاء الطعام"],"answer":0,"why":"البشاشة وحسن الاستقبال هما روح الضيافة الحقيقية."},{"type":"mcq","q":"من أبرز مظاهر استمرار قيمة «القِرى» في المجتمع العُماني اليوم:","options":["إغلاق الأبواب في وجه الضيوف","السبلة العُمانية وتقديم القهوة والتمر والحلوى بحفاوة للضيوف","إهدار الطعام","التكلف والرياء"],"answer":1,"why":"السبلة والقهوة العُمانية رمز عالمي لحفاوة وكرم أهل عُمان."},{"type":"mcq","q":"ما الفرق الجوهري بين «الكرم المحمود» و«الإسراف المذموم»؟","options":["الإسراف أفضل من الكرم","لا فرق بينهما","الكرم بذل بسخاء ومحبة بقدر الحاجة بلا رياء، والإسراف مبالغة وتبذير وإهدار للنعمة","الكرم يعني البخل"],"answer":2,"why":"الإسلام يأمر بالكرم وينهى عن الإسراف والتبذير."},{"type":"tfr","q":"كلمة «القِرى» (بكسر القاف) تعني إكرام الضيف، بينما «القُرى» (بضم القاف) جمع قرية.","answer":true,"reasons":["كلاهما بمعنى واحد","مع أن رسمهما متشابه بالألف المقصورة إلا أن التشكيل يفرق المعنى تمامًا","القِرى جمع قرية"],"reason":1},{"type":"tfr","q":"يُقاس إكرام الضيف الحقيقي بكثرة التبذير ورمي فائض الطعام بعد الوليمة.","answer":false,"reasons":["الكرم لا يتحقق إلا بالإسراف","نعم بالتبذير","الإسراف مذموم شرعًا؛ والكرم الحقيقي في طلاقة الوجه وحسن الترحيب والبذل المعتدل"],"reason":2},{"type":"essay","q":"عرّف «القِرى»، وبيّن كيف مارسه العرب قديمًا وكيف ارتقى به الإسلام.","model":"القِرى هو إكرام الضيف وتقديم الطعام والترحيب له. مارسه العرب بإيقاد «نار القِرى» ليلًا لهداية المسافرين وافتخروا به كحاتم الطائي، وارتقى به الإسلام فجعله من علامات الإيمان وعبادةً يُؤجر عليها المسلم."},{"type":"essay","q":"قارن بين «الكرم المحمود» و«الإسراف المذموم» عند استضافة الضيوف.","model":"الكرم المحمود: بشاشة وترحيب وبذل من الموجود بمحبة وبقدر الحاجة دون رياء. الإسراف المذموم: تكلف ومباهاة وإهدار للطعام مما ينهى عنه الإسلام."}],"hard":[{"type":"mcq","q":"ما المقصود بالفرق الإملائي والمعنوي بين «القِرى» و«القُرى»؟","options":["لا فرق في التشكيل","كلاهما جمع قرية","كلاهما إكرام الضيف","القِرى (بكسر القاف): إكرام الضيف | القُرى (بضم القاف): جمع قرية"],"answer":3,"why":"حركة واحدة (كسرة × ضمة) تغيّر المعنى بالكامل!"},{"type":"mcq","q":"أي مما يأتي يُعدّ من «آداب الضيف» تجاه مضيفه؟","options":["الاستئذان واختيار الوقت المناسب وعدم الإطالة المرهقة والدعاء للمضيف","القدوم في أوقات متأخرة دون إذن","انتقاد الطعام المقدم","إحراج المضيف بكثرة الطلبات"],"answer":0,"why":"مراعاة حال المضيف والدعاء له من أرقى آداب الضيافة."},{"type":"mcq","q":"مَن النبي الذي أثنى القرآن على مبادرته بإكرام ضيوفه؟","options":["فرعون","سيدنا إبراهيم عليه السلام","قارون","النمرود"],"answer":1,"why":"أسرع إبراهيم عليه السلام فجاء بعجل حنيذ لضيوفه."},{"type":"mcq","q":"كيف يتعامل طالب الصف التاسع إذا زار أسرته ضيوف في البيت؟","options":["يتضجر من الزيارة","يختبئ منشغلًا بهاتفه دون سلام","يبادر بالترحيب والابتسامة ومساعدة أسرته في تقديم القهوة والتمر بأدب","يقاطع حديث الكبار"],"answer":2,"why":"السمت العُماني يغرس أدب استقبال الضيوف في الأبناء."},{"type":"tfr","q":"ربط النبي ﷺ إكرام الضيف بالإيمان بالله واليوم الآخر.","answer":true,"reasons":["في الحديث الشريف: «من كان يؤمن بالله واليوم الآخر فليكرم ضيفه»","لم يرد فيه حديث","نهى عن الضيافة"],"reason":0},{"type":"tfr","q":"تُعدّ «السبلة العُمانية» وتقديم القهوة والتمر امتدادًا حيًّا لقيمة القِرى عند العرب.","answer":true,"reasons":["هي عادة حديثة فقط","وتعكس كرم الضيافة وحسن الخلق الذي يشتهر به أهل عُمان","تتعارض مع القرى"],"reason":1},{"type":"tfr","q":"الضيافة مسؤولية المضيف وحده، ولا توجد آداب مطلوبة من الضيف.","answer":false,"reasons":["الضيف يفعل ما يشاء","نعم لا آداب على الضيف","بل على الضيف الاستئذان واختيار الوقت المناسب وعدم إثقال كاهل المضيف والدعاء له"],"reason":2},{"type":"essay","q":"اذكر ثلاثة مظاهر لإكرام الضيف في المجتمع العُماني المعاصر.","model":"١) استقبال الضيف بحفاوة وطلاقة وجه في السبلة أو المجلس. ٢) تقديم القهوة العُمانية والتمر والحلوى (الفوالة). ٣) توديع الضيف بلطف واحترام حتى باب المنزل."},{"type":"essay","q":"اذكر ثلاثة آداب ينبغي للضيف أن يتحلّى بها عند زيارة الآخرين.","model":"١) الاستئذان المسبق واختيار الوقت المناسب. ٢) عدم الإطالة التي تحرج صاحب البيت. ٣) شكر المضيف والدعاء له بالخير والبركة."},{"type":"essay","q":"اشرح معنى البيت الشعري: «أضاحكُ ضيفي قبل إنزال رحلِه · ويُخصبُ عندي والمحلُّ جديبُ».","model":"يعني أن الشاعر يستقبل ضيفه بالابتسامة والترحيب الدافئ قبل أن ينزل عن راحلته، ويكرمه بسخاء حتى في أوقات القحط والشدة."}]}},
  {"id":"g9-arabic-2-u8-6","grade":"g9","subject":"arabic","term":2,"unit":8,"no":6,"title":"النص الأدبي: هل درى ظبيُ الحمى؟","summary":"شرح متحرك بـ SVG لدرس النص الأدبي: هل درى ظبيُ الحمى؟ (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-hal-dara-dhabiy-al-hima.html","video":"","pdf":"","notes":["الشاعر: ابن سهل الأندلسي | الفن: الموشّح الأندلسي (تنوع قوافي وأدوار وأقفال).","المطلع: «هل درى...» (استفهام بلاغي للتشوق) | «الحِمى / حَمى» (جناس تام بديع).","سمات النص: رقة الألفاظ، الامتزاج بالطبيعة، عذوبة الموسيقى، والخيال الأندلسي الهادئ."],"exercises":["عرّف «الموشّح الأندلسي»، واذكر فرقين بينه وبين القصيدة العمودية التقليدية.","استخرج من المطلع «هل درى ظبيُ الحمى أن قد حمى · قلبَ صَبٍّ حلّه عن مَكنِسِ»: (أ) استفهامًا وبيّن غرضه، (ب) جناسًا وبيّن نوعه وأثره.","اشرح معاني المفردات الآتية: الحِمى، صَبّ، مَكنِس."],"levels":{"easy":[{"type":"mcq","q":"من قائل موشح «هل درى ظبيُ الحمى أن قد حمى»؟","options":["معروف الرصافي","إبراهيم بن سهل الأندلسي","عنترة بن شداد","أبو العلاء المعري"],"answer":1,"why":"ابن سهل الإشبيلي الأندلسي من أشهر شعراء الموشحات."},{"type":"mcq","q":"إلى أي فنٍّ شعري ينتمي هذا النص الأدبي؟","options":["المقامة النثرية","شعر النقائض","فنّ الموشّح الأندلسي","المسرح الشعري"],"answer":2,"why":"الموشح فنّ أندلسي يتميّز بتنوّع القوافي والأدوار وعذوبة الإيقاع."},{"type":"mcq","q":"ما المحسّن البديعي بين كلمتَي «الحِمى» و«حَمى» في مطلع الموشح؟","options":["ترادف","طباق سلب","مقابلة","جناس تام (اتفقا في اللفظ واختلفا في المعنى)"],"answer":3,"why":"الحِمى اسم للمكان المحمي، وحَمى فعل بمعنى صان ومنع."},{"type":"mcq","q":"ما الغرض البلاغي من الاستفهام في قوله: «هل درى ظبيُ الحمى؟»","options":["التشوّق والتحسّر وإظهار لوعة الحنين","طلب معلومة علمية حقيقية","التهديد والوعيد","السخرية"],"answer":0,"why":"استفهام بلاغي يعبّر عن شدة الشوق والحنين."}],"medium":[{"type":"mcq","q":"ما معنى كلمة «صَبّ» في المطلع؟","options":["الغاضب القاسي","شديد الشوق والمحبة","المسافر التائه فقط","البخيل"],"answer":1,"why":"الصَّبّ في اللغة هو المشتاق المحبّ."},{"type":"mcq","q":"بمَ يختلف «الموشّح الأندلسي» شكليًا عن القصيدة العمودية التقليدية؟","options":["بأنه لا يحتوي على صور فنية","بأنه يُكتب نثرًا بلا وزن","بتنوّع قوافيه وتقسيمه إلى أدوار وأغصان وأقفال تلائم الغناء والإنشاد","بأنه بيت واحد فقط"],"answer":2,"why":"تنوع القوافي والأقفال هو السمة الشكلية الأبرز للموشح."},{"type":"mcq","q":"ما معنى كلمة «المَكنِس» الواردة في مطلع الموشح؟","options":["ساحل البحر","أداة التنظيف","قمة الجبل الثلجي","مأوى الظبي الذي يستتر فيه"],"answer":3,"why":"المكنس هو موضع استتار الظبي ومأواه (اسم مكان!)."},{"type":"tfr","q":"فنّ الموشحات فنّ شعري ابتكره أهل الأندلس ويتميّز بتنوّع القوافي والأقفال.","answer":true,"reasons":["يُكتب نثرًا بلا وزن","ابتُكر في العصر الجاهلي","مما أكسبه عذوبةً موسيقيةً عاليةً وجعله ملائمًا للإنشاد"],"reason":2},{"type":"tfr","q":"الجمع بين «الحِمى» و«حَمى» في مطلع الموشح يُعدّ طباقًا.","answer":false,"reasons":["بل هو «جناس تام» لأنهما اتفقا في الحروف واختلفا في المعنى","نعم طباق","هو ترادف"],"reason":0},{"type":"essay","q":"عرّف «الموشّح الأندلسي»، واذكر فرقين بينه وبين القصيدة العمودية التقليدية.","model":"الموشح فن شعري أندلسي مقسّم إلى أدوار وأغصان وأقفال. الفرقان: ١) تنوع القوافي والأقفال بدل القافية الموحدة في القصيدة العمودية. ٢) رقته ومناسبته العالية للغناء والإنشاد الموسيقي."},{"type":"essay","q":"استخرج من المطلع «هل درى ظبيُ الحمى أن قد حمى · قلبَ صَبٍّ حلّه عن مَكنِسِ»: (أ) استفهامًا وبيّن غرضه، (ب) جناسًا وبيّن نوعه وأثره.","model":"(أ) «هل درى...؟» استفهام بلاغي غرضه التشوق والتحسر. (ب) «الحِمى / حَمى» جناس تام يعطي جرسًا موسيقيًا جميلًا ويبرز المعنى."}],"hard":[{"type":"mcq","q":"ما أبرز سمةٍ للألفاظ والخيال في موشحات الأندلس؟","options":["الرقة والعذوبة والامتزاج الساحر بين جمال الطبيعة والوجدان","الخشونة والغرابة اللفظية","الجفاف العلمي البحت","الغموض التام"],"answer":0,"why":"بيئة الأندلس الجميلة انعكست رقةً وعذوبةً في شعرها."},{"type":"mcq","q":"أين نشأ فنّ الموشحات وازدهر في التاريخ الأدبي العربي؟","options":["في العصر الجاهلي قبل الإسلام","في الأندلس","في الصين","في القرن الحادي والعشرين"],"answer":1,"why":"ابتكره شعراء الأندلس وأبدعوا فيه."},{"type":"mcq","q":"ما الأثر الجمالي للجناس التام بين «الحِمى» و«حَمى»؟","options":["يجعل البيت غير مفهوم","يُضعف المعنى","يُحدث جرسًا موسيقيًا عذبًا يلفت انتباه السامع ويزيد البيت رونقًا","يُلغي الوزن"],"answer":2,"why":"الجناس غير المتكلّف يمنح الشعر طربًا موسيقيًا."},{"type":"mcq","q":"ما دلالة انتشار موشح ابن سهل ومعارضة الشعراء له عبر القرون؟","options":["أنه كُتب بلغة غير عربية","قلة الشعراء في عصره","أنه قصير جدًا فقط","سموّ قيمته الفنية وعذوبة موسيقاه وصدق عاطفته"],"answer":3,"why":"الأعمال الخالدة تُلهم الشعراء وتبقى حيّة عبر الأجيال."},{"type":"tfr","q":"الاستفهام في «هل درى ظبي الحمى؟» استفهام حقيقي ينتظر الشاعر إجابته بنعم أو لا.","answer":false,"reasons":["نعم استفهام حقيقي","بل استفهام بلاغي غرضه التشوّق والتحسّر وإظهار الحنين","غرضه التعجيز"],"reason":1},{"type":"tfr","q":"يمتاز شعر الأندلس عامةً وموشح ابن سهل خاصةً برقة الألفاظ والامتزاج بجمال الطبيعة.","answer":true,"reasons":["يخلو من الطبيعة","يمتاز بالخشونة والغرابة","بسبب جمال الطبيعة الأندلسية ورهافة حسّ شعرائها"],"reason":2},{"type":"tfr","q":"كلمة «مَكنِس» (مأوى الظبي) تأتي صرفيًا على وزن «مَفْعِل» لاسم المكان.","answer":true,"reasons":["لأن مضارعه يَكنِس (مكسور العين) فيأتي على مَفْعِل — ربط رائع بالصرف!","هي اسم آلة","هي صيغة مبالغة"],"reason":0},{"type":"essay","q":"اشرح معاني المفردات الآتية: الحِمى، صَبّ، مَكنِس.","model":"الحِمى: الديار المحمية العزيزة. صَبّ: المشتاق المحبّ. مَكنِس: مأوى الظبي الذي يستتر فيه."},{"type":"essay","q":"كيف عكست موشحات الأندلس أثر البيئة في الأدب؟","model":"جمال طبيعة الأندلس من حدائق وأنهار وأزهار أكسب شعرها رقة الألفاظ وعذوبة الإيقاع وكثرة الصور المستمدة من الطبيعة."},{"type":"essay","q":"ما الذي يثبته ازدهار فن الموشحات عن طبيعة اللغة العربية والأدب العربي؟","model":"يثبت حيوية العربية ومرونتها وقدرتها الدائمة على التجديد الإبداعي والموسيقي مع الحفاظ على أصالتها وفصاحتها."}]}}
);
UNITS.push(
  {"id":"g9-arabic-1-u1","grade":"g9","subject":"arabic","term":1,"title":"الوحدة الأولى: البلاغة والبيان","levels":{"easy":[{"type":"mcq","q":"من مؤلف كتاب «البيان والتبيين» الذي أُخذ منه درس البلاغة عند العرب؟","options":["البوصيري","الجاحظ","الخليل بن أحمد","سيبويه"],"answer":1,"why":"مؤلف كتاب البيان والتبيين هو الجاحظ."},{"type":"mcq","q":"ما الغرض الشعري لقصيدة «يا سماء» للبوصيري؟","options":["الرثاء","الهجاء","المدائح النبوية","الفخر"],"answer":2,"why":"القصيدة في مدح النبيّ محمد ﷺ وتعظيم مكانته."},{"type":"mcq","q":"أين المفعول لأجله في جملة: «أذاكرُ رَغْبَةً في التفوّقِ»؟","options":["أذاكرُ","رَغْبَةً","في","التفوّقِ"],"answer":1,"why":"«رَغْبَةً» مصدر قلبي منصوب يجيب عن السؤال: لماذا أذاكر؟"},{"type":"mcq","q":"أيٌّ مما يأتي يُعدّ معجمًا مختصًّا؟","options":["المعجم الوسيط","لسان العرب","المعجم الطبي الموحّد","القاموس المحيط"],"answer":2,"why":"المعجم الطبي يجمع مصطلحات علم الطب فقط."}],"medium":[{"type":"mcq","q":"ما الغرض البلاغي من الاستفهام في: «كيف ترقى رقيّك الأنبياءُ»؟","options":["النفي والتعظيم","التمني","الاستنكار","التخيير"],"answer":0,"why":"يدلّ على أن أحدًا لا يبلغ منزلة النبيّ ﷺ الرفيعة."},{"type":"tfr","q":"تُضبط كلمة «خَشْيَةَ» في «خشيةَ الحرِّ» بفتحة واحدة دون تنوين لأنها مضافة.","answer":true,"reasons":["لأن الإضافة تحذف التنوين من المضاف","لأنها مجرورة بالكسرة","لأنها مقترنة بأل"],"reason":0},{"type":"mcq","q":"ما المقصود بالبلاغة اصطلاحًا؟","options":["كثرة الكلام","مطابقة الكلام لمقتضى الحال مع فصاحته","استخدام الألفاظ الغريبة","الاكتفاء بالشعر"],"answer":1,"why":"البلاغة هي اختيار الكلام الفصيح المناسب للمقام والسامعين."},{"type":"tfr","q":"يؤلّف المعجم المختص علماء اللغة فقط دون مشاركة مختصّي العلوم.","answer":false,"reasons":["لأن المعجم المختص يؤلّفه المختصون في ذلك العلم أو الفن لضمان الدقة العلمية","لأن المعاجم المختصة لا مؤلفين لها","لأن اللغويين لا يؤلفون المعاجم العامة"],"reason":0},{"type":"essay","q":"أعرب كلمة «احترامًا» في جملة: «وَقَفَ الطالبُ احترامًا للمعلّمِ».","model":"احترامًا: مفعول لأجله منصوب وعلامة نصبه الفتحة الظاهرة على آخره."}],"hard":[{"type":"mcq","q":"لماذا جُرَّ المصدر باللام في: «أعددتُ الحقيبةَ للسفرِ غدًا»؟","options":["لأنه مضاف","لاختلاف الزمن بين الفعل والمصدر","لأنه حال","لأنه مفعول مطلق"],"answer":1,"why":"اختل شرط اتحاد الزمن (الإعداد الآن والسفر غدًا) فوجب الجر باللام."},{"type":"tfr","q":"يعتمد منهج الجاحظ في «البلاغة عند العرب» على طرح الفكرة ثم تدعيمها بشواهد من بلغاء العرب.","answer":true,"reasons":["لأنه استشهد بأقوال خطباء العرب مثل صُحار العبدي لإثبات أصالة بلاغتهم","لأنه لم يذكر أي شاهد في النص","لأنه اعتمد على القصص الخيالية"],"reason":0},{"type":"essay","q":"اشرح التشبيه في قول البوصيري: «أنت فيه اليتيمةُ العصماءُ».","model":"شبّه الشاعر النبيّ ﷺ بالدرّة الفريدة الثمينة التي تتوسّط عقد السيادة والشرف."},{"type":"mcq","q":"ما الفرق بين شرح كلمة «الجزم» في المعجم العام ومعجم النحو المختص؟","options":["العام يعطي المعنى اللغوي (القطع)، والمختص يعطي المعنى النحوي (حالة إعرابية للمضارع)","لا يوجد فرق بينهما","المعجم العام لا يشرح الكلمة","معجم النحو يعطي المعنى الطبي"],"answer":0,"why":"المعجم المختص يركّز على المعنى الاصطلاحي الدقيق في التخصص."},{"type":"essay","q":"فرّق بين المفعول لأجله والحال بمثال لكلٍّ منهما.","model":"المفعول لأجله مصدر قلبي يجيب عن «لماذا؟» مثل: اجتهدتُ طلبًا للنجاح. والحال يبيّن الهيئة ويجيب عن «كيف؟» مثل: أقبلَ الطالبُ مبتسمًا."}]},"test":[{"type":"mcq","q":"أُخذ نص «البلاغة عند العرب» للجاحظ من كتاب:","options":["البخلاء","البيان والتبيين","كتاب العين","الحيوان"],"answer":1,"why":"النص للجاحظ من كتابه الشهير «البيان والتبيين»."},{"type":"mcq","q":"ما معنى «البلاغة» في اللغة العربية؟","options":["الوصول والانتهاء إلى الغاية","الإطالة في الكلام","الغموض والتعقيد","تكرار الألفاظ"],"answer":0,"why":"البلاغة في اللغة من الفعل «بَلَغَ» أي وصل إلى الغاية والمنتهى."},{"type":"mcq","q":"عرّف الخطيب صُحار العبدي البلاغة بأنها:","options":["التكرار","الإيجاز","السجع","الإطالة"],"answer":1,"why":"لخّص صُحار العبدي البلاغة في «الإيجاز» أي أداء المعنى الكثير بلفظ قليل."},{"type":"tf","q":"البلاغة اصطلاحًا هي مطابقة الكلام لمقتضى الحال مع فصاحته.","answer":true,"why":"نعم، فلكل مقامٍ مقالٌ يناسبه من إيجاز أو تفصيل."},{"type":"tfr","q":"اكتفى الجاحظ بطرح رأيه في بلاغة العرب دون أن يقدّم أدلةً أو شواهد.","answer":false,"reasons":["لأن منهج الجاحظ يقوم على طرح الفكرة ثم تدعيمها بشواهد من خطباء العرب وبلغائهم","لأن الجاحظ لم يكتب في البلاغة أصلًا","لأن الشواهد تُستخدم في الشعر فقط"],"reason":0},{"type":"essay","q":"اذكر اثنتين من مقوّمات الخطيب البليغ كما وردت في درس «البلاغة عند العرب».","model":"وضوح الصوت، وحسن الإشارة، والثبات (رباطة الجأش)، ومعرفة متى يوجز ومتى يفصّل حسب الموقف."},{"type":"mcq","q":"من قائل قصيدة «يا سماء»؟","options":["الجاحظ","أبو تمام","شرف الدين البوصيري","المتنبي"],"answer":2,"why":"قائل القصيدة هو الإمام شرف الدين محمد بن سعيد البوصيري."},{"type":"mcq","q":"ما الغرض البلاغي من الاستفهام في قول البوصيري: «كيف ترقى رقيّك الأنبياءُ»؟","options":["التمنّي","النفي والتعظيم","طلب المعلومة","التخيير"],"answer":1,"why":"المعنى أنه لا يبلغ أحدٌ منزلة النبيّ ﷺ الرفيعة، فغرضه النفي والتعظيم."},{"type":"mcq","q":"ما العلاقة البلاغية بين كلمتي «مضيءٌ» و«ليلةٌ» في قصيدة «يا سماء»؟","options":["ترادف","طباق","جناس","توكيد"],"answer":1,"why":"الطباق بين النور والليل يبرز أثر نور النبيّ ﷺ في تبديد الظلام."},{"type":"tf","q":"كلمة «المحيّا» في قول البوصيري «ومحيًّا كالشمس منك مضيءٌ» تعني الوجه.","answer":true,"why":"نعم، المحيّا هو الوجه وقد شبّهه الشاعر بالشمس المضيئة."},{"type":"tfr","q":"يرى البوصيري أن معجزات النبيّ ﷺ انقضت بوفاته مثل معجزات الأنبياء السابقين.","answer":false,"reasons":["لأنه أكّد أن آيات الأنبياء السابقين انقضت، أما آيات النبيّ ﷺ والقرآن فباقية لا تنقضي","لأنه لم يتحدث عن المعجزات في القصيدة","لأن القصيدة في الرثاء لا في المدح"],"reason":0},{"type":"essay","q":"اشرح الصورة الجمالية في قول الشاعر: «حبّذا عقدُ سؤددٍ وفخارِ / أنت فيه اليتيمةُ العصماءُ».","model":"شبّه الشاعر نسب النبيّ ﷺ بعقدٍ ثمينٍ من السيادة والشرف، وشبّه النبيّ ﷺ بالدرّة الفريدة (اليتيمة) التي تتوسّط هذا العقد."},{"type":"mcq","q":"ما السؤال الذي نستدلّ به على المفعول لأجله في الجملة؟","options":["أين؟","متى؟","كيف؟","لماذا؟"],"answer":3,"why":"المفعول لأجله يبيّن سبب وقوع الفعل فيجيب عن «لماذا؟»."},{"type":"mcq","q":"ما صورة المفعول لأجله في جملة: «تصدّقتُ طَلَبًا للأجرِ»؟","options":["مجرّد من أل والإضافة","مضاف","مقترن بأل","جار ومجرور"],"answer":0,"why":"«طَلَبًا» نكرة منوّنة غير مقترنة بأل ولم تُضَف إلى اسم بعدها."},{"type":"mcq","q":"ما صورة المفعول لأجله في جملة: «يلجأ الناسُ إلى المصايفِ خَشْيَةَ الحرِّ»؟","options":["مجرّد من أل والإضافة","مضاف","مقترن بأل","حال منصوبة"],"answer":1,"why":"«خَشْيَةَ» أضيفت إلى «الحرِّ» فحُذف منها التنوين وجاءت بفتحة واحدة."},{"type":"tf","q":"في جملة «أقبلَ الطالبُ مبتسمًا» تُعرب كلمة «مبتسمًا» مفعولًا لأجله.","answer":false,"why":"«مبتسمًا» تجيب عن «كيف؟» وتبيّن الهيئة، فهي حال وليست مفعولًا لأجله."},{"type":"tfr","q":"إذا فقد المصدر شرط اتحاد الزمن أو الفاعل مع الفعل وجب جرّه بحرف الجر.","answer":true,"reasons":["لأن اتحاد الزمن والفاعل من شروط نصب المفعول لأجله، مثل: أعددتُ الحقيبةَ للسفرِ غدًا","لأن المفعول لأجله لا شروط له","لأن حرف الجر يُستعمل مع كل مفعول به"],"reason":0},{"type":"essay","q":"أعرب ما تحته خط: «أجتهدُ في دروسي رَغْبَةً في النجاحِ».","model":"رَغْبَةً: مفعول لأجله منصوب وعلامة نصبه الفتحة الظاهرة على آخره."},{"type":"essay","q":"فرّق بين إعراب الكلمة المنصوبة في: (١) اجتهدتُ اجتهادًا. (٢) اجتهدتُ طلبًا للعلمِ.","model":"في (١) «اجتهادًا» مفعول مطلق منصوب لأنه مصدر من لفظ الفعل. وفي (٢) «طلبًا» مفعول لأجله منصوب لأنه مصدر قلبي من غير لفظ الفعل يبيّن سبب الاجتهاد."},{"type":"mcq","q":"يُسمّى المعجم المختص أيضًا:","options":["المعجم العام","معجم المصطلحات","معجم القوافي","معجم الأمثال"],"answer":1,"why":"لأنه يجمع مصطلحات علم أو فن واحد ويشرحها شرحًا علميًّا دقيقًا."},{"type":"mcq","q":"أيٌّ مما يأتي يُعدّ مثالًا على المعجم العام؟","options":["المعجم الطبي الموحّد","معجم الحاسوب","المعجم الوسيط","معجم مصطلحات الفقه"],"answer":2,"why":"المعجم الوسيط معجم لغوي عام يجمع ألفاظ اللغة العامة كلها."},{"type":"mcq","q":"إذا أردتَ معرفة المعنى الاصطلاحي الدقيق لكلمة «الجزم» في النحو، فأيّ معجمٍ تراجع؟","options":["معجم الطب","معجم مصطلحات النحو","معجم الجغرافيا","معجم الفيزياء"],"answer":1,"why":"المعجم المختص في النحو يقدّم التعريف الاصطلاحي الدقيق للمصطلحات النحوية."},{"type":"tf","q":"تتجدّد مادة المعجم المختص باستمرار لمواكبة تطوّر العلوم والاكتشافات الحديثة.","answer":true,"why":"نعم، لأن العلوم الحديثة تنتج مصطلحات ومفاهيم جديدة باستمرار."},{"type":"tfr","q":"الترتيب الموضوعي في المعجم المختص يجمع مصطلحات كل موضوعٍ معًا في بابٍ واحد.","answer":true,"reasons":["لأنه يصنّف المصطلحات المتقاربة تحت موضوعها العلمي لتسهيل البحث","لأنه يرتّب الكلمات عشوائيًا","لأنه خاص بالمعجم العام فقط"],"reason":0},{"type":"essay","q":"اذكر فرقَين بين المعجم العام والمعجم المختص.","model":"١) المادة: المعجم العام يجمع ألفاظ اللغة العامة كلها، أما المختص فيجمع مصطلحات علمٍ واحدٍ فقط. ٢) المؤلّف: العام يؤلّفه اللغويون، والمختص يؤلّفه المختصون في ذلك العلم."}]},
  {"id":"g9-arabic-1-u2","grade":"g9","subject":"arabic","term":1,"title":"الوحدة الثانية: من أدب عُمان وتراثها","levels":{"easy":[{"type":"mcq","q":"من مؤسّس دولة اليعاربة في عُمان عام ١٦٢٤م؟","options":["الإمام ناصر بن مرشد","الجاحظ","البوصيري","أبو تمام"],"answer":0,"why":"بويع الإمام ناصر بن مرشد فوحّد عُمان وحرّر موانئها."},{"type":"mcq","q":"ما القسم الأكبر في تصميم موضوع التعبير؟","options":["المقدّمة","الجوهر (العرض)","الخاتمة","العنوان"],"answer":1,"why":"الجوهر يضمّ الأفكار الفرعية وتفاصيلها والشواهد."},{"type":"mcq","q":"أين تقع سلطنة عُمان في شبه الجزيرة العربية؟","options":["الشمال الغربي","الوسط","الجنوب الشرقي","الشمال"],"answer":2,"why":"تقع عُمان في الركن الجنوبي الشرقي من شبه الجزيرة العربية."},{"type":"mcq","q":"من كاتب رسالة النصيحة إلى الإمام ناصر بن مرشد؟","options":["الشيخ سعيد بن أحمد الخراسيني","الخليل بن أحمد","سيبويه","المتنبي"],"answer":0,"why":"صاحب النصيحة هو الشيخ العالم سعيد بن أحمد الخراسيني."}],"medium":[{"type":"mcq","q":"ما النظام المائي الهندسي العُماني المدرج في التراث العالمي لليونسكو؟","options":["الأفلاج","الأنهار","السدود الحديثة","الأنفاق"],"answer":0,"why":"الأفلاج قنوات مائية عريقة لريّ الواحات والمزارع."},{"type":"tfr","q":"تُخصَّص لكل فكرة فرعية في جوهر الموضوع فقرةٌ مستقلةٌ وواضحة.","answer":true,"reasons":["لأن ذلك يمنع تداخل الأفكار ويجعل الموضوع متسلسلًا وسهل القراءة","لأن الموضوع كله يجب أن يكون فقرة واحدة","لأن الأفكار الفرعية تُكتب في الخاتمة فقط"],"reason":0},{"type":"mcq","q":"ما العلاقة البلاغية بين «دُجاها» و«نهارُ» في شعر عصر اليعاربة؟","options":["ترادف","طباق","جناس","توكيد"],"answer":1,"why":"الدجى هو الظلام وبينه وبين النهار طباق."},{"type":"tfr","q":"حذّر الشيخ الخراسيني الإمام من تقريب المتملّقين وذوي الأطماع.","answer":true,"reasons":["لأن البطانة السيئة تزيّن الباطل وتخفي الحقائق عن الحاكم","لأن المتملّقين ينصرون الحق دائمًا","لأن الرسالة لم تتحدث عن الولاة والبطانة"],"reason":0},{"type":"essay","q":"اذكر اثنتين من سمات أسلوب الشيخ الخراسيني في نصيحته.","model":"وضوح الألفاظ وصدق العاطفة، والجمع بين الصدق واللطف، والتأثّر بالقرآن الكريم والسنة النبوية."}],"hard":[{"type":"mcq","q":"ما الغرض البلاغي من أساليب الأمر والنهي في نصيحة الشيخ الخراسيني؟","options":["السخرية","التعجيز","النصح والإرشاد","الاستفهام"],"answer":2,"why":"جاءت بدافع الإخلاص والمحبّة للنصح والإرشاد."},{"type":"tfr","q":"اقتصرت وظيفة القلاع والحصون العُمانية قديمًا على الدفاع العسكري فقط.","answer":false,"reasons":["لأنها كانت أيضًا مراكز للعلم والقضاء وإدارة شؤون الناس إلى جانب الحماية","لأن عُمان لا توجد فيها قلاع","لأنها كانت أسواقًا تجارية فقط"],"reason":0},{"type":"essay","q":"علّل: لماذا شهد عصر اليعاربة نهضةً علميةً وأدبيةً واسعةً في عُمان؟","model":"بسبب توحيد البلاد وتحرير الموانئ مما حقّق الأمن والاستقرار، وبسبب رعاية الأئمة للعلماء والأدباء ومشاركة بعض الأئمة أنفسهم في العلم والأدب."},{"type":"mcq","q":"لماذا نحدّد «الفكرة العامة» كأول خطوة عند تصميم موضوع تعبير؟","options":["لتكون بوصلة تضبط كل الفقرات وتمنع الخروج عن الموضوع","لإلغاء الحاجة إلى المقدمة","لتكرار نفس الجملة","لتقليص عدد الفقرات إلى واحدة"],"answer":0,"why":"تحديد الفكرة العامة يضمن ارتباط جميع الأفكار الفرعية بمحور الموضوع."},{"type":"essay","q":"اذكر ثلاث قيم إنسانية وحضارية تجمع بين دروس الوحدة الثانية.","model":"العدل والشورى، وحبّ الوطن والاعتزاز بتراثه، وكرم الضيافة والتسامح، وتنظيم الفكر والعمل."}]},"test":[{"type":"mcq","q":"بويع بالإمامة وأسّس دولة اليعاربة في عُمان عام ١٦٢٤م:","options":["الإمام ناصر بن مرشد","الجاحظ","شرف الدين البوصيري","الخليل بن أحمد"],"answer":0,"why":"الإمام ناصر بن مرشد وحّد عُمان وبدأ تحرير موانئها من البرتغاليين."},{"type":"mcq","q":"ضدّ مَن خاض العُمانيون معارك التحرير البحرية في عصر اليعاربة؟","options":["الروم","البرتغاليين","المغول","البيزنطيين"],"answer":1,"why":"حرّر اليعاربة السواحل والموانئ العُمانية من الاحتلال البرتغالي."},{"type":"mcq","q":"ما العلاقة البلاغية بين «دُجاها» و«نهارُ» في قول الشاعر «كأنّ دُجاها بالسيوفِ نهارُ»؟","options":["ترادف","طباق","جناس","سجع"],"answer":1,"why":"الدجى هو الظلام وبينه وبين النهار طباق يبرز شدة لمعان السيوف."},{"type":"tf","q":"كان بعض أئمة اليعاربة أنفسهم علماء وأدباء وشعراء متمكّنين.","answer":true,"why":"نعم، وقد أسهم ذلك في توثيق العلاقة بين الحكم والعلم والأدب."},{"type":"tfr","q":"اقتصر الشعر في عصر اليعاربة على شعر الحماسة والقتال دون غيره من الأغراض.","answer":false,"reasons":["لأنه تنوّع فشمل المديح والزهد والوعظ والوصف والرثاء إلى جانب الحماسة","لأن الشعر لم يوجد في عصر اليعاربة أصلًا","لأنه اقتصر على شعر الغزل فقط"],"reason":0},{"type":"essay","q":"اذكر اثنتين من الخصائص الفنية للأدب في عصر اليعاربة.","model":"الارتباط بقضايا الوطن والدين، وجزالة الألفاظ وقوة التراكيب، والعناية بالصور البلاغية والتشبيهات والمحسنات."},{"type":"mcq","q":"ما المقصود بـ «تصميم الموضوع» في التعبير الكتابي؟","options":["نسخ موضوع جاهز","وضع خطّة منظّمة للأفكار والعناصر قبل الكتابة","تلوين العنوان فقط","كتابة جملة واحدة"],"answer":1,"why":"التصميم هو التخطيط المسبق لترتيب الأفكار قبل كتابة النص الكامل."},{"type":"mcq","q":"ما القسم الأكبر في موضوع التعبير الذي يحتوي على الأفكار الفرعية؟","options":["العنوان","المقدّمة","الجوهر (العرض)","الخاتمة"],"answer":2,"why":"الجوهر هو القسم الأكبر وفيه تُفصّل الأفكار الفرعية وتُدعّم بالشواهد."},{"type":"mcq","q":"كيف نقوّي الأفكار الفرعية ونجعلها أكثر إقناعًا داخل الجوهر؟","options":["بتكرار الجمل نفسها","بالأمثلة والأدلة والشواهد المناسبة","بحذف علامات الترقيم","بالخروج عن الفكرة العامة"],"answer":1,"why":"الآيات والأحاديث والأمثلة الواقعية تقوّي الفكرة وتقنع القارئ."},{"type":"tf","q":"المقدّمة الجيّدة تكون موجزةً وتمهّد للموضوع دون الدخول في تفاصيل الجوهر.","answer":true,"why":"نعم، فالمقدّمة بوابة موجزة وجذّابة تمهّد للموضوع."},{"type":"tfr","q":"لا يجوز أن تأتي خاتمة الموضوع على هيئة رأي شخصي أو توصية بل يجب أن تكون تلخيصًا فقط.","answer":false,"reasons":["لأن الخاتمة تتنوّع بين التلخيص، وإبداء الرأي والتوصية، وطرح سؤال للتفكير","لأن الموضوع لا يحتاج إلى خاتمة أبدًا","لأن الخاتمة تُكتب في أول الصفحة"],"reason":0},{"type":"essay","q":"اذكر الأقسام الثلاثة الرئيسة لتصميم أي موضوع تعبير، ووظيفة كل قسم بإيجاز.","model":"١) المقدّمة: تمهيد موجز وجذّاب للموضوع. ٢) الجوهر: تفصيل الأفكار الفرعية وتدعيمها بالأمثلة والشواهد. ٣) الخاتمة: خلاصة موجزة أو رأي وتوصية أو سؤال للتفكير."},{"type":"mcq","q":"تقع سلطنة عُمان في الركن ......... من شبه الجزيرة العربية:","options":["الشمالي الغربي","الجنوبي الشرقي","الشمالي الشرقي","الأوسط"],"answer":1,"why":"تقع عُمان في الركن الجنوبي الشرقي وتطلّ على بحر عُمان وبحر العرب ومضيق هرمز."},{"type":"mcq","q":"ما النظام المائي الهندسي العُماني المدرج في التراث العالمي لليونسكو؟","options":["الأفلاج","البحيرات الصناعية","السدود الجليدية","الأنفاق"],"answer":0,"why":"الأفلاج قنوات مائية عريقة لريّ الواحات والمزارع وتعكس التعاون والابتكار."},{"type":"mcq","q":"أيُّ محافظة عُمانية تشتهر بموسم الخريف الأخضر والشلالات؟","options":["مسندم","البريمي","ظفار","الوسطى"],"answer":2,"why":"تتميّز ظفار في جنوب السلطنة بخريفها الأخضر وضبابها المنعش."},{"type":"tf","q":"أبحر العُمانيون بسفنهم التقليدية إلى شرق إفريقيا والهند والصين ناشرين التجارة والقيم الإسلامية.","answer":true,"why":"نعم، اشتهر العُمانيون بالملاحة والتواصل الحضاري وأخلاقهم الرفيعة."},{"type":"tfr","q":"اقتصرت القلاع والحصون العُمانية مثل قلعة نزوى وحصن جبرين على الأغراض العسكرية فقط.","answer":false,"reasons":["لأنها كانت أيضًا مراكز للعلم والقضاء وإدارة شؤون المجتمع إلى جانب الحماية","لأنها بُنيت في العصر الحديث فقط","لأنها لم تُستخدم في الدفاع أبدًا"],"reason":0},{"type":"essay","q":"اذكر ثلاث خطوات لإتقان مهارة الاستماع الواعي كما تعلّمت في الدرس.","model":"الإنصات بهدوء وتركيز، والتقاط الفكرة العامة، وتدوين الكلمات المفتاحية والتفاصيل، ثم تلخيص المسموع بأسلوبك."},{"type":"mcq","q":"صاحب نصيحة «من نصيحة الشيخ الخراسيني لأحد أئمة اليعاربة» هو:","options":["الشيخ سعيد بن أحمد الخراسيني","الجاحظ","البوصيري","أبو تمام"],"answer":0,"why":"كاتب الرسالة هو الشيخ العالم سعيد بن أحمد الخراسيني."},{"type":"mcq","q":"ما المبدأ الذي دعا إليه الشيخ الخراسيني للاستعانة بأهل العلم والخبرة في القرارات؟","options":["الاستبداد","الشورى","العزلة","التسرّع"],"answer":1,"why":"دعا إلى التمسّك بالشورى لأنها تكشف الصواب وتجمع الكلمة."},{"type":"mcq","q":"ما الغرض البلاغي من أساليب الأمر والنهي في رسالة الشيخ الخراسيني؟","options":["التعجيز","السخرية","النصح والإرشاد","التمنّي"],"answer":2,"why":"جاءت أساليب الأمر والنهي بروح المحبّة والإخلاص للنصح والإرشاد."},{"type":"tf","q":"جمع الشيخ الخراسيني في نصيحته بين الصدق والجرأة في الحقّ وبين اللطف والأدب في الخطاب.","answer":true,"why":"نعم، فالنصيحة المؤثّرة تقوم على الإخلاص ولين العبارة وقصد الإصلاح."},{"type":"tfr","q":"حذّر الشيخ الخراسيني الإمام من تقريب المتملّقين وذوي الأطماع.","answer":true,"reasons":["لأن البطانة السيئة تزيّن الباطل وتخفي الحقائق عن الحاكم مما يضرّ بالرعية","لأن المتملّقين يقدّمون النصيحة الصادقة دائمًا","لأن الرسالة لم تتناول اختيار الولاة والبطانة"],"reason":0},{"type":"essay","q":"اذكر ثلاث وصايا رئيسة وجّهها الشيخ الخراسيني إلى الإمام ناصر بن مرشد.","model":"تقوى الله ومراقبته في السر والعلن، وإقامة العدل بين الرعية، والرحمة بالضعفاء، والتمسّك بالشورى، وحسن اختيار الولاة الأمناء ومحاسبتهم."},{"type":"essay","q":"ما الدرس العملي الذي نتعلّمه من أسلوب الشيخ الخراسيني عندما ننصح زميلًا أو صديقًا؟","model":"أن تكون النصيحة خالصةً بقصد الإصلاح لا التشهير، وأن نجمع فيها بين الصدق والوضوح وبين اللطف وحسن الأدب."}]},
  {"id":"g9-arabic-1-u3","grade":"g9","subject":"arabic","term":1,"title":"الوحدة الثالثة: من روائع الشعر والنحو","levels":{"easy":[{"type":"mcq","q":"ما الاسم الحقيقي لأبي الطيب المتنبي؟","options":["أحمد بن الحسين","عمرو بن بحر","سعيد الخراسيني","محمد البوصيري"],"answer":0,"why":"اسمه أبو الطيب أحمد بن الحسين الجعفي."},{"type":"mcq","q":"ماذا تفعل «ظنّ وأخواتها» عند دخولها على الجملة الاسمية؟","options":["ترفع المبتدأ وتنصب الخبر","تنصب المبتدأ مفعولًا أول والخبر مفعولًا ثانيًا","تجرّ الاسمين","تنصب مفعولًا واحدًا فقط"],"answer":1,"why":"ظنّ وأخواتها تنصب مفعولين أصلهما المبتدأ والخبر."},{"type":"mcq","q":"أيُّ كتابةٍ مما يأتي صحيحة لكلمة «سماء» منوّنةً بالفتح؟","options":["سماءًا","سماءً","سمائًا","سماأً"],"answer":1,"why":"لا تقع الهمزة بين ألفين، فنضع التنوين فوقها دون ألف."},{"type":"mcq","q":"ماذا تصبح كلّ فكرة فرعية في المخطّط عند كتابة الموضوع؟","options":["فقرة مستقلة","كلمة واحدة","عنوانًا جديدًا","تُحذف عند الكتابة"],"answer":0,"why":"كل فكرة فرعية تُوسَّع في فقرة مستقلة متماسكة."}],"medium":[{"type":"mcq","q":"لماذا ارتحل المتنبي إلى البادية في شبابه؟","options":["للتجارة فقط","لتعلّم فصاحة اللغة وصفائها","للهروب من القراءة","للزراعة"],"answer":1,"why":"أكسبته البادية فصاحة اللسان وقوة الألفاظ."},{"type":"mcq","q":"ما إعراب «ساطعًا» في جملة: «رأيتُ القمرَ ساطعًا»؟","options":["مفعول به ثانٍ","حال منصوبة","مبتدأ","نعت مرفوع"],"answer":1,"why":"«رأى» هنا بصرية (بالعين) تنصب مفعولًا واحدًا، و«ساطعًا» حال."},{"type":"mcq","q":"لماذا لم نزد ألف التنوين بعد الهمزة في «بِنَاءً»؟","options":["لأنها مرفوعة","لأن الهمزة لا تقع بين ألفين","لأنها همزة وصل","لأنها على واو"],"answer":1,"why":"قبلها ألف مدّ فلا نضع ألفًا ثانية بعدها."},{"type":"tfr","q":"قضى المتنبي تسع سنواتٍ في بلاط سيف الدولة الحمداني في حلب.","answer":true,"reasons":["لأنها كانت أخصب مراحل حياته الشعرية وفيها أبدع السيفيات","لأنه لم يزر حلب أبدًا","لأنه عاش فيها أسبوعًا واحدًا"],"reason":0},{"type":"tfr","q":"إذا حذفنا الفعل والفاعل من «علمتُ الصدقَ منجاةً» بقيت جملة اسمية تامة (الصدقُ منجاةٌ).","answer":true,"reasons":["لأن المفعولين في ظنّ وأخواتها أصلهما المبتدأ والخبر","لأنها تتحول إلى جملة فعلية","لأن المعنى يختلّ تمامًا"],"reason":0}],"hard":[{"type":"mcq","q":"ما دلالة قول المتنبي: «أنا الذي نظرَ الأعمى إلى أدبي»؟","options":["شدة الاعتزاز بشعره وانتشار صيته ووضوحه","التواضع الشديد","الشكوى من الفقر","وصف الطبيعة"],"answer":0,"why":"مبالغة شعرية بليغة تدل على شهرة شعره وقوته واعتداده بنفسه."},{"type":"mcq","q":"ما الجملة الصحيحة نحويًّا بعد إدخال «ظنَّ» على «الطالبانِ مجتهدانِ»؟","options":["ظنَّ المعلمُ الطالبانِ مجتهدانِ","ظنَّ المعلمُ الطالبَينِ مجتهدَينِ","ظنَّ المعلمُ الطالبَينِ مجتهدانِ","ظنَّ المعلمُ الطالبانِ مجتهدَينِ"],"answer":1,"why":"المثنى يُنصب بالياء في المفعولين الأول والثاني."},{"type":"mcq","q":"أيُّ مجموعةٍ مما يأتي كُتبت جميع كلماتها كتابةً إملائيةً صحيحة؟","options":["مساءً، ضوءًا، شيئًا، ملجأً","مساءًا، ضوئًا، شيءًا، ملجأًا","مساءً، ضوئًا، شيئًا، خطأًا","بناءًا، جزءًا، دفئًا، نبأً"],"answer":0,"why":"كل كلمة فيها طبّقت القاعدة بدقة."},{"type":"essay","q":"كيف أثّرت نشأة المتنبي بين الكوفة والبادية في تكوينه الشعري؟","model":"أكسبته الكوفة الثقافة الواسعة وحلقات العلم، وأكسبته البادية فصاحة اللسان وجزالة الألفاظ وصفاء اللغة."},{"type":"essay","q":"فرّق إعرابيًا بين «وجدتُ» في: (١) وجدتُ الصبرَ جميلًا. (٢) وجدتُ المفتاحَ.","model":"في (١) «وجد» قلبية بمعنى علم تنصب مفعولين (الصبرَ، جميلًا). وفي (٢) بمعنى عثر تنصب مفعولًا واحدًا (المفتاحَ)."}]},"test":[{"type":"mcq","q":"ما الاسم الحقيقي لأبي الطيب المتنبي؟","options":["أحمد بن الحسين","عمرو بن بحر","سعيد الخراسيني","محمد البوصيري"],"answer":0,"why":"اسمه أبو الطيب أحمد بن الحسين الجعفي."},{"type":"mcq","q":"ماذا تفعل «ظنّ وأخواتها» عند دخولها على الجملة الاسمية؟","options":["ترفع المبتدأ وتنصب الخبر","تنصب المبتدأ مفعولًا أول والخبر مفعولًا ثانيًا","تجرّ الاسمين","تنصب مفعولًا واحدًا فقط"],"answer":1,"why":"ظنّ وأخواتها تنصب مفعولين أصلهما المبتدأ والخبر."},{"type":"mcq","q":"أيُّ كتابةٍ مما يأتي صحيحة لكلمة «سماء» منوّنةً بالفتح؟","options":["سماءًا","سماءً","سمائًا","سماأً"],"answer":1,"why":"لا تقع الهمزة بين ألفين، فنضع التنوين فوقها دون ألف."},{"type":"mcq","q":"ماذا تصبح كلّ فكرة فرعية في المخطّط عند كتابة الموضوع؟","options":["فقرة مستقلة","كلمة واحدة","عنوانًا جديدًا","تُحذف عند الكتابة"],"answer":0,"why":"كل فكرة فرعية تُوسَّع في فقرة مستقلة متماسكة."},{"type":"mcq","q":"من قائل قصيدة «لوحة الزمن»؟","options":["أبو تمام","أبو الطيب المتنبي","شرف الدين البوصيري","الجاحظ"],"answer":1,"why":"القصيدة من أشهر قصائد الحكمة لأبي الطيب المتنبي."},{"type":"mcq","q":"في أي مدينة وُلد المتنبي؟","options":["حلب","الكوفة","مسقط","القاهرة"],"answer":1,"why":"وُلد في الكوفة بالعراق عام ٣٠٣هـ."},{"type":"mcq","q":"أيُّ الأفعال الآتية من أفعال اليقين؟","options":["ظنَّ","عَلِمَ","جَعَلَ","زَعَمَ"],"answer":1,"why":"عَلِمَ ورأى ووجد وألفى من أفعال اليقين."},{"type":"mcq","q":"كيف تُكتب كلمة «شيء» عند تنوينها بالفتح؟","options":["شيءًا","شيئًا","شيءً","شيأً"],"answer":1,"why":"الياء تتصل بما بعدها فتُكتب الهمزة على نبرة ثم ألف التنوين."},{"type":"mcq","q":"أيُّ عبارةٍ مما يأتي من روابط الانتقال للخاتمة؟","options":["أولًا","وخلاصة القول","لأن","أين"],"answer":1,"why":"«وخلاصة القول» و«وفي الختام» تمهّدان للخاتمة."},{"type":"mcq","q":"ما الغرض الشعري لقصيدة «لوحة الزمن»؟","options":["الحكمة والتأمل في الحياة","الرثاء","المدح النبوي","الوصف الطبيعي"],"answer":0,"why":"تتناول تقلّبات الزمن وأحوال الناس وتدعو للشجاعة وعزّة النفس."},{"type":"mcq","q":"بماذا سُمّيت قصائد المتنبي في بلاط سيف الدولة الحمداني؟","options":["الحمدانيات","السيفيات","المعلقات","البردة"],"answer":1,"why":"سُمّيت السيفيات نسبةً إلى سيف الدولة الحمداني."},{"type":"mcq","q":"أيُّ الأفعال الآتية من أفعال التحويل؟","options":["حَسِبَ","خَالَ","صَيَّرَ","عَلِمَ"],"answer":2,"why":"جعل وصيّر واتخذ وردّ من أفعال التحويل."},{"type":"tf","q":"قضى المتنبي تسع سنواتٍ في بلاط سيف الدولة الحمداني في حلب.","answer":true,"why":"لأنها كانت أخصب مراحل حياته الشعرية وفيها أبدع السيفيات"},{"type":"tf","q":"إذا حذفنا الفعل والفاعل من «علمتُ الصدقَ منجاةً» بقيت جملة اسمية تامة (الصدقُ منجاةٌ).","answer":true,"why":"لأن المفعولين في ظنّ وأخواتها أصلهما المبتدأ والخبر"},{"type":"tf","q":"تُكتب كلمة «هدوء» عند تنوين الفتح «هدوئًا» على نبرة.","answer":false,"why":"لأن الواو لا تتصل بما بعدها فتُكتب «هدوءًا» على السطر مع ألف"},{"type":"tf","q":"يُفضَّل تنويع الأساليب بين الخبر والاستفهام والتعجب لإبعاد الملل عن القارئ.","answer":true,"why":"لأن تنويع الأساليب يُضفي حيوية وتشويقًا على النص"},{"type":"tfr","q":"اقتصر شعر المتنبي على المدح دون أن يتضمّن حِكمًا أو فخرًا.","answer":false,"reasons":["لأن شعره حافل بالحكم والأمثال السائرة والفخر والوصف والمدح","لأن المتنبي لم يكتب الشعر","لأنه كتب في النحو فقط"],"reason":0},{"type":"tfr","q":"الفعل «وَجَدَ» في جملة «وجدَ الطالبُ قلمَهُ» ينصب مفعولين.","answer":false,"reasons":["لأنه بمعنى عثر على شيء ضائع فينصب مفعولًا به واحدًا فقط (قلمَهُ)","لأنه من أفعال التحويل","لأنه فعل لازم"],"reason":0},{"type":"tfr","q":"في تنوين الضم والكسر تبقى صورة الهمزة المتطرفة كما هي دون تغيير.","answer":true,"reasons":["لأن التغيير يرتبط بألف تنوين النصب فقط، فنقول: شيءٌ وشيءٍ","لأن تنوين الضم يضيف ألفًا","لأن الكلمات المنتهية بهمزة لا تُرفع"],"reason":0},{"type":"tfr","q":"يكفي وضع الشاهد في الفقرة دون تمهيد له أو ربطه بالفكرة.","answer":false,"reasons":["لأن الشاهد يجب أن يُمهَّد له ويُربط بالفكرة التي يدعمها ليخدم الإقناع","لأن الشواهد لا علاقة لها بالأفكار","لأن الشواهد تُوضع في العنوان"],"reason":0},{"type":"essay","q":"اذكر ثلاث خصائص فنية لشعر المتنبي.","model":"جزالة الألفاظ وقوتها، وكثرة الحِكم والأمثال السائرة، وعمق المعاني، والاعتزاز بالنفس."},{"type":"essay","q":"أدخل «علمتُ» على جملة «المهندسونَ مبدعونَ» مع تغيير ما يلزم.","model":"علمتُ المهندسينَ مبدعينَ. (نُصبا بالياء لأنهما جمع مذكر سالم)."},{"type":"essay","q":"نوّن الكلمات الآتية بالفتح: عِبْء، مَسَاء، بَدْء، مَلْجَأ.","model":"عِبْئًا، مَسَاءً، بَدْءًا، مَلْجَأً."},{"type":"essay","q":"اذكر أربع أدوات ربط تُستخدم للانتقال بين فقرات الموضوع.","model":"وعلاوةً على ذلك، ومن ناحية أخرى، وبالمقابل، غير أن، وخلاصة القول، وفي الختام."},{"type":"essay","q":"اشرح البيت: «وتعظمُ في عينِ الصغيرِ صغارُها / وتصغرُ في عينِ العظيمِ العظائمُ».","model":"الأمور البسيطة تبدو كبيرةً وصعبةً أمام ضعيف الهمّة، أما صاحب الهمّة العالية فتهون أمامه أعظم الصعاب."}]},
  {"id":"g9-arabic-1-u4","grade":"g9","subject":"arabic","term":1,"title":"الوحدة الرابعة: في رحاب العلم والعمل","levels":{"easy":[{"type":"mcq","q":"من أي سورة استُلهم عنوان درس «قرآن الفجر»؟","options":["الفاتحة","الإسراء","الكهف","يوسف"],"answer":1,"why":"قال تعالى في سورة الإسراء: ﴿إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا﴾."},{"type":"mcq","q":"أيُّ الأفعال الآتية ينصب مفعولين ليس أصلهما المبتدأ والخبر؟","options":["عَلِمَ","وَهَبَ","ظَنَّ","صَيَّرَ"],"answer":1,"why":"وَهَبَ وأعطى ومنح وكسا تنصب مفعولين ليس أصلهما مبتدأ وخبرًا."},{"type":"mcq","q":"لماذا كُتبت الألف مقصورة في «فَتَى»؟","options":["لأنه ثلاثي أصل ألفه ياء","لأنه ثلاثي أصل ألفه واو","لأنه فوق ثلاثي","لأنه اسم أعجمي"],"answer":0,"why":"مثنى فتى هو فتيان، فأصل الألف ياء."},{"type":"mcq","q":"ما المقصود بالتلخيص؟","options":["نسخ النص كما هو","إعادة صياغة الأفكار الرئيسة بإيجاز وبأسلوبك","إطالة النص","ترجمة النص"],"answer":1,"why":"التلخيص يختصر النص في أفكاره الأساسية بأسلوبك الخاص."}],"medium":[{"type":"mcq","q":"لماذا تكون تلاوة القرآن والمذاكرة في الفجر أعمق أثرًا؟","options":["لصفاء الذهن وهدوء الكون وخلوّه من الضجيج","لأن الوقت قصير","لكثرة المشاغل","بسبب السهر"],"answer":0,"why":"يكون العقل مرتاحًا والنفس هادئة مستعدة للتدبر والفهم."},{"type":"mcq","q":"ما إعراب «العافيةَ» في جملة: «أسألُ اللهَ العافيةَ»؟","options":["مفعول به أول","مفعول به ثانٍ منصوب بالفتحة","فاعل","حال"],"answer":1,"why":"سأل هنا تنصب مفعولين: لفظ الجلالة (أول) والعافية (ثانٍ)."},{"type":"mcq","q":"كيف نفرّق إملائيًا بين «يحيى» (اسم شخص) و«يحيا» (الفعل المضارع)؟","options":["الاسم مقصورة والفعل قائمة","كلاهما قائمة","كلاهما مقصورة","الاسم قائمة والفعل مقصورة"],"answer":0,"why":"كُتب العلم «يحيى» مقصورًا للتمييز بينه وبين الفعل «يحيا»."},{"type":"tfr","q":"يقتصر أثر وقت الفجر على الجانب الروحي دون أي أثر في النشاط والعمل.","answer":false,"reasons":["لأنه يمنح بركةً في الوقت ونشاطًا في الجسد وإنجازًا في الدراسة والعمل","لأن العمل ممنوع صباحًا","لأن الفجر وقت النوم"],"reason":0},{"type":"tfr","q":"عند بناء «أعطى الغنيُّ الفقيرَ صدقةً» للمجهول تصبح: «أُعْطِيَ الفقيرُ صدقةً».","answer":true,"reasons":["لأن المفعول الأول يصبح نائب فاعل مرفوعًا ويبقى الثاني منصوبًا","لأن المفعولين يُرفعان معًا","لأن الفعل لا يُبنى للمجهول"],"reason":0}],"hard":[{"type":"mcq","q":"ما دلالة تشبيه الكون عند الفجر بـ «محرابٍ هادئ»؟","options":["إيحاء بالخشوع والسكينة وقدسية اللحظة","وصف لبناء قديم","كثرة الضجيج","حرارة الجو"],"answer":0,"why":"المحراب موضع العبادة والسكينة، والتشبيه يبرز صفاء اللحظة وخشوعها."},{"type":"mcq","q":"أيُّ جملةٍ مما يأتي فيها فعلان ينصب أحدهما مفعولين أصلهما مبتدأ وخبر، والآخر ليس أصلهما؟","options":["علمتُ الصدقَ نافعًا وأعطيتُ الفقيرَ مالًا","قرأتُ كتابًا وكتبتُ درسًا","نام الطفلُ وصحا","كان الجوُّ جميلًا"],"answer":0,"why":"«علمتُ» من أخوات ظن، و«أعطيتُ» من أخوات أعطى."},{"type":"mcq","q":"ما أصل الألف في «ذُرَا» (جمع ذروة) وكيف تُكتب؟","options":["أصلها واو فتُكتب قائمة (ذُرا)","أصلها ياء فتُكتب مقصورة (ذُرى)","فوق ثلاثي","اسم أعجمي"],"answer":0,"why":"مفردها ذروة فأصلها واو وتُكتب قائمة."},{"type":"essay","q":"كيف توفّق كطالب بين الاستفادة من وقت الفجر وبين جدول مذاكرتك اليومي؟","model":"أنظم نومي مبكرًا، وأستيقظ لصلاة الفجر وتلاوة ورد قصير من القرآن، ثم أستثمر هدوء الصباح في مراجعة أهم الدروس بتركيز عالٍ."},{"type":"essay","q":"اشرح كيف تميّز عمليًا بين مفعولَي «ظنّ وأخواتها» ومفعولَي «أعطى وأخواتها».","model":"بحذف الفعل والفاعل؛ فإن تكوّنت جملة اسمية مفيدة من مبتدأ وخبر فهما من أخوات ظن، وإن لم تتكوّن فهما من أخوات أعطى."}]},"test":[{"type":"mcq","q":"من أي سورة استُلهم عنوان درس «قرآن الفجر»؟","options":["الفاتحة","الإسراء","الكهف","يوسف"],"answer":1,"why":"قال تعالى في سورة الإسراء: ﴿إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا﴾."},{"type":"mcq","q":"أيُّ الأفعال الآتية ينصب مفعولين ليس أصلهما المبتدأ والخبر؟","options":["عَلِمَ","وَهَبَ","ظَنَّ","صَيَّرَ"],"answer":1,"why":"وَهَبَ وأعطى ومنح وكسا تنصب مفعولين ليس أصلهما مبتدأ وخبرًا."},{"type":"mcq","q":"لماذا كُتبت الألف مقصورة في «فَتَى»؟","options":["لأنه ثلاثي أصل ألفه ياء","لأنه ثلاثي أصل ألفه واو","لأنه فوق ثلاثي","لأنه اسم أعجمي"],"answer":0,"why":"مثنى فتى هو فتيان، فأصل الألف ياء."},{"type":"mcq","q":"ما المقصود بالتلخيص؟","options":["نسخ النص كما هو","إعادة صياغة الأفكار الرئيسة بإيجاز وبأسلوبك","إطالة النص","ترجمة النص"],"answer":1,"why":"التلخيص يختصر النص في أفكاره الأساسية بأسلوبك الخاص."},{"type":"mcq","q":"ما معنى كلمة «الصَّنَاع» في اللغة العربية؟","options":["الماهرة المتقِنة لعمل يديها","الكسولة","الكثيرة السفر","البائعة فقط"],"answer":0,"why":"الصَّنَاع صفة تدل على البراعة والحذق في الصنعة."},{"type":"mcq","q":"لماذا يُعدّ العلم خيرًا من المال؟","options":["لأن العلم يحرسك وأنت تحرس المال","لأن المال لا ينقص أبدًا","لأن العلم ينقص بالإنفاق","لأن المال يبقى بعد الموت"],"answer":0,"why":"العلم يحفظ صاحبه ويزداد بالتعليم بخلاف المال."},{"type":"mcq","q":"من الذين يشهدون قرآن الفجر؟","options":["ملائكة الليل والنهار","الشعراء فقط","التجار","المسافرون"],"answer":0,"why":"تلتقي ملائكة الليل وملائكة النهار عند صلاة الفجر."},{"type":"mcq","q":"أين المفعول به الأول في: «منحَ المعلمُ الطالبَ جائزةً»؟","options":["المعلمُ","الطالبَ","جائزةً","منحَ"],"answer":1,"why":"المعلم فاعل، والطالب مفعول به أول، وجائزة مفعول به ثانٍ."},{"type":"mcq","q":"كيف تُكتب كلمة «مستشفـ...»؟","options":["مستشفا","مستشفى","مستشفئ","مستشفي"],"answer":1,"why":"اسم فوق ثلاثي لم تسبق ألفه ياء فتُكتب مقصورة."},{"type":"mcq","q":"كم يبلغ حجم الملخّص الجيّد عادةً؟","options":["ضعف الأصل","بين رُبع النص الأصلي وثُلثه","نفس عدد الكلمات","كلمة واحدة"],"answer":1,"why":"يتراوح الملخّص الجيّد بين ربع الأصل وثلثه."},{"type":"mcq","q":"ما القيمة الكبرى التي يبرزها نص «مريم الصناع»؟","options":["إتقان العمل والاعتماد على النفس","الاعتماد على الآخرين","تضييع الوقت","الافتخار بالمال فقط"],"answer":0,"why":"النص يحتفي بالعمل الشريف وإتقانه وكرامة الإنسان العامل."},{"type":"mcq","q":"ما أول كلمة نزلت في القرآن الكريم دلالةً على مكانة العلم؟","options":["اكتب","اقرأ","سافر","اعمل"],"answer":1,"why":"أول ما نزل من القرآن قوله تعالى: ﴿اقْرَأْ بِاسْمِ رَبِّكَ﴾."},{"type":"tf","q":"يقتصر أثر وقت الفجر على الجانب الروحي دون أي أثر في النشاط والعمل.","answer":false,"why":"لأنه يمنح بركةً في الوقت ونشاطًا في الجسد وإنجازًا في الدراسة والعمل"},{"type":"tf","q":"عند بناء «أعطى الغنيُّ الفقيرَ صدقةً» للمجهول تصبح: «أُعْطِيَ الفقيرُ صدقةً».","answer":true,"why":"لأن المفعول الأول يصبح نائب فاعل مرفوعًا ويبقى الثاني منصوبًا"},{"type":"tf","q":"تُكتب ألف الاسم الثلاثي «قُرَى» مقصورة لأن مفردها «قرية» فأصل الألف ياء.","answer":true,"why":"لأن ردّ الجمع إلى المفرد يكشف أصل الألف (قرية = ياء)"},{"type":"tf","q":"التلخيص يعني نسخ جمل متفرقة من النص الأصلي ولصقها معًا.","answer":false,"why":"لأن التلخيص يتطلب إعادة صياغة الأفكار بأسلوبك الخاص وربطها بتماسك"},{"type":"tfr","q":"توظيف الصور الحسية (النور والنسيم وصوت التلاوة) يقرّب مشاعر النص إلى القارئ.","answer":true,"reasons":["لأنها تخاطب البصر والسمع والشعور فتجعل القارئ يعيش أجواء الفجر","لأنها تُضعف الأسلوب","لأنها تُستخدم في الشعر فقط"],"reason":0},{"type":"tfr","q":"الفعل «مَنَعَ» ينصب مفعولين أصلهما المبتدأ والخبر.","answer":false,"reasons":["لأنه ينصب مفعولين ليس أصلهما المبتدأ والخبر، مثل: منعتُ المهملَ الجائزةَ","لأنه فعل لازم","لأنه من أخوات كان"],"reason":0},{"type":"tfr","q":"جميع الأسماء المبنية المنتهية بألف تُكتب مقصورة.","answer":false,"reasons":["لأن الأصل فيها أن تُكتب قائمة (أنا، هذا) ما عدا أربعة (متى، لدى، أنّى، الأُلى)","لأنها لا تنتهي بألف","لأنها تُكتب بالتاء"],"reason":0},{"type":"tfr","q":"تُحذف الجمل الاعتراضية والمترادفات المكررة عند التلخيص.","answer":true,"reasons":["لأن حذفها يختصر النص دون الإخلال بالأفكار الأساسية","لأنها هي الأفكار الرئيسة","لأنها تُطيل الملخّص"],"reason":0},{"type":"essay","q":"صف مظهرين من مظاهر جمال الطبيعة عند انبلاج الفجر كما وردت في الدرس.","model":"تسلّل خيوط النور الأولى وسط الظلام، وهبوب النسيم النقي العليل، وسكون الكون واستعداد الطيور للطيران."},{"type":"essay","q":"أعرب: «وهبَ اللهُ الإنسانَ عقلًا».","model":"وهبَ: فعل ماضٍ. اللهُ: لفظ الجلالة فاعل مرفوع. الإنسانَ: مفعول به أول منصوب بالفتحة. عقلًا: مفعول به ثانٍ منصوب بالفتحة."},{"type":"essay","q":"علّل رسم الألف في أواخر الأسماء الآتية: رُبَا، هُدَى، مُنْتَدَى، قَضَايَا.","model":"ربا: ثلاثي أصلها واو (ربوة). هدى: ثلاثي أصلها ياء (يهدي). منتدى: فوق ثلاثي بلا ياء قبله. قضايا: فوق ثلاثي قبلها ياء."},{"type":"essay","q":"اذكر خطوات التلخيص الخمس بالترتيب.","model":"١) القراءة الفاحصة. ٢) تحديد الأفكار الرئيسة. ٣) حذف التكرار والشواهد والزوائد. ٤) الصياغة بأسلوبك الخاص وربط الجمل. ٥) المراجعة والمقارنة بالأصل."},{"type":"essay","q":"اذكر أربع قيم إيجابية نتعلّمها من شخصية مريم الصناع.","model":"إتقان العمل، والاعتماد على النفس، والصبر والمثابرة، والأمانة، وخدمة الأسرة والمجتمع."}]},
  {"id":"g9-arabic-1-u5","grade":"g9","subject":"arabic","term":1,"title":"الوحدة الخامسة: القصة القرآنية والرثاء","levels":{"easy":[{"type":"mcq","q":"ما الغاية الكبرى من القصة في القرآن الكريم؟","options":["التسلية فقط","الهداية والعظة وتثبيت القلوب","الخيال الأدبي","جمع الأخبار فقط"],"answer":1,"why":"تهدف القصة القرآنية إلى الهداية والاعتبار وتثبيت الإيمان."},{"type":"mcq","q":"أيُّ الكلمات الآتية كُتبت خطأً؟","options":["شاطئ","سماءً","هدايى","جزءًا"],"answer":2,"why":"الصواب «هدايا» بألف قائمة لأنها فوق ثلاثي وسبقت ألفها ياء."},{"type":"mcq","q":"كيف نتعامل مع موضوع طويل متعدّد الفقرات عند تلخيصه؟","options":["نلخّص الفقرة الأولى فقط","نستخرج فكرة كل فقرة في جملة ثم ندمجها","نحذف الفقرات الأخيرة","ننسخ النص كاملًا"],"answer":1,"why":"تقسيم الموضوع إلى فقرات واستخراج فكرة كل فقرة يضمن شمول الملخّص."},{"type":"mcq","q":"من قائل قصيدة «يا كوكبًا ما كان أقصر عمره»؟","options":["أبو الطيب المتنبي","أبو الحسن التهامي","أبو تمام","البوصيري"],"answer":1,"why":"قالها أبو الحسن التهامي في رثاء ابنه الصغير."}],"medium":[{"type":"mcq","q":"لماذا لم يذكر القرآن تفاصيل مثل لون كلب أهل الكهف؟","options":["لأن التركيز على العبرة والإيمان لا على التفاصيل غير المؤثرة","لأنه نسيها","لأن القصة قصيرة","لعدم وجود كلب"],"answer":0,"why":"من خصائص القصة القرآنية الإيجاز والتركيز على موضع العبرة."},{"type":"mcq","q":"أيُّ جملةٍ مما يأتي خالية تمامًا من الأخطاء الإملائية؟","options":["قدّم يحيى هدايا رائعةً مساءً.","قدّم يحيا هدايى رائعةً مساءًا.","قدّم يحيى هدايا رائعةً مساءًا.","قدّم يحيا هدايا رائعةً مساءً."],"answer":0,"why":"يحيى (علم مقصورة)، هدايا (قبلها ياء)، مساءً (بلا ألف ثانية)."},{"type":"mcq","q":"ما فائدة ترقيم الفقرات وكتابة جملة موجزة في الهامش لكل فقرة؟","options":["تسهيل السيطرة على الموضوع وعدم سقوط أي فكرة رئيسة","إطالة وقت التلخيص","إضافة أفكار خارجية","حذف العنوان"],"answer":0,"why":"هذه الطريقة المنظمة تضمن تلخيصًا شاملًا ومتوازنًا."},{"type":"tfr","q":"تكرار قصة موسى عليه السلام في عدة سور يُعدّ تكرارًا حرفيًا بلا فائدة جديدة.","answer":false,"reasons":["لأن كل موضع يعرض زاوية جديدة بأسلوب يناسب موضوع السورة وسياقها","لأنها لم ترد إلا مرة واحدة","لأن التكرار للزينة فقط"],"reason":0},{"type":"tfr","q":"تُكتب «عُلا» بألف قائمة لأن أصل ألفها واو (من العلوّ).","answer":true,"reasons":["لأن الاسم الثلاثي الذي أصل ألفه واو تُكتب ألفه قائمة","لأنها فوق ثلاثي","لأنها اسم أعجمي"],"reason":0}],"hard":[{"type":"mcq","q":"ما دلالة تنوّع الأسلوب عند تكرار القصة القرآنية في أكثر من سورة؟","options":["إعجاز القرآن البياني وملاءمة كل عرض لسياق السورة","اختلاف الوقائع","ضعف الترابط","نقص المعلومات"],"answer":0,"why":"يُظهر الإعجاز البلاغي للقرآن وتوظيف القصة لخدمة هدف كل سورة."},{"type":"mcq","q":"أيُّ مجموعةٍ مما يأتي كلها صحيحة إملائيًا؟","options":["دِفئًا، بَدءًا، مَبْدأً، مَساءً","دِفءًا، بَدئًا، مَبْدأًا، مَساءًا","دِفئًا، بَدئًا، مَبْدأً، مَساءً","دِفءًا، بَدءًا، مَبْدأً، مَساءًا"],"answer":0,"why":"كل كلمة فيها طبّقت قاعدة تنوين الهمزة المتطرفة بدقة."},{"type":"mcq","q":"ما العيب في ملخّصٍ جُمعت فيه الجمل المفتاحية لكل فقرة كما هي دون روابط؟","options":["يبدو مفكّكًا ومنسوخًا لا متماسكًا بأسلوب الطالب","يكون طويلًا جدًا","يخلو من الأفكار","يكون خياليًا"],"answer":0,"why":"لا بد من إعادة الصياغة والربط اللغوي ليصبح نصًا متماسكًا."},{"type":"essay","q":"قارن بين القصة القرآنية والقصة الأدبية من حيث: المصدر، والواقعية، والهدف.","model":"القصة القرآنية مصدرها الوحي، وواقعيتها صادقة مطلقة، وهدفها الهداية والعظة. أما القصة الأدبية فمصدرها الإنسان، وقد تعتمد على الخيال، وهدفها المتعة الأدبية أو الفكرة الاجتماعية."},{"type":"essay","q":"صوّب جميع الأخطاء الإملائية في الفقرة: «ذهب مصطفا وعيسا إلى القرا، وحملا عصى طويلةً، وتأملا سماءًا مليئةً بالنجوم».","model":"ذهب مصطفى وعيسى إلى القرى، وحملا عصا طويلةً، وتأملا سماءً مليئةً بالنجوم."}]},"test":[{"type":"mcq","q":"ما الغاية الكبرى من القصة في القرآن الكريم؟","options":["التسلية فقط","الهداية والعظة وتثبيت القلوب","الخيال الأدبي","جمع الأخبار فقط"],"answer":1,"why":"تهدف القصة القرآنية إلى الهداية والاعتبار وتثبيت الإيمان."},{"type":"mcq","q":"أيُّ الكلمات الآتية كُتبت خطأً؟","options":["شاطئ","سماءً","هدايى","جزءًا"],"answer":2,"why":"الصواب «هدايا» بألف قائمة لأنها فوق ثلاثي وسبقت ألفها ياء."},{"type":"mcq","q":"كيف نتعامل مع موضوع طويل متعدّد الفقرات عند تلخيصه؟","options":["نلخّص الفقرة الأولى فقط","نستخرج فكرة كل فقرة في جملة ثم ندمجها","نحذف الفقرات الأخيرة","ننسخ النص كاملًا"],"answer":1,"why":"تقسيم الموضوع إلى فقرات واستخراج فكرة كل فقرة يضمن شمول الملخّص."},{"type":"mcq","q":"من قائل قصيدة «يا كوكبًا ما كان أقصر عمره»؟","options":["أبو الطيب المتنبي","أبو الحسن التهامي","أبو تمام","البوصيري"],"answer":1,"why":"قالها أبو الحسن التهامي في رثاء ابنه الصغير."},{"type":"mcq","q":"بماذا تمتاز القصة القرآنية عن القصص الأدبية الخيالية؟","options":["بالصدق الواقعي التام","بكثرة الخيال","بإهمال العبرة","بالغموض"],"answer":0,"why":"أحداثها حقائق واقعية وليست من نسج الخيال."},{"type":"mcq","q":"ما الصواب عند تنوين «مَلْجَأ» بالفتح؟","options":["ملجأً","ملجأًا","ملجئًا","ملجءًا"],"answer":0,"why":"الهمزة فوق ألف فلا نزيد ألفًا ثانية."},{"type":"mcq","q":"ما الذي يجعل جمل الملخّص مترابطة وسلسة بعد دمجها؟","options":["أدوات الربط وعلامات الترقيم","تكرار الكلمات","كتابة جمل عامية","ترك النص بلا فواصل"],"answer":0,"why":"الروابط مثل (لذلك، كما أن، ومن ثمّ) تدمج الجمل في نسيج واحد."},{"type":"mcq","q":"ما الغرض الشعري لقصيدة «يا كوكبًا ما كان أقصر عمره»؟","options":["الفخر","الرثاء","الوصف","المدح"],"answer":1,"why":"رثى فيها ابنه الذي توفي صغيرًا."},{"type":"mcq","q":"أيٌّ مما يأتي مثال على «قصص الصالحين» في القرآن؟","options":["أصحاب الكهف","غزوة بدر","قصة فرعون","قارون"],"answer":0,"why":"أصحاب الكهف نموذج للشباب المؤمن الصالح."},{"type":"mcq","q":"ما الصواب في كتابة اسم الشخص «يحيى»؟","options":["يحيى","يحيا","يحيأ","يحيء"],"answer":0,"why":"العلم يحيى يُكتب مقصورًا ليمتاز عن الفعل يحيا."},{"type":"mcq","q":"ماذا نفعل بالأمثلة والإحصاءات التفصيلية في كل فقرة؟","options":["نحذفها ونبقي الفكرة الرئيسة","ننسخها كلها","نضعها في العنوان","نكرّرها مرتين"],"answer":0,"why":"التلخيص يحتفظ بالأفكار الأساسية ويحذف التفاصيل الفرعية."},{"type":"mcq","q":"ما المقصود بـ «الأسحار» في البيت الأول؟","options":["أوقات آخر الليل قبيل الفجر","أوقات الظهيرة","فصل الصيف","النجوم البعيدة"],"answer":0,"why":"الأسحار جمع سَحَر وهو الوقت الذي يسبق الفجر."},{"type":"tf","q":"تكرار قصة موسى عليه السلام في عدة سور يُعدّ تكرارًا حرفيًا بلا فائدة جديدة.","answer":false,"why":"لأن كل موضع يعرض زاوية جديدة بأسلوب يناسب موضوع السورة وسياقها"},{"type":"tf","q":"تُكتب «عُلا» بألف قائمة لأن أصل ألفها واو (من العلوّ).","answer":true,"why":"لأن الاسم الثلاثي الذي أصل ألفه واو تُكتب ألفه قائمة"},{"type":"tf","q":"يمكن دمج أفكار ثلاث فقرات قصيرة في فقرة واحدة متماسكة عند التلخيص.","answer":true,"why":"لأن التلخيص يوجز الموضوع ويجمع أفكاره المتقاربة بسلاسة"},{"type":"tf","q":"النداء في «يا كوكبًا» غرضه التحسّر والألم على فقد الابن.","answer":true,"why":"لأن الشاعر ينادي ابنه المتوفى بقلب مفجوع متحسّر"},{"type":"tfr","q":"يؤدّي الحوار في القصة القرآنية دورًا مهمًا في كشف نفسيات الشخصيات ومواقفها.","answer":true,"reasons":["لأن الحوار ينقل الصراع بين الحق والباطل بحيوية وإقناع كما في حوار موسى وفرعون","لأن القصة القرآنية تخلو من الحوار","لأن الحوار للخيال فقط"],"reason":0},{"type":"tfr","q":"في كلمة «عِبْئًا» تُكتب الهمزة على نبرة لأن الباء تتصل بألف التنوين.","answer":true,"reasons":["لأن الحرف الساكن قبل الهمزة يتصل بما بعده فتُكتب على نبرة","لأن الباء لا تتصل","لأن قبلها ألفًا"],"reason":0},{"type":"tfr","q":"إذا كان النص الأصلي صفحتين، فإن ملخّصه المناسب يكون حوالي نصف صفحة.","answer":true,"reasons":["لأن حجم الملخّص الجيّد يتراوح بين ربع الأصل وثلثه (حوالي نصف صفحة من صفحتين)","لأن الملخّص يجب أن يكون صفحتين","لأن الملخّص كلمة واحدة"],"reason":0},{"type":"tfr","q":"خلت قصيدة التهامي من الحكمة والتأمّل في حقيقة الدنيا والموت.","answer":false,"reasons":["لأن الشاعر ارتقى بحزنه إلى التأمل والحكمة فبيّن أن الدنيا دار فناء والجميع عابرون","لأنها قصيدة مدح","لأنها تتحدث عن السفر فقط"],"reason":0},{"type":"essay","q":"اذكر ثلاث خصائص فنية للقصة في القرآن الكريم.","model":"الصدق الواقعي، وجمال التصوير الفني الحي، وقوة الحوار الكاشف للشخصيات، والإيجاز والتركيز على العبرة."},{"type":"essay","q":"صوّب الأخطاء الإملائية في الجملة: «قرأ الفتا جزءً من القصة في الميناءِ بهدوئٍ».","model":"قرأ الفتى جزءًا من القصة في الميناءِ بهدوءٍ. (الفتى، جزءًا، بهدوءٍ)."},{"type":"essay","q":"لخّص الأفكار الثلاث الآتية في جملتين مترابطتين: ١) القراءة غذاء العقل. ٢) المكتبة توفّر كتبًا متنوعة. ٣) يجب تخصيص وقت يومي للمطالعة.","model":"القراءة غذاء العقل، وتوفّر المكتبة كتبًا متنوعة لتنميتها؛ لذلك ينبغي تخصيص وقت يومي للمطالعة."},{"type":"essay","q":"اشرح صورة تشبيه الابن بـ «الهلال» كما وردت في القصيدة.","model":"شبّه الشاعر ابنه الصغير بالهلال الذي ينتظر الناس اكتماله بدرًا، لكن الموت عاجله قبل أن يبلغ تمام شبابه وعطائه."},{"type":"essay","q":"اذكر الأنواع الثلاثة الرئيسة للقصص في القرآن الكريم مع مثال لكل نوع.","model":"١) قصص الأنبياء (يوسف وموسى). ٢) قصص الصالحين (أصحاب الكهف ومريم). ٣) أحداث السيرة النبوية (غزوة بدر وأحد)."}]},
  {"id":"g9-arabic-1-u6","grade":"g9","subject":"arabic","term":1,"title":"الوحدة السادسة: السيرة والعلم والأدب","levels":{"easy":[{"type":"mcq","q":"ما المقصود بالسيرة الذاتية؟","options":["نص يكتب فيه الكاتب قصة حياته بنفسه","نص يكتبه مؤلف عن شخص آخر","قصيدة مدح","معجم لغوي"],"answer":0,"why":"السيرة الذاتية هي سيرة بقلم صاحبها."},{"type":"mcq","q":"كيف يُكتب الفعل الماضي من «يَنْمُو»؟","options":["نَمَا","نَمَى","نَمَأ","نَمَء"],"answer":0,"why":"أصل الألف واو (ينمو، نموتُ) فتُكتب قائمة."},{"type":"mcq","q":"ما العلم الذي يدرس بقايا الحضارات القديمة لفهم تاريخ الإنسان؟","options":["علم الفلك","علم الآثار","علم النبات","علم الصرف"],"answer":1,"why":"علم الآثار يدرس المخلفات المادية للحضارات القديمة."},{"type":"mcq","q":"من قائل بيت: «ألم تغتمض عيناك ليلة أرمدا»؟","options":["المتنبي","الأعشى (ميمون بن قيس)","البوصيري","التهامي"],"answer":1,"why":"هو الشاعر الجاهلي ميمون بن قيس المعروف بالأعشى."}],"medium":[{"type":"mcq","q":"ما الفرق الجوهري بين السيرة الذاتية والسيرة الغيرية؟","options":["الذاتية يكتبها الشخص عن نفسه والغيرية يكتبها غيره عنه","الذاتية شعر والغيرية نثر","الذاتية قصيرة دائمًا","لا يوجد فرق"],"answer":0,"why":"في الذاتية الكاتب هو البطل، وفي الغيرية المؤلف يكتب عن شخصية أخرى."},{"type":"mcq","q":"أيُّ اختبارٍ يكشف أصل الألف في الفعل «سَعَى» بدقة؟","options":["إسناده لتاء الفاعل: سَعَيْتُ","مضارعه: يَسْعَى","الأمر منه: اسْعَ","عدّ حروفه"],"answer":0,"why":"في المضارع تبقى ألفًا، أما مع تاء الفاعل «سعيتُ» فتظهر الياء بوضوح."},{"type":"mcq","q":"كيف تختلف طريقة التنقيب حديثًا عن الماضي؟","options":["حديثًا توفّر الأقمار الصناعية الوقت والجهد وتحدّد المواقع بدقة قبل الحفر","قديمًا كانت أسرع","لا يوجد أي فرق","حديثًا لا يوجد حفر أبدًا"],"answer":0,"why":"تختصر التقنية الفضائية سنوات من البحث العشوائي."},{"type":"tfr","q":"تُعدّ السيرة الذاتية وثيقةً اجتماعيةً وتاريخيةً تعكس ملامح عصر الكاتب.","answer":true,"reasons":["لأنها تصف العادات والمدارس والحياة اليومية في الزمن الذي عاش فيه الكاتب","لأنها لا تذكر أي أماكن","لأنها خيالية بالكامل"],"reason":0},{"type":"tfr","q":"تُكتب الألف في الفعل «رَمَى» مقصورة، فإذا اتصل به ضمير تصبح قائمة: «رَمَاهُ».","answer":true,"reasons":["لأن الألف تصبح متوسطة وليست متطرفة فتُكتب قائمة","لأن أصلها واو","لأن الضمير يحذف الألف"],"reason":0}],"hard":[{"type":"mcq","q":"لماذا يتعاطف القارئ مع السيرة الذاتية الصادقة أكثر من غيرها؟","options":["لأنها تكشف الجانب الإنساني الحقيقي للتحديات والنجاح بلا تصنّع","لأنها مليئة بالمبالغات","لأنها قصيرة جدًا","لأنها تخلو من المشاعر"],"answer":0,"why":"الصدق الإنساني يلامس القارئ ويشعره بقرب التجربة."},{"type":"mcq","q":"ما الصواب في: «........ اللهُ الأرضَ بالمطرِ، و........ المؤمنُ إلى الخيرِ»؟","options":["أحيا / سعى","أحيى / سعا","أحيا / سعا","أحيى / سعى"],"answer":0,"why":"أحيا (فوق ثلاثي قبلها ياء ← ا)، سعى (ثلاثي سعيتُ ← ى)."},{"type":"mcq","q":"لماذا كان اكتشاف الآثار في الصحاري الشاسعة صعبًا جدًا قبل عصر الفضاء؟","options":["لاتساع المساحات وتغطية الرمال المتحركة للمعالم القديمة","لعدم وجود آثار في الصحاري","لكثرة الأنهار فيها","لصغر مساحتها"],"answer":0,"why":"الرمال الشاسعة تخفي المعالم ويصعب مسحها يدويًا."},{"type":"essay","q":"ما الفوائد التي يجنيها طالب الصف التاسع من قراءة السير الذاتية للعلماء والأدباء؟","model":"يتعلّم منهم الصبر والمثابرة، ويستفيد من تجاربهم في التغلب على الصعاب، ويتعرّف تاريخ مجتمعهم وثقافته، ويستلهم القدوة الحسنة."},{"type":"essay","q":"فرّق بين رسم «عَصَا» و«عَصَى» مع ذكر نوع كل كلمة وسبب كتابة الألف.","model":"«عَصَا» اسم ثلاثي أصل ألفه واو (عصوان) فتُكتب قائمة. «عَصَى» فعل ثلاثي أصل ألفه ياء (يعصي) فتُكتب مقصورة."}]},"test":[{"type":"mcq","q":"ما المقصود بالسيرة الذاتية؟","options":["نص يكتب فيه الكاتب قصة حياته بنفسه","نص يكتبه مؤلف عن شخص آخر","قصيدة مدح","معجم لغوي"],"answer":0,"why":"السيرة الذاتية هي سيرة بقلم صاحبها."},{"type":"mcq","q":"كيف يُكتب الفعل الماضي من «يَنْمُو»؟","options":["نَمَا","نَمَى","نَمَأ","نَمَء"],"answer":0,"why":"أصل الألف واو (ينمو، نموتُ) فتُكتب قائمة."},{"type":"mcq","q":"ما العلم الذي يدرس بقايا الحضارات القديمة لفهم تاريخ الإنسان؟","options":["علم الفلك","علم الآثار","علم النبات","علم الصرف"],"answer":1,"why":"علم الآثار يدرس المخلفات المادية للحضارات القديمة."},{"type":"mcq","q":"من قائل بيت: «ألم تغتمض عيناك ليلة أرمدا»؟","options":["المتنبي","الأعشى (ميمون بن قيس)","البوصيري","التهامي"],"answer":1,"why":"هو الشاعر الجاهلي ميمون بن قيس المعروف بالأعشى."},{"type":"mcq","q":"ما الضمير الغالب استخدامه في السيرة الذاتية؟","options":["ضمير المتكلم (أنا)","ضمير الغائب (هو)","ضمير المخاطب (أنت)","ضمير الغائبين (هم)"],"answer":0,"why":"لأن الكاتب يروي أحداث حياته بنفسه."},{"type":"mcq","q":"كيف يُكتب الفعل الماضي من «يَبْنِي»؟","options":["بَنَا","بَنَى","بَنَأ","بَنَء"],"answer":1,"why":"أصل الألف ياء (يبني، بنيتُ) فتُكتب مقصورة."},{"type":"mcq","q":"ما التقنية التي تستخدمها الأقمار الصناعية لرصد المعالم المدفونة؟","options":["الاستشعار عن بُعد","الحفر اليدوي","المجهر فقط","الرسم اليدوي"],"answer":0,"why":"الاستشعار عن بُعد يكشف ما تحت الرمال والغابات من الفضاء."},{"type":"mcq","q":"بماذا لُقّب الأعشى في تاريخ الأدب العربي؟","options":["صنّاجة العرب","أمير النثر","شيخ النحاة","الجاحظ"],"answer":0,"why":"لُقّب بصناجة العرب لجودة إيقاعه وموسيقى شعره."},{"type":"mcq","q":"من مؤلّف السيرة الذاتية الشهيرة «الأيام»؟","options":["الجاحظ","طه حسين","المتنبي","البوصيري"],"answer":1,"why":"كتب الأديب طه حسين سيرته الذاتية الشهيرة «الأيام»."},{"type":"mcq","q":"كيف يُكتب الفعل «اسْتَدْعـ...»؟","options":["استدعا","استدعى","استدعئ","استدعي"],"answer":1,"why":"فعل سداسي (فوق ثلاثي) لم تسبق ألفه ياء فتُكتب مقصورة."},{"type":"mcq","q":"ماذا ساعدت صور الأقمار الصناعية على تتبّعه في الجزيرة العربية؟","options":["طرق قوافل اللبان والمدن المدفونة","أعماق المحيط المتجمد","الجبال الجليدية","القطارات الحديثة"],"answer":0,"why":"كشفت مسارات طرق التجارة القديمة ومواقع مدفونة تحت الرمال."},{"type":"mcq","q":"ما المقصود بـ «السليم» في قول الأعشى «كما بات السليم مسهدا»؟","options":["اللديغ (من باب التفاؤل)","المعافى تمامًا","الطفل الصغير","المسافر"],"answer":0,"why":"تطلق العرب لفظ السليم على اللديغ تفاؤلًا بنجاته وسلامته."},{"type":"tf","q":"تُعدّ السيرة الذاتية وثيقةً اجتماعيةً وتاريخيةً تعكس ملامح عصر الكاتب.","answer":true,"why":"لأنها تصف العادات والمدارس والحياة اليومية في الزمن الذي عاش فيه الكاتب"},{"type":"tf","q":"تُكتب الألف في الفعل «رَمَى» مقصورة، فإذا اتصل به ضمير تصبح قائمة: «رَمَاهُ».","answer":true,"why":"لأن الألف تصبح متوسطة وليست متطرفة فتُكتب قائمة"},{"type":"tf","q":"تستطيع الرادارات الفضائية والأشعة تحت الحمراء رصد أساسات مبانٍ مدفونة تحت الرمال.","answer":true,"why":"لأنها تلتقط فروقًا دقيقة في التربة وطبقات الأرض لا تراها العين المجردة"},{"type":"tf","q":"لُقّب الأعشى بـ «صنّاجة العرب» لعذوبة موسيقى شعره وحسن إيقاعه.","answer":true,"why":"لأن المغنّين كانوا يتغنّون بأشعاره لتناغم ألفاظها وسلاسة أوزانها"},{"type":"tfr","q":"ينبغي لكاتب السيرة الذاتية أن يذكر نجاحاته فقط ويُخفي كل إخفاقاته وتحدياته.","answer":false,"reasons":["لأن ذكر التحديات والإخفاقات وكيف تغلّب عليها يمنح السيرة صدقًا وفائدة تربوية","لأن التحديات لا تهم القارئ","لأن السيرة للمبالغة فقط"],"reason":0},{"type":"tfr","q":"الفعل «أَعْطَى» كُتبت ألفه مقصورة لأن أصلها ياء.","answer":false,"reasons":["لأنه فعل رباعي (فوق ثلاثي) لم تسبق ألفه ياء، فلا نبحث عن أصل الألف في غير الثلاثي","لأنه ثلاثي واوي","لأن قبله ياء"],"reason":0},{"type":"tfr","q":"أغنت الأقمار الصناعية تمامًا عن عمل علماء الآثار على الأرض.","answer":false,"reasons":["لأن القمر الصناعي يحدّد الموقع، ثم ينزل العلماء للتنقيب الدقيق ودراسة اللقى الأثرية","لأن الأقمار تحفر الأرض بنفسها","لأن الآثار موجودة في الفضاء"],"reason":0},{"type":"tfr","q":"يُسمّى خطاب الشاعر لنفسه كأنها شخص آخر في البلاغة «التجريد».","answer":true,"reasons":["لأن الشاعر ينتزع من نفسه شخصًا آخر يخاطبه بـ «عيناك» و«بتَّ» لتنفيس همّه","لأنه يُسمّى طباقًا","لأنه خطأ نحوي"],"reason":0},{"type":"essay","q":"اذكر ثلاثة أهداف لكتابة السيرة الذاتية.","model":"١) نقل الخبرات والتجارب للأجيال. ٢) توثيق مرحلة تاريخية واجتماعية. ٣) التعبير عن الوفاء والامتنان لمن أثّروا في حياة الكاتب."},{"type":"essay","q":"علّل رسم الألف في الأفعال الآتية: نَجَا، قَضَى، اهْتَدَى، أَحْيَا.","model":"نجا: ثلاثي أصلها واو (ينجو). قضى: ثلاثي أصلها ياء (يقضي). اهتدى: فوق ثلاثي بلا ياء قبله. أحيا: فوق ثلاثي قبلها ياء."},{"type":"essay","q":"اذكر فائدتين لاستخدام الأقمار الصناعية في مجال الآثار.","model":"١) اكتشاف المدن والطرق الأثرية المدفونة وتوفير الوقت والجهد. ٢) مراقبة المواقع الأثرية وحمايتها من التلف والتعديات."},{"type":"essay","q":"اشرح التشبيه في قول الأعشى: «وبتَّ كما باتَ السليمُ مسهّدا».","model":"شبّه الشاعر نفسه في سهره وأرقه باللديغ الذي يبيت ساهرًا طوال الليل لا يغمض له جفن، مما يبرز شدة همّه."},{"type":"essay","q":"قارن بين «سيرة بقلم صاحبها» و«ترجمة علم» من حيث الضمير والكاتب.","model":"في السيرة الذاتية الكاتب هو صاحب الحياة ويستخدم ضمير المتكلم (أنا)، أما في ترجمة العلم فالكاتب شخص آخر ويستخدم ضمير الغائب (هو)."}]},
  {"id":"g9-arabic-1-u7","grade":"g9","subject":"arabic","term":1,"title":"الوحدة السابعة: من تراث عُمان والأدب","levels":{"easy":[{"type":"mcq","q":"من مؤلف كتاب «تحفة الأعيان بسيرة أهل عُمان»؟","options":["الإمام نور الدين السالمي","الجاحظ","الخليل بن أحمد","البوصيري"],"answer":0,"why":"ألّفه الإمام عبد الله بن حميد السالمي."},{"type":"mcq","q":"ما الاسم الآخر للمفعول فيه؟","options":["الحال","الظرف (زمان أو مكان)","المفعول المطلق","التمييز"],"answer":1,"why":"المفعول فيه هو ظرف الزمان أو ظرف المكان."},{"type":"mcq","q":"أيُّ الكلمات الآتية كُتبت خطأً؟","options":["دعا","اهتدى","اشترىه","شيئًا"],"answer":2,"why":"الصواب «اشتراه» بألف قائمة لاتصال الضمير بها."},{"type":"mcq","q":"أيٌّ مما يأتي يدخل ضمن «البيانات التعريفية» في عرض الكتاب؟","options":["عنوان الكتاب والمؤلف ودار النشر وسنة الطبع","رأي القارئ فقط","ملخص الفصل الأخير","أسماء أصدقائك"],"answer":0,"why":"البيانات التعريفية تتيح للقارئ التعرّف على الكتاب والوصول إليه."}],"medium":[{"type":"mcq","q":"ما دافع الإمام السالمي من تأليف «تحفة الأعيان»؟","options":["حفظ تاريخ عُمان واستخلاص العبر للأجيال","التسلية فقط","وصف الرحلات الأجنبية","جمع الأمثال فقط"],"answer":0,"why":"أراد توثيق تاريخ وطنه وإفادة الأجيال بعبره."},{"type":"mcq","q":"ما إعراب «يومُ» في: «يومُ العيدِ سعيدٌ»؟","options":["ظرف زمان منصوب","مبتدأ مرفوع بالضمة","مفعول به","خبر"],"answer":1,"why":"لا تتضمن معنى «في» فتُعرب حسب موقعها مبتدأ."},{"type":"mcq","q":"أيُّ جملةٍ مما يأتي خالية تمامًا من الأخطاء الإملائية؟","options":["سعى مصطفى بهدوءٍ حتى نال شيئًا عظيمًا.","سعا مصطفا بهدوئٍ حتى نال شيءًا عظيمًا.","سعى مصطفا بهدوءٍ حتى نال شيئًا عظيمًا.","سعا مصطفى بهدوءٍ حتى نال شيءًا عظيمًا."],"answer":0,"why":"سعى (سعيتُ)، مصطفى (فوق ثلاثي)، بهدوءٍ (مد ساكن)، شيئًا (نبرة)."},{"type":"tfr","q":"اقتصر كتاب «تحفة الأعيان» على سرد المعارك السياسية دون ذكر العلماء والأدب.","answer":false,"reasons":["لأنه أورد سير العلماء والأدباء والقصائد والرسائل إلى جانب التاريخ السياسي","لأنه كتاب شعر فقط","لأنه لم يذكر عُمان"],"reason":0},{"type":"tfr","q":"الظرف «قَبْلَ» يُستعمل للزمان فقط ولا يأتي للمكان أبدًا.","answer":false,"reasons":["لأنه ظرف مشترك يحدّد معناه ما بعده: قبل الفجر (زمان)، قبل المسجد (مكان)","لأنه للمكان فقط","لأنه ليس ظرفًا"],"reason":0}],"hard":[{"type":"mcq","q":"ما القيمة المزدوجة التي يقدّمها كتاب «تحفة الأعيان» للقارئ؟","options":["القيمة التاريخية الموثّقة والقيمة الأدبية والتراثية","القيمة الرياضية فقط","القيمة الخيالية","لا قيمة له"],"answer":0,"why":"يجمع بين دقة التأريخ وجمال النصوص والقصائد والرسائل."},{"type":"mcq","q":"في أيّ جملة مما يأتي وقعت كلمة «ساعة» مفعولًا فيه؟","options":["الساعةُ دقيقةٌ","اشتريتُ ساعةً جديدةً","ذاكرتُ دروسي ساعةً","نظرتُ إلى الساعةِ"],"answer":2,"why":"«ذاكرتُ دروسي ساعةً» بتقدير «في ساعة» فتُعرب مفعولًا فيه."},{"type":"mcq","q":"أيُّ مجموعة كلمات كلها صحيحة إملائيًا؟","options":["نَمَا، قَضَى، اسْتَدْعَى، اسْتَحْيَا","نَمَى، قَضَا، اسْتَدْعَا، اسْتَحْيَى","عَفَى، بَنَا، أَعْطَى، أَحْيَا","دَعَا، مَشَا، اهْتَدَى، أَحْيَا"],"answer":0,"why":"كل الأفعال الأربعة مطابقة تمامًا للقاعدة."},{"type":"essay","q":"استخلص درسين من سيرة الإمام نور الدين السالمي يقتدي بهما طالب اليوم.","model":"١) التغلب على الصعاب بالإرادة والهمّة العالية. ٢) الأمانة العلمية والتحرّي قبل نقل أي معلومة."},{"type":"essay","q":"فرّق في الإعراب بين «صباح» في: (١) سافرتُ صباحًا. (٢) أشرقَ الصباحُ.","model":"في (١) «صباحًا» مفعول فيه ظرف زمان منصوب بالفتحة. وفي (٢) «الصباحُ» فاعل مرفوع بالضمة."}]},"test":[{"type":"mcq","q":"من مؤلف كتاب «تحفة الأعيان بسيرة أهل عُمان»؟","options":["الإمام نور الدين السالمي","الجاحظ","الخليل بن أحمد","البوصيري"],"answer":0,"why":"ألّفه الإمام عبد الله بن حميد السالمي."},{"type":"mcq","q":"ما الاسم الآخر للمفعول فيه؟","options":["الحال","الظرف (زمان أو مكان)","المفعول المطلق","التمييز"],"answer":1,"why":"المفعول فيه هو ظرف الزمان أو ظرف المكان."},{"type":"mcq","q":"أيُّ الكلمات الآتية كُتبت خطأً؟","options":["دعا","اهتدى","اشترىه","شيئًا"],"answer":2,"why":"الصواب «اشتراه» بألف قائمة لاتصال الضمير بها."},{"type":"mcq","q":"أيٌّ مما يأتي يدخل ضمن «البيانات التعريفية» في عرض الكتاب؟","options":["عنوان الكتاب والمؤلف ودار النشر وسنة الطبع","رأي القارئ فقط","ملخص الفصل الأخير","أسماء أصدقائك"],"answer":0,"why":"البيانات التعريفية تتيح للقارئ التعرّف على الكتاب والوصول إليه."},{"type":"mcq","q":"من هو أبو تمام الذي يخاطبه الشاعر في القصيدة؟","options":["شاعر عباسي شهير (حبيب بن أوس الطائي)","كاتب قصة قصيرة","عالم رياضيات","مؤرخ عُماني"],"answer":0,"why":"أبو تمام من أعظم شعراء العصر العباسي وصاحب بائية عمورية."},{"type":"mcq","q":"ما الموضوع الرئيس لكتاب «تحفة الأعيان»؟","options":["تاريخ عُمان وسير أئمتها وعلمائها","علم النحو","علم الطب","الخيال العلمي"],"answer":0,"why":"يُعدّ من أشمل المصادر في التاريخ العُماني."},{"type":"mcq","q":"أين ظرف الزمان في جملة: «استيقظَ الفلاحُ فجرًا»؟","options":["استيقظَ","الفلاحُ","فجرًا","لا يوجد"],"answer":2,"why":"«فجرًا» تبيّن زمان الاستيقاظ وتجيب عن متى."},{"type":"mcq","q":"ما الصواب في: «........ اللهُ الأرضَ بالمطرِ»؟","options":["أحيا","أحيى","أحيأ","أحيء"],"answer":0,"why":"فعل فوق ثلاثي سبقت ألفه ياء فتُكتب قائمة."},{"type":"mcq","q":"بماذا يختلف «عرض الكتاب» عن «التلخيص»؟","options":["عرض الكتاب يشتمل على التقييم والرأي الموضوعي","التلخيص أطول من الكتاب","عرض الكتاب لا يذكر المؤلف","لا يوجد فرق"],"answer":0,"why":"التلخيص محايد بلا رأي، أما عرض الكتاب فيضم تقييمًا وتوصية."},{"type":"mcq","q":"ما دلالة حذف أداة النداء في «أبا تمام»؟","options":["قربه من قلب الشاعر وروحه","بُعده","تجاهله","الغضب منه"],"answer":0,"why":"حذف أداة النداء يُشعر بقرب المنادى وحضوره في الوجدان."},{"type":"mcq","q":"علامَ اعتمد الإمام السالمي في توثيق الأحداث التاريخية؟","options":["التحرّي والوثائق والروايات الموثوقة","القصص الخيالية","التخمين","الترجمة الحرفية فقط"],"answer":0,"why":"التزم بالمنهج العلمي التحقيقي الدقيق."},{"type":"mcq","q":"أين ظرف المكان في جملة: «وقفَ الطائرُ فوقَ الغصنِ»؟","options":["وقفَ","الطائرُ","فوقَ","الغصنِ"],"answer":2,"why":"«فوقَ» ظرف مكان منصوب بالفتحة وهو مضاف."},{"type":"tf","q":"اقتصر كتاب «تحفة الأعيان» على سرد المعارك السياسية دون ذكر العلماء والأدب.","answer":false,"why":"لأنه أورد سير العلماء والأدباء والقصائد والرسائل إلى جانب التاريخ السياسي"},{"type":"tf","q":"الظرف «قَبْلَ» يُستعمل للزمان فقط ولا يأتي للمكان أبدًا.","answer":false,"why":"لأنه ظرف مشترك يحدّد معناه ما بعده: قبل الفجر (زمان)، قبل المسجد (مكان)"},{"type":"tf","q":"يتشابه الاسم غير الثلاثي والفعل غير الثلاثي في قاعدة رسم الألف اللينة في آخرهما.","answer":true,"why":"لأن كليهما تُكتب ألفه مقصورة إلا إذا سبقتها ياء فتُكتب قائمة (باستثناء العلم يحيى)"},{"type":"tf","q":"تحديد الجمهور المستهدف من الكتاب (طلاب، باحثون، عموم القراء) جزء مفيد في عرض الكتاب.","answer":true,"why":"لأنه يساعد القارئ على معرفة هل الكتاب مناسب لمستواه واهتماماته"},{"type":"tfr","q":"لم يمنع فقدان البصر الإمامَ السالميَّ من التأليف العلمي الغزير وخدمة وطنه.","answer":true,"reasons":["لأنه امتلك همّة عالية وذاكرة قوية فألّف كتبًا خالدة في التاريخ والفقه والأدب","لأنه لم يؤلّف سوى صفحة واحدة","لأنه اعتزل العلم"],"reason":0},{"type":"tfr","q":"الظرف «أمسِ» مبني على الكسر في محل نصب مفعول فيه.","answer":true,"reasons":["لأنه من الظروف المبنية مثل: أمسِ، الآنَ، حيثُ، هنا","لأنه معرب بالفتحة","لأنه مرفوع"],"reason":0},{"type":"tfr","q":"عندما نقول «رَمَاهُ» كُتبت الألف قائمة لأن أصل ألف «رمى» واو.","answer":false,"reasons":["لأن أصلها ياء، وإنما كُتبت قائمة لأنها صارت متوسطة لاتصالها بضمير الغائب","لأنها اسم أعجمي","لأنها فوق ثلاثي"],"reason":0},{"type":"tfr","q":"ينبغي أن يكون النقد والتقييم في عرض الكتاب موضوعيًا ومؤدّبًا يبرز جوانب القوة والملاحظات بإنصاف.","answer":true,"reasons":["لأن الموضوعية والإنصاف تكسبان العرض مصداقية لدى القارئ","لأن العرض للمدح المبالغ فيه فقط","لأن النقد يجب أن يكون قاسيًا"],"reason":0},{"type":"essay","q":"اذكر ثلاث سمات لمنهج الإمام السالمي في كتاب «تحفة الأعيان».","model":"التحقيق والتثبّت من الروايات، والإنصاف والموضوعية، والترتيب الزمني، والجمع بين التاريخ وسير العلماء والأدب."},{"type":"essay","q":"أعرب «ليلًا» في: «أضاءَ القمرُ السماءَ ليلًا».","model":"ليلًا: مفعول فيه (ظرف زمان) منصوب وعلامة نصبه الفتحة الظاهرة على آخره."},{"type":"essay","q":"صوّب الأخطاء في الجملة: «استحى الفتا من خطأًا وقع فيه فدعى ربّه واستغفره».","model":"استحيا الفتى من خطأٍ وقع فيه فدعا ربّه واستغفره."},{"type":"essay","q":"اذكر العناصر الأربعة الرئيسة لعرض أي كتاب بالترتيب.","model":"١) البيانات التعريفية. ٢) الفكرة العامة وأبرز الأبواب. ٣) وصف الأسلوب والمنهج. ٤) التقييم الموضوعي والتوصية."},{"type":"essay","q":"اشرح دلالة عنوان القصيدة «أبا تمام – أين تكون؟».","model":"يجمع العنوان بين نداءٍ محذوف الأداة يدلّ على القرب العاطفي من أبي تمام وتراثه، واستفهامٍ غرضه التحسّر والشوق إلى أمجاد الماضي وروح البطولة."}]},
  {"id":"g9-arabic-1-u8","grade":"g9","subject":"arabic","term":1,"title":"الوحدة الثامنة: آفاق العلم والأدب","levels":{"easy":[{"type":"mcq","q":"ما الذي يجمع بينه أدب الخيال العلمي؟","options":["المعرفة العلمية والخيال الإبداعي","الخرافة والسحر فقط","الأرقام بلا قصة","التاريخ القديم فقط"],"answer":0,"why":"يمزج الخيال العلمي بين العلم الصحيح والخيال المستقبلي."},{"type":"mcq","q":"أيُّ فعلٍ مما يأتي من أفعال الشروع؟","options":["شرعَ","عسى","علمَ","أعطى"],"answer":0,"why":"شرع وبدأ وأخذ وطفق من أفعال الشروع."},{"type":"mcq","q":"أين توضع النقطة (.)؟","options":["في نهاية الجملة التامة والفقرة","بعد المنادى","بعد القول","قبل التعداد"],"answer":0,"why":"النقطة علامة الوقف التام في نهاية الجملة أو الفقرة."},{"type":"mcq","q":"أيٌّ مما يأتي ليس من عناصر القصة الأساسية؟","options":["الشخصيات","الزمان والمكان","العقدة والحل","جدول الضرب"],"answer":3,"why":"عناصر القصة: الشخصيات، والزمان والمكان، والأحداث، والعقدة، والحل."}],"medium":[{"type":"mcq","q":"كيف أثّر أدب الخيال العلمي في مسيرة المخترعين؟","options":["ألهمهم بأفكار مستقبلية تحوّلت لاحقًا إلى اختراعات حقيقية","منعهم من البحث","أغلق المختبرات","لم يؤثر أبدًا"],"answer":0,"why":"الغواصات والأقمار الصناعية ومكالمات الفيديو بدأت أفكارًا خيالية علمية."},{"type":"mcq","q":"ما إعراب «قلمَهُ» في: «أخذَ الطالبُ قلمَهُ»؟","options":["خبر أخذ","مفعول به منصوب","اسم أخذ","ظرف مكان"],"answer":1,"why":"أخذ هنا فعل تام لأن بعده اسمًا لا جملة فعلية مضارعة."},{"type":"mcq","q":"ما العلامة المناسبة بعد المنادى في: «يا طالبُ ...... نظّمْ وقتَكَ»؟","options":["الفاصلة (،)","علامة الاستفهام (؟)","النقطة (.)","علامة الحذف"],"answer":0,"why":"توضع الفاصلة بعد المنادى."},{"type":"tfr","q":"قصص البساط الطائر والمصباح السحري تُعدّ من أدب الخيال العلمي.","answer":false,"reasons":["لأنها تنتمي للخيال الخرافي الأسطوري الذي لا يستند إلى قوانين علمية","لأنها تعتمد على الفيزياء","لأنها قصص واقعية"],"reason":0},{"type":"tfr","q":"في جملة «سافرتُ يومَ الجمعةِ» كلمة «يومَ» مفعول فيه منصوب.","answer":true,"reasons":["لأنها تبيّن زمان السفر بتقدير «في يوم الجمعة»","لأنها فاعل","لأنها مفعول لأجله"],"reason":0}],"hard":[{"type":"mcq","q":"ما الدور الذي يؤدّيه الخيال في عملية الابتكار العلمي؟","options":["يفتح آفاقًا جديدة للبحث ويصنع تصوّرات يسعى العلماء لتحقيقها","يعطّل التفكير المنطقي","يُلغي التجارب العلمية","يقتصر على الرسم"],"answer":0,"why":"الخيال المنضبط بالعلم هو الشرارة الأولى للاختراع."},{"type":"mcq","q":"أيُّ جملةٍ مما يأتي فيها «نائب عن المفعول المطلق»؟","options":["أحببتُ وطني كلَّ الحُبِّ","وقفتُ احترامًا للمعلم","جلستُ أمامَ البيتِ","كادَ المطرُ ينزلُ"],"answer":0,"why":"«كلَّ» مضافة إلى المصدر فتُعرب نائبًا عن المفعول المطلق."},{"type":"mcq","q":"ما العلامة المناسبة في نهاية: «أتعقّ والديك وقد ربياك صغيرًا ......»؟","options":["؟!",".","،",":"],"answer":0,"why":"استفهام استنكاري تعجبي تجتمع فيه (؟!)."},{"type":"essay","q":"قارن بين «الخيال العلمي» و«الخيال الخرافي» من حيث الأساس والهدف.","model":"الخيال العلمي أساسه النظريات العلمية وهدفه استشراف المستقبل وتحفيز الإبداع والوعي، أما الخيال الخرافي فأساسه الخوارق والسحر وهدفه التسلية أو الرمز الأسطوري."},{"type":"essay","q":"صوّب الأخطاء النحوية في الجمل الثلاث: (١) بدأَ الطالبُ أن يقرأَ. (٢) ظننتُ الطالبانِ غائبانِ. (٣) أُعْطِيَ المتفوّقينَ جوائزَ.","model":"(١) بدأَ الطالبُ يقرأُ (يمتنع اقتران الشروع بأنْ). (٢) ظننتُ الطالبَينِ غائبَينِ. (٣) أُعْطِيَ المتفوّقونَ جوائزَ."}]},"test":[{"type":"mcq","q":"ما الذي يجمع بينه أدب الخيال العلمي؟","options":["المعرفة العلمية والخيال الإبداعي","الخرافة والسحر فقط","الأرقام بلا قصة","التاريخ القديم فقط"],"answer":0,"why":"يمزج الخيال العلمي بين العلم الصحيح والخيال المستقبلي."},{"type":"mcq","q":"أيُّ فعلٍ مما يأتي من أفعال الشروع؟","options":["شرعَ","عسى","علمَ","أعطى"],"answer":0,"why":"شرع وبدأ وأخذ وطفق من أفعال الشروع."},{"type":"mcq","q":"أين توضع النقطة (.)؟","options":["في نهاية الجملة التامة والفقرة","بعد المنادى","بعد القول","قبل التعداد"],"answer":0,"why":"النقطة علامة الوقف التام في نهاية الجملة أو الفقرة."},{"type":"mcq","q":"أيٌّ مما يأتي ليس من عناصر القصة الأساسية؟","options":["الشخصيات","الزمان والمكان","العقدة والحل","جدول الضرب"],"answer":3,"why":"عناصر القصة: الشخصيات، والزمان والمكان، والأحداث، والعقدة، والحل."},{"type":"mcq","q":"من هو مؤلّف موسوعة «الحاوي في الطب»؟","options":["أبو بكر الرازي","الجاحظ","المتنبي","الخليل بن أحمد"],"answer":0,"why":"ألّف الرازي موسوعة الحاوي التي أصبحت مرجعًا عالميًا."},{"type":"mcq","q":"بماذا شُبّه الجليس الصالح في الحديث الشريف؟","options":["بحامل المسك","بنافخ الكير","بالسحاب","بالسيف"],"answer":0,"why":"لأنه ينفع صاحبه بالخير والسمعة الطيبة كرائحة المسك."},{"type":"mcq","q":"ما معنى «حِذْق» في قولنا «حذق طبيب»؟","options":["البراعة والمهارة والفطنة","الكسل","الغضب","النسيان"],"answer":0,"why":"الحذق يدل على الإتقان التام والذكاء في الصنعة."},{"type":"mcq","q":"بماذا يختلف الخيال العلمي عن الخيال الخرافي؟","options":["يستند إلى قوانين العلم ومنطقه","يعتمد على السحر","لا يحتاج للتفكير","يخلو من الأحداث"],"answer":0,"why":"الخيال العلمي ينطلق من أسس علمية ممكنة."},{"type":"mcq","q":"أين المفعول المطلق في: «اجتهدَ الطالبُ اجتهادًا طلبًا للنجاحِ صباحًا»؟","options":["اجتهادًا","طلبًا","صباحًا","الطالبُ"],"answer":0,"why":"«اجتهادًا» مصدر من لفظ الفعل اجتهدَ."},{"type":"mcq","q":"ما العلامة المناسبة في الفراغ: «نجح الطالبُ ...... لأنه اجتهدَ»؟","options":["؛","؟","!",":"],"answer":0,"why":"الثانية سبب للأولى فنضع الفاصلة المنقوطة."},{"type":"mcq","q":"ما المقصود بـ «العقدة» في القصة؟","options":["لحظة تأزّم المشكلة وذروة التشويق","أول سطر في القصة","اسم المؤلف","نهاية القصة"],"answer":0,"why":"العقدة هي ذروة الصراع أو المشكلة التي يواجهها البطل."},{"type":"mcq","q":"بين أي مرضَين كان الرازي أول من فرّق علميًا بدقة؟","options":["الجدري والحصبة","الصداع والزكام","الحساسية والربو","الأرق والتعب"],"answer":0,"why":"رسالته في الجدري والحصبة من أعظم إنجازات الطب."},{"type":"tf","q":"قصص البساط الطائر والمصباح السحري تُعدّ من أدب الخيال العلمي.","answer":false,"why":"لأنها تنتمي للخيال الخرافي الأسطوري الذي لا يستند إلى قوانين علمية"},{"type":"tf","q":"في جملة «سافرتُ يومَ الجمعةِ» كلمة «يومَ» مفعول فيه منصوب.","answer":true,"why":"لأنها تبيّن زمان السفر بتقدير «في يوم الجمعة»"},{"type":"tf","q":"تُوضع الجملة الاعتراضية مثل «صلى الله عليه وسلم» بين شرطتين (– ... –).","answer":true,"why":"لأن الشرطتين تحصران الجملة الاعتراضية التي يصح المعنى بدونها"},{"type":"tf","q":"تحديد الزمان والمكان في بداية القصة يساعد القارئ على تخيّل الأحداث ومعايشتها.","answer":true,"why":"لأنه يرسم المسرح الذي تتحرك فيه الشخصيات بوضوح"},{"type":"tfr","q":"يطرح الخيال العلمي تساؤلاتٍ أخلاقيةً حول كيفية توجيه التقنية لخدمة الإنسان.","answer":true,"reasons":["لأنه ينبّه إلى ضرورة اقتران التقدم التقني بالأخلاق وحماية البيئة والإنسان","لأنه يهمل الأخلاق دائمًا","لأنه يرفض التقنية كلها"],"reason":0},{"type":"tfr","q":"يمتنع اقتران خبر «عَسَى» بـ «أنْ».","answer":false,"reasons":["لأن اقتران خبر «عسى» بأنْ يكثر، أما الذي يمتنع فهو أفعال الشروع","لأن عسى من أفعال الشروع","لأن عسى لا خبر لها"],"reason":0},{"type":"tfr","q":"تُوضع النقطتان الرأسيتان (:) في نهاية السؤال.","answer":false,"reasons":["لأن نهاية السؤال توضع فيها علامة الاستفهام (؟)، أما النقطتان فبعد القول وقبل التعداد","لأن السؤال يختم بنقطة","لأن النقطتين توضعان بعد التعجب"],"reason":0},{"type":"tfr","q":"يُفضّل أن يكشف عنوان القصة القصيرة نهايتها والحل منذ البداية.","answer":false,"reasons":["لأن العنوان الجيّد يكون مشوّقًا وغامضًا قليلًا دون أن يحرق النهاية","لأن التشويق غير مهم","لأن العنوان يجب أن يكون فقرة كاملة"],"reason":0},{"type":"essay","q":"اذكر ثلاثة موضوعات يتناولها أدب الخيال العلمي.","model":"استكشاف الفضاء والكواكب، والروبوتات والذكاء الاصطناعي، والمدن المستقبلية، وتطوّر الطب والطاقة."},{"type":"essay","q":"استخرج المفاعيل الثلاثة من الجملة وبيّن نوع كل منها: «قَرَأتُ قراءةً متأنيةً مساءً حبًّا في المعرفة».","model":"قراءةً: مفعول مطلق (مبيّن للنوع). مساءً: مفعول فيه (ظرف زمان). حبًّا: مفعول لأجله."},{"type":"essay","q":"أعد كتابة الجملة بوضع علامات الترقيم المناسبة: «قال أبي يا بني احفظ وقتك لأن الوقت ثمين».","model":"قال أبي: «يا بني، احفظ وقتك؛ لأن الوقت ثمين»."},{"type":"essay","q":"اذكر العناصر الخمسة الأساسية لبناء القصة القصيرة.","model":"الشخصيات، والزمان والمكان، والأحداث (الحبكة)، والعقدة (الذروة)، والحل (النهاية)."},{"type":"essay","q":"اذكر ثلاثة إنجازات طبية وعلمية لأبي بكر الرازي.","model":"١) التفريق العلمي بين الجدري والحصبة. ٢) تأليف موسوعة «الحاوي في الطب». ٣) تأسيس الطب التجريبي والملاحظة السريرية، واستخدام خيوط الجراحة."}]},
  {"id":"g9-arabic-2-u1","grade":"g9","subject":"arabic","term":2,"title":"الوحدة الأولى: من وحي الطبيعة","levels":{"easy":[{"type":"mcq","q":"ما المقصود بـ«الرذاذ» في وصف خريف صلالة؟","options":["الرياح الرملية الحارة","المطر الخفيف الناعم المستمر","الثلوج الكثيفة","العواصف الرعدية الشديدة"],"answer":1,"why":"الرذاذ هو المطر الخفيف الذي يميّز خريف ظفار."},{"type":"mcq","q":"ما اللون الغالب الذي يرسمه النص لجبال صلالة في الخريف؟","options":["الأصفر الصحراوي","الأسود الداكن","الأخضر المكسو بالضباب الأبيض","الرمادي القاحل"],"answer":2,"why":"تكتسي الجبال بساطًا أخضر يلفّه الضباب الأبيض."},{"type":"mcq","q":"قول الكاتب «تكتسي الجبال حُلّةً خضراء» يُعدّ صورةً فنيةً تقوم على:","options":["السجع الصوتي فقط","المقابلة اللفظية","الترادف","التشخيص والاستعارة"],"answer":3,"why":"شُبّهت الجبال بإنسان يرتدي ثوبًا أخضر."},{"type":"mcq","q":"ما الحاسة التي يستثيرها وصف «خرير العيون المائية»؟","options":["السمع","التذوق","اللمس","الشم"],"answer":0,"why":"الخرير هو صوت جريان الماء."}],"medium":[{"type":"mcq","q":"ما العاطفة الرئيسة المسيطرة على نص «من وحي الخريف في صلالة»؟","options":["الحزن واليأس","الإعجاب بجمال الطبيعة والاعتزاز بالوطن","الغضب والعتاب","الخوف والتردد"],"answer":1,"why":"النص يحتفي بروعة الخريف وجمال عُمان."},{"type":"mcq","q":"ما معنى كلمة «وحي» في عنوان الدرس؟","options":["السرعة الفائقة","الابتعاد والهجر","الإلهام والأثر النفسي الجميل","الصوت المرتفع"],"answer":2,"why":"الوحي هنا ما يُلهمه المنظر الطبيعي للأديب."},{"type":"mcq","q":"أي مما يأتي من العيون المائية الشهيرة في محافظة ظفار؟","options":["بحيرة قارون","نهر النيل","شلالات نياجرا","عين رزات وعين حمران"],"answer":3,"why":"رزات وحمران وصحلنوت من أشهر عيون صلالة."},{"type":"tfr","q":"يُعدّ تنظيم الوصف من العام إلى الخاص سمةً فنيةً تزيد النص وضوحًا.","answer":true,"reasons":["العشوائية أفضل في الوصف","حيث يبدأ بالمشهد الكلي ثم ينتقل للتفاصيل الدقيقة","يجب البدء بالخاتمة"],"reason":1},{"type":"tfr","q":"أحرف المضارعة والضمائر المتصلة تُعدّ من حروف الزيادة عند تصنيف الفعل لمجرد ومزيد.","answer":false,"reasons":["نعم تُعدّ زيادة","الضمائر فقط تُعد زيادة","لا تُعدّ زيادة؛ نرد الفعل للماضي (هو) أولًا"],"reason":2}],"hard":[{"type":"mcq","q":"ما نوع النص «من وحي الخريف في صلالة»؟","options":["نص نثري وصفي أدبي","مسرحية هزلية","تقرير مالي","قصيدة عمودية"],"answer":0,"why":"هو مقالة نثرية وصفية أدبية."},{"type":"mcq","q":"ما فائدة توظيف الحواس المتعددة في النص الوصفي؟","options":["إطالة النص بلا فائدة","جعل القارئ يعيش المشهد كأنه حاضر فيه","إخفاء الفكرة الرئيسة","تقليل وضوح المعنى"],"answer":1,"why":"الحواس تحوّل الكلمات إلى تجربة حسية حيّة."},{"type":"mcq","q":"ما علاقة عنوان النص بمضمونه؟","options":["عنوان غامض لا صلة له بالنص","عنوان علمي بحت","عنوان موحٍ يلخّص مصدر إلهام الكاتب في وصف الخريف","عنوان يعارض المضمون"],"answer":2,"why":"العنوان يمهّد لجو الإلهام والوصف الطبيعي."},{"type":"essay","q":"اذكر ثلاث سمات طبيعية تميّز خريف صلالة كما وردت في النص.","model":"١) تساقط الرذاذ وانتشار الضباب. ٢) اكتساء الجبال والسهول بالخضرة الكثيفة. ٣) تدفق العيون المائية واعتدال الطقس."},{"type":"essay","q":"اشرح جمال التصوير في عبارة: «تلفّ السحب قمم الجبال بوشاح أبيض».","model":"شبّه الكاتب السحب والضباب بوشاح أبيض يلتف حول قمم الجبال، مما يبرز جمال المشهد ورقته ويوحي بالدفء والألفة."}]},"test":[{"type":"mcq","q":"ما المقصود بـ«الرذاذ» في وصف خريف صلالة؟","options":["الرياح الرملية الحارة","المطر الخفيف الناعم المستمر","الثلوج الكثيفة","العواصف الرعدية الشديدة"],"answer":1,"why":"الرذاذ هو المطر الخفيف الذي يميّز خريف ظفار."},{"type":"mcq","q":"ما اللون الغالب الذي يرسمه النص لجبال صلالة في الخريف؟","options":["الأصفر الصحراوي","الأسود الداكن","الأخضر المكسو بالضباب الأبيض","الرمادي القاحل"],"answer":2,"why":"تكتسي الجبال بساطًا أخضر يلفّه الضباب الأبيض."},{"type":"mcq","q":"قول الكاتب «تكتسي الجبال حُلّةً خضراء» يُعدّ صورةً فنيةً تقوم على:","options":["السجع الصوتي فقط","المقابلة اللفظية","الترادف","التشخيص والاستعارة"],"answer":3,"why":"شُبّهت الجبال بإنسان يرتدي ثوبًا أخضر."},{"type":"mcq","q":"ما الحاسة التي يستثيرها وصف «خرير العيون المائية»؟","options":["السمع","التذوق","اللمس","الشم"],"answer":0,"why":"الخرير هو صوت جريان الماء."},{"type":"mcq","q":"ما العاطفة الرئيسة المسيطرة على نص «من وحي الخريف في صلالة»؟","options":["الحزن واليأس","الإعجاب بجمال الطبيعة والاعتزاز بالوطن","الغضب والعتاب","الخوف والتردد"],"answer":1,"why":"النص يحتفي بروعة الخريف وجمال عُمان."},{"type":"mcq","q":"ما معنى كلمة «وحي» في عنوان الدرس؟","options":["السرعة الفائقة","الابتعاد والهجر","الإلهام والأثر النفسي الجميل","الصوت المرتفع"],"answer":2,"why":"الوحي هنا ما يُلهمه المنظر الطبيعي للأديب."},{"type":"mcq","q":"أي مما يأتي من العيون المائية الشهيرة في محافظة ظفار؟","options":["بحيرة قارون","نهر النيل","شلالات نياجرا","عين رزات وعين حمران"],"answer":3,"why":"رزات وحمران وصحلنوت من أشهر عيون صلالة."},{"type":"mcq","q":"ما نوع النص «من وحي الخريف في صلالة»؟","options":["نص نثري وصفي أدبي","مسرحية هزلية","تقرير مالي","قصيدة عمودية"],"answer":0,"why":"هو مقالة نثرية وصفية أدبية."},{"type":"mcq","q":"ما فائدة توظيف الحواس المتعددة في النص الوصفي؟","options":["إطالة النص بلا فائدة","جعل القارئ يعيش المشهد كأنه حاضر فيه","إخفاء الفكرة الرئيسة","تقليل وضوح المعنى"],"answer":1,"why":"الحواس تحوّل الكلمات إلى تجربة حسية حيّة."},{"type":"mcq","q":"ما علاقة عنوان النص بمضمونه؟","options":["عنوان غامض لا صلة له بالنص","عنوان علمي بحت","عنوان موحٍ يلخّص مصدر إلهام الكاتب في وصف الخريف","عنوان يعارض المضمون"],"answer":2,"why":"العنوان يمهّد لجو الإلهام والوصف الطبيعي."},{"type":"mcq","q":"أي الأسلوبين يغلب على نقل المشاهد والحقائق في النص الوصفي؟","options":["أسلوب النهي فقط","أسلوب الأمر فقط","أسلوب القسم فقط","الأسلوب الخبري"],"answer":3,"why":"الأسلوب الخبري هو الأساس في الوصف والتقرير."},{"type":"mcq","q":"في جملة «إنّ المعلمينَ مخلصونَ»، ما إعراب كلمة «المعلمين»؟","options":["اسم إنّ منصوب وعلامة نصبه الياء","مبتدأ مرفوع بالواو","خبر إنّ مرفوع","فاعل مرفوع"],"answer":0,"why":"إنّ تنصب اسمها، وجمع المذكر السالم يُنصب بالياء."},{"type":"tf","q":"يعتمد النص الوصفي الناجح على حاسة البصر وحدها دون بقية الحواس.","answer":false,"why":"بل يدمج البصر والسمع واللمس والشم ليكون الوصف حيًّا"},{"type":"tf","q":"التشخيص في الوصف الأدبي يمنح عناصر الطبيعة حركةً وحياةً تشدّ القارئ.","answer":true,"why":"مثل جعل الجبال تكتسي والنسائم تداعب الوجوه"},{"type":"tf","q":"موسم الخريف في صلالة يوافق أشهر الصيف فلكيًا ويتميّز بالرذاذ واعتدال الجو.","answer":true,"why":"وهو ما يجعل ظفار وجهةً سياحيةً فريدةً في المنطقة"},{"type":"tf","q":"النص الأدبي الوصفي يخلو تمامًا من الصور الفنية والتشبيهات.","answer":false,"why":"بل تقوم جماليته على التشبيهات والاستعارات والألفاظ الموحية"},{"type":"tfr","q":"يُعدّ تنظيم الوصف من العام إلى الخاص سمةً فنيةً تزيد النص وضوحًا.","answer":true,"reasons":["العشوائية أفضل في الوصف","حيث يبدأ بالمشهد الكلي ثم ينتقل للتفاصيل الدقيقة","يجب البدء بالخاتمة"],"reason":1},{"type":"tfr","q":"أحرف المضارعة والضمائر المتصلة تُعدّ من حروف الزيادة عند تصنيف الفعل لمجرد ومزيد.","answer":false,"reasons":["نعم تُعدّ زيادة","الضمائر فقط تُعد زيادة","لا تُعدّ زيادة؛ نرد الفعل للماضي (هو) أولًا"],"reason":2},{"type":"tfr","q":"جمع المؤنث السالم يُنصب وعلامة نصبه الكسرة نيابةً عن الفتحة.","answer":true,"reasons":["مثل: كرّمت المدرسةُ المتفوقاتِ","بل يُنصب بالفتحة","يُنصب بالياء"],"reason":0},{"type":"tfr","q":"الفعل «كسا» ينصب مفعولين أصلهما مبتدأ وخبر.","answer":false,"reasons":["نعم أصلهما مبتدأ وخبر","بل ليس أصلهما مبتدأ وخبرًا (من أخوات أعطى)","فعل لازم لا ينصب مفعولًا"],"reason":1},{"type":"essay","q":"اذكر ثلاث سمات طبيعية تميّز خريف صلالة كما وردت في النص.","model":"١) تساقط الرذاذ وانتشار الضباب. ٢) اكتساء الجبال والسهول بالخضرة الكثيفة. ٣) تدفق العيون المائية واعتدال الطقس."},{"type":"essay","q":"اشرح جمال التصوير في عبارة: «تلفّ السحب قمم الجبال بوشاح أبيض».","model":"شبّه الكاتب السحب والضباب بوشاح أبيض يلتف حول قمم الجبال، مما يبرز جمال المشهد ورقته ويوحي بالدفء والألفة."},{"type":"essay","q":"كيف وظّف الكاتب الحواس في نقل أجواء الخريف؟ أعطِ مثالين.","model":"حاسة البصر في وصف الخضرة والضباب، وحاسة السمع في خرير المياه، وحاسة اللمس في برودة الرذاذ."},{"type":"essay","q":"ما الأثر السياحي والاقتصادي لموسم الخريف في محافظة ظفار؟","model":"يجذب آلاف الزوار من داخل عُمان وخارجها، فينشّط السياحة والتجارة والتعريف بالتراث العُماني."},{"type":"essay","q":"اكتب ثلاث جمل وصفية من إنشائك تصف فيها منظرًا طبيعيًا زرتَه في سلطنة عُمان.","model":"وقفتُ على شاطئ القرم وقت الغروب، فإذا بأمواج البحر تتلألأ بلون الذهب، والنسيم العليل يداعب الوجوه بينما تحلّق النوارس فوق الأفق الهادئ."}]},
  {"id":"g9-arabic-2-u2","grade":"g9","subject":"arabic","term":2,"title":"الوحدة الثانية: العدل والتكافل","levels":{"easy":[{"type":"mcq","q":"لماذا سُمّي العام الثامن عشر للهجرة بـ«عام الرمادة»؟","options":["لوقوع معركة كبيرة","لكثرة الأمطار والسيول","لأن الأرض اسودّت من الجفاف والريح كانت تذرو ترابًا كالرماد","لبناء مدينة جديدة"],"answer":2,"why":"الجفاف الشديد جعل الأرض تشبه الرماد."},{"type":"mcq","q":"ماذا حرّم عمر بن الخطاب رضي الله عنه على نفسه طوال أزمة عام الرمادة؟","options":["مراسلة الولاة","شرب الماء نهائيًا","الخروج من بيته","أكل السمن واللحم واللبن حتى يشبع الناس"],"answer":3,"why":"آلى ألا يأكل السمن واللحم ليشارك الرعية معاناتهم."},{"type":"mcq","q":"من الوالي الذي أرسل من مصر قافلة إغاثة عظيمة إلى المدينة؟","options":["عمرو بن العاص","خالد بن الوليد","طارق بن زياد","قتيبة بن مسلم"],"answer":0,"why":"استجاب عمرو بن العاص لرسالة عمر بقافلة ضخمة من مصر."},{"type":"mcq","q":"ماذا يدل قول عمر: «بئس الوالي أنا إن شبعتُ والناس جياع»؟","options":["رغبته في السفر","شعوره العميق بالمسؤولية ومشاركته الرعية في الشدة","كرهه للطعام","إهماله للإدارة"],"answer":1,"why":"يبرز معيار القيادة العادلة والقدوة العملية."}],"medium":[{"type":"mcq","q":"كم استمرت شدة عام الرمادة تقريبًا؟","options":["عشر سنوات","ثلاثة أيام فقط","نحو تسعة أشهر","أسبوعين"],"answer":2,"why":"استمرت الأزمة قرابة تسعة أشهر حتى أغاثهم الله."},{"type":"mcq","q":"بمَ جمع عمر رضي الله عنه في معالجة أزمة عام الرمادة؟","options":["إغلاق أبواب المدينة","الاكتفاء بالانتظار دون عمل","الاعتماد على المال فقط","بين الأخذ بالأسباب المادية (القوافل والتنظيم) والدعاء والاستسقاء"],"answer":3,"why":"وازن بين التخطيط الإداري واللجوء إلى الله."},{"type":"mcq","q":"ما الإجراء الفقهي الرحيم الذي اتخذه عمر في عام المجاعة؟","options":["إسقاط حدّ السرقة عن المضطر الجائع في عام المجاعة","مضاعفة العقوبات","منع دخول الوافدين","رفع الضرائب"],"answer":0,"why":"راعى مقاصد الشريعة في حفظ النفس والرحمة بالمضطر."},{"type":"tfr","q":"التكافل الاجتماعي في الأزمات مسؤولية الحاكم وحده ولا دور للأفراد فيه.","answer":false,"reasons":["نعم الحاكم وحده","لا حاجة للتكافل","بل هو مسؤولية مشتركة بين القيادة وأفراد المجتمع جميعًا"],"reason":2},{"type":"tfr","q":"اسم لا النافية للجنس «المفرد» يُقصد به ما ليس مضافًا ولا شبيهًا بالمضاف، حتى لو كان مثنى أو جمعًا.","answer":true,"reasons":["مثل: لا طالبَين مهملان (مبني على الياء في محل نصب)","يقصد به المفرد العددي فقط","المثنى يكون مضافًا دائمًا"],"reason":0}],"hard":[{"type":"mcq","q":"بمن توسّل عمر رضي الله عنه في صلاة الاستسقاء؟","options":["بأهل العراق فقط","بدعاء العباس بن عبد المطلب عمّ النبي ﷺ","بالتجار","بالشعراء"],"answer":1,"why":"قال: اللهم إنا نتوسل إليك بعمّ نبيّنا فاسقنا."},{"type":"mcq","q":"ما القيمة الاجتماعية التي يربطها النص بمجتمعنا العُماني وقت الأنواء المناخية؟","options":["التنافس على الاحتكار","الفردية والأنانية","التكافل والتآزر ومدّ يد العون للمتضررين","الانعزال عن الناس"],"answer":2,"why":"التكاتف وقت الشدائد قيمة إسلامية وعُمانية أصيلة."},{"type":"mcq","q":"ما معنى كلمة «القحط» الواردة في سياق النص؟","options":["كثرة المحاصيل","غزارة المطر","اعتدال الجو","انقطاع المطر وجفاف الأرض"],"answer":3,"why":"القحط والجدب هما انحباس المطر والجفاف."},{"type":"essay","q":"اذكر ثلاثة إجراءات عملية اتخذها عمر بن الخطاب لإدارة أزمة عام الرمادة.","model":"١) مراسلة الولاة في مصر والشام والعراق لإرسال قوافل الطعام. ٢) تنظيم توزيع الطعام وإقامة قدور للوافدين. ٣) التفقد الليلي للأسر المتعففة ومشاركتهم التقشف."},{"type":"essay","q":"اشرح كيف توازن قصة عام الرمادة بين «الأخذ بالأسباب» و«التوكل على الله».","model":"أخذ عمر بكل الأسباب الإدارية والاقتصادية بجلب المؤن وتوزيعها بعدل، ثم خرج مع الناس لصلاة الاستسقاء متضرعًا إلى الله الذي أغاثهم بالمطر."}]},"test":[{"type":"mcq","q":"لماذا سُمّي العام الثامن عشر للهجرة بـ«عام الرمادة»؟","options":["لوقوع معركة كبيرة","لكثرة الأمطار والسيول","لأن الأرض اسودّت من الجفاف والريح كانت تذرو ترابًا كالرماد","لبناء مدينة جديدة"],"answer":2,"why":"الجفاف الشديد جعل الأرض تشبه الرماد."},{"type":"mcq","q":"ماذا حرّم عمر بن الخطاب رضي الله عنه على نفسه طوال أزمة عام الرمادة؟","options":["مراسلة الولاة","شرب الماء نهائيًا","الخروج من بيته","أكل السمن واللحم واللبن حتى يشبع الناس"],"answer":3,"why":"آلى ألا يأكل السمن واللحم ليشارك الرعية معاناتهم."},{"type":"mcq","q":"من الوالي الذي أرسل من مصر قافلة إغاثة عظيمة إلى المدينة؟","options":["عمرو بن العاص","خالد بن الوليد","طارق بن زياد","قتيبة بن مسلم"],"answer":0,"why":"استجاب عمرو بن العاص لرسالة عمر بقافلة ضخمة من مصر."},{"type":"mcq","q":"ماذا يدل قول عمر: «بئس الوالي أنا إن شبعتُ والناس جياع»؟","options":["رغبته في السفر","شعوره العميق بالمسؤولية ومشاركته الرعية في الشدة","كرهه للطعام","إهماله للإدارة"],"answer":1,"why":"يبرز معيار القيادة العادلة والقدوة العملية."},{"type":"mcq","q":"كم استمرت شدة عام الرمادة تقريبًا؟","options":["عشر سنوات","ثلاثة أيام فقط","نحو تسعة أشهر","أسبوعين"],"answer":2,"why":"استمرت الأزمة قرابة تسعة أشهر حتى أغاثهم الله."},{"type":"mcq","q":"بمَ جمع عمر رضي الله عنه في معالجة أزمة عام الرمادة؟","options":["إغلاق أبواب المدينة","الاكتفاء بالانتظار دون عمل","الاعتماد على المال فقط","بين الأخذ بالأسباب المادية (القوافل والتنظيم) والدعاء والاستسقاء"],"answer":3,"why":"وازن بين التخطيط الإداري واللجوء إلى الله."},{"type":"mcq","q":"ما الإجراء الفقهي الرحيم الذي اتخذه عمر في عام المجاعة؟","options":["إسقاط حدّ السرقة عن المضطر الجائع في عام المجاعة","مضاعفة العقوبات","منع دخول الوافدين","رفع الضرائب"],"answer":0,"why":"راعى مقاصد الشريعة في حفظ النفس والرحمة بالمضطر."},{"type":"mcq","q":"بمن توسّل عمر رضي الله عنه في صلاة الاستسقاء؟","options":["بأهل العراق فقط","بدعاء العباس بن عبد المطلب عمّ النبي ﷺ","بالتجار","بالشعراء"],"answer":1,"why":"قال: اللهم إنا نتوسل إليك بعمّ نبيّنا فاسقنا."},{"type":"mcq","q":"ما القيمة الاجتماعية التي يربطها النص بمجتمعنا العُماني وقت الأنواء المناخية؟","options":["التنافس على الاحتكار","الفردية والأنانية","التكافل والتآزر ومدّ يد العون للمتضررين","الانعزال عن الناس"],"answer":2,"why":"التكاتف وقت الشدائد قيمة إسلامية وعُمانية أصيلة."},{"type":"mcq","q":"ما معنى كلمة «القحط» الواردة في سياق النص؟","options":["كثرة المحاصيل","غزارة المطر","اعتدال الجو","انقطاع المطر وجفاف الأرض"],"answer":3,"why":"القحط والجدب هما انحباس المطر والجفاف."},{"type":"mcq","q":"ما دلالة عبارة «قافلة أولها في المدينة وآخرها في مصر»؟","options":["الكناية عن ضخامة الإمدادات وتواصل القوافل دون انقطاع","أن الطريق كان قصيرًا جدًا","أن القافلة ضلّت الطريق","أنها قافلة واحدة صغيرة"],"answer":0,"why":"تعبير بلاغي يدل على كثرة الإمدادات واتصالها."},{"type":"mcq","q":"ما نوع اسم لا النافية للجنس وإعرابه في: «لا منافقَ محبوبٌ»؟","options":["مبتدأ مرفوع","مفرد — مبني على الفتح في محل نصب","شبيه بالمضاف — منصوب","مضاف — منصوب بالفتحة"],"answer":1,"why":"كلمة واحدة نكرة غير مضافة ولا شبيهة بالمضاف فهي مفرد مبني."},{"type":"tf","q":"سُمّي عام الرمادة بهذا الاسم بسبب الجفاف الشديد الذي جعل الأرض تشبه الرماد.","answer":true,"why":"حيث انحبس المطر سنة ١٨ هـ وجفّت الأرض"},{"type":"tf","q":"اكتفى عمر بن الخطاب بالدعاء ولم يرسل طلبًا للإغاثة من الولايات الأخرى.","answer":false,"why":"بل أخذ بكل الأسباب وأرسل لولاته في مصر والشام والعراق ونظّم توزيع الطعام"},{"type":"tf","q":"مشاركة القائد لشعبه في المعاناة تعزّز الثقة والتماسك الاجتماعي في الأزمات.","answer":true,"why":"وهو ما جسّده عمر بامتناعه عن السمن واللحم وتفقده الأسر بنفسه"},{"type":"tf","q":"وقعت أزمة عام الرمادة في خلافة عمر بن الخطاب سنة ١٨ هـ.","answer":true,"why":"واستمرت قرابة تسعة أشهر حتى فرّج الله عنهم"},{"type":"tfr","q":"التكافل الاجتماعي في الأزمات مسؤولية الحاكم وحده ولا دور للأفراد فيه.","answer":false,"reasons":["نعم الحاكم وحده","لا حاجة للتكافل","بل هو مسؤولية مشتركة بين القيادة وأفراد المجتمع جميعًا"],"reason":2},{"type":"tfr","q":"اسم لا النافية للجنس «المفرد» يُقصد به ما ليس مضافًا ولا شبيهًا بالمضاف، حتى لو كان مثنى أو جمعًا.","answer":true,"reasons":["مثل: لا طالبَين مهملان (مبني على الياء في محل نصب)","يقصد به المفرد العددي فقط","المثنى يكون مضافًا دائمًا"],"reason":0},{"type":"tfr","q":"تعمل لا النافية للجنس إذا دخل عليها حرف الجر الباء مثل «بلا خوفٍ».","answer":false,"reasons":["تُرفع الكلمة بعدها","يُلغى عملها وتُجر الكلمة بعدها بحرف الجر","نعم تبقى عاملة"],"reason":1},{"type":"tfr","q":"الفرق الظاهر بين المضاف والشبيه بالمضاف هو بقاء التنوين أو النون في الشبيه بالمضاف وحذفهما في المضاف.","answer":true,"reasons":["لا فرق بينهما","المضاف يكون منوّنًا","لا طالبَ علمٍ (مضاف بلا تنوين) مقابل لا طالبًا علمًا (شبيه منوّن)"],"reason":2},{"type":"essay","q":"اذكر ثلاثة إجراءات عملية اتخذها عمر بن الخطاب لإدارة أزمة عام الرمادة.","model":"١) مراسلة الولاة في مصر والشام والعراق لإرسال قوافل الطعام. ٢) تنظيم توزيع الطعام وإقامة قدور للوافدين. ٣) التفقد الليلي للأسر المتعففة ومشاركتهم التقشف."},{"type":"essay","q":"اشرح كيف توازن قصة عام الرمادة بين «الأخذ بالأسباب» و«التوكل على الله».","model":"أخذ عمر بكل الأسباب الإدارية والاقتصادية بجلب المؤن وتوزيعها بعدل، ثم خرج مع الناس لصلاة الاستسقاء متضرعًا إلى الله الذي أغاثهم بالمطر."},{"type":"essay","q":"ما أثر قول عمر: «بئس الوالي أنا إن شبعت والناس جياع» في نفوس الرعية؟","model":"يبعث الطمأنينة والرضا في قلوب الناس، ويجعلهم يشعرون بالعدالة والمساواة والتلاحم مع قائدهم."},{"type":"essay","q":"اربط بين دروس عام الرمادة ومظاهر التكافل في سلطنة عُمان عند حدوث الأنواء المناخية.","model":"كما تكاتف المسلمون في عام الرمادة لإغاثة المحتاجين، يهبّ أبناء عُمان والجهات التطوعية معًا لفتح الطرق وإيواء المتضررين وتقديم المساعدات بروح أخوية واحدة."},{"type":"essay","q":"لماذا أسقط عمر رضي الله عنه حدّ السرقة في عام المجاعة؟","model":"تحقيقًا لمقاصد الشريعة في الرحمة ورفع الحرج عن المضطر الذي دفعه الجوع الشديد، فالشريعة قائمة على العدل والرحمة."}]},
  {"id":"g9-arabic-2-u3","grade":"g9","subject":"arabic","term":2,"title":"الوحدة الثالثة: الحضارة والتواصل","levels":{"easy":[{"type":"mcq","q":"ما الفكرة المحورية في نص «عالمية الحضارة الإنسانية»؟","options":["التاريخ القديم لا علاقة له بالحاضر","الحضارة ملك لأمة واحدة فقط","التبادل الثقافي يضر بالعلم","الحضارة بناء إنساني مشترك تسهم فيه جميع الأمم بالأخذ والعطاء"],"answer":3,"why":"كل حضارة تبني على ما سبقها وتضيف إبداعها."},{"type":"mcq","q":"كيف تعامل العلماء المسلمون مع علوم الأمم السابقة؟","options":["ترجموها ونقدوها وصحّحوها وأبدعوا علومًا جديدةً فوقها","نقلوها دون فهم أو إضافة","رفضوا قراءتها تمامًا","أخفوها عن العالم"],"answer":0,"why":"تميّزوا بالنقد العلمي والإبداع مثل الجبر والبصريات."},{"type":"mcq","q":"أي مما يأتي يُعدّ من أبرز معابر انتقال العلوم العربية إلى أوروبا؟","options":["القطب الجنوبي","الأندلس وصقلية","أستراليا","أمريكا الجنوبية"],"answer":1,"why":"الأندلس وصقلية كانتا الجسر الرئيس لنقل العلوم."},{"type":"mcq","q":"ما المقصود بـ«التفاعل الحضاري الواعي»؟","options":["الانغلاق الكامل عن العالم","التقليد الأعمى لكل ما يأتي من الخارج","الاستفادة من العلوم النافعة مع الحفاظ على الهوية والقيم والإسهام بالإبداع","إهمال اللغة العربية"],"answer":2,"why":"التوازن بين الانفتاح العلمي وحفظ الهوية."}],"medium":[{"type":"mcq","q":"أي عالم مسلم أسّس علم الجبر ونُسبت إليه «الخوارزميات»؟","options":["الأصمعي","أبو الطيب المتنبي","عنترة بن شداد","محمد بن موسى الخوارزمي"],"answer":3,"why":"الخوارزمي رائد الجبر والخوارزميات."},{"type":"mcq","q":"ما المقصود بـ«التلاقح الفكري» بين الحضارات؟","options":["التفاعل الإيجابي المثمر الذي يولّد معرفةً وإبداعًا جديدًا","الصراع والحرب الدائمة","انعزال كل ثقافة وحدها","إلغاء اللغات"],"answer":0,"why":"التلاقح يعني الإخصاب والتفاعل المثمر."},{"type":"mcq","q":"كيف أسهمت سلطنة عُمان تاريخيًا في التواصل الحضاري؟","options":["بالعزلة عن البحار","عبر موانئها وأساطيلها التجارية السلمية نحو الهند والصين وشرق إفريقيا","برفض التجارة","بعدم بناء السفن"],"answer":1,"why":"كان العُمانيون سفراء للتجارة والعلم والتسامح."},{"type":"tfr","q":"يعتمد المقال الفكري على الأدلة والشواهد المنطقية لإقناع القارئ.","answer":true,"reasons":["مع لغة واضحة وموضوعية وروابط منطقية","يعتمد على الخيال فقط","يخلو من الأدلة"],"reason":0},{"type":"tfr","q":"إذا كان الفاعل ضميرًا مستترًا يعود على مؤنث مجازي مثل «السيارةُ انطلقَتْ» فإن تأنيث الفعل واجب.","answer":true,"reasons":["بل جائز الوجهين","فمتى كان الفاعل ضميرًا مستترًا لمؤنث (حقيقي أو مجازي) وجب التأنيث","بل يجب التذكير"],"reason":1}],"hard":[{"type":"mcq","q":"ما الخطر الناجم عن «التقليد الأعمى» للحضارات الأخرى؟","options":["تعزيز الثقة بالنفس","زيادة الابتكار العلمي","فقدان الهوية والشخصية والتحول إلى مجرد مستهلك","حفظ التراث"],"answer":2,"why":"التقليد الأعمى يضعف الإبداع والهوية."},{"type":"mcq","q":"ما نوع أسلوب نص «عالمية الحضارة الإنسانية»؟","options":["شعر غزلي","أسلوب قصصي خيالي","أسلوب هزلي ساخر","أسلوب فكري موضوعي يعتمد على الحجة والشواهد التاريخية"],"answer":3,"why":"مقالة فكرية تخاطب العقل بالبراهين."},{"type":"mcq","q":"من العالم المسلم الرائد في علم البصريات والمنهج التجريبي؟","options":["الحسن بن الهيثم","أمرؤ القيس","زهير بن أبي سلمى","جرير"],"answer":0,"why":"ابن الهيثم مؤسس علم البصريات الحديث."},{"type":"essay","q":"علّل: لماذا تُوصف الحضارة الإنسانية بأنها «عالمية وتراكمية»؟","model":"لأنها ليست حكرًا على شعب واحد، بل تسلم كل أمة مشعل المعرفة للأخرى، فتستفيد اللاحقة من السابقة وتضيف إبداعها لصالح البشرية جمعاء."},{"type":"essay","q":"اذكر ثلاثة مجالات أبدع فيها العلماء المسلمون وأثروا في الحضارة العالمية مع مثال لعالم في كل مجال.","model":"١) الرياضيات: الخوارزمي (الجبر والخوارزميات). ٢) البصريات والفيزياء: ابن الهيثم. ٣) الطب: ابن سينا والرازي (أو الملاحة: أحمد بن ماجد)."}]},"test":[{"type":"mcq","q":"ما الفكرة المحورية في نص «عالمية الحضارة الإنسانية»؟","options":["التاريخ القديم لا علاقة له بالحاضر","الحضارة ملك لأمة واحدة فقط","التبادل الثقافي يضر بالعلم","الحضارة بناء إنساني مشترك تسهم فيه جميع الأمم بالأخذ والعطاء"],"answer":3,"why":"كل حضارة تبني على ما سبقها وتضيف إبداعها."},{"type":"mcq","q":"كيف تعامل العلماء المسلمون مع علوم الأمم السابقة؟","options":["ترجموها ونقدوها وصحّحوها وأبدعوا علومًا جديدةً فوقها","نقلوها دون فهم أو إضافة","رفضوا قراءتها تمامًا","أخفوها عن العالم"],"answer":0,"why":"تميّزوا بالنقد العلمي والإبداع مثل الجبر والبصريات."},{"type":"mcq","q":"أي مما يأتي يُعدّ من أبرز معابر انتقال العلوم العربية إلى أوروبا؟","options":["القطب الجنوبي","الأندلس وصقلية","أستراليا","أمريكا الجنوبية"],"answer":1,"why":"الأندلس وصقلية كانتا الجسر الرئيس لنقل العلوم."},{"type":"mcq","q":"ما المقصود بـ«التفاعل الحضاري الواعي»؟","options":["الانغلاق الكامل عن العالم","التقليد الأعمى لكل ما يأتي من الخارج","الاستفادة من العلوم النافعة مع الحفاظ على الهوية والقيم والإسهام بالإبداع","إهمال اللغة العربية"],"answer":2,"why":"التوازن بين الانفتاح العلمي وحفظ الهوية."},{"type":"mcq","q":"أي عالم مسلم أسّس علم الجبر ونُسبت إليه «الخوارزميات»؟","options":["الأصمعي","أبو الطيب المتنبي","عنترة بن شداد","محمد بن موسى الخوارزمي"],"answer":3,"why":"الخوارزمي رائد الجبر والخوارزميات."},{"type":"mcq","q":"ما المقصود بـ«التلاقح الفكري» بين الحضارات؟","options":["التفاعل الإيجابي المثمر الذي يولّد معرفةً وإبداعًا جديدًا","الصراع والحرب الدائمة","انعزال كل ثقافة وحدها","إلغاء اللغات"],"answer":0,"why":"التلاقح يعني الإخصاب والتفاعل المثمر."},{"type":"mcq","q":"كيف أسهمت سلطنة عُمان تاريخيًا في التواصل الحضاري؟","options":["بالعزلة عن البحار","عبر موانئها وأساطيلها التجارية السلمية نحو الهند والصين وشرق إفريقيا","برفض التجارة","بعدم بناء السفن"],"answer":1,"why":"كان العُمانيون سفراء للتجارة والعلم والتسامح."},{"type":"mcq","q":"ما الخطر الناجم عن «التقليد الأعمى» للحضارات الأخرى؟","options":["تعزيز الثقة بالنفس","زيادة الابتكار العلمي","فقدان الهوية والشخصية والتحول إلى مجرد مستهلك","حفظ التراث"],"answer":2,"why":"التقليد الأعمى يضعف الإبداع والهوية."},{"type":"mcq","q":"ما نوع أسلوب نص «عالمية الحضارة الإنسانية»؟","options":["شعر غزلي","أسلوب قصصي خيالي","أسلوب هزلي ساخر","أسلوب فكري موضوعي يعتمد على الحجة والشواهد التاريخية"],"answer":3,"why":"مقالة فكرية تخاطب العقل بالبراهين."},{"type":"mcq","q":"من العالم المسلم الرائد في علم البصريات والمنهج التجريبي؟","options":["الحسن بن الهيثم","أمرؤ القيس","زهير بن أبي سلمى","جرير"],"answer":0,"why":"ابن الهيثم مؤسس علم البصريات الحديث."},{"type":"mcq","q":"كيف تعود أمتنا شريكًا فاعلًا في الحضارة العالمية المعاصرة؟","options":["بالاكتفاء بالتغني بالماضي دون عمل","بإتقان العلم والبحث والابتكار مع الالتزام بالقيم الإنسانية","بمقاطعة التقنية الحديثة","بالتقليد فقط"],"answer":1,"why":"المشاركة الحضارية تتطلب علمًا وابتكارًا وعملاً."},{"type":"mcq","q":"ما حكم تأنيث الفعل في جملة: «الشمسُ أشرقَتْ»؟","options":["واجب التذكير","جائز التأنيث والتذكير","واجب التأنيث (لأن الفاعل ضمير مستتر يعود لمؤنث)","ممتنع التأنيث"],"answer":2,"why":"الفاعل ضمير مستتر يعود على «الشمس» فيجب التأنيث حتى مع المجازي."},{"type":"tf","q":"الحضارة الإنسانية الحديثة قامت بجهد أمة واحدة فقط دون الاستفادة من غيرها.","answer":false,"why":"بل هي ثمرة تراكم معرفي شاركت فيه أمم عديدة بينها الحضارة العربية الإسلامية"},{"type":"tf","q":"اكتفى المسلمون بترجمة علوم اليونان والهند دون أي نقد أو إضافة علمية.","answer":false,"why":"بل نقدوها وصحّحوا أخطاءها وأسّسوا علومًا كالجبر والبصريات والمنهج التجريبي"},{"type":"tf","q":"الانفتاح الحضاري الواعي يجمع بين اكتساب العلم الحديث والحفاظ على الهوية والقيم.","answer":true,"why":"فلا انغلاق يحرمنا من التطور ولا تقليد أعمى يذيب هويتنا"},{"type":"tf","q":"أدّت الموانئ العُمانية دورًا مهمًا في التواصل الحضاري السلمي بين الشرق والغرب.","answer":true,"why":"عبر التجارة البحرية مع الهند والصين وشرقي إفريقيا"},{"type":"tfr","q":"يعتمد المقال الفكري على الأدلة والشواهد المنطقية لإقناع القارئ.","answer":true,"reasons":["مع لغة واضحة وموضوعية وروابط منطقية","يعتمد على الخيال فقط","يخلو من الأدلة"],"reason":0},{"type":"tfr","q":"إذا كان الفاعل ضميرًا مستترًا يعود على مؤنث مجازي مثل «السيارةُ انطلقَتْ» فإن تأنيث الفعل واجب.","answer":true,"reasons":["بل جائز الوجهين","فمتى كان الفاعل ضميرًا مستترًا لمؤنث (حقيقي أو مجازي) وجب التأنيث","بل يجب التذكير"],"reason":1},{"type":"tfr","q":"يجوز تذكير الفعل وتأنيثه إذا كان الفاعل جمع تكسير مثل: حضرَ/حضرَتِ الطلابُ.","answer":true,"reasons":["يجب التذكير فقط","يجب التأنيث فقط","لأن جمع التكسير يجوز تأويله بالجماعة"],"reason":2},{"type":"tfr","q":"المؤنث الحقيقي هو كل اسم يدل على أنثى تلد أو تبيض.","answer":true,"reasons":["مثل: الأم، المعلمة، الغزالة، الحمامة","هو الجمادات فقط","هو جمع التكسير"],"reason":0},{"type":"essay","q":"علّل: لماذا تُوصف الحضارة الإنسانية بأنها «عالمية وتراكمية»؟","model":"لأنها ليست حكرًا على شعب واحد، بل تسلم كل أمة مشعل المعرفة للأخرى، فتستفيد اللاحقة من السابقة وتضيف إبداعها لصالح البشرية جمعاء."},{"type":"essay","q":"اذكر ثلاثة مجالات أبدع فيها العلماء المسلمون وأثروا في الحضارة العالمية مع مثال لعالم في كل مجال.","model":"١) الرياضيات: الخوارزمي (الجبر والخوارزميات). ٢) البصريات والفيزياء: ابن الهيثم. ٣) الطب: ابن سينا والرازي (أو الملاحة: أحمد بن ماجد)."},{"type":"essay","q":"قارن بين «التفاعل الحضاري الواعي» و«التقليد الأعمى» و«الانغلاق».","model":"التفاعل الواعي: أخذ العلوم النافعة مع حفظ الهوية والإبداع. التقليد الأعمى: اتباع الآخرين بلا تمييز مما يُفقد الهوية. الانغلاق: العزلة التي تؤدي للتخلف."},{"type":"essay","q":"كيف جسّدت سلطنة عُمان مفهوم التواصل الحضاري عبر التاريخ؟","model":"بموقعها البحري وموانئها المزدهرة (صحار وقلهات ومسقط) التي كانت مراكز لتبادل التجارة والعلوم والقيم السمحة مع الهند والصين وشرقي إفريقيا."},{"type":"essay","q":"ما الدور المطلوب من الشباب العُماني اليوم للمساهمة في الحضارة الإنسانية؟","model":"إتقان العلوم الحديثة والتقنية، والابتكار والبحث العلمي، والتمسك بالأخلاق العُمانية السمحة في تمثيل وطنهم أمام العالم."}]},
  {"id":"g9-arabic-2-u4","grade":"g9","subject":"arabic","term":2,"title":"الوحدة الرابعة: رسائل وتقارير","levels":{"easy":[{"type":"mcq","q":"من كاتب نص «رسالة إلى ابني»؟","options":["الأديب المصري أحمد أمين","طه حسين","عباس العقاد","الجاحظ"],"answer":0,"why":"الأديب والمفكّر أحمد أمين (صاحب فيض الخاطر)."},{"type":"mcq","q":"ما السلاحان العظيمان اللذان يذكّر الكاتب ابنه بأن الله منحهما له؟","options":["المال والجاه","العقل والحرية المسؤولة","السرعة والقوة الجسدية فقط","الحظ والمصادفة"],"answer":1,"why":"العقل للتمييز والحرية للاختيار المسؤول."},{"type":"mcq","q":"وفق النص، ما المعايير الثلاثة لاختيار العمل المناسب؟","options":["تقليد الأصدقاء فقط","الراتب وحده دون رغبة","الميل الشخصي، والقدرة، وفائدة المجتمع","أسهل عمل بلا جهد"],"answer":2,"why":"تجمع بين الرغبة والاستعداد وخدمة الوطن."},{"type":"mcq","q":"أين تكمن «السعادة الحقيقية» في نظر الكاتب؟","options":["في الإسراف واللهو","في الكسل والراحة الدائمة","في تجنّب كل مسؤولية","في القيام بالواجب والشعور بالإنجاز بعد العمل الشريف"],"answer":3,"why":"السعادة ثمرة الإنجاز وأداء الواجب."}],"medium":[{"type":"mcq","q":"ما الغرض البلاغي من نداء الأب لابنه بـ«أي بُنيّ»؟","options":["التحبّب والإشفاق وتهيئة النفس لقبول النصيحة","التوبيخ والغضب","التعجب","الاستفهام"],"answer":0,"why":"التصغير «بُنيّ» يفيض حنانًا ومحبةً أبويةً."},{"type":"mcq","q":"ما الفن النثري الذي ينتمي إليه النص؟","options":["المسرحية","فنّ الرسائل الأدبية التربوية","السيرة الذاتية","التقرير العلمي"],"answer":1,"why":"رسالة أدبية من أب إلى ابنه."},{"type":"mcq","q":"بمَ يتميّز أسلوب أحمد أمين في هذه الرسالة؟","options":["بالسجع المتكلّف","بالألفاظ الغريبة المعقدة","بالوضوح والسلاسة (السهل الممتنع) والمزج بين العاطفة والإقناع العقلي","بالغموض"],"answer":2,"why":"أسلوبه سلس فصيح يقنع العقل ويؤثر في القلب."},{"type":"tfr","q":"الحرية في فكر الكاتب تعني التفلّت من الواجبات وعدم الالتزام بأي قاعدة.","answer":false,"reasons":["تعني إهمال الدراسة","بل هي حرية مسؤولة منضبطة بالعقل والأخلاق","نعم بلا أي ضابط"],"reason":1},{"type":"tfr","q":"يُصاغ اسم الفاعل من الفعل غير الثلاثي بإبدال حرف المضارعة ميمًا مضمومةً وفتح ما قبل الآخر.","answer":false,"reasons":["بميم مفتوحة","نعم بفتح ما قبل الآخر","بل بـ«كسر» ما قبل الآخر (فتح ما قبل الآخر لاسم المفعول)"],"reason":2}],"hard":[{"type":"mcq","q":"كيف ينظر الكاتب إلى «الأخلاق» في رسالته؟","options":["خاصة بكبار السن","قواعد للحفظ في الاختبار فقط","شيء ثانوي بعد المال","سلوك عملي يظهر في الصدق والمعاملة لا مجرد كلام نظري"],"answer":3,"why":"الأخلاق الحقيقية تُترجم إلى أفعال ومواقف."},{"type":"mcq","q":"ما الغرض البلاغي من أساليب الأمر والنهي في الرسالة؟","options":["النصح والإرشاد والتحذير المشفق","الإلزام القسري والتهديد","التعجيز","التمني"],"answer":0,"why":"أمر الأب لابنه في الرسالة غرضه النصح والإرشاد."},{"type":"mcq","q":"لماذا يرفض الكاتب الاستسلام لفكرة «الحظ والظروف»؟","options":["لأن الظروف لا وجود لها","لأن الإنسان مسؤول عن صناعة مستقبله بعقله وإرادته واجتهاده","لأن العمل غير مهم","لأن الحرية بلا حدود"],"answer":1,"why":"يدعو للإيجابية وتحمّل المسؤولية."},{"type":"essay","q":"اذكر أربع وصايا رئيسة قدّمها أحمد أمين لابنه في الرسالة.","model":"١) استثمار العقل والحرية المسؤولة. ٢) اختيار العمل وفق الميل والقدرة ونفع المجتمع. ٣) إدراك أن السعادة في أداء الواجب. ٤) التحلي بالأخلاق العملية واختيار الصديق الصالح."},{"type":"essay","q":"اشرح كيف تطبّق معايير الكاتب الثلاثة عند اختيار تخصصك المستقبلي في المرحلة الثانوية والجامعة.","model":"أبحث عن التخصص الذي أحبه (الميل)، وأملك فيه مهارة وتفوقًا (القدرة)، ويحتاج إليه وطني عُمان وسوق العمل (نفع المجتمع)."}]},"test":[{"type":"mcq","q":"من كاتب نص «رسالة إلى ابني»؟","options":["الأديب المصري أحمد أمين","طه حسين","عباس العقاد","الجاحظ"],"answer":0,"why":"الأديب والمفكّر أحمد أمين (صاحب فيض الخاطر)."},{"type":"mcq","q":"ما السلاحان العظيمان اللذان يذكّر الكاتب ابنه بأن الله منحهما له؟","options":["المال والجاه","العقل والحرية المسؤولة","السرعة والقوة الجسدية فقط","الحظ والمصادفة"],"answer":1,"why":"العقل للتمييز والحرية للاختيار المسؤول."},{"type":"mcq","q":"وفق النص، ما المعايير الثلاثة لاختيار العمل المناسب؟","options":["تقليد الأصدقاء فقط","الراتب وحده دون رغبة","الميل الشخصي، والقدرة، وفائدة المجتمع","أسهل عمل بلا جهد"],"answer":2,"why":"تجمع بين الرغبة والاستعداد وخدمة الوطن."},{"type":"mcq","q":"أين تكمن «السعادة الحقيقية» في نظر الكاتب؟","options":["في الإسراف واللهو","في الكسل والراحة الدائمة","في تجنّب كل مسؤولية","في القيام بالواجب والشعور بالإنجاز بعد العمل الشريف"],"answer":3,"why":"السعادة ثمرة الإنجاز وأداء الواجب."},{"type":"mcq","q":"ما الغرض البلاغي من نداء الأب لابنه بـ«أي بُنيّ»؟","options":["التحبّب والإشفاق وتهيئة النفس لقبول النصيحة","التوبيخ والغضب","التعجب","الاستفهام"],"answer":0,"why":"التصغير «بُنيّ» يفيض حنانًا ومحبةً أبويةً."},{"type":"mcq","q":"ما الفن النثري الذي ينتمي إليه النص؟","options":["المسرحية","فنّ الرسائل الأدبية التربوية","السيرة الذاتية","التقرير العلمي"],"answer":1,"why":"رسالة أدبية من أب إلى ابنه."},{"type":"mcq","q":"بمَ يتميّز أسلوب أحمد أمين في هذه الرسالة؟","options":["بالسجع المتكلّف","بالألفاظ الغريبة المعقدة","بالوضوح والسلاسة (السهل الممتنع) والمزج بين العاطفة والإقناع العقلي","بالغموض"],"answer":2,"why":"أسلوبه سلس فصيح يقنع العقل ويؤثر في القلب."},{"type":"mcq","q":"كيف ينظر الكاتب إلى «الأخلاق» في رسالته؟","options":["خاصة بكبار السن","قواعد للحفظ في الاختبار فقط","شيء ثانوي بعد المال","سلوك عملي يظهر في الصدق والمعاملة لا مجرد كلام نظري"],"answer":3,"why":"الأخلاق الحقيقية تُترجم إلى أفعال ومواقف."},{"type":"mcq","q":"ما الغرض البلاغي من أساليب الأمر والنهي في الرسالة؟","options":["النصح والإرشاد والتحذير المشفق","الإلزام القسري والتهديد","التعجيز","التمني"],"answer":0,"why":"أمر الأب لابنه في الرسالة غرضه النصح والإرشاد."},{"type":"mcq","q":"لماذا يرفض الكاتب الاستسلام لفكرة «الحظ والظروف»؟","options":["لأن الظروف لا وجود لها","لأن الإنسان مسؤول عن صناعة مستقبله بعقله وإرادته واجتهاده","لأن العمل غير مهم","لأن الحرية بلا حدود"],"answer":1,"why":"يدعو للإيجابية وتحمّل المسؤولية."},{"type":"mcq","q":"ما أثر «الصديق الصالح» كما توحيه الوصايا التربوية؟","options":["يُضعف الطموح","لا أثر للصديق على الإنسان","يعين على الخير والاجتهاد ويرتقي بأخلاق صاحبه","يمنع النجاح"],"answer":2,"why":"الصاحب يؤثر بعمق في السلوك والطموح."},{"type":"mcq","q":"ما اسم الفاعل من الفعل الثلاثي الأجوف «صامَ»؟","options":["مَصوم","صوّام","مُصيم","صائِم"],"answer":3,"why":"تُقلب ألف الأجوف همزةً على نبرة: صائم."},{"type":"tf","q":"يرى أحمد أمين أن السعادة الحقيقية تكون في الكسل وتجنّب العمل الشاق.","answer":false,"why":"بل في القيام بالواجب والشعور بالإنجاز بعد العمل الشريف"},{"type":"tf","q":"استخدام صيغة التصغير «بُنيّ» يدل على المحبة والحنان الأبوي.","answer":true,"why":"ويفتح قلب الابن لتلقي النصائح برضا"},{"type":"tf","q":"ينصح الكاتب باختيار المهنة حسب تقليد الأصدقاء بغضّ النظر عن الميل والقدرة.","answer":false,"why":"بل وفق الميل والقدرة وفائدة المجتمع"},{"type":"tf","q":"جمع الكاتب في رسالته بين العاطفة الأبوية الصادقة والحجة العقلية المقنعة.","answer":true,"why":"مما جعل نصائحه مؤثرة ومقنعة للشباب"},{"type":"tfr","q":"الحرية في فكر الكاتب تعني التفلّت من الواجبات وعدم الالتزام بأي قاعدة.","answer":false,"reasons":["تعني إهمال الدراسة","بل هي حرية مسؤولة منضبطة بالعقل والأخلاق","نعم بلا أي ضابط"],"reason":1},{"type":"tfr","q":"يُصاغ اسم الفاعل من الفعل غير الثلاثي بإبدال حرف المضارعة ميمًا مضمومةً وفتح ما قبل الآخر.","answer":false,"reasons":["بميم مفتوحة","نعم بفتح ما قبل الآخر","بل بـ«كسر» ما قبل الآخر (فتح ما قبل الآخر لاسم المفعول)"],"reason":2},{"type":"tfr","q":"تُحذف ياء اسم الفاعل المشتق من الثلاثي الناقص (مثل قاضٍ) إذا كان نكرةً مرفوعًا أو مجرورًا.","answer":true,"reasons":["ويُعوّض عنها بتنوين الكسر: جاء قاضٍ، سلمتُ على قاضٍ","تُحذف في النصب فقط","لا تُحذف أبدًا"],"reason":0},{"type":"tfr","q":"اسم الفاعل من الفعل «باعَ» هو «بائِع» بقلب الألف همزةً.","answer":true,"reasons":["هو بايِع","وهكذا في كل ثلاثي أجوف كقال وقائل ونام ونائم","هو مَبيع"],"reason":1},{"type":"essay","q":"اذكر أربع وصايا رئيسة قدّمها أحمد أمين لابنه في الرسالة.","model":"١) استثمار العقل والحرية المسؤولة. ٢) اختيار العمل وفق الميل والقدرة ونفع المجتمع. ٣) إدراك أن السعادة في أداء الواجب. ٤) التحلي بالأخلاق العملية واختيار الصديق الصالح."},{"type":"essay","q":"اشرح كيف تطبّق معايير الكاتب الثلاثة عند اختيار تخصصك المستقبلي في المرحلة الثانوية والجامعة.","model":"أبحث عن التخصص الذي أحبه (الميل)، وأملك فيه مهارة وتفوقًا (القدرة)، ويحتاج إليه وطني عُمان وسوق العمل (نفع المجتمع)."},{"type":"essay","q":"لماذا ربط الكاتب بين «السعادة» و«القيام بالواجب»؟","model":"لأن الكسل يورث الملل والفراغ، بينما إتقان الواجب يبعث في النفس الرضا والثقة والفرح بالإنجاز."},{"type":"essay","q":"استخرج سمتين أسلوبيتين من رسالة أحمد أمين مع مثال لكل سمة.","model":"١) النداء للتحبب («أي بنيّ»). ٢) السهولة والوضوح والمزج بين الأمر للنصح والتعليل العقلي."},{"type":"essay","q":"اكتب فقرة قصيرة (٣ أسطر) توجه فيها نصيحةً لأخيك الأصغر بأسلوب «رسالة إلى ابني».","model":"أي أخي العزيز، اجعل من وقتك كنزًا لا يُهدر، وابحث عن سعادتك في إتقان دروسك ومساعدة أسرتك؛ فالعقل والاجتهاد هما جناحاك للوصول إلى أحلامك."}]},
  {"id":"g9-arabic-2-u5","grade":"g9","subject":"arabic","term":2,"title":"الوحدة الخامسة: عُمان والتاريخ","levels":{"easy":[{"type":"mcq","q":"ما الوسيلة الرئيسة التي نشر بها العُمانيون الإسلام في الهند؟","options":["الحروب والغزو العسكري","التجارة السلمية والأخلاق الحسنة والقدوة العملية","إكراه السكان","العزلة والانغلاق"],"answer":1,"why":"الصدق والأمانة وحسن المعاملة هي التي حبّبت أهل الهند في الإسلام."},{"type":"mcq","q":"ما معنى عبارة «القِدْح المُعلّى» الواردة في النص؟","options":["المكانة الضعيفة","الوعاء الفارغ","الدور الأبرز والمكانة العليا والنصيب الأوفر","الميناء الصغير"],"answer":2,"why":"تعبير عربي أصيل يدل على السبق والمكانة العليا."},{"type":"mcq","q":"ما معنى كلمة «الناخوذة» في التراث البحري العُماني؟","options":["حارس الميناء","صانع الشباك","بائع التوابل","ربّان السفينة وقائدها"],"answer":3,"why":"الناخوذة حسن كان ربّانًا عُمانيًا بنى مسجدًا جامعًا في الهند."},{"type":"mcq","q":"من الرحالة الجغرافي الذي ذكر وجود نحو عشرة آلاف عُماني في ميناء «سيمور» بالهند؟","options":["المسعودي","ابن خلدون","المتنبي","الأصمعي"],"answer":0,"why":"شاهد المسعودي ميناء سيمور ووثّق كثرة العُمانيين فيها."}],"medium":[{"type":"mcq","q":"لماذا أقبل كثير من سكان الهند على الدخول في الإسلام طوعًا؟","options":["خوفًا من السفن","لما وجدوا فيه من مساواة وعدالة تنقذهم من الطبقية ولصدق التجار العُمانيين","لأسباب مناخية","بتقليد أعمى"],"answer":1,"why":"العدالة الاجتماعية والمساواة كانتا نقطة جذب كبرى."},{"type":"mcq","q":"ما معنى كلمة «زُهاء» في عبارة «زُهاء عشرة آلاف»؟","options":["ضعف العدد","أقل من عشرة","ما يقرب من (نحو)","بالضبط دون زيادة"],"answer":2,"why":"زهاء تفيد التقريب العددي."},{"type":"mcq","q":"ما مفرد كلمة «الأصقاع» ومعناها؟","options":["صَغار — وتعني الصغر","صَقيع — وتعني الثلج","سَقْف — وتعني السطح","صُقْع — وتعني الناحية والجهة"],"answer":3,"why":"الأصقاع هي النواحي والأماكن البعيدة."},{"type":"tfr","q":"امتدّ دور العُمانيين في نشر الإسلام من سواحل الهند إلى الجزر المحيطة بها في المحيط الهندي.","answer":true,"reasons":["توقف عند ميناء واحد فقط","لم يتجاوز بحر عُمان","بفضل نشاطهم البحري الواسع ومهارتهم الملاحية"],"reason":2},{"type":"tfr","q":"يُشتق اسم المفعول من الفعل المبني للمجهول للدلالة على من وقع عليه الفعل.","answer":true,"reasons":["فإذا قيل ما فعل «مَسموع» نكتب «سُمِعَ» مبنيًا للمجهول","يُشتق من المبني للمعلوم فقط","يدل على من قام بالفعل"],"reason":0}],"hard":[{"type":"mcq","q":"ما الذي يدل على ثقة حكام الهند بالتجار العُمانيين؟","options":["اتخاذهم قادةً للأساطيل وتولي بعضهم القضاء كالقاضي بدر الدين في منجرور","منعهم من دخول الموانئ","فرض ضرائب مضاعفة عليهم","إبعادهم عن السواحل"],"answer":0,"why":"تولي القضاء وقيادة الأساطيل دليل ثقة ومكانة سامية."},{"type":"mcq","q":"كيف أثّر دخول العُمانيين في الإسلام على أهداف رحلاتهم البحرية؟","options":["توقفت رحلاتهم البحرية","تطورت من مجرد تجارة وملاحة لتصبح رسالةً ساميةً لنشر الإسلام والحضارة","اقتصرت على الصيد القريب","لم يتغير شيء"],"answer":1,"why":"أصبح نشر الإسلام من أسمى مقاصدهم مع التجارة."},{"type":"mcq","q":"من الذي بنى مسجدًا جامعًا كبيرًا على الساحل الهندي كما ورد في النص؟","options":["أحمد بن ماجد","عمرو بن العاص","الناخوذة حسن العُماني","عباس بن فرناس"],"answer":2,"why":"الناخوذة حسن أحد الملاحين العُمانيين."},{"type":"essay","q":"كيف أسهم الموقع الجغرافي لعُمان في قيام العُمانيين بدورهم الحضاري في الهند؟","model":"إطلالة عُمان على بحر العرب والمحيط الهندي وسواحلها الممتدة وموانئها المزدهرة كصحار جعلت العُمانيين مهرةً في الملاحة، فوصلوا بأساطيلهم إلى الهند وشرقي إفريقيا."},{"type":"essay","q":"اذكر ثلاثة أدلة تاريخية من النص تثبت المكانة الرفيعة للعُمانيين في الهند.","model":"١) وجود نحو عشرة آلاف عُماني في ميناء سيمور بشهادة المسعودي. ٢) تولّي القاضي العُماني بدر الدين القضاء في منجرور واتخاذ قادة أساطيل منهم. ٣) بناء الناخوذة حسن لمسجد جامع كبير على الساحل الهندي."}]},"test":[{"type":"mcq","q":"ما الوسيلة الرئيسة التي نشر بها العُمانيون الإسلام في الهند؟","options":["الحروب والغزو العسكري","التجارة السلمية والأخلاق الحسنة والقدوة العملية","إكراه السكان","العزلة والانغلاق"],"answer":1,"why":"الصدق والأمانة وحسن المعاملة هي التي حبّبت أهل الهند في الإسلام."},{"type":"mcq","q":"ما معنى عبارة «القِدْح المُعلّى» الواردة في النص؟","options":["المكانة الضعيفة","الوعاء الفارغ","الدور الأبرز والمكانة العليا والنصيب الأوفر","الميناء الصغير"],"answer":2,"why":"تعبير عربي أصيل يدل على السبق والمكانة العليا."},{"type":"mcq","q":"ما معنى كلمة «الناخوذة» في التراث البحري العُماني؟","options":["حارس الميناء","صانع الشباك","بائع التوابل","ربّان السفينة وقائدها"],"answer":3,"why":"الناخوذة حسن كان ربّانًا عُمانيًا بنى مسجدًا جامعًا في الهند."},{"type":"mcq","q":"من الرحالة الجغرافي الذي ذكر وجود نحو عشرة آلاف عُماني في ميناء «سيمور» بالهند؟","options":["المسعودي","ابن خلدون","المتنبي","الأصمعي"],"answer":0,"why":"شاهد المسعودي ميناء سيمور ووثّق كثرة العُمانيين فيها."},{"type":"mcq","q":"لماذا أقبل كثير من سكان الهند على الدخول في الإسلام طوعًا؟","options":["خوفًا من السفن","لما وجدوا فيه من مساواة وعدالة تنقذهم من الطبقية ولصدق التجار العُمانيين","لأسباب مناخية","بتقليد أعمى"],"answer":1,"why":"العدالة الاجتماعية والمساواة كانتا نقطة جذب كبرى."},{"type":"mcq","q":"ما معنى كلمة «زُهاء» في عبارة «زُهاء عشرة آلاف»؟","options":["ضعف العدد","أقل من عشرة","ما يقرب من (نحو)","بالضبط دون زيادة"],"answer":2,"why":"زهاء تفيد التقريب العددي."},{"type":"mcq","q":"ما مفرد كلمة «الأصقاع» ومعناها؟","options":["صَغار — وتعني الصغر","صَقيع — وتعني الثلج","سَقْف — وتعني السطح","صُقْع — وتعني الناحية والجهة"],"answer":3,"why":"الأصقاع هي النواحي والأماكن البعيدة."},{"type":"mcq","q":"ما الذي يدل على ثقة حكام الهند بالتجار العُمانيين؟","options":["اتخاذهم قادةً للأساطيل وتولي بعضهم القضاء كالقاضي بدر الدين في منجرور","منعهم من دخول الموانئ","فرض ضرائب مضاعفة عليهم","إبعادهم عن السواحل"],"answer":0,"why":"تولي القضاء وقيادة الأساطيل دليل ثقة ومكانة سامية."},{"type":"mcq","q":"كيف أثّر دخول العُمانيين في الإسلام على أهداف رحلاتهم البحرية؟","options":["توقفت رحلاتهم البحرية","تطورت من مجرد تجارة وملاحة لتصبح رسالةً ساميةً لنشر الإسلام والحضارة","اقتصرت على الصيد القريب","لم يتغير شيء"],"answer":1,"why":"أصبح نشر الإسلام من أسمى مقاصدهم مع التجارة."},{"type":"mcq","q":"من الذي بنى مسجدًا جامعًا كبيرًا على الساحل الهندي كما ورد في النص؟","options":["أحمد بن ماجد","عمرو بن العاص","الناخوذة حسن العُماني","عباس بن فرناس"],"answer":2,"why":"الناخوذة حسن أحد الملاحين العُمانيين."},{"type":"mcq","q":"ما موقف البرتغاليين من الوجود الإسلامي والعربي في الهند؟","options":["انسحبوا فورًا دون صراع","ساعدوا في بناء المساجد","تحالفوا مع التجار العُمانيين","حاولوا القضاء عليه لأنه يهدد نفوذهم التجاري والسياسي"],"answer":3,"why":"قاوم المسلمون والعُمانيون السيطرة البرتغالية."},{"type":"mcq","q":"ما اسم المفعول من الفعل الثلاثي الأجوف «بِيعَ» (باعَ)؟","options":["مَبيع","بائِع","مَبيوع","مُباع"],"answer":0,"why":"مضارعه يَبيع ← نبدل الياء ميمًا مفتوحةً: مَبيع."},{"type":"tf","q":"انتشر الإسلام في الهند على يد العُمانيين بالحكمة والقدوة الحسنة والتجارة السلمية لا بالعنف.","answer":true,"why":"فقد جذب صدقهم وأمانتهم وعدالة الإسلام قلوب أهل الهند"},{"type":"tf","q":"تعني كلمة «الناخوذة» القاضي في المحكمة.","answer":false,"why":"بل تعني ربّان السفينة وقائدها"},{"type":"tf","q":"وثّق الرحالة العرب كالمسعودي والمقدسي ازدهار الموانئ العُمانية وحضور العُمانيين في الهند.","answer":true,"why":"وهو دليل تاريخي موثّق على عظمة الدور الحضاري العُماني"},{"type":"tf","q":"اقتصر أثر العُمانيين في الهند على بيع السلع دون أي أثر علمي أو ديني أو عمراني.","answer":false,"why":"بل بنوا المساجد وتولّوا القضاء ونشروا العلم والإسلام والحضارة"},{"type":"tfr","q":"امتدّ دور العُمانيين في نشر الإسلام من سواحل الهند إلى الجزر المحيطة بها في المحيط الهندي.","answer":true,"reasons":["توقف عند ميناء واحد فقط","لم يتجاوز بحر عُمان","بفضل نشاطهم البحري الواسع ومهارتهم الملاحية"],"reason":2},{"type":"tfr","q":"يُشتق اسم المفعول من الفعل المبني للمجهول للدلالة على من وقع عليه الفعل.","answer":true,"reasons":["فإذا قيل ما فعل «مَسموع» نكتب «سُمِعَ» مبنيًا للمجهول","يُشتق من المبني للمعلوم فقط","يدل على من قام بالفعل"],"reason":0},{"type":"tfr","q":"اسم المفعول من الفعل «باعَ» هو «مَبيوع».","answer":false,"reasons":["الصواب بائع","الصواب «مَبيع» بحذف واو مفعول","نعم مبيوع"],"reason":1},{"type":"tfr","q":"يُصاغ اسم المفعول من الفعل غير الثلاثي بميم مضمومة وفتح ما قبل الآخر.","answer":true,"reasons":["على وزن مفعول","بكسر ما قبل الآخر","مثل: أُكرِمَ ← مُكرَم، اسْتُعمِلَ ← مُستعمَل"],"reason":2},{"type":"essay","q":"كيف أسهم الموقع الجغرافي لعُمان في قيام العُمانيين بدورهم الحضاري في الهند؟","model":"إطلالة عُمان على بحر العرب والمحيط الهندي وسواحلها الممتدة وموانئها المزدهرة كصحار جعلت العُمانيين مهرةً في الملاحة، فوصلوا بأساطيلهم إلى الهند وشرقي إفريقيا."},{"type":"essay","q":"اذكر ثلاثة أدلة تاريخية من النص تثبت المكانة الرفيعة للعُمانيين في الهند.","model":"١) وجود نحو عشرة آلاف عُماني في ميناء سيمور بشهادة المسعودي. ٢) تولّي القاضي العُماني بدر الدين القضاء في منجرور واتخاذ قادة أساطيل منهم. ٣) بناء الناخوذة حسن لمسجد جامع كبير على الساحل الهندي."},{"type":"essay","q":"فسّر لماذا وجد أهل الهند في الإسلام ملاذًا اجتماعيًا.","model":"لأن الإسلام نادى بالمساواة والعدالة وكرامة الإنسان، مما أنقذ كثيرًا منهم من نظام الطبقية والعنصرية."},{"type":"essay","q":"اشرح معاني المفردات الآتية: القدح المعلّى، الناخوذة، زُهاء، الأصقاع.","model":"القدح المعلّى: الدور الأبرز والمكانة العليا. الناخوذة: ربان السفينة. زهاء: ما يقرب من. الأصقاع: النواحي والأماكن."},{"type":"essay","q":"ما الدرس الذي يستلهمه الطالب العُماني اليوم من سيرة التجار العُمانيين في الهند؟","model":"أن الأخلاق الرفيعة (الصدق والأمانة والتسامح وإتقان العمل) هي أعظم سفير للدين والوطن في أي مكان في العالم."}]},
  {"id":"g9-arabic-2-u6","grade":"g9","subject":"arabic","term":2,"title":"الوحدة السادسة: اللغة والإبداع","levels":{"easy":[{"type":"mcq","q":"ما الصورة الفنية في عنوان النص «اللغة تلد الحضارة»؟","options":["طباق","ترادف لفظي","استعارة مكنية شبّهت اللغة بأمٍّ تلد الحضارة وترعاها","جناس تام"],"answer":2,"why":"حُذف المشبه به (الأم) وأُشير إليه بلازمه (تلد)."},{"type":"mcq","q":"لماذا تُعدّ اللغة أساسًا لقيام أي حضارة إنسانية؟","options":["لأنها بديل عن العمل","لأنها تُستخدم في الشعر فقط","لأنها تمنع التواصل","لأنها وعاء الفكر وأداة حفظ العلوم ونقل الخبرات وتنظيم المجتمع"],"answer":3,"why":"لا يمكن بناء علم أو تعاون مجتمعي دون لغة دقيقة."},{"type":"mcq","q":"ما الميزة اللغوية التي تمنح العربية قدرةً فائقةً على توليد مصطلحات علمية جديدة؟","options":["نظام الاشتقاق الغني (مثل: حاسوب من حسب، وهاتف من هتف)","قلة عدد حروفها","عدم وجود قواعد فيها","الاعتماد على لغة واحدة فقط"],"answer":0,"why":"الاشتقاق يولّد كلمات دقيقة من الجذور العربية الأصيلة."},{"type":"mcq","q":"ما الموقف المتوازن تجاه تعلّم اللغات الأجنبية؟","options":["نهمل العربية تمامًا لصالحها","نتعلمها للاستفادة من العلوم والتواصل مع الاعتزاز بلغتنا الأم وإتقانها","نرفض تعلم أي لغة أجنبية","نخلط اللغات في كل جملة"],"answer":1,"why":"الانفتاح الواعي يجمع الاعتزاز بالعربية وإتقان لغات العالم."}],"medium":[{"type":"mcq","q":"ما الدليل التاريخي على أن اللغة العربية لغة علم وحضارة؟","options":["أنها خالية من المصطلحات","أنها أقدم لغة مكتوبة فقط","استيعابها وإبداعها في الطب والفلك والرياضيات والبصريات في العصر الذهبي","أنها لغة محادثة فقط"],"answer":2,"why":"كانت العربية لغة العلم العالمية لقرون طويلة."},{"type":"mcq","q":"ما العلاقة بين ثراء لغة الإنسان وقدرته على التفكير؟","options":["اللغة تُضعف التفكير","علاقة عكسية","لا علاقة بينهما","علاقة طردية: كلما دقّت اللغة اتضح التفكير وزاد الإبداع"],"answer":3,"why":"الإنسان يفكّر بالكلمات والمفاهيم اللغوية."},{"type":"mcq","q":"من أبرز التحديات المعاصرة التي تواجه اللغة العربية:","options":["ضعف المحتوى العلمي الرقمي وشيوع الكتابة الركيكة في وسائل التواصل","قلة المتحدثين بها في العالم","عجزها عن الاشتقاق","خلوّها من المعاجم"],"answer":0,"why":"التحدي الحقيقي في الإنتاج العلمي والرقمي العربي."},{"type":"tfr","q":"أثبت التاريخ في العصر الذهبي أن العربية قادرة على استيعاب جميع العلوم التجريبية والنظرية.","answer":true,"reasons":["حيث أُلّفت بها أمهات كتب الطب والرياضيات والفلك والبصريات","اقتصر دورها على الشعر فقط","لم تُستخدم في العلوم"],"reason":0},{"type":"tfr","q":"الأوزان القياسية الخمسة لصيغ المبالغة هي: فَعّال، مِفْعال، فَعُول، فَعِيل، فَعِل.","answer":true,"reasons":["هي ثلاثة أوزان فقط","وتجمعها عبارة: هو مقوال كذاب وأنت حذر والله غفور رحيم","منها مفعول وفاعل"],"reason":1}],"hard":[{"type":"mcq","q":"كيف يُسهم الشباب اليوم عمليًا في تعزيز مكانة العربية؟","options":["بالكتابة بحروف لاتينية بدل العربية","بإنتاج محتوى علمي وتعليمي رقمي عربي رصين والحرص على الكتابة السليمة","بترك القراءة","بالتخلي عن الفصحى"],"answer":1,"why":"إثراء الإنترنت بالعلم العربي يرفع مكانة اللغة."},{"type":"mcq","q":"ما المقصود بوصف اللغة بأنها «ذاكرة الأمة»؟","options":["أنها كتاب تاريخ واحد","أنها تقتصر على الماضي فقط","أنها تحفظ تاريخ الأمة ودينها وتراثها وعلومها عبر الأجيال","أنها لا تتطور"],"answer":2,"why":"بفضل اللغة تتواصل الأجيال وتقرأ تراثها."},{"type":"mcq","q":"نوع نص «اللغة تلد الحضارة» هو:","options":["قصيدة رثاء","تقرير ميداني","قصة خيالية","مقال فكري ثقافي"],"answer":3,"why":"يناقش قضية فكرية حضارية بالأدلة."},{"type":"essay","q":"اشرح المقصود بعنوان الدرس «اللغة تلد الحضارة» مبينًا الجمال الفني فيه.","model":"شبّه الكاتب اللغة بالأم التي تلد الحضارة وترعاها؛ لأن اللغة هي وعاء الفكر وأداة حفظ العلوم ونقل الخبرات التي تقوم عليها كل حضارة."},{"type":"essay","q":"اذكر ثلاثة مقومات تجعل اللغة العربية قادرةً على مواكبة علوم العصر الحديث.","model":"١) نظام الاشتقاق الخصب لتوليد المصطلحات. ٢) ثراء المفردات والمرونة في التعريب. ٣) تجربتها التاريخية الناجحة في استيعاب علوم العالم."}]},"test":[{"type":"mcq","q":"ما الصورة الفنية في عنوان النص «اللغة تلد الحضارة»؟","options":["طباق","ترادف لفظي","استعارة مكنية شبّهت اللغة بأمٍّ تلد الحضارة وترعاها","جناس تام"],"answer":2,"why":"حُذف المشبه به (الأم) وأُشير إليه بلازمه (تلد)."},{"type":"mcq","q":"لماذا تُعدّ اللغة أساسًا لقيام أي حضارة إنسانية؟","options":["لأنها بديل عن العمل","لأنها تُستخدم في الشعر فقط","لأنها تمنع التواصل","لأنها وعاء الفكر وأداة حفظ العلوم ونقل الخبرات وتنظيم المجتمع"],"answer":3,"why":"لا يمكن بناء علم أو تعاون مجتمعي دون لغة دقيقة."},{"type":"mcq","q":"ما الميزة اللغوية التي تمنح العربية قدرةً فائقةً على توليد مصطلحات علمية جديدة؟","options":["نظام الاشتقاق الغني (مثل: حاسوب من حسب، وهاتف من هتف)","قلة عدد حروفها","عدم وجود قواعد فيها","الاعتماد على لغة واحدة فقط"],"answer":0,"why":"الاشتقاق يولّد كلمات دقيقة من الجذور العربية الأصيلة."},{"type":"mcq","q":"ما الموقف المتوازن تجاه تعلّم اللغات الأجنبية؟","options":["نهمل العربية تمامًا لصالحها","نتعلمها للاستفادة من العلوم والتواصل مع الاعتزاز بلغتنا الأم وإتقانها","نرفض تعلم أي لغة أجنبية","نخلط اللغات في كل جملة"],"answer":1,"why":"الانفتاح الواعي يجمع الاعتزاز بالعربية وإتقان لغات العالم."},{"type":"mcq","q":"ما الدليل التاريخي على أن اللغة العربية لغة علم وحضارة؟","options":["أنها خالية من المصطلحات","أنها أقدم لغة مكتوبة فقط","استيعابها وإبداعها في الطب والفلك والرياضيات والبصريات في العصر الذهبي","أنها لغة محادثة فقط"],"answer":2,"why":"كانت العربية لغة العلم العالمية لقرون طويلة."},{"type":"mcq","q":"ما العلاقة بين ثراء لغة الإنسان وقدرته على التفكير؟","options":["اللغة تُضعف التفكير","علاقة عكسية","لا علاقة بينهما","علاقة طردية: كلما دقّت اللغة اتضح التفكير وزاد الإبداع"],"answer":3,"why":"الإنسان يفكّر بالكلمات والمفاهيم اللغوية."},{"type":"mcq","q":"من أبرز التحديات المعاصرة التي تواجه اللغة العربية:","options":["ضعف المحتوى العلمي الرقمي وشيوع الكتابة الركيكة في وسائل التواصل","قلة المتحدثين بها في العالم","عجزها عن الاشتقاق","خلوّها من المعاجم"],"answer":0,"why":"التحدي الحقيقي في الإنتاج العلمي والرقمي العربي."},{"type":"mcq","q":"كيف يُسهم الشباب اليوم عمليًا في تعزيز مكانة العربية؟","options":["بالكتابة بحروف لاتينية بدل العربية","بإنتاج محتوى علمي وتعليمي رقمي عربي رصين والحرص على الكتابة السليمة","بترك القراءة","بالتخلي عن الفصحى"],"answer":1,"why":"إثراء الإنترنت بالعلم العربي يرفع مكانة اللغة."},{"type":"mcq","q":"ما المقصود بوصف اللغة بأنها «ذاكرة الأمة»؟","options":["أنها كتاب تاريخ واحد","أنها تقتصر على الماضي فقط","أنها تحفظ تاريخ الأمة ودينها وتراثها وعلومها عبر الأجيال","أنها لا تتطور"],"answer":2,"why":"بفضل اللغة تتواصل الأجيال وتقرأ تراثها."},{"type":"mcq","q":"نوع نص «اللغة تلد الحضارة» هو:","options":["قصيدة رثاء","تقرير ميداني","قصة خيالية","مقال فكري ثقافي"],"answer":3,"why":"يناقش قضية فكرية حضارية بالأدلة."},{"type":"mcq","q":"عندما تضعف اللغة لدى أمة ما، فإن النتيجة المباشرة تكون:","options":["ضعف التفكير والإبداع وتراجع الهوية الحضارية","ازدهار العلوم فورًا","زيادة الاستقلالية","لا يحدث أي تأثير"],"answer":0,"why":"تراجع اللغة ينعكس مباشرةً على الفكر والهوية."},{"type":"mcq","q":"أي الأوزان الآتية «ليس» من الأوزان القياسية الخمسة لصيغ المبالغة؟","options":["فَعِل","مَفعول","مِفْعال","فَعّال"],"answer":1,"why":"مَفعول هو وزن اسم المفعول من الثلاثي وليس صيغة مبالغة."},{"type":"tf","q":"العجز عن إنتاج مصطلحات علمية حديثة سببه قصور في اللغة العربية نفسها.","answer":false,"why":"بل العربية غنية جدًا بالاشتقاق، والقصور في الإنتاج العلمي والبحثي لأبنائها"},{"type":"tf","q":"تعلّم اللغات الأجنبية نافع بشرط ألا يكون على حساب إهمال اللغة العربية الأم.","answer":true,"why":"فالمثقف الواعي يعتز بلغته وينفتح على لغات العالم"},{"type":"tf","q":"اللغة ليست مجرد أداة تواصل سطحي بل هي وعاء الفكر ومحرك الحضارة.","answer":true,"why":"لأن التفكير والإبداع ونقل العلوم كلها تتم عبر اللغة"},{"type":"tf","q":"بناء منصات ومحتوى تعليمي عربي رصين على الإنترنت يُعدّ خدمةً حضاريةً للغة العربية.","answer":true,"why":"لأنه يعالج فجوة المحتوى الرقمي العربي ويدعم الطلاب"},{"type":"tfr","q":"أثبت التاريخ في العصر الذهبي أن العربية قادرة على استيعاب جميع العلوم التجريبية والنظرية.","answer":true,"reasons":["حيث أُلّفت بها أمهات كتب الطب والرياضيات والفلك والبصريات","اقتصر دورها على الشعر فقط","لم تُستخدم في العلوم"],"reason":0},{"type":"tfr","q":"الأوزان القياسية الخمسة لصيغ المبالغة هي: فَعّال، مِفْعال، فَعُول، فَعِيل، فَعِل.","answer":true,"reasons":["هي ثلاثة أوزان فقط","وتجمعها عبارة: هو مقوال كذاب وأنت حذر والله غفور رحيم","منها مفعول وفاعل"],"reason":1},{"type":"tfr","q":"كلمة «مِنشار» في جملة «قطع النجارُ الخشبَ بالمِنشار» تُعدّ صيغة مبالغة.","answer":false,"reasons":["نعم صيغة مبالغة","هي اسم فاعل","هنا هي «اسم آلة» لأنها تدل على أداة القطع لا على كثرة الفعل"],"reason":2},{"type":"tfr","q":"تُشتق صيغ المبالغة من الثلاثي غالبًا، وقد تأتي قليلًا من الرباعي مثل مِعطاء ونَذير.","answer":true,"reasons":["مِعطاء من أعطى، مِقدام من أقدم، نذير من أنذر","تُشتق من السداسي فقط","لا تأتي من الرباعي أبدًا"],"reason":0},{"type":"essay","q":"اشرح المقصود بعنوان الدرس «اللغة تلد الحضارة» مبينًا الجمال الفني فيه.","model":"شبّه الكاتب اللغة بالأم التي تلد الحضارة وترعاها؛ لأن اللغة هي وعاء الفكر وأداة حفظ العلوم ونقل الخبرات التي تقوم عليها كل حضارة."},{"type":"essay","q":"اذكر ثلاثة مقومات تجعل اللغة العربية قادرةً على مواكبة علوم العصر الحديث.","model":"١) نظام الاشتقاق الخصب لتوليد المصطلحات. ٢) ثراء المفردات والمرونة في التعريب. ٣) تجربتها التاريخية الناجحة في استيعاب علوم العالم."},{"type":"essay","q":"كيف نوفّق بين «تعلّم اللغة الإنجليزية واللغات الحديثة» وبين «الحفاظ على لغتنا العربية»؟","model":"بإتقان العربية أولًا واستخدامها في التواصل والكتابة والبحث مع الاعتزاز بها، وتعلّم اللغات الأخرى كوسيلة للانفتاح العلمي والمهني دون إهمال هويتنا."},{"type":"essay","q":"اقترح ثلاث مبادرات طلابية لخدمة اللغة العربية في مدرستك أو عبر الإنترنت.","model":"١) إنشاء نادٍ للقراءة وتلخيص الكتب العلمية بالعربية. ٢) بناء منصات ومحتوى تعليمي عربي رقمي سليم. ٣) إطلاق حملة للكتابة العربية السليمة دون أخطاء إملائية."},{"type":"essay","q":"علّل: لماذا تحرص الدول المتقدمة علميًا على تدريس العلوم بلُغتها الأم؟","model":"لأن فهم الطالب للعلوم وتفكيره الإبداعي يكونان أعمق وأسرع حين يتعلم بلغته التي يفكّر بها منذ طفولته."}]},
  {"id":"g9-arabic-2-u7","grade":"g9","subject":"arabic","term":2,"title":"الوحدة السابعة: آفاق العلم والأدب","levels":{"easy":[{"type":"mcq","q":"من العالم الذي اكتشف الأشعة السينية (X-rays)؟","options":["توماس إديسون","إسحاق نيوتن","لويس باستور","العالم الألماني فيلهلم رونتجن"],"answer":3,"why":"فيلهلم رونتجن اكتشفها عام ١٨٩٥م ونال بها أول جائزة نوبل في الفيزياء."},{"type":"mcq","q":"لماذا أطلق النص على رونتجن صفة «نسّاء»؟","options":["لكثرة نسيانه لمواعيد طعامه وما يريد فعله لشدة انغماسه في أبحاثه","لأنه نسي اسمه","لأنه لم يدرس الفيزياء","لأنه لم يجرِ تجارب"],"answer":0,"why":"نسّاء صيغة مبالغة على وزن فعّال تعني كثير النسيان."},{"type":"mcq","q":"ما العلاقة البلاغية بين «نسّاء» و«لن ينساها» في عنوان الدرس؟","options":["ترادف","طباق يثير التشويق ويبرز المفارقة الجميلة","سجع","استفهام"],"answer":1,"why":"المفارقة بين كثرة نسيانه وخلود اكتشافه تشدّ القارئ."},{"type":"mcq","q":"لماذا سُمّيت هذه الأشعة بـ«الأشعة السينية (X-rays)»؟","options":["لأنها سريعة جدًا فقط","نسبةً إلى مدينة تبدأ بحرف السين","نسبةً إلى رمز المجهول (X في الإنجليزية و«س» في العربية) لجهله بطبيعتها أولًا","نسبةً لاسم زوجته"],"answer":2,"why":"X و«س» هما رمزا المجهول في الرياضيات."}],"medium":[{"type":"mcq","q":"ما الدور الذي لعبه «مفتاح مكتب رونتجن» في قصة الاكتشاف؟","options":["لم يكن له أي دور","فتح به باب المختبر فقط","كسر به الأنبوب الزجاجي","ظهر ظلّ المفتاح المعدني واضحًا على اللوح الفوتوغرافي بعد تحميضه مما أكد نفاذ الأشعة"],"answer":3,"why":"ظهور ظل المفتاح عبر الغلاف أثبت وجود أشعة نافذة تخترق الورق."},{"type":"mcq","q":"أي مما يأتي «ليس» من استخدامات الأشعة السينية في الطب؟","options":["توليد الكهرباء في السدود","تصوير الكسور في العظام","كشف تسوس الأسنان","تحديد موضع الأجسام المعدنية المبتلعة"],"answer":0,"why":"توليد الكهرباء ليس من استخدامات الأشعة السينية."},{"type":"mcq","q":"كيف تُسهم الأشعة السينية في تعزيز الثقة التجارية والأمنية؟","options":["في طهي الطعام","في فحص الحقائب بالمطارات وكشف أوراق النقد واللؤلؤ المزيف","في زراعة الأشجار","في قياس سرعة الرياح"],"answer":1,"why":"تكشف بنية المواد الداخلية دون إتلافها."},{"type":"tfr","q":"كلمة «نسّاء» في عنوان الدرس صيغة مبالغة على وزن «فَعّال».","answer":true,"reasons":["هي اسم آلة","وتعني كثير النسيان (من الفعل نسيَ)","هي جمع امرأة"],"reason":1},{"type":"tfr","q":"يأتي اسم المكان والزمان من الفعل الثلاثي الناقص (مثل سعى ورمى) على وزن «مَفْعَل» بفتح العين دائمًا.","answer":true,"reasons":["يأتي على مِفْعال","يأتي على مَفْعِل بالكسر","مثل: مَسعى، مَرمى، مَجرى، مَأوى"],"reason":2}],"hard":[{"type":"mcq","q":"ما الموقف الأخلاقي العظيم الذي اتخذه رونتجن بعد اكتشافه؟","options":["أخفى الاكتشاف عشرين سنة","باع الاكتشاف بأعلى ثمن ومنع المستشفيات منه","رفض احتكار براءة الاختراع ووهب الاكتشاف مجانًا لخدمة البشرية","دمّر أجهزته"],"answer":2,"why":"ضرب مثلًا عالميًا في نبل العلماء."},{"type":"mcq","q":"ما أول صورة طبية شهيرة التقطها رونتجن بالأشعة السينية؟","options":["صورة لشجرة","صورة لأسد","صورة لمدينة برلين","صورة لعظام يد زوجته وخاتمها المعدني"],"answer":3,"why":"أذهلت صورة عظام يد زوجته العالم أجمع."},{"type":"mcq","q":"ما معنى كلمة «المحارة» في سياق الكشف عن اللؤلؤ؟","options":["الصدفة البحرية التي يتكوّن بداخلها اللؤلؤ","الشبكة الحديدية","السفينة الكبيرة","موج البحر"],"answer":0,"why":"المحارة هي الصدفة البحرية."},{"type":"essay","q":"اشرح العلاقة بين اسم الأشعة بالإنجليزية (X-rays) واسمها بالعربية (الأشعة السينية).","model":"أطلق عليها رونتجن «X» وهو رمز المجهول في الرياضيات الإنجليزية لجهله بطبيعتها أولًا، وعند التعريب استُخدم رمز المجهول في الجبر العربي «س» فسمّيت «الأشعة السينية»."},{"type":"essay","q":"اذكر ثلاثة استخدامات طبية واستخدامين غير طبيين للأشعة السينية.","model":"طبية: ١) تصوير كسور العظام. ٢) فحص الأسنان. ٣) كشف الأجسام المعدنية المبتلعة. غير طبية: ١) فحص الحقائب في المطارات. ٢) كشف النقود المزيفة والشقوق في المعادن."}]},"test":[{"type":"mcq","q":"من العالم الذي اكتشف الأشعة السينية (X-rays)؟","options":["توماس إديسون","إسحاق نيوتن","لويس باستور","العالم الألماني فيلهلم رونتجن"],"answer":3,"why":"فيلهلم رونتجن اكتشفها عام ١٨٩٥م ونال بها أول جائزة نوبل في الفيزياء."},{"type":"mcq","q":"لماذا أطلق النص على رونتجن صفة «نسّاء»؟","options":["لكثرة نسيانه لمواعيد طعامه وما يريد فعله لشدة انغماسه في أبحاثه","لأنه نسي اسمه","لأنه لم يدرس الفيزياء","لأنه لم يجرِ تجارب"],"answer":0,"why":"نسّاء صيغة مبالغة على وزن فعّال تعني كثير النسيان."},{"type":"mcq","q":"ما العلاقة البلاغية بين «نسّاء» و«لن ينساها» في عنوان الدرس؟","options":["ترادف","طباق يثير التشويق ويبرز المفارقة الجميلة","سجع","استفهام"],"answer":1,"why":"المفارقة بين كثرة نسيانه وخلود اكتشافه تشدّ القارئ."},{"type":"mcq","q":"لماذا سُمّيت هذه الأشعة بـ«الأشعة السينية (X-rays)»؟","options":["لأنها سريعة جدًا فقط","نسبةً إلى مدينة تبدأ بحرف السين","نسبةً إلى رمز المجهول (X في الإنجليزية و«س» في العربية) لجهله بطبيعتها أولًا","نسبةً لاسم زوجته"],"answer":2,"why":"X و«س» هما رمزا المجهول في الرياضيات."},{"type":"mcq","q":"ما الدور الذي لعبه «مفتاح مكتب رونتجن» في قصة الاكتشاف؟","options":["لم يكن له أي دور","فتح به باب المختبر فقط","كسر به الأنبوب الزجاجي","ظهر ظلّ المفتاح المعدني واضحًا على اللوح الفوتوغرافي بعد تحميضه مما أكد نفاذ الأشعة"],"answer":3,"why":"ظهور ظل المفتاح عبر الغلاف أثبت وجود أشعة نافذة تخترق الورق."},{"type":"mcq","q":"أي مما يأتي «ليس» من استخدامات الأشعة السينية في الطب؟","options":["توليد الكهرباء في السدود","تصوير الكسور في العظام","كشف تسوس الأسنان","تحديد موضع الأجسام المعدنية المبتلعة"],"answer":0,"why":"توليد الكهرباء ليس من استخدامات الأشعة السينية."},{"type":"mcq","q":"كيف تُسهم الأشعة السينية في تعزيز الثقة التجارية والأمنية؟","options":["في طهي الطعام","في فحص الحقائب بالمطارات وكشف أوراق النقد واللؤلؤ المزيف","في زراعة الأشجار","في قياس سرعة الرياح"],"answer":1,"why":"تكشف بنية المواد الداخلية دون إتلافها."},{"type":"mcq","q":"ما الموقف الأخلاقي العظيم الذي اتخذه رونتجن بعد اكتشافه؟","options":["أخفى الاكتشاف عشرين سنة","باع الاكتشاف بأعلى ثمن ومنع المستشفيات منه","رفض احتكار براءة الاختراع ووهب الاكتشاف مجانًا لخدمة البشرية","دمّر أجهزته"],"answer":2,"why":"ضرب مثلًا عالميًا في نبل العلماء."},{"type":"mcq","q":"ما أول صورة طبية شهيرة التقطها رونتجن بالأشعة السينية؟","options":["صورة لشجرة","صورة لأسد","صورة لمدينة برلين","صورة لعظام يد زوجته وخاتمها المعدني"],"answer":3,"why":"أذهلت صورة عظام يد زوجته العالم أجمع."},{"type":"mcq","q":"ما معنى كلمة «المحارة» في سياق الكشف عن اللؤلؤ؟","options":["الصدفة البحرية التي يتكوّن بداخلها اللؤلؤ","الشبكة الحديدية","السفينة الكبيرة","موج البحر"],"answer":0,"why":"المحارة هي الصدفة البحرية."},{"type":"mcq","q":"ما نوع أسلوب نص «نسّاء يكتشف أشعة لن ينساها التاريخ»؟","options":["أسلوب قانوني جاف","أسلوب علمي متأدّب يجمع التشويق القصصي والحقائق العلمية","شعر عمودي","تقرير مالي"],"answer":1,"why":"يبسّط قصة اكتشاف علمي بلغة أدبية مشوّقة."},{"type":"mcq","q":"ما وزن اسم المكان «مَوقِف» ولماذا كُسرت ما قبل آخره؟","options":["مِفْعال — لأنه اسم آلة","مَفْعَل — لأنه مضموم العين","مَفْعِل — لأنه من فعل ثلاثي مثال واوي (وَقَفَ)","مُفعَل — لأنه رباعي"],"answer":2,"why":"المثال الواوي مثل وقف ووعد وولد يأتي على مَفْعِل."},{"type":"tf","q":"سُمّيت الأشعة السينية بهذا الاسم لأن «س» بالعربية تقابل «X» بالإنجليزية رمزًا للمجهول.","answer":true,"why":"فقد أطلق عليها رونتجن أشعة X لأنه لم يعرف طبيعتها في البداية"},{"type":"tf","q":"الصدفة وحدها دون ملاحظة وعقل علمي مستعد تكفي لتحقيق الاكتشافات الكبرى.","answer":false,"why":"الصدفة لا تنفع إلا عقلًا متيقظًا ملاحظًا ومثابرًا كعقل رونتجن"},{"type":"tf","q":"تُستخدم الأشعة السينية في المجال الطبي لتصوير العظام والأسنان، وفي المطارات لفحص الحقائب.","answer":true,"why":"بفضل قدرتها على اختراق الأنسجة والورق وتوقفها عند العظام والمعادن"},{"type":"tf","q":"احتكر رونتجن براءة اختراع الأشعة السينية ليحقق ثروةً شخصيةً ضخمةً.","answer":false,"why":"بل رفض احتكارها ووهب اكتشافه مجانًا للبشرية جمعاء"},{"type":"tfr","q":"كلمة «نسّاء» في عنوان الدرس صيغة مبالغة على وزن «فَعّال».","answer":true,"reasons":["هي اسم آلة","وتعني كثير النسيان (من الفعل نسيَ)","هي جمع امرأة"],"reason":1},{"type":"tfr","q":"يأتي اسم المكان والزمان من الفعل الثلاثي الناقص (مثل سعى ورمى) على وزن «مَفْعَل» بفتح العين دائمًا.","answer":true,"reasons":["يأتي على مِفْعال","يأتي على مَفْعِل بالكسر","مثل: مَسعى، مَرمى، مَجرى، مَأوى"],"reason":2},{"type":"tfr","q":"يُفرّق بين اسم المكان واسم الزمان واسم المفعول في غير الثلاثي (مثل مُلتقى ومُستخرَج) عن طريق السياق.","answer":true,"reasons":["لأن صياغتها واحدة: ميم مضمومة وفتح ما قبل الآخر","تختلف في الوزن تمامًا","لا يمكن التفريق بينها"],"reason":0},{"type":"tfr","q":"كلمة «مِنشار» و«مِفتاح» تبدآن بميم مفتوحة مثل اسم المكان.","answer":false,"reasons":["نعم بميم مفتوحة","بل تبدآن بميم مكسورة (مِـ) على وزن مِفْعال","بميم مضمومة"],"reason":1},{"type":"essay","q":"اشرح العلاقة بين اسم الأشعة بالإنجليزية (X-rays) واسمها بالعربية (الأشعة السينية).","model":"أطلق عليها رونتجن «X» وهو رمز المجهول في الرياضيات الإنجليزية لجهله بطبيعتها أولًا، وعند التعريب استُخدم رمز المجهول في الجبر العربي «س» فسمّيت «الأشعة السينية»."},{"type":"essay","q":"اذكر ثلاثة استخدامات طبية واستخدامين غير طبيين للأشعة السينية.","model":"طبية: ١) تصوير كسور العظام. ٢) فحص الأسنان. ٣) كشف الأجسام المعدنية المبتلعة. غير طبية: ١) فحص الحقائب في المطارات. ٢) كشف النقود المزيفة والشقوق في المعادن."},{"type":"essay","q":"كيف ساعدت «الملاحظة الدقيقة» رونتجن في اكتشاف الأشعة السينية رغم نسيانه؟","model":"حين رأى ظل المفتاح على اللوح الفوتوغرافي وتوهّج الشاشة في الظلام، لم يتجاهل الظاهرة بل تتبّع سببها بالتجارب المنظمة حتى كشف الأشعة."},{"type":"essay","q":"ما القيمة الأخلاقية التي نستخلصها من رفض رونتجن احتكار براءة اختراع الأشعة السينية؟","model":"أن العلم رسالة إنسانية سامية تهدف لخدمة البشرية وتخفيف آلام المرضى قبل السعي للمكاسب المادية."},{"type":"essay","q":"وضّح الجمال الفني في عنوان الدرس «نسّاء يكتشف أشعة لن ينساها التاريخ».","model":"جمع بين «نسّاء» (كثير النسيان) و«لن ينساها» في طباق لفظي ومعنوي طريف يشد انتباه القارئ ويلخّص مفارقة القصة."}]},
  {"id":"g9-arabic-2-u8","grade":"g9","subject":"arabic","term":2,"title":"الوحدة الثامنة: الأرض والقيم الأصيلة","levels":{"easy":[{"type":"mcq","q":"ما الفكرة المحورية التي يدور حولها نص «محبة الأرض»؟","options":["قيمة الأرض والارتباط بها وإعمارها بالعمل الصابر باعتبارها مصدر الحياة والانتماء","هجر القرى وإهمال الزراعة","التخلي عن العمل اليدوي","الاعتماد على الاستيراد وحده"],"answer":0,"why":"الأرض مصدر الرزق والأمن الغذائي والهوية الوطنية."},{"type":"mcq","q":"بمَ يُشبّه الأدباء الأرض في سياق عطائها المستمر للإنسان؟","options":["بالصخرة الصماء التي لا فائدة منها","بالأم الحنون المعطاءة التي تغذّي أبناءها وتحتضنهم","بالسحابة العابرة","بالآلة الجامدة"],"answer":1,"why":"تشبيه يبرز الحنان والعطاء والوفاء."},{"type":"mcq","q":"ما القيمتان اللتان تجسّدهما شخصية الفلاح المخلص في النص؟","options":["اليأس والشكوى","التسرّع والكسل","الصبر والأمل والعمل الشريف المتواصل","إهمال الوقت"],"answer":2,"why":"الزراعة مدرسة في الصبر والتوكل والإتقان."},{"type":"mcq","q":"ما الأهمية الإستراتيجية للزراعة والاهتمام بالأرض في العصر الحاضر؟","options":["إهدار المياه","إنقاص فرص العمل","زيادة التصحر","تحقيق الأمن الغذائي والاستقلال الاقتصادي وحماية البيئة"],"answer":3,"why":"الأمن الغذائي ركيزة أساسية لقوة أي دولة."}],"medium":[{"type":"mcq","q":"من أبرز شواهد محبة العُمانيين لأرضهم وإبداعهم الزراعي عبر التاريخ:","options":["نظام الأفلاج والمدرجات الجبلية وزراعة النخيل","تدمير الغابات","إهمال مصادر المياه","ترك الزراعة بالكامل"],"answer":0,"why":"الأفلاج والمدرجات شاهد عالمي على الإبداع الزراعي العُماني."},{"type":"mcq","q":"كيف يمكن توظيف التقنية الحديثة لخدمة محبة الأرض اليوم؟","options":["بهدم المزارع وبناء المصانع مكانها فقط","باستخدام الري بالتنقيط والبيوت المحمية والزراعة الذكية لترشيد الماء وزيادة الإنتاج","بالري العشوائي المسرف","بعدم استخدام العلم في الزراعة"],"answer":1,"why":"الزراعة الذكية تجمع الأصالة والمعاصرة."},{"type":"mcq","q":"ما العاطفة الغالبة على نص «محبة الأرض»؟","options":["السخرية","الحزن واليأس التام","الوفاء للأرض وتقدير العمل الشريف والانتماء للوطن","اللامبالاة"],"answer":2,"why":"النص يحتفي بالعمل والعطاء والانتماء."},{"type":"tfr","q":"محبة الأرض تقتصر على التغني بها بالكلمات دون عمل أو محافظة على البيئة.","answer":false,"reasons":["نعم تكفي الكلمات","لا تحتاج عملًا","بل تُثبت بالعمل والإعمار والتشجير وحماية التربة والماء"],"reason":2},{"type":"tfr","q":"الفرق بين «مُنتِج» و«مُنتَج» أن الأولى اسم فاعل والثانية اسم مفعول.","answer":true,"reasons":["بكسر ما قبل الآخر لاسم الفاعل وفتحه لاسم المفعول","كلاهما اسم فاعل","الأولى اسم آلة"],"reason":0}],"hard":[{"type":"mcq","q":"ما موقف النص من هجر الأرض الزراعية وإهمالها؟","options":["لا يتطرق إليه","يشجّع عليه","يراه دليل تقدم","يحذّر منه ويدعو للتمسّك بالأرض وإعمارها"],"answer":3,"why":"إهمال الأرض يُضعف الإنتاج ويقطع الصلة بالجذور."},{"type":"mcq","q":"كيف يعبّر طالب الصف التاسع عمليًا عن «محبة الأرض»؟","options":["بالمشاركة في التشجير وترشيد استهلاك الماء واحترام المزارعين","بقطف الأشجار وإتلاف الحدائق","بإهدار الماء","برمي النفايات في الأودية"],"answer":0,"why":"السلوك البيئي الواعي هو الترجمة العملية لمحبة الأرض."},{"type":"mcq","q":"قال النبي ﷺ: «ما من مسلم يغرس غرسًا أو يزرع زرعًا فيأكل منه طير أو إنسان أو بهيمة إلا كان له به صدقة»؛ يربط هذا الحديث الزراعة بـ:","options":["المشقة بلا فائدة","الأجر الدائم والصدقة الجارية ونفع الكائنات","الأمر الثانوي","تضييع الوقت"],"answer":1,"why":"الإسلام يشجّع على الغرس وإعمار الأرض ويجعله صدقة."},{"type":"essay","q":"اذكر ثلاث فوائد اقتصادية واجتماعية وبيئية للاهتمام بالأرض والزراعة.","model":"١) اقتصادية: تحقيق الأمن الغذائي وتوفير فرص العمل والدخل. ٢) اجتماعية: تعزيز الانتماء والاستقرار الأسري. ٣) بيئية: تنقية الهواء ومكافحة التصحر."},{"type":"essay","q":"كيف جسّد العُمانيون «محبة الأرض» في تراثهم الزراعي؟ اذكر مثالين.","model":"١) هندسة الأفلاج وتوزيع مياهها بعدل ودقة. ٢) بناء المدرجات الزراعية في الجبل الأخضر والاهتمام بزراعة النخيل واللبان."}]},"test":[{"type":"mcq","q":"ما الفكرة المحورية التي يدور حولها نص «محبة الأرض»؟","options":["قيمة الأرض والارتباط بها وإعمارها بالعمل الصابر باعتبارها مصدر الحياة والانتماء","هجر القرى وإهمال الزراعة","التخلي عن العمل اليدوي","الاعتماد على الاستيراد وحده"],"answer":0,"why":"الأرض مصدر الرزق والأمن الغذائي والهوية الوطنية."},{"type":"mcq","q":"بمَ يُشبّه الأدباء الأرض في سياق عطائها المستمر للإنسان؟","options":["بالصخرة الصماء التي لا فائدة منها","بالأم الحنون المعطاءة التي تغذّي أبناءها وتحتضنهم","بالسحابة العابرة","بالآلة الجامدة"],"answer":1,"why":"تشبيه يبرز الحنان والعطاء والوفاء."},{"type":"mcq","q":"ما القيمتان اللتان تجسّدهما شخصية الفلاح المخلص في النص؟","options":["اليأس والشكوى","التسرّع والكسل","الصبر والأمل والعمل الشريف المتواصل","إهمال الوقت"],"answer":2,"why":"الزراعة مدرسة في الصبر والتوكل والإتقان."},{"type":"mcq","q":"ما الأهمية الإستراتيجية للزراعة والاهتمام بالأرض في العصر الحاضر؟","options":["إهدار المياه","إنقاص فرص العمل","زيادة التصحر","تحقيق الأمن الغذائي والاستقلال الاقتصادي وحماية البيئة"],"answer":3,"why":"الأمن الغذائي ركيزة أساسية لقوة أي دولة."},{"type":"mcq","q":"من أبرز شواهد محبة العُمانيين لأرضهم وإبداعهم الزراعي عبر التاريخ:","options":["نظام الأفلاج والمدرجات الجبلية وزراعة النخيل","تدمير الغابات","إهمال مصادر المياه","ترك الزراعة بالكامل"],"answer":0,"why":"الأفلاج والمدرجات شاهد عالمي على الإبداع الزراعي العُماني."},{"type":"mcq","q":"كيف يمكن توظيف التقنية الحديثة لخدمة محبة الأرض اليوم؟","options":["بهدم المزارع وبناء المصانع مكانها فقط","باستخدام الري بالتنقيط والبيوت المحمية والزراعة الذكية لترشيد الماء وزيادة الإنتاج","بالري العشوائي المسرف","بعدم استخدام العلم في الزراعة"],"answer":1,"why":"الزراعة الذكية تجمع الأصالة والمعاصرة."},{"type":"mcq","q":"ما العاطفة الغالبة على نص «محبة الأرض»؟","options":["السخرية","الحزن واليأس التام","الوفاء للأرض وتقدير العمل الشريف والانتماء للوطن","اللامبالاة"],"answer":2,"why":"النص يحتفي بالعمل والعطاء والانتماء."},{"type":"mcq","q":"ما موقف النص من هجر الأرض الزراعية وإهمالها؟","options":["لا يتطرق إليه","يشجّع عليه","يراه دليل تقدم","يحذّر منه ويدعو للتمسّك بالأرض وإعمارها"],"answer":3,"why":"إهمال الأرض يُضعف الإنتاج ويقطع الصلة بالجذور."},{"type":"mcq","q":"كيف يعبّر طالب الصف التاسع عمليًا عن «محبة الأرض»؟","options":["بالمشاركة في التشجير وترشيد استهلاك الماء واحترام المزارعين","بقطف الأشجار وإتلاف الحدائق","بإهدار الماء","برمي النفايات في الأودية"],"answer":0,"why":"السلوك البيئي الواعي هو الترجمة العملية لمحبة الأرض."},{"type":"mcq","q":"قال النبي ﷺ: «ما من مسلم يغرس غرسًا أو يزرع زرعًا فيأكل منه طير أو إنسان أو بهيمة إلا كان له به صدقة»؛ يربط هذا الحديث الزراعة بـ:","options":["المشقة بلا فائدة","الأجر الدائم والصدقة الجارية ونفع الكائنات","الأمر الثانوي","تضييع الوقت"],"answer":1,"why":"الإسلام يشجّع على الغرس وإعمار الأرض ويجعله صدقة."},{"type":"mcq","q":"ما العلاقة بين «جهد الفلاح» و«عطاء الأرض» في النص؟","options":["لا علاقة بينهما","علاقة صراع وعداوة","علاقة تكامل ووفاء (فكلما أخلص الفلاح في خدمتها جادت عليه بالخير)","الأرض تعطي بلا أي جهد"],"answer":2,"why":"العطاء ثمرة الإخلاص والجدّ."},{"type":"mcq","q":"في جملة: «لا ساعيًا للخيرِ نادمٌ»، ما نوع اسم لا وإعرابه؟","options":["مفرد — مبني على الفتح","مبتدأ مرفوع","مضاف — منصوب","شبيه بالمضاف — معرب منصوب بالفتحة"],"answer":3,"why":"منوّن وبعده جار ومجرور يتمم معناه فهو شبيه بالمضاف."},{"type":"tf","q":"إعمار الأرض بالزراعة والعمل الشريف يسهم في تحقيق الأمن الغذائي للوطن.","answer":true,"why":"ويعزّز الاكتفاء الذاتي والاستقرار الاقتصادي"},{"type":"tf","q":"التطور التقني الحديث يتعارض تمامًا مع الاهتمام بالأرض والزراعة.","answer":false,"why":"بل التقنية الحديثة كالري بالتنقيط والزراعة الذكية تطوّر الزراعة وتزيد إنتاجها"},{"type":"tf","q":"يمثّل نظام الأفلاج العُماني شاهدًا حضاريًا على محبة العُمانيين لأرضهم وعدالتهم في توزيع الماء.","answer":true,"why":"وقد أُدرج عدد من الأفلاج العُمانية في قائمة التراث العالمي"},{"type":"tf","q":"العمل الزراعي يعلّم الإنسان الصبر والأمل والتوكل على الله.","answer":true,"why":"لأن المزارع يغرس البذرة ويرعاها بثقة وأمل حتى تثمر"},{"type":"tfr","q":"محبة الأرض تقتصر على التغني بها بالكلمات دون عمل أو محافظة على البيئة.","answer":false,"reasons":["نعم تكفي الكلمات","لا تحتاج عملًا","بل تُثبت بالعمل والإعمار والتشجير وحماية التربة والماء"],"reason":2},{"type":"tfr","q":"الفرق بين «مُنتِج» و«مُنتَج» أن الأولى اسم فاعل والثانية اسم مفعول.","answer":true,"reasons":["بكسر ما قبل الآخر لاسم الفاعل وفتحه لاسم المفعول","كلاهما اسم فاعل","الأولى اسم آلة"],"reason":0},{"type":"tfr","q":"في جملة «أشرقَتِ الشمسُ» تأنيث الفعل واجب.","answer":false,"reasons":["بل واجب التذكير","بل جائز لأن الفاعل ظاهر مؤنث مجازي (أشرقَ/أشرقتِ الشمسُ)","نعم واجب"],"reason":1},{"type":"tfr","q":"اسم لا النافية للجنس في «لا مجتهدِينَ فاشلون» مبني على الياء في محل نصب.","answer":true,"reasons":["منصوب بالفتحة","مرفوع بالواو","لأنه مفرد (غير مضاف ولا شبيه بالمضاف) فيُبنى على ما يُنصب به"],"reason":2},{"type":"essay","q":"اذكر ثلاث فوائد اقتصادية واجتماعية وبيئية للاهتمام بالأرض والزراعة.","model":"١) اقتصادية: تحقيق الأمن الغذائي وتوفير فرص العمل والدخل. ٢) اجتماعية: تعزيز الانتماء والاستقرار الأسري. ٣) بيئية: تنقية الهواء ومكافحة التصحر."},{"type":"essay","q":"كيف جسّد العُمانيون «محبة الأرض» في تراثهم الزراعي؟ اذكر مثالين.","model":"١) هندسة الأفلاج وتوزيع مياهها بعدل ودقة. ٢) بناء المدرجات الزراعية في الجبل الأخضر والاهتمام بزراعة النخيل واللبان."},{"type":"essay","q":"اشرح جمال التشبيه حين يوصف ارتباط الإنسان بأرضه كعلاقة «الابن بأمه».","model":"لأن الأم تحتضن أبناءها وتغذيهم وتمنحهم الأمان، والأرض كذلك تحتضن الإنسان وتطعمه من خيراتها وتستحق منه البرّ والوفاء والحماية."},{"type":"essay","q":"اقترح طريقتين لتوظيف التقنية الحديثة في مزارع سلطنة عُمان.","model":"١) أنظمة الري الذكي بالتنقيط لتوفير المياه. ٢) البيوت المحمية المبرّدة والزراعة المائية للإنتاج طوال العام."},{"type":"essay","q":"ما واجبك تجاه المزارع والبيئة الزراعية في مجتمعك؟","model":"تقدير جهده واحترام مهنته الشريفة، وشراء المنتجات العُمانية المحلية لدعمه، والحفاظ على الماء والأشجار ونظافة المزارع والأفلاج."}]}
);
